INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000015', 'e1000001-0000-4000-8000-000000000005', 'Esai Beasiswa Internasional (LPDP, Fulbright & Statement of Purpose)', 'Rangkai narasi Statement of Purpose berstandar Ivy League, Fulbright, dan LPDP yang menyatukan rekam jejak riset, kesenjangan keilmuan, dan dampak nasional.', 'curriculum', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000016', 'e1000001-0000-4000-8000-000000000005', 'Sintesis Riset: Membandingkan Teori Kuliah vs Teks Bacaan', 'Kuasai sintesis akademik bernuansa tinggi ketika kuliah tidak sekadar membantah total, melainkan mengualifikasi, mendamaikan konflik data, atau mempertajam teori bacaan.', 'curriculum', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000017', 'e1000001-0000-4000-8000-000000000005', 'Presentasi Eksekutif, Q&A Kritis & Krisis Komunikasi', 'Kendalikan sesi tanya-jawab direksi yang tajam, tangani komunikasi insiden krisis secara transparan, dan kuasai penekanan verbal eksekutif.', 'curriculum', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000018', 'e1000001-0000-4000-8000-000000000005', 'Nominalisasi & Kepadatan Informasi Akademik', 'Ubah rangkaian anak kalimat lisan yang cair menjadi frasa nomina padat berstandar jurnal akademik, laporan ekonomi, dan TOEFL Reading/Writing 110+.', 'curriculum', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000019', 'e1000001-0000-4000-8000-000000000005', 'Diplomasi Lintas Budaya & Umpan Balik Manajerial Halus', 'Navigasikan perbedaan komunikasi konteks-tinggi Asia dan konteks-rendah Amerika menggunakan litotes, tactical softening, dan upward management.', 'curriculum', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000020', 'e1000001-0000-4000-8000-000000000005', 'Fronting & Paralelisme: Arsitektur Kalimat TOEFL & Policy Brief', 'Kuasai pengedepanan predikat (fronting) untuk transisi antarkalimat yang mulus serta keseimbangan paralelisme mutlak pada esai TOEFL 105+ dan ringkasan kebijakan.', 'curriculum', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000021', 'e1000001-0000-4000-8000-000000000005', 'Elipsis & Substitusi: Kohesi Tanpa Pengulangan untuk Esai & RFC', 'Hapus pengulangan kata kerja dan klausa yang kaku menggunakan substitusi ''do so'', ''if so / if not'', ''the former / the latter'', serta elipsis kata bantu tingkat C1.', 'curriculum', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000022', 'e1000001-0000-4000-8000-000000000005', 'Ujian Kesiapan CEFR C1 & TOEFL iBT 95–114', 'Evaluasi komprehensif lintas empat pilar (Reading, Listening, Writing, Speaking) yang menguji kemahiran bahasa Inggris akademik, beasiswa internasional, dan kepemimpinan global C1.', 'diagnostic_exam', 99, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000023', 'e1000001-0000-4000-8000-000000000006', 'Pengandaian Terbalik Tanpa ''If'' (Should, Were & Had)', 'Kuasai inversi pengandaian tingkat eksekutif, hukum, dan TOEFL 115–120 dengan menanggalkan kata ''if'' pada skenario kontingensi, hipotesis jauh, serta kontrafaktual lampau.', 'curriculum', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000024', 'e1000001-0000-4000-8000-000000000006', 'Struktur ''Be + To-Infinitive'': Mandat Resmi, Protokol & Takdir Sejarah', 'Kuasai konstruksi ringkas namun sarat otoritas (''are to comply'', ''if we are to succeed'', ''was never to return'') dalam regulasi, diplomasi, dan narasi sejarah TOEFL.', 'curriculum', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000025', 'e1000001-0000-4000-8000-000000000006', 'Konstruksi Absolut: Klausa Lepas Berkelas dalam Prosa Ilmiah & Editorial', 'Padatkan hubungan sebab-akibat dan rincian latar menggunakan konstruksi absolut bersubjek mandiri (''The audit completed, ...'', ''Other things being equal, ...'') khas majalah The Economist dan jurnal ilmiah.', 'curriculum', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000026', 'e1000001-0000-4000-8000-000000000006', 'Inversi Konsesif Emfatik: ''Much as...'', ''Try as...'' & ''Brilliant though...''', 'Bentuk konsesi bernilai sastra dan retoris tertinggi dengan mengedepankan kata sifat, kata kerja dasar, atau ''Much as'' untuk mengkritik secara elegan pada esai TOEFL 120 dan tinjauan ilmiah.', 'curriculum', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000027', 'e1000001-0000-4000-8000-000000000006', 'Distancing & Evidentiality: Kritik Riset Objektif & Presisi Bukti', 'Jaga jarak intelektual dan hukum dari klaim yang belum teruji menggunakan verba skeptisisme halus (''purports to'', ''ostensibly'') serta pasif pelaporan perfek (''is alleged to have V3'').', 'curriculum', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000028', 'e1000001-0000-4000-8000-000000000006', 'Formulaic Subjunctive: Ungkapan Klasik Eksekutif, Hukum & Pidato', 'Gunakan fosil struktur subjunctive klasik (''Be that as it may'', ''Suffice it to say'', ''Be it... or...'', ''Far be it from me'') secara tepat konteks dalam pidato eksekutif dan esai C2.', 'curriculum', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000029', 'e1000001-0000-4000-8000-000000000006', 'Aposisi & Resumptive Modifiers: Ekspansi Kalimat Gaya The Economist', 'Bangun kalimat panjang yang jernih tanpa kesalahan '', which'' kabur menggunakan aposisi pembuka, *summative modifiers* (''—a flaw that...''), dan *resumptive modifiers*.', 'curriculum', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000030', 'e1000001-0000-4000-8000-000000000006', 'Nuanced Discourse Framing: ''Insofar as'', ''Notwithstanding'' & ''Vis-à-vis''', 'Batasi ruang lingkup klaim hukum, ekonomi, dan filsafat sains dengan presisi bedah menggunakan penghubung tingkat C2 (''insofar as'', ''notwithstanding'', ''by the same token'').', 'curriculum', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000031', 'e1000001-0000-4000-8000-000000000006', 'Three-Word Phrasal-Prepositional Verbs: Idiom Kepemimpinan AS', 'Kuasai idiom kerja tiga kata tak terpisahkan (''come down to'', ''live up to'', ''do away with'', ''zero in on'') yang mendominasi rapat eksekutif Amerika dan TOEFL Listening.', 'curriculum', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e5000001-0000-4000-8000-000000000032', 'e1000001-0000-4000-8000-000000000006', 'Rhetorical Antithesis & Cadence: Ritme Keynote & Esai TOEFL 120', 'Puncaki penguasaan bahasa Inggris C2 Anda dengan kontras antitesis simetris (''less about X than about Y'', ''not by..., but by...'') serta irama tiga serangkai (*tricolon*) kelas pidato kunci dunia.', 'curriculum', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
