INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000001', 'e5100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih phrasal verb yang tepat untuk konteks penyelesaian kendala kontrak:', '{"options":["brush aside","iron out","fall behind","call off"],"translation":"Sebelum menandatangani perjanjian vendor, kedua tim hukum bertemu untuk membereskan sisa kendala lisensi.","sentence_template":"Before signing the vendor agreement, both legal teams met to [blank] the remaining licensing issues."}'::jsonb, '{"selected":"iron out"}'::jsonb, NULL, NULL, '''Iron out'' bermakna menyelesaikan rincian masalah yang tersisa hingga tuntas sebelum kesepakatan disahkan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000002', 'e5100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Lengkapi kolokasi kepemimpinan proyek global berikut:', '{"options":["backfire","undergo","spearhead","withhold"],"translation":"Direktur regional meminta Maya memelopori inisiatif migrasi cloud kami di seluruh Asia Tenggara.","sentence_template":"The regional director asked Maya to [blank] our cloud migration initiative across Southeast Asia."}'::jsonb, '{"selected":"spearhead"}'::jsonb, NULL, NULL, '''Spearhead an initiative'' adalah kolokasi profesional Amerika untuk memimpin langsung proyek baru yang strategis.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000003', 'e5100001-0000-4000-8000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan pembaruan manajer proyek. Apa yang terjadi pada jadwal peluncuran?', '{"options":[{"id":"opt_1","text":"Proyek pembayaran dibatalkan sepenuhnya oleh tim audit"},{"id":"opt_2","text":"Jadwal peluncuran diundur selama dua minggu karena audit gerbang pembayaran memakan waktu lebih lama"},{"id":"opt_3","text":"Peluncuran dimajukan dua minggu lebih awal dari rencana semula"},{"id":"opt_4","text":"Tim teknik menolak menjalani proses audit keamanan"}],"audio_text":"Because the payment gateway audit took longer than expected, we decided to push back the launch by two weeks."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Push back the launch by two weeks'' berarti mengundur waktu peluncuran ke dua minggu lebih lambat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000004', 'e5100001-0000-4000-8000-000000000001', NULL, 'writing', 'sentence_builder', 'Susun kalimat profesional tentang penuntasan komitmen kuartalan:', '{"romaji":"/ˈɛvri skwɑːd mʌst ˈfɑːloʊ θruː ɑːn ðə rɪˌlaɪəˈbɪləti ˈtɑːrɡɪts/","tokens":["promising at","promised to enterprise clients.","follow on through","the reliability targets","Every squad must","follow through on"],"target_translation":"Setiap tim wajib menuntaskan target keandalan yang dijanjikan kepada klien korporat."}'::jsonb, '["Every squad must","follow through on","the reliability targets","promised to enterprise clients."]'::jsonb, NULL, NULL, 'Phrasal verb tiga kata ''follow through on'' bersifat tak terpisahkan dan langsung diikuti objek targetnya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000005', 'e5100001-0000-4000-8000-000000000001', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan ucapkan kalimat koordinasi tim berikut dengan intonasi Amerika alami:', '{"romaji":"/lɛts ˈaɪərn aʊt ðiːz dɪˈplɔɪmənt ˈɡlɪtʃɪz bɪˈfɔːr ˈmʌndeɪ ˈmɔːrnɪŋ/","display_text":"Let''s iron out these deployment glitches before Monday morning.","phonetic_breakdown":["Let''s iron out","these deployment glitches","before Monday morning."]}'::jsonb, '{"expected_transcript":"Let''s iron out these deployment glitches before Monday morning."}'::jsonb, NULL, NULL, 'Tautkan bunyi konsonan akhir ''iron_out'' secara mulus dan tekankan suku kata kedua pada ''de-PLOY-ment''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000006', 'e5100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih kolokasi bisnis yang tepat untuk menyatakan peningkatan skala operasional:', '{"options":["scale up","opt out","wind down","water down"],"translation":"Begitu program percontohan terbukti menguntungkan di Jakarta, kantor pusat menyetujui pendanaan untuk memperbesar skala operasional secara nasional.","sentence_template":"Once the pilot program proved profitable in Jakarta, headquarters approved funding to [blank] operations nationwide."}'::jsonb, '{"selected":"scale up"}'::jsonb, NULL, NULL, '''Scale up operations'' adalah istilah baku bisnis/teknologi untuk memperluas kapasitas secara terukur.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000007', 'e5100001-0000-4000-8000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan pesan rekan kerja di Slack. Apa yang ia tanyakan kepada tim?', '{"options":[{"id":"opt_1","text":"Mengumumkan pembekuan seluruh rekrutmen hingga akhir tahun"},{"id":"opt_2","text":"Membatalkan rapat anggaran karena data kuartal ketiga belum siap"},{"id":"opt_3","text":"Mengajak berdiskusi singkat sepuluh menit setelah makan siang guna menyamakan pandangan soal anggaran rekrutmen Q3"},{"id":"opt_4","text":"Meminta tim memotong anggaran makan siang pada kuartal ketiga"}],"audio_text":"Hey team, can we touch base for ten minutes after lunch to align on the Q3 hiring budget?"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Touch base'' berarti menghubungi atau berkoordinasi singkat untuk menyelaraskan informasi terbaru.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000008', 'e5100001-0000-4000-8000-000000000001', NULL, 'writing', 'sentence_builder', 'Susun kalimat tanggapan kerja menggunakan kolokasi profesional:', '{"romaji":"/ˈaʊər ˌɛndʒəˈnɪrɪŋ liːd ˈspɪrˌhɛdɪd ði ˈɛfərt tə ˈstriːmˌlaɪn/","tokens":["streamlined into","spearheading for","to streamline","cross-border onboarding.","Our engineering lead","spearheaded the effort"],"target_translation":"Pemimpin rekayasa kami memelopori upaya untuk menyederhanakan proses orientasi lintas negara."}'::jsonb, '["Our engineering lead","spearheaded the effort","to streamline","cross-border onboarding."]'::jsonb, NULL, NULL, '''Spearhead the effort to + V1'' merupakan struktur ringkas dan kuat untuk menggambarkan kepemimpinan aktif.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000009', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Pilih susunan kata ganti objek yang gramatikal untuk kalimat bisnis berikut:', '{"options":["phase them out","them phase out","phase out them","phasing out them"],"translation":"API lawas tersebut memakan terlalu banyak memori, sehingga arsitek kami berencana menghentikannya secara bertahap sebelum Desember.","sentence_template":"Those legacy APIs consume too much memory, so our architects plan to [blank] by December."}'::jsonb, '{"selected":"phase them out"}'::jsonb, NULL, NULL, '''Phase out'' adalah separable phrasal verb; saat objeknya berupa kata ganti ''them'', posisinya wajib berada di antara kata kerja dan partikel.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000010', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Pilih bentuk multi-word verb tak terpisahkan yang tepat:', '{"options":["into it looked","looked into them drop","looked it into","looked into it"],"translation":"Ketika dasbor analitik menunjukkan penurunan retensi mendadak, ilmuwan data kami segera menyelidikinya.","sentence_template":"When the analytics dashboard showed a sudden drop in retention, our data scientist immediately [blank]."}'::jsonb, '{"selected":"looked into it"}'::jsonb, NULL, NULL, '''Look into'' (menyelidiki) adalah prepositional verb yang tidak dapat dipisahkan oleh kata ganti ''it''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000011', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'listening', 'listening_choice', 'Dengarkan percakapan dua manajer. Mengapa pembicara menolak tawaran vendor tersebut?', '{"options":[{"id":"opt_1","text":"Vendor membatalkan penawaran sebelum tim sempat meninjau harga"},{"id":"opt_2","text":"Mereka menerima tawaran tersebut setelah memangkas biaya tahunan"},{"id":"opt_3","text":"Perangkat lunaknya tidak memiliki fitur yang dijanjikan di atas kertas"},{"id":"opt_4","text":"Biaya pemeliharaan tahunannya terlalu mahal sehingga tawaran tersebut harus ditolak"}],"audio_text":"Their software suite looked impressive on paper, but the annual maintenance fee was exorbitant, so we had to turn it down."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Exorbitant'' berarti sangat mahal melampaui batas wajar, sehingga ''we had to turn it down'' (kami terpaksa menolaknya).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000012', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat analisis rapat menggunakan phrasal verb tiga kata:', '{"romaji":"/ˈdʊrɪŋ ðə ˌrɛtrəˈspɛktɪv ˈaʊər tiːm ˈzɪroʊd ɪn ɑːn ðə ruːt kɔːz/","tokens":["the checkout latency.","During the retrospective,","zeroed on in","in zeroed them","our team zeroed in on","the root cause of"],"target_translation":"Selama sesi retrospektif, tim kami memusatkan perhatian pada akar penyebab kelambatan proses pembayaran."}'::jsonb, '["During the retrospective,","our team zeroed in on","the root cause of","the checkout latency."]'::jsonb, NULL, NULL, '''Zero in on'' tetap utuh sebagai satu kesatuan sebelum objek ''the root cause''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000013', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'speaking', 'speaking_repeat', 'Tirukan pengucapan kalimat berikut dengan reduksi bunyi ''it'' yang alami:', '{"romaji":"/ðə ˈklaɪənt reɪzd ə ˈvælɪd kənˈsɜːrn soʊ aɪ brɔːt ɪt ʌp æt ˈstændʌp/","display_text":"The client raised a valid concern, so I brought it up at standup.","phonetic_breakdown":["The client raised","a valid concern,","so I brought it up","at standup."]}'::jsonb, '{"expected_transcript":"The client raised a valid concern, so I brought it up at standup."}'::jsonb, NULL, NULL, 'Pada American English, ''brought it up'' dilafalkan menyambung dengan flap /ɾ/ ringan: [brɔːɾɪɾʌp].', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000014', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi anggaran dengan phrasal verb tiga kata yang tepat:', '{"options":["back cut on","cut on back","cut back on","cut it back on"],"translation":"Demi menjaga keberlanjutan hibah riset, laboratorium harus memangkas biaya perjalanan yang tidak esensial.","sentence_template":"To keep the research grant sustainable, the laboratory had to [blank] non-essential travel expenses."}'::jsonb, '{"selected":"cut back on"}'::jsonb, NULL, NULL, '''Cut back on + noun'' bermakna mengurangi pengeluaran atau konsumsi secara terencana.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000015', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'listening', 'listening_choice', 'Dengarkan arahan direktur operasional. Apa langkah terhadap prosedur pelaporan manual?', '{"options":[{"id":"opt_1","text":"Seluruh staf diwajibkan mengisi lebih banyak spreadsheet manual kuartal depan"},{"id":"opt_2","text":"Pipeline otomatis dihapus karena sering memicu kesalahan manusia"},{"id":"opt_3","text":"Pelaporan spreadsheet manual akan dihentikan bertahap dan digantikan pipeline otomatis kuartal depan"},{"id":"opt_4","text":"Pelaporan kuartal depan ditunda sampai tim baru direkrut"}],"audio_text":"Manual spreadsheet reporting is prone to human error, so we''re phasing it out in favor of automated pipelines next quarter."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Phasing it out in favor of X'' berarti menghentikan penggunaan sesuatu secara bertahap untuk beralih ke X.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000016', 'e5100001-0000-4000-8000-000000000002', 'e2000001-0000-4000-8000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat profesional dengan penempatan pronomina objek yang benar:', '{"romaji":"/ˈsɛvrəl ɛdʒ ˈkeɪsɪz ɪˈmɜːrdʒd soʊ ðə ˌkjuːˈeɪ ˌɛndʒəˈnɪr roʊt ðɛm daʊn/","tokens":["for regression testing.","writing it down","wrote them down","so the QA engineer","wrote down them","Several edge cases emerged,"],"target_translation":"Beberapa kasus batas muncul, sehingga insinyur QA mencatatnya untuk pengujian regresi."}'::jsonb, '["Several edge cases emerged,","so the QA engineer","wrote them down","for regression testing."]'::jsonb, NULL, NULL, 'Karena merujuk pada jamak ''several edge cases'', gunakan ''wrote them down'' (bukan ''wrote down them'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000017', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Lengkapi kalimat diskusi riset kampus berikut:', '{"options":["hand over","rule out","touch base","pan out"],"translation":"Sampai hasil penanggalan karbon tiba, para arkeolog belum dapat sepenuhnya mengesampingkan kemungkinan adanya permukiman yang lebih tua.","sentence_template":"Until the carbon-dating results arrive, archaeologists cannot completely [blank] the possibility of an earlier settlement."}'::jsonb, '{"selected":"rule out"}'::jsonb, NULL, NULL, '''Rule out the possibility'' berarti mencoret atau mengeliminasi suatu kemungkinan berdasarkan bukti.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000018', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Pilih ungkapan yang tepat untuk perencanaan anggaran proyek:', '{"options":["stepped down","factored in","turned down","zeroed out"],"translation":"Linimasa Anda tampak terlalu optimistis karena Anda belum memperhitungkan keterlambatan bea cukai di pelabuhan.","sentence_template":"Your timeline looks optimistic because you haven''t [blank] customs clearance delays at the port."}'::jsonb, '{"selected":"factored in"}'::jsonb, NULL, NULL, '''Factor in'' digunakan ketika memasukkan faktor penting ke dalam perhitungan biaya atau waktu.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000019', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'listening', 'listening_choice', 'Dengarkan percakapan mahasiswa dengan pembimbing riset (gaya TOEFL Campus Conversation). Apa maksud perkataan dosen?', '{"options":[{"id":"opt_1","text":"Mahasiswa dilarang mengganti topik riset setelah ujian tengah semester"},{"id":"opt_2","text":"Mahasiswa perlu menyiapkan kumpulan data cadangan jika sumber arsip utama tidak membuahkan hasil yang diharapkan"},{"id":"opt_3","text":"Sumber arsip utama sudah terbukti berhasil dan siap dipublikasikan"},{"id":"opt_4","text":"Dosen meminta mahasiswa menghapus kumpulan data sekunder dari laporan"}],"audio_text":"If your primary archive source doesn''t pan out, make sure you have a secondary dataset ready before midterms."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Doesn''t pan out'' dalam konteks riset berarti tidak berhasil atau tidak memberikan data memadai.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000020', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat pembuka rapat lintas negara berikut:', '{"romaji":"/bɪˈfɔːr wi daɪv ˈɪntuː ðə sprɪnt ˈmɛtrɪks lɛts ɡɛt ˈɛvriˌwʌn ɑːn ðə seɪm peɪdʒ/","tokens":["let''s get everyone","diving onto","Before we dive into","on the same page.","the sprint metrics,","in the same page"],"target_translation":"Sebelum kita membahas mendalam metrik sprint, mari samakan pemahaman semua anggota tim."}'::jsonb, '["Before we dive into","the sprint metrics,","let''s get everyone","on the same page."]'::jsonb, NULL, NULL, 'Idiom yang benar selalu memakai preposisi ''on'': ''on the same page'', bukan ''in the same page''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000021', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'speaking', 'speaking_repeat', 'Ucapkan respons diskusi akademik berikut secara jelas dan terstruktur:', '{"romaji":"/wi ˈkænɑːt ruːl aʊt əbˈzɜːrvər ˈbaɪəs wɪˈðaʊt ˈrʌnɪŋ ə blaɪnd ˈtraɪəl/","display_text":"We cannot rule out observer bias without running a blind trial.","phonetic_breakdown":["We cannot rule out","observer bias","without running","a blind trial."]}'::jsonb, '{"expected_transcript":"We cannot rule out observer bias without running a blind trial."}'::jsonb, NULL, NULL, 'Berikan penekanan jelas pada kata kunci kontras ilmiah: ''rule OUT'', ''ob-SER-ver BI-as'', dan ''BLIND TRI-al''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000022', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Pilih idiom rapat yang tepat untuk menanggapi rencana cadangan:', '{"options":["pan out","brush up","iron out","phase in"],"translation":"Kami berharap kemitraan di Boston segera menghasilkan prospek, namun ketika tidak berjalan sesuai harapan, kami beralih ke penjualan korporat.","sentence_template":"We hoped the partnership in Boston would generate immediate leads, but when it didn''t [blank], we pivoted to enterprise sales."}'::jsonb, '{"selected":"pan out"}'::jsonb, NULL, NULL, '''Pan out'' bersifat intransitif (tanpa objek langsung) dan berarti berhasil sesuai ekspektasi.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000023', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah ekonomi. Apa kelemahan studi awal menurut sang profesor?', '{"options":[{"id":"opt_1","text":"Studi awal terlalu berfokus pada transportasi kereta bawah tanah"},{"id":"opt_2","text":"Data kepadatan lalu lintas dikumpulkan menggunakan sensor otomatis modern"},{"id":"opt_3","text":"Perencana kota membangun terlalu sedikit jalur jalan tol di pinggiran kota"},{"id":"opt_4","text":"Perencana kota gagal memperhitungkan lonjakan permintaan baru yang muncul akibat penambahan jalur jalan tol"}],"audio_text":"Early urban mobility models failed precisely because planners didn''t factor in induced demand whenever new highway lanes were added."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Didn''t factor in induced demand'' memparafrasakan kegagalan memperhitungkan variabel permintaan terinduksi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000024', 'e5100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat kesimpulan evaluasi eksperimen berikut:', '{"romaji":"/wʌns wi ˈfæktərd ɪn ˈsiːzənəl ˈtɛmprətʃər ʃɪfts ði əˈnæməli ˌdɪsəˈpɪrd/","tokens":["disappearing at","Once we factored in","the anomaly disappeared","from our dataset.","factoring on","seasonal temperature shifts,"],"target_translation":"Begitu kami memperhitungkan perubahan suhu musiman, anomali tersebut hilang dari kumpulan data kami."}'::jsonb, '["Once we factored in","seasonal temperature shifts,","the anomaly disappeared","from our dataset."]'::jsonb, NULL, NULL, 'Klausa waktu ''Once we factored in + Noun Phrase'' diikuti klausa utama lampau secara koheren.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000025', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Pilih penempatan kata ganti yang tepat:', '{"options":["ironing out them","iron them out","iron out them","them iron out"],"translation":"Draf kontrak memuat dua klausul ambigu, sehingga penasihat hukum kami meminta pihak lawan membereskannya sebelum Jumat.","sentence_template":"The draft contract contained two ambiguous clauses, so our counsel asked the counterparty to [blank] before Friday."}'::jsonb, '{"selected":"iron them out"}'::jsonb, NULL, NULL, 'Pronomina jamak ''them'' wajib diletakkan di tengah separable phrasal verb ''iron ... out''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000026', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Pilih phrasal verb tiga kata yang tepat:', '{"options":["follow through on","turn down to","move up from","pan out of"],"translation":"Pemimpin tangguh tidak sekadar mengumumkan OKR ambisius; mereka menuntaskan dukungan operasional yang dibutuhkan tim.","sentence_template":"Strong leaders don''t just announce ambitious OKRs; they [blank] the operational support their teams need."}'::jsonb, '{"selected":"follow through on"}'::jsonb, NULL, NULL, '''Follow through on'' menegaskan konsistensi menindaklanjuti komitmen sampai tuntas.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000027', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'listening', 'listening_choice', 'Evaluasi Unit 1 — Dengarkan pembaruan VP Engineering. Apa keputusan rapat tersebut?', '{"options":[{"id":"opt_1","text":"Tim keamanan mengesampingkan laporan kebocoran token karena dianggap sepele"},{"id":"opt_2","text":"Proyek beta publik dihentikan permanen tanpa perbaikan lebih lanjut"},{"id":"opt_3","text":"Rilis beta publik diundur sampai tim berhasil menambal celah kebocoran token keamanan"},{"id":"opt_4","text":"Rilis beta publik dipercepat agar pengguna dapat menguji fitur keamanan"}],"audio_text":"Since security testing uncovered a token leak, we''re pushing back the public beta until our team patches it."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Pushing back the public beta until...'' berarti menunda jadwal rilis hingga perbaikan selesai.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000028', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'writing', 'sentence_builder', 'Evaluasi Unit 1 — Susun kalimat analisis riset dengan tepat:', '{"romaji":"/ðə kənˈtroʊl ɡruːp rɪˈzʌlts əˈlaʊd ˈriːsɜːrtʃərz tə ruːl aʊt pləˈsiːboʊ ɪˈfɛkts/","tokens":["rule out placebo effects","rule placebo out it","The control group results","ruling into","allowed researchers to","with high confidence."],"target_translation":"Hasil kelompok kontrol memungkinkan peneliti mengesampingkan efek plasebo dengan tingkat keyakinan tinggi."}'::jsonb, '["The control group results","allowed researchers to","rule out placebo effects","with high confidence."]'::jsonb, NULL, NULL, 'Objek frasa nomina penuh (''placebo effects'') lazim diletakkan sesudah ''rule out''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000029', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'speaking', 'speaking_repeat', 'Evaluasi Unit 1 — Ucapkan kalimat kepemimpinan proyek berikut dengan lancar:', '{"romaji":"/ʃi ˈspɪrˌhɛdɪd ˈaʊər ɪkˈspænʃən ænd ɡɑːt ˈɛvri ˈsteɪkˌhoʊldər ɑːn ðə seɪm peɪdʒ/","display_text":"She spearheaded our expansion and got every stakeholder on the same page.","phonetic_breakdown":["She spearheaded","our expansion","and got every stakeholder","on the same page."]}'::jsonb, '{"expected_transcript":"She spearheaded our expansion and got every stakeholder on the same page."}'::jsonb, NULL, NULL, 'Jaga ritme alami frasa ''got every stakeholder'' dan akhiri dengan penekanan pada ''SAME PAGE''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000030', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Lengkapi kalimat tentang penyelidikan insiden:', '{"options":["panning it out","looking it into","spearheading into","looking into it"],"translation":"Pelanggan melaporkan waktu habis berkala di Singapura, dan tim keandalan situs kami sedang aktif menyelidikinya.","sentence_template":"Customers reported intermittent timeouts in Singapore, and our site reliability team is actively [blank]."}'::jsonb, '{"selected":"looking into it"}'::jsonb, NULL, NULL, '''Look into'' adalah prepositional verb tak terpisahkan sehingga ''it'' harus berada sesudah ''into''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000031', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'listening', 'listening_choice', 'Evaluasi Unit 1 — Dengarkan diskusi evaluasi bisnis. Mengapa ekspansi produk ditinjau ulang?', '{"options":[{"id":"opt_1","text":"Biaya cloud turun drastis sehingga model freemium sangat menguntungkan"},{"id":"opt_2","text":"Tim lupa meluncurkan fitur freemium kepada pengguna aktif"},{"id":"opt_3","text":"Investor menolak membiayai riset pengguna baru tahun ini"},{"id":"opt_4","text":"Eksperimen freemium kurang berhasil setelah biaya komputasi cloud per pengguna aktif ikut diperhitungkan"}],"audio_text":"Our freemium experiment didn''t quite pan out once we factored in cloud inference costs per active user."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Menggabungkan dua idiom inti Unit 1: ''didn''t pan out'' (tidak membuahkan hasil) dan ''factored in'' (memperhitungkan).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000032', 'e5100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000031', 'writing', 'sentence_builder', 'Evaluasi Unit 1 — Susun kalimat transisi sistem berikut:', '{"romaji":"/bɪˈkɔːz ði oʊld ˌɛsdiːˈkeɪ læks ɪnˈkrɪpʃən wi wɪl feɪz ɪt aʊt/","tokens":["Because the old SDK","we will phase it out","phase out it","over two quarters.","phased into them","lacks encryption,"],"target_translation":"Karena SDK lama tidak memiliki enkripsi, kami akan menghentikannya secara bertahap selama dua kuartal."}'::jsonb, '["Because the old SDK","lacks encryption,","we will phase it out","over two quarters."]'::jsonb, NULL, NULL, 'Kata ganti tunggal ''it'' (merujuk ''the old SDK'') ditempatkan di antara ''phase'' dan ''out''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000033', 'e5100001-0000-4000-8000-000000000005', NULL, 'reading', 'fill_blank', 'Pilih kata kerja berdampak tinggi untuk bagian Action pada wawancara STAR:', '{"options":["overhauled","stagnated","complied","hesitated"],"translation":"Ketika volume tiket pelanggan berlipat ganda, saya merombak total alur triase kami dan memperkenalkan perutean otomatis.","sentence_template":"When customer ticket volume doubled, I [blank] our triage workflow and introduced automated routing."}'::jsonb, '{"selected":"overhauled"}'::jsonb, NULL, NULL, '''Overhauled'' menunjukkan tindakan proaktif merombak sistem yang tidak efisien secara menyeluruh.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000034', 'e5100001-0000-4000-8000-000000000005', NULL, 'reading', 'fill_blank', 'Pilih preposisi kuantifikasi metrik yang tepat untuk bagian Result:', '{"options":["into","since","by","until"],"translation":"Dalam dua bulan sejak meluncurkan lapisan caching, tim kami memangkas rata-rata waktu respons API sebesar 55 persen.","sentence_template":"Within two months of launching caching layers, our team reduced average API response time [blank] 55 percent."}'::jsonb, '{"selected":"by"}'::jsonb, NULL, NULL, 'Gunakan ''by + persentase'' untuk menyatakan besaran selisih pengurangan atau peningkatan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000035', 'e5100001-0000-4000-8000-000000000005', NULL, 'listening', 'listening_choice', 'Dengarkan jawaban wawancara kandidat. Bagian STAR manakah yang sedang ditekankan kandidat?', '{"options":[{"id":"opt_1","text":"Keluhan pribadi kandidat terhadap kurangnya staf operasional"},{"id":"opt_2","text":"Pertanyaan balik kandidat mengenai gaji dan tunjangan lembur"},{"id":"opt_3","text":"Bagian Situation awal sebelum kandidat bergabung ke perusahaan"},{"id":"opt_4","text":"Bagian Result (Hasil) yang menyajikan dampak terukur berupa penghematan waktu dan jam kerja"}],"audio_text":"As a result, onboarding time dropped from fourteen days to just three days, saving the operations team roughly two hundred hours per quarter."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Penanda ''As a result'' diikuti angka konkret (''from fourteen days to three days'', ''saving 200 hours'') adalah ciri khas tahap Result yang kuat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000036', 'e5100001-0000-4000-8000-000000000005', NULL, 'writing', 'sentence_builder', 'Susun kalimat Situation & Task pembuka wawancara behavioral berikut:', '{"romaji":"/ˈmænjuəl ˈɪnvɔɪs əˈpruːvəl hæd bɪˈkʌm ə ˈmeɪdʒər ˈbɑːtəlˌnɛk/","tokens":["for regionally","finance team.","Manual invoice approval","for our regional","becoming bottlenecked","had become a major bottleneck"],"target_translation":"Persetujuan faktur manual telah menjadi titik kemacetan utama bagi tim keuangan regional kami."}'::jsonb, '["Manual invoice approval","had become a major bottleneck","for our regional","finance team."]'::jsonb, NULL, NULL, 'Menjelaskan konteks masalah bisnis secara ringkas membuka cerita STAR dengan tajam.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000037', 'e5100001-0000-4000-8000-000000000005', NULL, 'speaking', 'speaking_repeat', 'Latih intonasi percaya diri saat menyampaikan capaian wawancara berikut:', '{"romaji":"/aɪ droʊv ˌkrɔːsˈfʌŋkʃənəl əˈlaɪnmənt əˈkrɔːs ˌɛndʒəˈnɪrɪŋ ˈliːɡəl ænd ˈprɑːdʌkt/","display_text":"I drove cross-functional alignment across engineering, legal, and product.","phonetic_breakdown":["I drove","cross-functional alignment","across engineering,","legal, and product."]}'::jsonb, '{"expected_transcript":"I drove cross-functional alignment across engineering, legal, and product."}'::jsonb, NULL, NULL, 'Gunakan intonasi naik tipis pada daftar ''engineering, legal,'' lalu turun tegas pada ''and product.''', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000038', 'e5100001-0000-4000-8000-000000000005', NULL, 'reading', 'fill_blank', 'Pilih kata benda yang tepat untuk mendeskripsikan hasil nyata proyek:', '{"options":["digressions","speculations","deliverables","placeholders"],"translation":"Selama wawancara behavioral, manajer perekrutan mencari luaran kerja yang konkret alih-alih deskripsi pekerjaan yang samar.","sentence_template":"During behavioral interviews, hiring managers look for concrete [blank] rather than vague job descriptions."}'::jsonb, '{"selected":"deliverables"}'::jsonb, NULL, NULL, '''Deliverables'' merujuk pada hasil atau luaran nyata yang berhasil diselesaikan dan diserahkan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000039', 'e5100001-0000-4000-8000-000000000005', NULL, 'listening', 'listening_choice', 'Dengarkan pertanyaan pewawancara. Kompetensi apa yang ingin digali pewawancara?', '{"options":[{"id":"opt_1","text":"Alasan kandidat ingin berpindah industri dalam lima tahun ke depan"},{"id":"opt_2","text":"Kemampuan memengaruhi dan membangun kesepahaman lintas fungsi tanpa wewenang atasan langsung"},{"id":"opt_3","text":"Pengalaman menulis kode kompilator tingkat rendah secara mandiri"},{"id":"opt_4","text":"Kemampuan memberhentikan bawahan yang melanggar prosedur keselamatan"}],"audio_text":"Tell me about a time when you had to persuade a skeptical stakeholder without having direct authority over them."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Persuade a skeptical stakeholder without direct authority'' menguji *influence without authority* pada level B2–C1.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000040', 'e5100001-0000-4000-8000-000000000005', NULL, 'writing', 'sentence_builder', 'Susun kalimat Result terukur dengan kontras angka awal dan akhir:', '{"romaji":"/ðɪs ɪˈnɪʃətɪv ˈbuːstɪd ˈaʊər nɛt prəˈmoʊtər skɔːr frʌm ˈθɜːrti eɪt tə ˈsɪksti fɔːr/","tokens":["from thirty-eight","our net promoter score","by sixty-four from","to sixty-four.","This initiative boosted","boosting into"],"target_translation":"Inisiatif ini mendongkrak skor net promoter kami dari 38 menjadi 64."}'::jsonb, '["This initiative boosted","our net promoter score","from thirty-eight","to sixty-four."]'::jsonb, NULL, NULL, 'Pasangan preposisi ''from [angka awal] to [angka akhir]'' menyajikan bukti transformasi secara presisi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000041', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Pilih bentuk kala lampau yang tepat untuk menjelaskan akar masalah sebelum kandidat bertindak:', '{"options":["have eroded","are eroding","had been eroding","will be eroding"],"translation":"Pada saat saya bergabung ke tim pemenuhan pesanan, keterlambatan pengiriman telah terus menggerus kepercayaan pelanggan selama hampir enam bulan.","sentence_template":"By the time I joined the fulfillment squad, late deliveries [blank] customer trust for nearly six months."}'::jsonb, '{"selected":"had been eroding"}'::jsonb, NULL, NULL, '''By the time + Simple Past'' menuntut Past Perfect Continuous (''had been eroding'') untuk durasi yang mendahului titik waktu lampau.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000042', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Pilih bentuk kata kerja yang tepat untuk aksi utama kandidat setelah latar kejadian:', '{"options":["had been building","built","am building","have built"],"translation":"Sementara tim pemasaran sedang merampungkan aset kampanye, saya membangun uji beban otomatis guna mencegah server tumbang.","sentence_template":"While the marketing team was finalizing the campaign assets, I [blank] an automated load test to prevent server crashes."}'::jsonb, '{"selected":"built"}'::jsonb, NULL, NULL, 'Aksi spesifik yang diambil kandidat pada cerita lampau dinyatakan dengan Simple Past (''built'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000043', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'listening', 'listening_choice', 'Dengarkan cuplikan cerita kandidat. Apa kondisi awal sistem sebelum kandidat melakukan perbaikan?', '{"options":[{"id":"opt_1","text":"Insinyur baru sebelumnya menghabiskan sebulan penuh pertama hanya untuk memahami instalasi lokal"},{"id":"opt_2","text":"Dokumentasi API sudah terstandarisasi sejak perusahaan berdiri"},{"id":"opt_3","text":"Kandidat meminta insinyur baru menulis ulang seluruh server produksi"},{"id":"opt_4","text":"Insinyur baru sudah dapat merilis kode pada hari pertama bekerja"}],"audio_text":"Before I standardized our API documentation, new engineers had been spending their entire first month just figuring out local setup."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Past Perfect Continuous ''had been spending'' menandai masalah berulang sebelum tindakan ''Before I standardized...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000044', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat latar Situation wawancara dengan Past Perfect yang tepat:', '{"romaji":"/bɪˈkɔːz ðə ˈpriːviəs ˈvɛndər hæd ˈnɛvər ɪnˈkrɪptɪd ˈbækʌp ˈsnæpˌʃɑːts/","tokens":["prioritizing on","has never encrypt","backup snapshots,","Because the previous vendor","had never encrypted","we prioritized security remediation."],"target_translation":"Karena vendor sebelumnya belum pernah mengenkripsi salinan cadangan, kami memprioritaskan pemulihan keamanan."}'::jsonb, '["Because the previous vendor","had never encrypted","backup snapshots,","we prioritized security remediation."]'::jsonb, NULL, NULL, 'Kelalaian di masa sebelum proyek dimulai dinyatakan dengan Past Perfect (''had never encrypted'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000045', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'speaking', 'speaking_repeat', 'Ucapkan kalimat Action wawancara berikut dengan artikulasi akhiran -ed yang akurat:', '{"romaji":"/aɪ ˌdaɪəɡˈnoʊst ðə ˈmɛməri liːk ˌriːˈfæktərd ðə ˈsɜːrvɪs ænd rɪˈstɔːrd stəˈbɪləti/","display_text":"I diagnosed the memory leak, refactored the service, and restored stability.","phonetic_breakdown":["I diagnosed","the memory leak,","refactored the service,","and restored stability."]}'::jsonb, '{"expected_transcript":"I diagnosed the memory leak, refactored the service, and restored stability."}'::jsonb, NULL, NULL, 'Perhatikan tiga bunyi akhiran -ed tanpa tambahan vokal berlebih: diagnosed /t/, refactored /d/, restored /d/.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000046', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Lengkapi kalimat refleksi pembelajaran (Learning) di akhir jawaban STAR:', '{"options":["will question","questions","is questioning","had questioned"],"translation":"Gangguan sistem tersebut mengajarkan saya betapa pentingnya memverifikasi asumsi yang belum pernah dipertanyakan siapa pun selama bertahun-tahun.","sentence_template":"That outage taught me how vital it was to verify assumptions that nobody [blank] in years."}'::jsonb, '{"selected":"had questioned"}'::jsonb, NULL, NULL, 'Asumsi tersebut tidak dipertanyakan pada periode sebelum gangguan terjadi, sehingga memakai Past Perfect ''had questioned''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000047', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'listening', 'listening_choice', 'Dengarkan bagian Action seorang Product Manager. Apa langkah pertama yang ia lakukan sendiri?', '{"options":[{"id":"opt_1","text":"Ia menyerahkan seluruh wawancara pelanggan kepada agensi eksternal"},{"id":"opt_2","text":"Ia langsung menyetujui pembangunan tiga fitur baru tanpa riset pengguna"},{"id":"opt_3","text":"Ia mewawancarai langsung lima belas pengguna yang berhenti berlangganan untuk menemukan alasan pasti mereka membatalkan layanan"},{"id":"opt_4","text":"Ia menaikkan harga langganan guna menutupi kehilangan lima belas pengguna"}],"audio_text":"Although my team wanted to build three new features right away, I first interviewed fifteen churned users to pinpoint why they had canceled."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''I first interviewed... to pinpoint why they had canceled'' menunjukkan kepemimpinan berbasis riset dan kontras Simple Past + Past Perfect.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000048', 'e5100001-0000-4000-8000-000000000006', 'e2000001-0000-4000-8000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat penutup cerita wawancara berikut:', '{"romaji":"/wʌns aɪ hæd ˈvæləˌdeɪtɪd ðə ˈproʊtəˌtaɪp wɪð ˈjuːzərz ˈliːdərˌʃɪp ˈɡriːnˌlɪt/","tokens":["greenlighting to","leadership greenlit","the prototype with users,","Once I had validated","have validating","full production funding."],"target_translation":"Begitu saya selesai memvalidasi prototipe bersama pengguna, pimpinan menyetujui pendanaan produksi penuh."}'::jsonb, '["Once I had validated","the prototype with users,","leadership greenlit","full production funding."]'::jsonb, NULL, NULL, '''Once I had validated'' menegaskan selesainya tahap validasi sebelum keputusan ''greenlit'' (Simple Past dari greenlight).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000049', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Lengkapi kalimat refleksi wawancara kerja berikut:', '{"options":["At random","On the brink","By coincidence","In hindsight"],"translation":"Jika dilihat kembali ke belakang, saya semestinya melibatkan tim kepatuhan hukum sejak sprint desain awal, bukan tepat menjelang peluncuran.","sentence_template":"[blank], I should have involved the legal compliance team during the initial design sprint rather than right before launch."}'::jsonb, '{"selected":"In hindsight"}'::jsonb, NULL, NULL, '''In hindsight'' digunakan untuk mengevaluasi keputusan masa lalu berdasarkan pemahaman yang baru dimiliki sekarang.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000050', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Pilih struktur Wh-Cleft yang tepat untuk menonjolkan pelajaran utama:', '{"options":["Why I took away","That I took away","Which took me away","What I took away"],"translation":"Pelajaran penting yang saya petik dari menangani krisis tersebut adalah bahwa komunikasi transparan membangun kepercayaan jauh lebih besar daripada perfeksionisme yang tertutup.","sentence_template":"[blank] from managing that crisis was that transparent communication builds far more trust than silent perfectionism."}'::jsonb, '{"selected":"What I took away"}'::jsonb, NULL, NULL, 'Wh-Cleft dimulai dengan ''What + Subject + Verb'' yang berfungsi sebagai subjek kalimat sebelum ''was''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000051', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'listening', 'listening_choice', 'Dengarkan respons TOEFL Independent Speaking berikut. Mengapa pembicara memilih bekerja di startup kecil pada awal karier?', '{"options":[{"id":"opt_1","text":"Gaji pokok awal yang jauh lebih tinggi dibandingkan perusahaan teknologi raksasa"},{"id":"opt_2","text":"Keinginan menghindari interaksi langsung dengan pelanggan produk"},{"id":"opt_3","text":"Kesempatan memegang beragam peran sekaligus melihat dampak langsung kodenya pada pengguna nyata"},{"id":"opt_4","text":"Jam kerja yang sangat singkat tanpa tanggung jawab lintas divisi"}],"audio_text":"What drew me to an early-stage startup was the chance to wear multiple hats and see the direct impact of my code on real users."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Idiom ''wear multiple hats'' berarti menjalankan berbagai peran/tanggung jawab sekaligus.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000052', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat akuntabilitas profesional berikut:', '{"romaji":"/ˈræðər ðæn ˈbleɪmɪŋ æmˈbɪɡjuəs rɪˈkwaɪərmənts aɪ oʊnd ʌp tuː/","tokens":["ambiguous requirements,","I owned up to","and course-corrected.","owning into","blamed at","the estimation oversight","Rather than blaming"],"target_translation":"Alih-alih menyalahkan spesifikasi yang ambigu, saya mengakui kekeliruan estimasi tersebut dan mengoreksi arah kerja."}'::jsonb, '["Rather than blaming","ambiguous requirements,","I owned up to","the estimation oversight","and course-corrected."]'::jsonb, NULL, NULL, '''Own up to + Noun'' diikuti ''course-corrected'' memperlihatkan kedewasaan profesional yang dicari pewawancara.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000053', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'speaking', 'speaking_repeat', 'Latih penekanan retoris Wh-Cleft untuk TOEFL Speaking & wawancara:', '{"romaji":"/wʌt meɪd ðə ˈbɪɡɪst ˈdɪfrəns wʌz ˈlɪsənɪŋ tə ˈfrʌntˌlaɪn səˈpɔːrt ˈeɪdʒənts/","display_text":"What made the biggest difference was listening to frontline support agents.","phonetic_breakdown":["What made","the biggest difference","was listening to","frontline support agents."]}'::jsonb, '{"expected_transcript":"What made the biggest difference was listening to frontline support agents."}'::jsonb, NULL, NULL, 'Berikan jeda mikro sesudah ''difference'' sebelum masuk ke fokus informasi baru sesudah ''was''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000054', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Pilih ungkapan yang tepat untuk merangkum poin akhir presentasi atau wawancara:', '{"options":["key takeaway","shortfall","blind spot","red tape"],"translation":"Pelajaran terpenting saya dari memimpin tiga tim jarak jauh adalah kejelasan tulisan asinkron jauh lebih berarti daripada panggilan video tanpa henti.","sentence_template":"My [blank] from leading three remote squads is that asynchronous written clarity matters more than endless video calls."}'::jsonb, '{"selected":"key takeaway"}'::jsonb, NULL, NULL, '''Key takeaway'' adalah kolokasi profesional untuk inti pelajaran atau kesimpulan utama.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000055', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'listening', 'listening_choice', 'Dengarkan kandidat menceritakan kegagalan proyek. Bagaimana ia memulihkan keadaan?', '{"options":[{"id":"opt_1","text":"Mereka menutup layanan untuk pemilik usaha kecil secara permanen"},{"id":"opt_2","text":"Mereka menambahkan lima tingkatan harga baru yang lebih rumit"},{"id":"opt_3","text":"Mereka segera mengoreksi strategi dengan menyederhanakan skema harga menjadi dua tingkatan tarif tetap"},{"id":"opt_4","text":"Mereka menyalahkan tim penjualan atas turunnya jumlah pelanggan"}],"audio_text":"Once we realized our pricing model confused small business owners, we quickly course-corrected by simplifying into two flat tiers."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Course-corrected by simplifying...'' menjelaskan langkah perbaikan cepat begitu kesalahan terdeteksi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000056', 'e5100001-0000-4000-8000-000000000007', 'e2000001-0000-4000-8000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat refleksi akhir wawancara yang elegan:', '{"romaji":"/wʌt ðæt ˈfeɪljər tɔːt mi wʌz ˈnɛvər tə dɪˈplɔɪ wɪˈðaʊt ə ˈroʊlˌbæk plæn/","tokens":["without a rollback plan.","taught me was","What that failure","deploying without to","never to deploy","Which that failure"],"target_translation":"Hal yang diajarkan kegagalan itu kepada saya adalah jangan pernah merilis sistem tanpa rencana pemulihan mundur."}'::jsonb, '["What that failure","taught me was","never to deploy","without a rollback plan."]'::jsonb, NULL, NULL, 'Pola ''What [S] taught me was never to [V1]'' sangat efektif menutup jawaban behavioral.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000057', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Pilih bentuk waktu yang tepat untuk bagian Situation:', '{"options":["will halt","are halting","have halted","had been halting"],"translation":"Sebelum saya memperkenalkan pemeriksaan skema otomatis, migrasi yang rusak telah terus menghentikan perilisan staging hampir setiap minggu.","sentence_template":"Before I introduced automated schema checks, broken migrations [blank] staging deployments almost every week."}'::jsonb, '{"selected":"had been halting"}'::jsonb, NULL, NULL, 'Masalah berulang yang berlangsung sebelum aksi lampau dinyatakan dengan Past Perfect Continuous (''had been halting'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000058', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Pilih preposisi dampak kuantitatif yang presisi:', '{"options":["until","onto","for","by"],"translation":"Merancang ulang alur pembayaran kami menurunkan pengabaian keranjang belanja sebesar 28 persen hanya dalam satu kuartal.","sentence_template":"Redesigning our checkout funnel decreased cart abandonment [blank] 28 percent within a single quarter."}'::jsonb, '{"selected":"by"}'::jsonb, NULL, NULL, 'Selisih penurunan persentase wajib menggunakan preposisi ''by''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000059', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'listening', 'listening_choice', 'Evaluasi Unit 2 — Dengarkan jawaban kandidat. Mengapa rekruter akan menilai jawaban ini sangat kuat?', '{"options":[{"id":"opt_1","text":"Kandidat menjelaskan tindakan pribadinya secara spesifik (''I renegotiated'') beserta metrik hasil yang konkret (''above 98%'')"},{"id":"opt_2","text":"Kandidat menghindari tanggung jawab dan menyalahkan pemasok sepenuhnya"},{"id":"opt_3","text":"Kandidat hanya berbicara teoretis tanpa menyebutkan tindakan nyata"},{"id":"opt_4","text":"Kandidat membatalkan seluruh pesanan pelanggan selama krisis berlangsung"}],"audio_text":"When vendor shipments stalled, I renegotiated SLA terms with two backup suppliers, which kept our fulfillment rate above ninety-eight percent."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Jawaban STAR unggulan memadukan aksi kepemilikan jelas (Action) dan capaian kuantitatif (Result).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000060', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'writing', 'sentence_builder', 'Evaluasi Unit 2 — Susun kalimat refleksi Wh-Cleft berikut:', '{"romaji":"/wʌt aɪ lɜːrnd frʌm ðæt lɔːntʃ wʌz tə əˈlaɪn ˈsteɪkˌhoʊldərz bɪˈfɔːr ˈkoʊdɪŋ/","tokens":["What I learned","from that launch","That I learned","stakeholders before coding.","was to align","aligning into"],"target_translation":"Pelajaran yang saya petik dari peluncuran tersebut adalah menyelaraskan para pemangku kepentingan sebelum mulai menulis kode."}'::jsonb, '["What I learned","from that launch","was to align","stakeholders before coding."]'::jsonb, NULL, NULL, 'Wh-Cleft menempatkan ''What I learned from that launch'' sebagai subjek utuh sebelum ''was''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000061', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'speaking', 'speaking_repeat', 'Evaluasi Unit 2 — Ucapkan pernyataan dampak STAR berikut dengan artikulasi angka yang jelas:', '{"romaji":"/aɪ ˈoʊvərˌhɔːld ˈaʊər ˈɔːnˌbɔːrdɪŋ floʊ ænd kʌt ˌæktəˈveɪʃən taɪm baɪ hæf/","display_text":"I overhauled our onboarding flow and cut activation time by half.","phonetic_breakdown":["I overhauled","our onboarding flow","and cut activation time","by half."]}'::jsonb, '{"expected_transcript":"I overhauled our onboarding flow and cut activation time by half."}'::jsonb, NULL, NULL, 'Tekankan verba ''OVERHAULED'' dan metrik penutup ''by HALF'' (/hæf/ dengan vokal Amerika æ).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000062', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Lengkapi kalimat evaluasi diri profesional:', '{"options":["pushed back at","panned out on","ruled out from","owned up to"],"translation":"Ketika proyeksi awal saya terbukti meleset, saya segera mengakui kekeliruan tersebut dan menyajikan tiga opsi mitigasi.","sentence_template":"When my initial forecast proved inaccurate, I immediately [blank] the error and presented three mitigation options."}'::jsonb, '{"selected":"owned up to"}'::jsonb, NULL, NULL, '''Own up to an error'' berarti mengakui kesalahan secara terbuka dan bertanggung jawab.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000063', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'listening', 'listening_choice', 'Evaluasi Unit 2 — Dengarkan refleksi seorang Engineering Manager. Apa perubahan proses yang ia terapkan?', '{"options":[{"id":"opt_1","text":"Melarang perubahan kode sama sekali selama dua minggu penuh"},{"id":"opt_2","text":"Menghapus pengujian otomatis agar penggabungan kode lebih cepat"},{"id":"opt_3","text":"Menerapkan integrasi kode harian agar tim tidak lagi menumpuk penggabungan cabang pada hari Jumat"},{"id":"opt_4","text":"Mewajibkan seluruh insinyur bekerja lembur setiap Jumat malam"}],"audio_text":"In hindsight, waiting until Friday to integrate branches caused unnecessary stress, so my key takeaway was to enforce daily trunk-based integration."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''In hindsight'' + ''key takeaway'' merangkum akar masalah lama dan solusi permanen yang diterapkan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000064', 'e5100001-0000-4000-8000-000000000008', 'e2000001-0000-4000-8000-000000000032', 'writing', 'sentence_builder', 'Evaluasi Unit 2 — Susun kalimat kontras waktu narasi STAR:', '{"romaji":"/waɪl səˈpɔːrt ˈeɪdʒənts wɜːr ˈhændlɪŋ ˈtɪkɪts aɪ bɪlt ə skrɪpt tə ˈɔːtəˌmeɪt ˈriːfʌndz/","tokens":["automating into","While support agents","to automate refunds.","I built a script","were handling tickets,","had handling"],"target_translation":"Sementara agen layanan sedang menangani tiket, saya membuat skrip untuk mengotomatiskan pengembalian dana."}'::jsonb, '["While support agents","were handling tickets,","I built a script","to automate refunds."]'::jsonb, NULL, NULL, 'Past Continuous (''were handling'') memberi latar waktu bagi aksi utama Simple Past (''I built'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000065', 'e5100001-0000-4000-8000-000000000009', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kuliah ekologi berikut dengan verba relasional yang tepat:', '{"options":["brushes off","complies to","digresses from","hinges on"],"translation":"Seluruh siklus migrasi kupu-kupu raja sangat bergantung pada perubahan halus durasi cahaya siang dan ketersediaan tanaman milkweed.","sentence_template":"The entire migration cycle of monarch butterflies [blank] subtle changes in daylight duration and milkweed availability."}'::jsonb, '{"selected":"hinges on"}'::jsonb, NULL, NULL, '''Hinges on'' menyatakan ketergantungan krusial suatu fenomena ilmiah pada faktor penentu.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000066', 'e5100001-0000-4000-8000-000000000009', NULL, 'reading', 'fill_blank', 'Pilih kata sifat akademik yang menggambarkan temuan sains di luar dugaan umum:', '{"options":["obsolete","redundant","unanimous","counterintuitive"],"translation":"Sekilas tampak bertentangan dengan intuisi awam bahwa kebakaran hutan terkendali justru meningkatkan keanekaragaman hayati jangka panjang.","sentence_template":"At first glance, it seems [blank] that controlled forest fires actually increase long-term biodiversity."}'::jsonb, '{"selected":"counterintuitive"}'::jsonb, NULL, NULL, '''Counterintuitive'' berarti berlawanan dengan tebakan naluriah atau akal sehat sepintas.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000067', 'e5100001-0000-4000-8000-000000000009', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah geologi TOEFL. Mengapa profesor mengatakan ''Wait—let me back up a second''?', '{"options":[{"id":"opt_1","text":"Profesor lupa membawa slide presentasi tentang gunung berapi"},{"id":"opt_2","text":"Profesor meminta mahasiswa keluar ruangan karena jam kuliah sudah habis"},{"id":"opt_3","text":"Profesor menyadari penjelasan tentang magma basal sepenuhnya salah secara ilmiah"},{"id":"opt_4","text":"Profesor ingin menjelaskan konsep dasar kekentalan (viscosity) terlebih dahulu agar mahasiswa paham mekanisme utamanya"}],"audio_text":"So basaltic magma rises rapidly through fissures... Wait—let me back up a second and clarify how viscosity affects gas escape first."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Penanda koreksi diri ''Wait—let me back up a second'' di TOEFL Listening berfungsi menyisipkan prasyarat konsep sebelum melanjutkan topik.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000068', 'e5100001-0000-4000-8000-000000000009', NULL, 'writing', 'sentence_builder', 'Susun kalimat kesimpulan riset laboratorium berikut:', '{"romaji":"/ˈsætəˌlaɪt ˈθɜːrməl ˈdeɪtə kəˈrɑːbəˌreɪtɪd ðə ˈfaɪndɪŋz ˈpʌblɪʃt baɪ məˈriːn baɪˈɑːlədʒɪsts/","tokens":["corroborated the findings","published by","publishing at","Satellite thermal data","marine biologists last year.","corroborating into"],"target_translation":"Data termal satelit menguatkan temuan yang diterbitkan oleh para ahli biologi kelautan tahun lalu."}'::jsonb, '["Satellite thermal data","corroborated the findings","published by","marine biologists last year."]'::jsonb, NULL, NULL, '''Corroborate the findings'' menghubungkan sumber bukti baru dengan hasil riset sebelumnya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000069', 'e5100001-0000-4000-8000-000000000009', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat penjelasan ilmiah berikut dengan penekanan suku kata Amerika yang tepat:', '{"romaji":"/ˌsʌbtəˈreɪniən ˈmaɪkroʊbz əˈkaʊnt fɔːr ˈnɪrli ˈfɔːrti pərˈsɛnt ʌv ˌkɑːntəˈnɛntəl ˈbaɪoʊˌmæs/","display_text":"Subterranean microbes account for nearly forty percent of continental biomass.","phonetic_breakdown":["Subterranean microbes","account for","nearly forty percent","of continental biomass."]}'::jsonb, '{"expected_transcript":"Subterranean microbes account for nearly forty percent of continental biomass."}'::jsonb, NULL, NULL, 'Perhatikan tekanan utama pada ''sub-ter-RA-ne-an'' dan makna ''account for'' (mencakup porsi).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000070', 'e5100001-0000-4000-8000-000000000009', NULL, 'reading', 'fill_blank', 'Pilih frasa kerja akademik yang berarti ''menjelaskan alasan terjadinya suatu fenomena'':', '{"options":["account for","opt out","hand down","rule in"],"translation":"Para oseanografer mengajukan dua model yang saling bersaing untuk menjelaskan penyebab pemanasan mendadak arus dalam Pasifik.","sentence_template":"Oceanographers proposed two competing models to [blank] the sudden warming of deep Pacific currents."}'::jsonb, '{"selected":"account for"}'::jsonb, NULL, NULL, 'Selain berarti ''mencakup persentase'', ''account for'' dalam sains berarti memberi penjelasan kausal atas suatu fenomena.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000071', 'e5100001-0000-4000-8000-000000000009', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah psikologi kognitif. Apa fungsi contoh ''mencari kunci di saku yang sama berkali-kali''?', '{"options":[{"id":"opt_1","text":"Memberikan analogi sehari-hari guna memperjelas konsep ilmiah ''perseverative error'' saat stres"},{"id":"opt_2","text":"Mengalihkan pembicaraan karena topik ujian tidak membahas stres"},{"id":"opt_3","text":"Membuktikan bahwa ingatan jangka pendek manusia tidak dapat dilatih"},{"id":"opt_4","text":"Menyarankan mahasiswa membeli gantungan kunci elektronik pintar"}],"audio_text":"Think about checking the same coat pocket three times for your lost keys—that everyday frustration illustrates perseverative error under stress."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pertanyaan pragmatik TOEFL (''Why does the professor mention...'') dijawab dengan mengaitkan contoh konkret ke istilah teoretisnya.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000072', 'e5100001-0000-4000-8000-000000000009', NULL, 'writing', 'sentence_builder', 'Susun kalimat pengantar kuliah profesor berikut:', '{"romaji":"/bɪˈfɔːr ɪɡˈzæmɪnɪŋ ˈnʊrəl plæˈstɪsəti lɛts ˈbriːfli ˈriːkæp haʊ sɪˈnæptɪk ˈpruːnɪŋ wɜːrks/","tokens":["worked how","briefly recapping to","let''s briefly recap","Before examining","neural plasticity,","how synaptic pruning works."],"target_translation":"Sebelum menelaah plastisitas saraf, mari kita ulas singkat bagaimana pemangkasan sinaptik bekerja."}'::jsonb, '["Before examining","neural plasticity,","let''s briefly recap","how synaptic pruning works."]'::jsonb, NULL, NULL, 'Perhatikan kata tanya tidak langsung (embedded question) ''how synaptic pruning works'' memakai susunan S + V normal tanpa ''does''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000073', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Pilih susunan klausa tanya tak langsung (embedded question) yang gramatikal:', '{"options":["did whether","whether","that did","if or not did"],"translation":"Para ahli paleontologi telah lama bertanya-tanya apakah musim dingin vulkanik mendadak memicu kepunahan Trias.","sentence_template":"Paleontologists have long wondered [blank] sudden volcanic winters triggered the Triassic extinction."}'::jsonb, '{"selected":"whether"}'::jsonb, NULL, NULL, '''Wondered whether + Subject + Verb'' adalah struktur baku tanpa kata bantu inversi ''did''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000074', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat laporan riset berikut dengan struktur klausa yang benar:', '{"options":["the extent which","the extent to which","how much do","to what extent do"],"translation":"Studi kembar jangka panjang membantu ahli genetika menentukan sejauh mana faktor lingkungan membentuk penuaan kognitif.","sentence_template":"Longitudinal twin studies help geneticists determine [blank] environmental factors shape cognitive aging."}'::jsonb, '{"selected":"the extent to which"}'::jsonb, NULL, NULL, '''The extent to which + S + V'' merupakan konstruksi akademik formal yang bebas dari kesalahan inversi ''do''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000075', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'listening', 'listening_choice', 'Dengarkan profesor sejarah seni menggunakan pertanyaan retoris. Apa poin yang langsung ia tegaskan?', '{"options":[{"id":"opt_1","text":"Cat minyak mengering cukup lambat sehingga memungkinkan pencampuran gradasi warna yang halus"},{"id":"opt_2","text":"Tempera telur memiliki warna yang terlalu kusam dan mudah pudar"},{"id":"opt_3","text":"Seniman Renaisans kesulitan membeli pigmen mineral dari luar negeri"},{"id":"opt_4","text":"Mahasiswa diminta mempraktikkan lukisan tempera minggu depan"}],"audio_text":"Now, why did Renaissance workshops suddenly abandon egg tempera? Not because tempera lacked vibrancy, mind you, but because oil paint dried slowly enough for seamless blending."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pertanyaan retoris diikuti sanggahan ''Not because X, but because Y'' menandai Y sebagai jawaban kunci soal TOEFL.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000076', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat akademik dengan embedded question tanpa inversi:', '{"romaji":"/ˈaʊər ɪkˈspɛrəmənt træks haʊ sɔɪl səˈlɪnəti əˈfɛkts ruːt əbˈzɔːrpʃən/","tokens":["affects root absorption","during severe droughts.","Our experiment tracks","how soil salinity","how does salinity","affecting into"],"target_translation":"Eksperimen kami melacak bagaimana salinitas tanah memengaruhi penyerapan akar selama kekeringan parah."}'::jsonb, '["Our experiment tracks","how soil salinity","affects root absorption","during severe droughts."]'::jsonb, NULL, NULL, 'Di dalam objek ''tracks how...'', urutan kata wajib Subjek (''soil salinity'') + Verba (''affects''), bukan ''how does...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000077', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'speaking', 'speaking_repeat', 'Tirukan intonasi pertanyaan retoris dan jawabannya ala kuliah kampus Amerika:', '{"romaji":"/soʊ wʌt draɪvz diːp siː ˌbaɪoʊˌluːməˈnɛsəns praɪˈmɛrəli ˈprɛdətər ɪˈveɪʒən ænd meɪt əˈtrækʃən/","display_text":"So what drives deep-sea bioluminescence? Primarily predator evasion and mate attraction.","phonetic_breakdown":["So what drives","deep-sea bioluminescence?","Primarily predator evasion","and mate attraction."]}'::jsonb, '{"expected_transcript":"So what drives deep-sea bioluminescence? Primarily predator evasion and mate attraction."}'::jsonb, NULL, NULL, 'Naikkan nada ekspresif pada ''bioluminescence?'', beri jeda setengah detik, lalu jawab mantap dengan nada turun.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000078', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Pilih kelanjutan gramatikal sesudah preposisi ''regardless of'':', '{"options":["if","did","what did","whether"],"translation":"Seluruh hasil uji klinis wajib didaftarkan secara terbuka, terlepas dari apakah obat tersebut mengungguli kelompok kontrol.","sentence_template":"All clinical trial results must be registered publicly, regardless of [blank] the drug outperformed the control group."}'::jsonb, '{"selected":"whether"}'::jsonb, NULL, NULL, 'Sesudah preposisi (''regardless of'', ''depend on''), bahasa Inggris standar mengharuskan ''whether'', bukan ''if''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000079', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'listening', 'listening_choice', 'Dengarkan diskusi mahasiswa dengan pustakawan kampus. Apa kendala akses jurnal yang dialami mahasiswa?', '{"options":[{"id":"opt_1","text":"Akses proxy luar kampusnya terus menolak kredensial login saat membuka arsip radiologi"},{"id":"opt_2","text":"Mahasiswa lupa mengembalikan buku cetak radiologi bulan lalu"},{"id":"opt_3","text":"Server universitas sedang dimatikan selama libur musim panas"},{"id":"opt_4","text":"Perpustakaan kampus sudah berhenti berlangganan seluruh jurnal kedokteran"}],"audio_text":"I''m trying to figure out why my off-campus proxy keeps rejecting my credentials whenever I open radiology archives."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Perhatikan embedded clause ''figure out why my off-campus proxy keeps rejecting...'' yang menjelaskan inti masalah mahasiswa.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000080', 'e5100001-0000-4000-8000-000000000010', 'e2000001-0000-4000-8000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat metodologi riset dengan frasa ''the degree to which'':', '{"romaji":"/fiːld ˈsɛnsərz ˈmɛʒərd ðə dɪˈɡriː tə wɪtʃ ˈɜːrbən triː ˈkænəpiz ˈmɪtəˌɡeɪt hiːt ˈaɪləndz/","tokens":["urban tree canopies","which degree do","Field sensors measured","mitigate heat islands.","the degree to which","mitigating of"],"target_translation":"Sensor lapangan mengukur sejauh mana kanopi pepohonan kota meredam pulau panas perkotaan."}'::jsonb, '["Field sensors measured","the degree to which","urban tree canopies","mitigate heat islands."]'::jsonb, NULL, NULL, '''The degree to which'' setara dengan ''the extent to which'' dan diikuti klausa lengkap S + V.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000081', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Pilih penghubung hasil ringkas yang tepat untuk rangkuman kuliah biologi:', '{"options":["nonetheless","unless","thereby","whereas"],"translation":"Tupai tanah Arktik menurunkan laju metabolisme mendekati titik beku, sehingga menghemat energi vital sepanjang musim dingin.","sentence_template":"Arctic ground squirrels lower their metabolic rate near freezing, [blank] conserving vital energy throughout winter."}'::jsonb, '{"selected":"thereby"}'::jsonb, NULL, NULL, ''', thereby + V-ing'' menyatakan konsekuensi langsung secara padat dalam satu kalimat ilmiah.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000082', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Pilih idiom akademik yang tepat untuk menjelaskan kontribusi temuan arkeologi:', '{"options":["fall behind on","pan out from","turn down to","shed light on"],"translation":"Lempengan tanah liat yang baru digali memberikan titik terang tentang bagaimana pedagang Zaman Perunggu membiayai perdagangan laut.","sentence_template":"Newly excavated clay tablets [blank] how Bronze Age merchants financed maritime trade."}'::jsonb, '{"selected":"shed light on"}'::jsonb, NULL, NULL, '(Catatan kosakata: ''shed light on'' berarti menyingkap kejelasan baru atas fenomena yang tadinya kabur.)', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000083', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'listening', 'listening_choice', 'Dengarkan rangkuman lisan mahasiswa untuk TOEFL Speaking Task 4. Dua mekanisme apa yang sedang ia bandingkan?', '{"options":[{"id":"opt_1","text":"Reproduksi spora jamur dibanding penyerbukan serangga pada bunga"},{"id":"opt_2","text":"Kamuflase untuk menghindari deteksi dibanding warna mencolok sebagai sinyal peringatan racun"},{"id":"opt_3","text":"Migrasi jarak jauh burung dibanding hibernasi mamalia kutub"},{"id":"opt_4","text":"Perburuan berkelompok serigala dibanding penyergapan soliter macan tutul"}],"audio_text":"The lecturer explains two anti-predator strategies: whereas stick insects rely on camouflage to avoid detection altogether, poison dart frogs use bright warning coloration to deter attacks."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Konjungsi kontras ''whereas'' memetakan dua sub-topik kuliah secara seimbang dalam satu kalimat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000084', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat rangkuman TOEFL Speaking Task 4 berikut:', '{"romaji":"/ðə prəˈfɛsər ˈɪləˌstreɪts ˈkɑːɡnətɪv ˈfreɪmɪŋ baɪ kəmˈpɛrɪŋ tuː ˈsuːpərˌmɑːrkɪt ˈpraɪsɪŋ ˈleɪbəlz/","tokens":["The professor illustrates","supermarket pricing labels.","by comparing two","cognitive framing","two comparing of","illustrating into"],"target_translation":"Profesor mengilustrasikan pembingkaian kognitif dengan membandingkan dua label harga supermarket."}'::jsonb, '["The professor illustrates","cognitive framing","by comparing two","supermarket pricing labels."]'::jsonb, NULL, NULL, 'Pola ''The professor illustrates [Concept] by + V-ing [Example]'' langsung membuka rangkuman dengan efisien.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000085', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'speaking', 'speaking_repeat', 'Latih kelancaran bicara rangkuman ilmiah 60 detik berikut:', '{"romaji":"/kɛlp ˈfɔːrɪsts əbˈzɔːrb weɪv ˈɛnərdʒi ˌðɛrˈbaɪ prəˈtɛktɪŋ ˈkoʊstəl ˈiːkoʊˌsɪstəmz frʌm ɪˈroʊʒən/","display_text":"Kelp forests absorb wave energy, thereby protecting coastal ecosystems from erosion.","phonetic_breakdown":["Kelp forests","absorb wave energy,","thereby protecting","coastal ecosystems from erosion."]}'::jsonb, '{"expected_transcript":"Kelp forests absorb wave energy, thereby protecting coastal ecosystems from erosion."}'::jsonb, NULL, NULL, 'Jaga transisi mulus pada jeda koma sebelum ''thereby protecting'' tanpa keraguan (''uh/um'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000086', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Perbaiki pilihan kata transisi kontras untuk menghubungkan contoh kedua profesor:', '{"options":["as a result","in other words","by contrast","for instance"],"translation":"Eksperimen pertama menguji ingatan visual dalam keheningan; sebaliknya, eksperimen kedua menambahkan kebisingan latar kafetaria.","sentence_template":"The first experiment tested visual recall in silence; [blank], the second introduced background cafeteria noise."}'::jsonb, '{"selected":"by contrast"}'::jsonb, NULL, NULL, '''By contrast'' menandai perbedaan kondisi eksperimen pertama dan kedua secara eksplisit.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000087', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'listening', 'listening_choice', 'Dengarkan penutup kuliah sosiologi. Apa implikasi utama dari fenomena ''pluralistic ignorance''?', '{"options":[{"id":"opt_1","text":"Mahasiswa enggan bertanya karena profesor melarang diskusi selama jam kuliah"},{"id":"opt_2","text":"Persamaan matematika yang diajarkan terlalu mudah bagi seluruh peserta kelas"},{"id":"opt_3","text":"Mahasiswa lebih suka menanyakan rumus melalui email seusai ujian akhir"},{"id":"opt_4","text":"Seluruh kelas diam tak bertanya karena tiap mahasiswa keliru mengira teman-teman lainnya sudah paham"}],"audio_text":"Ultimately, pluralistic ignorance explains why an entire classroom stays silent without asking questions—each student mistakenly assumes everyone else understood the equation."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Memahami definisi sebab-akibat inti di akhir kuliah sangat krusial untuk menjawab soal ''Main Takeaway'' TOEFL.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000088', 'e5100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat sintesis penutup kuliah sains berikut:', '{"romaji":"/ðiːz ˈɡleɪʃəl kɔːrz ʃɛd laɪt ɑːn ði ɪkˈstɛnt tə wɪtʃ ˈmɛθeɪn ækˈsɛləˌreɪtɪd ˈwɔːrmɪŋ/","tokens":["shed light on","methane accelerated warming.","These glacial cores","shedding lights to","which extent did","the extent to which"],"target_translation":"Inti es gletser ini memberikan titik terang mengenai sejauh mana metana mempercepat pemanasan."}'::jsonb, '["These glacial cores","shed light on","the extent to which","methane accelerated warming."]'::jsonb, NULL, NULL, 'Menggabungkan idiom ''shed light on'' dengan klausa formal ''the extent to which + S + V''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000089', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih susunan embedded clause yang tepat:', '{"options":["if or not","whether does","how does","how"],"translation":"Para ahli akustik kelautan sedang menyelidiki bagaimana sonar frekuensi rendah mengganggu navigasi paus balin.","sentence_template":"Marine acousticians are investigating [blank] low-frequency sonar disrupts baleen whale navigation."}'::jsonb, '{"selected":"how"}'::jsonb, NULL, NULL, 'Di dalam klausa objek ''investigating how...'', subjek ''low-frequency sonar'' langsung diikuti verba ''disrupts''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000090', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih kata kerja relasional yang tepat:', '{"options":["digresses into","rules out","owns up","hinges on"],"translation":"Di ekosistem gersang, perkecambahan biji sangat bergantung pada hujan deras musiman yang singkat alih-alih curah hujan stabil.","sentence_template":"In arid ecosystems, seed germination [blank] brief seasonal cloudbursts rather than steady rainfall."}'::jsonb, '{"selected":"hinges on"}'::jsonb, NULL, NULL, '''Hinges on'' menegaskan ketergantungan mutlak proses biologis pada pemicu tertentu.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000091', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'listening', 'listening_choice', 'Evaluasi Unit 3 — Dengarkan cuplikan kuliah astronomi TOEFL. Mengapa profesor menyisipkan cerita tentang kacamata berembun?', '{"options":[{"id":"opt_1","text":"Memakai pengalaman kondensasi sehari-hari untuk membantu mahasiswa memvisualisasikan pembentukan tetesan awan pada inti debu"},{"id":"opt_2","text":"Membuktikan bahwa kelembapan udara merusak instrumen optik modern"},{"id":"opt_3","text":"Mengingatkan mahasiswa untuk membersihkan lensa teleskop sebelum pengamatan malam"},{"id":"opt_4","text":"Menjelaskan perbedaan iklim tropis Jakarta dan gurun tempat observatorium berada"}],"audio_text":"Ever walk out of an air-conditioned room into humid Jakarta air and have your glasses fog up instantly? Well, atmospheric condensation around dust nuclei works on a remarkably similar principle."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Analogi pembuka profesor selalu bertujuan menjembatani fenomena abstrak ke pengalaman familier pendengar.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000092', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'writing', 'sentence_builder', 'Evaluasi Unit 3 — Susun kalimat rangkuman mekanisme biologi berikut:', '{"romaji":"/ˈælpaɪn plænts ɡroʊ ɪn dɛns ˈkʊʃənz ˌðɛrˈbaɪ ˈtræpɪŋ hiːt nɪr ðə sɔɪl ˈsɜːrfɪs/","tokens":["thereby trap","Alpine plants grow","thereby trapping heat","near the soil surface.","growing into cushion","in dense cushions,"],"target_translation":"Tanaman alpen tumbuh dalam rumpun bantalan padat, sehingga memerangkap panas di dekat permukaan tanah."}'::jsonb, '["Alpine plants grow","in dense cushions,","thereby trapping heat","near the soil surface."]'::jsonb, NULL, NULL, 'Partisip hasil '', thereby trapping heat'' merangkum adaptasi dan manfaatnya secara presisi.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000093', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'speaking', 'speaking_repeat', 'Evaluasi Unit 3 — Ucapkan kalimat pembuka rangkuman kuliah TOEFL berikut:', '{"romaji":"/ðə ˈlɛktʃər ʃɛdz laɪt ɑːn haʊ ˈmaɪɡrəˌtɔːri bɜːrdz dɪˈtɛkt ɜːrθs mæɡˈnɛtɪk fiːld/","display_text":"The lecture sheds light on how migratory birds detect Earth''s magnetic field.","phonetic_breakdown":["The lecture","sheds light on","how migratory birds","detect Earth''s magnetic field."]}'::jsonb, '{"expected_transcript":"The lecture sheds light on how migratory birds detect Earth''s magnetic field."}'::jsonb, NULL, NULL, 'Lafalkan ''migratory'' ala Amerika /ˈmaɪɡrəˌtɔːri/ (empat suku kata dengan vokal kedua pada -tory).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000094', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih kata penghubung sesudah preposisi yang benar:', '{"options":["does","whether","if","that"],"translation":"Penelaah sejawat mengevaluasi metodologi secara ketat, terlepas dari apakah hipotesis tersebut sejalan dengan konsensus arus utama.","sentence_template":"Peer reviewers evaluate methodology strictly, irrespective of [blank] the hypothesis aligns with mainstream consensus."}'::jsonb, '{"selected":"whether"}'::jsonb, NULL, NULL, 'Sesudah preposisi majemuk ''irrespective of'', wajib menggunakan ''whether'' (bukan ''if'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000095', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'listening', 'listening_choice', 'Evaluasi Unit 3 — Dengarkan profesor merangkum eksperimen ekonomi perilaku. Mengapa hasilnya disebut ''counterintuitive''?', '{"options":[{"id":"opt_1","text":"Harga enam rasa selai didiskon hingga separuh harga normal"},{"id":"opt_2","text":"Menyediakan pilihan jauh lebih banyak justru menurunkan jumlah pembelian akibat kelumpuhan mengambil keputusan"},{"id":"opt_3","text":"Kualitas selai pada meja besar lebih rendah daripada meja kecil"},{"id":"opt_4","text":"Pembeli selalu lebih menyukai toko yang memajang dua puluh empat rasa selai"}],"audio_text":"Counterintuitively, offering shoppers twenty-four jam varieties generated far fewer purchases than displaying just six—choice overload paralyzed decision-making."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Eksperimen klasik *choice overload* ini ''counterintuitive'' karena lebih banyak opsi ternyata menghasilkan lebih sedikit transaksi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000096', 'e5100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000033', 'writing', 'sentence_builder', 'Evaluasi Unit 3 — Susun kalimat bukti riset independen berikut:', '{"romaji":"/ˌreɪdioʊˈkɑːrbən ˈdeɪtɪŋ kəˈrɑːbəˌreɪtɪd ðə ˈtaɪmˌlaɪn prəˈpoʊzd baɪ ɪnˈdɪdʒənəs ˈɔːrəl ˈhɪstəriz/","tokens":["corroborates into","corroborated the timeline","proposed by","Radiocarbon dating","indigenous oral histories.","proposing from"],"target_translation":"Penanggalan radiokarbon menguatkan linimasa yang diajukan oleh sejarah lisan masyarakat adat."}'::jsonb, '["Radiocarbon dating","corroborated the timeline","proposed by","indigenous oral histories."]'::jsonb, NULL, NULL, 'Subjek + ''corroborated the timeline'' + reduced relative clause ''proposed by...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000097', 'e5100001-0000-4000-8000-000000000013', NULL, 'reading', 'fill_blank', 'Lengkapi pembuka sanggahan diplomatis dalam rapat strategi berikut:', '{"options":["jump the gun on","see the merit in","fall short of","turn a blind eye"],"translation":"Meskipun saya mengakui sisi positif ekspansi ke tiga pasar baru sekaligus, tim layanan kita saat ini sudah kewalahan.","sentence_template":"While I [blank] expanding into three new markets simultaneously, our support team is already stretched thin."}'::jsonb, '{"selected":"see the merit in"}'::jsonb, NULL, NULL, '''See the merit in + V-ing/Noun'' membuka ketidaksetujuan secara konstruktif dan menghargai lawan bicara.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000098', 'e5100001-0000-4000-8000-000000000013', NULL, 'reading', 'fill_blank', 'Pilih kata benda akademik yang merujuk pada ''catatan batasan penting'':', '{"options":["milestone","incentive","caveat","consensus"],"translation":"Hasil survei tampak menjanjikan, dengan satu catatan batasan besar: sembilan puluh persen responden berasal dari pusat teknologi perkotaan.","sentence_template":"The survey results look promising, with one major [blank]: ninety percent of respondents came from urban tech hubs."}'::jsonb, '{"selected":"caveat"}'::jsonb, NULL, NULL, '''Caveat'' menandai pengecualian atau keterbatasan metodologis yang tidak boleh diabaikan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000099', 'e5100001-0000-4000-8000-000000000013', NULL, 'listening', 'listening_choice', 'Dengarkan intervensi seorang arsitek perangkat lunak di rapat. Apa maksud pembicara menyebut ''play devil''s advocate''?', '{"options":[{"id":"opt_1","text":"Ia sengaja mengajukan skenario terburuk guna menguji ketahanan desain sebelum disepakati"},{"id":"opt_2","text":"Ia meminta rapat segera diakhiri tanpa keputusan teknis"},{"id":"opt_3","text":"Ia memastikan bahwa penyimpanan lokal sama sekali bebas risiko"},{"id":"opt_4","text":"Ia menolak bekerja sama dengan tim infrastruktur regional"}],"audio_text":"Just to play devil''s advocate for a second—if we store session state locally, how will the app behave during regional failover?"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Play devil''s advocate'' memberi sinyal bahwa pertanyaan kritis diajukan demi menguji kualitas solusi, bukan menyerang pembuat usulan.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000100', 'e5100001-0000-4000-8000-000000000013', NULL, 'writing', 'sentence_builder', 'Susun kalimat sanggahan akademik bergaya TOEFL Writing Task 2:', '{"romaji":"/waɪl klɛr ˈreɪzɪz ə ˈvælɪd pɔɪnt hɜːr prəˈpoʊzəl ˌoʊvərˈlʊks lɔːŋ tɜːrm ˈmeɪntənəns kɔːsts/","tokens":["While Claire raises","overlooking into","her proposal overlooks","a valid point,","validly points","long-term maintenance costs."],"target_translation":"Meskipun Claire mengangkat poin yang masuk akal, usulannya melewatkan biaya pemeliharaan jangka panjang."}'::jsonb, '["While Claire raises","a valid point,","her proposal overlooks","long-term maintenance costs."]'::jsonb, NULL, NULL, 'Template emas TOEFL Academic Discussion: ''While [Name] raises a valid point, his/her proposal overlooks [X]''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000101', 'e5100001-0000-4000-8000-000000000013', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat sanggahan rapat yang sopan dan persuasif berikut:', '{"romaji":"/ˈɡræntɪd spiːd ˈmætərz jɛt ˈʃɪpɪŋ ʌnˈtɛstɪd koʊd rɪsks ˈkʌstəmər trʌst/","display_text":"Granted, speed matters, yet shipping untested code risks customer trust.","phonetic_breakdown":["Granted, speed matters,","yet shipping untested code","risks customer trust."]}'::jsonb, '{"expected_transcript":"Granted, speed matters, yet shipping untested code risks customer trust."}'::jsonb, NULL, NULL, 'Beri penekanan konsesi pada ''GRAN-ted,'' jeda singkat, lalu tekankan kontras pada ''YET shipping UN-tested code''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000102', 'e5100001-0000-4000-8000-000000000013', NULL, 'reading', 'fill_blank', 'Pilih kata hubung ringkas yang tepat sebelum frasa sifat ''at a higher upfront cost'':', '{"options":["despite of","albeit","whereas","unless"],"translation":"Mikrogrid surya menawarkan listrik pedesaan yang andal, meskipun dengan biaya pemasangan awal yang lebih tinggi.","sentence_template":"Solar microgrids offer reliable rural electricity, [blank] at a higher upfront installation cost."}'::jsonb, '{"selected":"albeit"}'::jsonb, NULL, NULL, '''Albeit'' dapat langsung diikuti frasa preposisi/adjektiva tanpa memerlukan subjek dan kata kerja baru.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000103', 'e5100001-0000-4000-8000-000000000013', NULL, 'listening', 'listening_choice', 'Dengarkan respons manajer produk terhadap usulan tenggat waktu CEO. Bagaimana sikap manajer tersebut?', '{"options":[{"id":"opt_1","text":"Ia setuju menghapus seluruh tahapan uji keamanan demi mengejar pameran"},{"id":"opt_2","text":"Ia memahami urgensi acara pameran, namun menolak pemangkasan uji keamanan karena risiko sanksi kepatuhan"},{"id":"opt_3","text":"Ia menyarankan perusahaan membatalkan keikutsertaan di pameran dagang"},{"id":"opt_4","text":"Ia mengklaim regulasi keamanan tidak berlaku selama masa promosi"}],"audio_text":"I completely understand the urgency ahead of the trade show; that said, trimming security QA could expose us to compliance penalties."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Penanda transisi ''that said'' (meski demikian) mengalihkan pengakuan empati ke keberatan substantif secara elegan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000104', 'e5100001-0000-4000-8000-000000000013', NULL, 'writing', 'sentence_builder', 'Susun kalimat konsesi dengan penanda ''That said'' berikut:', '{"romaji":"/ˌɔːtəˈmeɪʃən seɪvz ˈleɪbər ðæt sɛd ˈhjuːmən ˈoʊvərˌsaɪt rɪˈmeɪnz ˌɪndɪˈspɛnsəbəl/","tokens":["that said, human oversight","saying that","remains indispensable","for edge cases.","indispensably to","Automation saves labor;"],"target_translation":"Otomatisasi menghemat tenaga kerja; meski demikian, pengawasan manusia tetap mutlak diperlukan untuk kasus batas."}'::jsonb, '["Automation saves labor;","that said, human oversight","remains indispensable","for edge cases."]'::jsonb, NULL, NULL, 'Titik koma + ''that said,'' menghubungkan pengakuan manfaat dengan batasan realistisnya.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000105', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Pilih bentuk saran persuasif paling diplomatis untuk rapat lintas negara:', '{"options":["Don''t it be","Why you don''t be","Wouldn''t it be","Isn''t it must be"],"translation":"Bukankah akan lebih hemat biaya menyewa server lokal terlebih dahulu sebelum membangun pusat data milik kita sendiri?","sentence_template":"[blank] more cost-effective to lease local servers before building our own data center?"}'::jsonb, '{"selected":"Wouldn''t it be"}'::jsonb, NULL, NULL, '''Wouldn''t it be + comparative adjective + to V1?'' adalah pola standar persuasi sopan berbahasa Inggris Amerika.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000106', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat sanggahan hipotetis dengan pola ''were to'' yang tepat:', '{"options":["has to been","will to","were to","would to"],"translation":"Bahkan seandainya komite menyetujui dana tambahan besok sekalipun, waktu tunggu pengadaan alat lab melebihi empat bulan.","sentence_template":"Even if the committee [blank] approve extra funding tomorrow, laboratory equipment lead times exceed four months."}'::jsonb, '{"selected":"were to"}'::jsonb, NULL, NULL, 'Pada klausa pengandaian formal ''Even if + Subject + were to + V1'', ''were to'' dipakai untuk semua subjek tunggal maupun jamak.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000107', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'listening', 'listening_choice', 'Dengarkan komentar pemimpin tim kepada desainer produk. Apa maksud sebenarnya dari ''we might want to simplify step three''?', '{"options":[{"id":"opt_1","text":"Meminta desainer menyederhanakan langkah ketiga secara sopan agar pengguna baru tidak berhenti di tengah proses"},{"id":"opt_2","text":"Memuji langkah ketiga sebagai bagian terbaik yang tidak boleh diubah"},{"id":"opt_3","text":"Meminta seluruh desain ulang dibatalkan karena terlalu rumit"},{"id":"opt_4","text":"Menyatakan bahwa penyederhanaan langkah ketiga sama sekali tidak penting"}],"audio_text":"The visual hierarchy looks super clean overall—though we might want to simplify step three so first-time users don''t drop off."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Dalam pragmatik kerja Amerika, ''we might want to + V1'' berfungsi sebagai arahan perbaikan yang dibungkus kesopanan kolaboratif.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000108', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat opini akademik formal pengganti ''I think'':', '{"romaji":"/ˈlʊkɪŋ æt ðə ˈdeɪtə aɪ wʊd ˈɑːrɡjuː ðæt prɪˈvɛntɪv ˈsʌbsədiz ˌaʊtpərˈfɔːrm ɪˈmɜːrdʒənsi ˈbeɪlaʊts/","tokens":["outperform emergency bailouts.","outperformed to","I would argue that","arguing would I","Looking at the data,","preventive subsidies"],"target_translation":"Melihat data yang ada, saya berargumen bahwa subsidi pencegahan mengungguli dana talangan darurat."}'::jsonb, '["Looking at the data,","I would argue that","preventive subsidies","outperform emergency bailouts."]'::jsonb, NULL, NULL, '''I would argue that + Clause'' meningkatkan wibawa akademik pada esai TOEFL maupun diskusi kebijakan.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000109', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'speaking', 'speaking_repeat', 'Tirukan intonasi pertanyaan negatif persuasif berikut dengan ramah:', '{"romaji":"/ˈwʊdənt ɪt meɪk mɔːr sɛns tə ˈbɛntʃˌmɑːrk ɪɡˈzɪstɪŋ tuːlz bɪˈfɔːr ˈbɪldɪŋ ˈaʊər oʊn/","display_text":"Wouldn''t it make more sense to benchmark existing tools before building our own?","phonetic_breakdown":["Wouldn''t it make","more sense","to benchmark existing tools","before building our own?"]}'::jsonb, '{"expected_transcript":"Wouldn''t it make more sense to benchmark existing tools before building our own?"}'::jsonb, NULL, NULL, 'Gunakan nada terbuka dan ingin tahu pada akhir kalimat agar terdengar kolaboratif, bukan menyindir.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000110', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Pilih ungkapan pelembut untuk mengoreksi asumsi angka di rapat:', '{"options":["shall been","will to","must to","could"],"translation":"Jika boleh saya menyela sebentar, slide pendapatan Q2 tersebut belum memasukkan perpanjangan kontrak korporat berulang.","sentence_template":"If I [blank] jump in briefly, the Q2 revenue slide excludes recurring enterprise renewals."}'::jsonb, '{"selected":"could"}'::jsonb, NULL, NULL, '''If I could jump in briefly'' atau ''If I may add'' adalah cara paling sopan mengambil giliran bicara di rapat Amerika.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000111', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'listening', 'listening_choice', 'Dengarkan diskusi kebijakan kampus pada TOEFL Listening. Mengapa pembicara meragukan rencana parkir sepeda baru?', '{"options":[{"id":"opt_1","text":"Penambahan rak sepeda tidak akan efektif selama jalur sepeda yang aman terlindung di Oak Avenue belum tersedia"},{"id":"opt_2","text":"Kampus sudah memiliki terlalu banyak jalur sepeda terlindung di Oak Avenue"},{"id":"opt_3","text":"Dua ratus rak sepeda sudah cukup menyelesaikan seluruh masalah transportasi"},{"id":"opt_4","text":"Mahasiswa lebih memilih membeli tiket parkir mobil tahunan yang mahal"}],"audio_text":"Even if the university were to install two hundred extra bike racks, students still wouldn''t cycle without protected lane barriers on Oak Avenue."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Even if X were to..., Y still wouldn''t...'' menunjukkan bahwa usulan X gagal menyentuh akar masalah sesungguhnya.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000112', 'e5100001-0000-4000-8000-000000000014', 'e2000001-0000-4000-8000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat saran sopan kepada pemangku kepentingan:', '{"romaji":"/ˈɡɪvən ðə taɪt ˈdɛdˌlaɪn wi maɪt wɑːnt tə diːˈskoʊp ˈkʌstəm ˌænəˈmeɪʃənz fɔːr ˈvɜːrʒən wʌn/","tokens":["wanting might we","Given the tight deadline,","for version one.","descoped into","we might want to","descope custom animations"],"target_translation":"Mengingat tenggat waktu yang ketat, sebaiknya kita mengeluarkan animasi kustom dari cakupan versi pertama."}'::jsonb, '["Given the tight deadline,","we might want to","descope custom animations","for version one."]'::jsonb, NULL, NULL, '''Given + Noun Phrase, we might want to + V1'' menggabungkan alasan objektif dengan saran diplomatis.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000113', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Pilih kolokasi yang tepat untuk mengembangkan pendapat peserta rapat sebelumnya:', '{"options":["Phasing out","Cutting back","Ruling out","Building on"],"translation":"Mengembangkan pengamatan Nadia terkait kerapuhan rantai pasok, mendiversifikasi pabrik perakitan lokal juga akan menurunkan tarif bea.","sentence_template":"[blank] Nadia''s observation regarding supply-chain fragility, diversifying local assembly plants would also lower tariffs."}'::jsonb, '{"selected":"Building on"}'::jsonb, NULL, NULL, '''Building on [someone]''s point/observation'' menunjukkan kolaborasi intelektual aktif dalam seminar.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000114', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat solusi kebijakan publik berikut:', '{"options":["turn down between","strike a balance between","zero in from","play devil''s advocate on"],"translation":"Pemerintah kota harus mencapai keseimbangan antara melestarikan kawasan bersejarah dan memperluas hunian terjangkau.","sentence_template":"Municipalities must [blank] preserving historic neighborhoods and expanding affordable housing."}'::jsonb, '{"selected":"strike a balance between"}'::jsonb, NULL, NULL, '''Strike a balance between A and B'' merupakan kolokasi baku untuk menyintesis dua prioritas penting.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000115', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'listening', 'listening_choice', 'Dengarkan kontribusi mahasiswa dalam seminar kebijakan energi. Bagaimana posisi mahasiswa ini terhadap pendapat David?', '{"options":[{"id":"opt_1","text":"Ia berpendapat baterai natrium-ion justru meningkatkan ketergantungan mineral"},{"id":"opt_2","text":"Ia menyetujui pandangan David soal penyimpanan jaringan listrik sekaligus menambahkan keunggulan baterai natrium-ion"},{"id":"opt_3","text":"Ia meminta profesor mengganti topik diskusi ke bahan bakar fosil"},{"id":"opt_4","text":"Ia menolak seluruh argumen David tentang penyimpanan energi terbarukan"}],"audio_text":"I''d like to echo David''s sentiment on grid storage, and add that sodium-ion batteries could cut mineral dependency in half."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Echo [someone]''s sentiment, and add that...'' menyatakan persetujuan penuh yang diperkaya bukti baru.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000116', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat evaluasi keputusan strategis berikut:', '{"romaji":"/ˈæftər ˈweɪɪŋ ðə proʊz ænd kɑːnz ðə bɔːrd ˈɑːptɪd fɔːr ə feɪzd ˈriːdʒənəl ˈroʊlaʊt/","tokens":["weighed into","After weighing","the pros and cons,","a phased regional rollout.","the board opted for","opting of"],"target_translation":"Setelah menimbang untung ruginya, dewan direksi memilih peluncuran regional secara bertahap."}'::jsonb, '["After weighing","the pros and cons,","the board opted for","a phased regional rollout."]'::jsonb, NULL, NULL, 'Preposisi ''After + V-ing'' diikuti klausa utama dengan verba formal ''opted for'' (memilih).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000117', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'speaking', 'speaking_repeat', 'Ucapkan kalimat sintesis seminar akademik berikut dengan lancar:', '{"romaji":"/aɪ ˈɛkoʊ ˈsɛrəz kənˈsɜːrn jɛt wi mʌst straɪk ə ˈbæləns bɪˈtwiːn ˈpraɪvəsi ænd kənˈviːniəns/","display_text":"I echo Sarah''s concern, yet we must strike a balance between privacy and convenience.","phonetic_breakdown":["I echo Sarah''s concern,","yet we must","strike a balance","between privacy and convenience."]}'::jsonb, '{"expected_transcript":"I echo Sarah''s concern, yet we must strike a balance between privacy and convenience."}'::jsonb, NULL, NULL, 'Lafalkan ''privacy'' dengan diftong Amerika /ˈpraɪvəsi/ (bukan /ˈprɪvəsi/ ala Inggris).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000118', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Pilih ungkapan formal untuk menyatakan kesepahaman terhadap kekhawatiran rekan:', '{"options":["overhauled","corroborated into","echoed","factored out"],"translation":"Beberapa ketua jurusan menyuarakan kekhawatiran serupa dengan dekan terkait menurunnya pendaftaran bidang humaniora.","sentence_template":"Several department chairs [blank] the dean''s concern about declining humanities enrollment."}'::jsonb, '{"selected":"echoed"}'::jsonb, NULL, NULL, '''Echo a concern / sentiment'' berarti menyatakan dukungan atau pandangan yang seirama.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000119', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'listening', 'listening_choice', 'Dengarkan kesimpulan moderator rapat lintas tim. Apa langkah konkret yang disepakati?', '{"options":[{"id":"opt_1","text":"Merilis fitur ekspor keuangan hari Jumat tanpa persetujuan tim hukum"},{"id":"opt_2","text":"Menghapus dasbor inti dan hanya berfokus pada dokumen hukum"},{"id":"opt_3","text":"Merilis dasbor inti hari Jumat, namun menahan fitur ekspor keuangan sampai tim hukum memberi persetujuan resmi"},{"id":"opt_4","text":"Menunda seluruh fitur dasbor tanpa batas waktu yang jelas"}],"audio_text":"Since both speed and auditability matter here, let''s strike a compromise: ship the core dashboard Friday, and hold financial exports until legal signs off."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Strike a compromise'' diikuti pembagian rilis dua tahap yang mengakomodasi kecepatan sekaligus kepatuhan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000120', 'e5100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat pembuka esai TOEFL Academic Discussion berikut:', '{"romaji":"/ˈbɪldɪŋ ɑːn ˈkɛvənz pɔɪnt aɪ wʊd ˈɑːrɡjuː ðæt rɪˈmoʊt ˈɪntɜːrnˌʃɪps ˈbrɔːdən ˈæksɛs/","tokens":["Built into Kevin","remote internships broaden","access for rural students.","Building on Kevin''s point,","I would argue that","broadening to"],"target_translation":"Mengembangkan poin Kevin, saya berargumen bahwa magang jarak jauh memperluas akses bagi mahasiswa daerah."}'::jsonb, '["Building on Kevin''s point,","I would argue that","remote internships broaden","access for rural students."]'::jsonb, NULL, NULL, 'Memadukan partisip kohesif ''Building on X'' dengan klausa argumen terpelajar ''I would argue that...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000121', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Pilih pembuka konsesi yang tepat:', '{"options":["Because","Despite","While","Albeit of"],"translation":"Meskipun saya melihat sisi baik penyeragaman satu templat global, undang-undang pajak regional menuntut kolom yang disesuaikan secara lokal.","sentence_template":"[blank] I see the merit in standardizing one global template, regional tax laws require localized fields."}'::jsonb, '{"selected":"While"}'::jsonb, NULL, NULL, '''While + Subject + Verb'' membuka klausa konsesi lengkap, berbeda dari ''Despite'' yang hanya diikuti frasa nomina.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000122', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Pilih struktur pengandaian sanggahan yang tepat:', '{"options":["would to","has","will","were to"],"translation":"Bahkan seandainya pemerintah kota menggratiskan bus pusat kota sekalipun, komuter tetap akan menyetir kecuali frekuensi keberangkatan ditingkatkan.","sentence_template":"Even if the city [blank] make downtown buses free, commuters would still drive unless frequency improves."}'::jsonb, '{"selected":"were to"}'::jsonb, NULL, NULL, '''Even if + Subject + were to + V1'' dipakai untuk menguji skenario hipotetis secara formal.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000123', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'listening', 'listening_choice', 'Evaluasi Unit 4 — Dengarkan respons seorang Tech Lead di rapat perencanaan. Apa pesan intinya?', '{"options":[{"id":"opt_1","text":"Menolak keterlibatan dalam proyek migrasi basis data kuartal ini"},{"id":"opt_2","text":"Mengusulkan pencatatan ganda selama seminggu karena jauh lebih aman daripada memindahkan basis data sekaligus secara mendadak"},{"id":"opt_3","text":"Meminta tim segera mematikan basis data lama hari ini tanpa cadangan"},{"id":"opt_4","text":"Menghapus data transaksi selama satu minggu penuh"}],"audio_text":"Let me play devil''s advocate—wouldn''t it be safer to run dual writes for a week rather than cutting over the database cold turkey?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Memadukan ''play devil''s advocate'', pertanyaan negatif sopan ''wouldn''t it be safer to...'', dan kontras idiom ''cold turkey'' (seketika tanpa transisi).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000124', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'writing', 'sentence_builder', 'Evaluasi Unit 4 — Susun kalimat batasan argumen dengan ''albeit'':', '{"romaji":"/ðə ˈpaɪlət ˈproʊɡræm rɪˈduːst ɪˈmɪʃənz ɔːlˈbiːɪt ɑːn ə ˈsmɔːlər skeɪl ðæn prəˈdʒɛktɪd/","tokens":["projecting scale","whereas on","albeit on a smaller","scale than projected.","reduced emissions,","The pilot program"],"target_translation":"Program percontohan tersebut menurunkan emisi, meskipun pada skala yang lebih kecil daripada yang diproyeksikan."}'::jsonb, '["The pilot program","reduced emissions,","albeit on a smaller","scale than projected."]'::jsonb, NULL, NULL, '''Albeit'' diikuti langsung frasa preposisi ''on a smaller scale than projected'' secara ringkas.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000125', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'speaking', 'speaking_repeat', 'Evaluasi Unit 4 — Ucapkan kalimat pembuka sanggahan diplomatis berikut:', '{"romaji":"/waɪl ɛˈleɪnə ˈreɪzɪz ə ˈvælɪd pɔɪnt hɜːr prəˈpoʊzəl ˌoʊvərˈlʊks ˈrʊrəl ˌkɑːnɛkˈtɪvəti ɡæps/","display_text":"While Elena raises a valid point, her proposal overlooks rural connectivity gaps.","phonetic_breakdown":["While Elena raises","a valid point,","her proposal overlooks","rural connectivity gaps."]}'::jsonb, '{"expected_transcript":"While Elena raises a valid point, her proposal overlooks rural connectivity gaps."}'::jsonb, NULL, NULL, 'Pastikan transisi nada turun-naik pada ''valid point,'' diikuti penekanan jelas pada ''OVERLOOKS''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000126', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Lengkapi kalimat arahan halus manajerial berikut:', '{"options":["would to","might want to","ought verify","might wanting"],"translation":"Sebelum mengirim materi presentasi kepada dewan direksi, sebaiknya kita memastikan setiap grafik memakai angka Q4 yang telah diaudit.","sentence_template":"Before sending the deck to the board, we [blank] verify that every chart uses audited Q4 figures."}'::jsonb, '{"selected":"might want to"}'::jsonb, NULL, NULL, '''Might want to + V1'' adalah bentuk saran halus profesional standar Amerika.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000127', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'listening', 'listening_choice', 'Evaluasi Unit 4 — Dengarkan diskusi akademik kampus. Apa catatan peringatan (''caveat'') yang disampaikan pembicara?', '{"options":[{"id":"opt_1","text":"Sistem pengawasan daring telah terbukti sempurna tanpa bias pencahayaan"},{"id":"opt_2","text":"Ujian jarak jauh selalu membutuhkan biaya sewa gedung yang lebih mahal"},{"id":"opt_3","text":"Algoritma kamera pengawas cenderung tidak adil menandai mahasiswa yang berada di ruangan berpencahayaan redup"},{"id":"opt_4","text":"Seluruh mahasiswa diwajibkan membeli lampu studio profesional"}],"audio_text":"Remote proctoring lowers exam logistics costs; that said, one crucial caveat is how unevenly webcam algorithms flag students in dim lighting."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''That said, one crucial caveat is...'' menyoroti kelemahan keadilan teknis dari solusi sebelumnya.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000128', 'e5100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000034', 'writing', 'sentence_builder', 'Evaluasi Unit 4 — Susun kalimat penutup rapat yang seimbang:', '{"romaji":"/ˈaʊər ˈpɑːləsi mʌst straɪk ə ˈbæləns bɪˈtwiːn ˈræpɪd ɪkˌspɛrəmɛnˈteɪʃən ænd strɪkt ˈdeɪtə ˈpraɪvəsi/","tokens":["between rapid experimentation","strike a balance","and strict data privacy.","strictly privacies","striking balances to","Our policy must"],"target_translation":"Kebijakan kita harus mencapai keseimbangan antara eksperimen cepat dan privasi data yang ketat."}'::jsonb, '["Our policy must","strike a balance","between rapid experimentation","and strict data privacy."]'::jsonb, NULL, NULL, '''Strike a balance between [A] and [B]'' menyatukan dua tuntutan organisasi secara presisi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000129', 'e5100001-0000-4000-8000-000000000017', NULL, 'reading', 'fill_blank', 'Pilih kata kerja kolokasi yang baku untuk ''technical debt'' dalam dokumen RFC:', '{"options":["invent","digress","comply","incur"],"translation":"Merilis tanpa penomoran halaman basis data akan menimbulkan utang teknis berat begitu klien korporat masuk.","sentence_template":"Shipping without database pagination will [blank] heavy technical debt once enterprise tenants onboard."}'::jsonb, '{"selected":"incur"}'::jsonb, NULL, NULL, '''Incur debt / costs / penalties'' adalah kolokasi formal standar dalam bahasa Inggris bisnis dan rekayasa.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000130', 'e5100001-0000-4000-8000-000000000017', NULL, 'reading', 'fill_blank', 'Pilih istilah arsitektur yang merujuk pada komponen tunggal pelumpuh sistem:', '{"options":["single point of failure","key takeaway","rule of thumb","silver lining"],"translation":"Menjalankan basis data utama tanpa pengalihan cadangan otomatis menciptakan satu titik kegagalan yang berbahaya.","sentence_template":"Deploying a primary database without automated read-replica failover creates a dangerous [blank]."}'::jsonb, '{"selected":"single point of failure"}'::jsonb, NULL, NULL, '''Single point of failure'' (SPOF) berarti komponen yang jika tumbang langsung menghentikan seluruh layanan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000131', 'e5100001-0000-4000-8000-000000000017', NULL, 'listening', 'listening_choice', 'Dengarkan komentar senior engineer pada sesi tinjauan arsitektur. Mengapa ia memberi label ''nit'' pada sarannya?', '{"options":[{"id":"opt_1","text":"Baris delapan puluh menyebabkan kebocoran memori pada server produksi"},{"id":"opt_2","text":"Ia menolak menyetujui Pull Request sampai arsitektur basis data diganti"},{"id":"opt_3","text":"Logika konkurensi mengandung bug fatal yang wajib ditulis ulang dari nol"},{"id":"opt_4","text":"Perubahan nama variabel bersifat minor demi keterbacaan sehingga tidak perlu menghambat persetujuan substansi logika utama"}],"audio_text":"Overall the concurrency logic is rock solid—just one tiny nit on line eighty: renaming ''val'' to ''retryIntervalMs'' would clarify units for future readers."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Label ''nit'' (nitpick) memisahkan saran kerapian minor dari masalah pemblokir (*blocking issues*) agar kolaborasi lintas zona waktu tetap cepat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000132', 'e5100001-0000-4000-8000-000000000017', NULL, 'writing', 'sentence_builder', 'Susun kalimat evaluasi kompromi arsitektur berikut:', '{"romaji":"/ˈtʃuːzɪŋ ɪˈvɛntʃuəl kənˈsɪstənsi wʌz ə dɪˈlɪbərət ˈtreɪdˌɔːf tə ˈmɪnəˌmaɪz/","tokens":["minimized for","trading off into","Choosing eventual consistency","cross-region write latency.","to minimize","was a deliberate trade-off"],"target_translation":"Memilih konsistensi bertahap merupakan kompromi arsitektur yang disengaja demi meminimalkan latensi tulis lintas wilayah."}'::jsonb, '["Choosing eventual consistency","was a deliberate trade-off","to minimize","cross-region write latency."]'::jsonb, NULL, NULL, 'Subjek gerund ''Choosing eventual consistency'' menjelaskan alasan teknis di balik sebuah ''deliberate trade-off''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000133', 'e5100001-0000-4000-8000-000000000017', NULL, 'speaking', 'speaking_repeat', 'Ucapkan saran Code Review konstruktif dan impersonal berikut:', '{"romaji":"/ɪkˈstræktɪŋ ðɪs ˌvæləˈdeɪʃən ˈlɑːdʒɪk ˈɪntuː ˈmɪdəlˌwɛr wʊd prɪˈvɛnt ˈduːplɪkət tʃɛks/","display_text":"Extracting this validation logic into middleware would prevent duplicate checks.","phonetic_breakdown":["Extracting this","validation logic","into middleware","would prevent duplicate checks."]}'::jsonb, '{"expected_transcript":"Extracting this validation logic into middleware would prevent duplicate checks."}'::jsonb, NULL, NULL, 'Perhatikan pelafalan kata sifat ''duplicate'' sebagai /ˈduːplɪkət/ (vokal schwa di suku kata akhir, berbeda dari verba /ˈduːplɪkeɪt/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000134', 'e5100001-0000-4000-8000-000000000017', NULL, 'reading', 'fill_blank', 'Pilih frasa kerja yang bermakna ''mengurangi / melunasi utang teknis secara bertahap'':', '{"options":["rule out","push back","pan out","pay down"],"translation":"Pimpinan rekayasa mengalokasikan dua puluh persen dari setiap sprint untuk mencicil pelunasan utang teknis lawas.","sentence_template":"Engineering leadership allocated twenty percent of every sprint to [blank] legacy technical debt."}'::jsonb, '{"selected":"pay down"}'::jsonb, NULL, NULL, 'Analogi finansial ''pay down debt'' dipakai secara identik pada ''pay down technical debt''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000135', 'e5100001-0000-4000-8000-000000000017', NULL, 'listening', 'listening_choice', 'Dengarkan diskusi desain sistem antara dua arsitek. Mengapa mereka memilih antrean asinkron (message queue)?', '{"options":[{"id":"opt_1","text":"Meminta pengguna mengunggah dokumen pajak secara manual lewat pos"},{"id":"opt_2","text":"Memisahkan proses pembuatan PDF lewat antrean pesan menjaga API utama tetap responsif saat terjadi lonjakan trafik"},{"id":"opt_3","text":"Menghapus fitur unduh PDF sepenuhnya selama musim pelaporan pajak"},{"id":"opt_4","text":"Menggabungkan server PDF langsung ke dalam utas API utama"}],"audio_text":"If third-party PDF generation spikes during tax season, decoupling it via a message queue keeps our main API responsive."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Decoupling it via a message queue keeps [Object] + [Adjective]'' adalah pola penjelasan desain sistem tingkat lanjut.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000136', 'e5100001-0000-4000-8000-000000000017', NULL, 'writing', 'sentence_builder', 'Susun kalimat otomatisasi CI/CD dengan struktur kausatif ''have'':', '{"romaji":"/lɛts hæv ðə ˈlɪntər flæɡ ʌnˈjuːzd ˈɪmpɔːrts ˌɔːtəˈmætɪkli bɪˈfɔːr koʊd rɪˈvjuː bɪˈɡɪnz/","tokens":["flagging into","code review begins.","Let''s have the linter","automatically before","to flag by","flag unused imports"],"target_translation":"Mari atur agar linter menandai impor tak terpakai secara otomatis sebelum tinjauan kode dimulai."}'::jsonb, '["Let''s have the linter","flag unused imports","automatically before","code review begins."]'::jsonb, NULL, NULL, 'Kausatif aktif ''have + [agent/tool] + V1 bare infinitive'' (''have the linter flag'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000137', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Pilih bentuk kata kerja kausatif aktif sesudah ''had the gateway'':', '{"options":["to reroute","rerouting to","reroute","rerouted by"],"translation":"Untuk mengisolasi layanan mikro yang bermasalah, insinyur SRE jaga kami mengatur gerbang API agar mengalihkan trafik ke klaster cadangan.","sentence_template":"To isolate the faulty microservice, our SRE on call had the API gateway [blank] traffic to the backup cluster."}'::jsonb, '{"selected":"reroute"}'::jsonb, NULL, NULL, 'Struktur kausatif aktif ''have + Agent + bare infinitive (V1)'' memakai ''reroute'' tanpa ''to''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000138', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Pilih bentuk kata kerja kausatif pasif sesudah ''get all legacy tokens'':', '{"options":["revokes","revoke","to revoking","revoked"],"translation":"Sebelum mengaktifkan single sign-on, administrator wajib memastikan seluruh token sesi lawas dicabut.","sentence_template":"Before enabling single sign-on, administrators must get all legacy session tokens [blank]."}'::jsonb, '{"selected":"revoked"}'::jsonb, NULL, NULL, 'Karena ''legacy session tokens'' adalah objek yang dikenai tindakan pencabutan, gunakan V3 (''revoked'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000139', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'listening', 'listening_choice', 'Dengarkan penjelasan post-mortem insiden berikut. Bagaimana tim mencegah masalah serupa terulang?', '{"options":[{"id":"opt_1","text":"Mematikan sistem penagihan secara permanen bagi seluruh pelanggan"},{"id":"opt_2","text":"Mengganti seluruh basis kode situs dalam waktu semalam"},{"id":"opt_3","text":"Memasang pemutus sirkuit agar kelambatan API penagihan tidak merembet menjadi kelumpuhan situs menyeluruh"},{"id":"opt_4","text":"Membiarkan kegagalan layanan hilir menghentikan seluruh halaman utama"}],"audio_text":"We added circuit breakers to prevent a slow downstream billing API from cascading into a site-wide outage."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Prevent [A] from cascading into [B]'' menjelaskan mekanisme isolasi kegagalan (*fault isolation*) secara presisi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000140', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat pencegahan keamanan dengan pola ''prevent ... from V-ing'':', '{"romaji":"/pəˈræmətəˌraɪzd ˈkwɪriz prɪˈvɛnt əˈtækərz frʌm ɪnˈdʒɛktɪŋ ˈɑːrbəˌtrɛri ˌɛskjuːˈɛl/","tokens":["injecting arbitrary SQL","into user inputs.","Parameterized queries","to inject SQL","prevent attackers from","prevented into"],"target_translation":"Kueri berparameter mencegah penyerang menyuntikkan perintah SQL sembarang ke dalam masukan pengguna."}'::jsonb, '["Parameterized queries","prevent attackers from","injecting arbitrary SQL","into user inputs."]'::jsonb, NULL, NULL, 'Verba ''prevent + Object + from + V-ing'' wajib diikuti bentuk gerund (''injecting'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000141', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'speaking', 'speaking_repeat', 'Ucapkan kalimat spesifikasi keamanan RFC berikut dengan tegas:', '{"romaji":"/ˈsɛnsətɪv ˈpɜːrsənəli aɪˌdɛntəˈfaɪəbəl ˌɪnfərˈmeɪʃən mʌst bi rɪˈdæktɪd bɪˈfɔːr ˈlɔːɡɪŋ/","display_text":"Sensitive personally identifiable information must be redacted before logging.","phonetic_breakdown":["Sensitive personally","identifiable information","must be redacted","before logging."]}'::jsonb, '{"expected_transcript":"Sensitive personally identifiable information must be redacted before logging."}'::jsonb, NULL, NULL, 'Latih artikulasi istilah panjang ''personally identifiable information'' (PII) dengan tempo stabil.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000142', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Pilih bentuk kausatif ''get + Agent + to V1'' yang benar:', '{"options":["documenting of","to document","document","documented by"],"translation":"Pemimpin tim kami akhirnya berhasil meminta penyedia pembayaran eksternal mendokumentasikan kebijakan coba-ulang webhook mereka.","sentence_template":"Our team lead finally got the external payment provider [blank] their webhook retry policy."}'::jsonb, '{"selected":"to document"}'::jsonb, NULL, NULL, 'Berbeda dari ''have + Agent + V1'', kausatif persuasif ''get + Agent'' wajib diikuti ''to + V1'' (''to document'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000143', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'listening', 'listening_choice', 'Dengarkan pembaruan lintas zona waktu dari tim San Francisco ke tim Jakarta. Apa yang sudah diselesaikan?', '{"options":[{"id":"opt_1","text":"Tim Jakarta diminta membuat data uji anonim sendiri sebelum pulang"},{"id":"opt_2","text":"Basis data produksi tidak sengaja terhapus saat pergantian sif"},{"id":"opt_3","text":"Basis data staging sudah diisi data uji anonim sehingga tim Jakarta bisa langsung menguji filter pencarian"},{"id":"opt_4","text":"Pengujian filter pencarian ditunda hingga tim San Francisco bangun"}],"audio_text":"Hey Jakarta squad—before signing off, we had staging databases seeded with anonymized fixtures so you can test search filters right away."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Kausatif pasif ''we had staging databases seeded'' menyatakan kesiapan lingkungan kerja serah-terima (*handoff*).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000144', 'e5100001-0000-4000-8000-000000000018', 'e2000001-0000-4000-8000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat serah-terima lintas negara dengan kausatif pasif:', '{"romaji":"/pliːz ɡɛt ði ˌeɪpiːˈaɪ ˈskiːmə rɪˈvjuːd baɪ ˈmoʊbəl ˌɛndʒəˈnɪrz/","tokens":["locking the contract.","to review by","mobile engineers before","schema reviewed by","reviewing schema","Please get the API"],"target_translation":"Mohon pastikan skema API ditinjau oleh para insinyur mobile sebelum mengunci kontrak antarmuka."}'::jsonb, '["Please get the API","schema reviewed by","mobile engineers before","locking the contract."]'::jsonb, NULL, NULL, '''Get + [Target: the API schema] + [V3: reviewed] + by [Agent]'' adalah kalimat koordinasi lintas tim yang sangat alami.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000145', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat kuliah ilmu komputer tentang batas optimisasi berikut:', '{"options":["hindsight","single failures","devil''s advocates","diminishing returns"],"translation":"Menambahkan lebih banyak lapisan cache pada akhirnya mencapai titik hasil tambahan yang kian menyusut, ketika biaya sinkronisasi melampaui peningkatan kecepatan.","sentence_template":"Adding more cache layers eventually hits a point of [blank], where synchronization costs outweigh speed gains."}'::jsonb, '{"selected":"diminishing returns"}'::jsonb, NULL, NULL, '''Point of diminishing returns'' menggambarkan kondisi saat penambahan input tak lagi sebanding dengan output tambahan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000146', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Pilih struktur komparatif berpasangan (''semakin..., semakin...'') yang gramatikal:', '{"options":["fewer","the less of","the fewer","most few"],"translation":"Dalam tim terdistribusi, semakin banyak konteks yang Anda dokumentasikan secara asinkron, semakin sedikit rapat lanjutan yang dibutuhkan rekan Anda.","sentence_template":"In distributed teams, the more context you document asynchronously, [blank] follow-up meetings your colleagues need."}'::jsonb, '{"selected":"the fewer"}'::jsonb, NULL, NULL, 'Karena ''meetings'' adalah kata benda jamak dapat dihitung (*countable*), bentuk komparatif gandanya wajib memakai ''the fewer'' (bukan ''the less'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000147', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'listening', 'listening_choice', 'Dengarkan pesan suara serah-terima kerja dari Dublin ke Singapura. Apa tujuan utama pesan tersebut?', '{"options":[{"id":"opt_1","text":"Meminta tim Singapura berhenti mengerjakan fitur frontend minggu ini"},{"id":"opt_2","text":"Menyingkirkan hambatan bagi tim frontend Singapura agar mereka dapat langsung lanjut mengintegrasikan fitur pagi harinya"},{"id":"opt_3","text":"Mengabarkan bahwa repositori GraphQL dihapus karena gagal uji"},{"id":"opt_4","text":"Menjadwalkan panggilan video mendadak pada pukul dua dini hari"}],"audio_text":"I pushed the draft GraphQL resolver and left inline notes on the auth edge case so I can unblock your frontend integration first thing in your morning."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Unblock your frontend integration'' mencerminkan praktik kolaborasi asinkron lintas benua yang efektif.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000148', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat komparatif ganda tentang ukuran bundel aplikasi:', '{"romaji":"/ðə ˈsmɔːlər ðə ˈdʒɑːvəˌskrɪpt ˈbʌndəl rɪˈmeɪnz ðə ˈfæstər ˈmoʊbəl ˈpeɪdʒɪz ˈrɛndər/","tokens":["bundle remains,","render on slow networks.","rendering fastest","the faster mobile pages","The smaller the JavaScript","smaller JavaScript"],"target_translation":"Semakin kecil ukuran bundel JavaScript dijaga, semakin cepat halaman seluler tampil pada jaringan lambat."}'::jsonb, '["The smaller the JavaScript","bundle remains,","the faster mobile pages","render on slow networks."]'::jsonb, NULL, NULL, 'Pola ''The + comparative + S + V, the + comparative + S + V'' menghubungkan dua variabel performa secara presisi.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000149', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kuliah komputasi berikut dengan pengucapan istilah teknis yang mulus:', '{"romaji":"/ˌhoʊməˈmɔːrfɪk ɪnˈkrɪpʃən prəˈtɛkts klaʊd ˈpraɪvəsi bʌt ˌɪntrəˈduːsɪz stiːp ˌkɑːmpjəˈteɪʃənəl ˈoʊvərˌhɛd/","display_text":"Homomorphic encryption protects cloud privacy but introduces steep computational overhead.","phonetic_breakdown":["Homomorphic encryption","protects cloud privacy","but introduces steep","computational overhead."]}'::jsonb, '{"expected_transcript":"Homomorphic encryption protects cloud privacy but introduces steep computational overhead."}'::jsonb, NULL, NULL, 'Pastikan ''introduces'' dilafalkan ala Amerika /ˌɪntrəˈduːsɪz/ (tanpa bunyi /j/ sesudah d).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000150', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Pilih kata kerja yang tepat untuk konteks menyerahkan kelanjutan insiden ke sif berikutnya:', '{"options":["handed off","turned down","ruled out","panned out"],"translation":"Pada pukul 18.00 WIB, insinyur keandalan kami di Jakarta menyerahkan kelanjutan migrasi basis data secara rapi kepada tim London.","sentence_template":"At 6 p.m. WIB, our Jakarta reliability engineer cleanly [blank] the ongoing database migration to the London team."}'::jsonb, '{"selected":"handed off"}'::jsonb, NULL, NULL, '''Hand off [task] to [team]'' adalah istilah standar operasional global untuk serah-terima tugas lintas zona waktu.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000151', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah TOEFL tentang kompresi gambar. Apa kompromi teknis yang dijelaskan profesor?', '{"options":[{"id":"opt_1","text":"Semakin tinggi rasio kompresi, ukuran berkas kian kecil tetapi detail tekstur halus mulai mengabur"},{"id":"opt_2","text":"Algoritma lossy hanya dapat digunakan pada berkas teks dokumen hukum"},{"id":"opt_3","text":"Mata manusia sangat peka terhadap seluruh frekuensi yang dihapus algoritma"},{"id":"opt_4","text":"Kompresi tinggi membuat ukuran berkas membesar sekaligus mempertajam tekstur"}],"audio_text":"Lossy algorithms strip away frequencies the human eye barely notices—so the higher the compression ratio you choose, the smaller the file, though fine textures start blurring."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Profesor merangkum *trade-off* antara efisiensi ukuran berkas dan degradasi visual memakai komparatif ganda.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000152', 'e5100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat kolaborasi PR lintas negara berikut:', '{"romaji":"/ˈliːvɪŋ ˌriːprəˈduːsəbəl stɛps ɪn bʌɡ rɪˈpɔːrts hɛlps ˌɛndʒəˈnɪrz ʌnˈblɑːk iːtʃ ˈʌðər/","tokens":["each others","helps engineers unblock","Leaving reproducible steps","each other across time zones.","in bug reports","to unblocking"],"target_translation":"Menyertakan langkah reproduksi yang jelas pada laporan bug membantu para insinyur saling membuka hambatan kerja lintas zona waktu."}'::jsonb, '["Leaving reproducible steps","in bug reports","helps engineers unblock","each other across time zones."]'::jsonb, NULL, NULL, '''Helps + Object + V1 (unblock) + each other'' (bukan ''each others'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000153', 'e5100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih bentuk kausatif aktif yang tepat:', '{"options":["spun by","spinning to","spin","to spin"],"translation":"Selama puncak obral kilat, orkestrator kami mengatur node pekerja cadangan agar menyala otomatis dalam hitungan detik.","sentence_template":"During peak flash sales, our orchestrator has idle worker nodes [blank] up automatically within seconds."}'::jsonb, '{"selected":"spin"}'::jsonb, NULL, NULL, '''Has + [Agent: idle worker nodes] + [V1: spin] up'' mengikuti rumus kausatif aktif.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000154', 'e5100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih pasangan komparatif ganda untuk kata benda jamak terhitung (''bugs''):', '{"options":["least","the fewer","fewer of","the less"],"translation":"Semakin dini pengujian otomatis menangkap ketidakcocokan tipe data, semakin sedikit bug produksi yang sampai ke pelanggan berbayar.","sentence_template":"The earlier automated tests catch type mismatches, [blank] production bugs reach paying customers."}'::jsonb, '{"selected":"the fewer"}'::jsonb, NULL, NULL, '''Production bugs'' dapat dihitung (*countable plural*), sehingga wajib memakai ''the fewer'' alih-alih ''the less''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000155', 'e5100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000035', 'listening', 'listening_choice', 'Evaluasi Unit 5 — Dengarkan evaluasi arsitektur seorang Principal Engineer. Mengapa ia menolak usulan mikroservis berlebih?', '{"options":[{"id":"opt_1","text":"Mikroservis selalu menghilangkan seluruh beban operasional secara instan"},{"id":"opt_2","text":"Memecah sistem menjadi tiga puluh mikroservis saat tim masih kecil hanya akan menumpuk beban operasional besar tanpa menyelesaikan kemacetan utama"},{"id":"opt_3","text":"Ia mewajibkan lima insinyur membangun tiga puluh mikroservis minggu ini"},{"id":"opt_4","text":"Startup tersebut sudah memiliki tiga ratus insinyur infrastruktur khusus"}],"audio_text":"Splitting a five-person startup monolith into thirty microservices right now would incur massive operational overhead without solving our real bottleneck."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Mengintegrasikan kolokasi ''incur operational overhead'' dan ''bottleneck'' dalam analisis pragmatis rekayasa.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
