INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000158', 'e5100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000035', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih bentuk kausatif pasif yang tepat:', '{"options":["scrubs","scrubbed","to scrubbing","scrub"],"translation":"Sebelum membuka kode repositori ke publik, kita wajib memastikan setiap kunci API rahasia dibersihkan dari riwayat komit.","sentence_template":"Before open-sourcing the repository, we must get every proprietary API key [blank] from commit history."}'::jsonb, '{"selected":"scrubbed"}'::jsonb, NULL, NULL, '''Get + [Target: every proprietary API key] + [V3: scrubbed]'' menyatakan kausatif pasif.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000159', 'e5100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000035', 'listening', 'listening_choice', 'Evaluasi Unit 5 — Dengarkan komentar PR rekan kerja. Apa tindakan yang diminta sebelum penggabungan kode?', '{"options":[{"id":"opt_1","text":"Mengubah baris empat puluh dua menjadi kueri berparameter terlebih dahulu karena ini masalah keamanan pemblokir sebelum digabung"},{"id":"opt_2","text":"Langsung menggabungkan kode sekarang tanpa mengubah baris empat puluh dua"},{"id":"opt_3","text":"Menghapus seluruh fitur pencarian karena tidak disukai pengguna"},{"id":"opt_4","text":"Mengabaikan komentar tersebut karena hanya berupa gaya penulisan opsional"}],"audio_text":"LGTM overall! One blocking issue before merge, though: let''s parameterize line forty-two so untrusted query strings are properly escaped."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Kontras penting: berbeda dari ''nit:'', frasa ''One blocking issue before merge'' wajib diperbaiki sebelum PR digabungkan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000160', 'e5100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000035', 'writing', 'sentence_builder', 'Evaluasi Unit 5 — Susun kalimat serah-terima tim global berikut:', '{"romaji":"/klɪr pʊl rɪˈkwɛst ˈsʌməriz əˈlaʊ rɪˈvjuːərz tə ʌnˈblɑːk ˈtiːmˌmeɪts əˈkrɔːs twɛlv taɪm zoʊnz/","tokens":["Clear pull request","across twelve time zones.","summaries allow reviewers","allows reviewer","unblocking to","to unblock teammates"],"target_translation":"Ringkasan pull request yang jelas memungkinkan peninjau menyingkirkan hambatan rekan setim melintasi dua belas zona waktu."}'::jsonb, '["Clear pull request","summaries allow reviewers","to unblock teammates","across twelve time zones."]'::jsonb, NULL, NULL, '''Allow + Object + to V1'' (''allow reviewers to unblock teammates'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000161', 'e5100001-0000-4000-8000-000000000021', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat post-mortem proyek dengan Third Conditional yang benar:', '{"options":["had included","has included","would have included","includes"],"translation":"Seandainya pipeline QA menyertakan uji beban sintetis minggu lalu, kita pasti sudah menangkap lonjakan memori sebelum peluncuran.","sentence_template":"If the QA pipeline [blank] synthetic load tests last week, we would have caught the memory spike before launch."}'::jsonb, '{"selected":"had included"}'::jsonb, NULL, NULL, 'Di dalam klausa ''If'' pada Third Conditional, gunakan Past Perfect (''had included''), bukan ''would have''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000162', 'e5100001-0000-4000-8000-000000000021', NULL, 'reading', 'fill_blank', 'Pilih kata kerja kolokasi formal yang tepat untuk objek ''a costly recall'':', '{"options":["incur","hinge","avert","digress"],"translation":"Pengujian termal sejak dini memampukan divisi perangkat keras mencegah penarikan produk baterai global yang mahal.","sentence_template":"Early thermal testing enabled the hardware division to [blank] a costly global battery recall."}'::jsonb, '{"selected":"avert"}'::jsonb, NULL, NULL, '''Avert a recall / crisis / catastrophe'' berarti berhasil mencegah bencana sebelum terjadi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000163', 'e5100001-0000-4000-8000-000000000021', NULL, 'listening', 'listening_choice', 'Dengarkan evaluasi direktur rantai pasok. Apa faktor penyelamat perusahaan selama penutupan pelabuhan?', '{"options":[{"id":"opt_1","text":"Perusahaan memutuskan menghentikan seluruh distribusi barang di Jawa Timur"},{"id":"opt_2","text":"Penutupan pelabuhan baru akan terjadi pada kuartal keempat tahun depan"},{"id":"opt_3","text":"Pemimpin pengadaan sudah menyiapkan gudang cadangan di Surabaya sebelumnya sehingga pengiriman Q4 tidak lumpuh"},{"id":"opt_4","text":"Pengiriman Q4 terhenti total karena tidak ada gudang di Surabaya"}],"audio_text":"Honestly, if our procurement lead hadn''t lined up a secondary warehouse in Surabaya, our Q4 deliveries would have ground to a halt."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Klausa pengandaian negatif ''if X hadn''t lined up..., Y would have ground to a halt'' berarti pada kenyataannya X SUDAH menyiapkan gudang tersebut!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000164', 'e5100001-0000-4000-8000-000000000021', NULL, 'writing', 'sentence_builder', 'Susun kalimat evaluasi proyek menggunakan Third Conditional:', '{"romaji":"/ɪf wi hæd ɪˈstæblɪʃt ə kənˈtɪndʒənsi plæn ðə ˈsɜːrvər maɪˈɡreɪʃən wʊd həv ɡɔːn ˈsmuːðli/","tokens":["would have gone smoothly.","going smooth","the server migration","a contingency plan,","would have establish","If we had established"],"target_translation":"Seandainya kita telah menyusun rencana darurat cadangan, migrasi server pasti berjalan lancar."}'::jsonb, '["If we had established","a contingency plan,","the server migration","would have gone smoothly."]'::jsonb, NULL, NULL, 'Pasangan baku Third Conditional: ''If + had V3, ... would have V3''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000165', 'e5100001-0000-4000-8000-000000000021', NULL, 'speaking', 'speaking_repeat', 'Latih reduksi bunyi ''would have'' (/ˈwʊdəv/) yang alami dalam ucapan Amerika:', '{"romaji":"/wɪˈðaʊt klɪr ˈroʊlˌbæk skrɪpts wi ˈkʊdənt həv əˈvɜːrtɪd ˈtuːzdeɪz ˈaʊtɪdʒ/","display_text":"Without clear rollback scripts, we couldn''t have averted Tuesday''s outage.","phonetic_breakdown":["Without clear","rollback scripts,","we couldn''t have averted","Tuesday''s outage."]}'::jsonb, '{"expected_transcript":"Without clear rollback scripts, we couldn''t have averted Tuesday''s outage."}'::jsonb, NULL, NULL, 'Lafalkan ''couldn''t have'' menyatu lembut sebagai /ˈkʊdəntəv/ (tapi dalam tulisan tetap ''couldn''t have'', bukan ''couldn''t of''!).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000166', 'e5100001-0000-4000-8000-000000000021', NULL, 'reading', 'fill_blank', 'Pilih kata benda yang tepat untuk ''kemampuan mengantisipasi risiko sebelum terjadi'':', '{"options":["hindsight","caveat","nitpick","foresight"],"translation":"Berkat visi antisipasi CFO dalam melakukan lindung nilai kurs, volatilitas rupiah tidak menggerus dana abadi beasiswa kami.","sentence_template":"Thanks to the CFO''s [blank] in hedging currency rates, rupiah volatility did not erode our scholarship endowment."}'::jsonb, '{"selected":"foresight"}'::jsonb, NULL, NULL, '''Foresight'' merujuk pada kebijaksanaan memprediksi dan bersiap sebelum kejadian berlangsung.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000167', 'e5100001-0000-4000-8000-000000000021', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah sejarah bisnis TOEFL. Mengapa jaringan ritel tersebut bangkrut?', '{"options":[{"id":"opt_1","text":"Pembeli kembali berbelanja melalui katalog cetak setelah diskon besar"},{"id":"opt_2","text":"Pemangkasan harga tidak mampu membendung gelombang perpindahan pembeli ke lokapasar seluler"},{"id":"opt_3","text":"Perusahaan terlalu cepat meluncurkan aplikasi belanja seluler"},{"id":"opt_4","text":"Harga barang dinaikkan dua kali lipat menjelang musim liburan"}],"audio_text":"Management tried slashing catalog prices in desperation, yet nothing could stem the tide of shoppers migrating to mobile marketplaces."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Idiom ''stem the tide of...'' menegaskan ketidakmampuan menahan arus perubahan besar.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000168', 'e5100001-0000-4000-8000-000000000021', NULL, 'writing', 'sentence_builder', 'Susun kalimat pengandaian masa lalu dengan peluang ''might have'':', '{"romaji":"/hæd ðə ˈstɑːrtʌp ˈlɪsənd tə ˈbeɪtə ˈtɛstərz ɪt maɪt həv rɪˈteɪnd ɪts ˈɜːrli əˈdɑːptərz/","tokens":["would listened","retaining into","listened to beta testers,","it might have retained","Had the startup","its early adopters."],"target_translation":"Seandainya rintisan itu mendengarkan penguji beta, ia mungkin berhasil mempertahankan pengguna awalnya."}'::jsonb, '["Had the startup","listened to beta testers,","it might have retained","its early adopters."]'::jsonb, NULL, NULL, 'Bentuk ringkas ''Had + S + V3'' setara dengan ''If + S + had + V3''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000169', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Perhatikan keterangan waktu ''right now'' lalu pilih bentuk Mixed Conditional yang tepat:', '{"options":["will not be","had not been","would not be","would not have been"],"translation":"Seandainya perencana kota memperluas rel komuter pada tahun 1990-an, jalan raya pusat kota tidak akan begitu padat sekarang.","sentence_template":"If city planners had expanded commuter rail in the 1990s, downtown highways [blank] so congested right now."}'::jsonb, '{"selected":"would not be"}'::jsonb, NULL, NULL, 'Sebab terjadi di tahun 1990-an (''had expanded''), namun akibatnya dirasakan ''right now'', sehingga memakai ''would not be''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000170', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Pilih frasa preposisi formal yang bermakna ''Seandainya bukan karena'':', '{"options":["Aside of","In spite","Except that","But for"],"translation":"Seandainya bukan karena kolaborasi sumber terbuka yang cepat, analisis urutan mRNA vaksin pasti memakan waktu berbulan-bulan lebih lama.","sentence_template":"[blank] rapid open-source collaboration, vaccine mRNA sequence analysis would have taken months longer."}'::jsonb, '{"selected":"But for"}'::jsonb, NULL, NULL, '''But for + Noun Phrase'' setara dengan ''If it had not been for + Noun Phrase''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000171', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'listening', 'listening_choice', 'Dengarkan pernyataan penerima beasiswa pascasarjana. Apa fakta sebenarnya tentang kemampuan statistik pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara baru berencana mempelajari statistik setelah lulus kuliah"},{"id":"opt_2","text":"Pembicara menguasai statistik Bayesian dengan baik sehingga ia berhasil ditempatkan di lab biologi komputasi"},{"id":"opt_3","text":"Komite seleksi menghapus syarat statistik dari program biologi tahun ini"},{"id":"opt_4","text":"Pembicara ditolak dari lab biologi komputasi karena lemah di bidang statistik"}],"audio_text":"If I weren''t comfortable with Bayesian statistics, the admissions committee never would have placed me in the computational biology lab."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Mixed Conditional tipe kedua (''If I weren''t [present trait], they wouldn''t have placed me [past action]'') menyiratkan sifat tersebut memang dimiliki pembicara!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000172', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat Mixed Conditional (sebab lampau → dampak hari ini):', '{"romaji":"/ɪf wi hæd lɑːkt fɪkst reɪt klaʊd ˈkɑːntrækts ˈaʊər ˈmɑːrdʒɪnz wʊd lʊk mʌtʃ ˈhɛlθiər təˈdeɪ/","tokens":["fixed-rate cloud contracts,","locking into","would have looked","If we had locked","our margins would look","much healthier today."],"target_translation":"Seandainya dulu kita mengunci kontrak cloud bertarif tetap, margin keuntungan kita pasti terlihat jauh lebih sehat hari ini."}'::jsonb, '["If we had locked","fixed-rate cloud contracts,","our margins would look","much healthier today."]'::jsonb, NULL, NULL, 'Kata ''today'' mengunci klausa hasil pada ''would look'' (bukan ''would have looked'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000173', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'speaking', 'speaking_repeat', 'Ucapkan kalimat apresiasi formal menggunakan ''But for'' berikut:', '{"romaji":"/bʌt fɔːr ði ˌɛlpiːdiːˈpiː ˈskɑːlərˌʃɪp aɪ ˈwʊdənt bi kənˈdʌktɪŋ ˈklaɪmət ˈriːsɜːrtʃ ɪn ˈbɑːstən təˈdeɪ/","display_text":"But for the LPDP scholarship, I wouldn''t be conducting climate research in Boston today.","phonetic_breakdown":["But for","the LPDP scholarship,","I wouldn''t be conducting","climate research in Boston today."]}'::jsonb, '{"expected_transcript":"But for the LPDP scholarship, I wouldn''t be conducting climate research in Boston today."}'::jsonb, NULL, NULL, 'Jaga transisi kontras yang hangat pada ''But for the LPDP scholarship,'' diikuti ritme stabil.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000174', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Pilih kata penghubung pengandaian implisit yang tepat di awal kalimat kedua:', '{"options":["albeit","meanwhile","whereas","otherwise"],"translation":"Syukurlah tim hukum kami mematenkan desain sensor pada bulan Maret; jika tidak demikian, pesaing pasti sedang menirunya dengan bebas sekarang.","sentence_template":"Thankfully, our legal team patented the sensor design in March; [blank], competitors would be copying it freely right now."}'::jsonb, '{"selected":"otherwise"}'::jsonb, NULL, NULL, '''Otherwise'' menyiratkan ''If our legal team hadn''t patented it in March'' dan diikuti konsekuensi Mixed Conditional.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000175', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'listening', 'listening_choice', 'Dengarkan percakapan dua pendiri startup. Penyesalan masa lalu apa yang masih berdampak hari ini?', '{"options":[{"id":"opt_1","text":"Mereka telanjur melepas hak distribusi eksklusif di tahun pertama sehingga kini tidak bisa menjual langsung ke rumah sakit di Asia"},{"id":"opt_2","text":"Mereka baru saja membatalkan kontrak distributor eksklusif pagi tadi"},{"id":"opt_3","text":"Mereka saat ini sedang menjual langsung ke seluruh rumah sakit besar di Asia"},{"id":"opt_4","text":"Rumah sakit di Asia menolak membeli produk medis buatan startup"}],"audio_text":"If we hadn''t given away exclusive distribution rights in year one, we''d be selling directly to enterprise hospitals across Asia right now."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Kontraksi lisan ''we''d be selling ... right now'' menunjukkan ''we would be selling'' (akibat masa kini dari kesalahan tahun pertama).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000176', 'e5100001-0000-4000-8000-000000000022', 'e2000001-0000-4000-8000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat evaluasi strategis menggunakan ''But for'':', '{"romaji":"/bʌt fɔːr ˈɔːtəˌmeɪtɪd kəˈnɛri ˈroʊlaʊts ˈjɛstərdeɪz ˈfɔːlti pætʃ wʊd həv əˈfɛktɪd ˈmɪljənz/","tokens":["would have affected millions.","But for automated","Except automated","would affect yesterday","canary rollouts,","yesterday''s faulty patch"],"target_translation":"Seandainya bukan karena peluncuran bertahap canary otomatis, tambalan kode rusak kemarin pasti telah berdampak pada jutaan pengguna."}'::jsonb, '["But for automated","canary rollouts,","yesterday''s faulty patch","would have affected millions."]'::jsonb, NULL, NULL, 'Karena kejadian berlangsung ''yesterday'', klausa utama menggunakan Third Conditional ''would have affected''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000177', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Lengkapi kalimat kuliah sejarah teknologi berikut:', '{"options":["pivotal turning point","contingency plan","single point of failure","nitpick"],"translation":"Para sejarawan memandang penemuan huruf cetak logam lepas sebagai titik balik krusial yang mendemokratisasi literasi ilmiah.","sentence_template":"Historians view the invention of movable metal type as a [blank] that democratized scientific literacy."}'::jsonb, '{"selected":"pivotal turning point"}'::jsonb, NULL, NULL, '''Pivotal turning point'' menegaskan momen penentu perubahan besar dalam sejarah.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000178', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Pilih kata kerja pengandaian yang tepat untuk subjek gerund kontrafaktual:', '{"options":["would","was","having","had"],"translation":"Menghilangkan zona penyangga lahan basah di sepanjang pesisir akan membuat lahan pertanian daratan terpapar intrusi air asin parah.","sentence_template":"Eliminating wetland buffer zones along the coast [blank] expose inland farms to severe saltwater intrusion."}'::jsonb, '{"selected":"would"}'::jsonb, NULL, NULL, 'Subjek gerund ''Eliminating X'' mengandung makna pengandaian (''If we eliminated X''), sehingga dipasangkan dengan ''would + V1''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000179', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah ekologi TOEFL tentang serigala di Taman Nasional Yellowstone. Apa yang terjadi seandainya serigala tidak diperkenalkan kembali?', '{"options":[{"id":"opt_1","text":"Populasi rusa elk yang tak terkendali masih akan terus menggunduli pohon willow di tepi sungai hingga hari ini"},{"id":"opt_2","text":"Serigala justru merusak vegetasi tepi sungai lebih parah daripada rusa elk"},{"id":"opt_3","text":"Populasi berang-berang meningkat pesat tanpa kehadiran serigala"},{"id":"opt_4","text":"Pohon willow tepi sungai sudah punah seluruhnya sebelum tahun 1995"}],"audio_text":"Had wolves not been reintroduced to Yellowstone in 1995, unchecked elk grazing would still be stripping riverbank willows bare today."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Perhatikan Mixed Conditional pada kuliah TOEFL: ''Had wolves not been reintroduced in 1995 [past], elk grazing would still be stripping ... today [present]''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000180', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat analisis dampak berantai dalam kuliah ekonomi:', '{"romaji":"/əˈlaʊɪŋ ðæt ˈriːdʒənəl bæŋk tə kəˈlæps ɪn tuː ˈθaʊzənd eɪt wʊd həv ˈtrɪɡərd/","tokens":["triggering have","collapsed into","would have triggered","Allowing that regional bank","a global domino effect.","to collapse in 2008"],"target_translation":"Membiarkan bank regional itu runtuh pada tahun 2008 pasti telah memicu efek domino global."}'::jsonb, '["Allowing that regional bank","to collapse in 2008","would have triggered","a global domino effect."]'::jsonb, NULL, NULL, 'Gerund lampau kontekstual (''in 2008'') diikuti Third Conditional ''would have triggered''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000181', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kuliah biologi TOEFL berikut dengan intonasi akademik yang jernih:', '{"romaji":"/wɪˈðaʊt siː ˈɑːtərz ˈæktɪŋ æz ə ˈkiːˌstoʊn ˈspiːʃiːz kɛlp ˈiːkoʊˌsɪstəmz wʊd kəˈlæps/","display_text":"Without sea otters acting as a keystone species, kelp ecosystems would collapse.","phonetic_breakdown":["Without sea otters","acting as","a keystone species,","kelp ecosystems would collapse."]}'::jsonb, '{"expected_transcript":"Without sea otters acting as a keystone species, kelp ecosystems would collapse."}'::jsonb, NULL, NULL, 'Lafalkan ''otters'' dengan flap Amerika /ˈɑːɾərz/ dan tekankan istilah ''KEY-stone SPE-cies''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000182', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Lengkapi kalimat refleksi lintasan karier/riset berikut:', '{"options":["blameless hindsight","drastically different trajectory","counterintuitive nitpick","valid caveat"],"translation":"Tanpa server pracetak akses terbuka, riset pembelajaran mesin modern pasti menempuh lintasan perkembangan yang jauh berbeda.","sentence_template":"Without open-access preprint servers, modern machine learning research would have taken a [blank]."}'::jsonb, '{"selected":"drastically different trajectory"}'::jsonb, NULL, NULL, '''Take a drastically different trajectory'' adalah kolokasi C1/B2+ untuk menggambarkan perubahan arah evolusi suatu bidang.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000183', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'listening', 'listening_choice', 'Dengarkan diskusi seminar sejarah ekonomi. Mengapa pembicara menyebut Terusan Suez sebagai contoh kontrafaktual?', '{"options":[{"id":"opt_1","text":"Perdagangan antara Mumbai dan London baru dimulai pada abad ke-20"},{"id":"opt_2","text":"Kapal uap abad ke-19 belum sanggup berlayar melintasi Terusan Suez"},{"id":"opt_3","text":"Tanpa Terusan Suez, kapal uap abad ke-19 terpaksa memutar jauh mengelilingi benua Afrika di setiap pelayaran"},{"id":"opt_4","text":"Rute mengelilingi Afrika jauh lebih pendek dibandingkan lewat Terusan Suez"}],"audio_text":"Just imagine nineteenth-century steamships without the Suez Canal—maritime freight between Mumbai and London would have had to detour around Africa every single voyage."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Without X — Y would have had to V1'' menunjukkan kewajiban alternatif yang berat seandainya X tidak pernah dibangun.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000184', 'e5100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat penutup esai analisis sejarah berikut:', '{"romaji":"/hæd ˈprɪntɪŋ ˈprɛsɪz rɪˈmeɪnd proʊˈhɪbətɪvli ɪkˈspɛnsɪv ˌsaɪənˈtɪfɪk ˌrɛvəˈluːʃənz wʊd həv ʌnˈfoʊldɪd/","tokens":["remained prohibitively expensive,","scientific revolutions","Had printing presses","much later.","would unfold yesterday","would have unfolded","unfolding later"],"target_translation":"Seandainya mesin cetak tetap luar biasa mahal, revolusi ilmiah pasti baru berlangsung jauh lebih lambat."}'::jsonb, '["Had printing presses","remained prohibitively expensive,","scientific revolutions","would have unfolded","much later."]'::jsonb, NULL, NULL, 'Inversi ''Had + S + V3'' dipasangkan dengan ''would have unfolded''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000185', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Periksa penanda waktu ''today'' dan pilih jawaban yang tepat:', '{"options":["will not have been","would not have been","would not be","had not been"],"translation":"Seandainya Indonesia dulu tidak berinvestasi besar pada standar pembayaran digital, adopsi QRIS tidak akan nyaris merata di kalangan pedagang kecil hari ini.","sentence_template":"If Indonesia had not invested heavily in digital payment standards, QRIS adoption [blank] nearly universal across small merchants today."}'::jsonb, '{"selected":"would not be"}'::jsonb, NULL, NULL, 'Mixed Conditional (sebab masa lalu → kondisi faktual ''today'') menuntut ''would not be''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000186', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Pilih bentuk klausa ''If'' untuk peristiwa murni masa lalu:', '{"options":["have overlooked","had overlooked","overlook","would have overlooked"],"translation":"Wahana antariksa kita pasti telah melewatkan jendela masuk orbitnya seandainya insinyur navigasi melewatkan galat kalibrasi pendorong tersebut.","sentence_template":"Our spacecraft would have missed its orbital insertion window if navigation engineers [blank] the thruster calibration error."}'::jsonb, '{"selected":"had overlooked"}'::jsonb, NULL, NULL, 'Klausa ''if'' pada Third Conditional wajib memakai Past Perfect (''had overlooked'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000187', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'listening', 'listening_choice', 'Evaluasi Unit 6 — Dengarkan ringkasan post-mortem direktur teknik. Apa yang berhasil mencegah kebocoran data?', '{"options":[{"id":"opt_1","text":"Perusahaan belum memiliki kebijakan keamanan zero-trust saat insiden terjadi"},{"id":"opt_2","text":"Tim keamanan baru mengaktifkan rotasi token setelah data pelanggan tercuri"},{"id":"opt_3","text":"Kebijakan rotasi token zero-trust berhasil melindungi data pelanggan meskipun sebuah laptop sempat disusupi"},{"id":"opt_4","text":"Data pelanggan produksi bocor seluruhnya akibat laptop yang disusupi"}],"audio_text":"But for our zero-trust token rotation policy, that compromised laptop could have exposed production customer records."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''But for X, Y could have exposed Z'' berarti berkat adanya X, kebocoran Z berhasil dicegah!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000188', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'writing', 'sentence_builder', 'Evaluasi Unit 6 — Susun kalimat kontrafaktual dengan ''Otherwise'':', '{"romaji":"/wi ræn ˈkeɪɑːs drɪlz ɪn ɑːkˈtoʊbər ˈʌðərˌwaɪz blæk ˈfraɪdeɪ ˈtræfɪk wʊd həv kræʃt ˈtʃɛkˌaʊt/","tokens":["running into","Black Friday traffic","We ran chaos drills","would crash October","would have crashed checkout.","in October; otherwise,"],"target_translation":"Kami menjalankan latihan simulasi gangguan pada bulan Oktober; jika tidak, trafik Black Friday pasti sudah menumbangkan sistem pembayaran."}'::jsonb, '["We ran chaos drills","in October; otherwise,","Black Friday traffic","would have crashed checkout."]'::jsonb, NULL, NULL, 'Fakta lampau diikuti ''; otherwise, + would have V3''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000189', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'speaking', 'speaking_repeat', 'Evaluasi Unit 6 — Ucapkan kalimat Mixed Conditional berikut dengan jelas:', '{"romaji":"/ɪf wi ˈhædənt peɪd daʊn ˈaʊər ˈtɛknɪkəl dɛt wiːd bi stʌk ˈfɪksɪŋ ˈlɛɡəsi bʌɡz naʊ/","display_text":"If we hadn''t paid down our technical debt, we''d be stuck fixing legacy bugs now.","phonetic_breakdown":["If we hadn''t","paid down our technical debt,","we''d be stuck","fixing legacy bugs now."]}'::jsonb, '{"expected_transcript":"If we hadn''t paid down our technical debt, we''d be stuck fixing legacy bugs now."}'::jsonb, NULL, NULL, 'Kontraksi ''we''d be stuck ... now'' (/wiːd bi stʌk/) mengalir alami untuk dampak masa kini.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000190', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Pilih kolokasi formal untuk ''mencegah bencana tepat waktu'':', '{"options":["avert","echo","corroborate","incur"],"translation":"Koordinasi sigap antar-petugas pemandu lalu lintas udara membantu mencegah tabrakan landasan pacu saat kabut tebal.","sentence_template":"Swift coordination between air-traffic controllers helped [blank] a runway collision during dense fog."}'::jsonb, '{"selected":"avert"}'::jsonb, NULL, NULL, '''Avert a collision'' adalah kolokasi baku untuk mengelakkan insiden berbahaya.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000191', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'listening', 'listening_choice', 'Evaluasi Unit 6 — Dengarkan refleksi seorang peneliti pascadoktoral. Mengapa penguasaan Python berperan krusial baginya?', '{"options":[{"id":"opt_1","text":"Ia baru mulai belajar dasar pemrograman Python minggu depan"},{"id":"opt_2","text":"Analisis disertasinya memakan waktu enam bulan karena ia tidak menguasai Python"},{"id":"opt_3","text":"Kampusnya melarang penggunaan Python untuk riset genomik"},{"id":"opt_4","text":"Berkat kemampuannya memparalelkan skrip Python, analisis disertasinya semester lalu selesai dalam empat hari alih-alih enam bulan"}],"audio_text":"If I didn''t know how to parallelize genomic scripts in Python, my dissertation analysis last semester would have taken six months instead of four days."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Mixed Conditional tipe Present-State → Past-Event: ''If I didn''t know X [kemampuan umum], my analysis last semester would have taken...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000192', 'e5100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000036', 'writing', 'sentence_builder', 'Evaluasi Unit 6 — Susun kalimat pembuka evaluasi ''But for'' berikut:', '{"romaji":"/bʌt fɔːr ɪˈmɜːrdʒənsi ˈsɛntrəl bæŋk lɪˈkwɪdəti ˈkrɛdɪt ˈmɑːrkɪts wʊd həv ˈfroʊzən kəmˈpliːtli/","tokens":["frozen completely.","credit markets would have","central bank liquidity,","Except emergency","freezing would","But for emergency"],"target_translation":"Seandainya bukan karena likuiditas darurat bank sentral, pasar kredit pasti telah membeku sepenuhnya."}'::jsonb, '["But for emergency","central bank liquidity,","credit markets would have","frozen completely."]'::jsonb, NULL, NULL, '''But for + Noun Phrase'' diikuti ''would have + V3 (frozen)''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000193', 'e5100001-0000-4000-8000-000000000025', NULL, 'reading', 'fill_blank', 'Pilih bentuk klausa partisip pasif yang tepat untuk menerangkan ''the micro-loan program'':', '{"options":["To backing","Backed","Have backed","Backing"],"translation":"Didukung oleh koperasi perempuan lokal, program pinjaman mikro tersebut mencapai tingkat pengembalian sembilan puluh sembilan persen.","sentence_template":"[blank] by local women''s cooperatives, the micro-loan program achieved a ninety-nine percent repayment rate."}'::jsonb, '{"selected":"Backed"}'::jsonb, NULL, NULL, 'Karena ''the micro-loan program'' didukung (pasif) oleh koperasi, gunakan Past Participle ''Backed''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000194', 'e5100001-0000-4000-8000-000000000025', NULL, 'reading', 'fill_blank', 'Pilih Perfect Participle yang menegaskan selesainya audit sebelum ekspansi dimulai:', '{"options":["Be obtaining","Obtained by","Having obtained","To have obtain"],"translation":"Setelah mengantongi sertifikasi keamanan ISO pada bulan Juni, vendor cloud tersebut mulai menerima klien perbankan pada bulan Juli.","sentence_template":"[blank] ISO security certification in June, the cloud vendor began onboarding banking clients in July."}'::jsonb, '{"selected":"Having obtained"}'::jsonb, NULL, NULL, '''Having + V3'' (''Having obtained'') menunjukkan urutan kronologis aktif yang selesai mendahului klausa utama.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000195', 'e5100001-0000-4000-8000-000000000025', NULL, 'listening', 'listening_choice', 'Dengarkan ringkasan laporan kuartalan CFO. Apa penyebab utama naiknya margin laba bersih?', '{"options":[{"id":"opt_1","text":"Turunnya biaya bahan bakar logistik serta otomatisasi gudang mendorong kenaikan margin operasional Q3"},{"id":"opt_2","text":"Margin operasional Q3 turun drastis akibat mahalnya otomatisasi gudang"},{"id":"opt_3","text":"Biaya bahan bakar logistik melonjak tertinggi sepanjang tahun"},{"id":"opt_4","text":"Perusahaan menaikkan harga jual produk sebesar empat puluh persen"}],"audio_text":"Driven by lower logistics fuel costs and warehouse automation, Q3 operating margins expanded by four hundred basis points."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Driven by X and Y, margins expanded...'' memadatkan hubungan sebab-akibat pasif dalam gaya laporan eksekutif.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000196', 'e5100001-0000-4000-8000-000000000025', NULL, 'writing', 'sentence_builder', 'Susun kalimat ringkas menggunakan frasa partisip ''stemming from'':', '{"romaji":"/səˈplaɪ dɪˈleɪz ˈstɛmɪŋ frʌm taɪˈfuːn ˈkloʊʒərz fɔːrst ˈfæktəriz tə drɔː daʊn ˈbʌfər ˈɪnvənˌtɔːri/","tokens":["Supply delays stemming from","forced factories to","drawing into","draw down buffer inventory.","stemmed by","typhoon closures"],"target_translation":"Keterlambatan pasokan yang bersumber dari penutupan akibat topan memaksa pabrik menguras persediaan penyangga."}'::jsonb, '["Supply delays stemming from","typhoon closures","forced factories to","draw down buffer inventory."]'::jsonb, NULL, NULL, 'Reduced relative clause aktif ''stemming from...'' memodifikasi ''Supply delays'' tanpa kata ''which stemmed''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000197', 'e5100001-0000-4000-8000-000000000025', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat pembuka laporan eksekutif berpartisip berikut dengan mantap:', '{"romaji":"/ˈhævɪŋ ˈvæləˌdeɪtɪd ˈmɑːrkɪt dɪˈmænd ˈaʊər dɪˈvɪʒən ˈstriːmˌlaɪnd ˈriːdʒənəl ˌdɪstrəˈbjuːʃən/","display_text":"Having validated market demand, our division streamlined regional distribution.","phonetic_breakdown":["Having validated","market demand,","our division streamlined","regional distribution."]}'::jsonb, '{"expected_transcript":"Having validated market demand, our division streamlined regional distribution."}'::jsonb, NULL, NULL, 'Beri jeda tipis pada koma sesudah ''demand,'' agar struktur dua tahap terdengar jelas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000198', 'e5100001-0000-4000-8000-000000000025', NULL, 'reading', 'fill_blank', 'Pilih bentuk partisip aktif untuk menggantikan ''Because they recognized...'':', '{"options":["Recognizing","Been recognizing","Recognized","Have recognize"],"translation":"Menyadari pergeseran menuju komputasi tepi, para produsen cip merancang ulang prosesor saraf berdaya rendah.","sentence_template":"[blank] the shift toward edge computing, chipmakers redesigned low-power neural processors."}'::jsonb, '{"selected":"Recognizing"}'::jsonb, NULL, NULL, 'Subjek ''chipmakers'' secara aktif menyadari pergeseran tersebut, sehingga wajib memakai Present Participle ''Recognizing''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000199', 'e5100001-0000-4000-8000-000000000025', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan berita riset medis. Mengapa terapi baru tersebut mudah didistribusikan di daerah tropis?', '{"options":[{"id":"opt_1","text":"Klinik daerah tropis wajib membeli lemari pendingin khusus terlebih dahulu"},{"id":"opt_2","text":"Bentuk bubuk kering mengurangi efektivitas vaksin hingga separuhnya"},{"id":"opt_3","text":"Vaksin hirup tersebut diformulasikan sebagai bubuk kering tahan panas sehingga tidak memerlukan pendingin rantai dingin"},{"id":"opt_4","text":"Vaksin tersebut harus disimpan pada suhu beku ekstrem sepanjang waktu"}],"audio_text":"Formulated as a heat-stable dry powder, the new inhalable vaccine requires zero cold-chain refrigeration."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Past Participle pembuka ''Formulated as...'' langsung menjelaskan sifat kunci subjek ''the new inhalable vaccine''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000200', 'e5100001-0000-4000-8000-000000000025', NULL, 'writing', 'sentence_builder', 'Susun kalimat laporan kebijakan dengan Past Participle di awal:', '{"romaji":"/ˈspɪrˌhɛdɪd baɪ ðə ˈmɪnɪstri ʌv hɛlθ ðə ˌdɪdʒətəˈzeɪʃən ɪˈnɪʃətɪv kəˈnɛktɪd/","tokens":["connected ten thousand clinics.","the digitization initiative","the Ministry of Health,","Spearheaded by","Spearheading by","connecting into"],"target_translation":"Dipelopori oleh Kementerian Kesehatan, inisiatif digitalisasi tersebut menghubungkan sepuluh ribu klinik."}'::jsonb, '["Spearheaded by","the Ministry of Health,","the digitization initiative","connected ten thousand clinics."]'::jsonb, NULL, NULL, 'Subjek ''the digitization initiative'' menerima tindakan ''Spearheaded by...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000201', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Pilih klausa utama yang bebas dari kesalahan dangling modifier sesudah ''Having analyzed the seismic waves,'':', '{"options":["three tsunami buoys","the epicenter was","it was clear that","the geophysicists"],"translation":"Setelah menganalisis gelombang seismik dari tiga stasiun, para ahli geofisika berhasil menentukan titik pusat gempa lepas pantai.","sentence_template":"Having analyzed the seismic waves from three stations, [blank] pinpointed the offshore epicenter."}'::jsonb, '{"selected":"the geophysicists"}'::jsonb, NULL, NULL, 'Pelaku yang menganalisis gelombang seismik adalah ''the geophysicists'', sehingga wajib menjadi subjek tepat sesudah koma.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000202', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Pilih subjek yang selaras secara logis sesudah klausa pasif ''Viewed under an electron microscope,'':', '{"options":["our laboratory team","the camera technician","butterfly wing scales","entomologists can"],"translation":"Dilihat di bawah mikroskop elektron, sisik sayap kupu-kupu menampakkan nanostruktur heksagonal yang rumit.","sentence_template":"Viewed under an electron microscope, [blank] reveal intricate hexagonal nanostructures."}'::jsonb, '{"selected":"butterfly wing scales"}'::jsonb, NULL, NULL, 'Benda yang dilihat di bawah mikroskop adalah ''butterfly wing scales'', bukan ilmuwan atau teknisi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000203', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'listening', 'listening_choice', 'Dengarkan umpan balik dosen penulisan akademik. Mengapa kalimat draf mahasiswa perlu diperbaiki?', '{"options":[{"id":"opt_1","text":"Subjek sesudah koma (''connectivity'') tidak cocok dengan pelaku wawancara (''While interviewing''), sehingga terjadi dangling modifier"},{"id":"opt_2","text":"Kalimat pembuka esai tidak boleh menggunakan tanda koma sama sekali"},{"id":"opt_3","text":"Kata kerja ''emerged'' tidak boleh dipakai dalam bahasa Inggris akademik"},{"id":"opt_4","text":"Mahasiswa dilarang mewawancarai guru di daerah pedesaan"}],"audio_text":"Careful with your opening sentence—writing ''While interviewing rural teachers, connectivity emerged as a barrier'' makes it sound like connectivity conducted the interviews!"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '(Perhatikan koreksi dosen: pelaku ''interviewing'' seharusnya peneliti, bukan kata benda abstrak ''connectivity''.)', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000204', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat ilmiah bebas dangling modifier dengan ''Unless + V3'':', '{"romaji":"/ʌnˈlɛs ˈprɑːpərli ˈɪnsəˌleɪtɪd ˌsuːpərkənˈdʌktɪŋ ˈmæɡnəts luːz ðɛr ˈzɪroʊ rɪˈzɪstəns steɪt/","tokens":["superconducting magnets","lose their zero-resistance","state almost instantly.","insulating properly","engineers lose","Unless properly insulated,"],"target_translation":"Kecuali diisolasi dengan benar, magnet superkonduktor kehilangan kondisi hambatan-nolnya hampir seketika."}'::jsonb, '["Unless properly insulated,","superconducting magnets","lose their zero-resistance","state almost instantly."]'::jsonb, NULL, NULL, 'Subjek ''superconducting magnets'' selaras sempurna dengan partisip pasif ''properly insulated''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000205', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'speaking', 'speaking_repeat', 'Ucapkan kalimat laporan teknis dengan reduced clause ''Once deployed'' berikut:', '{"romaji":"/wʌns dɪˈplɔɪd tə ɛdʒ ˈsɜːrvərz ðə ˈraʊtɪŋ ˈteɪbəl ʌpˈdeɪts wɪˈðɪn ˈmɪləˌsɛkəndz/","display_text":"Once deployed to edge servers, the routing table updates within milliseconds.","phonetic_breakdown":["Once deployed","to edge servers,","the routing table","updates within milliseconds."]}'::jsonb, '{"expected_transcript":"Once deployed to edge servers, the routing table updates within milliseconds."}'::jsonb, NULL, NULL, 'Di Amerika Utara, ''routing'' pada jaringan komputer lazim dilafalkan /ˈraʊtɪŋ/ (seperti ''out'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000206', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Pilih bentuk reduksi klausa waktu (''When + V-ing'') yang tepat ketika subjeknya ''auditors'':', '{"options":["evaluating","be evaluated","evaluation of","evaluated"],"translation":"Saat mengevaluasi anak perusahaan lintas negara, auditor eksternal wajib mencocokkan buku besar pajak lokal dengan standar IFRS.","sentence_template":"When [blank] cross-border subsidiaries, external auditors must reconcile local tax ledgers with IFRS standards."}'::jsonb, '{"selected":"evaluating"}'::jsonb, NULL, NULL, 'Karena subjek ''external auditors'' melakukan aksi evaluasi secara aktif, gunakan ''When evaluating''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000207', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah arsitektur ramah lingkungan. Keunggulan apa yang dimiliki beton self-healing?', '{"options":[{"id":"opt_1","text":"Bakteri di dalam beton hanya aktif di gurun yang sama sekali kering"},{"id":"opt_2","text":"Bakteri penghasil batu kapur yang tertanam di dalamnya menutup retakan halus secara otomatis saat air hujan merembes masuk"},{"id":"opt_3","text":"Pekerja konstruksi harus menyuntikkan semen cair secara manual setiap kali hujan turun"},{"id":"opt_4","text":"Beton tersebut melarut sepenuhnya apabila terkena air hujan"}],"audio_text":"Embedded with dormant limestone-producing bacteria, self-healing concrete seals hairline cracks automatically whenever rainwater seeps in."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Partisip pasif pembuka ''Embedded with...'' berpadu serasi dengan subjek ''self-healing concrete''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000208', 'e5100001-0000-4000-8000-000000000026', 'e2000001-0000-4000-8000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat pembuka esai riset yang gramatikal dan presisi:', '{"romaji":"/ˈhævɪŋ ˈsɜːrveɪd fɔːr ˈhʌndrəd ˈɛkspɔːrt ˌmænjəˈfæktʃərərz ði ɪˈkɑːnəmɪsts aɪˈdɛntəˌfaɪd/","tokens":["surveyed by","export manufacturers,","customs delays were","Having surveyed four hundred","customs delays as","the chief bottleneck.","the economists identified"],"target_translation":"Setelah menyurvei empat ratus produsen ekspor, para ekonom mengidentifikasi keterlambatan bea cukai sebagai kemacetan utama."}'::jsonb, '["Having surveyed four hundred","export manufacturers,","the economists identified","customs delays as","the chief bottleneck."]'::jsonb, NULL, NULL, 'Pelaku survei (''the economists'') ditempatkan tepat sesudah koma sehingga bebas dangling modifier.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000209', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Pilih kata kerja tren grafik untuk menggambarkan pertumbuhan yang melampaui variabel lain:', '{"options":["plateaued","averted","digressed","outpaced"],"translation":"Selama satu dekade terakhir, instalasi jaringan energi terbarukan secara konsisten melaju melampaui penambahan kapasitas bahan bakar fosil.","sentence_template":"Over the past decade, renewable grid installations have consistently [blank] fossil-fuel capacity additions."}'::jsonb, '{"selected":"outpaced"}'::jsonb, NULL, NULL, '''Outpace + Object'' adalah verba transitif presisi untuk membandingkan kecepatan pertumbuhan dua tren.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000210', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Lengkapi kalimat statistik berikut dengan klausa partisip penjelas angka:', '{"options":["reaches","to reached","reaching","reached by"],"translation":"Produksi panas bumi Indonesia meningkat stabil sepanjang dekade tersebut, mencapai hampir dua gigawatt daya beban dasar.","sentence_template":"Indonesia''s geothermal output rose steadily throughout the decade, [blank] nearly two gigawatts of baseload power."}'::jsonb, '{"selected":"reaching"}'::jsonb, NULL, NULL, 'Trailing Present Participle ('', reaching...'') menambahkan titik capaian data secara ringkas.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000211', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'listening', 'listening_choice', 'Dengarkan pemaparan analis riset pasar. Bagaimana pola adopsi kacamata VR berdasarkan grafik tersebut?', '{"options":[{"id":"opt_1","text":"Perangkat ditarik dari pasar dua belas hari sesudah peluncuran"},{"id":"opt_2","text":"Penggunaan aktif harian terus meroket hingga melampaui sembilan puluh persen pembeli"},{"id":"opt_3","text":"Penggunaan aktif harian sempat melonjak tajam saat peluncuran liburan, namun segera mendatar di kisaran dua belas persen pembeli"},{"id":"opt_4","text":"Penjualan saat musim liburan turun tajam tanpa ada pembeli baru"}],"audio_text":"After a sharp uptick during the holiday launch, daily active usage quickly plateaued at around twelve percent of buyers."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Kontras kosakata tren: ''sharp uptick'' (lonjakan awal) diikuti ''plateaued at ~12%'' (mendatar).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000212', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat ringkasan laporan keuangan dengan trailing participle:', '{"romaji":"/ˈɛntərˌpraɪz səbˈskrɪpʃənz sɜːrdʒd ˈfɔːrti pərˈsɛnt ˈɔːfˌsɛtɪŋ ˈsɔːftər dɪˈmænd/","tokens":["Enterprise subscriptions","offsetting softer demand","surging into","offsetted by","surged forty percent,","in consumer hardware."],"target_translation":"Langganan korporat melonjak empat puluh persen, mengimbangi permintaan yang melemah pada perangkat keras konsumen."}'::jsonb, '["Enterprise subscriptions","surged forty percent,","offsetting softer demand","in consumer hardware."]'::jsonb, NULL, NULL, ''', offsetting...'' menjelaskan dampak penyeimbang dari lonjakan klausa utama secara elegan.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000213', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'speaking', 'speaking_repeat', 'Ucapkan kalimat presentasi data eksekutif berikut dengan artikulasi Amerika yang jelas:', '{"romaji":"/klaʊd ˈrɛvəˌnuː ˌaʊtˈpeɪst prəˈdʒɛkʃənz ˈpiːkɪŋ æt ˈnaɪnti ˈmɪljən ˈdɑːlərz ɪn ˌkjuːˈfɔːr/","display_text":"Cloud revenue outpaced projections, peaking at ninety million dollars in Q4.","phonetic_breakdown":["Cloud revenue","outpaced projections,","peaking at","ninety million dollars in Q4."]}'::jsonb, '{"expected_transcript":"Cloud revenue outpaced projections, peaking at ninety million dollars in Q4."}'::jsonb, NULL, NULL, 'Lafalkan ''revenue'' ala Amerika /ˈrɛvəˌnuː/ (tanpa bunyi /nj/) dan bedakan jelas ''ninety'' (/ˈnaɪnti/) dari ''nineteen''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000214', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Pilih kata benda yang menggambarkan ''lonjakan naik mendadak'' pada indikator ekonomi:', '{"options":["dangling modifier","sharp uptick","single failure","status quo"],"translation":"Otoritas pelabuhan melaporkan lonjakan tajam pada ekspor kontainer menyusul penurunan tarif bilateral.","sentence_template":"Port authorities reported a [blank] in container exports following the bilateral tariff reduction."}'::jsonb, '{"selected":"sharp uptick"}'::jsonb, NULL, NULL, '''A sharp uptick in + Noun'' adalah frasa baku berita ekonomi dan laporan industri AS.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000215', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'listening', 'listening_choice', 'Dengarkan kuliah demografi TOEFL. Mengapa angka urbanisasi di wilayah tersebut berhenti naik?', '{"options":[{"id":"opt_1","text":"Angka kelahiran di pusat kota meningkat tiga kali lipat sesudah 2015"},{"id":"opt_2","text":"Laju urbanisasi mendatar sesudah 2015 karena kota-kota satelit penyangga menyerap limpahan penduduk"},{"id":"opt_3","text":"Penduduk dilarang berpindah ke kota satelit sejak tahun 2015"},{"id":"opt_4","text":"Seluruh pabrik dipindahkan kembali ke pusat kota tua"}],"audio_text":"Rural-to-urban migration climbed rapidly until 2015 before plateauing, largely because satellite commuter towns absorbed the overflow."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Before plateauing, largely because...'' merangkum perubahan kemiringan kurva beserta faktor penjelasnya.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000216', 'e5100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat analisis pangsa pasar berikut:', '{"romaji":"/dəˈmɛstɪk ˈbætəri rɪˈfaɪnɪŋ ɪkˈspændɪd ˈræpɪdli əˈkaʊntɪŋ fɔːr hæf ʌv ˈriːdʒənəl ˈɛkspɔːrts/","tokens":["accounting for half","Domestic battery refining","expanded rapidly,","accounted by","of regional exports.","rapidly expand"],"target_translation":"Pemurnian baterai dalam negeri berkembang pesat, mencakup separuh dari ekspor kawasan."}'::jsonb, '["Domestic battery refining","expanded rapidly,","accounting for half","of regional exports."]'::jsonb, NULL, NULL, 'Klausa utama Simple Past diikuti '', accounting for...'' untuk porsi persentase/pecahan.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000217', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Eliminasi dangling modifier dengan memilih subjek yang tepat:', '{"options":["efficacy rates were","the research consortium","patient recovery","the therapeutic bottle"],"translation":"Setelah merampungkan uji klinis ketat di enam rumah sakit, konsorsium riset tersebut mengajukan terapi demam berdarah itu untuk tinjauan regulasi.","sentence_template":"Having completed rigorous clinical trials across six hospitals, [blank] submitted the dengue therapeutic for regulatory review."}'::jsonb, '{"selected":"the research consortium"}'::jsonb, NULL, NULL, 'Hanya ''the research consortium'' yang secara logis mampu menyelesaikan uji klinis dan mengajukan dokumen.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000218', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Pilih bentuk partisip pembuka pasif yang tepat:', '{"options":["Establishing","Have established","To establishing","Established"],"translation":"Didirikan melalui kolaborasi bersama nelayan setempat, kawasan konservasi laut tersebut memulihkan biomassa ikan karang dalam tiga tahun.","sentence_template":"[blank] in collaboration with local fishermen, the marine reserve restored reef fish biomass within three years."}'::jsonb, '{"selected":"Established"}'::jsonb, NULL, NULL, 'Kawasan konservasi laut (''the marine reserve'') didirikan (pasif), sehingga memakai Past Participle ''Established''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000219', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'listening', 'listening_choice', 'Evaluasi Unit 7 — Dengarkan koreksi editor jurnal ilmiah. Perbaikan apa yang diminta?', '{"options":[{"id":"opt_1","text":"Menghapus seluruh data ketinggian dari paragraf kedua"},{"id":"opt_2","text":"Memastikan subjek tepat setelah koma benar-benar objek yang diukur oleh klausa partisip pembukanya"},{"id":"opt_3","text":"Mengganti seluruh kalimat pasif menjadi pertanyaan retoris"},{"id":"opt_4","text":"Menambahkan lebih banyak kata sambung ''and'' di setiap baris"}],"audio_text":"In paragraph two, ''Measured at high altitude, the athletes showed higher red blood cell counts'' works, whereas ''Measured at high altitude, oxygen levels...'' would change what was measured—keep the subject aligned!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Menegaskan ketepatan logis antara partisip pasif pembuka dan subjek klausa utama.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000220', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'writing', 'sentence_builder', 'Evaluasi Unit 7 — Susun kalimat tren eksekutif berpartisip:', '{"romaji":"/ˈdɪdʒɪtəl rɪˈmɪtəns ˈvɑːljuːm ɡruː ˈsɪksti pərˈsɛnt ˌaʊtˈpeɪsɪŋ trəˈdɪʃənəl ˈwaɪər ˈtrænsfɜːrz/","tokens":["wire transfers across ASEAN.","grew sixty percent,","outpaced by","growing into","Digital remittance volume","outpacing traditional"],"target_translation":"Volume remitansi digital tumbuh enam puluh persen, melampaui transfer kawat tradisional di seluruh ASEAN."}'::jsonb, '["Digital remittance volume","grew sixty percent,","outpacing traditional","wire transfers across ASEAN."]'::jsonb, NULL, NULL, ''', outpacing...'' menyatukan laju pertumbuhan dengan perbandingan kompetitifnya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000221', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'speaking', 'speaking_repeat', 'Evaluasi Unit 7 — Ucapkan kalimat laporan riset yang padat berikut:', '{"romaji":"/wʌns ˈkæləˌbreɪtɪd ˈprɑːpərli ði ˈɑːptɪkəl ˈsɛnsər dɪˈtɛkts ˈmɛθeɪn liːks frʌm ˈɔːrbɪt/","display_text":"Once calibrated properly, the optical sensor detects methane leaks from orbit.","phonetic_breakdown":["Once calibrated properly,","the optical sensor","detects methane leaks","from orbit."]}'::jsonb, '{"expected_transcript":"Once calibrated properly, the optical sensor detects methane leaks from orbit."}'::jsonb, NULL, NULL, 'Lafalkan ''methane'' ala Amerika /ˈmɛθeɪn/ (vokal pendek /ɛ/, bukan /ˈmiːθeɪn/ ala Inggris!).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000222', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Lengkapi kalimat kronologi proyek dengan Perfect Participle:', '{"options":["Having raised","Raised by","To raising","Being raise"],"translation":"Setelah berhasil menghimpun modal awal dari dua dana iklim, tim Agritech tersebut membangun pusat penyimpanan dingin tenaga surya pertamanya.","sentence_template":"[blank] seed capital from two climate funds, the Agritech team built its first solar cold-storage hub."}'::jsonb, '{"selected":"Having raised"}'::jsonb, NULL, NULL, '''Having raised'' menandai keberhasilan pendanaan yang mendahului pembangunan fasilitas.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000223', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'listening', 'listening_choice', 'Evaluasi Unit 7 — Dengarkan laporan kuartalan analis energi. Bagaimana pergerakan harga litium menurut audio?', '{"options":[{"id":"opt_1","text":"Perdagangan litium dihentikan sepenuhnya sejak tahun 2022"},{"id":"opt_2","text":"Harga litium tidak pernah berubah sedikit pun selama lima tahun"},{"id":"opt_3","text":"Setelah melonjak drastis pada 2022, harga litium terkoreksi tajam lalu mendatar di kisaran rata-rata historis kuartal ini"},{"id":"opt_4","text":"Harga litium terus mencetak rekor tertinggi baru pada kuartal ini"}],"audio_text":"Following a dramatic surge in 2022, spot lithium prices corrected sharply before plateauing near historical averages this quarter."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Rangkaian tiga fase grafik: ''surge'' → ''corrected sharply'' → ''before plateauing''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000224', 'e5100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000037', 'writing', 'sentence_builder', 'Evaluasi Unit 7 — Susun kalimat pembuka pasif ringkas berikut:', '{"romaji":"/dɪˈzaɪnd fɔːr ˈɔːflaɪn fɜːrst ˈfiːldˌwɜːrk ðə ˈmoʊbəl æp sɪŋks ˈsɜːrveɪ rɪˈspɑːnsɪz/","tokens":["synced whenever","fieldwork, the mobile app","whenever signal returns.","Designing for","Designed for offline-first","syncs survey responses"],"target_translation":"Dirancang untuk kerja lapangan luring-utama, aplikasi seluler tersebut menyinkronkan respons survei setiap kali sinyal kembali."}'::jsonb, '["Designed for offline-first","fieldwork, the mobile app","syncs survey responses","whenever signal returns."]'::jsonb, NULL, NULL, '''Designed for..., the mobile app syncs...'' menempatkan subjek yang dirancang tepat sesudah koma.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000225', 'e5100001-0000-4000-8000-000000000029', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat negosiasi kontrak vendor dengan pengikat syarat yang tepat:', '{"options":["provided that","despite that","whereas","in hindsight"],"translation":"Agensi kami dapat menyerahkan aplikasi seluler terlokalisasi sebelum November, dengan syarat seluruh aset merek tiba paling lambat hari Jumat.","sentence_template":"Our agency can deliver the localized mobile app by November, [blank] all brand assets arrive by Friday."}'::jsonb, '{"selected":"provided that"}'::jsonb, NULL, NULL, '''Provided that + Present Simple'' menetapkan syarat timbal balik yang tegas dan profesional.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000226', 'e5100001-0000-4000-8000-000000000029', NULL, 'reading', 'fill_blank', 'Pilih istilah manajemen proyek untuk penambahan fitur terus-menerus di luar kontrak awal:', '{"options":["scope creep","upticks","keystones","foresight"],"translation":"Klausul perubahan pesanan yang jelas melindungi konsultan perangkat lunak dari pembengkakan cakupan kerja tak berbayar.","sentence_template":"Clear change-order clauses protect software consultancies against unpaid [blank]."}'::jsonb, '{"selected":"scope creep"}'::jsonb, NULL, NULL, '''Scope creep'' adalah istilah baku industri untuk melebarnya tuntutan proyek tanpa penyesuaian anggaran.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000227', 'e5100001-0000-4000-8000-000000000029', NULL, 'listening', 'listening_choice', 'Dengarkan kandidat menegosiasikan paket kompensasi dengan rekruter AS. Alternatif apa yang ia ajukan?', '{"options":[{"id":"opt_1","text":"Meminta waktu sebulan untuk melamar ke perusahaan pesaing lainnya"},{"id":"opt_2","text":"Menolak tawaran kerja sepenuhnya karena gaji pokok tidak bisa dinaikkan"},{"id":"opt_3","text":"Meminta tambahan bonus penandatanganan sepuluh ribu dolar karena batas gaji pokok sudah mentok, dan siap langsung tanda tangan"},{"id":"opt_4","text":"Bersedia dipotong gaji pokoknya demi bekerja dari kantor pusat"}],"audio_text":"I understand the base salary is capped at this band—if there''s room to sweeten the offer with a ten-thousand-dollar sign-on bonus, I''m ready to sign today."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Strategi negosiasi elegan: mengakui batasan lawan (''base salary is capped''), menawarkan solusi alternatif (''sweeten the offer with a sign-on bonus''), dan menjanjikan kepastian penutupan (''ready to sign today'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000228', 'e5100001-0000-4000-8000-000000000029', NULL, 'writing', 'sentence_builder', 'Susun kalimat kompromi negosiasi harga berikut:', '{"romaji":"/sɪns ˈaʊər ˈbʌdʒɪts ɑːr tɛn pərˈsɛnt əˈpɑːrt kʊd wi miːt ˌhæfˈweɪ ɑːn ði ˈænjuəl ˈlaɪsəns/","tokens":["Since our budgets","meeting halfways","could we meet halfway","apart by ten","are ten percent apart,","on the annual license?"],"target_translation":"Karena selisih anggaran kita terpaut sepuluh persen, bisakah kita mengambil jalan tengah untuk biaya lisensi tahunan?"}'::jsonb, '["Since our budgets","are ten percent apart,","could we meet halfway","on the annual license?"]'::jsonb, NULL, NULL, '''Meet halfway on [item]'' mengajak kompromi timbal balik secara bersahabat.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000229', 'e5100001-0000-4000-8000-000000000029', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat negosiasi syarat ruang lingkup berikut dengan tenang dan berwibawa:', '{"romaji":"/wi kæn əˈkɑːməˌdeɪt ˈkʌstəm rɪˈpɔːrtɪŋ prəˈvaɪdɪd ðæt wi əˈdʒʌst ðə ˈmaɪlˌstoʊn ˈskɛdʒuːl/","display_text":"We can accommodate custom reporting, provided that we adjust the milestone schedule.","phonetic_breakdown":["We can accommodate","custom reporting,","provided that we adjust","the milestone schedule."]}'::jsonb, '{"expected_transcript":"We can accommodate custom reporting, provided that we adjust the milestone schedule."}'::jsonb, NULL, NULL, 'Lafalkan ''schedule'' ala Amerika /ˈskɛdʒuːl/ (diawali bunyi /sk/, bukan /ʃ/ ala Inggris!).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000230', 'e5100001-0000-4000-8000-000000000029', NULL, 'reading', 'fill_blank', 'Pilih kata benda yang menyatakan ''syarat mutlak yang menggagalkan kesepakatan jika tak terpenuhi'':', '{"options":["dealbreaker","digression","nitpick","plateau"],"translation":"Bagi klien rumah sakit Eropa, enkripsi ujung-ke-ujung adalah syarat penentu mutlak, bukan sekadar fitur tambahan.","sentence_template":"For European hospital clients, end-to-end encryption is an absolute [blank], not a nice-to-have feature."}'::jsonb, '{"selected":"dealbreaker"}'::jsonb, NULL, NULL, 'Dalam konteks syarat wajib, ketiadaan enkripsi menjadi ''dealbreaker'' (atau sifatnya ''non-negotiable'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000231', 'e5100001-0000-4000-8000-000000000029', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan negosiasi lisensi perangkat lunak. Apa konsesi timbal balik yang disepakati?', '{"options":[{"id":"opt_1","text":"Memberikan diskon lima belas persen sekaligus memperpanjang tempo bayar jadi sembilan puluh hari"},{"id":"opt_2","text":"Memberikan diskon tahun jamak lima belas persen dengan syarat pelunasan faktur dipercepat menjadi lima belas hari"},{"id":"opt_3","text":"Menaikkan tarif lisensi sebesar enam puluh persen untuk pembayaran bertahap"},{"id":"opt_4","text":"Membatalkan diskon karena klien menolak kontrak satu bulan"}],"audio_text":"We''re happy to lock in a fifteen percent multi-year discount on condition that invoice settlement happens within fifteen days rather than sixty."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''On condition that + S + V (present)'' mengikat pemberian diskon dengan percepatan arus kas.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000232', 'e5100001-0000-4000-8000-000000000029', NULL, 'writing', 'sentence_builder', 'Susun kalimat negosiasi fleksibilitas kerja jarak jauh berikut:', '{"romaji":"/aɪ kæn ˌoʊvərˈlæp fɔːr ˈaʊərz wɪð pəˈsɪfɪk taɪm æz lɔːŋ æz ˈfraɪdeɪz rɪˈmeɪn ˈmiːtɪŋ friː/","tokens":["as long as Fridays","overlapping into","will remain","hours with Pacific Time,","remain meeting-free.","I can overlap four"],"target_translation":"Saya dapat menyelaraskan empat jam kerja dengan Waktu Pasifik, selama hari Jumat tetap bebas rapat."}'::jsonb, '["I can overlap four","hours with Pacific Time,","as long as Fridays","remain meeting-free."]'::jsonb, NULL, NULL, 'Sesudah ''as long as'', gunakan Present Simple ''remain'' (bukan ''will remain'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000233', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Pilih kata kerja positif yang logis sesudah konjungsi eksklusif ''unless'':', '{"options":["does not grant","will not grant","grants","granting"],"translation":"Kumpulan data rahasia tidak boleh dibagikan kepada subkontraktor kecuali klien secara tegas memberikan persetujuan tertulis sebelumnya.","sentence_template":"Confidential datasets may not be shared with subcontractors unless the client explicitly [blank] prior written consent."}'::jsonb, '{"selected":"grants"}'::jsonb, NULL, NULL, 'Karena ''unless'' berarti ''if ... not'', kata kerja di dalamnya wajib positif Present Simple (''grants'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000234', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Pilih frasa hukum bisnis yang tepat sebelum kata benda ''a data breach'':', '{"options":["Provided that","As long as","In the event of","Unless"],"translation":"Apabila terjadi kebocoran keamanan, vendor wajib memberi tahu pelanggan korporat terdampak dalam waktu dua puluh empat jam.","sentence_template":"[blank] a security breach, the vendor must notify affected enterprise customers within twenty-four hours."}'::jsonb, '{"selected":"In the event of"}'::jsonb, NULL, NULL, '''In the event of + Noun Phrase'' adalah pembuka baku klausul penanganan insiden kontrak.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000235', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'listening', 'listening_choice', 'Dengarkan penjelasan penasihat hukum tentang draf Letter of Intent. Mengapa dokumen tersebut belum mengikat penuh?', '{"options":[{"id":"opt_1","text":"Ketentuan akuisisi awal tersebut masih bergantung pada hasil uji tuntas yang memuaskan serta izin regulator"},{"id":"opt_2","text":"Perusahaan wajib membayar denda pembatalan hari ini juga"},{"id":"opt_3","text":"Proses uji tuntas telah dibatalkan oleh kedua belah pihak"},{"id":"opt_4","text":"Akuisisi sudah sah sepenuhnya tanpa memerlukan izin regulator"}],"audio_text":"Keep in mind that these preliminary acquisition terms remain subject to satisfactory due diligence and regulatory clearance."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Remain subject to X and Y'' menandakan kesepakatan baru berlaku efektif apabila X dan Y terpenuhi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000236', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'writing', 'sentence_builder', 'Susun kalimat klausul perpanjangan langganan berikut:', '{"romaji":"/ˈɛntərˌpraɪz siːts rɪˈnuː ˈænjuəli ʌnˈlɛs ˈkænsəld ɪn ˈraɪtɪŋ ˈθɜːrti deɪz bɪˈfɔːr ˌɛkspəˈreɪʃən/","tokens":["Enterprise seats renew","canceling into","annually unless canceled","before expiration.","unless not canceled","in writing thirty days"],"target_translation":"Lisensi kursi korporat diperpanjang setiap tahun kecuali dibatalkan secara tertulis tiga puluh hari sebelum masa berakhir."}'::jsonb, '["Enterprise seats renew","annually unless canceled","in writing thirty days","before expiration."]'::jsonb, NULL, NULL, 'Ejaan Amerika standar memakai satu huruf ''l'' pada ''canceled'', dalam struktur reduced clause ''unless canceled''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000237', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'speaking', 'speaking_repeat', 'Ucapkan kalimat klausul negosiasi berikut dengan artikulasi yang jernih:', '{"romaji":"/ɔːl prəˈpoʊzd ˈtaɪmˌlaɪn əˈdʒʌstmənts rɪˈmeɪn ˈsʌbdʒɪkt tə ˈstɪrɪŋ kəˈmɪti ˈsaɪnˌɔːf/","display_text":"All proposed timeline adjustments remain subject to steering committee sign-off.","phonetic_breakdown":["All proposed","timeline adjustments","remain subject to","steering committee sign-off."]}'::jsonb, '{"expected_transcript":"All proposed timeline adjustments remain subject to steering committee sign-off."}'::jsonb, NULL, NULL, 'Perhatikan tekanan kata sifat ''SUB-ject to'' (/ˈsʌbdʒɪkt/), berbeda dari verba ''sub-JECT'' (/səbˈdʒɛkt/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000238', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Pilih ejaan kata kerja hukum yang berarti ''membebaskan biaya denda keterlambatan'':', '{"options":["weigh","wave","waive","weave"],"translation":"Sebagai bentuk iktikad baik seusai gangguan sistem perbankan, pemilik gedung setuju membebaskan biaya keterlambatan bulan ini.","sentence_template":"As a goodwill gesture after the banking outage, the landlord agreed to [blank] this month''s late payment fee."}'::jsonb, '{"selected":"waive"}'::jsonb, NULL, NULL, '''Waive a fee / right / penalty'' berarti secara resmi melepaskan tuntutan atas biaya atau hak tersebut.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000239', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'listening', 'listening_choice', 'Dengarkan percakapan dua manajer proyek tentang dana cadangan (''contingency buffer''). Mengapa mereka menyisihkan 15% anggaran?', '{"options":[{"id":"opt_1","text":"Lima belas persen anggaran dipakai untuk bonus liburan tim"},{"id":"opt_2","text":"Bea cukai sudah menjamin tarif tidak akan berubah sepanjang tahun"},{"id":"opt_3","text":"Dana cadangan disisihkan sejak sekarang sebagai langkah antisipasi kalau-kalau tarif bea cukai berubah di tengah kuartal"},{"id":"opt_4","text":"Dana baru akan dicari setelah tarif bea cukai benar-benar naik bulan depan"}],"audio_text":"We keep a fifteen percent contingency reserve in case customs tariffs shift mid-quarter—not only if they shift, we set it aside upfront!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Menjelaskan perbedaan krusial ''in case'' (tindakan berjaga-jaga dilakukan di muka) vs. ''if'' (tindakan menunggu syarat terjadi).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000240', 'e5100001-0000-4000-8000-000000000030', 'e2000001-0000-4000-8000-000000000038', 'writing', 'sentence_builder', 'Susun kalimat klausul penghentian proyek berikut:', '{"romaji":"/ɪn ði ɪˈvɛnt ðæt ˈfʌndɪŋ fɔːlz θruː boʊθ ˈpɑːrtiz meɪ ˈtɜːrməˌneɪt wɪˈðaʊt ˈpɛnəlti/","tokens":["both parties may","In the event that","terminating into","funding falls through,","terminate without penalty.","In the event of"],"target_translation":"Apabila pendanaan batal terwujud, kedua belah pihak dapat mengakhiri kontrak tanpa denda."}'::jsonb, '["In the event that","funding falls through,","both parties may","terminate without penalty."]'::jsonb, NULL, NULL, 'Karena diikuti klausa lengkap S + V (''funding falls through''), gunakan ''In the event that'' (bukan ''In the event of'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000241', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Lengkapi kalimat advokasi sopan mahasiswa kepada koordinator hibah kampus:', '{"options":["devil''s advocate","scope creep","single failure","wiggle room"],"translation":"Mengingat kenaikan tarif tiket pesawat internasional, saya ingin menanyakan apakah sekiranya ada sedikit kelonggaran pada batas tunjangan perjalanan konferensi.","sentence_template":"Given the international airfare hike, I was wondering if there might be any [blank] in the conference travel stipend."}'::jsonb, '{"selected":"wiggle room"}'::jsonb, NULL, NULL, '''Wiggle room'' adalah idiom sopan dan alami di kampus/kantor AS untuk menanyakan fleksibilitas batas aturan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000242', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Pilih susunan kata yang gramatikal sesudah pembuka sopan ''I was hoping'':', '{"options":["may to","can to","could","will can"],"translation":"Berhubung saya menerima tawaran riset serupa di Chicago, saya berharap pihak jurusan sekiranya dapat menyamakan tunjangan musim panas tersebut.","sentence_template":"Since I received a parallel research offer in Chicago, I was hoping the department [blank] match the summer stipend."}'::jsonb, '{"selected":"could"}'::jsonb, NULL, NULL, 'Pembuka lampau penghalus ''I was hoping'' selaras dengan modal lampau ''could / might + V1''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000243', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'listening', 'listening_choice', 'Dengarkan percakapan mahasiswa dengan administrator asrama (TOEFL Campus Conversation). Bagaimana solusi yang disepakati?', '{"options":[{"id":"opt_1","text":"Pihak asrama bersedia memberi pengecualian dan membebaskan denda pindah asrama asalkan mahasiswa menyerahkan memo dosen pembimbing"},{"id":"opt_2","text":"Mahasiswa tetap wajib membayar denda penuh tanpa pengecualian apa pun"},{"id":"opt_3","text":"Permohonan pindah asrama ditolak karena seluruh kamar sudah penuh"},{"id":"opt_4","text":"Praktikum laboratorium mahasiswa dipindahkan kembali ke kampus utama"}],"audio_text":"Normally late housing changes incur a fee, but since your lab practicum moved to the medical campus, we can make an exception and waive it provided you submit your advisor''s memo."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menggabungkan tiga frasa kunci unit ini dalam konteks TOEFL asli: ''incur a fee'', ''make an exception and waive it'', dan ''provided you submit...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000244', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'writing', 'sentence_builder', 'Susun kalimat permohonan pendanaan konferensi yang santun:', '{"romaji":"/baɪ ˈʃɛrɪŋ hoʊˈtɛl ruːmz ˈaʊər roʊˈbɑːtɪks tiːm kæn strɛtʃ ðə ɡrænt tə ˈkʌvər fɔːr prɪˈzɛntərz/","tokens":["stretching into","can stretch the grant","covered four","By sharing hotel rooms,","our robotics team","to cover four presenters."],"target_translation":"Dengan berbagi kamar hotel, tim robotika kami dapat memaksimalkan dana hibah agar mencukupi empat pemakalah."}'::jsonb, '["By sharing hotel rooms,","our robotics team","can stretch the grant","to cover four presenters."]'::jsonb, NULL, NULL, '''Stretch the grant / budget to cover X'' menunjukkan inisiatif penghematan sebelum meminta dana ekstra.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000245', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'speaking', 'speaking_repeat', 'Ucapkan kalimat negosiasi beasiswa/riset berikut dengan pelafalan ''leverage'' ala Amerika:', '{"romaji":"/aɪ wʌz ˈwʌndərɪŋ ɪf aɪ kʊd ˈlɛvərɪdʒ maɪ ˈtiːtʃɪŋ ɪkˈspɪriəns fɔːr ə tuˈɪʃən ˈweɪvər/","display_text":"I was wondering if I could leverage my teaching experience for a tuition waiver.","phonetic_breakdown":["I was wondering","if I could leverage","my teaching experience","for a tuition waiver."]}'::jsonb, '{"expected_transcript":"I was wondering if I could leverage my teaching experience for a tuition waiver."}'::jsonb, NULL, NULL, 'Lafalkan ''leverage'' /ˈlɛvərɪdʒ/ dan ''tuition'' /tuˈɪʃən/ secara mulus dengan intonasi sopan.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000246', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Pilih kolokasi yang tepat untuk pemberian pengecualian kebijakan akademik:', '{"options":["stemmed the tide","incurred a debt","made an exception","jumped the gun"],"translation":"Meskipun seminar pascasarjana membatasi peserta maksimal dua belas orang, Profesor Lin memberikan pengecualian bagi penerima beasiswa tamu Fulbright.","sentence_template":"Although graduate seminars cap enrollment at twelve, Professor Lin [blank] for visiting Fulbright fellows."}'::jsonb, '{"selected":"made an exception"}'::jsonb, NULL, NULL, '''Make an exception for [someone]'' adalah kolokasi baku untuk dispensasi aturan resmi.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000247', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'listening', 'listening_choice', 'Dengarkan saran penasihat karier kampus AS kepada mahasiswa doktoral. Apa yang disarankan saat menerima tawaran kerja pertama?', '{"options":[{"id":"opt_1","text":"Ucapkan terima kasih dengan antusias, minta rincian tunjangan tertulis, dan ambil waktu 48 jam untuk membandingkan standar pasar"},{"id":"opt_2","text":"Langsung menyetujui angka gaji pertama pada detik itu juga lewat telepon"},{"id":"opt_3","text":"Mengabaikan komponen saham dan asuransi kesehatan dalam kontrak"},{"id":"opt_4","text":"Mengancam akan membatalkan lamaran jika gaji tidak digandakan"}],"audio_text":"Never accept the initial base number on the spot—thank them enthusiastically, ask for the full benefits breakdown in writing, and take forty-eight hours to benchmark."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Etika profesional negosiasi AS: antusiasme positif + meminta penawaran tertulis + riset patokan pasar (*benchmark*).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000248', 'e5100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000038', 'writing', 'sentence_builder', 'Susun kalimat advokasi sopan di kantor akademik berikut:', '{"romaji":"/aɪ wʌz ˈwʌndərɪŋ ˈwɛðər ðə ˈfɛloʊˌʃɪp maɪt ˈkʌvər ɑːrˈkaɪvəl ˈfiːldˌwɜːrk ɪn ˈlaɪdən/","tokens":["might cover archival","whether the fellowship","might covering","fieldwork in Leiden.","was wondered","I was wondering"],"target_translation":"Saya ingin menanyakan apakah beasiswa riset tersebut sekiranya dapat menanggung biaya penelitian arsip lapangan di Leiden."}'::jsonb, '["I was wondering","whether the fellowship","might cover archival","fieldwork in Leiden."]'::jsonb, NULL, NULL, '''I was wondering whether + S + might + V1'' adalah standar emas kesopanan korespondensi akademik.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000249', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih bentuk kata kerja yang tepat sesudah ''provided that'':', '{"options":["executes","would executed","will execute","executing"],"translation":"Kami dapat menyertakan dua puluh jam pelatihan pascapeluncuran, dengan syarat klien menandatangani perjanjian layanan induk paling lambat hari Rabu.","sentence_template":"We can include twenty hours of post-launch training, provided that the client [blank] the master services agreement by Wednesday."}'::jsonb, '{"selected":"executes"}'::jsonb, NULL, NULL, 'Klausa syarat ''provided that'' memakai Present Simple (''executes'' = menandatangani/mengesahkan kontrak), bukan ''will''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000250', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih kata kerja dengan ejaan tepat untuk ''membebaskan biaya denda'':', '{"options":["waive","weigh","weave","wave"],"translation":"Biro administrasi akademik setuju membebaskan denda keterlambatan registrasi karena portal kampus sempat tumbang malam itu.","sentence_template":"The registrar agreed to [blank] the late-registration penalty because the portal had crashed that evening."}'::jsonb, '{"selected":"waive"}'::jsonb, NULL, NULL, '''Waive a penalty'' = membebaskan sanksi denda secara resmi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000251', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'listening', 'listening_choice', 'Evaluasi Unit 8 — Dengarkan negosiasi antara konsultan produk dan klien. Bagaimana konsultan mencegah ''scope creep''?', '{"options":[{"id":"opt_1","text":"Mengerjakan fitur tambahan secara gratis sambil menunda peluncuran utama"},{"id":"opt_2","text":"Menghapus fitur utama hari Jumat demi mengerjakan ekspor analitik"},{"id":"opt_3","text":"Menyambut permintaan fitur baru namun memasukkannya sebagai pesanan perubahan Fase Dua agar peluncuran inti hari Jumat tidak molor"},{"id":"opt_4","text":"Menolak berbicara dengan klien hingga proyek selesai sepenuhnya"}],"audio_text":"We''d love to build that custom analytics export too—as long as we log it as a Phase Two change order so Friday''s core launch stays on track."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Cara paling elegan menolak *scope creep*: katakan ''Yes, and here is the Phase 2 trade-off'' menggunakan ''as long as''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000252', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'writing', 'sentence_builder', 'Evaluasi Unit 8 — Susun kalimat klausul kontrak dengan ''unless'':', '{"romaji":"/ˌɪntəˈlɛktʃuəl ˈprɑːpərti rɪˈmeɪnz wɪð ðə kriˈeɪtər ʌnˈlɛs ɪkˈsplɪsɪtli əˈsaɪnd/","tokens":["Intellectual property remains","with the creator","unless not assigned","in the written contract.","assigning into","unless explicitly assigned"],"target_translation":"Hak kekayaan intelektual tetap menjadi milik pencipta kecuali dialihkan secara tegas di dalam kontrak tertulis."}'::jsonb, '["Intellectual property remains","with the creator","unless explicitly assigned","in the written contract."]'::jsonb, NULL, NULL, 'Reduced conditional clause ''unless explicitly assigned'' ringkas dan presisi secara hukum.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000253', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'speaking', 'speaking_repeat', 'Evaluasi Unit 8 — Ucapkan kalimat negosiasi kompensasi berikut dengan percaya diri:', '{"romaji":"/ɪf wi kæn miːt ˌhæfˈweɪ ɑːn ˈɛkwəti aɪm ˈrɛdi tə saɪn ði ˈɔːfər təˈdeɪ/","display_text":"If we can meet halfway on equity, I''m ready to sign the offer today.","phonetic_breakdown":["If we can","meet halfway on equity,","I''m ready to sign","the offer today."]}'::jsonb, '{"expected_transcript":"If we can meet halfway on equity, I''m ready to sign the offer today."}'::jsonb, NULL, NULL, 'Nada hangat dan pasti pada ''I''m ready to sign the offer today'' memberi kepastian bagi rekruter.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000254', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih frasa pembuka untuk skenario wanprestasi sebelum frasa nomina:', '{"options":["As long as","In the event that","In the event of","Provided that"],"translation":"Apabila terjadi gagal bayar yang melebihi empat puluh lima hari, penyedia berhak menangguhkan akses API.","sentence_template":"[blank] non-payment exceeding forty-five days, the provider reserves the right to suspend API access."}'::jsonb, '{"selected":"In the event of"}'::jsonb, NULL, NULL, 'Karena diikuti frasa nomina (''non-payment...''), wajib menggunakan ''In the event of''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000255', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'listening', 'listening_choice', 'Evaluasi Unit 8 — Dengarkan mahasiswa pascasarjana berbicara dengan ketua jurusan. Apa yang sedang dilakukan mahasiswa?', '{"options":[{"id":"opt_1","text":"Meminta pembebasan seluruh kewajiban riset selama masa kuliah"},{"id":"opt_2","text":"Menegosiasikan tambahan tunjangan perjalanan riset secara sopan dengan merujuk pada tawaran pembanding dari Michigan"},{"id":"opt_3","text":"Mengeluhkan fasilitas laboratorium yang dianggap kurang memadai"},{"id":"opt_4","text":"Mengundurkan diri dari program pascasarjana karena pindah ke Michigan"}],"audio_text":"Thank you so much for the admission offer! I was wondering if there might be any wiggle room to match the research travel allowance offered by Michigan."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Mengaplikasikan ''I was wondering if there might be any wiggle room'' + memanfaatkan *competing offer* secara santun.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000256', 'e5100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000038', 'writing', 'sentence_builder', 'Evaluasi Unit 8 — Susun kalimat cadangan risiko proyek dengan ''in case'':', '{"romaji":"/wi prəˈvɪʒənd ˈbækʌp klaʊd ˈriːdʒənz ˈʌpˌfrʌnt ɪn keɪs ˈʌndərˌwɔːtər ˈkeɪbəlz ˈsʌfər stɔːrm ˈdæmɪdʒ/","tokens":["suffer storm damage.","suffering into","in case underwater cables","We provisioned backup","only if cables","cloud regions upfront"],"target_translation":"Kami menyiapkan wilayah cloud cadangan sejak awal untuk berjaga-jaga kalau-kalau kabel bawah laut mengalami kerusakan badai."}'::jsonb, '["We provisioned backup","cloud regions upfront","in case underwater cables","suffer storm damage."]'::jsonb, NULL, NULL, 'Tindakan dilakukan ''upfront'' sebagai antisipasi sebelum kejadian, sehingga wajib memakai ''in case''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000257', 'e5100001-0000-4000-8000-000000000033', NULL, 'reading', 'fill_blank', 'Pilih kata kerja akademik yang tepat ketika pembaca menarik simpulan logis dari bukti tersirat:', '{"options":["imply","incur","waive","infer"],"translation":"Dari hilangnya perkakas perunggu secara mendadak di Lapisan IV, para arkeolog dapat menyimpulkan bahwa jalur perdagangan telah terputus.","sentence_template":"From the sudden disappearance of bronze tools in Layer IV, archaeologists can [blank] that trade routes had been disrupted."}'::jsonb, '{"selected":"infer"}'::jsonb, NULL, NULL, 'Peneliti/pembaca menarik simpulan (''infer'') dari data, sedangkan data/penulis menyiratkan (''imply'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000258', 'e5100001-0000-4000-8000-000000000033', NULL, 'reading', 'fill_blank', 'Pilih kata sifat yang menggambarkan dua hipotesis yang tidak bisa benar bersamaan:', '{"options":["non-negotiable","counterintuitive to","mutually exclusive","blameless"],"translation":"Ahli geologi awal mengira erosi bertahap dan banjir besar saling meniadakan, namun stratigrafi modern menunjukkan keduanya sama-sama membentuk ngarai.","sentence_template":"Early geologists assumed gradual erosion and catastrophic floods were [blank], yet modern stratigraphy shows both shaped canyons."}'::jsonb, '{"selected":"mutually exclusive"}'::jsonb, NULL, NULL, '''Mutually exclusive'' berarti dua hal tidak mungkin hadir atau benar pada saat yang bersamaan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000259', 'e5100001-0000-4000-8000-000000000033', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan instruktur persiapan TOEFL. Mengapa pilihan jawaban B pada soal inferensi tersebut salah?', '{"options":[{"id":"opt_1","text":"Pilihan B terlalu pendek sehingga tidak memenuhi standar akademik"},{"id":"opt_2","text":"Bacaan aslinya tidak membahas amfibi maupun pernapasan sama sekali"},{"id":"opt_3","text":"Kata mutlak ''solely'' (semata-mata) melebih-lebihkan isi bacaan yang hanya menyebut pernapasan kulit sebagai pelengkap"},{"id":"opt_4","text":"Amfibi sama sekali tidak mampu bernapas melalui kulit di air dingin"}],"audio_text":"Notice choice B says amphibians rely solely on skin respiration—the passage only said cutaneous breathing supplements lung use in cold water, so ''solely'' goes way too far!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Mengenali jebakan *extreme modifier* (''solely'', ''only'', ''never'') adalah kunci utama meraih skor 28–30 di TOEFL Reading.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000260', 'e5100001-0000-4000-8000-000000000033', NULL, 'writing', 'sentence_builder', 'Susun kalimat pembuktian ilmiah menggunakan verba ''substantiate'':', '{"romaji":"/ˈaɪsəˌtoʊp ˈreɪʃioʊz ɪn ˈeɪnʃənt tuːθ ɪˈnæməl səbˈstænʃiˌeɪt ðə kleɪm/","tokens":["substantiating into","claims by","substantiate the claim","of seasonal migration.","ancient tooth enamel","Isotope ratios in"],"target_translation":"Rasio isotop pada email gigi purba membuktikan klaim mengenai migrasi musiman."}'::jsonb, '["Isotope ratios in","ancient tooth enamel","substantiate the claim","of seasonal migration."]'::jsonb, NULL, NULL, '''Substantiate the claim'' menghubungkan bukti empiris laboratorium dengan argumen utama.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000261', 'e5100001-0000-4000-8000-000000000033', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat analisis bacaan akademik berikut dengan artikulasi yang jernih:', '{"romaji":"/haɪ ˈlɪtərəsi reɪts ɪn pɔːrt ˈsɪtiz ɪmˈplaɪ ðæt kəˈmɜːrʃəl ˈkɑːntrækts droʊv ˈskuːlɪŋ/","display_text":"High literacy rates in port cities imply that commercial contracts drove schooling.","phonetic_breakdown":["High literacy rates","in port cities","imply that commercial contracts","drove schooling."]}'::jsonb, '{"expected_transcript":"High literacy rates in port cities imply that commercial contracts drove schooling."}'::jsonb, NULL, NULL, 'Fakta sejarah menyiratkan (''imply'') kesimpulan kausal bahwa kontrak dagang mendorong pendidikan.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000262', 'e5100001-0000-4000-8000-000000000033', NULL, 'reading', 'fill_blank', 'Pilih kata kerja yang berarti ''sudah ada mendahului suatu peristiwa waktu'':', '{"options":["outpaced","waived","predated","plateaued"],"translation":"Budidaya ubi jalar Polinesia di Pasifik sudah ada beberapa abad mendahului kontak pelayaran bangsa Eropa.","sentence_template":"Polynesian sweet potato cultivation in the Pacific [blank] European maritime contact by several centuries."}'::jsonb, '{"selected":"predated"}'::jsonb, NULL, NULL, '''Predate + Object'' berarti terjadi atau hadir pada era sebelum objek tersebut ada.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000263', 'e5100001-0000-4000-8000-000000000033', NULL, 'listening', 'listening_choice', 'Dengarkan diskusi bedah artikel jurnal. Mengapa penulis menyertakan paragraf tentang kegagalan teleskop awal?', '{"options":[{"id":"opt_1","text":"Menyoroti alasan mengapa masalah aberasi baru dapat terpecahkan setelah teleskop cermin ditemukan"},{"id":"opt_2","text":"Menyarankan astronom modern kembali memakai lensa kaca abad ke-17"},{"id":"opt_3","text":"Menjelaskan biaya pembuatan kacamata baca di Italia masa kini"},{"id":"opt_4","text":"Membuktikan bahwa Galileo gagal memberikan kontribusi bagi astronomi"}],"audio_text":"The author doesn''t mention blurry seventeenth-century lenses to criticize Galileo, but rather to highlight why atmospheric aberration remained unsolved until mirror telescopes appeared."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menjawab soal *Rhetorical Purpose* (''Why does the author mention X?''): perhatikan pola ''not to X, but rather to highlight Y''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000264', 'e5100001-0000-4000-8000-000000000033', NULL, 'writing', 'sentence_builder', 'Susun kalimat evaluasi hipotesis yang masuk akal:', '{"romaji":"/vɑːlˈkænɪk æʃ ˈleɪərz ˈɔːfər ə ˈplɔːzəbəl ˌɛkspləˈneɪʃən fɔːr ði əˈbrʌpt ˈhɑːrvɪst ˈfeɪljər/","tokens":["Volcanic ash layers","plausibly explain to","explanation for the","abrupt harvest failure.","failing harvest","offer a plausible"],"target_translation":"Lapisan abu vulkanik memberikan penjelasan yang masuk akal atas kegagalan panen mendadak tersebut."}'::jsonb, '["Volcanic ash layers","offer a plausible","explanation for the","abrupt harvest failure."]'::jsonb, NULL, NULL, '''Offer a plausible explanation for + Noun Phrase'' adalah struktur esai akademik standar tinggi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000265', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Pilih kata sambung mekanisme formal yang berarti ''yang melaluinya / dengan cara mana'':', '{"options":["unless","whereas","whereby","albeit"],"translation":"Perundingan bersama adalah kerangka hukum yang melaluinya serikat pekerja dan pemberi kerja menegosiasikan standar keselamatan serta upah.","sentence_template":"Collective bargaining is the legal framework [blank] unions and employers negotiate safety standards and wages."}'::jsonb, '{"selected":"whereby"}'::jsonb, NULL, NULL, '''Whereby'' (= by which / through which) menghubungkan kata benda proses/sistem/kerangka dengan cara kerjanya.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000266', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Temukan kata kerja utama yang selaras dengan subjek jamak ''Ancient irrigation canals'' setelah sisipan aposisi panjang:', '{"options":["being","is","was been","are"],"translation":"Kanal irigasi kuno—sebuah keajaiban rekayasa yang membentang empat puluh mil melintasi gurun—masih terlihat pada citra satelit.","sentence_template":"Ancient irrigation canals—an engineering marvel spanning forty miles of desert—[blank] still visible in satellite imagery."}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, 'Jangan terkecoh nomina tunggal ''an engineering marvel'' di dalam aposisi tanda pisah; subjek sejatinya adalah jamak ''Ancient irrigation canals'' → ''are''!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000267', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'listening', 'listening_choice', 'Dengarkan penjelasan strategi ''Sentence Simplification'' TOEFL. Mengapa parafrasa A dipilih sebagai jawaban benar?', '{"options":[{"id":"opt_1","text":"Pilihan A mempertahankan hubungan sebab-akibat inti kalimat asli tanpa terganggu rincian contoh di dalam tanda pisah"},{"id":"opt_2","text":"Pilihan A menambahkan klaim baru bahwa sensor tersebut tahan air"},{"id":"opt_3","text":"Pilihan A menghapus dampak kelembapan tinggi terhadap akurasi sensor"},{"id":"opt_4","text":"Pilihan A menyalin ketiga merek sensor secara persis tapi membalikkan sebab dan akibat"}],"audio_text":"Even though the original sentence lists three sensor brands inside dashes, its core cause-and-effect is simple: high humidity degraded calibration accuracy—and Choice A preserves both that cause and that effect."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pada TOEFL Sentence Simplification, jawaban benar selalu menjaga relasi logis utama (sebab-akibat/kontras) dan mengabaikan daftar contoh minor.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000268', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'writing', 'sentence_builder', 'Susun kalimat mekanisme biologi menggunakan ''whereby'':', '{"romaji":"/ˈnaɪtrədʒən fɪkˈseɪʃən ɪz ðə ˈkɛmɪkəl ˈprɑːsɛs wɛrˈbaɪ sɔɪl bækˈtɪriə kənˈvɜːrt/","tokens":["convert atmospheric gas","into plant nutrients.","whereas bacteria","whereby soil bacteria","Nitrogen fixation is","the chemical process","converting into"],"target_translation":"Fiksasi nitrogen adalah proses kimia yang melaluinya bakteri tanah mengubah gas atmosfer menjadi nutrisi tanaman."}'::jsonb, '["Nitrogen fixation is","the chemical process","whereby soil bacteria","convert atmospheric gas","into plant nutrients."]'::jsonb, NULL, NULL, '''The process whereby + Subject + Verb'' adalah definisi ilmiah berstandar publikasi.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000269', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'speaking', 'speaking_repeat', 'Ucapkan kalimat dengan sisipan penegas ''chief among them'' berikut:', '{"romaji":"/ˈmʌltəpəl ˈfæktərz tʃiːf əˈmʌŋ ðɛm ˈraɪzɪŋ ˈoʊʃən ˈtɛmprətʃərz bliːtʃt ðə riːf/","display_text":"Multiple factors, chief among them rising ocean temperatures, bleached the reef.","phonetic_breakdown":["Multiple factors,","chief among them","rising ocean temperatures,","bleached the reef."]}'::jsonb, '{"expected_transcript":"Multiple factors, chief among them rising ocean temperatures, bleached the reef."}'::jsonb, NULL, NULL, 'Turunkan nada sedikit saat membaca sisipan ''chief among them rising ocean temperatures,'' lalu kembali ke nada utama pada ''bleached the reef''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000270', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Pilih preposisi + kata ganti relatif yang tepat sesudah verba ''depend (on)'':', '{"options":["in that","whereby of","on which","which"],"translation":"Gletser alpen berfungsi sebagai menara air alami yang kepadanya jutaan petani hilir bergantung selama musim panas kering.","sentence_template":"Alpine glaciers act as natural water towers [blank] millions of downstream farmers depend during dry summers."}'::jsonb, '{"selected":"on which"}'::jsonb, NULL, NULL, 'Karena kata kerjanya ''depend on [water towers]'', bentuk relatif formalnya memindahkan preposisi ke depan: ''on which ... depend''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000271', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'listening', 'listening_choice', 'Dengarkan cuplikan bacaan sejarah cetak yang dibacakan dosen. Apa inti kalimat panjang tersebut?', '{"options":[{"id":"opt_1","text":"Piagam kerajaan berhasil melindungi monopoli serikat selamanya"},{"id":"opt_2","text":"Impor kertas meningkat pesat berkat dukungan serikat pekerja"},{"id":"opt_3","text":"Pabrik daerah dilarang memproduksi kertas berbahan kain perca"},{"id":"opt_4","text":"Monopoli serikat percetakan runtuh cepat begitu pabrik kertas daerah menguasai produksi bubur kain perca"}],"audio_text":"Guild monopolies—long shielded by royal charters that restricted paper imports—crumbled rapidly once provincial mills mastered rag-pulp manufacturing."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Tulang punggung kalimat di luar tanda pisah adalah ''Guild monopolies crumbled rapidly once provincial mills mastered...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000272', 'e5100001-0000-4000-8000-000000000034', 'e2000001-0000-4000-8000-000000000039', 'writing', 'sentence_builder', 'Susun kalimat dengan frasa penegas ''chief among them'':', '{"romaji":"/θriː ˈbreɪkˌθruːz tʃiːf əˈmʌŋ ðɛm ˈsɑːlɪd steɪt ɪˈlɛktrəˌlaɪts ɪkˈstɛndɪd ˈbætəri ˈlaɪfˌspæn/","tokens":["chief among them","solid-state electrolytes,","chiefly them","extending into","Three breakthroughs,","extended battery lifespan."],"target_translation":"Tiga terobosan, yang paling utama di antaranya elektrolit padat, memperpanjang masa pakai baterai."}'::jsonb, '["Three breakthroughs,","chief among them","solid-state electrolytes,","extended battery lifespan."]'::jsonb, NULL, NULL, 'Aposisi ''chief among them + Noun Phrase'' diapit koma di antara subjek dan verba utama.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000273', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Pilih kata kerja formal yang berarti ''menggarisbawahi pentingnya'':', '{"options":["nitpick","underscore","waive","digress"],"translation":"Pengukuran penyusutan gletser terbaru menggarisbawahi mendesaknya pemangkasan emisi jelaga karbon hitam.","sentence_template":"Recent glacier retreat measurements [blank] the urgency of cutting black-carbon soot emissions."}'::jsonb, '{"selected":"underscore"}'::jsonb, NULL, NULL, '''Underscore the urgency / significance'' menegaskan bobot suatu bukti ilmiah.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000274', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Pilih pembuka sintesis yang menyatukan beberapa temuan paragraf menjadi satu simpulan:', '{"options":["Unless notified","Mutually exclusive","Taken together","In hindsight"],"translation":"Jika dilihat secara keseluruhan, keramik arkeologis dan kata serapan bahasa menunjukkan perdagangan maritim berkelanjutan melintasi Laut Jawa.","sentence_template":"[blank], archaeological ceramics and linguistic loanwords indicate sustained maritime trade across the Java Sea."}'::jsonb, '{"selected":"Taken together"}'::jsonb, NULL, NULL, '''Taken together,'' menyatukan berbagai lini bukti menjadi satu *overarching thesis*.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000275', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'listening', 'listening_choice', 'Dengarkan tutor TOEFL mengevaluasi pilihan jawaban siswa pada soal Prose Summary. Mengapa pilihan D harus dicoret?', '{"options":[{"id":"opt_1","text":"Meskipun angkanya benar sesuai teks, pernyataan tersebut hanya rincian pendukung sempit dari satu kalimat, bukan ide utama bacaan"},{"id":"opt_2","text":"Paragraf kedua sama sekali tidak menyinggung peleburan tembaga"},{"id":"opt_3","text":"Suhu peleburan tembaga di dalam teks sebenarnya seribu lima ratus derajat"},{"id":"opt_4","text":"Semua pilihan yang mengandung kata benda sains wajib dipilih di ringkasan"}],"audio_text":"Choice D accurately states that copper smelters reached eleven hundred degrees Celsius, but that''s a single sentence detail in paragraph two, not a major point of the passage."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Membedakan *major idea* dari *true-but-minor detail* adalah kunci meraih 2/2 poin pada soal Prose Summary TOEFL.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000276', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'writing', 'sentence_builder', 'Susun kalimat sintesis penutup artikel ilmiah berikut:', '{"romaji":"/ˈteɪkən təˈɡɛðər ðiːz θriː ˈstʌdiz ˌʌndərˈskɔːr haʊ sliːp kənˈsɑːləˌdeɪts prəˈsiːdʒərəl ˈmɛməri/","tokens":["these three studies","consolidates procedural memory.","underscore how sleep","underscoring into","how does sleep","Taken together,"],"target_translation":"Jika dilihat bersama-sama, ketiga studi ini menggarisbawahi bagaimana tidur mengonsolidasikan memori prosedural."}'::jsonb, '["Taken together,","these three studies","underscore how sleep","consolidates procedural memory."]'::jsonb, NULL, NULL, '''Taken together, + S + underscore + embedded clause (how + S + V)''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000277', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'speaking', 'speaking_repeat', 'Ucapkan kalimat gagasan payung (overarching thesis) berikut dengan jelas:', '{"romaji":"/ði ˌoʊvərˈɑːrtʃɪŋ ˈθiːsɪs ˈɑːrɡjuːz ðæt kəˈnæl ˈnɛtˌwɜːrks trænsˈfɔːrmd ˈriːdʒənəl ˈæɡrɪˌkʌltʃər/","display_text":"The overarching thesis argues that canal networks transformed regional agriculture.","phonetic_breakdown":["The overarching thesis","argues that","canal networks transformed","regional agriculture."]}'::jsonb, '{"expected_transcript":"The overarching thesis argues that canal networks transformed regional agriculture."}'::jsonb, NULL, NULL, 'Perhatikan tekanan kata ''kə-NAL'' (di suku kata kedua) dan vokal jelas pada ''AG-ri-cul-ture''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000278', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Pilih istilah yang merujuk pada gagasan utama pemersatu seluruh bagian esai:', '{"options":["overarching","obsolete","erratic","inconsequential"],"translation":"Setiap paragraf isi dalam esai beasiswa Anda harus memajukan satu narasi besar yang terpadu alih-alih mendaftar penghargaan secara acak.","sentence_template":"Every body paragraph in your scholarship essay should advance one clear, [blank] narrative rather than listing random awards."}'::jsonb, '{"selected":"overarching"}'::jsonb, NULL, NULL, '''Overarching narrative / thesis'' berarti benang merah besar yang menyatukan seluruh tulisan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000279', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'listening', 'listening_choice', 'Dengarkan ringkasan lisan artikel sejarah perkotaan. Apa ketiga poin utama yang membentuk ringkasan utuh?', '{"options":[{"id":"opt_1","text":"Biaya tiket kereta api dari New York menuju Chicago"},{"id":"opt_2","text":"Alasan arsitek Eropa menolak mengunjungi Amerika Serikat"},{"id":"opt_3","text":"Rangka besi tuang, lift berpengaman, dan aturan zonasi kota berpadu melahirkan gedung pencakar langit modern di Chicago"},{"id":"opt_4","text":"Warna cat pintu lobi sebuah gedung di Chicago pada tahun 1889"}],"audio_text":"Overall, the passage traces how cast-iron framing, safety elevators, and municipal zoning laws converged to birth the modern Chicago skyscraper."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Verba ''converged to...'' merangkum tiga pilar paragraf bacaan menjadi satu ringkasan makro yang utuh.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000280', 'e5100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000039', 'writing', 'sentence_builder', 'Susun kalimat pembeda ide utama dan detail minor berikut:', '{"romaji":"/strɔːŋ ˌækəˈdɛmɪk ˈsʌməriz ˈkæptʃər ˌoʊvərˈɑːrtʃɪŋ ˈɑːrɡjəmənts waɪl oʊˈmɪtɪŋ ˈmaɪnər/","tokens":["Strong academic summaries","while omitting minor","omitted into","anecdotal examples.","argument overarching","capture overarching arguments"],"target_translation":"Ringkasan akademik yang kuat menangkap argumen-argumen payung sembari mengesampingkan contoh anekdotal kecil."}'::jsonb, '["Strong academic summaries","capture overarching arguments","while omitting minor","anecdotal examples."]'::jsonb, NULL, NULL, 'Klausa kontras ringkas ''while omitting...'' menjaga kepadatan definisi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000281', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Pilih kata kerja yang selaras dengan subjek utama di luar aposisi tanda pisah:', '{"options":["convert","converts","is converting","converting"],"translation":"Sel bahan bakar mikroba—teknologi bio-elektrokimia yang diuji di instalasi air limbah kota—mengubah materi organik langsung menjadi listrik.","sentence_template":"Microbial fuel cells—a bio-electrochemical technology tested in municipal wastewater plants—[blank] organic matter directly into electricity."}'::jsonb, '{"selected":"convert"}'::jsonb, NULL, NULL, 'Subjek utamanya jamak (''Microbial fuel cells''), bukan aposisi tunggal ''a technology'', sehingga memakai ''convert''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000282', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Pilih verba yang tepat untuk tindakan pembaca menarik simpulan logis:', '{"options":["inferred","implied","plateaued","waived"],"translation":"Karena guci keramik tersebut mengandung residu kakao ribuan mil di utara hutan kakao, para sejarawan menyimpulkan bahwa jaringan dagang jarak jauh telah ada.","sentence_template":"Because the ceramic jars contained cocoa residue thousands of miles north of cacao forests, historians [blank] that long-distance trade networks existed."}'::jsonb, '{"selected":"inferred"}'::jsonb, NULL, NULL, 'Sejarawan menarik simpulan logis (''inferred'') berdasarkan bukti residu.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000283', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'listening', 'listening_choice', 'Evaluasi Unit 9 — Dengarkan analisis soal ''Negative Factual'' (EXCEPT) TOEFL Reading. Mengapa pilihan C adalah jawaban yang dicari?', '{"options":[{"id":"opt_1","text":"Lumut kerak hancur seketika saat terkena sinar matahari pagi"},{"id":"opt_2","text":"Soal EXCEPT mengharuskan peserta memilih tiga jawaban yang benar"},{"id":"opt_3","text":"Pilihan C bertentangan langsung dengan paragraf empat yang menyatakan lumut kerak sanggup bertahan dari radiasi UV ekstrem"},{"id":"opt_4","text":"Pilihan C sesuai sepenuhnya dengan fakta di paragraf keempat"}],"audio_text":"Remember, in an EXCEPT question, three choices match the text and one contradicts or isn''t mentioned—here, paragraph four explicitly says lichens survive extreme UV radiation, which directly contradicts Choice C!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Pada soal ''All of the following are true EXCEPT...'', pilihan yang bertentangan dengan teks adalah jawaban yang benar!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000284', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'writing', 'sentence_builder', 'Evaluasi Unit 9 — Susun definisi ilmiah dengan ''whereby'':', '{"romaji":"/ˌfoʊtoʊˈsɪnθəsɪs ɪz ðə ˌbaɪoʊˈkɛmɪkəl ˈpæθˌweɪ wɛrˈbaɪ ɡriːn plænts ˈsɪnθəˌsaɪz ˈɡluːkoʊs/","tokens":["from sunlight.","synthesize glucose","synthesizing into","whereby green plants","Photosynthesis is","whereas plants","the biochemical pathway"],"target_translation":"Fotosintesis adalah jalur biokimia yang melaluinya tumbuhan hijau menyintesis glukosa dari cahaya matahari."}'::jsonb, '["Photosynthesis is","the biochemical pathway","whereby green plants","synthesize glucose","from sunlight."]'::jsonb, NULL, NULL, '''The pathway whereby + S + V'' menyusun definisi proses dengan presisi akademik.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000285', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'speaking', 'speaking_repeat', 'Evaluasi Unit 9 — Ucapkan kalimat sintesis bukti ilmiah berikut:', '{"romaji":"/ˈteɪkən təˈɡɛðər aɪs kɔːrz ænd triː rɪŋz səbˈstænʃiˌeɪt ðə draʊt haɪˈpɑːθəsɪs/","display_text":"Taken together, ice cores and tree rings substantiate the drought hypothesis.","phonetic_breakdown":["Taken together,","ice cores and tree rings","substantiate","the drought hypothesis."]}'::jsonb, '{"expected_transcript":"Taken together, ice cores and tree rings substantiate the drought hypothesis."}'::jsonb, NULL, NULL, 'Lafalkan ''drought'' /draʊt/ (berima dengan ''out'', tanpa bunyi gh!).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000286', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Pilih verba yang bermakna ''sudah hadir ratusan tahun sebelum'':', '{"options":["echoed","overhauled","predated","incurred"],"translation":"Tabel astronomi tertulis di Mesoamerika telah ada lebih dari satu milenium mendahului pengamatan teleskopik di Eropa.","sentence_template":"Written astronomical tables in Mesoamerica [blank] telescopic observations in Europe by more than a millennium."}'::jsonb, '{"selected":"predated"}'::jsonb, NULL, NULL, '''Predated [X] by [duration]'' menunjukkan keunggulan kronologis yang mendahului X.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000287', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'listening', 'listening_choice', 'Evaluasi Unit 9 — Dengarkan cuplikan teks sosiologi kerja. Apa yang disiratkan penulis tentang kantor konsep terbuka (''open-plan offices'')?', '{"options":[{"id":"opt_1","text":"Penghapusan sekat ruang kerja justru menurunkan interaksi tatap muka secara drastis alih-alih meningkatkannya"},{"id":"opt_2","text":"Pesan instan dihapus oleh perusahaan sesudah dinding kantor dibongkar"},{"id":"opt_3","text":"Karyawan dilarang mengenakan penyuara jemala selama jam kerja"},{"id":"opt_4","text":"Kantor konsep terbuka berhasil menggandakan percakapan tatap muka sebesar tujuh puluh persen"}],"audio_text":"Ironically, badge-tracking studies revealed that after walls were removed to boost collaboration, face-to-face conversations dropped by seventy percent as employees retreated into headphones and instant messaging."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Penanda ''Ironically'' menyingkap kontras tajam antara niat awal (''boost collaboration'') dan fakta empiris (''dropped by 70%'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000288', 'e5100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000039', 'writing', 'sentence_builder', 'Evaluasi Unit 9 — Susun kalimat kompatibilitas dua konsep berikut:', '{"romaji":"/ˈrɪɡərəs ˈseɪfti ˈtɛstɪŋ ænd ˈræpɪd dɪˈplɔɪmənt niːd nɑːt bi ˈmjuːtʃuəli ɪkˈskluːsɪv/","tokens":["need not be","and rapid deployment","mutually exclusively","Rigorous safety testing","in modern software.","needing not","mutually exclusive"],"target_translation":"Pengujian keamanan yang ketat dan perilisan cepat tidak harus saling meniadakan dalam perangkat lunak modern."}'::jsonb, '["Rigorous safety testing","and rapid deployment","need not be","mutually exclusive","in modern software."]'::jsonb, NULL, NULL, 'Modal semi-formal ''need not be + Adjective'' sangat elegan dalam penulisan esai argumen.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000289', 'e5100001-0000-4000-8000-000000000037', NULL, 'reading', 'fill_blank', 'Pilih frasa kerja baku TOEFL Integrated untuk menyatakan profesor menggoyahkan argumen bacaan:', '{"options":["echoes the sentiment of","meets halfway with","follows through on","casts doubt on"],"translation":"Dalam kuliah tersebut, pakar biologi meragukan hipotesis penulis bahwa kodok tebu invasif dapat dikendalikan menggunakan feromon.","sentence_template":"In the lecture, the biologist [blank] the author''s hypothesis that invasive cane toads can be controlled with pheromones."}'::jsonb, '{"selected":"casts doubt on"}'::jsonb, NULL, NULL, '''Casts doubt on + Noun Phrase'' adalah struktur pelaporan kontras paling idiomatis di TOEFL Integrated Writing.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000290', 'e5100001-0000-4000-8000-000000000037', NULL, 'reading', 'fill_blank', 'Pilih ungkapan kontras untuk data empiris yang bertolak belakang dengan klaim teks:', '{"options":["pan out for","opt out of","run counter to","hinge upon"],"translation":"Buku besar pajak yang baru ditemukan bertolak belakang dengan klaim bacaan bahwa pelabuhan tersebut ditinggalkan pada tahun 1420.","sentence_template":"Newly discovered tax ledgers [blank] the passage''s assertion that the port was abandoned in 1420."}'::jsonb, '{"selected":"run counter to"}'::jsonb, NULL, NULL, '''Run counter to [claim]'' berarti bertentangan langsung dengan pernyataan sebelumnya.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000291', 'e5100001-0000-4000-8000-000000000037', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah TOEFL Integrated (melawan bacaan yang memuji pembakaran hidrogen pesawat). Bagaimana profesor membantah poin bacaan?', '{"options":[{"id":"opt_1","text":"Teknologi tangki hidrogen sudah diterapkan di seluruh pesawat komersial saat ini"},{"id":"opt_2","text":"Meskipun unggul per kilogram, hidrogen cair memakan ruang tangki empat kali lebih besar sehingga memangkas kapasitas penumpang"},{"id":"opt_3","text":"Hidrogen cair lebih berat per kilogram dibandingkan bahan bakar jet biasa"},{"id":"opt_4","text":"Profesor setuju bahwa pesawat hidrogen mampu mengangkut lebih banyak penumpang"}],"audio_text":"While the article praises liquid hydrogen for having triple the energy per kilogram of jet fuel, it ignores volume: liquid hydrogen takes up four times more tank space, shrinking passenger capacity!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pola klasik bantahan TOEFL: profesor mengakui fakta sempit bacaan (''per kilogram''), lalu menghancurkan kesimpulannya lewat dimensi yang diabaikan (''volume / tank space'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000292', 'e5100001-0000-4000-8000-000000000037', NULL, 'writing', 'sentence_builder', 'Susun kalimat pembuka paragraf isi TOEFL Integrated Writing:', '{"romaji":"/wɛrˈæz ðə ˈriːdɪŋ ˈpɑːzɪts ðæt klaʊd ˈsiːdɪŋ buːsts ˈsnoʊˌfɔːl ðə ˈlɛktʃər rɪˈfjuːts ðɪs kleɪm/","tokens":["lecturer refutes this claim.","boosts snowfall, the","refuting claims","posited into","Whereas the reading","posits that cloud seeding"],"target_translation":"Sementara bacaan mengemukakan bahwa penyemaian awan meningkatkan curah salju, penceramah membantah klaim ini."}'::jsonb, '["Whereas the reading","posits that cloud seeding","boosts snowfall, the","lecturer refutes this claim."]'::jsonb, NULL, NULL, 'Kontras simetris ''Whereas the reading posits that..., the lecturer refutes this claim''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000293', 'e5100001-0000-4000-8000-000000000037', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat pelaporan TOEFL Integrated Speaking berikut dengan lancar:', '{"romaji":"/ðə prəˈfɛsər kɔːlz ðɪs əˈsʌmpʃən ˈɪntuː ˈkwɛstʃən baɪ ˈsaɪtɪŋ ˈriːsənt ˈkɛmɪkəl tɛsts/","display_text":"The professor calls this assumption into question by citing recent chemical tests.","phonetic_breakdown":["The professor calls","this assumption into question","by citing","recent chemical tests."]}'::jsonb, '{"expected_transcript":"The professor calls this assumption into question by citing recent chemical tests."}'::jsonb, NULL, NULL, 'Perhatikan pemisahan objek pendek ''calls [this assumption] into question'' yang sangat alami.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000294', 'e5100001-0000-4000-8000-000000000037', NULL, 'reading', 'fill_blank', 'Pilih kata kerja pelaporan formal untuk memperkenalkan argumen penulis bacaan:', '{"options":["digresses","averts","contends","waives"],"translation":"Pertama, teks bacaan berpendapat bahwa beton Romawi kuno memperoleh daya tahannya semata-mata berkat abu vulkanik.","sentence_template":"First, the reading passage [blank] that ancient Roman concrete owed its durability solely to volcanic ash."}'::jsonb, '{"selected":"contends"}'::jsonb, NULL, NULL, '''Contends / posits / asserts / maintains that...'' adalah variasi verba pelaporan bernilai tinggi pengganti ''says''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000295', 'e5100001-0000-4000-8000-000000000037', NULL, 'listening', 'listening_choice', 'Dengarkan rangkuman TOEFL Speaking Task 2 (pengumuman kampus + opini mahasiswa). Mengapa mahasiswi menolak penutupan ruang komputer perpustakaan?', '{"options":[{"id":"opt_1","text":"Kampus berjanji membagikan laptop baru gratis kepada seluruh mahasiswa teknik"},{"id":"opt_2","text":"Ia mendukung penutupan ruang komputer agar diubah menjadi kafe"},{"id":"opt_3","text":"Perangkat lunak teknik terlalu berat bagi laptop murah mahasiswa, dan kelompok belajar malam masih mengandalkan monitor ganda di sana"},{"id":"opt_4","text":"Mahasiswi tersebut tidak pernah menggunakan perpustakaan sepanjang semester"}],"audio_text":"The woman opposes the library''s plan for two reasons: first, engineering software like MATLAB is too heavy for cheap student laptops, and second, late-night study groups rely on those dual monitors."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Struktur sempurna TOEFL Speaking Task 2: nyatakan sikap pembicara (''opposes'') diikuti penanda jelas ''first,... and second,...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000296', 'e5100001-0000-4000-8000-000000000037', NULL, 'writing', 'sentence_builder', 'Susun kalimat bantahan paragraf ketiga TOEFL Integrated Writing:', '{"romaji":"/ˈfaɪnəli ðə ˈlɛktʃər kæsts daʊt ɑːn ði ˌiːkəˈnɑːmɪk ˈbɛnəfɪts ˈaʊtˌlaɪnd ɪn ðə ˈpæsɪdʒ/","tokens":["Finally, the lecturer","casting doubts to","casts doubt on","the economic benefits","outlined in the passage.","outlining into"],"target_translation":"Terakhir, penceramah meragukan manfaat ekonomi yang diuraikan di dalam bacaan."}'::jsonb, '["Finally, the lecturer","casts doubt on","the economic benefits","outlined in the passage."]'::jsonb, NULL, NULL, 'Partisip pasif tereduksi ''outlined in the passage'' merujuk kembali ke klaim bacaan secara ringkas.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000297', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Pilih pembuka kontras berkelas tinggi ketika suatu kebijakan justru memperburuk keadaan:', '{"options":["Provided that","Whereby","Chief among","Far from"],"translation":"Jauh dari menekan pembalakan liar, pajak kayu yang lemah pengawasannya justru mendorong penebang masuk lebih dalam ke hutan lindung.","sentence_template":"[blank] curbing illegal logging, the poorly enforced timber tax pushed harvesters deeper into protected reserves."}'::jsonb, '{"selected":"Far from"}'::jsonb, NULL, NULL, '''Far from + V-ing'' menegaskan bahwa hasil nyata justru berlawanan arah dari tujuan semula.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000298', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Pilih kelanjutan gramatikal sesudah frasa preposisi ''Contrary to'':', '{"options":["did the dealer claim","claimed by dealer","what the dealer claimed","the dealer claimed"],"translation":"Berlawanan dengan apa yang diklaim pedagang tersebut, analisis kimia membuktikan tinta manuskrip itu berasal dari abad kedua puluh.","sentence_template":"Contrary to [blank], chemical analysis proved the manuscript ink dated from the twentieth century."}'::jsonb, '{"selected":"what the dealer claimed"}'::jsonb, NULL, NULL, 'Preposisi ''to'' membutuhkan objek nomina atau klausa nomina (''what the dealer claimed''), tidak bisa diikuti klausa S+V telanjang.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000299', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'listening', 'listening_choice', 'Dengarkan profesor membantah teori bacaan tentang pajak kantong plastik sekali pakai. Apa efek tak terduga yang ia paparkan?', '{"options":[{"id":"opt_1","text":"Toko kelontong membagikan tas kain gratis kepada seluruh warga kota"},{"id":"opt_2","text":"Konsumsi resin plastik turun tujuh puluh persen tepat setelah pelarangan"},{"id":"opt_3","text":"Pelarangan kantong tipis justru mendorong pembeli membeli gulungan kantong sampah tebal yang memakai resin plastik 70% lebih banyak"},{"id":"opt_4","text":"Pembeli berhenti berbelanja di toko kelontong secara permanen"}],"audio_text":"Far from reducing overall plastic weight, banning thin grocery bags prompted shoppers to buy thick trash-bag rolls that used seventy percent more resin!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Contoh klasik bantahan ''Far from reducing X, the policy prompted Y'' pada TOEFL Integrated.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000300', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'writing', 'sentence_builder', 'Susun kalimat subjek klausa nomina ''The fact that'' berikut:', '{"romaji":"/ðə fækt ðæt ˈdʒuːvəˌnaɪl ˈfɑːsəlz lækt flaɪt ˈfɛðərz ˌʌndərˈmaɪnz ðə ˈɡlaɪdɪŋ haɪˈpɑːθəsɪs/","tokens":["undermining into","The fact that","juvenile fossils lacked","lacking feathers","the gliding hypothesis.","flight feathers undermines"],"target_translation":"Kenyataan bahwa fosil anakan tidak memiliki bulu terbang melemahkan hipotesis melayang tersebut."}'::jsonb, '["The fact that","juvenile fossils lacked","flight feathers undermines","the gliding hypothesis."]'::jsonb, NULL, NULL, 'Seluruh klausa ''The fact that juvenile fossils lacked flight feathers'' menjadi subjek tunggal bagi verba ''undermines''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000301', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kontras TOEFL Integrated berikut dengan pelafalan ''contrary'' dan ''juvenile'' ala AS:', '{"romaji":"/ˈkɑːntrɛri tə ðə ˈriːdɪŋz vjuː ˈdʒuːvəˌnaɪl ˈsæmən ˈnævəˌɡeɪt ˈjuːzɪŋ ɑːlˈfæktəri kjuːz/","display_text":"Contrary to the reading''s view, juvenile salmon navigate using olfactory cues.","phonetic_breakdown":["Contrary to","the reading''s view,","juvenile salmon navigate","using olfactory cues."]}'::jsonb, '{"expected_transcript":"Contrary to the reading''s view, juvenile salmon navigate using olfactory cues."}'::jsonb, NULL, NULL, 'Ingat huruf ''l'' pada ''salmon'' (/ˈsæmən/) sepenuhnya bisu (*silent l*)!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000302', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Pilih kata kerja tunggal yang selaras dengan subjek klausa nomina ''That the Viking settlement lasted less than a decade'':', '{"options":["are","have","is","were"],"translation":"Bahwa permukiman Viking di Newfoundland bertahan kurang dari satu dekade terlihat jelas dari tipisnya lapisan sampah arkeologis.","sentence_template":"That the Viking settlement in Newfoundland lasted less than a decade [blank] clear from thin midden layers."}'::jsonb, '{"selected":"is"}'::jsonb, NULL, NULL, 'Klausa nomina yang diawali ''That...'' atau ''The fact that...'' selalu dihitung sebagai subjek TUNGGAL (''is'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000303', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'listening', 'listening_choice', 'Dengarkan rangkuman poin kedua mahasiswa pada TOEFL Speaking Task 3. Bagaimana contoh eksperimen profesor mendukung definisi bacaan?', '{"options":[{"id":"opt_1","text":"Bacaan dan kuliah saling bertentangan soal perilaku makan sigung"},{"id":"opt_2","text":"Predator sama sekali tidak takut terhadap entakan kaki maupun semprotan"},{"id":"opt_3","text":"Contoh anak sigung mengentakkan kaki memperjelas cara sinyal peringatan bekerja mengusir predator tanpa membuang semprotan"},{"id":"opt_4","text":"Profesor membantah bahwa sigung memiliki kelenjar semprotan pelindung"}],"audio_text":"The reading defines ''aposematism'' as warning signals, and the professor illustrates how baby skunks stamp their feet first so predators retreat before any spray is wasted."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Ingat perbedaan krusial TOEFL: pada Writing Task 1 kuliah MEMBANTAH bacaan, sedangkan pada Speaking Task 3 kuliah MENGILUSTRASIKAN definisi bacaan!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000304', 'e5100001-0000-4000-8000-000000000038', 'e2000001-0000-4000-8000-000000000040', 'writing', 'sentence_builder', 'Susun kalimat bantahan tajam dengan ''Far from + V-ing'':', '{"romaji":"/fɑːr frʌm ˈbuːstɪŋ ˈwɜːrkər məˈræl ˈmændəˌtɔːri ˈwiːkˌɛnd rɪˈtriːts ˈfjuːəld ˈwaɪdˌsprɛd ˈbɜːrnaʊt/","tokens":["weekend retreats fueled","burnouts fueling","Far from boosting","worker morale, mandatory","boosting far to","widespread burnout."],"target_translation":"Jauh dari mendongkrak semangat kerja karyawan, retret akhir pekan wajib justru memicu kelelahan kerja yang meluas."}'::jsonb, '["Far from boosting","worker morale, mandatory","weekend retreats fueled","widespread burnout."]'::jsonb, NULL, NULL, '''Far from boosting X, [Subject] fueled Y'' memberikan struktur kontras C1 yang sangat kuat.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000305', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Pilih frasa transisi topik formal untuk mengawali pembahasan aspek kedua esai:', '{"options":["Mutually exclusive of","In case","Contrary from","With respect to"],"translation":"Terkait dengan keselamatan awak dalam misi Mars, penceramah menjelaskan bahwa dinding air dapat melindungi astronot dari radiasi matahari.","sentence_template":"[blank] crew safety on Mars missions, the lecturer explains that water walls can shield astronauts against solar radiation."}'::jsonb, '{"selected":"With respect to"}'::jsonb, NULL, NULL, '''With respect to + Noun Phrase'' memperkenalkan sub-topik bahasan baru secara terstruktur.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000306', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Pilih pasangan kata kerja kausal yang tepat (''mengaitkan akibat X pada penyebab Y''):', '{"options":["waived","digressed","attributed","corroborated"],"translation":"Sementara sejarawan awal mengaitkan runtuhnya peradaban Maya pada invasi asing, inti sedimen modern menunjuk pada kekeringan panjang.","sentence_template":"While early historians [blank] the Mayan collapse to foreign invasion, modern sediment cores point to prolonged megadroughts."}'::jsonb, '{"selected":"attributed"}'::jsonb, NULL, NULL, '''Attribute [Effect: collapse] to [Cause: invasion]'' adalah pola baku sintesis sebab-akibat.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000307', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'listening', 'listening_choice', 'Dengarkan rangkuman lisan peserta TOEFL yang memperoleh skor 29/30 pada Speaking Task 4. Apa kualitas yang membuat rangkuman ini unggul?', '{"options":[{"id":"opt_1","text":"Merangkum kontras antara tujuan perlindungan awal dan dampak erosi sampingan pada pantai tetangga secara padat dan kohesif"},{"id":"opt_2","text":"Peserta hanya mengulang satu kata yang sama selama enam puluh detik"},{"id":"opt_3","text":"Peserta menyimpulkan bahwa dinding laut menghentikan seluruh erosi di pantai tetangga"},{"id":"opt_4","text":"Peserta memberikan opini pribadi bahwa hotel tepi pantai harus dibongkar"}],"audio_text":"To sum up how seawalls trigger unintended consequences, the professor shows that while concrete barriers protect beachfront hotels, deflected wave energy scours away neighboring public beaches."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Penggunaan ''unintended consequences'' + klausa kontras ''while..., deflected wave energy scours away...'' mencerminkan kemahiran sintesis B2+/C1.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000308', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'writing', 'sentence_builder', 'Susun kalimat evaluasi kritis untuk paragraf TOEFL Integrated:', '{"romaji":"/ði ˈɔːθərz ˈtaɪmˌlaɪn haʊˈɛvər feɪlz tə stænd ʌp tə ˌreɪdioʊˈkɑːrbən ˈskruːtəni/","tokens":["however, fails to","radiocarbon scrutiny.","failed scrutiny","standing up into","stand up to","The author''s timeline,"],"target_translation":"Linimasa penulis tersebut, bagaimanapun, tidak tahan diuji terhadap pemeriksaan radiokarbon."}'::jsonb, '["The author''s timeline,","however, fails to","stand up to","radiocarbon scrutiny."]'::jsonb, NULL, NULL, '''Fail to stand up to [type of] scrutiny'' adalah ungkapan akademik tingkat lanjut untuk mematahkan bukti lemah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000309', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kontras atribusi kausal berikut dengan tekanan verba ''attributes'' yang tepat:', '{"romaji":"/ðə tɛkst əˈtrɪbjuːts ðə ˈkreɪtər tə ˈvɑːlkəˌnɪzəm wɛrˈæz ðə ˈlɛktʃər saɪts ˈmiːtiəˌraɪt ˈɪmpækt/","display_text":"The text attributes the crater to volcanism, whereas the lecturer cites meteorite impact.","phonetic_breakdown":["The text attributes","the crater to volcanism,","whereas the lecturer","cites meteorite impact."]}'::jsonb, '{"expected_transcript":"The text attributes the crater to volcanism, whereas the lecturer cites meteorite impact."}'::jsonb, NULL, NULL, 'Tekankan suku kata kedua pada verba ''at-TRIB-utes'' (/əˈtrɪbjuːts/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000310', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Lengkapi kalimat tentang dampak kebijakan ekologi yang tak diharapkan:', '{"options":["wiggle room","key takeaway","dealbreaker","unintended consequence"],"translation":"Mendatangkan kumbang tebu membawa dampak tak terduga berupa musnahnya penyerbuk asli di seluruh pulau tersebut.","sentence_template":"Introducing cane beetles had the [blank] of decimating native pollinators across the island."}'::jsonb, '{"selected":"unintended consequence"}'::jsonb, NULL, NULL, '''Have the unintended consequence of + V-ing'' sangat lazim dalam esai lingkungan TOEFL.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000311', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'listening', 'listening_choice', 'Dengarkan instruksi terakhir sebelum simulasi kesiapan B2. Kesalahan apa yang paling mengurangi nilai TOEFL Integrated Writing?', '{"options":[{"id":"opt_1","text":"Menulis sekitar dua ratus dua puluh lima kata dalam waktu dua puluh menit"},{"id":"opt_2","text":"Menggunakan kata sambung kontras seperti ''whereas'' dan ''conversely''"},{"id":"opt_3","text":"Menyalin untaian kalimat mentah-mentah dari kotak bacaan tanpa memparafrasakan struktur kalimatnya"},{"id":"opt_4","text":"Menyebutkan tiga contoh spesifik yang disampaikan oleh profesor di audio"}],"audio_text":"Copying five-word strings verbatim from the reading box signals weak paraphrasing—always restate the reading''s core claim using fresh syntax and attribution verbs."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Parafrasa aktif + atribusi tepat adalah pembeda utama skor 20 vs. skor 27+ di TOEFL Writing.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000312', 'e5100001-0000-4000-8000-000000000039', 'e2000001-0000-4000-8000-000000000040', 'writing', 'sentence_builder', 'Susun kalimat pembuka kontras topik dengan ''With respect to'':', '{"romaji":"/wɪð rɪˈspɛkt tə ˈwaɪldˌlaɪf ˈkɔːrɪdɔːrz fiːld ˈtrækɪŋ kæsts daʊt ɑːn ˈhaɪˌweɪ brɪdʒ ˈjuːsɪdʒ/","tokens":["With respect to","casting doubts","tracking casts doubt on","wildlife corridors, field","respecting into","highway bridge usage."],"target_translation":"Terkait dengan koridor satwa liar, pelacakan lapangan meragukan tingkat pemanfaatan jembatan penyeberangan jalan tol."}'::jsonb, '["With respect to","wildlife corridors, field","tracking casts doubt on","highway bridge usage."]'::jsonb, NULL, NULL, 'Menggabungkan ''With respect to [NP],'' dengan verba sintesis ''casts doubt on''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000313', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih pembuka kalimat yang tepat ketika bukti kuliah membalikkan harapan bacaan:', '{"options":["With respect","Provided that","Whereby","Far from"],"translation":"Jauh dari menurunkan biaya layanan kesehatan, denda kebugaran tersebut justru membuat pekerja enggan melaporkan gejala awal.","sentence_template":"[blank] lowering healthcare costs, the wellness penalty discouraged workers from reporting early symptoms."}'::jsonb, '{"selected":"Far from"}'::jsonb, NULL, NULL, '''Far from + V-ing'' menyoroti hasil yang bertolak belakang seratus delapan puluh derajat.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000314', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih kata kerja tunggal untuk subjek klausa nomina:', '{"options":["are refuting","refuting","refute","refutes"],"translation":"Kenyataan bahwa batangan tembaga tersebut memiliki tanda ukir Siprus membantah teori bacaan mengenai penambangan murni lokal.","sentence_template":"The fact that copper ingots bore Cypriot markings [blank] the reading''s theory of purely local mining."}'::jsonb, '{"selected":"refutes"}'::jsonb, NULL, NULL, 'Subjek tunggal ''The fact that...'' wajib diikuti kata kerja tunggal ''refutes''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000315', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'listening', 'listening_choice', 'Evaluasi Unit 10 — Dengarkan bantahan profesor terhadap artikel tentang ''vertical farming'' di perkotaan. Apa kelemahan utamanya?', '{"options":[{"id":"opt_1","text":"Tanaman di menara dalam ruangan tumbuh tiga kali lebih lambat daripada di ladang"},{"id":"opt_2","text":"Pertanian vertikal tidak membutuhkan listrik sama sekali di perkotaan"},{"id":"opt_3","text":"Menyalakan lampu LED buatan sepanjang waktu justru menghasilkan emisi karbon tiga kali lipat pertanian lahan terbuka"},{"id":"opt_4","text":"Profesor setuju bahwa pertanian vertikal sepenuhnya bebas emisi karbon"}],"audio_text":"Contrary to the article''s claim that indoor LED towers slash carbon footprints, powering artificial sunlight twenty-four seven emits triple the carbon of sunlit field farms!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Sintesis kontras ''Contrary to the article''s claim..., powering artificial sunlight emits triple...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000316', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'writing', 'sentence_builder', 'Evaluasi Unit 10 — Susun kalimat atribusi sebab-akibat kontras berikut:', '{"romaji":"/wɛrˈæz ði ˈɔːθər əˈtrɪbjuːts ðə dɪˈklaɪn tə ˌoʊvərˈfɪʃɪŋ ðə ˈlɛktʃər bleɪmz ˈoʊʃən əˌsɪdəfɪˈkeɪʃən/","tokens":["blaming into","attributing from","Whereas the author","attributes the decline","to overfishing, the lecturer","blames ocean acidification."],"target_translation":"Sementara penulis mengaitkan penurunan populasi tersebut pada penangkapan ikan berlebih, penceramah menyalahkan pengasaman laut."}'::jsonb, '["Whereas the author","attributes the decline","to overfishing, the lecturer","blames ocean acidification."]'::jsonb, NULL, NULL, 'Membandingkan dua faktor kausal dengan ''Whereas... attributes X to Y, the lecturer blames Z''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000317', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'speaking', 'speaking_repeat', 'Evaluasi Unit 10 — Ucapkan kalimat pembuka sintesis TOEFL Integrated berikut:', '{"romaji":"/ðə ˈlɛktʃər kæsts ˈsɪriəs daʊt ɑːn iːtʃ ʌv ði ˈɔːθərz θriː ˈɑːrɡjəmənts/","display_text":"The lecturer casts serious doubt on each of the author''s three arguments.","phonetic_breakdown":["The lecturer casts","serious doubt on","each of the author''s","three arguments."]}'::jsonb, '{"expected_transcript":"The lecturer casts serious doubt on each of the author''s three arguments."}'::jsonb, NULL, NULL, 'Kalimat tesis pembuka klasik yang jernih, objektif, dan tegas untuk Integrated Writing maupun Speaking.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000318', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih frasa idiomatis untuk argumen yang gagal bertahan saat diuji:', '{"options":["sweeten the pot","meet halfway","hand off cleanly","stand up to scrutiny"],"translation":"Begitu peneliti mengontrol variabel pendapatan rumah tangga, klaim pola makan pada bacaan gagal bertahan terhadap pengujian kritis.","sentence_template":"Once researchers controlled for household income, the passage''s dietary claim failed to [blank]."}'::jsonb, '{"selected":"stand up to scrutiny"}'::jsonb, NULL, NULL, '''Fail to stand up to scrutiny'' berarti argumen runtuh ketika diuji secara cermat.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000319', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'listening', 'listening_choice', 'Evaluasi Unit 10 — Dengarkan rangkuman Speaking Task 3 tentang efek psikologi ''anchoring''. Mengapa toko memajang mesin espreso $900 di sebelah mesin $300?', '{"options":[{"id":"opt_1","text":"Mesin seharga $900 dipasang sebagai patokan angka tinggi agar model $300 terasa sangat terjangkau saat dibandingkan"},{"id":"opt_2","text":"Mesin seharga $300 memiliki fitur yang lebih lengkap daripada model $900"},{"id":"opt_3","text":"Toko hanya ingin menjual mesin seharga $900 dan menghentikan model $300"},{"id":"opt_4","text":"Pelanggan dilarang membeli mesin seharga $900 tanpa kartu anggota"}],"audio_text":"The $900 machine isn''t actually expected to sell in high volume; rather, it acts as a high anchor that makes the $300 model feel like a bargain by comparison."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menangkap fungsi contoh bisnis profesor dalam mengilustrasikan definisi kognitif bacaan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000320', 'e5100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000040', 'writing', 'sentence_builder', 'Evaluasi Unit 10 — Susun kalimat rangkuman kontras bacaan vs. kuliah:', '{"romaji":"/ɪmˈpɪrɪkəl kræʃ ˈdeɪtə rʌnz ˈkaʊntər tə ði əˈsɜːrʃən ðæt ˈwaɪdər leɪnz sloʊ ˈdraɪvərz/","tokens":["running counters","runs counter to","the assertion that","asserted into","wider lanes slow drivers.","Empirical crash data"],"target_translation":"Data kecelakaan empiris bertolak belakang dengan klaim bahwa lajur jalan yang lebih lebar memperlambat pengemudi."}'::jsonb, '["Empirical crash data","runs counter to","the assertion that","wider lanes slow drivers."]'::jsonb, NULL, NULL, '''Runs counter to the assertion that + S + V'' merangkum bukti tandingan dengan tajam.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000321', 'e5100001-0000-4000-8000-000000000041', NULL, 'reading', 'fill_blank', 'Simulasi B2 [Reading 1/4] — Pilih penempatan kata ganti phrasal verb dan waktu yang tepat:', '{"options":["iron out them","pan them in","rule out them","iron them out"],"translation":"Dua klausul pertanggungjawaban yang ambigu menunda kontrak vendor, sehingga penasihat hukum bertemu untuk membereskannya sebelum penandatanganan hari Jumat.","sentence_template":"Two ambiguous liability clauses delayed the vendor contract, so legal counsel met to [blank] before Friday''s signing."}'::jsonb, '{"selected":"iron them out"}'::jsonb, NULL, NULL, 'Separable phrasal verb ''iron ... out'' mewajibkan pronomina ''them'' berada di tengah.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000322', 'e5100001-0000-4000-8000-000000000041', NULL, 'reading', 'fill_blank', 'Simulasi B2 [Reading 2/4] — Periksa keterangan waktu ''today'' untuk Mixed Conditional:', '{"options":["would have been","will have been","would be","had been"],"translation":"Seandainya tim platform kita memodularisasi layanan pembayaran dua tahun silam, ekspansi internasional pasti jauh lebih mudah hari ini.","sentence_template":"If our platform team had modularized the payment service two years ago, international expansion [blank] far simpler today."}'::jsonb, '{"selected":"would be"}'::jsonb, NULL, NULL, 'Sebab masa lalu (''had modularized ... two years ago'') dengan dampak masa kini (''today'') membutuhkan ''would be''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000323', 'e5100001-0000-4000-8000-000000000041', NULL, 'reading', 'fill_blank', 'Simulasi B2 [Reading 3/4] — Eliminasi dangling modifier pada klausa partisip pembuka:', '{"options":["flood levels were","the river basin","forecasting models","the hydrologists"],"translation":"Setelah memeriksa silang telemetri satelit dengan alat ukur darat, para ahli hidrologi memastikan curah hujan monsun melampaui prakiraan.","sentence_template":"Having cross-checked satellite telemetry with ground gauges, [blank] confirmed that monsoon rainfall had outpaced forecasts."}'::jsonb, '{"selected":"the hydrologists"}'::jsonb, NULL, NULL, 'Pelaku yang memeriksa silang telemetri wajib menjadi subjek tepat sesudah koma (''the hydrologists'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000324', 'e5100001-0000-4000-8000-000000000041', NULL, 'reading', 'fill_blank', 'Simulasi B2 [Reading 4/4] — Pilih penghubung mekanisme definisi akademik:', '{"options":["whereas","unless","whereby","albeit"],"translation":"Fitoremediasi adalah proses berkelanjutan yang melaluinya tanaman hiperakumulator mengekstrak logam berat dari tanah tercemar.","sentence_template":"Phytoremediation is a sustainable process [blank] hyperaccumulator plants extract heavy metals from contaminated soil."}'::jsonb, '{"selected":"whereby"}'::jsonb, NULL, NULL, '''Whereby'' (= through which) menjelaskan mekanisme kerja suatu proses ilmiah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000325', 'e5100001-0000-4000-8000-000000000041', NULL, 'listening', 'listening_choice', 'Simulasi B2 [Listening 1/4] — Dengarkan jawaban wawancara STAR kandidat Product Lead. Apa capaian utamanya?', '{"options":[{"id":"opt_1","text":"Menyederhanakan pembayaran tamu menjadi satu ketukan sehingga memangkas pengabaian keranjang belanja sebesar 32%"},{"id":"opt_2","text":"Menghapus opsi pembayaran tamu sehingga pelanggan wajib mendaftar akun panjang"},{"id":"opt_3","text":"Membiarkan pengabaian keranjang terus naik selama dua kuartal berikutnya"},{"id":"opt_4","text":"Menaikkan biaya layanan transaksi sebesar tiga puluh dua persen"}],"audio_text":"Checkout drop-off had been climbing for months before I simplified guest payment into one tap, cutting cart abandonment by thirty-two percent."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Narasi STAR memadukan latar Past Perfect Continuous (''had been climbing''), aksi Simple Past (''I simplified''), dan metrik ''cutting ... by 32%''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000326', 'e5100001-0000-4000-8000-000000000041', NULL, 'listening', 'listening_choice', 'Simulasi B2 [Listening 2/4] — Dengarkan cuplikan kuliah ekologi TOEFL. Mengapa profesor menyebut hasil eksperimen ''counterintuitive''?', '{"options":[{"id":"opt_1","text":"Pohon pinus yang tumbuh berdesakan menghasilkan getah pelindung paling banyak"},{"id":"opt_2","text":"Kumbang kulit kayu hanya menyerang hutan yang baru mengalami kebakaran"},{"id":"opt_3","text":"Menebang anakan pinus membuat seluruh hutan mati diserang kumbang kulit kayu"},{"id":"opt_4","text":"Penjarangan anakan pinus justru memperkuat daya tahan hutan terhadap kumbang kulit kayu karena pohon tersisa menghasilkan lebih banyak getah pelindung"}],"audio_text":"It sounds counterintuitive, I know, yet thinning overcrowded pine saplings actually helped the forest survive bark-beetle outbreaks because remaining trees produced more defensive resin."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Menangkap inti kausalitas di balik penanda kuliah ''counterintuitive''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000327', 'e5100001-0000-4000-8000-000000000041', NULL, 'listening', 'listening_choice', 'Simulasi B2 [Listening 3/4] — Dengarkan negosiasi lisensi perangkat lunak antar-eksekutif. Apa syarat yang mengikat kesepakatan?', '{"options":[{"id":"opt_1","text":"Klien diizinkan membatalkan kontrak kapan saja setiap bulan tanpa komitmen"},{"id":"opt_2","text":"Dukungan teknis baru diberikan setelah kontrak berjalan selama dua tahun"},{"id":"opt_3","text":"Pembebasan biaya orientasi dan dukungan khusus diberikan asalkan klien menandatangani komitmen kontrak 24 bulan sebelum akhir kuartal"},{"id":"opt_4","text":"Biaya orientasi tetap ditagih penuh meskipun klien menandatangani kontrak dua tahun"}],"audio_text":"We can waive the onboarding fee and include dedicated Slack support, provided that your procurement team signs a twenty-four-month commitment by quarter-end."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Memahami konsesi bersyarat ''waive X, provided that Y signs...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000328', 'e5100001-0000-4000-8000-000000000041', NULL, 'listening', 'listening_choice', 'Simulasi B2 [Listening 4/4] — Dengarkan kuliah TOEFL Integrated yang menanggapi bacaan soal rel kereta cepat. Bagaimana dosen membantah bacaan?', '{"options":[{"id":"opt_1","text":"Kereta cepat hanya berhenti di ibu kota negara tanpa melewati kota perantara"},{"id":"opt_2","text":"Profesor sependapat bahwa kota-kota kecil di sepanjang jalur kereta mengalami kebangkrutan"},{"id":"opt_3","text":"Alih-alih mematikan ekonomi kota perantara seperti dikhawatirkan penulis, kereta cepat justru mengubahnya menjadi pusat komuter yang berkembang"},{"id":"opt_4","text":"Stasiun di kota Lille ditutup karena kurangnya penumpang perusahaan multinasional"}],"audio_text":"Far from draining economic life out of intermediate towns as the author fears, high-speed rail turned stations like Lille into thriving commuter hubs for multinational offices."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Struktur bantahan ''Far from draining..., high-speed rail turned...'' membalikkan prediksi negatif bacaan.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000329', 'e5100001-0000-4000-8000-000000000041', NULL, 'writing', 'sentence_builder', 'Simulasi B2 [Writing 1/4] — Susun sanggahan diplomatis bergaya rapat & TOEFL Academic Discussion:', '{"romaji":"/waɪl aɪ siː ðə ˈmɛrɪt ɪn ˈlɔːntʃɪŋ ˈɜːrli ˈskɪpɪŋ loʊd tɛsts ɪnˈkɜːrz sɪˈvɪr ˈaʊtɪdʒ rɪsks/","tokens":["seeing merits","the merit in","incurred to","severe outage risks.","While I see","launching early, skipping","load tests incurs"],"target_translation":"Meskipun saya melihat sisi baik peluncuran lebih awal, melewatkan uji beban menimbulkan risiko gangguan parah."}'::jsonb, '["While I see","the merit in","launching early, skipping","load tests incurs","severe outage risks."]'::jsonb, NULL, NULL, 'Menggabungkan konsesi ''While I see the merit in...'' dengan kolokasi teknis ''incurs severe outage risks''.', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000330', 'e5100001-0000-4000-8000-000000000041', NULL, 'writing', 'sentence_builder', 'Simulasi B2 [Writing 2/4] — Susun kalimat pencegahan keamanan kausatif/preventif:', '{"romaji":"/strɪkt ˈskiːmə ˌvæləˈdeɪʃən prɪˈvɛnts mælˈfɔːrmd ˈpeɪˌloʊdz frʌm ˈkræʃɪŋ ˈdaʊnˌstriːm ˈbɪlɪŋ ˈwɜːrkərz/","tokens":["Strict schema validation","to crash","from crashing","preventing into","downstream billing workers.","prevents malformed payloads"],"target_translation":"Validasi skema yang ketat mencegah muatan data cacat menumbangkan pekerja penagihan hilir."}'::jsonb, '["Strict schema validation","prevents malformed payloads","from crashing","downstream billing workers."]'::jsonb, NULL, NULL, 'Rumus wajib ''prevent + Object + from + V-ing''.', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000331', 'e5100001-0000-4000-8000-000000000041', NULL, 'writing', 'sentence_builder', 'Simulasi B2 [Writing 3/4] — Susun kalimat sintesis TOEFL Integrated Writing:', '{"romaji":"/ˈkɑːntrɛri tə ði ˈɔːθərz əˈsɜːrʃən ɑːrˈkaɪvəl ˈrɛkərdz səbˈstænʃiˌeɪt kənˈtɪnjuəs pɔːrt ækˈtɪvəti/","tokens":["Contrary to the","records substantiate","continuous port activity.","author''s assertion, archival","Contrary that","substantiating into"],"target_translation":"Berlawanan dengan klaim penulis, catatan arsip membuktikan aktivitas pelabuhan yang berkelanjutan."}'::jsonb, '["Contrary to the","author''s assertion, archival","records substantiate","continuous port activity."]'::jsonb, NULL, NULL, '''Contrary to + Noun Phrase'' dipadukan verba bukti ''substantiate''.', 11, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000332', 'e5100001-0000-4000-8000-000000000041', NULL, 'writing', 'sentence_builder', 'Simulasi B2 [Writing 4/4] — Susun kalimat evaluasi kontrafaktual ''But for'':', '{"romaji":"/bʌt fɔːr ˈɔːtəˌmeɪtɪd ˈfeɪlˌoʊvər ˈraʊtɪŋ ˈjɛstərdeɪz ˈfaɪbər kʌt wʊd həv ˈhɔːltɪd/","tokens":["would have halted","would halt yesterday","Except automated","But for automated","failover routing,","regional trading.","yesterday''s fiber cut"],"target_translation":"Seandainya bukan karena perutean pengalihan otomatis, putusnya kabel serat optik kemarin pasti telah menghentikan perdagangan regional."}'::jsonb, '["But for automated","failover routing,","yesterday''s fiber cut","would have halted","regional trading."]'::jsonb, NULL, NULL, '''But for + NP'' + ''yesterday'' menuntut Third Conditional ''would have halted''.', 12, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000333', 'e5100001-0000-4000-8000-000000000041', NULL, 'speaking', 'speaking_repeat', 'Simulasi B2 [Speaking 1/4] — Ucapkan kalimat refleksi wawancara Wh-Cleft berikut:', '{"romaji":"/wʌt ðæt ˈɪnsədənt tɔːt mi wʌz tə əˈlaɪn ˈsteɪkˌhoʊldərz bɪˈfɔːr ˈtʃeɪndʒɪŋ skoʊp/","display_text":"What that incident taught me was to align stakeholders before changing scope.","phonetic_breakdown":["What that incident","taught me was","to align stakeholders","before changing scope."]}'::jsonb, '{"expected_transcript":"What that incident taught me was to align stakeholders before changing scope."}'::jsonb, NULL, NULL, 'Jaga penekanan jelas pada ''WHAT that incident TAUGHT me'' dan akhiri tegas pada ''changing SCOPE''.', 13, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000334', 'e5100001-0000-4000-8000-000000000041', NULL, 'speaking', 'speaking_repeat', 'Simulasi B2 [Speaking 2/4] — Ucapkan kalimat rangkuman mekanisme kuliah TOEFL:', '{"romaji":"/ˈɔɪstərz ˈfɪltər ˈkoʊstəl ˈwɔːtər ˌðɛrˈbaɪ ɪmˈpruːvɪŋ ˈklɛrəti fɔːr ˈʌndərˌwɔːtər ˈsiːˌɡræs ˈmɛdoʊz/","display_text":"Oysters filter coastal water, thereby improving clarity for underwater seagrass meadows.","phonetic_breakdown":["Oysters filter","coastal water,","thereby improving clarity","for underwater seagrass meadows."]}'::jsonb, '{"expected_transcript":"Oysters filter coastal water, thereby improving clarity for underwater seagrass meadows."}'::jsonb, NULL, NULL, 'Alirkan klausa partisip hasil '', thereby improving clarity'' dengan lancar.', 14, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000335', 'e5100001-0000-4000-8000-000000000041', NULL, 'speaking', 'speaking_repeat', 'Simulasi B2 [Speaking 3/4] — Ucapkan kalimat advokasi sopan akademik berikut:', '{"romaji":"/aɪ wʌz ˈwʌndərɪŋ ˈwɛðər ðɛr maɪt bi ˈɛni ˈwɪɡəl ruːm ɑːn ðə ɡrænt ˈdɛdˌlaɪn/","display_text":"I was wondering whether there might be any wiggle room on the grant deadline.","phonetic_breakdown":["I was wondering","whether there might be","any wiggle room","on the grant deadline."]}'::jsonb, '{"expected_transcript":"I was wondering whether there might be any wiggle room on the grant deadline."}'::jsonb, NULL, NULL, 'Gunakan intonasi pernyataan sopan (bukan interogasi tajam) untuk ''I was wondering whether...''.', 15, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000336', 'e5100001-0000-4000-8000-000000000041', NULL, 'speaking', 'speaking_repeat', 'Simulasi B2 [Speaking 4/4] — Ucapkan kalimat bantahan kuliah TOEFL Integrated:', '{"romaji":"/ðə ˈlɛktʃər kæsts daʊt ɑːn ðɪs kleɪm baɪ ˈhaɪˌlaɪtɪŋ ˌʌnɪnˈtɛndɪd ˌiːkəˈlɑːdʒɪkəl kɔːsts/","display_text":"The lecturer casts doubt on this claim by highlighting unintended ecological costs.","phonetic_breakdown":["The lecturer","casts doubt on this claim","by highlighting","unintended ecological costs."]}'::jsonb, '{"expected_transcript":"The lecturer casts doubt on this claim by highlighting unintended ecological costs."}'::jsonb, NULL, NULL, 'Lafalkan ''ecological'' ala Amerika /ˌiːkəˈlɑːdʒɪkəl/ dengan vokal /ɑː/ jelas pada suku kata ketiga.', 16, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000337', 'e5100001-0000-4000-8000-000000000042', NULL, 'reading', 'fill_blank', 'Pilih susunan inversi yang tepat sesudah ''Not only'' di awal kalimat:', '{"options":["slashed the facility","did the facility slash","did the facility slashed","the facility slashed"],"translation":"Fasilitas tersebut tidak hanya memangkas biaya operasional sebesar tiga puluh persen, tetapi mikrogrid surya itu juga meniadakan kebisingan mesin diesel.","sentence_template":"Not only [blank] operational costs by thirty percent, but the solar microgrid also eliminated diesel noise."}'::jsonb, '{"selected":"did the facility slash"}'::jsonb, NULL, NULL, 'Sesudah ''Not only'' di awal klausa, pinjam kata bantu lampau ''did + Subject + V1 (slash)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000338', 'e5100001-0000-4000-8000-000000000042', NULL, 'reading', 'fill_blank', 'Lengkapi protokol kepatuhan keamanan siber dengan inversi negatif yang benar:', '{"options":["do engineers should share","should engineers share","engineers should share","should engineers shared"],"translation":"Dalam keadaan apa pun para insinyur tidak boleh membagikan kredensial basis data produksi melalui kanal Slack teks biasa.","sentence_template":"Under no circumstances [blank] production database credentials in plaintext Slack channels."}'::jsonb, '{"selected":"should engineers share"}'::jsonb, NULL, NULL, '''Under no circumstances'' memicu inversi modal: ''should + Subject (engineers) + V1 (share)''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000339', 'e5100001-0000-4000-8000-000000000042', NULL, 'listening', 'listening_choice', 'Dengarkan pembukaan pidato rektor pada simposium riset. Apa penekanan utama dari kalimat ''Seldom have three disciplines converged so rapidly''?', '{"options":[{"id":"opt_1","text":"Perpaduan secepat ini antara ilmu komputer, biologi struktural, dan kedokteran klinis merupakan peristiwa luar biasa langka"},{"id":"opt_2","text":"Ketiga bidang ilmu tersebut menolak bekerja sama dalam riset pelipatan protein"},{"id":"opt_3","text":"Ilmu komputer tidak lagi dibutuhkan dalam penelitian biologi modern"},{"id":"opt_4","text":"Kolaborasi lintas ilmu sudah biasa terjadi setiap tahun sejak abad lalu"}],"audio_text":"Seldom have computer science, structural biology, and clinical medicine converged so rapidly to solve protein-folding mysteries."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Inversi ''Seldom have [Subjects] converged...'' memberi penekanan retoris pada kelangkaan dan kehebatan pencapaian tersebut.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000340', 'e5100001-0000-4000-8000-000000000042', NULL, 'writing', 'sentence_builder', 'Susun kalimat sejarah penemuan ilmiah dengan inversi ''Little did'':', '{"romaji":"/ˈlɪtəl dɪd ˈflɛmɪŋ ˈriːəˌlaɪz ðæt moʊld kənˌtæməˈneɪʃən wʊd ˌrɛvəˈluːʃəˌnaɪz/","tokens":["modern antibiotic medicine.","Fleming realized","did Fleming realized","Little did Fleming","realize that mold","contamination would revolutionize"],"target_translation":"Sama sekali tidak disadari Fleming saat itu bahwa kontaminasi jamur akan merevolusi pengobatan antibiotik modern."}'::jsonb, '["Little did Fleming","realize that mold","contamination would revolutionize","modern antibiotic medicine."]'::jsonb, NULL, NULL, '''Little + did + Subject + V1 (realize)'' menciptakan efek dramatis dalam narasi ilmiah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000341', 'e5100001-0000-4000-8000-000000000042', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat inversi retoris C1 berikut dengan penekanan pada ''Not only'' dan ''also'':', '{"romaji":"/nɑːt ˈoʊnli dʌz ˈmæŋɡroʊv ˌrɛstəˈreɪʃən stɔːr ˈkɑːrbən bʌt ɪt ˈɔːlsoʊ ʃiːldz ˈkoʊstˌlaɪnz/","display_text":"Not only does mangrove restoration store carbon, but it also shields coastlines.","phonetic_breakdown":["Not only does","mangrove restoration","store carbon,","but it also shields coastlines."]}'::jsonb, '{"expected_transcript":"Not only does mangrove restoration store carbon, but it also shields coastlines."}'::jsonb, NULL, NULL, 'Perhatikan kontras tata bahasa: klausa pertama terinversi (''does ... store''), sedangkan klausa kedua kembali normal (''it also shields'')!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000342', 'e5100001-0000-4000-8000-000000000042', NULL, 'reading', 'fill_blank', 'Pilih bentuk inversi Present Perfect sesudah ''Rarely'':', '{"options":["urban planners have witnessed","have urban planners witness","did urban planners have witnessed","have urban planners witnessed"],"translation":"Jarang sekali para perencana kota menyaksikan dukungan lintas partai yang begitu bulat bagi obligasi transportasi kota.","sentence_template":"Rarely [blank] such unanimous bipartisan backing for municipal transit bonds."}'::jsonb, '{"selected":"have urban planners witnessed"}'::jsonb, NULL, NULL, 'Pada Present Perfect, kata bantu ''have'' langsung maju mendahului subjek sebelum Past Participle ''witnessed''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000343', 'e5100001-0000-4000-8000-000000000042', NULL, 'listening', 'listening_choice', 'Dengarkan peringatan auditor keuangan kepada dewan direksi. Apa larangan tegas yang disampaikan?', '{"options":[{"id":"opt_1","text":"Manajer dianjurkan mencatat seluruh pendapatan lima tahun sekaligus hari ini"},{"id":"opt_2","text":"Manajer anak perusahaan sama sekali dilarang membukukan pendapatan perangkat lunak tahun jamak di muka sebelum tahapan layanan terpenuhi"},{"id":"opt_3","text":"Anak perusahaan dibebaskan dari audit pendapatan tahun ini"},{"id":"opt_4","text":"Tahapan pengiriman layanan tidak memengaruhi laporan akuntansi"}],"audio_text":"On no account may subsidiary managers recognize multi-year software revenue upfront before service delivery milestones are met."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''On no account may + Subject + V1'' setara tegasnya dengan ''Under no circumstances'' dalam wacana audit/regulasi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000344', 'e5100001-0000-4000-8000-000000000042', NULL, 'writing', 'sentence_builder', 'Susun kalimat penekanan kebijakan dengan ''Never before'':', '{"romaji":"/ˈnɛvər bɪˈfɔːr hæz ˈsætəˌlaɪt spɛkˈtrɑːskəpi ɪˈneɪbəld sʌtʃ prɪˈsaɪs ˈtrækɪŋ/","tokens":["satellite spectroscopy enabled","has enabled spectroscopy","enabling before","of methane plumes.","Never before has","such precise tracking"],"target_translation":"Belum pernah sebelumnya spektroskopi satelit memungkinkan pelacakan semburan metana yang begitu presisi."}'::jsonb, '["Never before has","satellite spectroscopy enabled","such precise tracking","of methane plumes."]'::jsonb, NULL, NULL, 'Perhatikan tekanan kata Amerika ''spec-TROS-co-py'' (/spɛkˈtrɑːskəpi/) dan inversi tunggal ''has ... enabled''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000345', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Perhatikan posisi klausa utama lalu pilih bentuk inversi tunda yang benar sesudah ''Not until'':', '{"options":["did mission control understood","did mission control understand","understood mission control","mission control understood"],"translation":"Baru setelah log telemetri didekripsi, pusat kendali misi memahami mengapa pendorong kendali arah gagal menyala.","sentence_template":"Not until the telemetry logs were decrypted [blank] why the attitude thrusters had misfired."}'::jsonb, '{"selected":"did mission control understand"}'::jsonb, NULL, NULL, 'Anak kalimat ''the telemetry logs were decrypted'' tetap normal, lalu induk kalimat wajib terinversi: ''did mission control understand''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000346', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Pilih kata sambung pasangan baku untuk konstruksi ''No sooner had...'':', '{"options":["when","than","that","then"],"translation":"Begitu perusahaan tekfin itu meluncurkan pembayaran QR lintas batas instan, seketika itu pula volume transaksi naik tiga kali lipat.","sentence_template":"No sooner had the fintech launched instant cross-border QR payments [blank] transaction volume tripled."}'::jsonb, '{"selected":"than"}'::jsonb, NULL, NULL, 'Komparatif ''sooner'' wajib dipasangkan dengan ''than'' (bukan ''when'' dan bukan ejaan waktu ''then''!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000347', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'listening', 'listening_choice', 'Dengarkan kesimpulan pembicara pada panel kebijakan iklim. Apa syarat mutlak yang ditekankan?', '{"options":[{"id":"opt_1","text":"Tarif listrik tetap sepanjang hari sudah cukup mengatasi beban puncak"},{"id":"opt_2","text":"Perusahaan listrik hanya dapat mendorong pabrik menggeser beban berat ke puncak surya siang hari dengan menerapkan tarif kemacetan dinamis"},{"id":"opt_3","text":"Perusahaan listrik akan mematikan aliran listrik pabrik setiap siang"},{"id":"opt_4","text":"Pabrik menolak menggunakan listrik tenaga surya pada siang hari"}],"audio_text":"Only by pricing grid congestion dynamically can utilities incentivize factories to shift heavy loads to midday solar peaks."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Only by + V-ing + can + Subject + V1'' menonjolkan satu-satunya mekanisme kebijakan yang efektif.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000348', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'writing', 'sentence_builder', 'Susun kalimat rekomendasi esai menggunakan ''Only by + V-ing'':', '{"romaji":"/ˈoʊnli baɪ ˈstændərˌdaɪzɪŋ ˌɪntərˈɑːpərəbəl hɛlθ ˈrɛkərdz kæn ˈhɑːspɪtəlz ɪˈlɪməˌneɪt/","tokens":["eliminating can","hospitals can eliminate","can hospitals eliminate","Only by standardizing","redundant diagnostic tests.","interoperable health records"],"target_translation":"Hanya dengan menstandarisasi rekam medis yang saling terhubung, rumah sakit dapat meniadakan tes diagnostik berulang."}'::jsonb, '["Only by standardizing","interoperable health records","can hospitals eliminate","redundant diagnostic tests."]'::jsonb, NULL, NULL, 'Frasa ''Only by + V-ing'' di awal kalimat memicu inversi modal ''can hospitals eliminate''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000349', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'speaking', 'speaking_repeat', 'Ucapkan kalimat inversi tunda ''Only after'' berikut dengan jeda frasa yang presisi:', '{"romaji":"/ˈoʊnli ˈæftər ˈrɛplɪˌkeɪtɪŋ ðə ˈtraɪəl ɪn θriː læbz dɪd ðə tiːm ˈpʌblɪʃ/","display_text":"Only after replicating the trial in three labs did the team publish.","phonetic_breakdown":["Only after replicating","the trial in three labs","did the team publish."]}'::jsonb, '{"expected_transcript":"Only after replicating the trial in three labs did the team publish."}'::jsonb, NULL, NULL, 'Berikan jeda mantap sesudah ''three labs'' tepat sebelum masuk ke inversi ''did the team publish''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000350', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Pilih kata sambung pasangan baku untuk ''Scarcely had...'':', '{"options":["then","when","than","whereas"],"translation":"(Catatan kolokasi: Begitu pidato utama simposium baru saja usai, puluhan mahasiswa pascasarjana langsung mengantre di mikrofon.)","sentence_template":"Scarcely had the symposium keynote concluded [blank] dozens of graduate students lined up at the microphone."}'::jsonb, '{"selected":"when"}'::jsonb, NULL, NULL, 'Berbeda dari ''No sooner... than'', adverbia ''Hardly / Scarcely / Barely had...'' berpasangan dengan ''when''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000351', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'listening', 'listening_choice', 'Dengarkan kuliah sejarah kedokteran TOEFL. Kapan komunitas medis akhirnya menerima teori kuman Ignaz Semmelweis?', '{"options":[{"id":"opt_1","text":"Ahli bedah Eropa sudah menerapkan sterilisasi sebelum Semmelweis lahir"},{"id":"opt_2","text":"Louis Pasteur membantah manfaat mencuci tangan di ruang operasi"},{"id":"opt_3","text":"Para ahli bedah Eropa baru menerima protokol cuci tangan Semmelweis puluhan tahun kemudian setelah Pasteur membuktikan penularan bakteri"},{"id":"opt_4","text":"Protokol cuci tangan Semmelweis langsung diadopsi sejak hari pertama diumumkan"}],"audio_text":"Tragically, not until Louis Pasteur demonstrated bacterial transmission decades later did European surgeons embrace Semmelweis''s handwashing protocol."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Memahami struktur lisan ''not until [Pasteur demonstrated...] did [surgeons embrace...]'' mencegah salah urut kronologi di soal TOEFL.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000352', 'e5100001-0000-4000-8000-000000000043', 'e2000001-0000-4000-8000-000000000041', 'writing', 'sentence_builder', 'Susun kalimat kronologi cepat dengan ''Hardly had ... when'':', '{"romaji":"/ˈhɑːrdli hæd ðə pætʃ ɡɔːn laɪv wɛn ˈɔːtəˌmeɪtɪd ˈmɑːnətərz dɪˈtɛktɪd ə ˈleɪtənsi rɪˈɡrɛʃən/","tokens":["gone live when","than automated","Hardly had the patch","a latency regression.","automated monitors detected","the patch had"],"target_translation":"Baru saja tambalan kode tersebut tayang langsung, pemantau otomatis seketika mendeteksi kemunduran latensi."}'::jsonb, '["Hardly had the patch","gone live when","automated monitors detected","a latency regression."]'::jsonb, NULL, NULL, 'Inversi Past Perfect ''Hardly had the patch gone live'' berpasangan dengan ''when + Simple Past''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000353', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Pilih struktur penekanan adjektiva yang gramatikal di awal kalimat:', '{"options":["So was severe","So severe did","Such severe was","So severe was"],"translation":"Begitu parahnya kemacetan komputasi tersebut sehingga para peneliti menulis ulang inti simulasi menggunakan bahasa Rust.","sentence_template":"[blank] the computational bottleneck that researchers rewrote the simulation kernel in Rust."}'::jsonb, '{"selected":"So severe was"}'::jsonb, NULL, NULL, 'Karena ''severe'' adalah kata sifat (adjective), gunakan pola ''So + Adjective + be (was) + Subject + that...''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000354', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Pilih kelanjutan klausa negatif kedua menggunakan ''nor'' dengan inversi yang benar:', '{"options":["neither it does preclude","nor does it preclude","nor it precludes","or does it not preclude"],"translation":"Lisensi sumber terbuka tidak memperlemah keamanan, dan tidak pula menghalangi profitabilitas komersial bila dipadukan dengan hosting cloud.","sentence_template":"Open-source licensing does not weaken security, [blank] commercial profitability when paired with cloud hosting."}'::jsonb, '{"selected":"nor does it preclude"}'::jsonb, NULL, NULL, 'Konjungsi negatif ''nor'' memicu inversi kata bantu: ''nor + does + Subject (it) + V1 (preclude)''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000355', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'listening', 'listening_choice', 'Dengarkan pembukaan kuliah etika kecerdasan buatan. Apa isu inti yang diangkat profesor lewat inversi lokatif?', '{"options":[{"id":"opt_1","text":"Larangan penggunaan komputer di jurusan hukum hak cipta"},{"id":"opt_2","text":"Biaya listrik harian yang dibutuhkan untuk mendinginkan pusat data"},{"id":"opt_3","text":"Cara mengganti kartu grafis pada komputer pribadi mahasiswa"},{"id":"opt_4","text":"Persoalan mendasar apakah pelatihan statistik tergolong penggunaan wajar yang transformatif"}],"audio_text":"At the very center of copyright disputes over generative models lies a fundamental question: does statistical training constitute transformative fair use?"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''At the very center of X lies [Subject]'' menempatkan informasi terpenting di ujung kalimat (*end-focus*) agar langsung tertancap di benak pendengar.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000356', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'writing', 'sentence_builder', 'Susun kalimat inversi lokatif pembuka esai yang elegan:', '{"romaji":"/bɪˈhaɪnd ðiːz ɪmˈprɛsɪv ˌdʒiːdiːˈpiː ˈfɪɡjərz laɪz ˈwaɪdənɪŋ ˈriːdʒənəl ˌɪnɪˈkwɑːləti/","tokens":["widening regional inequality","does lie","GDP figures lies","lying behind","in healthcare access.","Behind these impressive"],"target_translation":"Di balik angka-angka PDB yang mengesankan ini terletak ketimpangan antardaerah yang kian melebar dalam akses kesehatan."}'::jsonb, '["Behind these impressive","GDP figures lies","widening regional inequality","in healthcare access."]'::jsonb, NULL, NULL, 'Subjek di belakang kata kerja adalah tunggal tak terhitung (''widening regional inequality''), sehingga memakai ''lies'' (bukan ''lie'', jangan terkecoh ''figures''!).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000357', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'speaking', 'speaking_repeat', 'Ucapkan kalimat retoris ''So compelling was...'' berikut dengan ekspresi berwibawa:', '{"romaji":"/soʊ kəmˈpɛlɪŋ wʌz ðə ˈklɪnɪkəl ˈdeɪtə ðæt ˈrɛɡjəˌleɪtərz ˈɡræntɪd ækˈsɛləˌreɪtɪd əˈpruːvəl/","display_text":"So compelling was the clinical data that regulators granted accelerated approval.","phonetic_breakdown":["So compelling was","the clinical data","that regulators granted","accelerated approval."]}'::jsonb, '{"expected_transcript":"So compelling was the clinical data that regulators granted accelerated approval."}'::jsonb, NULL, NULL, 'Tekankan ''SO com-PEL-ling'' di awal untuk menonjolkan kekuatan bukti klinis tersebut.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000358', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Pilih kata pembuka yang tepat sebelum frasa kata benda ''the public backlash'':', '{"options":["Very","Too","So","Such"],"translation":"Sedemikian besarnya gelombang protes publik terhadap biaya dinamis tersembunyi sehingga platform tiket itu membatalkan kebijakannya dalam semalam.","sentence_template":"[blank] was the public backlash against hidden dynamic fees that the ticketing platform reversed its policy overnight."}'::jsonb, '{"selected":"Such"}'::jsonb, NULL, NULL, 'Sebelum ''be + Noun Phrase (the public backlash) + that'', gunakan ''Such'' (bukan ''So'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000359', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'listening', 'listening_choice', 'Dengarkan sanggahan analis kebijakan publik. Bagaimana ia membatasi ruang lingkup argumennya?', '{"options":[{"id":"opt_1","text":"Subsidi kereta komuter akan menggantikan seluruh angkutan pedesaan minggu depan"},{"id":"opt_2","text":"Jalan tol perkotaan akan segera dibongkar setelah kereta beroperasi"},{"id":"opt_3","text":"Subsidi kereta komuter tidak akan menghapus kemacetan tol dalam semalam, dan memang tidak pernah dirancang menggantikan angkutan pedesaan"},{"id":"opt_4","text":"Analis tersebut menolak pembangunan jalur kereta komuter di perkotaan"}],"audio_text":"Subsidizing commuter rail will not eliminate highway traffic overnight, nor was it ever designed to replace last-mile rural transport."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Pola ''...will not X, nor was it ever designed to Y'' menjaga argumen tetap proporsional dan tahan serangan kritik.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000360', 'e5100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000041', 'writing', 'sentence_builder', 'Susun kalimat penekanan ''Such was...'' berikut:', '{"romaji":"/sʌtʃ wʌz ðə prɪˈsɪʒən ʌv wɛbz ˈmɪrərz ðæt əˈstrɑːnəmərz dɪˈtɛktɪd ˈɛksoʊˌplænɪt ˈwɔːtər ˈveɪpər/","tokens":["Such was the precision","detecting vapor","So precision was","that astronomers detected","of Webb''s mirrors","exoplanet water vapor."],"target_translation":"Sedemikian tingginya presisi cermin teleskop Webb sehingga para astronom mendeteksi uap air eksoplanet."}'::jsonb, '["Such was the precision","of Webb''s mirrors","that astronomers detected","exoplanet water vapor."]'::jsonb, NULL, NULL, '''Such + was + Noun Phrase (the precision...) + that + Clause''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000361', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Pilih bentuk inversi tunda yang benar sesudah anak kalimat ''Only when'':', '{"options":["did electric propulsion became","electric propulsion became","did electric propulsion become","became electric propulsion"],"translation":"Hanya ketika kerapatan energi baterai melampaui 250 watt-jam per kilogram, propulsi listrik menjadi layak secara komersial untuk penerbangan regional.","sentence_template":"Only when battery energy density exceeded 250 watt-hours per kilogram [blank] commercially viable for regional aviation."}'::jsonb, '{"selected":"did electric propulsion become"}'::jsonb, NULL, NULL, 'Inversi terjadi di induk kalimat: ''did + Subject (electric propulsion) + V1 (become)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000362', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Pilih verba yang selaras dengan subjek di belakang pada inversi lokatif:', '{"options":["is","has","does","are"],"translation":"Di antara koleksi paling berharga milik arsip tersebut terdapat tiga buku catatan belum terbit yang ditulis Raden Saleh di Dresden.","sentence_template":"Among the archive''s most prized holdings [blank] three unpublished notebooks written by Raden Saleh in Dresden."}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, 'Subjek sejatinya berada di belakang kata kerja, yakni jamak ''three unpublished notebooks'' → ''are''!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000363', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'listening', 'listening_choice', 'Evaluasi Unit 1 — Dengarkan cuplikan pidato CEO tentang etika privasi. Apa komitmen mutlak perusahaan?', '{"options":[{"id":"opt_1","text":"Jurnal pengguna disimpan tanpa enkripsi di server pihak ketiga"},{"id":"opt_2","text":"Perusahaan menjual metadata anonim kepada pialang iklan demi menekan harga"},{"id":"opt_3","text":"Enkripsi hanya diaktifkan bagi pelanggan yang membayar biaya tambahan"},{"id":"opt_4","text":"Jurnal pengguna dienkripsi penuh di perangkat, dan metadata perilaku sama sekali tidak pernah dijual ke pialang iklan"}],"audio_text":"Not only do we encrypt user journals end-to-end on device, but under no circumstances do we monetize behavioral metadata through ad brokers."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Dua inversi negatif beruntun (''Not only do we...'' + ''under no circumstances do we...'') mempertegas integritas kebijakan.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000364', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'writing', 'sentence_builder', 'Evaluasi Unit 1 — Susun kalimat ''No sooner ... than'' dengan tepat:', '{"romaji":"/noʊ ˈsuːnər hæd ði ɛmˈbɑːrɡoʊ ˈlɪftɪd ðæn ˌæɡrɪˈkʌltʃərəl ˈɛkspɔːrts rɪˈbaʊndɪd/","tokens":["No sooner had","than agricultural exports","when agricultural","the embargo lifted","rebounded to record highs.","the embargo had"],"target_translation":"Begitu embargo dicabut, ekspor pertanian seketika melonjak kembali ke rekor tertinggi."}'::jsonb, '["No sooner had","the embargo lifted","than agricultural exports","rebounded to record highs."]'::jsonb, NULL, NULL, '''No sooner + had + S + V3 + than + Simple Past''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000365', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'speaking', 'speaking_repeat', 'Evaluasi Unit 1 — Ucapkan kalimat inversi C1 berikut dengan lancar:', '{"romaji":"/nɑːt ʌnˈtɪl wi ˈproʊfaɪld prəˈdʌkʃən ˈtræfɪk dɪd ðə lɑːk kənˈtɛnʃən ˈsɜːrfɪs/","display_text":"Not until we profiled production traffic did the lock contention surface.","phonetic_breakdown":["Not until we profiled","production traffic","did the lock","contention surface."]}'::jsonb, '{"expected_transcript":"Not until we profiled production traffic did the lock contention surface."}'::jsonb, NULL, NULL, 'Klausa pertama normal (''we profiled''), klausa kedua terinversi (''did the lock contention surface'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000366', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Perbaiki kata jumlah ''dozen'' pada kalimat inversi ''Not only'':', '{"options":["do the network issue","does the network issue","the network issues","does the network issues"],"translation":"Jaringan tersebut tidak hanya mengeluarkan peringatan dini banjir, tetapi jaring sensor itu juga memetakan bahaya tanah longsor secara waktu nyata.","sentence_template":"Not only [blank] early flood warnings, but the sensor mesh also maps landslide hazards in real time."}'::jsonb, '{"selected":"does the network issue"}'::jsonb, NULL, NULL, 'Subjek tunggal ''the network'' memerlukan ''does + S + V1 (issue)''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000367', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'listening', 'listening_choice', 'Evaluasi Unit 1 — Dengarkan analisis kuliah ekonomi makro. Apa dampak kenaikan biaya pelayaran yang sedemikian tajam?', '{"options":[{"id":"opt_1","text":"Kapal kontainer kosong melimpah ruah dengan tarif sangat murah"},{"id":"opt_2","text":"Kelangkaan kontainer begitu parah sehingga produsen sampai menyewa kapal curah gandum demi mengangkut barang elektronik"},{"id":"opt_3","text":"Perdagangan gandum di Pasifik digantikan sepenuhnya oleh pesawat kargo"},{"id":"opt_4","text":"Produsen menghentikan ekspor barang elektronik selama lima tahun"}],"audio_text":"So acute was the container shortage in late 2021 that manufacturers chartered bulk grain ships just to move electronics across the Pacific."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''So acute was X that...'' menekankan tingkat keparahan ekstrem yang mendorong tindakan tak lazim.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000368', 'e5100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000041', 'writing', 'sentence_builder', 'Evaluasi Unit 1 — Susun kalimat kelanjutan negatif dengan ''nor'':', '{"romaji":"/ˌkɔːrəˈleɪʃən dʌz nɑːt ɪˈstæblɪʃ kɔːˈzæləti nɔːr dʌz ə smɔːl ˈsæmpəl ˈwɔːrənt ˈswiːpɪŋ ˈpɑːləsi/","tokens":["does a small sample","nor a small","warrants sweeping","establish causality, nor","warrant sweeping policy.","Correlation does not"],"target_translation":"Korelasi tidak membuktikan kausalitas, dan sampel kecil pun tidak membenarkan kebijakan menyeluruh yang tergesa-gesa."}'::jsonb, '["Correlation does not","establish causality, nor","does a small sample","warrant sweeping policy."]'::jsonb, NULL, NULL, '''Nor + does + Subject + V1 (warrant)'' menjaga kesejajaran retoris C1.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000369', 'e5100001-0000-4000-8000-000000000046', NULL, 'reading', 'fill_blank', 'Pilih bentuk kata kerja Mandative Subjunctive yang tepat sesudah ''recommended that'':', '{"options":["rotated","rotates","has rotated","rotate"],"translation":"Menyusul audit keamanan siber, panel eksternal merekomendasikan agar kementerian segera merotasi kunci enkripsi lawas.","sentence_template":"Following the cybersecurity audit, the external panel recommended that the ministry [blank] legacy encryption keys immediately."}'::jsonb, '{"selected":"rotate"}'::jsonb, NULL, NULL, 'Sesudah ''recommended that + singular subject (the ministry)'', American English formal memakai bare infinitive ''rotate'' tanpa -s/-ed.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000370', 'e5100001-0000-4000-8000-000000000046', NULL, 'reading', 'fill_blank', 'Pilih bentuk negatif Subjunctive yang baku dalam kode etik peradilan:', '{"options":["not comment","not comments","does not comment","did not comment"],"translation":"Kaidah peradilan mensyaratkan secara tegas agar hakim banding tidak berkomentar di ruang publik mengenai perkara yang sedang berjalan.","sentence_template":"Judicial canons stipulate that an appellate judge [blank] publicly on pending litigation."}'::jsonb, '{"selected":"not comment"}'::jsonb, NULL, NULL, 'Negasi Mandative Subjunctive dibentuk langsung dengan ''not + bare infinitive'' (''not comment'') tanpa ''does''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000371', 'e5100001-0000-4000-8000-000000000046', NULL, 'listening', 'listening_choice', 'Dengarkan pembacaan draf resolusi kebijakan kesehatan. Apa syarat pasif yang diwajibkan oleh komite?', '{"options":[{"id":"opt_1","text":"Produksi obat antimikroba dihentikan selama dua tahun"},{"id":"opt_2","text":"Dokter dilarang meresepkan antibiotik kepada pasien rumah sakit"},{"id":"opt_3","text":"Obat antimikroba berspektrum luas wajib diserahkan secara ketat hanya melalui resep dokter"},{"id":"opt_4","text":"Obat antimikroba diizinkan dijual bebas di seluruh minimarket"}],"audio_text":"To prevent antibiotic resistance, it is imperative that broad-spectrum antimicrobials be dispensed strictly by prescription."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Perhatikan bentuk pasif Subjunctive pada audio: ''that antimicrobials BE dispensed'' (bukan ''are dispensed'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000372', 'e5100001-0000-4000-8000-000000000046', NULL, 'writing', 'sentence_builder', 'Susun kalimat persyaratan tender pengadaan dengan pasif Subjunctive:', '{"romaji":"/prəˈkjʊrmənt ruːlz ˈstɪpjəˌleɪt ðæt ˈɛvri ˈvɛndər bɪd bi səbˈmɪtɪd/","tokens":["is submitted","be submitted in","that every vendor bid","submitting be","Procurement rules stipulate","a sealed digital vault."],"target_translation":"Aturan pengadaan mensyaratkan bahwa setiap penawaran vendor wajib diserahkan di dalam brankas digital tersegel."}'::jsonb, '["Procurement rules stipulate","that every vendor bid","be submitted in","a sealed digital vault."]'::jsonb, NULL, NULL, '''Stipulate that + Subject + be + V3 (submitted)'' merupakan standar penulisan dokumen legal dan kebijakan AS.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000373', 'e5100001-0000-4000-8000-000000000046', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat rekomendasi eksekutif ber-Subjunctive berikut dengan mantap:', '{"romaji":"/ɪt ɪz ɪmˈpɛrətɪv ðæt ðə ˈsɛntrəl bæŋk meɪnˈteɪn ˈpɑːləsi ˌkrɛdəˈbɪləti ˈdʊrɪŋ ɪnˈfleɪʃən ʃɑːks/","display_text":"It is imperative that the central bank maintain policy credibility during inflation shocks.","phonetic_breakdown":["It is imperative","that the central bank","maintain policy credibility","during inflation shocks."]}'::jsonb, '{"expected_transcript":"It is imperative that the central bank maintain policy credibility during inflation shocks."}'::jsonb, NULL, NULL, 'Ucapkan ''maintain'' murni tanpa bunyi -s di ujungnya meskipun subjeknya tunggal ''the central bank''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000374', 'e5100001-0000-4000-8000-000000000046', NULL, 'reading', 'fill_blank', 'Pilih bentuk pasif Subjunctive sesudah adjektiva urgensi ''vital'':', '{"options":["been screened","were screened","be screened","are screened"],"translation":"Demi tolok ukur AI yang dapat direproduksi, sangat penting agar kumpulan data pelatihan diperiksa terhadap kontaminasi data uji.","sentence_template":"For reproducible AI benchmarks, it is vital that training datasets [blank] against test-set contamination."}'::jsonb, '{"selected":"be screened"}'::jsonb, NULL, NULL, '''It is vital that + Subject + be + V3'' adalah rumus pasif Mandative Subjunctive.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000375', 'e5100001-0000-4000-8000-000000000046', NULL, 'listening', 'listening_choice', 'Dengarkan diskusi rapat dewan direksi startup. Apa tuntutan investor utama dalam klausul tata kelola?', '{"options":[{"id":"opt_1","text":"Penutupan pendanaan Seri B ditunda selama sembilan puluh hari"},{"id":"opt_2","text":"Perusahaan menolak membentuk komite audit selama lima tahun ke depan"},{"id":"opt_3","text":"Investor Seri B menuntut agar ketua komite audit independen ditunjuk dalam waktu 90 hari sesudah penutupan pendanaan"},{"id":"opt_4","text":"Investor sudah menunjuk dirinya sendiri sebagai ketua audit tahun lalu"}],"audio_text":"The lead Series B investor insisted that an independent audit chair be appointed within ninety days of closing."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Meskipun ''insisted'' berbentuk lampau, klausa ''that... be appointed'' tetap menggunakan bare infinitive pasif.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000376', 'e5100001-0000-4000-8000-000000000046', NULL, 'writing', 'sentence_builder', 'Susun kalimat kebijakan privasi dengan negasi Subjunctive:', '{"romaji":"/ˈpraɪvəsi ˈstætʃuːts ˈmændeɪt ðæt ˌbaɪoʊˈmɛtrɪk ˈtɛmpləts nɑːt bi stɔːrd/","tokens":["are not stored","Privacy statutes mandate","on external cloud servers.","not be stored","that biometric templates","not storing"],"target_translation":"Undang-undang privasi mewajibkan agar templat biometrik tidak disimpan di server cloud eksternal."}'::jsonb, '["Privacy statutes mandate","that biometric templates","not be stored","on external cloud servers."]'::jsonb, NULL, NULL, 'Gabungan negatif + pasif Subjunctive: ''not + be + V3'' (''not be stored'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000377', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Cermati makna ''mengindikasikan bukti fakta'' lalu pilih kata kerja yang tepat:', '{"options":["not thin","thin","are thinning","be thinning"],"translation":"Altimetri satelit terbaru mengindikasikan dengan kuat bahwa paparan es Antarktika Barat sedang menipis lebih cepat daripada prediksi model tahun 1990-an.","sentence_template":"Recent satellite altimetry strongly suggests that West Antarctic ice shelves [blank] faster than 1990s models predicted."}'::jsonb, '{"selected":"are thinning"}'::jsonb, NULL, NULL, 'Di sini ''suggests'' berarti ''menunjukkan bukti ilmiah'' (bukan menyuruh es menipis!), sehingga wajib memakai bentuk indikatif ''are thinning''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000378', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Pilih bentuk kata kerja sesudah ungkapan urgensi keterlambatan ''It is high time'':', '{"options":["enforced","be enforced","will enforce","enforce"],"translation":"Mengingat kerugian banjir perkotaan yang terus meningkat, sudah saatnya otoritas daerah menegakkan perlindungan daerah aliran sungai secara ketat.","sentence_template":"Given rising urban flood losses, it is high time regional authorities [blank] strict watershed protection."}'::jsonb, '{"selected":"enforced"}'::jsonb, NULL, NULL, 'Idiom ''It is (high/about) time + Subject'' selalu diikuti Past Simple Subjunctive (V2: ''enforced'') untuk urgensi masa kini.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000379', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'listening', 'listening_choice', 'Dengarkan argumen pengacara pembela dibanding tuntutan jaksa. Bagaimana perbedaan kedua kata ''insisted'' pada audio?', '{"options":[{"id":"opt_1","text":"Kedua belah pihak sepakat menutup operasional perusahaan minggu ini"},{"id":"opt_2","text":"Pendiri mengaku sengaja melakukan kecurangan akuntansi sejak awal"},{"id":"opt_3","text":"Regulator membebaskan perusahaan dari pengawasan pihak eksternal"},{"id":"opt_4","text":"Pendiri bersikeras mengklaim fakta ketidaksengajaan, sedangkan regulator menuntut agar pengawas eksternal mengawasi keuangan"}],"audio_text":"Throughout the hearing, the founder insisted that the accounting error was unintentional, yet regulators insisted that an external monitor oversee treasury operations."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Kontras sempurna: ''insisted that the error WAS...'' (klaim fakta lampau) vs. ''insisted that a monitor OVERSEE...'' (tuntutan tindakan).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000380', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'writing', 'sentence_builder', 'Susun kalimat kehati-hatian strategis menggunakan konjungsi ''lest'':', '{"romaji":"/ˈsɛntrəl ˈbæŋkərz ˈwɜːrdɪd ðə ˈsteɪtmənt ˈkɛrfəli lɛst bɑːnd ˈmɑːrkɪts ˌmɪsɪnˈtɜːrprɪt ðə pɔːz/","tokens":["the statement carefully","Central bankers worded","lest not markets","misinterprets the","lest bond markets","misinterpret the pause."],"target_translation":"Para bankir sentral menyusun kalimat pernyataan itu dengan hati-hati agar jangan sampai pasar obligasi salah menafsirkan jeda suku bunga tersebut."}'::jsonb, '["Central bankers worded","the statement carefully","lest bond markets","misinterpret the pause."]'::jsonb, NULL, NULL, '''Lest + Subject + bare infinitive (misinterpret)'' menyatakan pencegahan risiko formal tanpa kata ''not''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000381', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kontras Indikatif vs. Subjunctive berikut dengan jelas:', '{"romaji":"/prɪˈlɪməˌnɛri ˈtraɪəlz səɡˈdʒɛst ðæt ðə ˈkɑːmpaʊnd ɪz seɪf jɛt ˈrɛɡjəˌleɪtərz ɪnˈsɪst ðæt feɪz θriː prəˈsiːd ˈkɔːʃəsli/","display_text":"Preliminary trials suggest that the compound is safe, yet regulators insist that phase three proceed cautiously.","phonetic_breakdown":["Preliminary trials suggest","that the compound is safe,","yet regulators insist","that phase three proceed cautiously."]}'::jsonb, '{"expected_transcript":"Preliminary trials suggest that the compound is safe, yet regulators insist that phase three proceed cautiously."}'::jsonb, NULL, NULL, 'Lafalkan ''preliminary'' ala AS /prɪˈlɪməˌnɛri/ (dengan bunyi -nɛri jelas di akhir) dan ''proceed'' tanpa -s.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000382', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Pilih kata kerja yang tepat ketika saksi bersikeras menyatakan kejadian faktual masa lalu:', '{"options":["sending","send","had sent","be sent"],"translation":"Dalam pemeriksaan silang, kepala insinyur bersikeras bahwa ia telah mengirim memo keselamatan tiga minggu sebelum peluncuran.","sentence_template":"Under cross-examination, the chief engineer insisted that he [blank] the safety memo three weeks prior to the launch."}'::jsonb, '{"selected":"had sent"}'::jsonb, NULL, NULL, 'Karena menyatakan klaim fakta yang terjadi sebelum peluncuran (bukan perintah), gunakan Past Perfect indikatif ''had sent''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000383', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'listening', 'listening_choice', 'Dengarkan komentar editorial tentang infrastruktur jembatan. Mengapa pembicara mengatakan ''It''s high time Congress funded...''?', '{"options":[{"id":"opt_1","text":"Kondisi jembatan sudah mendesak sehingga pembiayaan pemeliharaan preventif seharusnya sudah dilakukan sekarang tanpa ditunda lagi"},{"id":"opt_2","text":"Pemeliharaan jembatan dinilai terlalu mahal dan sebaiknya diabaikan"},{"id":"opt_3","text":"Jembatan di seluruh negeri masih baru dan bebas kerusakan"},{"id":"opt_4","text":"Kongres sudah selesai memperbaiki empat puluh ribu jembatan pada masa lalu"}],"audio_text":"With forty thousand bridges rated structurally deficient, it''s high time Congress funded preventive maintenance rather than waiting for headlines."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''It''s high time + S + V2'' menyiratkan kritik bahwa tindakan tersebut seharusnya sudah diambil dan mendesak dilakukan sekarang.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000384', 'e5100001-0000-4000-8000-000000000047', 'e2000001-0000-4000-8000-000000000042', 'writing', 'sentence_builder', 'Susun kalimat peringatan ilmiah menggunakan ''lest'':', '{"romaji":"/ˈɑːrkaɪv kjʊˈreɪtərz kənˈtroʊl hjuːˈmɪdəti ˈstrɪktli lɛst ˈeɪnʃənt pɑːm liːf ˈmænjəˌskrɪpts ˈkrʌmbəl/","tokens":["not crumble","humidity strictly lest","crumbles into","ancient palm-leaf manuscripts","crumble into dust.","Archive curators control"],"target_translation":"Kurator arsip mengendalikan kelembapan secara ketat agar jangan sampai naskah lontar kuno hancur menjadi debu."}'::jsonb, '["Archive curators control","humidity strictly lest","ancient palm-leaf manuscripts","crumble into dust."]'::jsonb, NULL, NULL, '''Lest + Subject + V1 (crumble)'' adalah gaya prosa akademik C1 yang ringkas dan berkelas.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000385', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Pilih bentuk kata kerja di dalam klausa nomina ''The commission''s recommendation that...'':', '{"options":["restore","restored","is restoring","restores"],"translation":"Rekomendasi komisi agar setiap pemerintah kota pesisir memulihkan zona penyangga bakau telah disahkan menjadi undang-undang.","sentence_template":"The commission''s recommendation that every coastal municipality [blank] mangrove buffer zones was adopted into law."}'::jsonb, '{"selected":"restore"}'::jsonb, NULL, NULL, 'Kata benda mandatif ''recommendation that + singular subject (every municipality)'' memicu Subjunctive ''restore'' (sedangkan verba induk kalimatnya adalah ''was adopted'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000386', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Pilih frasa sifat C1 yang berarti ''bergantung pada terpenuhinya syarat'':', '{"options":["contingent upon","mutually exclusive to","contrary from","oblivious of"],"translation":"Kelanjutan pencairan pinjaman Bank Dunia bergantung pada penurunan kehilangan air tak berekening yang terverifikasi.","sentence_template":"Continued World Bank loan disbursement is [blank] verified reductions in non-revenue water loss."}'::jsonb, '{"selected":"contingent upon"}'::jsonb, NULL, NULL, '''Contingent upon + Noun Phrase'' adalah istilah baku pembiayaan pembangunan dan kontrak internasional.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000387', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'listening', 'listening_choice', 'Dengarkan presentasi kandidat beasiswa kebijakan publik. Mengapa ia mengusulkan kebijakan diterapkan secara ''phased in''?', '{"options":[{"id":"opt_1","text":"Agar petani kecil tidak terguncang mendadak dan mendapat pendampingan hibah agronomi selama transisi 36 bulan"},{"id":"opt_2","text":"Karena petani besar meminta larangan diberlakukan dalam waktu semalam"},{"id":"opt_3","text":"Untuk membatalkan seluruh program sertifikasi keberlanjutan selamanya"},{"id":"opt_4","text":"Untuk menghapus bantuan hibah agronomi bagi koperasi daerah"}],"audio_text":"Rather than imposing an abrupt ban that could shock small farmers, we propose that sustainable palm certification be phased in over thirty-six months with agronomy grants."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memadukan ''propose that certification BE phased in'' dengan alasan sosio-ekonomi yang realistis dan *actionable*.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000388', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'writing', 'sentence_builder', 'Susun kalimat kebijakan tata kelola dengan klausa nomina Subjunctive:', '{"romaji":"/ðə rɪˈkwaɪərmənt ðæt ˌælɡəˈrɪðmɪk ˈkrɛdɪt ˈmɑːdəlz bi ˈɔːdɪtɪd ˈænjuəli prəˈtɛkts/","tokens":["protecting fairness","algorithmic credit models","The requirement that","protects consumer fairness.","are audited","be audited annually"],"target_translation":"Persyaratan agar model kredit algoritmik diaudit setiap tahun melindungi keadilan bagi konsumen."}'::jsonb, '["The requirement that","algorithmic credit models","be audited annually","protects consumer fairness."]'::jsonb, NULL, NULL, 'Subjek utama tunggal ''The requirement [that ... be audited]'' diikuti verba tunggal ''protects''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000389', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penutup policy brief eksekutif berikut dengan artikulasi yang jernih:', '{"romaji":"/ˈaʊər waɪt ˈpeɪpər ˈaʊtˌlaɪnz θriː ˈækʃənəbəl ˌrɛkəmɛnˈdeɪʃənz fɔːr ˈriːdʒənəl ɡrɪd rɪˈzɪliəns/","display_text":"Our white paper outlines three actionable recommendations for regional grid resilience.","phonetic_breakdown":["Our white paper","outlines three","actionable recommendations","for regional grid resilience."]}'::jsonb, '{"expected_transcript":"Our white paper outlines three actionable recommendations for regional grid resilience."}'::jsonb, NULL, NULL, 'Pastikan tekanan suku kata keempat pada ''rec-om-men-DA-tions'' terdengar tegas dan proporsional.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000390', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Pilih kata sifat yang bermakna ''paling utama melampaui segalanya'' dalam keselamatan penerbangan:', '{"options":["paramount","redundant","arbitrary","plausible"],"translation":"Selama turbulensi hebat, keselamatan kabin penumpang tetap menjadi kepentingan paling utama di atas jadwal layanan makanan.","sentence_template":"During severe turbulence, passenger cabin safety remains of [blank] importance over meal service schedules."}'::jsonb, '{"selected":"paramount"}'::jsonb, NULL, NULL, 'Kolokasi tetap C1: ''of paramount importance''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000391', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'listening', 'listening_choice', 'Dengarkan tanya-jawab seminar administrasi publik. Kelemahan apa yang dikritik oleh penanya terhadap makalah kebijakan tersebut?', '{"options":[{"id":"opt_1","text":"Diagnosis mengenai penyebab berhentinya guru dinilai sepenuhnya keliru"},{"id":"opt_2","text":"Makalah tersebut terlalu banyak mencantumkan rincian teknis anggaran daerah"},{"id":"opt_3","text":"Bagian penutup belum memuat rekomendasi yang dapat dieksekusi secara konkret terkait sumber pendanaan tunjangan perumahan guru"},{"id":"opt_4","text":"Penanya menolak pemberian tunjangan perumahan bagi guru di daerah terpencil"}],"audio_text":"Your diagnosis of teacher attrition is spot-on, yet the closing section lacks actionable recommendations—how exactly would districts fund rural housing stipends?"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Spot-on'' (sangat tepat) menjadi konsesi pujian sebelum kritik inti ''lacks actionable recommendations''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000392', 'e5100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000042', 'writing', 'sentence_builder', 'Susun kalimat syarat hibah internasional dengan ''contingent upon'':', '{"romaji":"/ˈmætʃɪŋ ˈtrɛʒəri fʌndz ɑːr kənˈtɪndʒənt əˈpɑːn mjuːˌnɪsəˈpælətiz ˈpʌblɪʃɪŋ ˈkwɔːrtərli/","tokens":["Matching treasury funds","published inventories","contingent from","municipalities publishing","quarterly emissions inventories.","are contingent upon"],"target_translation":"Dana pendamping kas negara bergantung pada kepatuhan pemerintah kota menerbitkan inventaris emisi kuartalan."}'::jsonb, '["Matching treasury funds","are contingent upon","municipalities publishing","quarterly emissions inventories."]'::jsonb, NULL, NULL, 'Preposisi ''upon'' diikuti subjek gerund formal ''municipalities publishing...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000393', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Pilih bentuk Subjunctive pasif yang tepat:', '{"options":["be transferred","are transferred","have transferred","were transferred"],"translation":"Perjanjian penerbangan internasional mensyaratkan agar perekam penerbangan kotak hitam segera diserahkan ke laboratorium investigasi terakreditasi.","sentence_template":"International aviation treaties stipulate that black-box flight recorders [blank] immediately to accredited investigation labs."}'::jsonb, '{"selected":"be transferred"}'::jsonb, NULL, NULL, '''Stipulate that + Subject + be + V3'' berlaku mutlak dalam wacana perjanjian resmi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000394', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Bedakan makna ''suggest'' sebagai bukti empiris vs. usulan:', '{"options":["not lie","lies","be lain","lie"],"translation":"Pemetaan radar lapisan es mengindikasikan bahwa sebuah danau subglasial terletak di bawah punggungan tersebut, mendorong ilmuwan mengusulkan agar pengeboran dihentikan.","sentence_template":"Ice-sheet radar mapping suggests that a subglacial lake [blank] beneath the ridge, prompting scientists to propose that drilling be halted."}'::jsonb, '{"selected":"lies"}'::jsonb, NULL, NULL, 'Kontras C1 dalam satu kalimat: ''suggests that a lake LIES'' (fakta indikatif) vs. ''propose that drilling BE halted'' (usulan subjunctive)!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000395', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'listening', 'listening_choice', 'Evaluasi Unit 2 — Dengarkan pernyataan komite etika medis. Aturan apa yang ditetapkan bagi peneliti?', '{"options":[{"id":"opt_1","text":"Perusahaan sponsor dilarang membiayai peralatan laboratorium universitas"},{"id":"opt_2","text":"Peneliti utama dilarang memegang saham ekuitas pada perusahaan sponsor mana pun yang alatnya sedang diuji"},{"id":"opt_3","text":"Anggota komite etika wajib menggantikan peneliti utama di ruang operasi"},{"id":"opt_4","text":"Peneliti utama dianjurkan membeli saham sponsor sebelum uji klinis dimulai"}],"audio_text":"To safeguard objectivity, institutional rules mandate that a principal investigator not hold equity in any sponsor whose device is under review."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Negasi Mandative Subjunctive ''that a principal investigator not hold equity'' menyampaikan larangan etika resmi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000396', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'writing', 'sentence_builder', 'Evaluasi Unit 2 — Susun kalimat ''It is high time'' berikut:', '{"romaji":"/ɪt ɪz haɪ taɪm ˈɡloʊbəl ˈʃɪpɪŋ əˈlaɪənsɪz trænˈzɪʃənd əˈweɪ frʌm haɪ ˈsʌlfər ˈbʌŋkər ˈfjuːəl/","tokens":["transition away","high-sulfur bunker fuel.","It is high time","transitioned away from","global shipping alliances","be transitioned"],"target_translation":"Sudah saatnya aliansi pelayaran global beralih meninggalkan bahan bakar kapal bersulfur tinggi."}'::jsonb, '["It is high time","global shipping alliances","transitioned away from","high-sulfur bunker fuel."]'::jsonb, NULL, NULL, '''It is high time + Subject + V2 (transitioned)''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000397', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'speaking', 'speaking_repeat', 'Evaluasi Unit 2 — Ucapkan kalimat kebijakan Subjunctive berikut dengan lancar:', '{"romaji":"/ðə bɔːrd ɪnˈsɪstɪd ðæt ˈɛvri səbˈsɪdiˌɛri dɪsˈkloʊz ˈklaɪmət rɪsks ɪn ˈænjuəl ˈfaɪlɪŋz/","display_text":"The board insisted that every subsidiary disclose climate risks in annual filings.","phonetic_breakdown":["The board insisted","that every subsidiary","disclose climate risks","in annual filings."]}'::jsonb, '{"expected_transcript":"The board insisted that every subsidiary disclose climate risks in annual filings."}'::jsonb, NULL, NULL, 'Lafalkan ''subsidiary'' ala Amerika /səbˈsɪdiˌɛri/ (lima suku kata dengan tekanan kedua pada -ɛri).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000398', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Pilih konjungsi pencegahan formal pemicu Subjunctive:', '{"options":["whereas","unless","provided","lest"],"translation":"Simpan kunci akar kriptografi secara luring di modul perangkat keras, agar jangan sampai satu serangan phishing membobol seluruh otoritas sertifikat.","sentence_template":"Keep cryptographic root keys offline in hardware modules, [blank] a single phishing attack compromise the entire certificate authority."}'::jsonb, '{"selected":"lest"}'::jsonb, NULL, NULL, '''Lest + singular subject (a single phishing attack) + bare V1 (compromise)'' adalah penanda pasti konjungsi ''lest''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000399', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'listening', 'listening_choice', 'Evaluasi Unit 2 — Dengarkan evaluasi proposal hibah infrastruktur. Apa syarat pencairan tahap kedua?', '{"options":[{"id":"opt_1","text":"Pencairan dana tahap kedua bergantung pada sertifikasi kepatuhan tahan gempa oleh insinyur independen"},{"id":"opt_2","text":"Sertifikasi tahan gempa baru diwajibkan sepuluh tahun sesudah gedung selesai"},{"id":"opt_3","text":"Dana tahap kedua sudah dicairkan penuh tanpa pemeriksaan tahan gempa"},{"id":"opt_4","text":"Insinyur independen menolak memeriksa bangunan di wilayah gempa"}],"audio_text":"Release of the second funding tranche remains contingent upon independent engineers certifying seismic compliance."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Remains contingent upon [Agent] + V-ing'' menetapkan prasyarat pencairan yang ketat.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000400', 'e5100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000042', 'writing', 'sentence_builder', 'Evaluasi Unit 2 — Susun kalimat subjek nomina mandatif berikut:', '{"romaji":"/ðə ˌstɪpjəˈleɪʃən ðæt ˈklɪnɪkəl rɔː ˈdeɪtə bi ˈɑːrkaɪvd ˈpʌblɪkli kɜːrbd sɪˈlɛktɪv rɪˈpɔːrtɪŋ/","tokens":["curbed selective reporting.","be archived publicly","curbing selective","clinical raw data","The stipulation that","is archived"],"target_translation":"Ketentuan tegas agar data mentah klinis diarsipkan secara terbuka berhasil menekan pelaporan tebang pilih."}'::jsonb, '["The stipulation that","clinical raw data","be archived publicly","curbed selective reporting."]'::jsonb, NULL, NULL, '''The stipulation that ... be archived'' berfungsi sebagai subjek bagi verba lampau ''curbed''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000401', 'e5100001-0000-4000-8000-000000000050', NULL, 'reading', 'fill_blank', 'Pilih adverbia kritis C1 yang menyiratkan kontras antara klaim di permukaan dan motif sebenarnya:', '{"options":["inadvertently","ostensibly","mutually","unanimously"],"translation":"Aturan inspeksi impor baru tersebut di permukaan diperkenalkan demi keamanan kesehatan tanaman, padahal pelobi domestiklah yang menyusun setiap pasalnya.","sentence_template":"The new import inspection rule was [blank] introduced for phytosanitary safety, yet domestic lobbyists had drafted every clause."}'::jsonb, '{"selected":"ostensibly"}'::jsonb, NULL, NULL, '''Ostensibly'' menandai tujuan yang diklaim secara luar namun patut dicurigai motif aslinya.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000402', 'e5100001-0000-4000-8000-000000000050', NULL, 'reading', 'fill_blank', 'Pilih istilah metodologi untuk faktor tersembunyi yang mengacaukan kesimpulan kausal:', '{"options":["single failure","keystone species","dealbreaker","confounding variable"],"translation":"Tanpa mengontrol kekayaan rumah tangga sebagai variabel perancu, studi yang mengaitkan bimbingan privat dengan pendapatan kuliah berisiko melebih-lebihkan dampak kausal.","sentence_template":"Without controlling for household wealth as a [blank], studies linking private tutoring to college income risk overstating causal impact."}'::jsonb, '{"selected":"confounding variable"}'::jsonb, NULL, NULL, '''Confounding variable'' adalah variabel ketiga yang memengaruhi baik variabel bebas maupun terikat.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000403', 'e5100001-0000-4000-8000-000000000050', NULL, 'listening', 'listening_choice', 'Dengarkan profesor mengevaluasi esai draf mahasiswa. Mengapa kalimat klaim mahasiswa diminta diperlunak (hedged)?', '{"options":[{"id":"opt_1","text":"Profesor melarang mahasiswa membahas kesehatan mental remaja di esai"},{"id":"opt_2","text":"Kalimat akademik wajib menggunakan kata ''every country'' agar terdengar tegas"},{"id":"opt_3","text":"Klaim mutlak mudah dipatahkan satu contoh pengecualian, sedangkan bahasa terukur berbasis korelasi jauh lebih akurat secara ilmiah"},{"id":"opt_4","text":"Data jangka panjang membuktikan media sosial menyembuhkan kecemasan"}],"audio_text":"Writing ''Social media causes teen depression in every country'' invites immediate refutation—try ''Longitudinal data suggests heavy passive scrolling tends to correlate with elevated anxiety.''"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Prinsip inti penulisan akademik AS: klaim yang dikualifikasi secara presisi (''tends to correlate with'') jauh lebih tak terbantahkan daripada klaim ekstrem.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000404', 'e5100001-0000-4000-8000-000000000050', NULL, 'writing', 'sentence_builder', 'Susun kalimat pembuka esai akademik menggunakan ''arguably'':', '{"romaji":"/ˌsɛmikənˈdʌktər lɪˈθɑːɡrəfi ɪz ˈɑːrɡjuəbli ðə moʊst ˈkɑːmplɛks ˌmænjəˈfæktʃərɪŋ fiːt/","tokens":["complex manufacturing feat","Semiconductor lithography is","arguably the most","feat complexly","in modern industry.","arguing most"],"target_translation":"Litografi semikonduktor bisa dibilang merupakan pencapaian manufaktur paling rumit dalam industri modern."}'::jsonb, '["Semiconductor lithography is","arguably the most","complex manufacturing feat","in modern industry."]'::jsonb, NULL, NULL, 'Menyisipkan ''arguably'' sebelum superlatif (''the most complex'') menjaga klaim besar tetap elegan dan akademis.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000405', 'e5100001-0000-4000-8000-000000000050', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat akademik ber-hedging berikut dengan intonasi objektif:', '{"romaji":"/kəmˈpɛlɪŋ ˈɛvədəns səɡˈdʒɛsts ðæt ˈɜːrbən ɡriːn ˈspeɪsɪz ˈmɪtəˌɡeɪt ˌkɑːrdioʊˈvæskjələr strɛs/","display_text":"Compelling evidence suggests that urban green spaces mitigate cardiovascular stress.","phonetic_breakdown":["Compelling evidence","suggests that","urban green spaces","mitigate cardiovascular stress."]}'::jsonb, '{"expected_transcript":"Compelling evidence suggests that urban green spaces mitigate cardiovascular stress."}'::jsonb, NULL, NULL, 'Lafalkan flap /ɾ/ halus pada ''mitigate'' (/ˈmɪɾəˌɡeɪt/) dan tekanan jelas pada ''com-PEL-ling''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000406', 'e5100001-0000-4000-8000-000000000050', NULL, 'reading', 'fill_blank', 'Pilih frasa modal yang menyatakan ''kemungkinan besar yang beralasan kuat'':', '{"options":["may well","can scarcely not","ought","must to"],"translation":"Jika baterai natrium skala jaringan mencapai keseimbangan harga komersial pada 2028, kelangkaan litium besar kemungkinan mereda lebih cepat dari perkiraan analis.","sentence_template":"If grid-scale sodium batteries hit commercial parity by 2028, lithium shortages [blank] ease sooner than analysts expect."}'::jsonb, '{"selected":"may well"}'::jsonb, NULL, NULL, '''May well + V1'' menyatakan probabilitas kuat yang terukur tanpa kepastian sembrono.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000407', 'e5100001-0000-4000-8000-000000000050', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah epidemiologi TOEFL. Mengapa profesor memperingatkan soal ''reverse causality''?', '{"options":[{"id":"opt_1","text":"Kopi tanpa kafein terbukti meningkatkan tekanan darah secara kimiawi"},{"id":"opt_2","text":"Tekanan darah tinggilah yang mendorong pasien beralih ke kopi tanpa kafein atas saran dokter, bukan sebaliknya"},{"id":"opt_3","text":"Survei tersebut hanya melibatkan responden berusia di bawah sepuluh tahun"},{"id":"opt_4","text":"Dokter melarang pasien hipertensi meminum air putih maupun kopi"}],"audio_text":"When a survey finds that people who drink decaf coffee have higher blood pressure, don''t blame decaf—doctors had already advised hypertensive patients to switch to decaf!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Memahami *reverse causality* (sebab-akibat terbalik) krusial di bacaan dan kuliah sains sosial/medis TOEFL.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000408', 'e5100001-0000-4000-8000-000000000050', NULL, 'writing', 'sentence_builder', 'Susun kalimat kualifikasi temuan ilmiah dengan ''appears to'':', '{"romaji":"/ˌɪntərˈmɪtənt ˈfæstɪŋ əˈpɪrz tə ɪmˈpruːv ɡlaɪˈsiːmɪk kənˈtroʊl praɪˈmɛrəli θruː kəˈlɔːrɪk rɪˈstrɪkʃən/","tokens":["Intermittent fasting","glycemic control,","primarily through caloric restriction.","appearing improve","through calorically","appears to improve"],"target_translation":"Puasa berselang tampaknya memperbaiki kendali glikemik, terutama melalui pembatasan kalori."}'::jsonb, '["Intermittent fasting","appears to improve","glycemic control,","primarily through caloric restriction."]'::jsonb, NULL, NULL, '''Appears to + V1'' diikuti pengkhususan mekanisme '', primarily through...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000409', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Pilih infinitif sempurna (perfect infinitive) untuk peristiwa lampau sesudah ''is estimated'':', '{"options":["to have lowered","to lower now","having lowered","that lowered"],"translation":"Letusan Gunung Tambora tahun 1815 diperkirakan telah menurunkan suhu rata-rata global hampir satu derajat Celsius.","sentence_template":"The 1815 eruption of Mount Tambora is estimated [blank] global average temperatures by nearly one degree Celsius."}'::jsonb, '{"selected":"to have lowered"}'::jsonb, NULL, NULL, 'Karena letusan terjadi pada 1815 namun estimasi dipegang saat ini (''is estimated''), wajib memakai ''to have + V3'' (''to have lowered'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000410', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Pilih konjungsi pembatas ruang lingkup C1 yang berarti ''sejauh / hanya dalam batas bahwa'':', '{"options":["contrary to","insofar as","lest","no sooner"],"translation":"Skor tes terstandarisasi bersifat informatif sejauh skor tersebut mengukur kesiapan akademik berdampingan dengan nilai rapor SMA.","sentence_template":"Standardized test scores are informative [blank] they measure academic readiness alongside high school grades."}'::jsonb, '{"selected":"insofar as"}'::jsonb, NULL, NULL, '''Insofar as + S + V'' membatasi kondisi di mana suatu klaim berlaku valid.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000411', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'listening', 'listening_choice', 'Dengarkan kritik metodologi dalam seminar psikologi eksperimental. Apa keterbatasan sampel yang disoroti pembicara?', '{"options":[{"id":"opt_1","text":"Sembilan puluh lima persen peserta riset berasal dari pedesaan Asia"},{"id":"opt_2","text":"Petani subsisten memiliki perilaku risiko yang persis sama dengan mahasiswa AS"},{"id":"opt_3","text":"Eksperimen tersebut gagal mengumpulkan data dari mahasiswa sarjana"},{"id":"opt_4","text":"Temuan dari sampel mahasiswa psikologi AS tidak dapat digeneralisasikan begitu saja pada petani subsisten"}],"audio_text":"Because ninety-five percent of participants were American psychology undergraduates, these risk-aversion findings cannot readily be extrapolated to subsistence farmers."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Kritik sampel *WEIRD* (*Western, Educated, Industrialized, Rich, Democratic*) menggunakan verba ''cannot readily be extrapolated to...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000412', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'writing', 'sentence_builder', 'Susun kalimat pasif epistemik tentang naskah kuno berikut:', '{"romaji":"/ðə ˈkɑːpər skroʊl ɪz θɔːt tə həv bɪn ɪnˈɡreɪvd ˈdʊrɪŋ ðə naɪnθ ˈsɛntʃəri/","tokens":["engraving during","The copper scroll","the ninth century.","been engraved during","is thought to have","thought having"],"target_translation":"Gulungan tembaga tersebut diperkirakan telah diukir pada abad kesembilan."}'::jsonb, '["The copper scroll","is thought to have","been engraved during","the ninth century."]'::jsonb, NULL, NULL, 'Bentuk pasif sempurna sesudah pasif pelaporan: ''is thought + to have been + V3 (engraved)''!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000413', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kualifikasi kebijakan berikut dengan artikulasi yang jernih:', '{"romaji":"/baɪ ænd lɑːrdʒ kənˈdʒɛstʃən ˈtʃɑːrdʒɪz kɜːrb ɪˈmɪʃənz ˌɪnsoʊˈfɑːr æz ˈtrænzɪt ɔːlˈtɜːrnətɪvz ɪɡˈzɪst/","display_text":"By and large, congestion charges curb emissions insofar as transit alternatives exist.","phonetic_breakdown":["By and large,","congestion charges curb emissions","insofar as","transit alternatives exist."]}'::jsonb, '{"expected_transcript":"By and large, congestion charges curb emissions insofar as transit alternatives exist."}'::jsonb, NULL, NULL, 'Lafalkan ''alternatives'' ala AS /ɔːlˈtɜːrnətɪvz/ dan sambungkan ''By_and_large'' secara luwes.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000414', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Pilih bentuk infinitif aktif masa kini sesudah ''are widely held'' untuk fakta yang berlaku sekarang:', '{"options":["that harbor","to harbor","harboring","have harbored"],"translation":"Ventilasi hidrotermal laut dalam secara luas diyakini menampung ekosistem kemosintetik unik yang tak bergantung pada sinar matahari.","sentence_template":"Deep-sea hydrothermal vents are widely held [blank] unique chemosynthetic ecosystems independent of sunlight."}'::jsonb, '{"selected":"to harbor"}'::jsonb, NULL, NULL, 'Karena kondisi tersebut masih berlangsung saat ini, gunakan present infinitive ''to harbor'' (ejaan AS tanpa ''u''!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000415', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'listening', 'listening_choice', 'Dengarkan rangkuman analis riset ekonomi. Apa arti ungkapan ''by and large'' dalam kesimpulannya?', '{"options":[{"id":"opt_1","text":"Tidak ada satu pun pelabuhan yang mengalami kendala teknis"},{"id":"opt_2","text":"Portal bea cukai gagal total di seluruh pelabuhan Nusantara"},{"id":"opt_3","text":"Secara umum di hampir seluruh kepulauan waktu bea cukai berhasil dipangkas, meskipun segelintir pelabuhan sempat mengalami kendala sementara"},{"id":"opt_4","text":"Sistem satu pintu hanya diterapkan pada kapal pesiar wisata"}],"audio_text":"While a few port districts experienced temporary bottlenecks, by and large the single-window customs portal shortened clearance times across the archipelago."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''By and large'' merangkum keberhasilan umum secara jujur sambil tetap mengakui adanya pengecualian kecil.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000416', 'e5100001-0000-4000-8000-000000000051', 'e2000001-0000-4000-8000-000000000043', 'writing', 'sentence_builder', 'Susun kalimat batasan ekstrapolasi laboratorium berikut:', '{"romaji":"/ˈroʊdənt lɑːnˈdʒɛvəti ɡeɪnz ˈkænɑːt ˌɔːtəˈmætɪkli bi ɪkˈstræpəˌleɪtɪd tə ˈhjuːmən ˈklɪnɪkəl ˈaʊtˌkʌmz/","tokens":["cannot automatic","cannot automatically be","Rodent longevity gains","extrapolated to","extrapolating into","human clinical outcomes."],"target_translation":"Peningkatan usia panjang pada hewan pengerat tidak dapat secara otomatis diekstrapolasi ke hasil klinis manusia."}'::jsonb, '["Rodent longevity gains","cannot automatically be","extrapolated to","human clinical outcomes."]'::jsonb, NULL, NULL, 'Lafalkan ''longevity'' /lɑːnˈdʒɛvəti/ (dengan bunyi /dʒ/ lembut seperti ''jet'') dalam pola ''be extrapolated to''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000417', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Lengkapi kalimat yang menunjukkan sikap hati-hati dan belum yakin terhadap teknologi baru:', '{"options":["remains to be seen","is mutually exclusive","goes without saying","stands beyond doubt"],"translation":"Meskipun prototipe lab mencapai efisiensi surya dua puluh delapan persen, masih perlu dibuktikan ke depan apakah panel perovskit tahan melewati sepuluh musim panas lembap.","sentence_template":"While lab prototypes achieved twenty-eight percent solar efficiency, it [blank] whether perovskite panels can survive ten humid summers."}'::jsonb, '{"selected":"remains to be seen"}'::jsonb, NULL, NULL, '''It remains to be seen whether...'' menyatakan ketidakpastian masa depan secara objektif.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000418', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Pilih frasa evaluatif kritis untuk bukti yang sangat lemah:', '{"options":["tentative at best","paramount at least","unanimous by far","compelling in full"],"translation":"Menentukan usia seluruh peradaban hanya dari tiga pecahan tembikar permukaan paling banter bersifat sementara/lemah dan menuntut penggalian stratigrafis.","sentence_template":"Dating an entire civilization from three surface pottery shards is [blank] and requires stratigraphic excavation."}'::jsonb, '{"selected":"tentative at best"}'::jsonb, NULL, NULL, '''[Weak adjective] + at best'' menegaskan bahwa bahkan dalam penilaian paling murah hati sekalipun, buktinya masih lemah.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000419', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'listening', 'listening_choice', 'Dengarkan nada dan pilihan kata profesor sejarah pada kuliah TOEFL berikut. Bagaimana sikap profesor terhadap catatan kronik istana tersebut?', '{"options":[{"id":"opt_1","text":"Skeptis terhadap keakuratan angka karena penulis kronik istana cenderung melebih-lebihkan kemenangan rajanya"},{"id":"opt_2","text":"Marah kepada mahasiswa karena membaca catatan sejarah kuno"},{"id":"opt_3","text":"Sepenuhnya percaya bahwa sepuluh ribu kapal menyerah tanpa kerusakan sedikit pun"},{"id":"opt_4","text":"Tidak peduli sama sekali terhadap sejarah pertempuran laut tersebut"}],"audio_text":"Of course, the royal chronicler claims ten thousand enemy ships surrendered without a scratch—we obviously have to take those numbers with a generous grain of salt."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Take [X] with a (generous) grain of salt'' menunjukkan keraguan kritis terhadap sumber yang berpotensi bias.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000420', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'writing', 'sentence_builder', 'Susun kalimat peringatan ilmiah agar tidak tergesa-gesa menyimpulkan:', '{"romaji":"/ˈɡɪvən ðə smɔːl ˈkoʊhɔːrt saɪz ɪt wʊd bi ˌpriːməˈtʃʊr tə kənˈkluːd ˈɛfɪkəsi/","tokens":["prematurely concluding","to conclude efficacy.","would be premature","Given the small","would premature","cohort size, it"],"target_translation":"Mengingat ukuran kelompok sampel yang kecil, terlalu dini untuk menyimpulkan kemanjuran terapi tersebut."}'::jsonb, '["Given the small","cohort size, it","would be premature","to conclude efficacy."]'::jsonb, NULL, NULL, '''It would be premature to conclude...'' adalah standar emas kehati-hatian ilmiah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000421', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'speaking', 'speaking_repeat', 'Ucapkan kalimat evaluasi kritis berikut dengan penekanan halus pada ''speculative at best'':', '{"romaji":"/ʌnˈtɪl ˌɪndɪˈpɛndənt læbz ˈrɛplɪˌkeɪt ðə ˈsɪɡnəl ðæt haɪˈpɑːθəsɪs rɪˈmeɪnz ˈspɛkjələtɪv æt bɛst/","display_text":"Until independent labs replicate the signal, that hypothesis remains speculative at best.","phonetic_breakdown":["Until independent labs","replicate the signal,","that hypothesis remains","speculative at best."]}'::jsonb, '{"expected_transcript":"Until independent labs replicate the signal, that hypothesis remains speculative at best."}'::jsonb, NULL, NULL, 'Gunakan intonasi tenang dan terukur pada ''SPEC-u-la-tive at BEST''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000422', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Pilih kata sifat sikap akademik yang tepat jika seorang ilmuwan melihat potensi baik tetapi tetap sadar keterbatasan awal:', '{"options":["cautiously optimistic","utterly indifferent","openly hostile","blindly dogmatic"],"translation":"Sebagian besar pakar biologi kelautan bersikap optimistis dengan penuh kehati-hatian terhadap uji adaptasi panas karang—terdorong oleh keberhasilan lab, namun realistis soal skala lautan.","sentence_template":"Most marine biologists remain [blank] about coral heat-adaptation trials—encouraged by lab survival, yet realistic about ocean scale."}'::jsonb, '{"selected":"cautiously optimistic"}'::jsonb, NULL, NULL, '''Cautiously optimistic'' adalah frasa kunci soal *Speaker Attitude* di TOEFL Listening & Reading.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000423', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'listening', 'listening_choice', 'Dengarkan komentar profesor astronomi tentang klaim sinyal kehidupan di atmosfer Venus. Apa penilaian profesor?', '{"options":[{"id":"opt_1","text":"Profesor memastikan kehidupan mikroba di awan Venus sudah terbukti mutlak"},{"id":"opt_2","text":"Gunung berapi di Venus mustahil menghasilkan reaksi kimia apa pun"},{"id":"opt_3","text":"Garis spektrum fosfin terbukti hanya kerusakan teleskop belaka"},{"id":"opt_4","text":"Temuan garis spektrum itu menarik, namun melompat ke kesimpulan mikroba udara terlalu dini sebelum reaksi kimia vulkanik tak hidup dikesampingkan"}],"audio_text":"Look, detecting phosphine spectral lines is intriguing, no question—but jumping straight to aerial microbes when abiotic volcano chemistry hasn''t been ruled out is premature."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Sikap berimbang khas TOEFL: mengakui ketertarikan awal (''intriguing''), namun menahan kesimpulan (''premature'' karena alternatif abiotik belum *ruled out*).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000424', 'e5100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000043', 'writing', 'sentence_builder', 'Susun kalimat subjek klausa ''Whether...'' dengan ''remains to be seen'':', '{"romaji":"/ˈwɛðər ˈsɑːlɪd steɪt ˈbætəriz kæn skeɪl əˈfɔːrdəbli fɔːr mæs ˈmɑːrkɪt kɑːrz rɪˈmeɪnz tə bi siːn/","tokens":["for mass-market cars","Whether solid-state batteries","If or not","remain to see","remains to be seen.","can scale affordably"],"target_translation":"Apakah baterai padat dapat diproduksi massal secara terjangkau bagi mobil pasar luas masih perlu dilihat ke depan."}'::jsonb, '["Whether solid-state batteries","can scale affordably","for mass-market cars","remains to be seen."]'::jsonb, NULL, NULL, 'Di awal kalimat sebagai subjek, wajib gunakan ''Whether...'' (TIDAK BOLEH ''If...''!) diikuti verba tunggal ''remains to be seen''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000425', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih bentuk perfect infinitive pasif epistemik untuk peristiwa kuno:', '{"options":["to have sailed","to be sail","that sailed","sailing"],"translation":"Kano berlambung ganda Polinesia diyakini telah berlayar ribuan mil melawan angin pasat dominan.","sentence_template":"Polynesian double-hulled canoes are believed [blank] thousands of miles against prevailing trade winds."}'::jsonb, '{"selected":"to have sailed"}'::jsonb, NULL, NULL, '''Are believed + to have + V3 (sailed)'' menghubungkan keyakinan ilmiah kini dengan pelayaran masa silam.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000426', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih kata sambung pembatas validitas argumen:', '{"options":["insofar as","lest","no sooner","ostensibly"],"translation":"Penyaringan resume algoritmik menghemat jam kerja rekruter sejauh data pelatihan historisnya diaudit terhadap bias demografis.","sentence_template":"Algorithmic resume screening saves recruiter hours [blank] historical training data is audited for demographic bias."}'::jsonb, '{"selected":"insofar as"}'::jsonb, NULL, NULL, '''Insofar as'' mengikat kebenaran klaim pertama pada syarat ketiadaan bias.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000427', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'listening', 'listening_choice', 'Evaluasi Unit 3 — Dengarkan ulasan sejawat atas makalah ekonomi pendidikan. Masalah metodologi apa yang diungkap?', '{"options":[{"id":"opt_1","text":"Musik terbukti menurunkan nilai akademik siswa sekolah menengah"},{"id":"opt_2","text":"Peninjau meminta ukuran sampel dikurangi menjadi sepuluh siswa"},{"id":"opt_3","text":"Seluruh siswa di dalam sampel berasal dari keluarga berpendapatan identik"},{"id":"opt_4","text":"Makalah tersebut mengabaikan status sosial-ekonomi sebagai variabel perancu besar yang memengaruhi kedua kelompok"}],"audio_text":"Comparing test scores of students who attend music conservatories with non-musicians ignores socioeconomic status as a massive confounding variable."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Mengidentifikasi *confounding variable* sebagai celah validitas internal studi observasional.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000428', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'writing', 'sentence_builder', 'Evaluasi Unit 3 — Susun kalimat analisis kritis menggunakan ''ostensibly'':', '{"romaji":"/ðə ˈlaɪsənsɪŋ ɪɡˈzæm ɑːˈstɛnsəbli dɪˈzaɪnd tə prəˈtɛkt ˈpʌblɪk ˈseɪfti ˈʃiːldɪd ɪnˈkʌmbənts/","tokens":["ostensible designing","The licensing exam,","protect public safety,","ostensibly designed to","from competing","shielded incumbents from competition."],"target_translation":"Ujian lisensi tersebut, yang di permukaan dirancang untuk melindungi keselamatan publik, justru membentengi pemain lama dari persaingan."}'::jsonb, '["The licensing exam,","ostensibly designed to","protect public safety,","shielded incumbents from competition."]'::jsonb, NULL, NULL, 'Frasa partisip ber-adverbia '', ostensibly designed to...,'' membedah motif tersembunyi kebijakan.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000429', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'speaking', 'speaking_repeat', 'Evaluasi Unit 3 — Ucapkan kalimat hedging ilmiah C1 berikut dengan jelas:', '{"romaji":"/ˌɑːbzərˈveɪʃənəl ˈfaɪndɪŋz ˈkænɑːt bi ɪkˈstræpəˌleɪtɪd tə ˈklɪnɪkəl ˌpɑːpjəˈleɪʃənz wɪˈðaʊt ˈrændəˌmaɪzd ˈtraɪəlz/","display_text":"Observational findings cannot be extrapolated to clinical populations without randomized trials.","phonetic_breakdown":["Observational findings","cannot be extrapolated","to clinical populations","without randomized trials."]}'::jsonb, '{"expected_transcript":"Observational findings cannot be extrapolated to clinical populations without randomized trials."}'::jsonb, NULL, NULL, 'Perhatikan ejaan Amerika ''randomized'' (dengan ''z'') dan artikulasi ''ex-TRAP-o-la-ted''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000430', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih kata awal yang gramatikal untuk klausa nomina subjek sebelum ''remains to be seen'':', '{"options":["If","Whether","That whether","Did"],"translation":"Apakah biaya penangkapan karbon akan turun cukup cepat untuk mendekarbonisasi industri semen masih perlu dibuktikan ke depan.","sentence_template":"[blank] carbon capture costs will fall fast enough to decarbonize cement manufacturing remains to be seen."}'::jsonb, '{"selected":"Whether"}'::jsonb, NULL, NULL, 'Klausa nomina ketidakpastian di posisi subjek kalimat wajib diawali ''Whether'' (bukan ''If'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000431', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'listening', 'listening_choice', 'Evaluasi Unit 3 — Dengarkan sikap profesor linguistik terhadap klaim aplikasi penerjemah instan. Apa pandangan profesor?', '{"options":[{"id":"opt_1","text":"Mesin penerjemah sudah melampaui diplomat manusia dalam menangkap sindiran budaya"},{"id":"opt_2","text":"Profesor menyarankan jurusan bahasa asing segera ditutup tahun ini"},{"id":"opt_3","text":"Menganggap penerjemah diplomatik manusia sudah usang terlalu spekulatif karena mesin masih sering gagal menangkap nuansa pragmatik"},{"id":"opt_4","text":"Terjemahan saraf gagal menerjemahkan pemesanan kamar hotel sederhana"}],"audio_text":"Sure, neural translation handles hotel bookings effortlessly, yet claiming it renders human diplomatic interpreters obsolete is speculative at best—pragmatic nuance still trips machines up."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Speculative at best'' menegaskan penolakan terukur terhadap klaim yang berlebihan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000432', 'e5100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000043', 'writing', 'sentence_builder', 'Evaluasi Unit 3 — Susun kalimat superlatif terukur dengan ''arguably'':', '{"romaji":"/kliːn ˈdrɪŋkɪŋ ˈwɔːtər ˈɪnfrəˌstrʌktʃər wʌz ˈɑːrɡjuəbli ðə ˈsɪŋɡəl ˈɡreɪtɪst ˈpʌblɪk hɛlθ ˈtraɪʌmf/","tokens":["triumphs greatest","public health triumph.","arguable the","infrastructure was arguably","Clean drinking water","the single greatest"],"target_translation":"Infrastruktur air minum bersih bisa dibilang merupakan satu-satunya kejayaan kesehatan masyarakat terbesar."}'::jsonb, '["Clean drinking water","infrastructure was arguably","the single greatest","public health triumph."]'::jsonb, NULL, NULL, '''Arguably + the single + superlative'' memberi bobot retoris tanpa kehilangan kehati-hatian akademik.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000433', 'e5100001-0000-4000-8000-000000000054', NULL, 'reading', 'fill_blank', 'Pilih kata kerja berkelas C1 yang menggantikan ''made me quickly want to study'' dalam pembuka SoP:', '{"options":["stagnated","waived","catalyzed","digressed"],"translation":"Menyelidiki kehilangan pascapanen kakao di Sulawesi memicu langkah saya mendalami optimisasi rantai pasok.","sentence_template":"Investigating post-harvest cocoa losses in Sulawesi [blank] my pursuit of supply-chain optimization."}'::jsonb, '{"selected":"catalyzed"}'::jsonb, NULL, NULL, '''Catalyzed my pursuit of / commitment to'' menghubungkan pengalaman lapangan langsung ke fokus akademik.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000434', 'e5100001-0000-4000-8000-000000000054', NULL, 'reading', 'fill_blank', 'Pilih istilah kebijakan yang tepat dan bermartabat untuk wilayah yang belum terlayani perbankan:', '{"options":["underserved","ostensible","redundant","obsolete"],"translation":"Platform tabungan mikro seluler tanpa agen memperluas inklusi keuangan di komunitas kepulauan yang selama ini kurang terlayani.","sentence_template":"Agentless mobile micro-savings platforms expand financial inclusion across [blank] island communities."}'::jsonb, '{"selected":"underserved"}'::jsonb, NULL, NULL, '''Underserved communities'' adalah diksi standar pembangunan internasional yang akurat dan empatik.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000435', 'e5100001-0000-4000-8000-000000000054', NULL, 'listening', 'listening_choice', 'Dengarkan umpan balik mentor beasiswa Fulbright atas paragraf pembuka pelamar. Mengapa pembuka kedua jauh lebih unggul?', '{"options":[{"id":"opt_1","text":"Membuka langsung dengan bukti kontribusi teknis nyata di lapangan jauh lebih meyakinkan komite seleksi ketimbang klise masa kecil"},{"id":"opt_2","text":"Komite seleksi Fulbright mewajibkan pelamar menceritakan hobi usia lima tahun"},{"id":"opt_3","text":"Pelamar disarankan menghapus seluruh pencapaian riset dari paragraf pertama"},{"id":"opt_4","text":"Pengalaman pemetaan bencana di Aceh dianggap tidak relevan untuk jurusan teknik"}],"audio_text":"Skip the childhood cliché about loving airplanes at age five—open directly with the moment your drone mapping algorithm helped disaster responders locate washed-out bridges in Aceh."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Komite seleksi AS mencari *evidence of agency and research maturity*, bukan romantisme masa kanak-kanak.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000436', 'e5100001-0000-4000-8000-000000000054', NULL, 'writing', 'sentence_builder', 'Susun kalimat rencana pascastudi untuk esai LPDP berikut:', '{"romaji":"/ɪˈkwɪpt wɪð ˈspeɪʃəl ɪˌkɑːnəˈmɛtrɪks ˈtreɪnɪŋ aɪ eɪm tə brɪdʒ ðə ˈtrænzɪt ˈplænɪŋ ɡæp/","tokens":["the transit planning gap","Equipped with spatial","aimed bridging","econometrics training,","equipping into","I aim to bridge","in secondary cities."],"target_translation":"Dibekali pelatihan ekonometrika spasial, saya menargetkan menjembatani kesenjangan perencanaan transportasi di kota-kota sekunder."}'::jsonb, '["Equipped with spatial","econometrics training,","I aim to bridge","the transit planning gap","in secondary cities."]'::jsonb, NULL, NULL, 'Partisip pasif ''Equipped with [Method],'' mengikat program magister dengan dampak kepulangan secara konkret.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000437', 'e5100001-0000-4000-8000-000000000054', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat visi kontribusi esai beasiswa berikut dengan penuh keyakinan:', '{"romaji":"/əˈpɑːn rɪˈtɜːrnɪŋ tə ˌɪndəˈniːʒə aɪ wɪl ˈspɪrˌhɛd kəˈpæsəti ˈbɪldɪŋ əˈkrɔːs ˈriːdʒənəl hɛlθ læbz/","display_text":"Upon returning to Indonesia, I will spearhead capacity building across regional health labs.","phonetic_breakdown":["Upon returning","to Indonesia,","I will spearhead","capacity building across regional health labs."]}'::jsonb, '{"expected_transcript":"Upon returning to Indonesia, I will spearhead capacity building across regional health labs."}'::jsonb, NULL, NULL, 'Lafalkan ''Indonesia'' ala Amerika /ˌɪndəˈniːʒə/ dengan konsonan lembut /ʒ/ dan tempo mantap.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000438', 'e5100001-0000-4000-8000-000000000054', NULL, 'reading', 'fill_blank', 'Pilih frasa preposisi pembuka formal yang setara dengan ''Immediately after graduating'':', '{"options":["Albeit","Upon","Lest","Whereby"],"translation":"Segera setelah menyelesaikan tesis magister saya tentang penurunan muka tanah pesisir, saya berniat bergabung dengan badan perencanaan tata ruang nasional.","sentence_template":"[blank] completing my master''s thesis on coastal subsidence, I intend to join the national spatial planning agency."}'::jsonb, '{"selected":"Upon"}'::jsonb, NULL, NULL, '''Upon + V-ing'' adalah pembuka kronologi rencana karier jangka pendek yang ringkas dan formal.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000439', 'e5100001-0000-4000-8000-000000000054', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan pelamar doktoral saat wawancara beasiswa mengenai ''Why this university?''. Mengapa jawabannya bernilai tinggi?', '{"options":[{"id":"opt_1","text":"Pelamar memilih kampus tersebut semata-mata karena peringkat keseluruhannya nomor satu"},{"id":"opt_2","text":"Pelamar mengaitkan keunikan metodologi spesifik laboratorium tujuan secara langsung dengan kumpulan data riset yang ia miliki"},{"id":"opt_3","text":"Pelamar ingin mengganti topik risetnya ke bidang sastra abad pertengahan"},{"id":"opt_4","text":"Pelamar belum pernah membaca publikasi ilmiah Profesor Patel sebelumnya"}],"audio_text":"Professor Patel''s group is the only lab combining tropical peatland eddy-covariance towers with satellite SAR interferometry, aligning directly with my Kalimantan dataset."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kesesuaian metodologis spesifik (*research fit*) adalah penentu utama diterimanya pelamar PhD & Fulbright.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000440', 'e5100001-0000-4000-8000-000000000054', NULL, 'writing', 'sentence_builder', 'Susun kalimat kecocokan riset (research fit) pada Statement of Purpose:', '{"romaji":"/maɪ ˈfiːldˌwɜːrk ɪn ˌdʒiːoʊˈθɜːrməl braɪn ɪkˈstrækʃən əˈlaɪnz ˈkloʊsli wɪð prəˈfɛsər ˈmɪlərz/","tokens":["closely align","My fieldwork in","aligns closely with","Professor Miller''s membrane","geothermal brine extraction","desalination research.","aligning into"],"target_translation":"Kerja lapangan saya dalam ekstraksi air tua panas bumi selaras erat dengan riset desalinasi membran Profesor Miller."}'::jsonb, '["My fieldwork in","geothermal brine extraction","aligns closely with","Professor Miller''s membrane","desalination research."]'::jsonb, NULL, NULL, '''Align closely with + [Faculty Research]'' menunjukkan kesiapan kolaborasi akademik.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000441', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Pilih kata penghubung baku untuk menyelesaikan kalimat It-Cleft berfokus waktu berikut:', '{"options":["whereby","which","that","when"],"translation":"Justru ketika menerjemahkan formulir persetujuan pasien di Medan itulah saya menyadari betapa jargon medis mengasingkan keluarga pasien.","sentence_template":"It was while translating patient consent forms in Medan [blank] I realized how medical jargon alienates families."}'::jsonb, '{"selected":"that"}'::jsonb, NULL, NULL, 'Dalam konstruksi It-Cleft (''It was [time/place phrase] + that + S + V''), kata sambung standarnya adalah ''that''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000442', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Pilih struktur Wh-Cleft yang menonjolkan keunggulan pembeda suatu universitas:', '{"options":["Which setting","What sets","That sets","How sets"],"translation":"Hal yang membedakan magister rantai pasok MIT dari program lain adalah proyek akhir sepuluh bulan wajibnya bersama sponsor logistik global.","sentence_template":"[blank] MIT''s supply-chain master''s apart is its mandatory ten-month capstone with global logistics sponsors."}'::jsonb, '{"selected":"What sets"}'::jsonb, NULL, NULL, '''What sets [X] apart is...'' merupakan ungkapan idiomatis C1 yang sangat persuasif pada esai pendaftaran.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000443', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'listening', 'listening_choice', 'Dengarkan jawaban wawancara LPDP ketika panelis bertanya mengapa kandidat beralih dari teknik kimia ke kebijakan publik. Apa benang merah yang ia tonjolkan?', '{"options":[{"id":"opt_1","text":"Ia menganggap regulasi pemerintah sama sekali tidak memerlukan masukan insinyur"},{"id":"opt_2","text":"Pengalaman teknis empat tahun merancang alat penyaring kilang justru memberinya pemahaman mendalam letak kegagalan penegakan regulasi emisi"},{"id":"opt_3","text":"Ia ingin kembali bekerja merancang kilang minyak tanpa mempelajari kebijakan"},{"id":"opt_4","text":"Ia menyesal pernah kuliah teknik kimia dan ingin melupakan pengalaman tersebut"}],"audio_text":"It is precisely because I spent four years designing refinery scrubbers that I understand where emissions regulations fail in technical enforcement."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''It is precisely because [Past Background] that [Present Advantage]'' mengubah perpindahan jalur karier menjadi kekuatan unik!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000444', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'writing', 'sentence_builder', 'Susun kalimat fokus interdisipliner pada Statement of Purpose:', '{"romaji":"/ɪt ɪz prɪˈsaɪsli ðɪs ˌɪntərˈsɛkʃən ʌv lɔː ænd krɪpˈtɑːɡrəfi ðæt ˈmoʊtəˌveɪts maɪ ˈdɑːktərəl ˈriːsɜːrtʃ/","tokens":["law and cryptography","this intersection of","It is precisely","that motivates my","which motivating","doctoral research.","precisely that"],"target_translation":"Persis titik temu antara ilmu hukum dan kriptografi inilah yang memotivasi riset doktoral saya."}'::jsonb, '["It is precisely","this intersection of","law and cryptography","that motivates my","doctoral research."]'::jsonb, NULL, NULL, 'It-Cleft menyoroti nomina tunggal ''this intersection...'', sehingga diikuti verba tunggal ''motivates''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000445', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'speaking', 'speaking_repeat', 'Ucapkan kalimat alasan pemilihan kampus berikut dengan intonasi meyakinkan:', '{"romaji":"/wʌt sɛts ˈmɪʃɪɡənz ˈɪnstəˌtuːt əˈpɑːrt ɪz ɪts ˈoʊpən ˈæksɛs ˈklɪnɪkəl ˈbaɪoʊˌbæŋk/","display_text":"What sets Michigan''s institute apart is its open-access clinical biobank.","phonetic_breakdown":["What sets","Michigan''s institute apart","is its open-access","clinical biobank."]}'::jsonb, '{"expected_transcript":"What sets Michigan''s institute apart is its open-access clinical biobank."}'::jsonb, NULL, NULL, 'Lafalkan ''Michigan'' dengan bunyi /ʃ/ lembut (/ˈmɪʃɪɡən/) dan ''institute'' ala AS /ˈɪnstəˌtuːt/.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000446', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Pilih verba yang tepat pada klausa It-Cleft berfokus subjek jamak (''frontline midwives''):', '{"options":["is detecting","detect","detecting","detects"],"translation":"Para bidan desa garda depanlah yang mendeteksi tanda-tanda peringatan paling awal preeklamsia di kabupaten pedesaan.","sentence_template":"It is frontline village midwives who [blank] the earliest warning signs of preeclampsia in rural districts."}'::jsonb, '{"selected":"detect"}'::jsonb, NULL, NULL, 'Meskipun kalimat dibuka dengan ''It is'', kata kerja sesudah ''who'' wajib selaras dengan anteseden jamak ''frontline village midwives'' → ''detect''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000447', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'listening', 'listening_choice', 'Dengarkan saran direktur penerimaan pascasarjana AS tentang surat rekomendasi dan esai. Apa kesalahan yang membuat esai terasa lemah?', '{"options":[{"id":"opt_1","text":"Menyebutkan nama laboratorium profesor yang relevan dengan tesis"},{"id":"opt_2","text":"Menulis esai di bawah batas maksimum seribu kata"},{"id":"opt_3","text":"Sekadar mengulang daftar riwayat hidup dalam bentuk paragraf alih-alih merangkai benang merah intelektual antarproyek"},{"id":"opt_4","text":"Mencantumkan pertanyaan riset yang ingin dijawab selama studi magister"}],"audio_text":"Don''t just restate every line of your CV in prose—use your Statement of Purpose to connect the intellectual thread behind why one project led to your next question."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Esai SoP unggulan menonjolkan *intellectual thread* (evolusi pertanyaan keilmuan), bukan salinan CV.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000448', 'e5100001-0000-4000-8000-000000000055', 'e2000001-0000-4000-8000-000000000044', 'writing', 'sentence_builder', 'Susun kalimat pembuka paragraf pengalaman kepemimpinan di SoP:', '{"romaji":"/ɪt wʌz waɪl koʊˈɔːrdəˌneɪtɪŋ tsuːˈnɑːmi rɪˈliːf ləˈdʒɪstɪks ðæt aɪ ɡræspt hjuːˌmænəˈtɛriən/","tokens":["logistics that I grasped","humanitarian supply bottlenecks.","grasping into","when I grasped","coordinating Tsunami relief","It was while"],"target_translation":"Justru ketika mengoordinasikan logistik bantuan tsunami itulah saya memahami kemacetan rantai pasok kemanusiaan."}'::jsonb, '["It was while","coordinating Tsunami relief","logistics that I grasped","humanitarian supply bottlenecks."]'::jsonb, NULL, NULL, 'It-Cleft ''It was while + V-ing ... that + S + V2'' memberikan pembuka paragraf yang hidup dan terfokus.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000449', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Pilih kolokasi yang menunjukkan dampak beasiswa yang berlipat ganda bagi masyarakat luas:', '{"options":["tentative nitpick","single point of failure","tangible multiplier effect","confounding variable"],"translation":"Melatih lima puluh instruktur vokasi menciptakan efek pengganda nyata yang menjangkau ribuan peserta magang setiap tahun.","sentence_template":"Training fifty vocational instructors creates a [blank], reaching thousands of apprentices each year."}'::jsonb, '{"selected":"tangible multiplier effect"}'::jsonb, NULL, NULL, '''Tangible multiplier effect'' menjelaskan bagaimana satu intervensi menghasilkan dampak berantai yang terukur.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000450', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Pilih kata kerja kepemimpinan sistemik untuk menanamkan inovasi ke dalam aturan permanen lembaga:', '{"options":["digress","extrapolate from","institutionalize","waive"],"translation":"Demi memastikan reformasi tetap bertahan melewati pergantian pimpinan, kementerian kita harus melembagakan promosi transparan berbasis merit.","sentence_template":"To ensure reforms survive leadership turnover, our ministry must [blank] transparent merit-based promotions."}'::jsonb, '{"selected":"institutionalize"}'::jsonb, NULL, NULL, '''Institutionalize [practices/reforms]'' berarti menjadikannya sistem baku organisasi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000451', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'listening', 'listening_choice', 'Dengarkan jawaban wawancara kandidat beasiswa tentang mengatasi penolakan terhadap sistem digital baru di daerah. Apa pendekatan kandidat?', '{"options":[{"id":"opt_1","text":"Menyelaraskan insentif dengan memangkas beban administrasi manual perawat hingga separuh terlebih dahulu agar mereka merasakan manfaat langsung"},{"id":"opt_2","text":"Menunggu seluruh perawat pensiun sebelum memperkenalkan komputer"},{"id":"opt_3","text":"Menambahkan sepuluh formulir laporan harian baru bagi klinik daerah"},{"id":"opt_4","text":"Memberi sanksi pemecatan langsung kepada perawat yang lambat mengetik"}],"audio_text":"Change rarely succeeds by decree alone—my approach is to align incentives across district clinics by cutting nurses'' manual paperwork in half first."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menjawab pertanyaan *barrier to implementation* dengan strategi *align incentives* yang empatik dan taktis.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000452', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'writing', 'sentence_builder', 'Susun kalimat visi dua tahap (jangka pendek → cetak biru nasional) berikut:', '{"romaji":"/ˈaʊər wɛst ˈdʒɑːvə ˈpaɪlət wɪl sɜːrv æz ə ˈskeɪləbəl ˈbluːˌprɪnt fɔːr ˈnæʃənəl/","tokens":["will serve as","serving into","agricultural logistics.","for national cold-chain","blueprints scalable","Our West Java pilot","a scalable blueprint"],"target_translation":"Uji coba kami di Jawa Barat akan berfungsi sebagai cetak biru terukur bagi logistik rantai dingin pertanian nasional."}'::jsonb, '["Our West Java pilot","will serve as","a scalable blueprint","for national cold-chain","agricultural logistics."]'::jsonb, NULL, NULL, '''Serve as a scalable blueprint for [Macro Goal]'' menjembatani realisme awal dengan visi besar.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000453', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'speaking', 'speaking_repeat', 'Ucapkan pernyataan pembuka wawancara beasiswa berikut dengan tenang dan berwibawa:', '{"romaji":"/ɪn ði ɪˈmiːdiət tɜːrm aɪ plæn tə ɪˈstæblɪʃ ən ˈoʊpən sɔːrs ˈsaɪzmɪk ˈhæzərd læb/","display_text":"In the immediate term, I plan to establish an open-source seismic hazard lab.","phonetic_breakdown":["In the immediate term,","I plan to establish","an open-source","seismic hazard lab."]}'::jsonb, '{"expected_transcript":"In the immediate term, I plan to establish an open-source seismic hazard lab."}'::jsonb, NULL, NULL, 'Beri artikulasi tajam pada ''In the im-ME-di-ate term'' diikuti intonasi terukur.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000454', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Pilih frasa kontras cakrawala waktu untuk melengkapi pasangan ''In the immediate term...'':', '{"options":["in hindsight","no sooner","at best","over the longer horizon"],"translation":"Dalam jangka pendek terdekat, riset saya menyasar titik rawan demam berdarah perkotaan; dalam cakrawala jangka panjang, riset ini membangun platform prediktif bagi arbovirus baru.","sentence_template":"In the immediate term, my research targets urban dengue hotspots; [blank], it establishes a predictive platform for emerging arboviruses."}'::jsonb, '{"selected":"over the longer horizon"}'::jsonb, NULL, NULL, 'Pasangan kohesif wawancara visi: ''In the immediate term...; over the longer horizon...''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000455', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'listening', 'listening_choice', 'Dengarkan pertanyaan penguji Fulbright: ''Why shouldn''t you pursue this master''s locally instead of in the US?''. Bagaimana pelamar menjawab tanpa merendahkan kampus dalam negeri?', '{"options":[{"id":"opt_1","text":"Memuji keunggulan taksonomi lapangan kampus Indonesia lalu memosisikan otomasi CRISPR di Berkeley sebagai pelengkap yang belum tersedia di dalam negeri"},{"id":"opt_2","text":"Menyatakan seluruh universitas dalam negeri tidak memiliki dosen biologi berkualitas"},{"id":"opt_3","text":"Mengaku hanya ingin merasakan tinggal di California selama dua tahun"},{"id":"opt_4","text":"Menolak kembali ke Indonesia setelah menyelesaikan studi magister"}],"audio_text":"Indonesian universities excel in tropical field taxonomy; complementing that strength with Berkeley''s high-throughput CRISPR screening lets me bring missing wet-lab automation home."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Prinsip diplomasi wawancara beasiswa: jangan pernah meremehkan institusi tanah air; bingkai studi luar negeri sebagai *complementary capability*!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000456', 'e5100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000044', 'writing', 'sentence_builder', 'Susun kalimat penutup wawancara beasiswa yang menginspirasi:', '{"romaji":"/əˈlaɪnɪŋ ɪnˈsɛntɪvz əˈkrɔːs ˈfɑːrmərz ænd ˈɔːfˌteɪkərz ɪnˈʃʊrz səˈsteɪnəbəl ˈɪnkʌm/","tokens":["incentive align","ensures sustainable income","farmers and off-takers","long after grant","Aligning incentives across","ensuring sustainably","funding concludes."],"target_translation":"Menyelaraskan insentif antara petani dan pembeli siaga menjamin pendapatan berkelanjutan jauh setelah dana hibah berakhir."}'::jsonb, '["Aligning incentives across","farmers and off-takers","ensures sustainable income","long after grant","funding concludes."]'::jsonb, NULL, NULL, 'Subjek gerund tunggal ''Aligning incentives...'' mengambil verba tunggal ''ensures''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
