INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000458', 'e5100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Pilih kata kerja C1 untuk menggantikan ''triggered quickly'' pada SoP:', '{"options":["waived","ostensibly","extrapolated","catalyzed"],"translation":"Ikut menulis naskah kebijakan telekesehatan nasional Indonesia memicu keputusan saya mengambil spesialisasi hukum informatika kesehatan.","sentence_template":"Co-authoring Indonesia''s national telehealth white paper [blank] my decision to specialize in health informatics law."}'::jsonb, '{"selected":"catalyzed"}'::jsonb, NULL, NULL, '''Catalyzed my decision to...'' menggambarkan pemicu intelektual secara kuat dan ringkas.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000459', 'e5100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000044', 'listening', 'listening_choice', 'Evaluasi Unit 4 — Dengarkan cuplikan Statement of Purpose pelamar PhD teknik elektro. Mengapa paragraf ini sangat persuasif?', '{"options":[{"id":"opt_1","text":"Pelamar ingin meneliti jaringan listrik bawah tanah di kota gurun"},{"id":"opt_2","text":"Pelamar hanya menyalin deskripsi brosur universitas tanpa kaitan pribadi"},{"id":"opt_3","text":"Menggabungkan lima tahun rekam jejak teknis nyata dengan tujuan riset spesifik yang menjawab tantangan geografis kepulauan"},{"id":"opt_4","text":"Pelamar belum memiliki pengalaman kerja maupun topik riset spesifik"}],"audio_text":"Equipped with five years of high-voltage substation diagnostics at PLN, I aim to develop fault-tolerant microgrid controllers tailored for island archipelagos."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Formula emas SoP: ''Equipped with [Concrete Track Record], I aim to develop [Targeted Innovation]''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000460', 'e5100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000044', 'writing', 'sentence_builder', 'Evaluasi Unit 4 — Susun kalimat pembeda program studi dengan Wh-Cleft:', '{"romaji":"/wʌt sɛts dʒɑːnz ˈhɑːpkɪnz əˈpɑːrt ɪz ɪts dʒɔɪnt kəˈrɪkjələm ˈbrɪdʒɪŋ ˌbaɪoʊstəˈtɪstɪks/","tokens":["What sets Johns Hopkins","biostatistics and frontline","joint curriculum bridging","That sets","epidemiology.","apart is its","bridged into"],"target_translation":"Hal yang membedakan Johns Hopkins secara unggul adalah kurikulum gabungannya yang menjembatani biostatistika dan epidemiologi lapangan."}'::jsonb, '["What sets Johns Hopkins","apart is its","joint curriculum bridging","biostatistics and frontline","epidemiology."]'::jsonb, NULL, NULL, 'Perhatikan nama resmi kampus AS adalah ''Johns Hopkins'' (dengan -s pada Johns!) dalam struktur ''What sets X apart is...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000461', 'e5100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000044', 'speaking', 'speaking_repeat', 'Evaluasi Unit 4 — Ucapkan kalimat visi dampak beasiswa berikut dengan artikulasi tegas:', '{"romaji":"/ˌɪnstəˈtuːʃənəˌlaɪzɪŋ ˈoʊpən ˈdeɪtə ˈstændərdz wɪl kriˈeɪt ə ˈtændʒəbəl ˈmʌltəˌplaɪər ɪˈfɛkt ˈneɪʃənˌwaɪd/","display_text":"Institutionalizing open-data standards will create a tangible multiplier effect nationwide.","phonetic_breakdown":["Institutionalizing","open-data standards","will create","a tangible multiplier effect nationwide."]}'::jsonb, '{"expected_transcript":"Institutionalizing open-data standards will create a tangible multiplier effect nationwide."}'::jsonb, NULL, NULL, 'Jaga kefasihan lima suku kata pada ''in-sti-TU-tion-al-i-zing'' tanpa terburu-buru.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000462', 'e5100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000044', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Pilih keselarasan kata kerja sesudah It-Cleft bersubjek jamak:', '{"options":["trains","is training","train","to train"],"translation":"Politeknik vokasi daerah-lah yang melatih teknisi terampil yang dibutuhkan bagi hilirisasi baterai.","sentence_template":"It is local vocational polytechnics that [blank] the skilled technicians needed for battery downstreaming."}'::jsonb, '{"selected":"train"}'::jsonb, NULL, NULL, 'Anteseden ''local vocational polytechnics'' berbentuk jamak, sehingga kata kerja klausa ''that'' memakai ''train''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000463', 'e5100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000044', 'listening', 'listening_choice', 'Evaluasi Unit 4 — Dengarkan jawaban kandidat tentang keberlanjutan proyek sekembalinya ke tanah air. Apa kunci keberlanjutannya?', '{"options":[{"id":"opt_1","text":"Menanamkan modul pelatihan langsung ke orientasi resmi ASN provinsi sehingga penguatan kapasitas berjalan mandiri tanpa bergantung hibah sesaat"},{"id":"opt_2","text":"Menghentikan pelatihan segera setelah masa ikatan dinas berakhir"},{"id":"opt_3","text":"Mengajukan hibah donor luar negeri baru setiap enam bulan selamanya"},{"id":"opt_4","text":"Membatasi pelatihan hanya untuk lima staf di kantor pusat Jakarta"}],"audio_text":"Rather than relying on one-off donor grants, our model embeds training modules directly into provincial civil-service onboarding so capacity building sustains itself."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Melembagakan inovasi ke mekanisme rutin (*embeds directly into onboarding*) membuktikan kelayakan jangka panjang.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000464', 'e5100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000044', 'writing', 'sentence_builder', 'Evaluasi Unit 4 — Susun kalimat penutup Statement of Purpose berikut:', '{"romaji":"/əˈpɑːn kəmˈpliːtɪŋ maɪ ˈdɑːktərəl ˈfɛloʊˌʃɪp aɪ wɪl brɪdʒ ˌækəˈdiːmiə ænd ɪnˈdʌstriəl ˈpɑːləsi/","tokens":["will bridge academia","Upon completing my","and industrial policy","doctoral fellowship, I","Upon complete","in Jakarta.","bridging to"],"target_translation":"Begitu merampungkan beasiswa doktoral saya, saya akan menjembatani dunia akademik dan kebijakan industri di Jakarta."}'::jsonb, '["Upon completing my","doctoral fellowship, I","will bridge academia","and industrial policy","in Jakarta."]'::jsonb, NULL, NULL, 'Lafalkan ''academia'' /ˌækəˈdiːmiə/ dengan vokal panjang /iː/ pada suku kata ketiga.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000465', 'e5100001-0000-4000-8000-000000000058', NULL, 'reading', 'fill_blank', 'Pilih kata kerja akademik yang berarti ''menambahkan batasan syarat pada klaim sebelumnya'':', '{"options":["waive","spearhead","incur","qualify"],"translation":"Di paragraf empat, sejarawan tersebut menyebut catatan serikat pesisir guna memberi batasan syarat atas generalisasi awalnya mengenai isolasi feodal.","sentence_template":"In paragraph four, the historian mentions coastal guild records in order to [blank] her earlier generalization about feudal isolation."}'::jsonb, '{"selected":"qualify"}'::jsonb, NULL, NULL, 'Dalam analisis retorika TOEFL, ''qualify a generalization/claim'' berarti mempersempit atau memperhalus cakupan klaim.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000466', 'e5100001-0000-4000-8000-000000000058', NULL, 'reading', 'fill_blank', 'Pilih verba yang tepat untuk ''menyatukan penjelasan atas dua hasil eksperimen yang tampak bertentangan'':', '{"options":["avert","catalyze","reconcile","extrapolate"],"translation":"Model memori dua tahap membantu ilmuwan saraf mendamaikan studi fMRI aktivitas hipokampus yang semula tampak saling bertentangan.","sentence_template":"A two-stage memory model helped neuroscientists [blank] seemingly contradictory fMRI studies on hippocampus activity."}'::jsonb, '{"selected":"reconcile"}'::jsonb, NULL, NULL, '''Reconcile conflicting/contradictory findings'' berarti menjelaskan mengapa kedua hasil tersebut sebenarnya selaras dalam kerangka yang lebih utuh.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000467', 'e5100001-0000-4000-8000-000000000058', NULL, 'listening', 'listening_choice', 'Dengarkan profesor biologi evolusioner menanggapi bacaan. Apakah profesor menolak bacaan sepenuhnya atau mengualifikasinya?', '{"options":[{"id":"opt_1","text":"Profesor setuju bahwa seluruh hewan pulau tanpa kecuali mengecil ukurannya"},{"id":"opt_2","text":"Profesor membantah pernah adanya gajah kerdil di pulau mana pun"},{"id":"opt_3","text":"Bacaan dan kuliah hanya membahas burung laut bermigrasi"},{"id":"opt_4","text":"Profesor mengakui kebenaran kerdilnya mamalia besar di pulau, namun mengualifikasinya dengan menunjukkan pengerat kecil justru berevolusi menjadi raksasa"}],"audio_text":"The textbook isn''t wrong that island mammals often evolve dwarfism—think pygmy elephants—yet it overlooks that small rodents on those very same islands evolve gigantism when predators are absent!"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Sintesis bernuansa (''The Island Rule''): mengakui kebenaran parsial bacaan untuk mamalia besar, sembari membatasi jangkauannya pada hewan pengerat kecil.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000468', 'e5100001-0000-4000-8000-000000000058', NULL, 'writing', 'sentence_builder', 'Susun kalimat penguatan hipotesis menggunakan ''lend credence to'':', '{"romaji":"/ˈnuːli diːˈkoʊdɪd ˈlɪniər ɪnˈskrɪpʃənz lɛnd ˈkriːdəns tə ˈθiːəriz ʌv ˌmaɪsəˈniːən/","tokens":["Mycenaean palace redistribution.","inscriptions lend credence","lending credences","to theories of","theories into","Newly decoded linear"],"target_translation":"Inskripsi linear yang baru terpecahkan memberikan bobot kepercayaan pada teori distribusi ulang istana Mikenai."}'::jsonb, '["Newly decoded linear","inscriptions lend credence","to theories of","Mycenaean palace redistribution."]'::jsonb, NULL, NULL, 'Kolokasi tetap C1: ''lend credence to + Noun Phrase'' (''credence'' tak terhitung, tanpa -s!).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000469', 'e5100001-0000-4000-8000-000000000058', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat sintesis nuansa riset berikut dengan intonasi analitis:', '{"romaji":"/waɪl kənˈsiːdɪŋ ˈʃɔːrt tɜːrm ɡeɪnz ðə ˈlɛktʃər ˈkwɑːləˌfaɪz ðə ˈriːdɪŋz ˈɑːptəmɪzəm/","display_text":"While conceding short-term gains, the lecturer qualifies the reading''s optimism.","phonetic_breakdown":["While conceding","short-term gains,","the lecturer qualifies","the reading''s optimism."]}'::jsonb, '{"expected_transcript":"While conceding short-term gains, the lecturer qualifies the reading''s optimism."}'::jsonb, NULL, NULL, 'Tekankan kontras intelektual antara ''con-CE-ding'' (mengakui) dan ''QUAL-i-fies'' (membatasi).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000470', 'e5100001-0000-4000-8000-000000000058', NULL, 'reading', 'fill_blank', 'Pilih idiom akademik yang berarti ''membuat ketimpangan tampak sangat mencolok dan jelas'':', '{"options":["swept under","cast into sharp relief","met halfway","took with salt"],"translation":"Penutupan sekolah saat pandemi membuat ketimpangan internet pita lebar antara pinggiran kota besar dan kabupaten pedesaan tampak sangat menonjol.","sentence_template":"Pandemic school closures [blank] existing broadband disparities between metropolitan suburbs and rural districts."}'::jsonb, '{"selected":"cast into sharp relief"}'::jsonb, NULL, NULL, '''Cast [Noun Phrase] into sharp relief'' (atau ''throw into sharp relief'') menonjolkan kontras yang sebelumnya kurang disadari.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000471', 'e5100001-0000-4000-8000-000000000058', NULL, 'listening', 'listening_choice', 'Dengarkan diskusi tinjauan pustaka (literature review) antara mahasiswa PhD dan pembimbingnya. Bagaimana cara menyusun dua studi yang bertolak belakang?', '{"options":[{"id":"opt_1","text":"Menghapus studi Lee 2022 agar tidak bertentangan dengan Smith 2019"},{"id":"opt_2","text":"Mengganti seluruh rujukan sebelum tahun 2024 dengan artikel berita populer"},{"id":"opt_3","text":"Menyintesis bagaimana perbedaan rentang waktu pengambilan sampel mendamaikan ketidaksesuaian semu di antara kedua studi"},{"id":"opt_4","text":"Meringkas masing-masing jurnal secara terpisah tanpa membandingkan metodenya"}],"audio_text":"Instead of summarizing Smith 2019 in one paragraph and Lee 2022 in the next, synthesize how their differing sampling windows reconcile the apparent discrepancy."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Inti *Literature Review* tingkat doktoral adalah menyintesis alasan metodologis di balik perbedaan temuan (*apparent discrepancy*).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000472', 'e5100001-0000-4000-8000-000000000058', NULL, 'writing', 'sentence_builder', 'Susun kalimat rekonsiliasi data ilmiah berikut:', '{"romaji":"/dɪˈstɪŋɡwɪʃɪŋ ˈkoʊstəl fɔːɡ frʌm mɑːnˈsuːn reɪn ˈrɛkənˌsaɪlz ðə tuː kənˈflɪktɪŋ/","tokens":["from monsoon rain","records conflicted","isotope records.","Distinguishing coastal fog","reconciles the two","conflicting tree-ring","reconciling into"],"target_translation":"Membedakan kabut pesisir dari hujan monsun berhasil mendamaikan kedua catatan isotop cincin pohon yang tampak bertentangan tersebut."}'::jsonb, '["Distinguishing coastal fog","from monsoon rain","reconciles the two","conflicting tree-ring","isotope records."]'::jsonb, NULL, NULL, 'Subjek gerund tunggal ''Distinguishing A from B'' mengambil verba tunggal ''reconciles''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000473', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Pilih pasangan paralel untuk melengkapi reframing ''not so much from lack of funding'':', '{"options":["whereas","but of","than by","as from"],"translation":"Keterlambatan implementasi berakar bukan terutama dari kurangnya pendanaan, melainkan dari perizinan kota yang terpecah-pecah.","sentence_template":"Implementation delays stemmed not so much from lack of funding [blank] fragmented municipal permitting."}'::jsonb, '{"selected":"as from"}'::jsonb, NULL, NULL, 'Rumus paralel ''not so much [from A] as [from B]'' mewajibkan kata ''as'' diikuti preposisi yang setara (''from'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000474', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Pilih pembuka konsesi formal sebelum klausa S + V (''admirers praised the prototype''):', '{"options":["Despite of","Much as","Insofar","Contrary to"],"translation":"Meskipun para pengagum awal sangat memuji kecepatan kereta uap tersebut, jalan batu bulat yang kasar menghancurkan poros besinya.","sentence_template":"[blank] early admirers praised the steam carriage''s speed, rough cobblestone roads shattered its iron axles."}'::jsonb, '{"selected":"Much as"}'::jsonb, NULL, NULL, '''Much as + Subject + Verb'' berfungsi sebagai klausa konsesi elegan (= Although ... greatly).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000475', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'listening', 'listening_choice', 'Dengarkan sintesis profesor sosiologi teknologi tentang kecemasan otomatisasi. Bagaimana ia membingkai ulang isu tersebut?', '{"options":[{"id":"opt_1","text":"Profesor berpendapat otomatisasi tidak membawa perubahan apa pun pada pasar kerja"},{"id":"opt_2","text":"Teknologi selalu memusnahkan seluruh lapangan kerja manusia secara permanen"},{"id":"opt_3","text":"Upah keterampilan kognitif turun hingga nol akibat mesin uap"},{"id":"opt_4","text":"Revolusi teknologi tidak menghapus kerja manusia sepenuhnya, melainkan mendefinisikan ulang keterampilan kognitif mana yang dihargai tinggi"}],"audio_text":"Historically, technological revolutions haven''t so much erased human labor altogether as redefined which cognitive skills command a wage premium."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Pola lisan ''haven''t so much [V3 A] as [V3 B]'' menyaring esensi sejarah ekonomi dengan presisi tinggi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000476', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'writing', 'sentence_builder', 'Susun kalimat konvergensi dan divergensi dua mazhab teori berikut:', '{"romaji":"/boʊθ skuːlz kənˈvɜːrdʒ ɑːn ˈraɪzɪŋ ˈtɛmprətʃərz jɛt daɪˈvɜːrdʒ ˈʃɑːrpli ɑːn klaʊd ˈfiːdˌbæk/","tokens":["mechanisms.","on rising temperatures,","on cloud feedback","diverging sharp","Both schools converge","yet diverge sharply","converged into"],"target_translation":"Kedua mazhab sepakat mengenai kenaikan suhu, namun berbeda pandangan secara tajam terkait mekanisme umpan balik awan."}'::jsonb, '["Both schools converge","on rising temperatures,","yet diverge sharply","on cloud feedback","mechanisms."]'::jsonb, NULL, NULL, 'Pasangan antonim akademik: ''converge on [shared ground], yet diverge sharply on [disputed mechanism]''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000477', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pembingkaian ulang ''not so much ... as'' berikut dengan kontras intonasi yang jelas:', '{"romaji":"/səkˈsɛs ɪn ˈɡrædʒuət ˈriːsɜːrtʃ ɪz nɑːt soʊ mʌtʃ rɔː ˈdʒiːnjəs æz ˈdɪsəplɪnd pərˈsɪstəns/","display_text":"Success in graduate research is not so much raw genius as disciplined persistence.","phonetic_breakdown":["Success in graduate research","is not so much","raw genius","as disciplined persistence."]}'::jsonb, '{"expected_transcript":"Success in graduate research is not so much raw genius as disciplined persistence."}'::jsonb, NULL, NULL, 'Naikkan nada sedikit pada ''raw genius'' lalu turunkan mantap pada ''as DIS-ci-plined per-SIS-tence''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000478', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Pilih kata sambung alasan formal yang berarti ''mengingat kenyataan bahwa / sejauh bahwa'':', '{"options":["albeit of","inasmuch as","no sooner","lest"],"translation":"Kumpulan data tersebut menuntut kehati-hatian mengingat kenyataan bahwa responden pedesaan tanpa telepon rumah kurang terwakili secara sistematis.","sentence_template":"The dataset warrants caution [blank] rural respondents without landlines were systematically underrepresented."}'::jsonb, '{"selected":"inasmuch as"}'::jsonb, NULL, NULL, '''Inasmuch as + Clause'' menjelaskan dasar alasan yang spesifik dan terukur dalam prosa formal.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000479', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'listening', 'listening_choice', 'Dengarkan perbandingan dua artikel paleontologi tentang kepunahan megafauna Australia. Di titik mana kedua penulis sepakat dan berbeda?', '{"options":[{"id":"opt_1","text":"Kedua penulis berselisih mengenai kapan megafauna Australia punah"},{"id":"opt_2","text":"Tidak ada bukti fosil megafauna yang ditemukan di benua Australia"},{"id":"opt_3","text":"Kedua penulis sepakat manusia tidak pernah hidup berdampingan dengan megafauna"},{"id":"opt_4","text":"Keduanya sepakat waktu kepunahannya sekitar 46.000 tahun silam, tetapi berbeda tajam soal pemicu utamanya antara pembakaran manusia atau pengeringan iklim"}],"audio_text":"Both authors agree megafauna vanished around forty-six thousand years ago; where they diverge sharply is whether human fire-stick farming or aridification dealt the decisive blow."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Wh-clause fokus kontras: ''where they diverge sharply is whether [A] or [B]...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000480', 'e5100001-0000-4000-8000-000000000059', 'e2000001-0000-4000-8000-000000000045', 'writing', 'sentence_builder', 'Susun kalimat konsesi ''Much as'' dalam tinjauan kebijakan berikut:', '{"romaji":"/mʌtʃ æz ˈmaɪkroʊˌfaɪnæns ɪmˈpaʊərz ˈsoʊloʊ ˈɑːrtəzənz ˈskeɪlɪŋ ɪnˈdʌstriəl dʒɑːbz rɪˈkwaɪərz/","tokens":["scaling industrial jobs","Much as microfinance","requires affordable commercial","credit.","requiring credit","Despite microfinance","empowers solo artisans,"],"target_translation":"Meskipun keuangan mikro sangat memberdayakan perajin mandiri, memperbesar lapangan kerja industri membutuhkan kredit komersial terjangkau."}'::jsonb, '["Much as microfinance","empowers solo artisans,","scaling industrial jobs","requires affordable commercial","credit."]'::jsonb, NULL, NULL, 'Lafalkan ''artisans'' ala Amerika /ˈɑːrtəzənz/ dalam klausa konsesi ''Much as...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000481', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Perhatikan ejaan dengan cermat lalu pilih kata yang berarti ''saling melengkapi'':', '{"options":["complementary","complimentary","ostensible","confounding"],"translation":"Etnografi kualitatif dan ekonometrika berskala besar menjalankan peran yang saling melengkapi dalam mengevaluasi intervensi kemiskinan.","sentence_template":"Qualitative ethnography and large-scale econometrics serve [blank] roles in evaluating poverty interventions."}'::jsonb, '{"selected":"complementary"}'::jsonb, NULL, NULL, '''Complementary'' (dengan huruf ''e'') berarti saling menyempurnakan/melengkapi; ''complimentary'' (dengan ''i'') berarti memuji atau cuma-cuma.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000482', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Pilih kata kerja C1 yang berarti ''menjadi landasan penopang utama bagi suatu kerangka'':', '{"options":["underpin","digress","extrapolate","waive"],"translation":"Bukti tanpa-pengetahuan kriptografis menopang arsitektur privasi dompet identitas digital generasi berikutnya.","sentence_template":"Cryptographic zero-knowledge proofs [blank] the privacy architecture of next-generation digital identity wallets."}'::jsonb, '{"selected":"underpin"}'::jsonb, NULL, NULL, '''Underpin + [architecture / framework / theory]'' berarti menjadi fondasi konseptual atau teknis.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000483', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'listening', 'listening_choice', 'Dengarkan rangkuman moderator seminar linguistik terapan. Bagaimana ia memosisikan hipotesis bawaan (innateness) dan input sosial?', '{"options":[{"id":"opt_1","text":"Riset modern mengambil jalan tengah bernuansa di mana kecenderungan biologis dan interaksi sosial saling berinteraksi, bukan saling meniadakan"},{"id":"opt_2","text":"Riset modern membuang peran interaksi sosial sepenuhnya dari pemerolehan bahasa"},{"id":"opt_3","text":"Faktor biologis terbukti tidak memiliki pengaruh apa pun pada anak-anak"},{"id":"opt_4","text":"Kedua mazhab menolak berdiskusi di dalam seminar yang sama"}],"audio_text":"Rather than treating biological predisposition and social interaction as mutually exclusive, modern acquisition research stakes out a nuanced middle ground where both interact."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Stakes out a nuanced middle ground'' adalah ungkapan idiomatis C1 untuk membangun sintesis integratif.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000484', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'writing', 'sentence_builder', 'Susun kalimat sintesis dua model ilmiah yang saling melengkapi:', '{"romaji":"/vjuːd æz ˌkɑːmpləˈmɛntəri tɛkˈtɑːnɪk ˈʌpˌlɪft ænd mɑːnˈsuːn ɪˈroʊʒən ˈdʒɔɪntli əˈkaʊnt fɔːr/","tokens":["account for Himalayan","topography.","monsoon erosion jointly","Viewed as complementary,","tectonic uplift and","accounting into","complimentary viewed"],"target_translation":"Dipandang saling melengkapi, pengangkatan tektonik dan erosi monsun bersama-sama menjelaskan topografi Himalaya."}'::jsonb, '["Viewed as complementary,","tectonic uplift and","monsoon erosion jointly","account for Himalayan","topography."]'::jsonb, NULL, NULL, 'Partisip pasif pembuka ''Viewed as complementary,'' berpadu dengan subjek gabungan ''tectonic uplift and monsoon erosion''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000485', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'speaking', 'speaking_repeat', 'Ucapkan kalimat keunggulan teori baru dalam seminar berikut:', '{"romaji":"/ˈkwɑːntəm ˈtʌnəlɪŋ əˈkaʊnts fɔːr riˈækʃən əˈnɑːməliz æt ˌkraɪəˈdʒɛnɪk ˈtɛmprətʃərz/","display_text":"Quantum tunneling accounts for reaction anomalies at cryogenic temperatures.","phonetic_breakdown":["Quantum tunneling","accounts for","reaction anomalies","at cryogenic temperatures."]}'::jsonb, '{"expected_transcript":"Quantum tunneling accounts for reaction anomalies at cryogenic temperatures."}'::jsonb, NULL, NULL, 'Perhatikan ejaan Amerika ''tunneling'' (satu ''l''!) dan pelafalan ''cry-o-GEN-ic'' (/ˌkraɪəˈdʒɛnɪk/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000486', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Pilih frasa yang tepat untuk posisi argumen yang menghindari dua kutub ekstrem:', '{"options":["blind dogma","confounding variable","scope creep","nuanced middle ground"],"translation":"Terkait regulasi hak cipta AI, makalah kebijakan kami mengusulkan jalan tengah bernuansa melalui registri pilih-keluar dan bagi hasil pendapatan.","sentence_template":"On AI copyright regulation, our policy paper proposes a [blank] through opt-out registries and revenue sharing."}'::jsonb, '{"selected":"nuanced middle ground"}'::jsonb, NULL, NULL, '''A nuanced middle ground'' merangkum solusi kebijakan yang matang dan seimbang.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000487', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'listening', 'listening_choice', 'Dengarkan profesor fisika menjelaskan mengapa relativitas umum Einstein menggantikan gravitasi Newton pada orbit Merkurius. Apa poin kuncinya?', '{"options":[{"id":"opt_1","text":"Kelengkungan ruang-waktu Einstein berhasil menjelaskan anomali pergeseran orbit Merkurius secara presisi yang gagal dijelaskan mekanika Newton"},{"id":"opt_2","text":"Hukum gravitasi Newton gagal memprediksi orbit Bumi maupun Bulan"},{"id":"opt_3","text":"Teori Einstein dan Newton memberikan angka yang meleset pada orbit Merkurius"},{"id":"opt_4","text":"Planet Merkurius tidak memiliki orbit tetap mengelilingi Matahari"}],"audio_text":"Newtonian mechanics predicted planetary orbits superbly except for one stubborn anomaly in Mercury''s perihelion—which Einstein''s spacetime curvature accounted for down to the arcsecond."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Accounted for [the stubborn anomaly] down to the arcsecond'' menunjukkan daya jelaskan (*explanatory power*) teori baru.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000488', 'e5100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000045', 'writing', 'sentence_builder', 'Susun kalimat tentang asumsi dasar kerangka ekonomi berikut:', '{"romaji":"/ɪmˈpɪrɪkəl trʌst ˈsɜːrveɪz ˌʌndərˈpɪn ði ˌɪnstəˈtuːʃənəl ˈfreɪmˌwɜːrk prəˈpoʊzd baɪ dɪˈvɛləpmənt ɪˈkɑːnəmɪsts/","tokens":["Empirical trust surveys","underpin the institutional","underpinning to","framework proposed by","proposing framework","development economists."],"target_translation":"Survei kepercayaan empiris menopang kerangka kelembagaan yang diusulkan oleh para ekonom pembangunan."}'::jsonb, '["Empirical trust surveys","underpin the institutional","framework proposed by","development economists."]'::jsonb, NULL, NULL, 'Subjek jamak ''surveys'' + verba ''underpin'' + objek bermodifikasi partisip pasif ''proposed by...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000489', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih kata kerja retoris TOEFL ketika penulis mempersempit klaim sebelumnya:', '{"options":["waive","compliment","catalyze","qualify"],"translation":"Penulis mengutip lumut kerak tundra alpen guna memberi batasan syarat pada klaim sebelumnya bahwa akar berpembuluh mutlak diperlukan bagi pelapukan batuan.","sentence_template":"The author cites alpine tundra lichens in order to [blank] the earlier claim that vascular roots are required for rock weathering."}'::jsonb, '{"selected":"qualify"}'::jsonb, NULL, NULL, '''Qualify an earlier claim'' menunjukkan adanya pengecualian valid yang memperhalus klaim awal.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000490', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih struktur paralel untuk ''not so much a technical failure'':', '{"options":["but","whereas","than","as"],"translation":"Hilangnya pengorbit Mars tersebut bukanlah terutama kegagalan perangkat keras, melainkan kelalaian konversi satuan antar-tim rekayasa.","sentence_template":"The Mars orbiter loss was not so much a hardware failure [blank] a unit-conversion oversight between engineering teams."}'::jsonb, '{"selected":"as"}'::jsonb, NULL, NULL, 'Pasangan korelatif baku adalah ''not so much [A] as [B]''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000491', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'listening', 'listening_choice', 'Evaluasi Unit 5 — Dengarkan sintesis mahasiswa tingkat C1 atas bacaan dan kuliah arkeologi. Bagaimana kuliah berinteraksi dengan bacaan?', '{"options":[{"id":"opt_1","text":"Menyalin seluruh isi teks bacaan tanpa menambahkan perspektif baru"},{"id":"opt_2","text":"Membantah bahwa bangsa Romawi pernah membangun jaringan jalan berbatu"},{"id":"opt_3","text":"Menyatakan jalan Romawi berhasil menghentikan penyebaran wabah penyakit"},{"id":"opt_4","text":"Mengakui fungsi percepatan militer di bacaan, namun menonjolkan sisi gelap penyebaran wabah perkotaan melalui jalan yang sama"}],"audio_text":"While conceding that Roman roads accelerated military movement as the text states, the lecturer casts into sharp relief how those same highways spread urban plagues."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Memadukan ''While conceding that...'' dengan ''casts into sharp relief how...'' untuk sintesis kontras bernuansa tinggi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000492', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'writing', 'sentence_builder', 'Evaluasi Unit 5 — Susun kalimat rekonsiliasi studi bertentangan berikut:', '{"romaji":"/ˈstrætəˌfaɪɪŋ ˈpeɪʃənts baɪ eɪdʒ ɡruːp ˈrɛkənˌsaɪlz ðə ˈsiːmɪŋli ˌkɑːntrəˈdɪktəri ˈklɪnɪkəl ˈtraɪəl ˈaʊtˌkʌmz/","tokens":["reconciling outcomes","the seemingly contradictory","clinical trial outcomes.","Stratifying patients by","age group reconciles","contradictorily seem"],"target_translation":"Mengelompokkan pasien berdasarkan kelompok usia mendamaikan hasil uji klinis yang semula tampak saling bertentangan tersebut."}'::jsonb, '["Stratifying patients by","age group reconciles","the seemingly contradictory","clinical trial outcomes."]'::jsonb, NULL, NULL, 'Gerund tunggal ''Stratifying patients...'' diikuti verba tunggal ''reconciles''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000493', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'speaking', 'speaking_repeat', 'Evaluasi Unit 5 — Ucapkan kalimat sintesis komplementer berikut dengan artikulasi tepat:', '{"romaji":"/ˈsætəˌlaɪt ˈreɪdɑːr ænd ɡraʊnd ˈɡeɪdʒɪz prəˈvaɪd ˌkɑːmpləˈmɛntəri pərˈspɛktɪvz ɑːn ˈækwəfər dɪˈpliːʃən/","display_text":"Satellite radar and ground gauges provide complementary perspectives on aquifer depletion.","phonetic_breakdown":["Satellite radar","and ground gauges","provide complementary perspectives","on aquifer depletion."]}'::jsonb, '{"expected_transcript":"Satellite radar and ground gauges provide complementary perspectives on aquifer depletion."}'::jsonb, NULL, NULL, 'Lafalkan ''gauges'' sebagai /ˈɡeɪdʒɪz/ (vokal diftong /eɪ/ seperti ''page''!).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000494', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih frasa kolokasi tetap yang berarti ''memberi bobot keterpercayaan pada'':', '{"options":["take salt with","diverge sharply on","incur debt to","lend credence to"],"translation":"Fosil ambar yang baru digali memberi bobot keterpercayaan pada hipotesis bahwa dinosaurus berbulu menghuni hutan beriklim sedang.","sentence_template":"Newly unearthed amber fossils [blank] the hypothesis that feathered dinosaurs inhabited temperate forests."}'::jsonb, '{"selected":"lend credence to"}'::jsonb, NULL, NULL, '''Lend credence to + Noun Phrase'' adalah kolokasi baku penguatan bukti ilmiah.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000495', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'listening', 'listening_choice', 'Evaluasi Unit 5 — Dengarkan diskusi metodologi ekonomi. Mengapa kedua peneliti berbeda kesimpulan soal upah minimum?', '{"options":[{"id":"opt_1","text":"Salah satu ekonom memalsukan berkas sensus nasional"},{"id":"opt_2","text":"Data sensus tersebut tidak memuat informasi pekerjaan paruh waktu"},{"id":"opt_3","text":"Keduanya memakai data sensus yang sama, namun berbeda tajam soal apakah kerja paruh waktu remaja mencerminkan kesehatan pasar kerja keseluruhan"},{"id":"opt_4","text":"Kedua ekonom mencapai kesimpulan kebijakan yang seratus persen identik"}],"audio_text":"Both economists analyze identical census files; they diverge sharply, however, on whether teenage part-time seasonal jobs reflect overall labor market health."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Diverge sharply on whether...'' memetakan akar perbedaan interpretasi atas data yang sama.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000496', 'e5100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000045', 'writing', 'sentence_builder', 'Evaluasi Unit 5 — Susun kalimat pembuka konsesi ''Much as'' berikut:', '{"romaji":"/mʌtʃ æz ˈlæbrəˌtɔːri ˌsɪmjəˈleɪʃənz ˈsɪmpləˌfaɪ ˈtɜːrbjələns ðeɪ ˌʌndərˈpɪn ˈmɑːdərn/","tokens":["they underpin modern","Despite simulations","underpinned into","simulations simplify turbulence,","aerodynamic wing design.","Much as laboratory"],"target_translation":"Meskipun simulasi laboratorium menyederhanakan turbulensi, simulasi tersebut tetap menopang desain sayap aerodinamis modern."}'::jsonb, '["Much as laboratory","simulations simplify turbulence,","they underpin modern","aerodynamic wing design."]'::jsonb, NULL, NULL, 'Perhatikan pelafalan Amerika ''laboratory'': /ˈlæbrəˌtɔːri/ (tekanan di suku kata PERTAMA ''LAB-ra-to-ry'', bukan ''la-BOR-a-tri'' ala Inggris!).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000497', 'e5100001-0000-4000-8000-000000000062', NULL, 'reading', 'fill_blank', 'Pilih idiom eksekutif untuk membuka pembahasan atas masalah besar yang sedang membayangi rapat:', '{"options":["play devil''s advocate","incur technical debt","take a grain of salt","address the elephant in the room"],"translation":"Sebelum meninjau target Q4, CEO baru memilih langsung membahas isu besar yang mengganjal di ruangan—keterlambatan produk bulan lalu dan bagaimana tim teknik memperbaikinya.","sentence_template":"Before reviewing Q4 targets, the new CEO chose to [blank]—last month''s product delay and how engineering fixed it."}'::jsonb, '{"selected":"address the elephant in the room"}'::jsonb, NULL, NULL, '''Address the elephant in the room'' berarti berani mengangkat isu besar yang sensitif secara jujur dan konstruktif.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000498', 'e5100001-0000-4000-8000-000000000062', NULL, 'reading', 'fill_blank', 'Pilih penekanan kata kerja positif (emphatic do) yang tepat saat menjawab pertanyaan kritis investor:', '{"options":["had to been","was","does expanded","did"],"translation":"Meskipun tekanan kurs memangkas pendapatan utama, segmen SaaS inti kami benar-benar berhasil memperluas retensi bersih ke 118 persen.","sentence_template":"Although currency headwinds trimmed headline revenue, our core SaaS segment [blank] expand net retention to 118 percent."}'::jsonb, '{"selected":"did"}'::jsonb, NULL, NULL, 'Penegas lampau ''did + V1 (expand)'' menonjolkan capaian nyata di tengah berita kurang menguntungkan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000499', 'e5100001-0000-4000-8000-000000000062', NULL, 'listening', 'listening_choice', 'Dengarkan cara VP Komunikasi menangani pertanyaan tajam wartawan saat konferensi pers gangguan layanan. Teknik apa yang ia gunakan?', '{"options":[{"id":"opt_1","text":"Menuduh negara asing melakukan peretasan tanpa menunggu bukti penyelidikan"},{"id":"opt_2","text":"Mengakui bahwa seluruh nomor kartu kredit pelanggan telah bocor"},{"id":"opt_3","text":"Meninggalkan podium konferensi pers tanpa menjawab satu kata pun"},{"id":"opt_4","text":"Menolak berspekulasi atas hal yang masih diselidiki, lalu menjembatani ke fakta keamanan penting yang sudah pasti terverifikasi"}],"audio_text":"We won''t speculate on attacker attribution while federal investigators are onsite; what we can confirm right now is that zero payment card numbers were accessed."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Teknik *bridging* C-suite: tolak spekulasi prematur (''We won''t speculate on X'') → arahkan ke kepastian terukur (''what we can confirm right now is Y'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000500', 'e5100001-0000-4000-8000-000000000062', NULL, 'writing', 'sentence_builder', 'Susun kalimat pembagian wewenang jawab dalam sesi Q&A direksi:', '{"romaji":"/aɪ kæn spiːk tə ˈklɪnɪkəl ˈɛfɪkəsi ˈdeɪtə waɪl ˈaʊər ˈdʒɛnərəl ˈkaʊnsəl əˈdrɛsɪz ˈpætənt ˈtaɪmˌlaɪnz/","tokens":["addresses patent timelines.","I can speak to","while our general counsel","clinical efficacy data,","addressed patent","speaking into"],"target_translation":"Saya dapat menjelaskan data kemanjuran klinis, sementara penasihat hukum utama kami membahas linimasa paten."}'::jsonb, '["I can speak to","clinical efficacy data,","while our general counsel","addresses patent timelines."]'::jsonb, NULL, NULL, 'Idiom profesional AS ''speak to [topic]'' berarti memberikan penjelasan kompeten mengenai suatu ranah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000501', 'e5100001-0000-4000-8000-000000000062', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat manajemen krisis dengan penekanan vokal kuat pada ''DO'':', '{"romaji":"/waɪl fʊl ˌdaɪəɡˈnɑːstɪks kənˈtɪnjuː wi duː hæv ˈɛvri ˈbækʌp ˈhɑːspɪtəl noʊd ˈrʌnɪŋ/","display_text":"While full diagnostics continue, we do have every backup hospital node running.","phonetic_breakdown":["While full diagnostics","continue,","we do have","every backup hospital node running."]}'::jsonb, '{"expected_transcript":"While full diagnostics continue, we do have every backup hospital node running."}'::jsonb, NULL, NULL, 'Tekankan kata bantu ''DO'' (/duː/) dengan mantap untuk menenangkan kekhawatiran audiens.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000502', 'e5100001-0000-4000-8000-000000000062', NULL, 'reading', 'fill_blank', 'Pilih kolokasi manajemen krisis yang berarti ''membatasi meluasnya dampak negatif susulan'':', '{"options":["substantiate","contain","catalyze","extrapolate"],"translation":"Mengeluarkan penarikan produk secara transparan dalam enam jam membantu produsen otomotif tersebut membatasi dampak buruk reputasi.","sentence_template":"Issuing a transparent recall within six hours helped the automaker [blank] reputational fallout."}'::jsonb, '{"selected":"contain"}'::jsonb, NULL, NULL, '''Contain the fallout'' adalah kolokasi baku komunikasi krisis dan hubungan internasional.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000503', 'e5100001-0000-4000-8000-000000000062', NULL, 'listening', 'listening_choice', 'Dengarkan nasihat penasihat PR kepada pendiri perusahaan teknologi. Mengapa perusahaan harus memberi tahu pengguna hari ini juga?', '{"options":[{"id":"opt_1","text":"Menutup akun media sosial perusahaan selama satu bulan"},{"id":"opt_2","text":"Mengumumkan kendala dan pengembalian dana otomatis lebih dulu hari ini menjaga kepercayaan sebelum berita luar mendahului mereka"},{"id":"opt_3","text":"Menolak mengembalikan dana pelanggan yang tertagih ganda"},{"id":"opt_4","text":"Menyembunyikan kendala penagihan dan berharap wartawan tidak menyadarinya"}],"audio_text":"If tech journalists uncover the billing glitch before we email affected customers, we lose trust—we need to get ahead of the narrative with automatic refunds today."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Get ahead of the narrative'' berarti memegang kendali kejujuran informasi sejak awal.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000504', 'e5100001-0000-4000-8000-000000000062', NULL, 'writing', 'sentence_builder', 'Susun kalimat penekanan kontras Q&A eksekutif berikut:', '{"romaji":"/wʌt ˈaʊər ˈpaɪlət dʌz ˈdɛmənˌstreɪt ɪz strɔːŋ ˈwɪlɪŋnəs tə peɪ əˈmʌŋ mɪd ˈmɑːrkɪt ˈklɪnɪks/","tokens":["willingly pay","strong willingness to pay","among mid-market clinics.","does demonstrate is","What our pilot","do demonstrate"],"target_translation":"Hal yang benar-benar dibuktikan oleh uji coba kami adalah tingginya kesediaan membayar di kalangan klinik pasar menengah."}'::jsonb, '["What our pilot","does demonstrate is","strong willingness to pay","among mid-market clinics."]'::jsonb, NULL, NULL, 'Gabungan Wh-Cleft + emphatic ''does'': ''What our pilot does demonstrate is...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000505', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Pilih susunan objek ekstraposisi yang gramatikal sesudah ''makes'':', '{"options":["it feasibly","feasible to","it feasible to","that feasible to"],"translation":"Konektivitas internet satelit membuat penempatan kios telemedisin di kabupaten kepulauan terpencil menjadi layak dijalankan.","sentence_template":"Satellite internet connectivity makes [blank] deploy telemedicine kiosks in remote island regencies."}'::jsonb, '{"selected":"it feasible to"}'::jsonb, NULL, NULL, 'Rumus wajib ''make + it + adjective (feasible) + to V1 (deploy)'' — menghapus ''it'' adalah kesalahan gramatikal.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000506', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi dewan direksi menggunakan ''deemed it'':', '{"options":["prudent to","that prudent","it prudently","it prudent to"],"translation":"Mengingat fluktuasi tarif kargo, dewan perbendaharaan memandang bijaksana untuk melakukan lindung nilai atas enam puluh persen eksposur bahan bakar tahunan.","sentence_template":"Given volatile freight rates, the treasury board deemed [blank] hedge sixty percent of annual fuel exposure."}'::jsonb, '{"selected":"it prudent to"}'::jsonb, NULL, NULL, '''Deem + it + adjective (prudent) + to V1'' adalah konstruksi formal C1.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000507', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'listening', 'listening_choice', 'Dengarkan pidato penutup CEO pada rapat umum pemegang saham. Kewajiban moral apa yang ia tekankan?', '{"options":[{"id":"opt_1","text":"Perusahaan memiliki utang moral kepada pasien pedesaan untuk terus menjaga keterjangkauan harga layanan diagnostik esensial"},{"id":"opt_2","text":"Perusahaan akan menutup klinik pedesaan demi menaikkan harga perkotaan"},{"id":"opt_3","text":"Pasien pedesaan berutang biaya tambahan kepada jaringan klinik perusahaan"},{"id":"opt_4","text":"Layanan diagnostik hanya akan disediakan bagi pemegang saham"}],"audio_text":"After communities trusted our clinics during the pandemic, we owe it to rural patients to keep essential diagnostics affordable."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''We owe it to [someone] to [V1]'' membangkitkan komitmen etis yang kuat dalam pidato kepemimpinan.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000508', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'writing', 'sentence_builder', 'Susun kalimat peringatan bisnis dengan idiom ''take it for granted that'':', '{"romaji":"/ˈmɑːrkɪt ˈliːdərz mʌst ˈnɛvər teɪk ɪt fɔːr ˈɡræntɪd ðæt ˈswɪtʃɪŋ kɔːsts/","tokens":["never take it","switching costs will","taking granted","Market leaders must","take for granted that","lock customers in.","for granted that"],"target_translation":"Pemimpin pasar tidak boleh sekali-kali menganggap remeh bahwa biaya berpindah layanan akan mengunci pelanggan selamanya."}'::jsonb, '["Market leaders must","never take it","for granted that","switching costs will","lock customers in."]'::jsonb, NULL, NULL, 'Sebelum klausa ''that...'', idiom wajib menyertakan ''it'': ''take it for granted that...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000509', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'speaking', 'speaking_repeat', 'Ucapkan kalimat dengan objek ekstraposisi ''find it'' berikut secara alami:', '{"romaji":"/ˌmʌltiˈnæʃənəl tiːmz ˈɔːfən faɪnd ɪt ˈtʃælɪndʒɪŋ tə əˈlaɪn ʌnˈspoʊkən ˈkʌltʃərəl nɔːrmz/","display_text":"Multinational teams often find it challenging to align unspoken cultural norms.","phonetic_breakdown":["Multinational teams","often find it challenging","to align","unspoken cultural norms."]}'::jsonb, '{"expected_transcript":"Multinational teams often find it challenging to align unspoken cultural norms."}'::jsonb, NULL, NULL, 'Di AS, ''multinational'' lazim dilafalkan /ˌmʌltiˈnæʃənəl/ atau /ˌmʌltaɪˈnæʃənəl/, dan sambungkan ''find_it''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000510', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Pilih struktur yang benar sesudah verba ''consider'' ketika diikuti adjektiva dan infinitif:', '{"options":["it essentially","it essential to","to be essential that","essential to"],"translation":"Para pakar hukum tata negara memandang sangat penting untuk menjaga kemandirian peradilan dari tekanan elektoral jangka pendek.","sentence_template":"Constitutional scholars consider [blank] safeguard judicial independence from short-term electoral pressures."}'::jsonb, '{"selected":"it essential to"}'::jsonb, NULL, NULL, '''Consider + it + adjective + to V1'' menjaga keseimbangan sintaksis objek kompleks.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000511', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'listening', 'listening_choice', 'Dengarkan kuliah sejarah sains TOEFL tentang penemuan kristalografi sinar-X. Bagaimana terobosan tersebut mengubah kimia?', '{"options":[{"id":"opt_1","text":"Hukum Bragg memungkinkan pemetaan kisi atom secara langsung hingga ketelitian angstrom yang sebelumnya hanya bisa ditebak tak langsung"},{"id":"opt_2","text":"Kimiawan sudah mampu memotret kisi atom sebelum sinar-X ditemukan"},{"id":"opt_3","text":"Difraksi sinar-X membuat pengukuran geometri molekul makin kabur"},{"id":"opt_4","text":"Hukum Bragg hanya berlaku pada cairan bersuhu tinggi"}],"audio_text":"Before X-ray diffraction, chemists inferred molecular geometry indirectly; Bragg''s law suddenly made it possible to map atomic lattices with angstrom precision."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Perhatikan klausa kunci: ''made it possible to map atomic lattices...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000512', 'e5100001-0000-4000-8000-000000000063', 'e2000001-0000-4000-8000-000000000046', 'writing', 'sentence_builder', 'Susun kalimat komunikasi eksekutif dengan ''made it clear that'':', '{"romaji":"/ˈdʊrɪŋ taʊn hɔːl ðə ˌsiːtiːˈoʊ meɪd ɪt klɪr ðæt rɪˌlaɪəˈbɪləti teɪks ˈprɛsədəns/","tokens":["it clear that","made clear that","taking precedences","over flashy features.","During town hall,","the CTO made","reliability takes precedence"],"target_translation":"Dalam pertemuan seluruh staf, CTO menegaskan dengan sangat jelas bahwa keandalan sistem lebih diutamakan daripada fitur kosmetik yang mencolok."}'::jsonb, '["During town hall,","the CTO made","it clear that","reliability takes precedence","over flashy features."]'::jsonb, NULL, NULL, '''Make it clear that + Clause'' + kolokasi C1 ''take precedence over'' (lebih diutamakan daripada).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000513', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Pilih kata kerja akademik C1 yang berarti ''layak mendapatkan / menuntut penelitian lebih lanjut'':', '{"options":["avert","incur","waive","warrant"],"translation":"Lonjakan konduktivitas anomali di bawah sepuluh kelvin layak diteliti lebih lanjut menggunakan sensor beresolusi lebih tinggi.","sentence_template":"Anomalous conductivity spikes below ten kelvins [blank] further investigation with higher-resolution sensors."}'::jsonb, '{"selected":"warrant"}'::jsonb, NULL, NULL, '''Warrant further investigation / scrutiny'' adalah kolokasi penutup jurnal ilmiah berstandar tinggi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000514', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Perhatikan ejaan dan pilih kata benda yang berarti ''prioritas utama di atas hal lain'':', '{"options":["presidency","precedence","precedent","pretense"],"translation":"Dalam protokol triase rumah sakit, menstabilkan sumbatan jalan napas selalu didahulukan di atas pencatatan administrasi.","sentence_template":"In hospital triage protocols, stabilizing airway obstruction always takes [blank] over administrative intake."}'::jsonb, '{"selected":"precedence"}'::jsonb, NULL, NULL, '''Take precedence over'' (berakhiran -ence) berarti lebih diprioritaskan; ''set a precedent'' (-ent) berarti menciptakan preseden awal.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000515', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'listening', 'listening_choice', 'Dengarkan pemakalah konferensi menjawab pertanyaan kritis dari audiens. Bagaimana ia menanggapi pertanyaan soal efek jangka panjang 20 tahun?', '{"options":[{"id":"opt_1","text":"Membatalkan publikasi penelitiannya karena belum berjalan dua puluh tahun"},{"id":"opt_2","text":"Mengklaim data dua tahunnya sudah membuktikan efek dua puluh tahun secara mutlak"},{"id":"opt_3","text":"Mengakui secara jujur bahwa efek 20 tahun berada di luar cakupan studi dua tahun ini, sembari menjelaskan kesiapan registri untuk pemantauan lanjutan"},{"id":"opt_4","text":"Menyalahkan penanya karena tidak membaca makalah dengan teliti"}],"audio_text":"That speaks directly to a key limitation of our two-year cohort—tracking twenty-year cardiovascular outcomes lies beyond the scope of this dataset, though our registry is designed for future follow-up."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Respons konferensi sempurna: apresiasi ketepatan pertanyaan + batasi cakupan dengan tegas + tunjukkan desain tindak lanjut.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000516', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'writing', 'sentence_builder', 'Susun kalimat pembatasan ruang lingkup tesis berikut:', '{"romaji":"/ˌmækroʊˌiːkəˈnɑːmɪk ɪksˈtʃeɪndʒ reɪt ˈmɑːdəlɪŋ laɪz bɪˈjɑːnd ðə skoʊp ʌv ðɪs/","tokens":["scopes from","lying beyond","scope of this","firm-level productivity study.","Macroeconomic exchange-rate modeling","lies beyond the"],"target_translation":"Pemodelan nilai tukar ekonomi makro berada di luar cakupan studi produktivitas tingkat perusahaan ini."}'::jsonb, '["Macroeconomic exchange-rate modeling","lies beyond the","scope of this","firm-level productivity study."]'::jsonb, NULL, NULL, 'Ejaan Amerika memakai satu ''l'' pada ''modeling'' diikuti verba tunggal ''lies beyond the scope of...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000517', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pertahanan sidang akademik berikut dengan tenang dan meyakinkan:', '{"romaji":"/ðiːz prɪˈlɪməˌnɛri əˈnɑːməliz ˈwɔːrənt ˈfɜːrðər ɪnˌvɛstəˈɡeɪʃən ɪn ə ˈlɑːrdʒər ˈkoʊhɔːrt/","display_text":"These preliminary anomalies warrant further investigation in a larger cohort.","phonetic_breakdown":["These preliminary anomalies","warrant further investigation","in a larger cohort."]}'::jsonb, '{"expected_transcript":"These preliminary anomalies warrant further investigation in a larger cohort."}'::jsonb, NULL, NULL, 'Pastikan bunyi /wɔːrənt/ terdengar mantap dan ''cohort'' dilafalkan /ˈkoʊhɔːrt/.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000518', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Pilih kata benda yang tepat untuk ''contoh putusan terdahulu yang menjadi rujukan'':', '{"options":["premise","precedence","precedent","prevalence"],"translation":"Menyetujui tunjangan kerja jarak jauh berlaku surut tanpa kriteria jelas dapat menciptakan preseden anggaran yang tak berkelanjutan.","sentence_template":"Approving retroactive remote-work stipends without clear criteria could set an unsustainable budget [blank]."}'::jsonb, '{"selected":"precedent"}'::jsonb, NULL, NULL, 'Kontras kolokasi: ''set a precedent'' (menciptakan contoh yurisprudensi/kebiasaan awal) vs. ''take precedence over'' (lebih diutamakan).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000519', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'listening', 'listening_choice', 'Dengarkan percakapan mahasiswa pascasarjana dengan profesor sebelum presentasi konferensi pertamanya. Apa saran profesor?', '{"options":[{"id":"opt_1","text":"Mengalihkan pembicaraan ke topik lain tanpa menjawab pertanyaan"},{"id":"opt_2","text":"Jangan pernah mengarang jawaban pura-pura tahu; akui celah tersebut dengan jujur lalu jelaskan bagaimana cara mengujinya di tahap berikutnya"},{"id":"opt_3","text":"Mengarang angka statistik perkiraan agar terlihat menguasai semua hal"},{"id":"opt_4","text":"Membaca ulang slide pertama dari awal hingga waktu habis"}],"audio_text":"If a senior scholar asks something you haven''t tested yet, never bluff—acknowledge the gap openly and frame how you''d test it next."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Budaya akademik AS sangat menghargai kejujuran intelektual (*intellectual candor*) di atas gertakan (*bluffing*).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000520', 'e5100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000046', 'writing', 'sentence_builder', 'Susun kalimat prioritas etika riset berikut:', '{"romaji":"/ɪnˈfɔːrmd pɑːrˈtɪsəpənt kənˈsɛnt mʌst ˈɔːlweɪz teɪk ˈprɛsədəns ˈoʊvər ˈræpɪd ˈdeɪtə kəˈlɛkʃən/","tokens":["precedence over rapid","Informed participant consent","must always take","consenting participant","data collection schedules.","take precedent"],"target_translation":"Persetujuan partisipan yang terinformasi harus selalu didahulukan di atas jadwal pengumpulan data yang cepat."}'::jsonb, '["Informed participant consent","must always take","precedence over rapid","data collection schedules."]'::jsonb, NULL, NULL, '''Take precedence over + Noun Phrase'' menegaskan hierarki etika secara tak terbantahkan.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000521', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Pilih struktur Preparatory ''It'' yang gramatikal:', '{"options":["that possible","it possibly","possible to","it possible to"],"translation":"Dasbor telemetri waktu nyata memungkinkan pendeteksian penurunan tegangan regional sebelum transformator mengalami panas berlebih.","sentence_template":"Real-time telemetry dashboards make [blank] spot regional voltage drops before transformers overheat."}'::jsonb, '{"selected":"it possible to"}'::jsonb, NULL, NULL, 'Wajib menyertakan objek penyangga ''it'' di antara ''make'' dan ''possible to V1''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000522', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Bedakan ''precedence'' dan ''precedent'' dalam konteks hukum:', '{"options":["precedent","precedence","prerogative","pretext"],"translation":"Putusan pengadilan banding bulan lalu menciptakan preseden hukum yang mengikat bagi surat perintah data cloud lintas batas.","sentence_template":"Last month''s appellate ruling set a binding legal [blank] for cross-border cloud data warrants."}'::jsonb, '{"selected":"precedent"}'::jsonb, NULL, NULL, 'Kolokasi hukum baku: ''set a binding legal precedent''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000523', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'listening', 'listening_choice', 'Evaluasi Unit 6 — Dengarkan respons CFO pada panggilan kinerja kuartalan. Bagaimana ia menggunakan penekanan ''did'' dan teknik bridging?', '{"options":[{"id":"opt_1","text":"CFO menolak mempublikasikan angka pertumbuhan pendapatan tahunan"},{"id":"opt_2","text":"Penjualan perangkat keras di Eropa mencetak rekor tertinggi sepanjang sejarah"},{"id":"opt_3","text":"Mengakui lesunya perangkat keras di Eropa, lalu menekankan pertumbuhan kuat 34% pada pendapatan berulang keamanan cloud"},{"id":"opt_4","text":"Pendapatan keamanan cloud turun tiga puluh empat persen sepanjang tahun"}],"audio_text":"While enterprise hardware cycles remained sluggish in Europe, our recurring cloud security revenue did grow thirty-four percent year over year."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Konsesi jujur diikuti penekanan positif ''did grow 34%'' menjaga kredibilitas di hadapan analis pasar modal.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000524', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'writing', 'sentence_builder', 'Evaluasi Unit 6 — Susun kalimat kewajiban etis pemimpin (''owe it to''):', '{"romaji":"/wi oʊ ɪt tə ˈfrʌntˌlaɪn ˌɛndʒəˈnɪrz tə ɪˈlɪməˌneɪt prɪˈvɛntəbəl ˈmɪdˌnaɪt əˈlɜːrt fəˈtiːɡ/","tokens":["to frontline engineers","owing to","to eliminate preventable","owe frontline","We owe it","midnight alert fatigue."],"target_translation":"Kita memiliki kewajiban moral kepada para insinyur garda depan untuk menghapus kelelahan peringatan tengah malam yang sebenarnya dapat dicegah."}'::jsonb, '["We owe it","to frontline engineers","to eliminate preventable","midnight alert fatigue."]'::jsonb, NULL, NULL, '''Owe it to [someone] to [V1]'' menuntut keberadaan ''it'' sebelum ''to frontline engineers''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000525', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'speaking', 'speaking_repeat', 'Evaluasi Unit 6 — Ucapkan kalimat pembuka rapat krisis berikut dengan mantap:', '{"romaji":"/lɛts ɡɛt əˈhɛd ʌv ðə ˈnærətɪv baɪ ˈpʌblɪʃɪŋ ə trænsˈpærənt ˈɪnsədənt ˈtaɪmˌlaɪn/","display_text":"Let''s get ahead of the narrative by publishing a transparent incident timeline.","phonetic_breakdown":["Let''s get ahead","of the narrative","by publishing","a transparent incident timeline."]}'::jsonb, '{"expected_transcript":"Let''s get ahead of the narrative by publishing a transparent incident timeline."}'::jsonb, NULL, NULL, 'Lafalkan ''narrative'' /ˈnærətɪv/ dan ''transparent'' /trænsˈpærənt/ secara jernih.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000526', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Pilih kata kerja akademik untuk menutup pembahasan anomali riset:', '{"options":["appease","warrant","digress","waive"],"translation":"Emisi metana tak terduga dari kulit pohon dataran tinggi layak diteliti lebih lanjut di berbagai bioma tropis.","sentence_template":"Unexpected methane emissions from upland tree bark [blank] further investigation across tropical biomes."}'::jsonb, '{"selected":"warrant"}'::jsonb, NULL, NULL, '''Warrant further investigation'' menghubungkan temuan awal ke agenda riset berikutnya.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000527', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'listening', 'listening_choice', 'Evaluasi Unit 6 — Dengarkan CTO menjawab pertanyaan dewan direksi tentang migrasi AI. Apa batasan yang ia tetapkan?', '{"options":[{"id":"opt_1","text":"Peluncuran ditahan sampai pagar pengaman lulus uji keamanan karena akurasi lebih diutamakan daripada sensasi peluncuran"},{"id":"opt_2","text":"Proyek kecerdasan buatan dihentikan permanen oleh dewan direksi"},{"id":"opt_3","text":"Sensasi pemasaran lebih diprioritaskan di atas ketepatan jawaban sistem"},{"id":"opt_4","text":"Chatbot akan langsung dirilis besok pagi tanpa pengujian keamanan"}],"audio_text":"Deploying customer-facing chatbots before hallucination guardrails pass red-teaming is out of the question—accuracy takes precedence over launch hype."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Out of the question'' (tidak mungkin diizinkan) diperkuat prinsip ''accuracy takes precedence over launch hype''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000528', 'e5100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000046', 'writing', 'sentence_builder', 'Evaluasi Unit 6 — Susun kalimat penilaian komite audit dengan ''deemed it'':', '{"romaji":"/ɪkˈstɜːrnəl ˈɔːdɪtərz diːmd ɪt ɪmˈpɛrətɪv ðæt rɪˈleɪtɪd ˈpɑːrti loʊnz bi dɪsˈkloʊzd/","tokens":["it imperative that","deemed imperative","related-party loans be","disclosed in footnotes.","are disclosed","External auditors deemed"],"target_translation":"Auditor eksternal memandang sangat mutlak agar pinjaman pihak berelasi diungkapkan di dalam catatan kaki."}'::jsonb, '["External auditors deemed","it imperative that","related-party loans be","disclosed in footnotes."]'::jsonb, NULL, NULL, 'Mengintegrasikan Unit 6 (''deemed it imperative that...'') dengan Mandative Subjunctive Unit 2 (''...be disclosed'')!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000529', 'e5100001-0000-4000-8000-000000000066', NULL, 'reading', 'fill_blank', 'Pilih kata benda hasil nominalisasi beserta preposisi yang tepat untuk menggantikan ''because patients strictly followed'':', '{"options":["adherent of","adherence from","adhering with","adherence to"],"translation":"Kepatuhan konsisten terhadap rejimen antiretroviral mengubah HIV dari diagnosis mematikan menjadi kondisi yang dapat dikelola.","sentence_template":"Consistent [blank] antiretroviral regimens transformed HIV from a fatal diagnosis into a manageable condition."}'::jsonb, '{"selected":"adherence to"}'::jsonb, NULL, NULL, 'Nomina ''adherence'' mempertahankan preposisi ''to'' dari kata kerja ''adhere to''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000530', 'e5100001-0000-4000-8000-000000000066', NULL, 'reading', 'fill_blank', 'Pilih nomina C1 yang mendeskripsikan ''menjamurnya jumlah perangkat secara cepat'':', '{"options":["precedence to","hesitation in","proliferation of","attrition from"],"translation":"Menjamurnya kamera IoT murah tanpa pengawasan telah memperluas permukaan serangan bagi botnet pelumpuh layanan.","sentence_template":"The unchecked [blank] low-cost IoT cameras has expanded the attack surface for distributed denial-of-service botnets."}'::jsonb, '{"selected":"proliferation of"}'::jsonb, NULL, NULL, '''The proliferation of + Plural Noun'' merangkum ledakan jumlah secara ringkas dan akademis.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000531', 'e5100001-0000-4000-8000-000000000066', NULL, 'listening', 'listening_choice', 'Dengarkan instruktur penulisan tesis membandingkan dua versi kalimat mahasiswa. Mengapa versi kedua dinilai berkelas C1?', '{"options":[{"id":"opt_1","text":"Versi pertama lebih disukai oleh editor jurnal biologi internasional"},{"id":"opt_2","text":"Versi kedua memadatkan tiga klausa lisan terpotong menjadi satu rantai sebab-akibat berbasis nomina ilmiah yang kohesif"},{"id":"opt_3","text":"Versi kedua menghapus informasi tentang pupuk dan kematian ikan"},{"id":"opt_4","text":"Kalimat jurnal dilarang menyebutkan hubungan sebab-akibat"}],"audio_text":"Compare ''When farmers used too much fertilizer, algae grew fast and fish died'' with ''Excessive fertilizer runoff triggered algal blooms, causing widespread fish mortality''—three choppy clauses become one cohesive causal chain!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Transformasi ''used too much fertilizer'' → ''Excessive fertilizer runoff'' dan ''fish died'' → ''widespread fish mortality'' adalah esensi kepadatan informasi akademik.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000532', 'e5100001-0000-4000-8000-000000000066', NULL, 'writing', 'sentence_builder', 'Susun kalimat akademik padat dengan nominalisasi ''disparities'':', '{"romaji":"/stɑːrk ˈriːdʒənəl dɪˈspærətiz ɪn ˈbrɔːdˌbænd ˈleɪtənsi ɪɡˈzæsərˌbeɪtɪd ˈlɜːrnɪŋ ˈlɔːsɪz/","tokens":["disparate regionally","exacerbating into","Stark regional disparities","in broadband latency","exacerbated learning losses","during remote schooling."],"target_translation":"Ketimpangan antardaerah yang mencolok pada latensi pita lebar memperparah ketertinggalan belajar selama sekolah jarak jauh."}'::jsonb, '["Stark regional disparities","in broadband latency","exacerbated learning losses","during remote schooling."]'::jsonb, NULL, NULL, 'Frasa nomina kompleks ''Stark regional disparities in broadband latency'' menjadi subjek bagi verba kausal ''exacerbated'' (memperparah).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000533', 'e5100001-0000-4000-8000-000000000066', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat akademik padat berikut dengan penekanan jelas pada kata kerja kausal ''accelerated'':', '{"romaji":"/prəˈlɔːŋd ˈækwəfər dɪˈpliːʃən ækˈsɛləˌreɪtɪd ˈkoʊstəl lænd səbˈsaɪdəns əˈkrɔːs ˈnɔːrðərn ˈdʒɑːvə/","display_text":"Prolonged aquifer depletion accelerated coastal land subsidence across northern Java.","phonetic_breakdown":["Prolonged aquifer depletion","accelerated","coastal land subsidence","across northern Java."]}'::jsonb, '{"expected_transcript":"Prolonged aquifer depletion accelerated coastal land subsidence across northern Java."}'::jsonb, NULL, NULL, 'Lafalkan ''subsidence'' /səbˈsaɪdəns/ atau /ˈsʌbsɪdəns/ dengan jelas pada empat frasa terukur.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000534', 'e5100001-0000-4000-8000-000000000066', NULL, 'reading', 'fill_blank', 'Pilih kata kerja kausal C1 yang berarti ''memperparah / memperburuk kondisi yang memang sudah sulit'':', '{"options":["exacerbated","reconciled","corroborated","alleviated"],"translation":"Kondisi kekeringan El Niño memperparah gejolak harga gandum di negara-negara yang bergantung pada impor.","sentence_template":"El Niño drought conditions [blank] grain price volatility across import-dependent economies."}'::jsonb, '{"selected":"exacerbated"}'::jsonb, NULL, NULL, '''Exacerbate'' (= memperburuk masalah) adalah pasangan lawan kata penting dari ''alleviate / mitigate'' (= meredakan).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000535', 'e5100001-0000-4000-8000-000000000066', NULL, 'listening', 'listening_choice', 'Dengarkan laporan SDM kuartalan perusahaan teknologi. Apa arti ''voluntary attrition dropped to six percent''?', '{"options":[{"id":"opt_1","text":"Persentase karyawan yang mengundurkan diri secara sukarela turun drastis dari 19% menjadi hanya 6%"},{"id":"opt_2","text":"Perusahaan memberhentikan sembilan belas persen insinyur bulan ini"},{"id":"opt_3","text":"Hanya enam persen karyawan yang bersedia mengikuti jenjang karier baru"},{"id":"opt_4","text":"Produktivitas tim teknik turun sebesar enam persen akibat kerja jarak jauh"}],"audio_text":"After we introduced flexible remote weeks and clearer engineering ladders, voluntary attrition dropped from nineteen percent to just six percent."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Voluntary attrition'' dalam manajemen SDM berarti tingkat pengunduran diri sukarela karyawan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000536', 'e5100001-0000-4000-8000-000000000066', NULL, 'writing', 'sentence_builder', 'Susun kalimat nominalisasi tentang peralihan energi berikut:', '{"romaji":"/ði əˈbrʌpt wɪðˈdrɔːəl ʌv fiːd ɪn ˈtærɪfs stɔːld ˌrɛzəˈdɛnʃəl ˈsoʊlər ˌɪnstəˈleɪʃənz/","tokens":["installations for two years.","stalling into","stalled residential solar","The abrupt withdrawal","withdrawing abruptly","of feed-in tariffs"],"target_translation":"Pencabutan mendadak tarif pembelian listrik surya menghentikan laju pemasangan panel surya rumah tangga selama dua tahun."}'::jsonb, '["The abrupt withdrawal","of feed-in tariffs","stalled residential solar","installations for two years."]'::jsonb, NULL, NULL, '''They abruptly withdrew tariffs'' dipadatkan menjadi subjek ''The abrupt withdrawal of feed-in tariffs''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000537', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Pilih frasa ''This/These + Summary Noun'' yang paling akurat merangkum dua kendala pada kalimat pertama:', '{"options":["Such abundance","This single triumph","These twin bottlenecks","That consensus"],"translation":"Derek pelabuhan menua dengan cepat sementara operator terampil pensiun berbondong-bondong. Kedua kemacetan kembar ini memangkas arus kontainer sebesar dua puluh persen.","sentence_template":"Port cranes aged rapidly while skilled operators retired in droves. [blank] cut container throughput by twenty percent."}'::jsonb, '{"selected":"These twin bottlenecks"}'::jsonb, NULL, NULL, '''These twin bottlenecks'' merangkum dua hambatan serentak pada kalimat sebelumnya secara presisi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000538', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Ganti kata ''This'' telanjang dengan Summary Noun yang tepat untuk fenomena prediksi model vs. pengukuran nyata:', '{"options":["Those adherents","This discrepancy","This unanimity","Such compliance"],"translation":"Model iklim memproyeksikan pengeringan ringan, namun inti sedimen menyingkap fase gersang seabad penuh. Ketidaksesuaian ini mendorong peneliti merevisi parameter interaksi laut.","sentence_template":"Climate models projected mild drying, yet sediment cores revealed a century-long arid phase. [blank] led researchers to revise ocean-coupling parameters."}'::jsonb, '{"selected":"This discrepancy"}'::jsonb, NULL, NULL, 'Selisih tajam antara proyeksi model dan bukti fisik dirangkum sempurna oleh ''This discrepancy''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000539', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'listening', 'listening_choice', 'Dengarkan penjelasan strategi ''Insert a Sentence'' TOEFL Reading. Mengapa kotak nomor [3] adalah tempat yang tepat?', '{"options":[{"id":"opt_1","text":"Kalimat kotak harus selalu diletakkan di awal paragraf pertama"},{"id":"opt_2","text":"Kata ''Such'' menandakan dimulainya topik baru yang tak berhubungan"},{"id":"opt_3","text":"Kalimat kedua sama sekali tidak membahas metabolisme kepiting"},{"id":"opt_4","text":"Frasa rujukan ''Such metabolic flexibility'' mengunci posisi kalimat tepat sesudah penjelasan cara kepiting berpindah jalur metabolisme"}],"audio_text":"Look at the boxed sentence: ''Such metabolic flexibility allows the crab to survive oxygen-free mudflats.'' That phrase ''Such metabolic flexibility'' must follow sentence two, which explains how the crab switches from aerobic to lactic pathways!"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Menguasai *anaphoric summary nouns* memberi manfaat ganda: tulisan esai 5.0 dan akurasi 100% di soal Insert Text TOEFL!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000540', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'writing', 'sentence_builder', 'Susun kalimat kedua berkohesi ''Such fragmentation'' berikut:', '{"romaji":"/ˈtwɛnti ˈprɑːvɪnsɪz bɪlt ˈsɛprət tæks ˈpɔːrtəlz sʌtʃ ˌfræɡmənˈteɪʃən ɪmˈpoʊzd stiːp kəmˈplaɪəns kɔːsts/","tokens":["on small exporters.","fragmenting such","separate tax portals;","steep compliance costs","imposing steep","such fragmentation imposed","Twenty provinces built"],"target_translation":"Dua puluh provinsi membangun portal pajak terpisah; terpecah-pecahnya sistem semacam itu membebankan biaya kepatuhan tinggi pada eksportir kecil."}'::jsonb, '["Twenty provinces built","separate tax portals;","such fragmentation imposed","steep compliance costs","on small exporters."]'::jsonb, NULL, NULL, 'Lafalkan kata sifat ''separate'' sebagai dua suku kata /ˈsɛprət/ (sedangkan verba ''to separate'' /ˈsɛpəˌreɪt/).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000541', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'speaking', 'speaking_repeat', 'Ucapkan dua kalimat berkohesi Given-to-New berikut dengan alur mantap:', '{"romaji":"/ˌæntibaɪˈɑːtɪks wɜːr prɪˈskraɪbd fɔːr ˈvaɪrəl koʊldz ðɪs ˌmɪsˈjuːs ækˈsɛləˌreɪtɪd bækˈtɪriəl rɪˈzɪstəns/","display_text":"Antibiotics were prescribed for viral colds. This misuse accelerated bacterial resistance.","phonetic_breakdown":["Antibiotics were prescribed","for viral colds.","This misuse accelerated","bacterial resistance."]}'::jsonb, '{"expected_transcript":"Antibiotics were prescribed for viral colds. This misuse accelerated bacterial resistance."}'::jsonb, NULL, NULL, 'Perhatikan kata benda ''misuse'' berbunyi /s/ di akhir (/ˌmɪsˈjuːs/), berbeda dari kata kerja /ˌmɪsˈjuːz/!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000542', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Pilih Summary Noun yang merangkum perpindahan anggaran dari rumah sakit kuratif ke klinik imunisasi desa:', '{"options":["These twin defeats","Such stagnation","This shift in preventive focus","This total abandonment"],"translation":"Kementerian kesehatan mengalihkan empat puluh persen anggaran rumah sakit menuju klinik imunisasi desa. Pergeseran fokus pencegahan ini memangkas separuh rawat inap bayi yang dapat dicegah.","sentence_template":"Health ministries redirected forty percent of hospital budgets toward rural immunization clinics. [blank] halved preventable infant hospitalizations."}'::jsonb, '{"selected":"This shift in preventive focus"}'::jsonb, NULL, NULL, '''This shift in preventive focus'' menangkap esensi realokasi kebijakan kalimat sebelumnya.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000543', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'listening', 'listening_choice', 'Dengarkan editor jurnal mengoreksi paragraf abstrak penulis. Mengapa kalimat ketiga diminta direvisi?', '{"options":[{"id":"opt_1","text":"Penulis diminta menghapus data penghematan memori dari abstrak"},{"id":"opt_2","text":"Abstrak jurnal dilarang menggunakan kata ''hypothesis''"},{"id":"opt_3","text":"Kata ''This'' tanpa nomina pendamping membuat pembaca bingung aspek mana dari kalimat sebelumnya yang dimaksud"},{"id":"opt_4","text":"Kalimat ketiga terlalu pendek karena kurang dari lima puluh kata"}],"audio_text":"Your third sentence starts with a bare ''This proves our hypothesis''—specify whether ''This'' refers to the lower latency, the memory savings, or the combined benchmark!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Menghindari *unattended demonstrative ''this''* adalah tanda pembeda penulis akademik terlatih.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000544', 'e5100001-0000-4000-8000-000000000067', 'e2000001-0000-4000-8000-000000000047', 'writing', 'sentence_builder', 'Susun kalimat kohesif dengan ''This convergence of'':', '{"romaji":"/ˈtʃiːpər ˈsɛnsərz mɛt ˈoʊpən sɔːrs ɛdʒ ˈmɑːdəlz ðɪs kənˈvɜːrdʒəns dɪˈmɑːkrəˌtaɪzd prɪˈsɪʒən ˈæɡrɪˌkʌltʃər/","tokens":["for smallholders.","converging this","this convergence democratized","open-source edge models;","precision agriculture","Cheaper sensors met","democratize precision"],"target_translation":"Sensor yang kian murah bertemu model tepi sumber terbuka; perpaduan ini mendemokratisasi pertanian presisi bagi petani kecil."}'::jsonb, '["Cheaper sensors met","open-source edge models;","this convergence democratized","precision agriculture","for smallholders."]'::jsonb, NULL, NULL, '''This convergence'' merangkum bertemunya dua tren teknologi pada klausa pertama.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000545', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Pilih phrasal verb idiomatis untuk merangkum esensi paling mendasar dari argumen rumit:', '{"options":["waives off","incurs upon","digresses into","boils down to"],"translation":"Di balik empat puluh halaman persamaan ekonometrika, pesan laporan tersebut pada intinya bermuara pada satu kaidah: tarif yang terprediksi menarik investasi pabrik.","sentence_template":"Beneath forty pages of econometric equations, the report''s message [blank] one rule: predictable tariffs attract factories."}'::jsonb, '{"selected":"boils down to"}'::jsonb, NULL, NULL, '''Boil down to + Noun Phrase'' menyarikan kesimpulan paling hakiki dari pembahasan kompleks.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000546', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Pilih penanda parafrasa lisan untuk menerjemahkan istilah medis berat ke bahasa awam:', '{"options":["lest","put simply","albeit of","inasmuch"],"translation":"Dokter menyebut kondisi ini ''hipotensi ortostatik''—dengan bahasa sederhana, tekanan darah Anda turun sesaat ketika berdiri terlalu cepat.","sentence_template":"Clinicians call this ''orthostatic hypotension''—[blank], your blood pressure dips briefly when you stand up too fast."}'::jsonb, '{"selected":"put simply"}'::jsonb, NULL, NULL, '''Put simply,'' (atau ''In plain terms,'') menjembatani definisi teknis dengan penjelasan verba sehari-hari.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000547', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'listening', 'listening_choice', 'Dengarkan bagaimana peserta TOEFL skor 30/30 memparafrasakan bacaan tentang ''olfactory imprinting'' pada ikan salmon. Mengapa parafrasa ini sangat efektif?', '{"options":[{"id":"opt_1","text":"Mengubah frasa nomina abstrak ''olfactory imprinting'' menjadi klausa verba aktif (''young salmon memorize the unique chemical scent...'') yang jernih"},{"id":"opt_2","text":"Mengganti topik ikan salmon dengan navigasi burung merpati"},{"id":"opt_3","text":"Membaca ulang kalimat kamus secara kaku dengan jeda terbata-bata"},{"id":"opt_4","text":"Mengeja huruf demi huruf kata ''olfactory'' tanpa menjelaskan artinya"}],"audio_text":"The reading introduces olfactory imprinting—which basically means young salmon memorize the unique chemical scent of their home stream before swimming out to sea."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'De-nominalisasi lisan membuktikan pemahaman konsep mendalam kepada penguji TOEFL Speaking.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000548', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'writing', 'sentence_builder', 'Susun kalimat komunikasi eksekutif untuk menguraikan dampak praktis bagi dewan:', '{"romaji":"/lɛt mi spɛl aʊt ðə ˈbʌdʒɪt ˌɪmpləˈkeɪʃənz ʌv dɪˈleɪɪŋ ˈaʊər ˈdeɪtə ˈsɛntər maɪˈɡreɪʃən/","tokens":["spelling implications","of delaying our","the budget implications","data-center migration.","Let me spell out","implicated budget"],"target_translation":"Izinkan saya menguraikan secara gamblang implikasi anggaran dari penundaan migrasi pusat data kita."}'::jsonb, '["Let me spell out","the budget implications","of delaying our","data-center migration."]'::jsonb, NULL, NULL, '''Spell out the implications of + V-ing'' mengarahkan fokus rapat pada konsekuensi nyata.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000549', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penyederhanaan konsep teknis berikut dengan ramah dan komunikatif:', '{"romaji":"/pʊt ˈsɪmpli ˈzɪroʊ ˈnɑːlɪdʒ pruːfs ˈvɛrəˌfaɪ jʊr eɪdʒ wɪˈðaʊt ɪkˈspoʊzɪŋ jʊr ˈbɜːrθˌdeɪt/","display_text":"Put simply, zero-knowledge proofs verify your age without exposing your birthdate.","phonetic_breakdown":["Put simply,","zero-knowledge proofs","verify your age","without exposing your birthdate."]}'::jsonb, '{"expected_transcript":"Put simply, zero-knowledge proofs verify your age without exposing your birthdate."}'::jsonb, NULL, NULL, 'Beri jeda bersahabat sesudah ''Put simply,'' lalu tekankan kontras ''VERIFY your age WITHOUT exposing...''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000550', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Pilih kata kerja yang melengkapi idiom ''menanggalkan istilah teknis yang rumit'':', '{"options":["strip","warrant","adhere","proliferate"],"translation":"Jika Anda menanggalkan jargon rekayasa keuangannya, obligasi beragunan pada dasarnya adalah kumpulan pinjaman yang diiris berdasarkan tingkat risiko.","sentence_template":"If you [blank] away the financial engineering jargon, collateralized obligations are pooled loans sliced by risk tier."}'::jsonb, '{"selected":"strip"}'::jsonb, NULL, NULL, '''Strip away the jargon'' membuka penjelasan konsep rumit secara lugas.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000551', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'listening', 'listening_choice', 'Dengarkan saran pelatih komunikasi kepada ilmuwan data sebelum presentasi di hadapan gubernur. Apa yang harus diubah pada slide pertama?', '{"options":[{"id":"opt_1","text":"Membatalkan pemaparan karena gubernur bukan ahli statistik"},{"id":"opt_2","text":"Menghapus peta kecamatan rawan banjir dari materi paparan"},{"id":"opt_3","text":"Menambahkan tiga halaman pembuktian teorema varians di slide pembuka"},{"id":"opt_4","text":"Fokus menguraikan manfaat praktis evakuasi warga bantaran sungai 12 jam lebih awal alih-alih membuka dengan jargon statistik"}],"audio_text":"Don''t open with ''heteroskedastic residual variance''—spell out what the flood model means for evacuating riverside subdistricts twelve hours earlier!"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Menyesuaikan laras bahasa (*audience adaptation*) adalah puncak kecakapan komunikasi C1.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000552', 'e5100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000047', 'writing', 'sentence_builder', 'Susun kalimat rangkuman esensi negosiasi berikut:', '{"romaji":"/wʌt ðə ˈfɪfti peɪdʒ ˈrɛɡjələˌtɔːri dræft bɔɪlz daʊn tuː ɪz ˈmændəˌtɔːri ˌælɡəˈrɪðmɪk trænsˈpærənsi/","tokens":["down to is","boil down","algorithmically transparent","What the fifty-page","regulatory draft boils","mandatory algorithmic transparency."],"target_translation":"Inti sari dari draf regulasi setebal lima puluh halaman tersebut bermuara pada kewajiban transparansi algoritmik."}'::jsonb, '["What the fifty-page","regulatory draft boils","down to is","mandatory algorithmic transparency."]'::jsonb, NULL, NULL, 'Wh-Cleft tunggal (''What the ... draft boils down to'') diikuti verba tunggal ''is''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000553', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Pilih Summary Noun yang tepat untuk mengikat kalimat kedua:', '{"options":["These logistical hurdles","This single windfall","Such surplus","Those consensus"],"translation":"Klinik pedesaan kekurangan penyimpanan dingin sementara jadwal kapal feri tetap tidak menentu. Hambatan-hambatan logistik ini mempersulit distribusi vaksin anak di pulau-pulau terluar.","sentence_template":"Rural clinics lacked cold storage while ferry schedules remained erratic. [blank] complicated childhood vaccine rollouts across outer islands."}'::jsonb, '{"selected":"These logistical hurdles"}'::jsonb, NULL, NULL, '''These logistical hurdles'' merangkum kedua kendala operasional pada kalimat pertama.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000554', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Pilih nomina beserta preposisi bawaan yang tepat:', '{"options":["proliferation of","disparity from","attrition in","adherence to"],"translation":"Kepatuhan ketat terhadap standar bangunan tahan gempa menyelamatkan gedung pencakar langit Tokyo modern dari keruntuhan struktural.","sentence_template":"Strict [blank] seismic building codes spared modern Tokyo skyscrapers from structural collapse."}'::jsonb, '{"selected":"adherence to"}'::jsonb, NULL, NULL, '''Strict adherence to [standards/codes]'' adalah nominalisasi baku dari ''strictly adhere to''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000555', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'listening', 'listening_choice', 'Evaluasi Unit 7 — Dengarkan analisis penempatan kalimat pada bacaan TOEFL tentang irigasi Mesopotamia. Mengapa kalimat sisipan diletakkan sesudah kalimat ketiga?', '{"options":[{"id":"opt_1","text":"Rujukan ''This progressive salinization'' mengacu langsung pada proses penumpukan kerak garam akibat penguapan di kalimat ketiga"},{"id":"opt_2","text":"Kalimat ketiga membahas perdagangan tekstil di luar Mesopotamia"},{"id":"opt_3","text":"Petani beralih ke jelai jauh sebelum tanah mengalami penguapan"},{"id":"opt_4","text":"Gandum jauh lebih tahan garam dibandingkan tanaman jelai"}],"audio_text":"Because the inserted sentence begins with ''This progressive salinization eventually forced farmers to switch from wheat to salt-tolerant barley,'' it must immediately follow sentence three, where evaporation leaves mineral crusts in topsoil!"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Rantai kohesi *evaporation leaves mineral crusts* → *This progressive salinization* menjadi bukti tak terbantahkan lokasi kalimat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000556', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'writing', 'sentence_builder', 'Evaluasi Unit 7 — Susun kalimat padat ber-nominalisasi ''proliferation'':', '{"romaji":"/ðə ˈræpɪd prəˌlɪfəˈreɪʃən ʌv sɪnˈθɛtɪk ˈmiːdiə nəˈsɛsəˌteɪts ˌkrɪptəˈɡræfɪk ˈprɑːvənəns ˈstændərdz/","tokens":["The rapid proliferation","proliferating rapid","standards for journalism.","necessitates cryptographic provenance","of synthetic media","necessitating into"],"target_translation":"Menjamurnya media sintetis secara pesat menuntut standar pelacakan asal-usul kriptografis bagi dunia jurnalisme."}'::jsonb, '["The rapid proliferation","of synthetic media","necessitates cryptographic provenance","standards for journalism."]'::jsonb, NULL, NULL, 'Subjek tunggal ''The rapid proliferation...'' berpasangan dengan verba formal ''necessitates'' (= menuntut/mengharuskan).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000557', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'speaking', 'speaking_repeat', 'Evaluasi Unit 7 — Ucapkan kalimat padat akademik berikut dengan artikulasi jernih:', '{"romaji":"/səˈplaɪ tʃeɪn dɪsˈrʌpʃənz ɪɡˈzæsərˌbeɪtɪd ɪnˈfleɪʃəˌnɛri ˈprɛʃərz əˈkrɔːs ɪˈmɜːrdʒɪŋ ˈmɑːrkɪts/","display_text":"Supply-chain disruptions exacerbated inflationary pressures across emerging markets.","phonetic_breakdown":["Supply-chain disruptions","exacerbated","inflationary pressures","across emerging markets."]}'::jsonb, '{"expected_transcript":"Supply-chain disruptions exacerbated inflationary pressures across emerging markets."}'::jsonb, NULL, NULL, 'Lafalkan ''exacerbated'' /ɪɡˈzæsərˌbeɪtɪd/ (bunyi gz diikuti s, bukan k) dan ''inflationary'' ala AS /-ˌnɛri/.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000558', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Pilih phrasal verb untuk merangkum inti sari penjelasan lisan:', '{"options":["diverges into","boils down to","stems away","takes precedence from"],"translation":"Pada intinya, regularisasi jaringan saraf bermuara pada upaya mencegah model menghafal derau data pelatihan.","sentence_template":"At its core, neural network regularization [blank] preventing the model from memorizing training noise."}'::jsonb, '{"selected":"boils down to"}'::jsonb, NULL, NULL, '''Boils down to + V-ing / Noun Phrase'' menerjemahkan konsep matematika berat menjadi intuisi jernih.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000559', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'listening', 'listening_choice', 'Evaluasi Unit 7 — Dengarkan laporan evaluasi studi klinis lima tahun. Mengapa peneliti merekrut 20% peserta ekstra di awal?', '{"options":[{"id":"opt_1","text":"Mengantisipasi penyusutan jumlah peserta akibat pindah domisili agar daya statistik studi tetap terjaga hingga tahun kelima"},{"id":"opt_2","text":"Peneliti kekurangan dana untuk menguji kelompok kontrol"},{"id":"opt_3","text":"Studi selesai dalam waktu dua minggu tanpa ada peserta yang pindah"},{"id":"opt_4","text":"Dua puluh persen peserta dikeluarkan paksa pada hari pertama eksperimen"}],"audio_text":"Longitudinal aging studies inevitably suffer participant attrition due to relocation, so oversampling by twenty percent preserved statistical power through year five."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memahami istilah ''participant attrition'' dan strategi mitigasi ''oversampling''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000560', 'e5100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000047', 'writing', 'sentence_builder', 'Evaluasi Unit 7 — Susun pasangan rangkuman Summary Noun ''Such volatility'':', '{"romaji":"/spɑːt freɪt reɪts swʌŋ ˈfɔːrti pərˈsɛnt ˈwiːkli sʌtʃ ˌvɑːləˈtɪləti ˈpærəˌlaɪzd ˈɛkspɔːrt kənˈtræktɪŋ/","tokens":["volatile such","paralyzed export contracting.","swung forty percent","weekly; such volatility","Spot freight rates","paralyzing into"],"target_translation":"Tarif kargo tunai berayun empat puluh persen tiap minggu; gejolak semacam itu melumpuhkan pengikatan kontrak ekspor."}'::jsonb, '["Spot freight rates","swung forty percent","weekly; such volatility","paralyzed export contracting."]'::jsonb, NULL, NULL, '''Swung 40% weekly'' dirangkum dengan sangat presisi oleh ''; such volatility...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000561', 'e5100001-0000-4000-8000-000000000070', NULL, 'reading', 'fill_blank', 'Pilih konstruksi litotes yang berarti ''membawa biaya yang cukup besar / sama sekali tidak kecil'':', '{"options":["not insignificant","not abundant","scarcely huge","hardly expensive not"],"translation":"Memelihara klaster GPU di gedung sendiri membutuhkan biaya pendinginan dan listrik yang sama sekali tidak kecil.","sentence_template":"Maintaining on-premise GPU clusters entails a [blank] cooling and electricity expense."}'::jsonb, '{"selected":"not insignificant"}'::jsonb, NULL, NULL, 'Litotes ''a not insignificant [noun]'' (= quite substantial) lazim dipakai dalam laporan keuangan dan kebijakan C1.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000562', 'e5100001-0000-4000-8000-000000000070', NULL, 'reading', 'fill_blank', 'Pilih idiom pujian berkelas untuk pencapaian teknis yang sangat sulit:', '{"options":["scope creep","a confounding variable","no small feat","speculative at best"],"translation":"Mencapai waktu aktif 99,99 persen selama siaran Piala Dunia merupakan pencapaian yang luar biasa besar.","sentence_template":"Achieving ninety-nine point nine nine percent uptime during World Cup streaming was [blank]."}'::jsonb, '{"selected":"no small feat"}'::jsonb, NULL, NULL, '''No small feat'' memberikan apresiasi tinggi tanpa terdengar hiperbolis murahan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000563', 'e5100001-0000-4000-8000-000000000070', NULL, 'listening', 'listening_choice', 'Dengarkan komentar Direktur Produk AS atas draf presentasi manajer baru: ''Your market sizing is super thorough; the go-to-market slide, though, feels a bit high-level.'' Apa yang harus dilakukan manajer tersebut?', '{"options":[{"id":"opt_1","text":"Membatalkan kehadiran pada rapat dewan direksi besok pagi"},{"id":"opt_2","text":"Membiarkan slide tersebut apa adanya karena ''high-level'' berarti sudah sempurna"},{"id":"opt_3","text":"Menghapus slide ukuran pasar yang dipuji terlalu teliti"},{"id":"opt_4","text":"Memperkaya slide strategi masuk pasar dengan rincian eksekusi konkret dan angka saluran distribusi sebelum rapat dewan besok"}],"audio_text":"Your market sizing is super thorough; the go-to-market slide, though, feels a bit high-level ahead of tomorrow''s board review."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Dalam kode manajerial AS, kritik ''feels a bit high-level'' berarti terlalu dangkal/umum dan kekurangan detail taktis!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000564', 'e5100001-0000-4000-8000-000000000070', NULL, 'writing', 'sentence_builder', 'Susun kalimat litotes tentang risiko ekspansi pasar baru berikut:', '{"romaji":"/ˈɛntərɪŋ ˈhɛvəli ˈrɛɡjəˌleɪtɪd ˈhɛlθˌkɛr ˈmɑːrkɪts ɪz ˈsɜːrtənli nɑːt wɪˈðaʊt kəmˈplaɪəns ˈhɜːrdəlz/","tokens":["certainly not without","healthcare markets is","regulating heavy","compliance hurdles.","not with hurdles","Entering heavily regulated"],"target_translation":"Memasuki pasar layanan kesehatan yang teregulasi ketat tentu saja bukannya tanpa hambatan kepatuhan."}'::jsonb, '["Entering heavily regulated","healthcare markets is","certainly not without","compliance hurdles."]'::jsonb, NULL, NULL, '''Not without + Noun'' menegaskan keberadaan hambatan nyata dengan nada diplomatis.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000565', 'e5100001-0000-4000-8000-000000000070', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat umpan balik manajerial yang jujur dan suportif berikut:', '{"romaji":"/jʊr ˈɑːrkəˌtɛktʃər dræft ɪz ˈsɑːlɪd ðoʊ ˈsɛkʃən θriː liːvz ruːm fɔːr rɪˈfaɪnmənt/","display_text":"Your architecture draft is solid, though section three leaves room for refinement.","phonetic_breakdown":["Your architecture draft","is solid,","though section three","leaves room for refinement."]}'::jsonb, '{"expected_transcript":"Your architecture draft is solid, though section three leaves room for refinement."}'::jsonb, NULL, NULL, 'Jaga intonasi hangat pada ''is solid,'' lalu transisi konstruktif pada ''leaves room for refinement''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000566', 'e5100001-0000-4000-8000-000000000070', NULL, 'reading', 'fill_blank', 'Pilih frasa litotes yang berarti ''jauh dari kondisi ideal / belum memadai'':', '{"options":["no small feat","far from optimal","paramount to","beyond precedent"],"translation":"Mengandalkan unggahan berkas CSV manual untuk pelacakan tempat tidur rumah sakit harian masih jauh dari kondisi ideal saat wabah musiman.","sentence_template":"Relying on manual CSV uploads for daily hospital bed tracking remains [blank] during seasonal outbreaks."}'::jsonb, '{"selected":"far from optimal"}'::jsonb, NULL, NULL, '''Far from optimal'' mengkritik kelemahan sistem secara profesional tanpa bahasa emosional.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000567', 'e5100001-0000-4000-8000-000000000070', NULL, 'listening', 'listening_choice', 'Dengarkan situasi komunikasi lintas budaya antara tim Jakarta dan VP di Seattle. Mengapa diamnya tim saat ditanya ''Any blockers?'' memicu masalah?', '{"options":[{"id":"opt_1","text":"Lembur diam-diam tanpa melapor merupakan standar wajib perusahaan AS"},{"id":"opt_2","text":"Insinyur dilarang berbicara selama rapat harian berlangsung"},{"id":"opt_3","text":"VP di Seattle lebih menyukai tim yang menyembunyikan masalah hingga hari peluncuran"},{"id":"opt_4","text":"Dalam budaya kerja konteks-rendah AS, diam ditafsirkan jadwal aman; mengangkat risiko sejak dini disertai opsi kompromi jauh lebih dihargai"}],"audio_text":"In low-context US engineering culture, staying silent during standup signals everything is on schedule—flagging risks early with two trade-off options builds far more respect than heroic silent overtime."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Memahami kontras *high-context vs. low-context communication* mencegah kesalahpahaman fatal di karier global.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000568', 'e5100001-0000-4000-8000-000000000070', NULL, 'writing', 'sentence_builder', 'Susun kalimat *upward management* kepada pimpinan eksekutif:', '{"romaji":"/ˈflæɡɪŋ ˈvɛndər dɪˈleɪz ˈɜːrli lɛts ʌs ˈmænɪdʒ ˌɛkspɛkˈteɪʃənz ˈʌpwərd/","tokens":["Flagging vendor delays","flag vendor","upwardly expect","early lets us","manage expectations upward","and reallocate scope."],"target_translation":"Melaporkan keterlambatan vendor sejak dini memungkinkan kita mengelola ekspektasi pimpinan dan mengalokasikan ulang ruang lingkup."}'::jsonb, '["Flagging vendor delays","early lets us","manage expectations upward","and reallocate scope."]'::jsonb, NULL, NULL, '''Manage expectations upward'' adalah keterampilan komunikasi kepemimpinan kunci di organisasi global.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000569', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Perhatikan hadirnya subjek baru ''the vendor'' untuk jadwal minggu depan, lalu pilih kata kerja yang tepat:', '{"options":["will postpone","postpones","postponing","postponed"],"translation":"Mengingat puncak trafik liburan minggu depan, direktur SRE kami lebih memilih agar vendor menunda pembaruan firmware hingga Januari.","sentence_template":"Given peak holiday traffic next week, our SRE director would rather the vendor [blank] firmware upgrades until January."}'::jsonb, '{"selected":"postponed"}'::jsonb, NULL, NULL, '''Would rather + Subject 2 (the vendor)'' untuk preferensi masa kini/depan wajib memakai Past Simple Subjunctive (''postponed'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000570', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Pilih penguat kontras negatif yang berarti ''apalagi / terlebih lagi tidak mungkin'':', '{"options":["by and large","provided that","insofar as","much less"],"translation":"Sebagian besar chatbot awal kesulitan melacak konteks dua giliran bicara, apalagi menegosiasikan kontrak pasokan banyak pihak.","sentence_template":"Most early chatbots struggled to track two-turn context, [blank] negotiate multi-party supply contracts."}'::jsonb, '{"selected":"much less"}'::jsonb, NULL, NULL, '''Much less + V1'' (paralel dengan ''track'') menegaskan ketidakmampuan tingkat yang jauh lebih tinggi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000571', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'listening', 'listening_choice', 'Dengarkan respons manajer hukum terhadap tindakan tim pemasaran kemarin. Kapan publikasi logo klien itu terjadi?', '{"options":[{"id":"opt_1","text":"Tim hukum sudah menyetujui penggunaan logo klien sejak minggu lalu"},{"id":"opt_2","text":"Tim pemasaran sudah telanjur memublikasikan logo klien kemarin tanpa meminta izin hukum terlebih dahulu"},{"id":"opt_3","text":"Manajer hukum meminta tim pemasaran mengunggah lebih banyak logo hari ini"},{"id":"opt_4","text":"Studi kasus tersebut baru akan dipublikasikan bulan depan"}],"audio_text":"Honestly, I''d much rather your team had cleared that client logo with legal yesterday before posting the case study."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Would rather + Subject 2 + HAD V3 (had cleared ... yesterday)'' menyatakan teguran halus atas tindakan masa lalu yang sudah telanjur terjadi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000572', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'writing', 'sentence_builder', 'Susun kalimat preferensi tata kelola menggunakan ''would rather + S2 + didn''t'':', '{"romaji":"/fɔːr ˈɔːdɪt ˌɪndɪˈpɛndəns ˈʃɛrˌhoʊldərz wʊd ˈræðər ɪɡˈzɛkjətɪvz ˈdɪdənt tʃɛr/","tokens":["For audit independence,","executives didn''t chair","don''t chair","chairing not","the compensation committee.","shareholders would rather"],"target_translation":"Demi independensi audit, pemegang saham lebih memilih agar para eksekutif tidak mengetuai komite remunerasi."}'::jsonb, '["For audit independence,","shareholders would rather","executives didn''t chair","the compensation committee."]'::jsonb, NULL, NULL, 'Negasi Past Subjunctive sesudah ''would rather + executives'' memakai ''didn''t + V1 (chair)''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000573', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kontras ''let alone'' berikut dengan penekanan alami:', '{"romaji":"/fjuː mjuːˌnɪsəˈpælətiz kæn fʌnd ˈbeɪsɪk ˈsiːˌwɔːlz lɛt əˈloʊn ˈɔːfˌʃɔːr stɔːrm ˈbæriərz/","display_text":"Few municipalities can fund basic seawalls, let alone offshore storm barriers.","phonetic_breakdown":["Few municipalities","can fund basic seawalls,","let alone","offshore storm barriers."]}'::jsonb, '{"expected_transcript":"Few municipalities can fund basic seawalls, let alone offshore storm barriers."}'::jsonb, NULL, NULL, 'Perhatikan ''Few municipalities'' (tanpa ''a'' = hampir tidak ada / negatif implisit!) sehingga sah diikuti ''let alone''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000574', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Pilih bentuk kata kerja sesudah ''would rather'' ketika subjeknya SAMA (tanpa subjek kedua):', '{"options":["declined","declines","decline","to decline"],"translation":"Demi menjaga netralitas editorial, lembaga riset kami lebih memilih menolak sponsor korporat sama sekali daripada mengorbankan tinjauan sejawat.","sentence_template":"To preserve editorial neutrality, our research institute would rather [blank] corporate sponsorship altogether than compromise peer review."}'::jsonb, '{"selected":"decline"}'::jsonb, NULL, NULL, 'Tanpa pergantian subjek (''would rather [V1] ... than [V1]''), gunakan bare infinitive ''decline''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000575', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'listening', 'listening_choice', 'Dengarkan diskusi sosiolinguistik TOEFL tentang komunikasi tidak langsung (indirectness). Mengapa penutur membingkai permintaan secara halus?', '{"options":[{"id":"opt_1","text":"Ketidaklangsungan dipakai bukan karena ragu, melainkan demi menghormati otonomi lawan bicara (''negative face'')"},{"id":"opt_2","text":"''Negative face'' berarti ekspresi wajah marah saat berdebat"},{"id":"opt_3","text":"Ahli linguistik menyarankan semua orang berbicara dengan kalimat perintah kasar"},{"id":"opt_4","text":"Penutur tidak langsung selalu gagal menyampaikan maksudnya di tempat kerja"}],"audio_text":"According to politeness theory, speakers use indirectness not out of confusion, but to protect the listener''s autonomy—what linguists call ''negative face.''"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Konsep klasik Brown & Levinson (*Politeness Theory: positive vs. negative face*) yang sering muncul di kuliah linguistik/antropologi TOEFL.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000576', 'e5100001-0000-4000-8000-000000000071', 'e2000001-0000-4000-8000-000000000048', 'writing', 'sentence_builder', 'Susun kalimat esai dengan paralelisme ''much less'':', '{"romaji":"/ʌnˈvɛrəˌfaɪd ˈpriːˌprɪnts ˈrɛrli ˈdʒʌstəˌfaɪ ˈklɪnɪkəl haɪp mʌtʃ lɛs ɪˈmiːdiət ˈtʃeɪndʒɪz/","tokens":["justifying rarely","changes in hospital","much less immediate","Unverified preprints rarely","less much","prescribing.","justify clinical hype,"],"target_translation":"Pracetak yang belum terverifikasi jarang membenarkan sensasi klinis, apalagi perubahan seketika pada peresepan obat rumah sakit."}'::jsonb, '["Unverified preprints rarely","justify clinical hype,","much less immediate","changes in hospital","prescribing."]'::jsonb, NULL, NULL, 'Adverbia pembatas ''rarely'' memberi nuansa negatif sehingga berpasangan mulus dengan ''much less + Noun Phrase''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000577', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Pilih idiom yang berarti ''memilih berprasangka baik saat niat seseorang belum jelas'':', '{"options":["give them the benefit of the doubt","take precedence over them","incur technical debt","cast them into sharp relief"],"translation":"Ketika rekan setim di Berlin mengirim komentar kode satu baris, insinyur yang dewasa memilih berprasangka baik alih-alih mengira ada permusuhan.","sentence_template":"When a teammate in Berlin sends a one-line code comment, mature engineers [blank] rather than assuming hostility."}'::jsonb, '{"selected":"give them the benefit of the doubt"}'::jsonb, NULL, NULL, '''Give [someone] the benefit of the doubt'' mencegah eskalasi salah paham lintas budaya.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000578', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Lengkapi kalimat mediasi rapat antara tim penjualan dan tim teknik berikut:', '{"options":["attrition rate","common ground","confounding variable","scope creep"],"translation":"Kedua tim sama-sama sangat peduli pada retensi klien korporat—berangkat dari titik temu tersebut membantu kami menyepakati peta jalan Q3 yang realistis.","sentence_template":"Both squads care deeply about enterprise retention—starting from that [blank] helped us agree on a realistic Q3 roadmap."}'::jsonb, '{"selected":"common ground"}'::jsonb, NULL, NULL, '''Common ground'' merujuk pada landasan tujuan bersama yang menyatukan pihak berbeda.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000579', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'listening', 'listening_choice', 'Dengarkan bagaimana Engineering Director menengahi perdebatan sengit soal insiden produksi. Apa aturan rapat yang ia tegakkan?', '{"options":[{"id":"opt_1","text":"Menghentikan saling menyalahkan individu dan mengalihkan fokus ke perbaikan celah sistem pengujian staging"},{"id":"opt_2","text":"Menutup diskusi tanpa mencari tahu penyebab ketidakcocokan skema"},{"id":"opt_3","text":"Menghapus lingkungan pengujian staging agar rilis lebih cepat"},{"id":"opt_4","text":"Mencari nama satu insinyur untuk diberi surat peringatan di depan umum"}],"audio_text":"Hold on—let''s separate the person from the problem here: nobody deployed a bug on purpose, so let''s ask why our staging suite missed the schema mismatch."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Separate the person from the problem'' adalah inti kepemimpinan psikologis yang aman (*psychological safety*).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000580', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'writing', 'sentence_builder', 'Susun kalimat pembingkaian ulang konflik lintas divisi berikut:', '{"romaji":"/ˈræðər ðæn ˈfreɪmɪŋ ðɪs æz seɪlz ˈvɜːrsəz ˌɛndʒəˈnɪrɪŋ lɛts ˈkoʊdɪˌzaɪn ə feɪzd/","tokens":["versus engineering, let''s","co-design a phased","Rather than framing","this as sales","enterprise launch.","launches phasing","framed into"],"target_translation":"Alih-alih membingkai hal ini sebagai kubu penjualan melawan kubu teknik, mari kita rancang bersama peluncuran korporat bertahap."}'::jsonb, '["Rather than framing","this as sales","versus engineering, let''s","co-design a phased","enterprise launch."]'::jsonb, NULL, NULL, '''Rather than framing this as A versus B, let''s...'' langsung mengubah suasana konfrontatif menjadi kolaboratif.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000581', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'speaking', 'speaking_repeat', 'Ucapkan kalimat mediasi kepemimpinan berikut dengan nada tenang dan merangkul:', '{"romaji":"/ˌrɛtrəˈspɛktɪvz ɡɪv ˈɛvri skwɑːd ə seɪf speɪs tə ɛr ˈɡriːvənsɪz kənˈstrʌktɪvli/","display_text":"Retrospectives give every squad a safe space to air grievances constructively.","phonetic_breakdown":["Retrospectives give","every squad a safe space","to air grievances","constructively."]}'::jsonb, '{"expected_transcript":"Retrospectives give every squad a safe space to air grievances constructively."}'::jsonb, NULL, NULL, 'Lafalkan ''grievances'' /ˈɡriːvənsɪz/ dengan vokal panjang /iː/ yang jernih.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000582', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Pilih kata kerja yang tepat dalam kolokasi ''menyampaikan ganjalan secara terbuka agar terselesaikan'':', '{"options":["extrapolate","proliferate","waive","air"],"translation":"Mengadakan sesi dengar pendapat terstruktur memungkinkan perawat rumah sakit menyampaikan keluhan penjadwalan secara terbuka sebelum perundingan serikat dimulai.","sentence_template":"Holding structured listening sessions allowed hospital nurses to [blank] scheduling grievances before union talks began."}'::jsonb, '{"selected":"air"}'::jsonb, NULL, NULL, '''Air grievances / concerns'' berarti mengemukakan keberatan secara terbuka di forum yang tepat.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000583', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'listening', 'listening_choice', 'Dengarkan kuliah manajemen organisasi TOEFL tentang keberagaman kognitif tim. Kapan tim multikultural mengungguli tim homogen?', '{"options":[{"id":"opt_1","text":"Anggota tim dianjurkan menyembunyikan perbedaan pendapat demi keharmonisan semu"},{"id":"opt_2","text":"Tim homogen selalu mengalahkan tim multikultural dalam setiap tugas"},{"id":"opt_3","text":"Tim multikultural unggul otomatis tanpa memerlukan peran kepemimpinan"},{"id":"opt_4","text":"Tim multikultural unggul secara khusus ketika pemimpin membangun rasa aman psikologis sehingga pandangan berbeda tidak disensor sendiri"}],"audio_text":"Multicultural teams don''t automatically outperform homogeneous ones; they excel specifically when leaders establish psychological safety so dissenting views aren''t self-censored."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Sintesis nuansa C1: mengualifikasi klaim (''don''t automatically outperform; they excel specifically when...'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000584', 'e5100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000048', 'writing', 'sentence_builder', 'Susun kalimat prinsip komunikasi lintas zona waktu berikut:', '{"romaji":"/əˈsuːmɪŋ ˈpɑːzətɪv ɪnˈtɛnt prɪˈvɛnts tɜːrs slæk ˈmɛsɪdʒɪz frʌm ˈspaɪrəlɪŋ ˈɪntuː/","tokens":["Assuming positive intent","to spiral","into cross-office resentment.","prevents terse Slack","messages from spiraling","prevented terse"],"target_translation":"Mengasumsikan niat baik mencegah pesan singkat di Slack meruncing menjadi rasa kesal antarkantor."}'::jsonb, '["Assuming positive intent","prevents terse Slack","messages from spiraling","into cross-office resentment."]'::jsonb, NULL, NULL, 'Lafalkan ''assuming'' ala AS /əˈsuːmɪŋ/ (tanpa /j/) dalam struktur ''prevents X from spiraling into Y''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000585', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih kata kerja Past Subjunctive sesudah ''would rather + subjek kedua'' untuk kebijakan saat ini:', '{"options":["using","used","use","will use"],"translation":"Pejabat pelindung data kami lebih memilih agar para manajer produk menggunakan data uji sintetis anonim selama demo langsung.","sentence_template":"Our data protection officer would rather product managers [blank] anonymized synthetic fixtures during live demos."}'::jsonb, '{"selected":"used"}'::jsonb, NULL, NULL, '''Would rather + Subject 2 (product managers)'' untuk preferensi kini/mendatang wajib menggunakan bentuk lampau ''used''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000586', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih litotes yang bermakna ''cukup lazim terjadi / bukannya jarang'':', '{"options":["not abundant","no small","much less","not uncommon"],"translation":"Dalam penggelaran kabel serat optik kepulauan, keterlambatan izin dasar laut cukup lazim terjadi selama bulan-bulan monsun.","sentence_template":"In archipelagic fiber deployments, seabed permit delays are [blank] during monsoon months."}'::jsonb, '{"selected":"not uncommon"}'::jsonb, NULL, NULL, '''Not uncommon'' (= fairly frequent) adalah litotes klasik bahasa Inggris akademik dan diplomatik.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000587', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'listening', 'listening_choice', 'Evaluasi Unit 8 — Dengarkan umpan balik tertulis investor AS kepada pendiri startup. Apa maksud di balik ungkapan halusnya?', '{"options":[{"id":"opt_1","text":"Investor meminta startup menutup operasional di kota-kota Tier-1"},{"id":"opt_2","text":"Model bisnis di pedesaan sudah jauh lebih menguntungkan daripada kota besar"},{"id":"opt_3","text":"Bagian pedesaan tidak memerlukan perubahan apa pun sebelum pendanaan"},{"id":"opt_4","text":"Ekonomi unit di kota besar sudah meyakinkan, namun model balik modal di wilayah pedesaan masih lemah dan perlu diperbaiki"}],"audio_text":"Your unit economics in Tier-1 cities are compelling; rural payback periods, however, leave room for refinement."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Menerjemahkan *diplomatic understatement* ''leave room for refinement'' secara akurat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000588', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'writing', 'sentence_builder', 'Evaluasi Unit 8 — Susun kalimat penegas ''much less'' berikut:', '{"romaji":"/ˈpeɪpər ˈlɛdʒərz kæn ˈskɛrsli træk ˈloʊkəl ˈɪnvənˌtɔːri mʌtʃ lɛs ˈriːəl taɪm/","tokens":["real-time omni-channel","scarcely track local","inventory, much less","returns.","Paper ledgers can","less much","scarcely tracking"],"target_translation":"Buku besar kertas nyaris tak sanggup melacak inventaris lokal, apalagi retur omni-kanal secara waktu nyata."}'::jsonb, '["Paper ledgers can","scarcely track local","inventory, much less","real-time omni-channel","returns."]'::jsonb, NULL, NULL, 'Adverbia semi-negatif ''scarcely'' berpasangan dengan ''much less + Noun Phrase''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000589', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'speaking', 'speaking_repeat', 'Evaluasi Unit 8 — Ucapkan kalimat pujian pencapaian tim berikut dengan tulus:', '{"romaji":"/koʊˈɔːrdəˌneɪtɪŋ twɛlv ˈmɪnɪstriz ɑːn wʌn ˈdɪdʒɪtəl ˈstændərd wʌz noʊ smɔːl fiːt/","display_text":"Coordinating twelve ministries on one digital standard was no small feat.","phonetic_breakdown":["Coordinating twelve ministries","on one digital standard","was no small feat."]}'::jsonb, '{"expected_transcript":"Coordinating twelve ministries on one digital standard was no small feat."}'::jsonb, NULL, NULL, 'Tekankan dengan hangat frasa penutup ''NO SMALL FEAT'' (/noʊ smɔːl fiːt/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000590', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih bentuk lampau sempurna sesudah ''would rather'' untuk penyesalan kejadian kemarin:', '{"options":["will vet","had vetted","vetted","vets"],"translation":"Terus terang, ketua dewan lebih memilih seandainya tim pers telah memeriksa draf pernyataan tersebut bersama penasihat hukum sebelum taklimat kemarin.","sentence_template":"Frankly, the chairwoman would rather the press team [blank] the draft statement with counsel before yesterday''s briefing."}'::jsonb, '{"selected":"had vetted"}'::jsonb, NULL, NULL, 'Keterangan masa lalu ''before yesterday''s briefing'' dengan subjek kedua menuntut Past Perfect ''had vetted''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000591', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'listening', 'listening_choice', 'Evaluasi Unit 8 — Dengarkan refleksi manajer Indonesia yang memimpin tim di Austin dan Jakarta. Bagaimana ia menjembatani perbedaan gaya bicara?', '{"options":[{"id":"opt_1","text":"Memadukan dokumen bacaan asinkron tertulis sebelum rapat dengan diskusi langsung agar kedua budaya kerja sama-sama terdengar suaranya"},{"id":"opt_2","text":"Memisahkan kedua tim agar tidak pernah bekerja pada proyek yang sama"},{"id":"opt_3","text":"Menghapus dokumen tertulis dan memaksa semua orang berdebat spontan"},{"id":"opt_4","text":"Melarang insinyur Austin berbicara langsung selama rapat berlangsung"}],"audio_text":"My Austin engineers critique ideas bluntly in meetings, whereas my Jakarta devs prefer written async comments—combining pre-read docs with live debate gave everyone an equal voice."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Kepemimpinan inklusif lintas budaya merancang proses yang mengakomodasi *direct verbal* maupun *reflective written* contributors.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000592', 'e5100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000048', 'writing', 'sentence_builder', 'Evaluasi Unit 8 — Susun kalimat mediasi konflik tim berikut:', '{"romaji":"/ˈsɛpəˌreɪtɪŋ ðə ˈpɜːrsən frʌm ðə ˈprɑːbləm hɛlpt boʊθ dəˈrɛktərz faɪnd ˈkɑːmən ɡraʊnd/","tokens":["from the problem","grounds common","find common ground","separates person","on budget cuts.","helped both directors","Separating the person"],"target_translation":"Memisahkan urusan pribadi dari pokok masalahnya membantu kedua direktur menemukan titik temu terkait pemangkasan anggaran."}'::jsonb, '["Separating the person","from the problem","helped both directors","find common ground","on budget cuts."]'::jsonb, NULL, NULL, 'Gerund pembuka diikuti ''helped + Object + bare infinitive (find common ground)''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000593', 'e5100001-0000-4000-8000-000000000074', NULL, 'reading', 'fill_blank', 'Perhatikan subjek sejati di belakang kata kerja pada struktur fronting berikut:', '{"options":["have","is","are","were"],"translation":"Inti dari proyeksi inflasi bank sentral tersebut adalah asumsi bahwa kemacetan pelabuhan akan mereda pada kuartal ketiga.","sentence_template":"Central to the central bank''s inflation forecasts [blank] the assumption that port bottlenecks will ease by Q3."}'::jsonb, '{"selected":"is"}'::jsonb, NULL, NULL, 'Jangan terkecoh kata jamak ''forecasts''; subjek kalimat yang dikedepankan ini adalah tunggal (''the assumption''), sehingga memakai ''is''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000594', 'e5100001-0000-4000-8000-000000000074', NULL, 'reading', 'fill_blank', 'Pilih kata kerja jamak yang selaras dengan subjek di bagian akhir kalimat fronting:', '{"options":["has been","was","is","are"],"translation":"Yang sama pentingnya bagi ketahanan pesisir adalah pembibitan bakau berbasis masyarakat serta sirene peringatan dini.","sentence_template":"Equally vital to coastal resilience [blank] community-led mangrove nurseries and early-warning sirens."}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, 'Subjek majemuk jamak di belakang (''mangrove nurseries and early-warning sirens'') menuntut kata kerja jamak ''are''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000595', 'e5100001-0000-4000-8000-000000000074', NULL, 'listening', 'listening_choice', 'Dengarkan pembukaan kuliah kebijakan energi TOEFL. Apa faktor inti yang menurut profesor paling menentukan keberhasilan dekarbonisasi?', '{"options":[{"id":"opt_1","text":"Peningkatan impor batu bara kokas untuk menekan harga listrik rumah tangga"},{"id":"opt_2","text":"Bagaimana produsen baja dapat menggantikan batu bara kokas dengan biaya yang tetap kompetitif"},{"id":"opt_3","text":"Penutupan seluruh pabrik baja dunia sebelum akhir dekade ini"},{"id":"opt_4","text":"Penghentian pembangunan jalur kereta api antarkota"}],"audio_text":"At the heart of industrial decarbonization lies a deceptively simple question: how can steelmakers replace coking coal at competitive cost?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Fronting lokatif-metaforis ''At the heart of X lies [Subject]'' menyoroti inti persoalan kuliah sejak kalimat pertama.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000596', 'e5100001-0000-4000-8000-000000000074', NULL, 'writing', 'sentence_builder', 'Susun kalimat *predicate fronting* untuk ringkasan kebijakan (*policy brief*) berikut:', '{"romaji":"/ˈpærəˌmaʊnt tə ˈpeɪʃənt trʌst ɪz trænˈspærənt ˈɡʌvərnəns ʌv ˈklɪnɪkəl ˈtreɪnɪŋ/","tokens":["Paramount to patient","trust is transparent","training datasets.","governing into","governance of clinical","are transparent"],"target_translation":"Hal paling utama bagi kepercayaan pasien adalah tata kelola dataset pelatihan klinis yang transparan."}'::jsonb, '["Paramount to patient","trust is transparent","governance of clinical","training datasets."]'::jsonb, NULL, NULL, '''Paramount to [NP] is [Singular Subject: transparent governance...]'' menonjolkan prioritas kebijakan.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000597', 'e5100001-0000-4000-8000-000000000074', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat transisi akademik berstruktur fronting berikut dengan jeda tegas sebelum ''is'':', '{"romaji":"/ˈkruːʃəl tə ðɪs ˈfreɪmˌwɜːrk ɪz ˈrɪɡərəs ˌvæləˈdeɪʃən əˈkrɔːs dəˈvɜːrs ˈrʊrəl ˈklɪnɪks/","display_text":"Crucial to this framework is rigorous validation across diverse rural clinics.","phonetic_breakdown":["Crucial to","this framework is","rigorous validation","across diverse rural clinics."]}'::jsonb, '{"expected_transcript":"Crucial to this framework is rigorous validation across diverse rural clinics."}'::jsonb, NULL, NULL, 'Lafalkan ''rural'' ala AS /ˈrʊrəl/ dengan lidah melengkung rhotic yang mantap.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000598', 'e5100001-0000-4000-8000-000000000074', NULL, 'reading', 'fill_blank', 'Pilih partisip pembuka fronting yang menggambarkan bukti terlampir dalam laporan audit:', '{"options":["Attaching","Attach","Attached","To attach"],"translation":"Terlampir pada memorandum ini adalah tiga tabel sensitivitas yang memodelkan skenario terburuk fluktuasi mata uang.","sentence_template":"[blank] to this memorandum are three sensitivity tables modeling worst-case currency swings."}'::jsonb, '{"selected":"Attached"}'::jsonb, NULL, NULL, 'Partisip pasif fronting ''Attached to X are [Plural Subject]'' sangat baku dalam korespondensi eksekutif dan hukum.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000599', 'e5100001-0000-4000-8000-000000000074', NULL, 'listening', 'listening_choice', 'Dengarkan pemaparan analis keamanan siber kepada komite audit. Mengapa pencadangan luring (*offline backups*) ditekankan di akhir kalimat?', '{"options":[{"id":"opt_1","text":"Perusahaan disarankan kembali memakai mesin ketik kertas sepenuhnya"},{"id":"opt_2","text":"Sinkronisasi cloud otomatis menghapus seluruh serangan ransomware tanpa cadangan luring"},{"id":"opt_3","text":"Serangan ransomware hanya mengincar komputer pribadi yang tidak terhubung ke internet"},{"id":"opt_4","text":"Sinkronisasi cloud biasa ikut menyalin berkas yang terenkripsi dalam hitungan detik kecuali tersedia pencadangan luring yang tak dapat diubah"}],"audio_text":"Compounding the ransomware threat is the sobering reality that cloud sync alone replicates encrypted files within seconds unless immutable offline backups exist."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Partisip aktif fronting ''Compounding the threat is [the reality that...]'' menghubungkan ancaman sebelumnya dengan eskalasi risiko baru.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000600', 'e5100001-0000-4000-8000-000000000074', NULL, 'writing', 'sentence_builder', 'Susun kalimat fronting lokatif dengan kata kerja intransitif ''stands'':', '{"romaji":"/æt ðə ˈsɛntər ʌv ˈaʊər ˈplætˌfɔːrm ˈɑːrkəˌtɛktʃər stændz ə ˈzɪroʊ trʌst/","tokens":["standing into","At the center","architecture stands a","stand a","of our platform","zero-trust identity broker."],"target_translation":"Di pusat arsitektur platform kami berdiri pialang identitas zero-trust."}'::jsonb, '["At the center","of our platform","architecture stands a","zero-trust identity broker."]'::jsonb, NULL, NULL, 'Frasa tempat di awal kalimat memicu inversi utuh kata kerja intransitif ''stands'' sebelum subjek tunggal.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000601', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Pilih kata ganti pembanding logis untuk menyetarakan ''the energy density'' (tunggal):', '{"options":["those of","that of","them in","which of"],"translation":"Kepadatan energi prototipe baterai padat sudah melampaui kepadatan energi paket litium-ion standar.","sentence_template":"The energy density of solid-state prototypes already surpasses [blank] standard lithium-ion packs."}'::jsonb, '{"selected":"that of"}'::jsonb, NULL, NULL, 'Karena ''the energy density'' bersifat tunggal tak terhitung, kata ganti pembanding yang wajib dipakai adalah ''that of''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000602', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Jaga paralelisme mutlak sesudah pasangan korelatif ''not only ... but also'':', '{"options":["but also V-ing offshore","and also offshore vendors","but offshore vendors also","but also to offshore vendors"],"translation":"Undang-undang privasi baru tersebut berlaku tidak hanya bagi tekfin domestik tetapi juga bagi vendor luar negeri yang memproses data warga.","sentence_template":"The new privacy statute applies not only to domestic fintechs [blank] processing citizen records."}'::jsonb, '{"selected":"but also to offshore vendors"}'::jsonb, NULL, NULL, 'Karena cabang pertama dibuka dengan preposisi ''to'' (''not only TO domestic fintechs''), cabang kedua wajib dibuka dengan ''but also TO offshore vendors''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000603', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'listening', 'listening_choice', 'Dengarkan petikan kuliah ekonomi pembangunan TOEFL. Kesalahan perbandingan apa yang dikoreksi dosen pada draf mahasiswa?', '{"options":[{"id":"opt_1","text":"Menulis angka persentase menggunakan huruf alih-alih simbol"},{"id":"opt_2","text":"Membandingkan angka penumpang langsung dengan nama kota tanpa menyisipkan kata ganti penunjuk ''that of''"},{"id":"opt_3","text":"Menggunakan kata kerja aktif alih-alih kalimat pasif di seluruh paragraf"},{"id":"opt_4","text":"Menyebutkan dua kota Asia Tenggara di dalam kalimat yang sama"}],"audio_text":"Watch your comparisons in policy memos: saying ''Jakarta''s transit ridership exceeds Kuala Lumpur'' compares riders to an entire city—write ''exceeds that of Kuala Lumpur''!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kaidah perbandingan setara (*like-to-like comparison*) selalu diuji ketat pada penyuntingan akademik tingkat lanjut.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000604', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'writing', 'sentence_builder', 'Susun kalimat paralelisme tiga serangkai (*parallelism in series*) berikut:', '{"romaji":"/ˈɔːdɪtərz ɪˈvæljuˌeɪtɪd haʊ ɡrænts wɜːr dɪsˈbɜːrst huː əˈpruːvd ˈɪnvɔɪsɪz/","tokens":["receipts matching","grants were disbursed,","who approved invoices,","matched ledger entries.","and whether receipts","approving invoices","Auditors evaluated how"],"target_translation":"Para auditor mengevaluasi bagaimana hibah dicairkan, siapa yang menyetujui faktur, dan apakah kuitansi cocok dengan entri buku besar."}'::jsonb, '["Auditors evaluated how","grants were disbursed,","who approved invoices,","and whether receipts","matched ledger entries."]'::jsonb, NULL, NULL, 'Tiga klausa nomina berurutan (''how S+V, who V, and whether S+V'') menjaga paralelisme sintaksis tingkat tinggi.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000605', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'speaking', 'speaking_repeat', 'Ucapkan kalimat perbandingan jamak ''those of'' berikut dengan artikulasi jernih:', '{"romaji":"/ˌɡrædʒuˈeɪʃən reɪts æt kəˈmjuːnəti ˈmɛntɔːrˌʃɪp ˈkoʊhɔːrts ˌaʊtˈpeɪs ðoʊz ʌv ʌnˈɡaɪdɪd ˈproʊɡræmz/","display_text":"Graduation rates at community mentorship cohorts outpace those of unguided programs.","phonetic_breakdown":["Graduation rates","at community mentorship cohorts","outpace those of","unguided programs."]}'::jsonb, '{"expected_transcript":"Graduation rates at community mentorship cohorts outpace those of unguided programs."}'::jsonb, NULL, NULL, '''Graduation rates'' berbentuk jamak sehingga diwakili secara presisi oleh ''those of''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000606', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Pilih kelanjutan paralel sesudah struktur ''whether by reducing ...'':', '{"options":["or to introduce","nor by introducing","or by introducing","and introducing"],"translation":"Pemerintah kota harus menekan permintaan listrik puncak, baik dengan memberi insentif surya atap maupun dengan memberlakukan tarif industri dinamis.","sentence_template":"Municipalities must curb peak electricity demand, whether by incentivizing rooftop solar [blank] dynamic industrial tariffs."}'::jsonb, '{"selected":"or by introducing"}'::jsonb, NULL, NULL, '''Whether by + V-ing'' wajib dipasangkan secara simetris dengan ''or by + V-ing''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000607', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'listening', 'listening_choice', 'Dengarkan pidato dekan teknik saat membuka laboratorium robotika baru. Bagaimana ia menyeimbangkan visi riset?', '{"options":[{"id":"opt_1","text":"Hanya meneliti rumus matematika murni tanpa aplikasi rumah sakit"},{"id":"opt_2","text":"Bukan mengejar keindahan teori yang terisolasi maupun membuat gawai berumur pendek, melainkan merekayasa sistem tangguh bagi rumah sakit publik"},{"id":"opt_3","text":"Menutup riset perangkat keras demi berfokus pada aplikasi permainan"},{"id":"opt_4","text":"Memproduksi gawai konsumen murah sebanyak mungkin setiap kuartal"}],"audio_text":"Our mandate is neither to chase theoretical elegance in isolation nor to build short-lived gadgets, but to engineer resilient systems that serve public hospitals."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Rangkaian korelatif paralel ''neither to V1 ... nor to V1, but to V1'' menciptakan ritme pidato yang sangat berwibawa.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000608', 'e5100001-0000-4000-8000-000000000075', 'e2000001-0000-4000-8000-000000000049', 'writing', 'sentence_builder', 'Susun kalimat keselarasan kedekatan (*proximity agreement*) ''neither ... nor'':', '{"romaji":"/ˈniːðər ðə ˈlɛɡəsi ˈprɑːksiz nɔːr ðə ˈbækˌʌp ˈfaɪərˌwɔːl səˈpɔːrts ɪnˈkrɪptɪd/","tokens":["encrypted HTTP/3","proxies nor the","Neither the legacy","traffic natively.","support encrypted","backup firewall supports","or the backup"],"target_translation":"Baik proksi lawas maupun tembok api cadangan tidak mendukung lalu lintas HTTP/3 terenkripsi secara bawaan."}'::jsonb, '["Neither the legacy","proxies nor the","backup firewall supports","encrypted HTTP/3","traffic natively."]'::jsonb, NULL, NULL, 'Pada ''Neither A nor B'', kata kerja mengikuti subjek terdekat (''the backup firewall'' = tunggal -> ''supports'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000609', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Pilih pasangan preposisi yang menjaga keseimbangan struktur diagnosis berikut:', '{"options":["except for","but from","and from","but by"],"translation":"Sebagian besar gangguan mikroservis berakar bukan dari kutu kernel yang langka, melainkan dari batas waktu yang salah dikonfigurasi saat perilisan rutin.","sentence_template":"Most microservices outages stem not from exotic kernel bugs, [blank] misconfigured timeouts during routine deploys."}'::jsonb, '{"selected":"but from"}'::jsonb, NULL, NULL, '''Stem not FROM X, but FROM Y'' mengulang preposisi ''from'' demi kejelasan paralelisme.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000610', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Lengkapi kalimat keseimbangan regulasi AI dengan pasangan paralel sesudah ''between'':', '{"options":["to mitigate","and mitigating","with mitigating","or mitigated"],"translation":"Tata kelola AI yang efektif mencapai keseimbangan peka antara mendorong penyelidikan ilmiah terbuka dan memitigasi risiko keamanan hayati.","sentence_template":"Effective AI governance strikes a delicate balance between fostering open scientific inquiry [blank] biosecurity risks."}'::jsonb, '{"selected":"and mitigating"}'::jsonb, NULL, NULL, '''Between + V-ing (fostering) + AND + V-ing (mitigating)'' adalah pasangan wajib.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000611', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'listening', 'listening_choice', 'Dengarkan jawaban kandidat beasiswa kebijakan publik tentang subsidi kendaraan listrik. Apa argumen keseimbangannya?', '{"options":[{"id":"opt_1","text":"Pemerintah sebaiknya menghentikan seluruh transportasi umum perkotaan"},{"id":"opt_2","text":"Kendaraan listrik menghasilkan asap knalpot lebih tebal daripada mobil bensin"},{"id":"opt_3","text":"Subsidi mobil listrik harus diberikan tanpa perlu memikirkan sumber pembangkit listrik"},{"id":"opt_4","text":"Subsidi mobil listrik hanya efektif bila berjalan beriringan dengan modernisasi jaringan listrik agar tidak sekadar memindahkan emisi ke PLTU batu bara"}],"audio_text":"Subsidizing electric cars works only in tandem with grid modernization; otherwise, we''re simply shifting tailpipe emissions back to coal-fired power plants."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Kolokasi ''in tandem with'' mengikat dua kebijakan yang saling bergantung.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000612', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'writing', 'sentence_builder', 'Susun kalimat diagnosis dua dimensi ''as much a matter of'' berikut:', '{"romaji":"/ˈskeɪlɪŋ ˌtɛləˈmɛdəsən ɪz æz mʌtʃ ə ˈmætər ʌv ˈklɪnɪkəl ˈwɜːrkˌfloʊ æz ʌv ˈbændˌwɪdθ/","tokens":["of clinical workflow","as of bandwidth.","Scaling telemedicine is","as much a matter","workflows clinical","than of"],"target_translation":"Memperluas layanan telemedisin sama besarnya merupakan persoalan alur kerja klinis sebagaimana lebar pita jaringan."}'::jsonb, '["Scaling telemedicine is","as much a matter","of clinical workflow","as of bandwidth."]'::jsonb, NULL, NULL, 'Pola ''as much a matter of [X] as of [Y]'' menyeimbangkan faktor manusia dan teknis.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000613', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'speaking', 'speaking_repeat', 'Ucapkan kalimat prinsip desain kebijakan berikut dengan ritme paralel yang mantap:', '{"romaji":"/ˈhɑːrdˌwɛr ˈsʌbsədiz səkˈsiːd ˈoʊnli wɛn dɪˈplɔɪd ɪn ˈtændəm wɪð ˈtiːtʃər ˈtreɪnɪŋ/","display_text":"Hardware subsidies succeed only when deployed in tandem with teacher training.","phonetic_breakdown":["Hardware subsidies succeed","only when deployed","in tandem with","teacher training."]}'::jsonb, '{"expected_transcript":"Hardware subsidies succeed only when deployed in tandem with teacher training."}'::jsonb, NULL, NULL, 'Pastikan klausa elipsis partisip ''when deployed'' mengalir langsung ke ''in tandem with''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000614', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Pilih penutup yang sejajar dalam kalimat perbandingan ''as ... as'' berikut:', '{"options":["with venture capital","to venture capital","as venture capital","than venture capital"],"translation":"Bagi pendiri bioteknologi tahap awal, kejelasan regulasi sama menentukan sepenuhnya seperti modal ventura.","sentence_template":"For early-stage biotech founders, regulatory clarity is every bit as decisive [blank]."}'::jsonb, '{"selected":"as venture capital"}'::jsonb, NULL, NULL, 'Penguat ''every bit as [Adjective]'' wajib ditutup dengan pasangan ''as [Noun Phrase]''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000615', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'listening', 'listening_choice', 'Dengarkan profesor sosiologi perkotaan merangkum dua penyebab gentrifikasi hijau. Bagaimana ia menyusun kalimat penutupnya?', '{"options":[{"id":"opt_1","text":"Kota harus memilih antara menanam pohon atau membangun perumahan terjangkau"},{"id":"opt_2","text":"Penyewa lama dilarang memanfaatkan taman kota yang baru dibangun"},{"id":"opt_3","text":"Penghijauan kota yang adil menuntut perluasan tajuk pohon sekaligus perlindungan penyewa lama dari lonjakan sewa spekulatif"},{"id":"opt_4","text":"Penanaman pohon di lingkungan padat selalu menurunkan harga sewa secara otomatis"}],"audio_text":"Ultimately, equitable urban greening requires both expanding tree canopy in heat-island neighborhoods and protecting long-term tenants from speculative rent spikes."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Korelatif paralel ''both + V-ing (expanding...) + and + V-ing (protecting...)'' merangkum tesis ganda dengan jernih.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000616', 'e5100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000049', 'writing', 'sentence_builder', 'Susun kalimat korelatif simetris untuk penutup paragraf TOEFL Writing:', '{"romaji":"/ˈlæstɪŋ rɪˈfɔːrm dɪˈmændz nɑːt ˈoʊnli ɪˈnæktɪŋ ˈstrɪktər lɔːz bʌt ˈɔːlsoʊ ˈfʌndɪŋ/","tokens":["also funded","stricter laws, but also","not only enacting","Lasting reform demands","funding local inspectors.","to fund"],"target_translation":"Reformasi yang bertahan lama menuntut bukan hanya pengesahan undang-undang yang lebih ketat, melainkan juga pendanaan inspektur daerah."}'::jsonb, '["Lasting reform demands","not only enacting","stricter laws, but also","funding local inspectors."]'::jsonb, NULL, NULL, 'Gerund ''enacting'' sesudah ''not only'' wajib disejajarkan dengan gerund ''funding'' sesudah ''but also''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000617', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Tentukan kata kerja yang selaras dengan subjek terbalik (*deferred subject*) pada fronting:', '{"options":["has","was","is","are"],"translation":"Tertanam di dalam lampiran perdagangan bilateral tersebut terdapat dua mekanisme arbitrase mengikat untuk layanan digital.","sentence_template":"Embedded within the bilateral trade annex [blank] two binding arbitration mechanisms for digital services."}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, 'Subjek sejati kalimat berada di belakang kata kerja (''two binding arbitration mechanisms'' = jamak), sehingga memakai ''are''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000618', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Pilih kata ganti penunjuk pembanding jamak yang tepat:', '{"options":["these in","that of","which of","those of"],"translation":"Standar bangunan tahan gempa Tokyo jauh lebih ketat dibandingkan standar milik kebanyakan megakota pesisir.","sentence_template":"The seismic building codes of Tokyo are considerably more stringent than [blank] most coastal megacities."}'::jsonb, '{"selected":"those of"}'::jsonb, NULL, NULL, 'Karena yang dibandingkan adalah ''The seismic building codes'' (jamak), wajib menggunakan ''those of''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000619', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'listening', 'listening_choice', 'Evaluasi Unit 9 — Dengarkan pembukaan laporan komite keselamatan penerbangan. Apa temuan utama yang dikedepankan pembicara?', '{"options":[{"id":"opt_1","text":"Seluruh maskapai sudah memakai satu sistem penomoran suku cadang terpadu"},{"id":"opt_2","text":"Penyidik menyimpulkan bahwa insiden murni disebabkan oleh cuaca ekstrem"},{"id":"opt_3","text":"Catatan pemeliharaan dari tiga subkontraktor regional memakai skema penomoran suku cadang yang tidak saling kompatibel"},{"id":"opt_4","text":"Tiga subkontraktor regional menolak menyerahkan catatan pemeliharaan kepada penyidik"}],"audio_text":"Particularly troubling to investigators was the discovery that maintenance logs from three regional subcontractors used incompatible part-numbering schemes."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Fronting ''Particularly troubling to X was [the discovery that...]'' menonjolkan bobot evaluasi atas temuan faktual.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000620', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'writing', 'sentence_builder', 'Evaluasi Unit 9 — Susun kalimat *predicate fronting* akademik berikut:', '{"romaji":"/ˈkruːʃəl tə vækˈsiːn ˈɛkwəti ɪz ˈkoʊld tʃeɪn ˈɪnfrəˌstrʌktʃər əˈkrɔːs ˈtrɑːpɪkəl/","tokens":["infrastructure across tropical","infrastructures tropical","are cold-chain","archipelagic provinces.","Crucial to vaccine","equity is cold-chain"],"target_translation":"Hal yang krusial bagi pemerataan vaksin adalah infrastruktur rantai dingin di seluruh provinsi kepulauan tropis."}'::jsonb, '["Crucial to vaccine","equity is cold-chain","infrastructure across tropical","archipelagic provinces."]'::jsonb, NULL, NULL, 'Subjek tunggal tak terhitung ''cold-chain infrastructure'' menentukan pemakaian ''is''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000621', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'speaking', 'speaking_repeat', 'Evaluasi Unit 9 — Ucapkan kalimat paralelisme pembanding berikut dengan jelas:', '{"romaji":"/pər ˈkæpɪtə ˈwɔːtər kənˈsʌmpʃən ɪn ˈdɛzərt rɪˈzɔːrts ɪkˈsiːdz ðæt ʌv ɪnˈdʌstriəl zoʊnz/","display_text":"Per-capita water consumption in desert resorts exceeds that of industrial zones.","phonetic_breakdown":["Per-capita water consumption","in desert resorts","exceeds that of","industrial zones."]}'::jsonb, '{"expected_transcript":"Per-capita water consumption in desert resorts exceeds that of industrial zones."}'::jsonb, NULL, NULL, 'Bedakan bunyi ''desert'' (gurun: /ˈdɛzərt/, tekanan awal) vs. ''dessert'' (hidangan penutup: /dɪˈzɜːrt/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000622', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Jaga paralelisme klausa sesudah ''not because ...'':', '{"options":["however because","and because of","but because","but due to"],"translation":"Program percontohan itu terhenti bukan karena warga desa menolak pompa tenaga surya, melainkan karena inverter cadangan membutuhkan enam bulan untuk diimpor.","sentence_template":"The pilot program stalled not because villagers resisted solar pumps, [blank] spare inverters took six months to import."}'::jsonb, '{"selected":"but because"}'::jsonb, NULL, NULL, '''Not because + [Clause]'' wajib disejajarkan dengan ''but because + [Clause]'', bukan frasa preposisi ''due to''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000623', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'listening', 'listening_choice', 'Evaluasi Unit 9 — Dengarkan penutup esai lisan peserta TOEFL Speaking (skor 29/30). Struktur retoris apa yang memperkuat kesimpulannya?', '{"options":[{"id":"opt_1","text":"Menyarankan penghapusan seluruh jalur kereta komuter di pusat kota"},{"id":"opt_2","text":"Menggabungkan kolokasi ''in tandem with'' dan paralelisme negatif ''neither fair nor effective'' untuk merangkum syarat keberhasilan kebijakan"},{"id":"opt_3","text":"Menyatakan bahwa kemacetan kota tidak mungkin diatasi oleh kebijakan publik"},{"id":"opt_4","text":"Mendukung pemberlakuan jalan berbayar tanpa menambah jadwal kereta komuter"}],"audio_text":"In short, congestion pricing succeeds only when paired in tandem with frequent commuter trains—punishing drivers without offering transit alternatives is neither fair nor effective."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perpaduan kohesi leksikal dan paralelisme korelatif memberikan penutup argumen lisan yang sangat meyakinkan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000624', 'e5100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000049', 'writing', 'sentence_builder', 'Evaluasi Unit 9 — Susun kalimat keseimbangan dua kepentingan berikut:', '{"romaji":"/ˈrɛɡjəˌleɪtərz mʌst straɪk ə ˈbæləns bɪˈtwiːn ækˈsɛləˌreɪtɪŋ drʌɡ əˈpruːvəlz ænd ˈseɪfˌɡɑːrdɪŋ/","tokens":["accelerating drug approvals","and safeguarding","a balance between","with safeguarding","to safeguard","patient safety.","Regulators must strike"],"target_translation":"Para regulator harus mencapai keseimbangan antara mempercepat persetujuan obat dan melindungi keselamatan pasien."}'::jsonb, '["Regulators must strike","a balance between","accelerating drug approvals","and safeguarding","patient safety."]'::jsonb, NULL, NULL, '''Between + V-ing + and + V-ing'' menjaga kesetaraan bentuk gramatikal.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000625', 'e5100001-0000-4000-8000-000000000078', NULL, 'reading', 'fill_blank', 'Pilih perangkat substitusi gerund formal untuk merujuk kembali ke tindakan kalimat sebelumnya:', '{"options":["doing so","doing them","so doing it","making so"],"translation":"Rumah sakit tersebut mendigitalkan formulir triase pada bulan Mei; melakukan hal itu memangkas waktu tunggu IGD sebesar dua puluh dua menit.","sentence_template":"The hospital digitized triage intake forms in May; [blank] shortened emergency room wait times by twenty-two minutes."}'::jsonb, '{"selected":"doing so"}'::jsonb, NULL, NULL, '''Doing so'' bertindak sebagai subjek gerund yang merangkum seluruh aksi ''digitizing triage intake forms''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000626', 'e5100001-0000-4000-8000-000000000078', NULL, 'reading', 'fill_blank', 'Pilih pasangan rujukan presisi untuk membedakan DUA opsi arsitektur yang baru disebutkan:', '{"options":["doing so","that former","the first one of all","the former"],"translation":"Tim menimbang penggelaran monolitik melawan mikroservis berbasis peristiwa: opsi pertama menyederhanakan penelusuran kutu awal, sedangkan opsi kedua menskalakan beban kerja secara mandiri.","sentence_template":"Teams weighed monolithic deployment against event-driven microservices: [blank] simplifies initial debugging, whereas the latter scales independent workloads."}'::jsonb, '{"selected":"the former"}'::jsonb, NULL, NULL, 'Berpasangan dengan ''the latter'' (opsi kedua), rujukan untuk opsi pertama dari dua pilihan adalah ''the former''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000627', 'e5100001-0000-4000-8000-000000000078', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah kebijakan moneter TOEFL. Apa yang terjadi sesudah Bank Sentral AS (the Fed) menaikkan suku bunga acuan?', '{"options":[{"id":"opt_1","text":"Bank sentral negara berkembang justru memangkas suku bunga hingga nol persen"},{"id":"opt_2","text":"Sejumlah bank sentral negara berkembang terpaksa ikut menaikkan suku bunga demi menjaga nilai tukar mata uang mereka"},{"id":"opt_3","text":"Seluruh perdagangan valuta asing dihentikan selama lima puluh hari"},{"id":"opt_4","text":"Mereka mengajukan gugatan hukum terhadap Bank Sentral AS"}],"audio_text":"Once the Federal Reserve hiked benchmark rates by fifty basis points, several emerging-market central banks had little choice but to follow suit to defend their currencies."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Idiom ''follow suit'' merangkum tindakan ''hike benchmark rates as well'' tanpa mengulang kata-katanya.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000628', 'e5100001-0000-4000-8000-000000000078', NULL, 'writing', 'sentence_builder', 'Susun kalimat klausul kepatuhan kontrak dengan substitusi ''fail to do so'':', '{"romaji":"/kənˈtræktərz mʌst rɪˈpɔːrt sʌb ˈprɑːsɛsər ˈtʃeɪndʒɪz wɪˈðɪn tɛn deɪz ðoʊz ˈfeɪlɪŋ tə duː soʊ/","tokens":["Contractors must report","sub-processor changes","face termination.","within ten days;","failing it","those failing to do so","do them"],"target_translation":"Kontraktor wajib melaporkan perubahan sub-pemroses dalam sepuluh hari; pihak yang lalai melakukannya menghadapi pemutusan kontrak."}'::jsonb, '["Contractors must report","sub-processor changes","within ten days;","those failing to do so","face termination."]'::jsonb, NULL, NULL, '''Failing to do so'' menggantikan ''failing to report sub-processor changes within ten days'' dengan sangat ringkas.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000629', 'e5100001-0000-4000-8000-000000000078', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat spesifikasi RFC teknis berikut dengan jeda titik koma yang jelas:', '{"romaji":"/tʃɛk ˈwɛðər ðə ˈpeɪˌloʊd ɪz saɪnd ɪf nɑːt rɪˈdʒɛkt ðə rɪˈkwɛst ɪˈmiːdiətli/","display_text":"Check whether the payload is signed; if not, reject the request immediately.","phonetic_breakdown":["Check whether","the payload is signed;","if not, reject","the request immediately."]}'::jsonb, '{"expected_transcript":"Check whether the payload is signed; if not, reject the request immediately."}'::jsonb, NULL, NULL, '''If not'' menggantikan klausa negatif penuh ''if the payload is not signed''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000630', 'e5100001-0000-4000-8000-000000000078', NULL, 'reading', 'fill_blank', 'Pilih kata ganti substitusi benda dapat dihitung jamak agar tidak mengulang kata ''sensors'':', '{"options":["doing so","those of","ones","one"],"translation":"Sensor tanah bertenaga baterai memerlukan kalibrasi tahunan, sedangkan sensor serat optik beroperasi bebas perawatan selama satu dekade.","sentence_template":"Battery-powered soil sensors require annual calibration, whereas fiber-optic [blank] operate maintenance-free for a decade."}'::jsonb, '{"selected":"ones"}'::jsonb, NULL, NULL, 'Setelah kata sifat deskriptif (''fiber-optic''), benda terhitung jamak (''sensors'') disubstitusi menggunakan ''ones'' (jangan gunakan ''ones'' untuk benda tak terhitung!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000631', 'e5100001-0000-4000-8000-000000000078', NULL, 'listening', 'listening_choice', 'Dengarkan tanya-jawab eksekutif soal ekspansi pusat data. Bagaimana CTO menjawab pertanyaan apakah perusahaan akan membangun reaktor nuklir sendiri?', '{"options":[{"id":"opt_1","text":"CTO menolak menggunakan energi bebas karbon untuk pusat data"},{"id":"opt_2","text":"Perusahaan akan menutup seluruh pusat datanya tahun depan"},{"id":"opt_3","text":"Perusahaan belum berencana membangun reaktor sendiri dalam waktu dekat, melainkan menandatangani perjanjian pembelian listrik jangka panjang"},{"id":"opt_4","text":"Perusahaan sudah mulai membangun tiga reaktor nuklir sendiri bulan ini"}],"audio_text":"Journalists keep asking whether we plan to build our own small modular reactors—while we have no immediate plans to do so, we''re signing long-term power purchase agreements."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Plans to do so'' merujuk mulus ke ''build our own small modular reactors''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000632', 'e5100001-0000-4000-8000-000000000078', NULL, 'writing', 'sentence_builder', 'Susun kalimat kontras ''the former ... the latter'' untuk esai akademik:', '{"romaji":"/wi kəmˈpɛrd ə ˈkɑːrbən tæks wɪð kæp ænd treɪd ðə ˈfɔːrmər ˌɡærənˈtiːz praɪs ˈsɜːrtənti/","tokens":["guarantees price certainty,","latter capping","We compared a","carbon tax with","the latter caps volume.","former guarantee","cap-and-trade: the former"],"target_translation":"Kami membandingkan pajak karbon dengan skema batas-dan-dagang: yang pertama menjamin kepastian harga, yang kedua membatasi volume emisi."}'::jsonb, '["We compared a","carbon tax with","cap-and-trade: the former","guarantees price certainty,","the latter caps volume."]'::jsonb, NULL, NULL, '''The former'' merujuk tunggal ke ''a carbon tax'' (''guarantees''), sedangkan ''the latter'' merujuk ke ''cap-and-trade'' (''caps'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000633', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Pilih bentuk yang bebas dari kesalahan *incompatible auxiliary ellipsis* (''has'' membutuhkan V3, ''will'' membutuhkan V1):', '{"options":["has championed, and will continuing,","has championed, and will continue to champion,","has, and will continue to, champion","have, and will, championed"],"translation":"Selama satu dekade terakhir, jaringan pembayaran Indonesia telah memperjuangkan, dan akan terus memperjuangkan, standar QR interoperal di jutaan pedagang mikro.","sentence_template":"Over the past decade, Indonesia''s payment network [blank] interoperable QR standards across millions of micro-merchants."}'::jsonb, '{"selected":"has championed, and will continue to champion,"}'::jsonb, NULL, NULL, 'Karena ''has'' membutuhkan V3 (''championed'') dan ''to'' membutuhkan V1 (''champion''), kata kerja pertama tidak boleh dihapus begitu saja.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000634', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Pilih sisipan elipsis pembatas yang tepat sesudah kata benda terhitung ''few'':', '{"options":["if ever","if any","doing so","if so"],"translation":"Sangat sedikit, kalaupun ada, komputer bingkai utama lawas yang sanggup memproses untaian emoji UTF-8 tanpa tambalan perantara khusus.","sentence_template":"Few, [blank], legacy mainframes can process UTF-8 emoji strings without custom middleware patches."}'::jsonb, '{"selected":"if any"}'::jsonb, NULL, NULL, '''Few, if any, + Plural Noun'' menekankan kelangkaan jumlah benda, sedangkan ''seldom, if ever,'' menekankan kelangkaan frekuensi waktu.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000635', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'listening', 'listening_choice', 'Dengarkan wawancara analis penerbangan tentang jadwal sertifikasi pesawat baru. Apa arti jawaban ''I''m afraid not''?', '{"options":[{"id":"opt_1","text":"Analis menyampaikan secara sopan bahwa pesawat tersebut kemungkinan besar tidak akan lulus sertifikasi sebelum pameran berlangsung"},{"id":"opt_2","text":"Pesawat tersebut sudah lulus sertifikasi FAA bulan lalu"},{"id":"opt_3","text":"Analis takut naik pesawat berbahan komposit tersebut"},{"id":"opt_4","text":"Pameran Dirgantara Paris dibatalkan tahun ini"}],"audio_text":"Will the composite airframe clear FAA certification before the Paris Air Show? Given the wing-load retesting, I''m afraid not."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''I''m afraid so'' (sayangnya ya) dan ''I''m afraid not'' (sayangnya tidak) adalah substitusi klausa sopan yang sangat lazim di dunia kerja.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000636', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'writing', 'sentence_builder', 'Susun kalimat *reduced infinitive* (''not to'') yang alami berikut:', '{"romaji":"/ˈsɛvrəl ˈkændɪˌdeɪts wɜːr ɪnˈvaɪtɪd tə əˈpiːl ðɛr skɔːrz jɛt moʊst ˈɑːptɪd nɑːt tuː/","tokens":["Several candidates were","opted to not","most opted not to.","not doing","their scores, yet","invited to appeal"],"target_translation":"Sejumlah kandidat diundang untuk mengajukan banding atas skor mereka, namun sebagian besar memilih untuk tidak melakukannya."}'::jsonb, '["Several candidates were","invited to appeal","their scores, yet","most opted not to."]'::jsonb, NULL, NULL, 'Urutan standar elipsis infinitif negatif adalah ''opted not to'' (menghentikan kalimat tepat pada partikel ''to'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000637', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'speaking', 'speaking_repeat', 'Ucapkan kalimat sisipan elipsis kata bantu sejenis berikut dengan tegas:', '{"romaji":"/ˈpʌblɪk ˌjuːnəˈvɜːrsətiz kæn ænd ɪnˈdiːd ʃʊd weɪv ˌæplɪˈkeɪʃən fiːz fɔːr ˈloʊ ˈɪnkʌm ˈskɑːlərz/","display_text":"Public universities can, and indeed should, waive application fees for low-income scholars.","phonetic_breakdown":["Public universities can,","and indeed should,","waive application fees","for low-income scholars."]}'::jsonb, '{"expected_transcript":"Public universities can, and indeed should, waive application fees for low-income scholars."}'::jsonb, NULL, NULL, 'Baik ''can'' maupun ''should'' diikuti V1 murni ''waive'', sehingga elipsis ini 100% gramatikal dan retoris.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000638', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Pilih sisipan elipsis frekuensi yang berpasangan alami dengan adverbia ''seldom'':', '{"options":["if not","the former","if any","if ever"],"translation":"Dalam epidemiologi tinjauan sejawat, satu studi observasional tunggal jarang sekali, kalaupun pernah, cukup untuk membuktikan hubungan sebab-akibat.","sentence_template":"In peer-reviewed epidemiology, a single observational study seldom, [blank], suffices to establish causation."}'::jsonb, '{"selected":"if ever"}'::jsonb, NULL, NULL, 'Adverbia frekuensi (''seldom / rarely'') berpasangan dengan ''if ever'' (= if it ever suffices at all).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000639', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'listening', 'listening_choice', 'Dengarkan percakapan dua peneliti pascadoktoral sebelum batas pengumpulan abstrak. Mengapa peneliti kedua menjawab ''I certainly hope not!''?', '{"options":[{"id":"opt_1","text":"Ia berharap tenggat waktu dipercepat agar bisa segera tidur"},{"id":"opt_2","text":"Ia memutuskan batal mengikuti konferensi tersebut"},{"id":"opt_3","text":"Ia sudah selesai mengirimkan makalahnya kemarin sore"},{"id":"opt_4","text":"Ia sangat berharap panitia TIDAK memajukan tenggat waktu ke UTC karena ia masih harus membuat dua grafik lagi"}],"audio_text":"Wait—did the conference committee move the submission deadline from midnight Pacific Time to UTC? I certainly hope not, because I still have two figures to plot!"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''I certainly hope not'' = ''I hope they did NOT move the deadline''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000640', 'e5100001-0000-4000-8000-000000000079', 'e2000001-0000-4000-8000-000000000050', 'writing', 'sentence_builder', 'Susun kalimat elipsis klausa konsesi tereduksi ''while + adjective'':', '{"romaji":"/waɪl ˌmæθəˈmætɪkli ˈɛləɡənt ðə prəˈpoʊzd ˈraʊtɪŋ hjʊˈrɪstɪk kənˈsuːmz ɪkˈsɛsɪv ɛdʒ ˈmɛməri/","tokens":["While mathematically elegant,","heuristic consumes","the proposed routing","excessive edge memory.","mathematically","While elegance"],"target_translation":"Meskipun elegan secara matematis, heuristik perutean yang diusulkan memakan memori tepi secara berlebihan."}'::jsonb, '["While mathematically elegant,","the proposed routing","heuristic consumes","excessive edge memory."]'::jsonb, NULL, NULL, 'Elipsis subjek + be (''While [it is] mathematically elegant, [it] consumes...'') sah karena subjek kedua klausa identik!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000641', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Pilih frasa transisi tujuan yang merujuk mulus pada target strategis kalimat sebelumnya:', '{"options":["if ever","to that end","the latter","vice versa"],"translation":"Konsorsium kami berupaya menghapus pembusukan penyimpanan dingin di pelabuhan kawasan timur; demi tujuan tersebut, kami menggelar mikro-sentra serpihan es tenaga surya.","sentence_template":"Our consortium seeks to eliminate cold-storage spoilage across eastern ports; [blank], we are deploying solar ice-flake micro-hubs."}'::jsonb, '{"selected":"to that end"}'::jsonb, NULL, NULL, '''To that end'' (= in order to achieve that previously stated goal) menjembatani sasaran dan aksi nyata.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000642', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Pilih ungkapan ringkas untuk menyatakan hubungan timbal balik dua arah:', '{"options":["if any","vice versa","doing so","former"],"translation":"Kurang tidur kronis memperparah peradangan metabolik, dan begitu pula sebaliknya, sehingga menciptakan siklus klinis yang saling menguatkan.","sentence_template":"Chronic sleep deprivation exacerbates metabolic inflammation, and [blank], creating a self-reinforcing clinical cycle."}'::jsonb, '{"selected":"vice versa"}'::jsonb, NULL, NULL, '''And vice versa'' menyatakan bahwa peradangan metabolik juga memperparah gangguan tidur tanpa perlu mengulang seluruh klausa.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000643', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'listening', 'listening_choice', 'Dengarkan cuplikan wawancara kandidat Fulbright bidang kesehatan masyarakat. Bagaimana ia merangkai paragraf rencana kontribusinya?', '{"options":[{"id":"opt_1","text":"Menyatakan kebutuhan nasional terlebih dahulu, lalu mengikat riset beasiswanya secara kohesif menggunakan ''to that end''"},{"id":"opt_2","text":"Mengulang kata ''standardized dengue genomic surveillance'' empat kali berturut-turut"},{"id":"opt_3","text":"Menolak kembali bekerja sama dengan laboratorium daerah sesudah lulus"},{"id":"opt_4","text":"Membahas topik wisata kuliner yang tidak berhubungan dengan kesehatan masyarakat"}],"audio_text":"Indonesia needs standardized dengue genomic surveillance across provincial labs; to that end, my fellowship research will adapt low-cost nanopore workflows for district hospitals."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pola ''National Need -> To that end, my research will...'' adalah cetak biru emas wawancara LPDP dan Fulbright.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000644', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'writing', 'sentence_builder', 'Susun kalimat kohesi dampak sekunder dengan ''In doing so,'':', '{"romaji":"/ði ˈɑːrkaɪv ˈdɪdʒəˌtaɪzd ˈfrædʒəl pɑːm liːf ˈmænjəˌskrɪpts ɪn ˈduːɪŋ soʊ ɪt ˈoʊpənd/","tokens":["opened centuries of","law to global scholars.","opened into","fragile palm-leaf manuscripts;","by so doing it","The archive digitized","in doing so, it"],"target_translation":"Arsip tersebut mendigitalkan naskah lontar yang rapuh; dalam prosesnya, langkah itu membuka berabad-abad literatur hukum bagi peneliti dunia."}'::jsonb, '["The archive digitized","fragile palm-leaf manuscripts;","in doing so, it","opened centuries of","law to global scholars."]'::jsonb, NULL, NULL, 'Lafalkan ''fragile'' ala AS /ˈfrædʒəl/ (bukan /ˈfrædʒaɪl/ Inggris) dan gunakan ''in doing so,'' untuk merangkai hasil.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000645', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kohesi penalaran berikut dengan artikulasi ''vice versa'' yang mantap:', '{"romaji":"/klɪr ˈɑːrkəˌtɛktʃər ˈsɪmpləˌfaɪz ˈɑːnˌbɔːrdɪŋ ænd ˈvaɪs ˈvɜːrsə ˈdɪsəplɪnd ˈɑːnˌbɔːrdɪŋ prɪˈzɜːrvz ˈɑːrkəˌtɛktʃər/","display_text":"Clear architecture simplifies onboarding, and vice versa, disciplined onboarding preserves architecture.","phonetic_breakdown":["Clear architecture","simplifies onboarding,","and vice versa,","disciplined onboarding preserves architecture."]}'::jsonb, '{"expected_transcript":"Clear architecture simplifies onboarding, and vice versa, disciplined onboarding preserves architecture."}'::jsonb, NULL, NULL, 'Jaga intonasi naik sedikit pada '', and vice versa,'' sebelum menutup kalimat dengan tegas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000646', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Pilih frasa anaforis untuk memperluas argumen ke skenario yang setara:', '{"options":["by the same logic","opted not to","if not","few if any"],"translation":"Kita tidak akan pernah memasang perangkat tegar pengereman yang belum diuji pada pesawat terbang; dengan penalaran yang sama, robot bedah otonom menuntut verifikasi formal.","sentence_template":"We would never deploy untested braking firmware in aircraft; [blank], autonomous surgical robots demand formal verification."}'::jsonb, '{"selected":"by the same logic"}'::jsonb, NULL, NULL, '''By the same logic'' mentransfer prinsip keselamatan dari satu domain ke domain sejajar.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000647', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'listening', 'listening_choice', 'Dengarkan umpan balik dosen penulisan akademik TOEFL terhadap esai yang mendapat nilai penuh. Mengapa paragrafnya terasa begitu mengalir?', '{"options":[{"id":"opt_1","text":"Menghapus seluruh tanda titik sehingga satu paragraf hanya berisi satu kalimat"},{"id":"opt_2","text":"Mengulang kalimat pembuka persis kata demi kata di kalimat terakhir"},{"id":"opt_3","text":"Mengganti tumpukan kata sambung mekanis dengan rujukan anaforis (''Such incentives'', ''In doing so'', ''If not'') yang menyatu dengan isi kalimat"},{"id":"opt_4","text":"Memulai setiap kalimat dengan kata ''Moreover'' dan ''Furthermore''"}],"audio_text":"Notice how she never starts three sentences in a row with mechanical transitions like ''Moreover''—instead, she links ideas through ''Such incentives,'' ''In doing so,'' and ''If not.''"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Inilah rahasia pembeda skor TOEFL Writing 25 vs. 29–30: kohesi referensial menggantikan penghubung hafalan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000648', 'e5100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000050', 'writing', 'sentence_builder', 'Susun kalimat rujukan ''the former ... the latter'' dengan kata kerja tunggal yang presisi:', '{"romaji":"/wi ɪˈvæljuˌeɪtɪd ˈsoʊlər ˈθɜːrməl ænd ˌfoʊtoʊvɑːlˈteɪɪks ðə ˈfɔːrmər stɔːrz hiːt ˈtʃiːpli/","tokens":["the former stores","store heat","the latter scales modularly.","heat cheaply, whereas","those latter","thermal and photovoltaics:","We evaluated solar"],"target_translation":"Kami mengevaluasi panas surya dan fotovoltaik: yang pertama menyimpan panas secara murah, sedangkan yang kedua terskala secara modular."}'::jsonb, '["We evaluated solar","thermal and photovoltaics:","the former stores","heat cheaply, whereas","the latter scales modularly."]'::jsonb, NULL, NULL, '''Solar thermal'' (tunggal) dirujuk oleh ''the former stores'', dan ''photovoltaics'' (sebagai satu bidang teknologi) dirujuk oleh ''the latter scales''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000649', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih perangkat substitusi verba untuk menghindari pengulangan klausa panjang:', '{"options":["did so","done them","made so","done so"],"translation":"Para regulator mendesak pemberi pinjaman regional melakukan uji ketahanan kredit properti komersial, dan sebagian besar bank papan atas telah melakukannya sebelum November.","sentence_template":"Regulators urged regional lenders to stress-test commercial real-estate loans, and most tier-one banks had already [blank] by November."}'::jsonb, '{"selected":"done so"}'::jsonb, NULL, NULL, 'Sesudah kata bantu Past Perfect ''had already'', gunakan bentuk V3 ''done so''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000650', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih sisipan elipsis konsesi yang tepat sesudah adverbia ''rarely'':', '{"options":["if ever","if any","doing so","the former"],"translation":"Migrasi sistem terdistribusi yang rumit jarang sekali, kalaupun pernah, rampung lebih cepat dari jadwal tanpa verifikasi tulis-ganda otomatis.","sentence_template":"Complex distributed migrations rarely, [blank], finish ahead of schedule without automated Dual-Write verification."}'::jsonb, '{"selected":"if ever"}'::jsonb, NULL, NULL, '''Rarely, if ever,'' adalah kolokasi elipsis baku untuk menekankan kelangkaan kejadian.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000651', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'listening', 'listening_choice', 'Evaluasi Unit 10 — Dengarkan petikan kuliah hukum kontrak bisnis AS. Apa konsekuensi jika penyewa TIDAK mengirimkan pemberitahuan tertulis 60 hari sebelumnya?', '{"options":[{"id":"opt_1","text":"Gedung perkantoran otomatis menjadi hak milik penyewa"},{"id":"opt_2","text":"Penyewa langsung mendapat potongan harga sewa sebesar enam puluh persen"},{"id":"opt_3","text":"Kontrak berakhir seketika tanpa kewajiban pembayaran apa pun"},{"id":"opt_4","text":"Perjanjian sewa komersial tersebut otomatis diperpanjang untuk masa dua belas bulan berikutnya"}],"audio_text":"Tenants may terminate the commercial lease early by serving sixty days'' written notice; if not, the agreement automatically renews for another twelve-month term."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Substitusi kondisi negatif ''if not'' (= if tenants do not serve 60 days'' written notice) mengikat klausul perpanjangan otomatis.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000652', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'writing', 'sentence_builder', 'Evaluasi Unit 10 — Susun kalimat tanpa cacat elipsis kata bantu berbeda tuntutan:', '{"romaji":"/ˈaʊər sɪˈkjʊrəti tiːm hæz ɪnˈfɔːrst ænd wɪl kənˈtɪnjuː tə ɪnˈfɔːrs ˈhɑːrdˌwɛr kiː/","tokens":["enforce, hardware-key MFA.","will continue to","Our security team","enforcing hardware","has enforced, and","has, and will,"],"target_translation":"Tim keamanan kami telah menegakkan, dan akan terus menegakkan, autentikasi multifaktor kunci perangkat keras."}'::jsonb, '["Our security team","has enforced, and","will continue to","enforce, hardware-key MFA."]'::jsonb, NULL, NULL, 'Menyebutkan ''enforced'' sesudah ''has'' dan ''enforce'' sesudah ''to'' menjaga ketepatan gramatikal C1.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000653', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'speaking', 'speaking_repeat', 'Evaluasi Unit 10 — Ucapkan kalimat transisi strategis berikut dengan lancar:', '{"romaji":"/wi eɪm tə dɪˈmɑːkrəˌtaɪz ˈbaɪoʊˌtɛk læbz tə ðæt ɛnd wi ˈoʊpən sɔːrst ˈaʊər paɪˈpɛtɪŋ ˈfɜːrmˌwɛr/","display_text":"We aim to democratize biotech labs; to that end, we open-sourced our pipetting firmware.","phonetic_breakdown":["We aim to","democratize biotech labs;","to that end,","we open-sourced our pipetting firmware."]}'::jsonb, '{"expected_transcript":"We aim to democratize biotech labs; to that end, we open-sourced our pipetting firmware."}'::jsonb, NULL, NULL, 'Beri penekanan jelas pada frasa penghubung tujuan ''; to that END,''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000654', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih respons klausa substitusi negatif yang idiomatis untuk kata kerja ''hope'':', '{"options":["hope no","are hoping none","hope not","don''t hope so"],"translation":"Ketika ditanya apakah kemacetan pelabuhan akan merembet hingga kuartal liburan, VP logistik menjawab, ''Kami tentu berharap tidak demikian.''","sentence_template":"When asked whether port congestion would spill over into the holiday quarter, the logistics VP answered, ''We certainly [blank].''"}'::jsonb, '{"selected":"hope not"}'::jsonb, NULL, NULL, 'Kata kerja ''hope'' wajib menggunakan substitusi negatif ''hope not'', bukan *''don''t hope so''*.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000655', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'listening', 'listening_choice', 'Evaluasi Unit 10 — Dengarkan analisis perbandingan dua protokol enkripsi kuantum. Mengapa pembicara memilih ''the latter'' untuk perangkat IoT kecil?', '{"options":[{"id":"opt_1","text":"Skema berbasis kisi (''the former'') tidak membutuhkan kunci publik sama sekali"},{"id":"opt_2","text":"Pembicara menyarankan menghapus enkripsi dari pembaruan perangkat tegar"},{"id":"opt_3","text":"Skema berbasis hash (''the latter'') mengandalkan asumsi keamanan minimal yang cocok bagi perangkat tegar berumur panjang"},{"id":"opt_4","text":"Kedua protokol tersebut sudah dilarang penggunaannya pada perangkat IoT"}],"audio_text":"Between lattice-based signatures and hash-based schemes, the former offers tiny public keys, whereas the latter relies on minimal security assumptions ideal for long-lived firmware."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Melacak rujukan ''the former'' (lattice-based) vs. ''the latter'' (hash-based) secara cepat saat menyimak kuliah teknis.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000656', 'e5100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000050', 'writing', 'sentence_builder', 'Evaluasi Unit 10 — Susun kalimat elipsis konsesi tereduksi berikut:', '{"romaji":"/ðoʊ ɪˈnɪʃəli ˈskɛptɪkəl ˈrʊrəl koʊˈɑːpərətɪvz əˈdɑːptɪd ˈsætəˌlaɪt sɔɪl ˈmɔɪstʃər əˈlɜːrts/","tokens":["Though initially skeptical,","alerts within months.","skeptical initially though","rural cooperatives adopted","satellite soil moisture","adopting alerts"],"target_translation":"Meskipun awalnya skeptis, koperasi-koperasi pedesaan mengadopsi peringatan kelembapan tanah satelit dalam hitungan bulan."}'::jsonb, '["Though initially skeptical,","rural cooperatives adopted","satellite soil moisture","alerts within months."]'::jsonb, NULL, NULL, 'Elipsis ''Though [they were] initially skeptical, rural cooperatives...'' ringkas dan bebas dari *dangling modifier*.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000657', 'e5100001-0000-4000-8000-000000000082', NULL, 'reading', 'fill_blank', 'Simulasi C1 [Reading 1/4] — Pilih susunan inversi negatif yang tepat sesudah ''Not until'':', '{"options":["was","did","had","they"],"translation":"Baru setelah para kriptografer independen mengaudit protokol pemungutan suara tersebut, muncul celah saluran samping waktu yang halus.","sentence_template":"Not until independent cryptographers audited the voting protocol [blank] subtle timing side-channels emerge."}'::jsonb, '{"selected":"did"}'::jsonb, NULL, NULL, 'Pada ''Not until [Time Clause] + Main Clause'', inversi terjadi di klausa UTAMA (''did ... emerge''), bukan di dalam klausa ''until''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000658', 'e5100001-0000-4000-8000-000000000082', NULL, 'reading', 'fill_blank', 'Simulasi C1 [Reading 2/4] — Pilih bentuk Mandative Subjunctive untuk rekomendasi resmi komite:', '{"options":["disclosed","discloses","disclose","to disclose"],"translation":"Panel bioetika merekomendasikan agar setiap vendor AI klinis mengungkapkan tingkat kesalahan demografis sebelum pengadaan rumah sakit.","sentence_template":"The bioethics panel recommended that every clinical AI vendor [blank] demographic error rates prior to hospital procurement."}'::jsonb, '{"selected":"disclose"}'::jsonb, NULL, NULL, '''Recommended that + Subject + bare infinitive (disclose)'' wajib tanpa akhiran ''-s'' pada American English.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000659', 'e5100001-0000-4000-8000-000000000082', NULL, 'reading', 'fill_blank', 'Simulasi C1 [Reading 3/4] — Uji keselarasan subjek terbalik (*fronting*) dan kata ganti pembanding:', '{"options":["are","were","have been","is"],"translation":"Inti dari kesimpulan studi tersebut adalah temuan bahwa penyimpanan karbon hutan bakau melampaui penyimpanan hutan hujan daratan.","sentence_template":"Central to the study''s conclusions [blank] the finding that mangrove carbon storage exceeds that of terrestrial rainforests."}'::jsonb, '{"selected":"is"}'::jsonb, NULL, NULL, 'Subjek sejati sesudah kata kerja adalah tunggal (''the finding''), bukan kata jamak ''conclusions''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000660', 'e5100001-0000-4000-8000-000000000082', NULL, 'reading', 'fill_blank', 'Simulasi C1 [Reading 4/4] — Pilih Past Subjunctive sesudah ''would rather'' dengan subjek kedua:', '{"options":["keep","kept","keeping","will keep"],"translation":"Mengingat pengendalian ekspor yang ketat, penasihat kepatuhan kami lebih memilih agar tim teknik menyimpan telemetri pelanggan di dalam cloud berdaulat regional.","sentence_template":"Given strict export controls, our compliance counsel would rather engineering teams [blank] customer telemetry inside regional sovereign clouds."}'::jsonb, '{"selected":"kept"}'::jsonb, NULL, NULL, '''Would rather + Subject 2 (engineering teams)'' untuk preferensi kebijakan kini/mendatang memakai bentuk lampau ''kept''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000661', 'e5100001-0000-4000-8000-000000000082', NULL, 'listening', 'listening_choice', 'Simulasi C1 [Listening 1/4] — Dengarkan kuliah epistemologi sains TOEFL tentang *confounding variables*. Mengapa kesimpulan studi kopi awal keliru?', '{"options":[{"id":"opt_1","text":"Biji kopi pada era 1960-an mengandung nikotin alami dalam jumlah tinggi"},{"id":"opt_2","text":"Perokok berat pada masa itu sama sekali tidak pernah meminum kopi"},{"id":"opt_3","text":"Studi awal mengabaikan variabel perancu besar bahwa peminum kopi berat pada era 1960-an sebagian besar juga perokok berat"},{"id":"opt_4","text":"Studi modern membuktikan kopi murni adalah satu-satunya penyebab penyakit jantung"}],"audio_text":"Early studies linking heavy coffee consumption to heart disease overlooked a massive confounder: back in the 1960s, heavy coffee drinkers were disproportionately heavy smokers!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Mengenali mekanisme ''confounding variable'' yang menggugurkan klaim kausalitas semu pada kuliah riset C1.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000662', 'e5100001-0000-4000-8000-000000000082', NULL, 'listening', 'listening_choice', 'Simulasi C1 [Listening 2/4] — Dengarkan respons CEO dalam sesi tanya-jawab krisis kebocoran vendor. Bagaimana ia menerapkan teknik *bridging*?', '{"options":[{"id":"opt_1","text":"Menyangkal adanya kebocoran data dan menyalahkan jurnalis atas rumor tersebut"},{"id":"opt_2","text":"Menolak berkomentar sampai tahun fiskal berikutnya berakhir"},{"id":"opt_3","text":"Menyatakan bahwa alamat surel pelanggan tidak penting untuk dilindungi"},{"id":"opt_4","text":"Mengakui insiden secara jujur sejak kalimat pertama lalu langsung mengarahkan fokus ke tindakan pencabutan akses dan audit forensik cepat"}],"audio_text":"Let me address the elephant in the room head-on: yes, an external billing vendor exposed hashed emails, and within two hours we revoked their API keys and engaged forensic auditors."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Komunikasi krisis eksekutif C1 menggabungkan transparansi cepat (''address the elephant in the room'') dengan bukti mitigasi terukur.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000663', 'e5100001-0000-4000-8000-000000000082', NULL, 'listening', 'listening_choice', 'Simulasi C1 [Listening 3/4] — Dengarkan wawancara kandidat beasiswa LPDP/Fulbright. Bagaimana kandidat menghubungkan pengalaman lampau dengan tujuan risetnya?', '{"options":[{"id":"opt_1","text":"Ia belum pernah terjun langsung ke proyek kelistrikan sebelum melamar beasiswa"},{"id":"opt_2","text":"Ia mengusulkan penambahan impor solar bersubsidi untuk seluruh klinik di Amerika Serikat"},{"id":"opt_3","text":"Ia ingin berpindah bidang sepenuhnya ke pemasaran ritel perkotaan"},{"id":"opt_4","text":"Berangkat dari pengalaman lapangan menangani kendala listrik klinik di Maluku, ia mengaitkan tesis masternya secara langsung untuk mengoptimalkan penyimpanan baterai pulau"}],"audio_text":"Having led rural microgrid deployments in Maluku, I saw firsthand how diesel logistics cripple clinic uptime; to that end, my master''s thesis will optimize sodium-ion storage for island grids."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Alur emas esai & wawancara beasiswa: bukti rekam jejak nyata (''Having led...'') + celah sistemik + ''to that end, my thesis will...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000664', 'e5100001-0000-4000-8000-000000000082', NULL, 'listening', 'listening_choice', 'Simulasi C1 [Listening 4/4] — Dengarkan umpan balik halus anggota dewan direksi AS tentang rencana akuisisi. Apa sikap sebenarnya dari pembicara?', '{"options":[{"id":"opt_1","text":"Memuji tim karena memiliki ruang kesalahan teknis yang sangat longgar"},{"id":"opt_2","text":"Memberikan dukungan bulat agar akuisisi dipercepat minggu depan juga"},{"id":"opt_3","text":"Menyampaikan keberatan serius secara diplomatis bahwa melakukan akuisisi dan migrasi platform secara bersamaan terlalu berisiko"},{"id":"opt_4","text":"Meminta perusahaan membatalkan migrasi platform secara permanen demi fokus mengakuisisi tiga perusahaan lagi"}],"audio_text":"Acquiring a European competitor right before our core platform migration is... certainly ambitious; I wonder whether digesting both simultaneously leaves sufficient margin for error."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Menangkap sinyal penolakan halus di balik *diplomatic understatement* (''certainly ambitious'' + ''I wonder whether...'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000665', 'e5100001-0000-4000-8000-000000000082', NULL, 'writing', 'sentence_builder', 'Simulasi C1 [Writing 1/4] — Susun kalimat inversi negatif pembuka esai TOEFL 110+:', '{"romaji":"/ˈrɛrli hæz ə ˌtɛknəˈlɑːdʒɪkəl ʃɪft trænsˈfɔːrmd ˌdaɪəɡˈnɑːstɪk ˌreɪdiˈɑːlədʒi æz ˈræpɪdli/","tokens":["Rarely a shift","Rarely has a","transforming as","diagnostic radiology as","rapidly as deep learning.","technological shift transformed"],"target_translation":"Jarang sekali sebuah pergeseran teknologi mengubah radiologi diagnostik secepat pembelajaran mendalam."}'::jsonb, '["Rarely has a","technological shift transformed","diagnostic radiology as","rapidly as deep learning."]'::jsonb, NULL, NULL, 'Adverbia negatif ''Rarely'' di awal kalimat memicu inversi kata bantu ''has + Subject + V3''.', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000666', 'e5100001-0000-4000-8000-000000000082', NULL, 'writing', 'sentence_builder', 'Simulasi C1 [Writing 2/4] — Susun kalimat pemadatan nominalisasi akademik berikut:', '{"romaji":"/ðə ˈræpɪd prəˌlɪfəˈreɪʃən ʌv sɪnˈθɛtɪk ˈmiːdiə nəˈsɛsəˌteɪts ˌkrɪptəˈɡræfɪk ˈprɑːvənəns ˈstændərdz/","tokens":["proliferating rapid","necessitate into","The rapid proliferation","of synthetic media","necessitates cryptographic provenance","standards across newsrooms."],"target_translation":"Pesatnya penyebaran media sintetis mengharuskan adanya standar asal-usul kriptografis di seluruh ruang redaksi."}'::jsonb, '["The rapid proliferation","of synthetic media","necessitates cryptographic provenance","standards across newsrooms."]'::jsonb, NULL, NULL, 'Nominalisasi subjek tunggal (''The rapid proliferation of...'') dipadukan verba formal ''necessitates''.', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000667', 'e5100001-0000-4000-8000-000000000082', NULL, 'writing', 'sentence_builder', 'Simulasi C1 [Writing 3/4] — Susun kalimat paralelisme perbandingan logis berikut:', '{"romaji":"/rɪˈtɛnʃən reɪts əˈmʌŋ ˈmɛntɔːrd ˈskɑːlərˌʃɪp ˈfɛloʊz kənˈsɪstəntli sərˈpæs ðoʊz ʌv/","tokens":["surpassing into","of non-mentored cohorts.","Retention rates among","consistently surpass those","that of","mentored scholarship fellows"],"target_translation":"Tingkat retensi di kalangan penerima beasiswa yang dibimbing secara konsisten melampaui tingkat retensi kelompok tanpa pembimbingan."}'::jsonb, '["Retention rates among","mentored scholarship fellows","consistently surpass those","of non-mentored cohorts."]'::jsonb, NULL, NULL, '''Retention rates'' (jamak) dirujuk secara paralel menggunakan ''those of''.', 11, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000668', 'e5100001-0000-4000-8000-000000000082', NULL, 'writing', 'sentence_builder', 'Simulasi C1 [Writing 4/4] — Susun kalimat kohesi substitusi & penekanan kata bantu:', '{"romaji":"/ˈsɪɡnəˌtɔːriz meɪ ˈɔːdɪt ˈsʌbkənˌtræktərz ˈænjuəli ænd ðoʊz ˈtʃuːzɪŋ tə duː soʊ mʌst ʃɛr/","tokens":["doing it","chose so","those choosing to do so","Signatories may audit","must share findings.","subcontractors annually, and"],"target_translation":"Para penanda tangan berhak mengaudit subkontraktor setiap tahun, dan pihak yang memilih melakukannya wajib membagikan temuan."}'::jsonb, '["Signatories may audit","subcontractors annually, and","those choosing to do so","must share findings."]'::jsonb, NULL, NULL, '''Choosing to do so'' menggantikan pengulangan seluruh predikat ''audit subcontractors annually''.', 12, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000669', 'e5100001-0000-4000-8000-000000000082', NULL, 'speaking', 'speaking_repeat', 'Simulasi C1 [Speaking 1/4] — Ucapkan kalimat inversi korelatif ''Not only ... but also'' berikut:', '{"romaji":"/nɑːt ˈoʊnli dɪd ðə ˈtraɪəl rɪˈduːs ˈhɑːspɪtəl steɪz bʌt ɪt ˈɔːlsoʊ hævd ˌriːədˈmɪʃən kɔːsts/","display_text":"Not only did the trial reduce hospital stays, but it also halved readmission costs.","phonetic_breakdown":["Not only did","the trial reduce","hospital stays, but","it also halved readmission costs."]}'::jsonb, '{"expected_transcript":"Not only did the trial reduce hospital stays, but it also halved readmission costs."}'::jsonb, NULL, NULL, 'Perhatikan inversi ''did the trial reduce'' di klausa pertama dan huruf ''l'' bisu pada ''halved'' (/hævd/).', 13, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000670', 'e5100001-0000-4000-8000-000000000082', NULL, 'speaking', 'speaking_repeat', 'Simulasi C1 [Speaking 2/4] — Ucapkan kalimat *hedging* ilmiah yang bernuansa berikut:', '{"romaji":"/prɪˈlɪməˌnɛri təˈlɛmətri səɡˈdʒɛsts ðæt ˌsʌbˈsɜːrfɪs ˈoʊʃən ˈwɔːrmɪŋ meɪ ækˈsɛləˌreɪt ˈɡleɪʃər ˈkævɪŋ/","display_text":"Preliminary telemetry suggests that subsurface ocean warming may accelerate glacier calving.","phonetic_breakdown":["Preliminary telemetry","suggests that subsurface","ocean warming may","accelerate glacier calving."]}'::jsonb, '{"expected_transcript":"Preliminary telemetry suggests that subsurface ocean warming may accelerate glacier calving."}'::jsonb, NULL, NULL, 'Huruf ''l'' pada ''calving'' (/ˈkævɪŋ/, pelepasan bongkahan es) juga bisu sebagaimana pada ''calf/half''!', 14, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000671', 'e5100001-0000-4000-8000-000000000082', NULL, 'speaking', 'speaking_repeat', 'Simulasi C1 [Speaking 3/4] — Ucapkan kalimat *fronting* kebijakan publik berikut:', '{"romaji":"/ˈkruːʃəl tə ˌɑːrkəˈpɛləɡoʊ ləˈdʒɪstɪks ɪz ˌɪntərˈɑːpərəbəl pɔːrt ˈskɛdʒuːlɪŋ əˈkrɔːs prəˈvɪnʃəl hʌbz/","display_text":"Crucial to archipelago logistics is interoperable port scheduling across provincial hubs.","phonetic_breakdown":["Crucial to","archipelago logistics is","interoperable port scheduling","across provincial hubs."]}'::jsonb, '{"expected_transcript":"Crucial to archipelago logistics is interoperable port scheduling across provincial hubs."}'::jsonb, NULL, NULL, 'Lafalkan ''schedule/scheduling'' ala AS dengan bunyi /sk/ (/ˈskɛdʒuːlɪŋ/), bukan /ʃ/.', 15, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000672', 'e5100001-0000-4000-8000-000000000082', NULL, 'speaking', 'speaking_repeat', 'Simulasi C1 [Speaking 4/4] — Ucapkan kalimat visi kepemimpinan beasiswa berikut:', '{"romaji":"/wʌt dɪˈstɪŋɡwɪʃɪz səˈsteɪnəbəl rɪˈfɔːrm ɪz ˌɪnstəˈtuːʃənəl əˌkaʊntəˈbɪləti ˈræðər ðæn ˈwʌn ɔːf ˈsʌbsədiz/","display_text":"What distinguishes sustainable reform is institutional accountability rather than one-off subsidies.","phonetic_breakdown":["What distinguishes","sustainable reform is","institutional accountability","rather than one-off subsidies."]}'::jsonb, '{"expected_transcript":"What distinguishes sustainable reform is institutional accountability rather than one-off subsidies."}'::jsonb, NULL, NULL, 'Tekankan kontras Wh-Cleft ''institutional ACCOUNTABILITY rather than one-off SUBSIDIES''.', 16, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000673', 'e5100001-0000-4000-8000-000000000083', NULL, 'reading', 'fill_blank', 'Pilih kata kerja bentuk dasar murni sesudah inversi kontingensi ''Should + subjek tunggal'':', '{"options":["to persist","persisted","persists","persist"],"translation":"Apabila inflasi bertahan di atas batas empat persen kuartal depan, komite siap mengetatkan kredit.","sentence_template":"Should inflation [blank] above the four-percent ceiling next quarter, the committee stands ready to tighten credit."}'::jsonb, '{"selected":"persist"}'::jsonb, NULL, NULL, 'Modal ''Should'' di awal pengandaian mewajibkan bare infinitive ''persist'' meskipun subjeknya tunggal (''inflation'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000674', 'e5100001-0000-4000-8000-000000000083', NULL, 'reading', 'fill_blank', 'Pilih susunan negatif formal yang sah dalam inversi pengandaian tanpa kontraksi:', '{"options":["Should not the shipment","Should the shipment not","If should the shipment not","Shouldn''t the shipment"],"translation":"Apabila kiriman tersebut tidak lolos bea cukai sebelum tengah malam, vaksin rantai dingin akan dialihkan ke gudang bandara.","sentence_template":"[blank] clear customs before midnight, cold-storage vaccines will be rerouted to the airport vault."}'::jsonb, '{"selected":"Should the shipment not"}'::jsonb, NULL, NULL, 'Dalam pengandaian terbalik, kata ''not'' diletakkan SESUDAH subjek (''Should the shipment not clear...''), tidak pernah disingkat ''Shouldn''t''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000675', 'e5100001-0000-4000-8000-000000000083', NULL, 'listening', 'listening_choice', 'Dengarkan arahan Chief Risk Officer perbankan kepada tim tresuri. Apa tindakan otomatis jika imbal hasil obligasi melonjak 40 basis poin?', '{"options":[{"id":"opt_1","text":"Membatalkan seluruh rencana kontingensi lindung nilai perusahaan"},{"id":"opt_2","text":"Menunggu pasar Asia tutup sebelum menghitung kerugian nilai tukar"},{"id":"opt_3","text":"Menjual seluruh cabang perbankan di kawasan Asia"},{"id":"opt_4","text":"Mengeksekusi lindung nilai mata uang lebih dulu secara antisipatif sebelum pasar Asia dibuka"}],"audio_text":"Should sovereign bond yields spike by forty basis points overnight, execute our currency hedge preemptively before Asian markets open."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Memadukan protokol ''Should [Event] spike..., execute... preemptively'' dalam instruksi eksekutif cepat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000676', 'e5100001-0000-4000-8000-000000000083', NULL, 'writing', 'sentence_builder', 'Susun kalimat klausul layanan pelanggan eksekutif dengan ''Should you'':', '{"romaji":"/ʃʊd juː rɪˈkwaɪər ˈɡrænjələr ˈɔːdɪt lɔːɡz pliːz ˈkɑːntækt ˈaʊər ˈdɛdɪˌkeɪtɪd kəmˈplaɪəns dɛsk/","tokens":["dedicated compliance desk.","granular audit logs,","Should you require","requires granular","please contact our","If should you"],"target_translation":"Apabila Anda memerlukan catatan audit terperinci, silakan hubungi meja kepatuhan khusus kami."}'::jsonb, '["Should you require","granular audit logs,","please contact our","dedicated compliance desk."]'::jsonb, NULL, NULL, 'Formula penutup surat eksekutif klasik AS: ''Should you require / have any questions, please...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000677', 'e5100001-0000-4000-8000-000000000083', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat analisis risiko rantai pasok berikut dengan penekanan tajam pada ''Should'':', '{"romaji":"/ʃʊd ə taɪˈfuːn kloʊz ˈkaʊʃjʊŋ pɔːrt ˈrɪpəl ɪˈfɛkts wʊd hɪt ˈɡloʊbəl ˈtʃɪpˌmeɪkərz/","display_text":"Should a typhoon close Kaohsiung port, ripple effects would hit global chipmakers.","phonetic_breakdown":["Should a typhoon","close Kaohsiung port,","ripple effects would","hit global chipmakers."]}'::jsonb, '{"expected_transcript":"Should a typhoon close Kaohsiung port, ripple effects would hit global chipmakers."}'::jsonb, NULL, NULL, 'Alirkan ''Should a typhoon close...'' dengan intonasi naik di akhir klausa syarat sebelum jeda koma.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000678', 'e5100001-0000-4000-8000-000000000083', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat untuk dampak berantai dari kegagalan satu pemasok inti:', '{"options":["benefit of the doubt","ripple effect","common ground","wiggle room"],"translation":"Berhentinya pemurnian neon di dua pabrik mengirimkan efek riak yang hebat ke pabrik litografi di seluruh dunia.","sentence_template":"Halting neon purification at two plants sent a severe [blank] across lithography fabs worldwide."}'::jsonb, '{"selected":"ripple effect"}'::jsonb, NULL, NULL, '''Send a ripple effect across...'' menggambarkan perambatan dampak sistemik.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000679', 'e5100001-0000-4000-8000-000000000083', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah ekologi laut TOEFL tentang terumbu karang laut dalam. Apa peringatan hipotesis dosen?', '{"options":[{"id":"opt_1","text":"Apabila kepulan sedimen tambang dasar laut menutupi karang laut dalam, pemulihannya bisa memakan waktu ribuan tahun"},{"id":"opt_2","text":"Karang laut dalam mampu pulih sempurna hanya dalam waktu dua dekade"},{"id":"opt_3","text":"Penambangan dasar laut tidak menghasilkan kepulan sedimen sama sekali"},{"id":"opt_4","text":"Karang laut dalam tumbuh lebih cepat daripada rumput laut permukaan"}],"audio_text":"Should seabed mining plumes smother these slow-growing deep corals, recovery wouldn''t take decades—it could take millennia."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Kontras skala waktu ''not decades—millennia'' yang dibuka oleh inversi pengandaian ''Should seabed mining plumes smother...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000680', 'e5100001-0000-4000-8000-000000000083', NULL, 'writing', 'sentence_builder', 'Susun kalimat rencana cadangan teknis (*contingency plan*) berikut:', '{"romaji":"/ʃʊd ˈpraɪˌmɛri ˈfaɪbər lɪŋks feɪl ˈsætəˌlaɪt ˈbækˌhɔːl ˈæktəˌveɪts ˌɔːtəˈmætɪkli wɪˈðɪn/","tokens":["links fail, satellite","activate satellite","Should primary fiber","failing links","within milliseconds.","backhaul activates automatically"],"target_translation":"Apabila tautan serat optik utama gagal, jalur cadangan satelit aktif secara otomatis dalam hitungan milidetik."}'::jsonb, '["Should primary fiber","links fail, satellite","backhaul activates automatically","within milliseconds."]'::jsonb, NULL, NULL, '''Should + Plural Subject + V1 (fail), Singular Subject + V-s (activates)''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000681', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Pilih struktur inversi Tipe 2 untuk kata kerja aksi hipotetis (''default''):', '{"options":["Were the borrower default","Were the borrower to default","If were the borrower defaulting","Was the borrower to default"],"translation":"Seandainya peminjam tersebut gagal bayar atas utang negaranya, pasar obligasi negara tetangga pasti menderita penularan seketika.","sentence_template":"[blank] on its sovereign debt, neighboring bond markets would suffer immediate contagion."}'::jsonb, '{"selected":"Were the borrower to default"}'::jsonb, NULL, NULL, 'Untuk kata kerja aksi pada inversi pengandaian Tipe 2, rumusnya wajib ''Were + Subject + to V1''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000682', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Pilih pembuka kontrafaktual masa lalu yang benar untuk kalimat berinduk ''would never have survived'':', '{"options":["Had it not been for","Hadn''t it been for","Were it not for","Should it not be for"],"translation":"Seandainya dulu bukan karena pembiayaan talangan darurat dari dana kekayaan negara, maskapai itu tidak akan pernah selamat dari penghentian terbang 2020.","sentence_template":"[blank] emergency bridge financing from sovereign funds, the airline would never have survived the 2020 grounding."}'::jsonb, '{"selected":"Had it not been for"}'::jsonb, NULL, NULL, 'Kejadian lampau (''2020'' + ''would never have survived'') menuntut Tipe 3 tanpa kontraksi: ''Had it not been for''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000683', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'listening', 'listening_choice', 'Dengarkan evaluasi retrospektif sejarawan ekonomi tentang krisis perbankan 1930-an. Apa argumen kontrafaktualnya?', '{"options":[{"id":"opt_1","text":"Bankir sentral berhasil mencegah Depresi Besar pada akhir tahun 1930"},{"id":"opt_2","text":"Seandainya bankir sentral menyuntikkan likuiditas pada akhir 1930, kepanikan lokal mungkin tidak akan membesar menjadi Depresi Besar"},{"id":"opt_3","text":"Depresi Besar hanya berlangsung selama dua minggu di pedesaan Amerika"},{"id":"opt_4","text":"Suntikan likuiditas pada tahun 1930 justru menjadi penyebab utama kebangkrutan bank"}],"audio_text":"Had central bankers injected liquidity into solvent community banks in late 1930, a localized panic might never have snowballed into the Great Depression."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Inversi Tipe 3 ''Had central bankers injected..., a panic might never have snowballed...'' menyajikan analisis sejarah tajam.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000684', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'writing', 'sentence_builder', 'Susun kalimat pengandaian terbalik masa kini ''Were it not for'':', '{"romaji":"/wɜːr ɪt nɑːt fɔːr ˌdʒiːoʊˈθɜːrməl ˈbeɪsˌloʊd ði ˈaɪlənd ɡrɪd wʊd rɪˈlaɪ ɪnˈtaɪərli/","tokens":["would rely entirely","would have relied","Were it not","on imported diesel.","Weren''t it","the island grid","for geothermal baseload,"],"target_translation":"Seandainya saat ini bukan karena beban dasar panas bumi, jaringan listrik pulau tersebut pasti bergantung sepenuhnya pada solar impor."}'::jsonb, '["Were it not","for geothermal baseload,","the island grid","would rely entirely","on imported diesel."]'::jsonb, NULL, NULL, 'Fakta masa kini menggunakan ''Were it not for [NP], S + would + V1''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000685', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'speaking', 'speaking_repeat', 'Ucapkan kalimat evaluasi pasca-insiden berstruktur ''Had we'' berikut:', '{"romaji":"/hæd wi ˈloʊd tɛstɪd ðə ˈfeɪlˌoʊvər ˈklʌstər ˈmʌndeɪz ˈaʊtɪdʒ kʊd həv bɪn əˈvɜːrtɪd/","display_text":"Had we load-tested the failover cluster, Monday''s outage could have been averted.","phonetic_breakdown":["Had we load-tested","the failover cluster,","Monday''s outage","could have been averted."]}'::jsonb, '{"expected_transcript":"Had we load-tested the failover cluster, Monday''s outage could have been averted."}'::jsonb, NULL, NULL, 'Sambungkan pelafalan lemah alami ''could have been'' menjadi /kʊdəv bɪn/ sebagaimana penutur asli AS.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000686', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Pilih bentuk inversi Tipe 2 keadaan (*stative ''be''*) tanpa ''to'':', '{"options":["Should land registries been","Were land registries","Had land registries","Were land registries to"],"translation":"Seandainya pencatatan tanah tidak begitu terpecah-pecah lintas yurisdiksi provinsi, perizinan energi terbarukan pasti memakan waktu berminggu-minggu alih-alih bertahun-tahun.","sentence_template":"[blank] less fragmented across provincial jurisdictions, renewable permitting would take weeks rather than years."}'::jsonb, '{"selected":"Were land registries"}'::jsonb, NULL, NULL, 'Ketika ''Were'' sendiri sudah menjadi kata kerja utama di depan frasa kata sifat (''less fragmented''), tidak perlu menambahkan ''to''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000687', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'listening', 'listening_choice', 'Dengarkan diskusi panel biosekuriti di universitas riset AS. Skenario hipotesis apa yang sedang diperingatkan pembicara?', '{"options":[{"id":"opt_1","text":"Seluruh penyedia sintesis gen dunia sudah diawasi secara wajib dan seragam"},{"id":"opt_2","text":"Penyaringan pesanan gen terbukti menghambat riset medis tanpa manfaat keamanan"},{"id":"opt_3","text":"Mesin sintesis gen meja sudah dilarang dijual kepada universitas riset"},{"id":"opt_4","text":"Seandainya penyaringan sintesis gen tetap bersifat sukarela semata, pelaku jahat dapat dengan mudah mencari penyedia tanpa pengawasan"}],"audio_text":"Were synthetic gene-synthesis screening to remain purely voluntary, bad actors could simply shop orders around until they found an unmonitored benchtop provider."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Were [Subject] to remain..., [Subject] could V1'' membingkai risiko kebijakan masa depan secara persuasif.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000688', 'e5100001-0000-4000-8000-000000000084', 'e2000001-0000-4000-8000-000000000051', 'writing', 'sentence_builder', 'Susun kalimat inversi kontrafaktual negatif (*non-contracted ''not''*) berikut:', '{"romaji":"/hæd ði ˈɔːdɪtərz nɑːt ˈkrɔːs tʃɛkt ˈkʌstəmz ˈmænəˌfɛsts ðə ˈfæntəm ˈɛkspɔːrts wʊd həv ɡɔːn/","tokens":["Had the auditors","went unnoticed","not cross-checked customs","gone unnoticed.","manifests, the phantom","Hadn''t the auditors","exports would have"],"target_translation":"Seandainya para auditor dulu tidak memeriksa silang manifes bea cukai, ekspor fiktif tersebut pasti lolos tanpa terdeteksi."}'::jsonb, '["Had the auditors","not cross-checked customs","manifests, the phantom","exports would have","gone unnoticed."]'::jsonb, NULL, NULL, 'Urutan baku negatif Tipe 3 terbalik: ''Had + Subject + not + V3''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000689', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Perhatikan kata keterangan ''today'' di akhir kalimat Mixed Inverted Conditional berikut:', '{"options":["had remained","would have remained","would remain","will remain"],"translation":"Seandainya pemerintah kota pesisir menegakkan zona penyangga bakau tiga puluh tahun silam, premi asuransi gelombang badai pasti tetap terjangkau hari ini.","sentence_template":"Had coastal municipalities enforced mangrove buffer zones thirty years ago, storm-surge insurance premiums [blank] sustainable today."}'::jsonb, '{"selected":"would remain"}'::jsonb, NULL, NULL, 'Sebab masa lalu terbalik (''Had ... enforced ... thirty years ago'') yang berdampak pada kondisi masa kini (''today'') memakai ''would + V1''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000690', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Pilih kata sifat C2 yang berarti ''tidak mungkin dipertahankan lagi'':', '{"options":["ostensible","paramount","laudable","untenable"],"translation":"Menyubsidi solar fosil sembari memajaki inverter surya menciptakan kontradiksi ekonomi yang mustahil dipertahankan.","sentence_template":"Subsidizing fossil diesel while taxing solar inverters creates an economically [blank] contradiction."}'::jsonb, '{"selected":"untenable"}'::jsonb, NULL, NULL, '''Untenable'' berarti tidak tahan dipertahankan di hadapan logika maupun kenyataan fiskal.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000691', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'listening', 'listening_choice', 'Dengarkan jawaban kandidat doktor kebijakan ekonomi saat diuji soal diversifikasi cadangan devisa. Bagaimana ia merangkai argumennya?', '{"options":[{"id":"opt_1","text":"Produsen dalam negeri disarankan menghentikan seluruh kegiatan ekspor"},{"id":"opt_2","text":"Kuota impor tidak pernah memengaruhi sektor manufaktur domestik"},{"id":"opt_3","text":"Mengandalkan satu mitra dagang tunggal adalah cara terbaik menghindari tarif"},{"id":"opt_4","text":"Diversifikasi pasar ekspor melindungi produsen dalam negeri sehingga jika satu mitra dagang besar memberlakukan kuota mendadak, koridor lain dapat menyerap surplus"}],"audio_text":"Diversifying export markets insulates domestic manufacturers from single-country tariff shocks; were a major trading partner to impose sudden quotas, alternative corridors could absorb the surplus."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'kombinasi ''insulates X from Y'' + ''; were [Subject] to impose..., [Subject] could absorb...'' sangat meyakinkan secara lisan.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000692', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'writing', 'sentence_builder', 'Susun kalimat rantai hipotesis lanjutan dengan ''Were that to transpire,'':', '{"romaji":"/ˈænəlɪsts wɔːrn ʌv ə streɪt blɑːˈkeɪd wɜːr ðæt tə trænˈspaɪər ˈɛlˈɛnˈdʒiː spɑːt ˈpraɪsɪz/","tokens":["transpired that","were that to transpire,","LNG spot prices","a strait blockade;","Analysts warn of","would have surged","would surge immediately."],"target_translation":"Para analis memperingatkan potensi blokade selat; seandainya hal itu terjadi, harga spot LNG akan langsung melonjak."}'::jsonb, '["Analysts warn of","a strait blockade;","were that to transpire,","LNG spot prices","would surge immediately."]'::jsonb, NULL, NULL, '''Were that to transpire,'' merujuk secara elegan ke skenario blokade di klausa sebelumnya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000693', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'speaking', 'speaking_repeat', 'Ucapkan kalimat Mixed Inverted Conditional berikut dengan ritme eksekutif yang tenang:', '{"romaji":"/hæd wi diːˈkʌpəld ˈaʊər ˈmɑːnəlɪθ ˈɜːrliər ˈriːdʒənəl dɪˈplɔɪmənts wʊd bi ˈɛfərtləs təˈdeɪ/","display_text":"Had we decoupled our monolith earlier, regional deployments would be effortless today.","phonetic_breakdown":["Had we decoupled","our monolith earlier,","regional deployments","would be effortless today."]}'::jsonb, '{"expected_transcript":"Had we decoupled our monolith earlier, regional deployments would be effortless today."}'::jsonb, NULL, NULL, 'Tekankan kontras waktu ''EARLIER'' di klausa pertama dan ''TODAY'' di penutup kalimat.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000694', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Pilih verba yang berpasangan tepat dengan preposisi ''from'' untuk arti ''melindungi dari guncangan'':', '{"options":["insulate","recede","purport","transpire"],"translation":"Obligasi hijau bersuku bunga tetap membantu melindungi otoritas transportasi tersebut dari lonjakan bunga jangka pendek yang bergejolak.","sentence_template":"Fixed-rate green bonds helped [blank] the transit authority from volatile short-term interest spikes."}'::jsonb, '{"selected":"insulate"}'::jsonb, NULL, NULL, '''Insulate [entity] from [volatility/shocks]'' adalah kolokasi baku manajemen keuangan dan kebijakan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000695', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'listening', 'listening_choice', 'Dengarkan kuliah ekonomi perkotaan TOEFL tentang *positive spillover effects*. Mengapa kehadiran universitas riset menguntungkan bengkel lokal di sekitarnya?', '{"options":[{"id":"opt_1","text":"Manfaat riset kampus hanya dirasakan oleh dosen yang menulis jurnal"},{"id":"opt_2","text":"Universitas riset membeli dan menutup seluruh bengkel mesin di sekitar kampus"},{"id":"opt_3","text":"Bengkel lokal menolak menerima pesanan pembuatan komponen dari mahasiswa"},{"id":"opt_4","text":"Bengkel mesin lokal di sekitar kampus ikut meningkatkan kepresisian peralatan mereka berkat pesanan purwarupa khusus dari laboratorium universitas"}],"audio_text":"Research universities generate powerful knowledge spillovers: even non-academic machine shops nearby upgrade precision tooling after fabricating custom prototypes for campus labs."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Memahami konsep ''knowledge spillovers'' (dampak limpahan pengetahuan positif lintas sektor).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000696', 'e5100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000051', 'writing', 'sentence_builder', 'Susun kalimat evaluasi kebijakan moneter C2 berikut:', '{"romaji":"/ʃʊd ˈkæpɪtəl flaɪt ækˈsɛləˌreɪt dɪˈfɛndɪŋ ən ˌoʊvərˈvæljuːd ˈkɜːrənsi pɛɡ ˈkwɪkli bɪˈkʌmz ʌnˈtɛnəbəl/","tokens":["untenably become","accelerates flight","accelerate, defending an","Should capital flight","overvalued currency peg","quickly becomes untenable."],"target_translation":"Apabila pelarian modal makin cepat, mempertahankan patokan mata uang yang terlalu mahal dengan cepat menjadi mustahil."}'::jsonb, '["Should capital flight","accelerate, defending an","overvalued currency peg","quickly becomes untenable."]'::jsonb, NULL, NULL, '''Should + S + V1 (accelerate), Gerund Subject (defending...) + becomes + Adjective (untenable)''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000697', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Pilih pembuka pengandaian Tipe 2 terbalik untuk kata kerja aksi ''collapse'':', '{"options":["Were the aquifer to collapse","Had the aquifer collapse","Should the aquifer collapsed","Were the aquifer collapse"],"translation":"Seandainya akuifer tersebut runtuh akibat intrusi air laut ke lensa air tawar, merelokasi setengah juta warga pesisir tidak akan terhindarkan.","sentence_template":"[blank] due to freshwater lens intrusion, relocating half a million coastal residents would be unavoidable."}'::jsonb, '{"selected":"Were the aquifer to collapse"}'::jsonb, NULL, NULL, 'Inversi pengandaian Tipe 2 pada kata kerja aksi wajib memakai pola ''Were + Subject + to + V1''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000698', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Perhatikan induk kalimat lampau ''would have triggered'' untuk memilih pembuka yang selaras:', '{"options":["Were it not for","Should it not be for","Had it not been for","Hadn''t it been for"],"translation":"Seandainya dulu bukan karena penghentian pemutus arus di bursa, kejatuhan kilat itu pasti telah memicu likuidasi margin beruntun.","sentence_template":"[blank] circuit-breaker halts on the exchange, the flash crash would have triggered cascading margin liquidations."}'::jsonb, '{"selected":"Had it not been for"}'::jsonb, NULL, NULL, 'Induk kalimat Tipe 3 (''would have triggered'') berpasangan dengan ''Had it not been for'' tanpa kontraksi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000699', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'listening', 'listening_choice', 'Evaluasi Unit 1 — Dengarkan klausul kontrak pengadaan satelit yang dibacakan penasihat hukum. Kapan denda keterlambatan mulai berlaku?', '{"options":[{"id":"opt_1","text":"Kontrak melarang adanya perhitungan ganti rugi harian dalam kondisi apa pun"},{"id":"opt_2","text":"Denda langsung dikenakan meskipun satelit berhasil mengorbit tepat waktu"},{"id":"opt_3","text":"Apabila penyedia peluncuran gagal mencapai penyisipan orbit dalam 90 hari sejak jendela target, ganti rugi terlikuidasi dihitung harian"},{"id":"opt_4","text":"Penyedia peluncuran dibebaskan dari segala denda hingga sembilan tahun ke depan"}],"audio_text":"Should the launch provider fail to achieve orbital insertion within ninety days of the target window, liquidated damages shall accrue daily."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Should [Provider] fail to..., liquidated damages shall accrue'' adalah bahasa hukum kontrak C2 yang sangat otentik.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000700', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'writing', 'sentence_builder', 'Evaluasi Unit 1 — Susun kalimat Mixed Inverted Conditional dengan penanda ''today'':', '{"romaji":"/hæd ˈrɛɡjəˌleɪtərz ˈmænˌdeɪtɪd ˈoʊpən ˈbæŋkɪŋ ˈeɪˈpiːˈaɪz ˈsuːnər ˈfɪnˌtɛk ˌkɑːmpəˈtɪʃən wʊd bi/","tokens":["sooner, fintech competition","Had regulators mandated","Hadn''t regulators","would have been","would be fiercer today.","open banking APIs"],"target_translation":"Seandainya para regulator mewajibkan API perbankan terbuka lebih awal, persaingan tekfin pasti lebih sengit hari ini."}'::jsonb, '["Had regulators mandated","open banking APIs","sooner, fintech competition","would be fiercer today."]'::jsonb, NULL, NULL, 'Sebab lampau (''Had regulators mandated ... sooner'') + hasil masa kini (''would be fiercer today'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000701', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'speaking', 'speaking_repeat', 'Evaluasi Unit 1 — Ucapkan kalimat pengandaian kontingensi formal negatif berikut:', '{"romaji":"/ʃʊd ðə ˈkwɔːrəm nɑːt bi mɛt ˈtuːzdeɪz ˈʃɛrˌhoʊldər voʊt wɪl bi əˈdʒɜːrnd/","display_text":"Should the quorum not be met, Tuesday''s shareholder vote will be adjourned.","phonetic_breakdown":["Should the quorum","not be met,","Tuesday''s shareholder vote","will be adjourned."]}'::jsonb, '{"expected_transcript":"Should the quorum not be met, Tuesday''s shareholder vote will be adjourned."}'::jsonb, NULL, NULL, 'Lafalkan ''adjourned'' /əˈdʒɜːrnd/ (ditunda sidangnya) dengan huruf ''d'' pertama menyatu dalam bunyi /dʒ/.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000702', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'reading', 'fill_blank', 'Evaluasi Unit 1 — Pilih kata kerja murni sesudah ''Should'' dengan subjek tunggal:', '{"options":["surface","surfaced","surfacing","surfaces"],"translation":"Apabila celah keamanan hari-nol muncul selama pembekuan rilis liburan, insinyur siaga berwenang melakukan pengembalian versi seketika.","sentence_template":"Should a zero-day exploit [blank] during the holiday freeze, on-call engineers have authority to roll back immediately."}'::jsonb, '{"selected":"surface"}'::jsonb, NULL, NULL, 'Subjek tunggal ''a zero-day exploit'' tetap diikuti V1 murni ''surface'' karena dikendalikan modal ''Should''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000703', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'listening', 'listening_choice', 'Evaluasi Unit 1 — Dengarkan analisis kebijakan fiskal tentang dana abadi komoditas (*sovereign wealth fund*). Mengapa Norwegia mampu meredam gejolak harga minyak?', '{"options":[{"id":"opt_1","text":"Aturan fiskal tersebut justru menghancurkan sektor manufaktur Norwegia"},{"id":"opt_2","text":"Berkat aturan fiskal ketat yang menyalurkan rezeki minyak ke dana abadi luar negeri, mata uang domestik Norwegia terhindar dari penyakit ekonomi komoditas"},{"id":"opt_3","text":"Norwegia menghabiskan seluruh pendapatan minyaknya langsung di anggaran tahunan"},{"id":"opt_4","text":"Dana abadi tersebut hanya boleh diinvestasikan pada tambang batu bara domestik"}],"audio_text":"Were it not for strict fiscal rules channeling oil windfalls into an offshore sovereign fund, Norway''s domestic currency would have suffered severe Dutch disease."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Memahami bagaimana ''Were it not for [ongoing institution]...'' menjelaskan ketahanan struktural jangka panjang.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000704', 'e5100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000051', 'writing', 'sentence_builder', 'Evaluasi Unit 1 — Susun kalimat inversi Tipe 2 untuk kata sifat predikatif:', '{"romaji":"/wɜːr ˈkwɑːntəm ˈɛrər kəˈrɛkʃən lɛs ɪkˈspɛnsɪv juːˈtɪləti skeɪl fɔːlt ˈtɑːlərənt məˈʃiːnz/","tokens":["utility-scale fault-tolerant","Were to be","exist.","machines would already","Were quantum error","would existed","correction less expensive,"],"target_translation":"Seandainya koreksi kesalahan kuantum tidak semahal sekarang, mesin toleran-kesalahan berskala utilitas pasti sudah ada."}'::jsonb, '["Were quantum error","correction less expensive,","utility-scale fault-tolerant","machines would already","exist."]'::jsonb, NULL, NULL, '''Were + Subject + Adjective Phrase (less expensive)'' tanpa ''to'' karena ''Were'' adalah kopula utamanya.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000705', 'e5100001-0000-4000-8000-000000000087', NULL, 'reading', 'fill_blank', 'Pilih konstruksi larangan pasif resmi untuk label kerahasiaan draf merjer:', '{"options":["is not to","not being to","does not to be","is not to be"],"translation":"Lembar ketentuan ini bersifat sangat rahasia dan dilarang keras digandakan atau dikutip tanpa persetujuan tertulis sebelumnya.","sentence_template":"This term sheet is strictly confidential and [blank] reproduced or quoted without prior written consent."}'::jsonb, '{"selected":"is not to be"}'::jsonb, NULL, NULL, 'Subjek benda pasif (''This term sheet'') membutuhkan struktur larangan pasif ''is not to be + V3 (reproduced)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000706', 'e5100001-0000-4000-8000-000000000087', NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman jadwal diplomatik resmi dengan konstruksi protokol C2:', '{"options":["are to convening","have to convened","are convening to","are to convene"],"translation":"Utusan dagang dari ASEAN dan Uni Eropa dijadwalkan bersidang di Brussel Selasa depan guna merampungkan aturan kepabeanan digital.","sentence_template":"Trade envoys from ASEAN and the European Union [blank] in Brussels next Tuesday to finalize digital customs rules."}'::jsonb, '{"selected":"are to convene"}'::jsonb, NULL, NULL, '''Are to + V1 (convene)'' adalah register standar diplomatik dan jurnalistik untuk agenda resmi yang telah ditetapkan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000707', 'e5100001-0000-4000-8000-000000000087', NULL, 'listening', 'listening_choice', 'Dengarkan pengarahan kepala laboratorium biosafety tingkat 3 kepada peneliti tamu. Apa aturan mutlak terkait sampel kultur?', '{"options":[{"id":"opt_1","text":"Aturan keselamatan federal bersifat sukarela bagi peneliti pascadoktoral"},{"id":"opt_2","text":"Kabinet bertekanan negatif hanya dinyalakan pada hari Jumat sore"},{"id":"opt_3","text":"Peneliti tamu diperbolehkan membawa kultur virus ke meja kerja biasa jika terburu-buru"},{"id":"opt_4","text":"Seluruh kultur virus wajib ditangani semata-mata di dalam kabinet bertekanan negatif sesuai ketat dengan aturan keselamatan hayati federal"}],"audio_text":"Let me be crystal clear on protocol: all viral cultures are to be handled exclusively inside negative-pressure cabinets in strict accordance with federal biosafety rules."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Are to be handled ... in strict accordance with...'' menegaskan mandat keselamatan nol-toleransi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000708', 'e5100001-0000-4000-8000-000000000087', NULL, 'writing', 'sentence_builder', 'Susun kalimat pengumuman berlakunya regulasi baru dengan ''is to take effect'':', '{"romaji":"/ðə rɪˈvaɪzd ˈkrɔːs ˈbɔːrdər ˈkɑːrbən ˈbɔːrdər əˈdʒʌstmənt ɪz tə teɪk ɪˈfɛkt ɑːn ɑːkˈtoʊbər fɜːrst/","tokens":["taking effect to","are to take","carbon border adjustment","is to take effect","on October first.","The revised cross-border"],"target_translation":"Penyesuaian perbatasan karbon lintas negara yang telah direvisi dijadwalkan mulai berlaku pada satu Oktober."}'::jsonb, '["The revised cross-border","carbon border adjustment","is to take effect","on October first."]'::jsonb, NULL, NULL, 'Subjek tunggal diikuti ''is to take effect'' menyatakan kepastian jadwal hukum.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000709', 'e5100001-0000-4000-8000-000000000087', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat mandat keamanan ruang server berikut dengan intonasi tegas:', '{"romaji":"/ɔːl kənˈtræktərz ɑːr tə səˈrɛndər ˈpɜːrsənəl ˈjuːˈɛsˈbiː draɪvz bɪˈfɔːr ˈɛntərɪŋ ðə vɔːlt/","display_text":"All contractors are to surrender personal USB drives before entering the vault.","phonetic_breakdown":["All contractors","are to surrender","personal USB drives","before entering the vault."]}'::jsonb, '{"expected_transcript":"All contractors are to surrender personal USB drives before entering the vault."}'::jsonb, NULL, NULL, 'Tekankan ''ARE to surrender'' untuk menyampaikan otoritas prosedur keamanan.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000710', 'e5100001-0000-4000-8000-000000000087', NULL, 'reading', 'fill_blank', 'Pilih frasa preposisi hukum untuk melengkapi klausul pelaksanaan audit:', '{"options":["at the heart of","for all","far from","in strict accordance with"],"translation":"Dana rekber wajib dicairkan sesuai secara ketat dengan jadwal verifikasi tonggak capaian pada Lampiran B.","sentence_template":"Escrow funds are to be disbursed [blank] the milestone verification schedule in Annex B."}'::jsonb, '{"selected":"in strict accordance with"}'::jsonb, NULL, NULL, '''In strict accordance with [rule/schedule]'' memastikan kepatuhan prosedural penuh.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000711', 'e5100001-0000-4000-8000-000000000087', NULL, 'listening', 'listening_choice', 'Dengarkan terjemahan makna tajuk utama berita ekonomi AS: ''Treasury to Auction Forty Billion in Ten-Year Notes''. Apa bentuk kalimat lengkap di balik judul singkat itu?', '{"options":[{"id":"opt_1","text":"Kementerian Keuangan AS dijadwalkan secara resmi akan melelang surat utang sepuluh tahun senilai empat puluh miliar dolar"},{"id":"opt_2","text":"Lelang tersebut baru sebatas rumor tak resmi di media sosial"},{"id":"opt_3","text":"Kementerian Keuangan sudah membatalkan lelang surat utang sepuluh tahun kemarin"},{"id":"opt_4","text":"Investor menolak membeli surat utang pemerintah Amerika Serikat"}],"audio_text":"When a Wall Street headline reads ''Treasury to Auction Forty Billion in Ten-Year Notes,'' it''s shorthand for ''The Treasury is scheduled to auction''—signaling an official upcoming event."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memahami elipsis ''be'' pada *headlinese* (''[is] to V1'' = dijadwalkan secara resmi untuk).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000712', 'e5100001-0000-4000-8000-000000000087', NULL, 'writing', 'sentence_builder', 'Susun kalimat instruksi tanggap insiden resmi berikut:', '{"romaji":"/prəˈdʌkʃən krɪˈdɛnʃəlz ɑːr ˈnɛvər tə bi ˈpeɪstɪd ˈɪntuː ˈpʌblɪk ˈdʒɛnərətɪv/","tokens":["generative AI prompts.","pasting into","never to be","never to paste","Production credentials are","pasted into public"],"target_translation":"Kredensial produksi dilarang keras ditempelkan ke dalam perintah AI generatif publik kapan pun."}'::jsonb, '["Production credentials are","never to be","pasted into public","generative AI prompts."]'::jsonb, NULL, NULL, 'Penegas ''are never to be + V3'' menetapkan garis merah keamanan organisasi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000713', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Pilih konstruksi syarat tujuan (*goal-prerequisite*) untuk membuka kalimat rekomendasi kebijakan:', '{"options":["will to phase out","are to phase out","are phasing to","to phase out"],"translation":"Jika negara-negara kepulauan memang ingin menghapus bertahap impor solar pada pertengahan abad, kabel arus searah tegangan tinggi antarpulau wajib dibiayai sekarang.","sentence_template":"If archipelagic nations [blank] diesel imports by mid-century, inter-island HVDC cables must be financed now."}'::jsonb, '{"selected":"are to phase out"}'::jsonb, NULL, NULL, '''If + Subject + are to + V1, [Main Clause] must...'' menetapkan prasyarat mutlak bagi suatu cita-cita besar.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000714', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Perhatikan klausa ''before volcanic ash grounded all flights''—rencana masa lalu tersebut BATAL terlaksana:', '{"options":["was never to be","were to","is to have","was to have"],"translation":"Delegasi iklim tersebut tadinya dijadwalkan mendarat di Reykjavik pada hari Kamis, sebelum abu vulkanik menghentikan seluruh penerbangan Atlantik Utara.","sentence_template":"The climate delegation [blank] landed in Reykjavik on Thursday, before volcanic ash grounded all North Atlantic flights."}'::jsonb, '{"selected":"was to have"}'::jsonb, NULL, NULL, '''Was to have + V3 (landed)'' secara spesifik menandai jadwal resmi masa lalu yang gagal terwujud.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000715', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'listening', 'listening_choice', 'Dengarkan cuplikan bacaan biografi sejarah sains TOEFL tentang Rosalind Franklin. Apa makna kalimat ''a prize she was never to share''?', '{"options":[{"id":"opt_1","text":"Ia membagi uang Hadiah Nobel tersebut kepada rekan laboratoriumnya pada 1962"},{"id":"opt_2","text":"Foto 51 terbukti tidak berkaitan dengan penemuan struktur heliks ganda DNA"},{"id":"opt_3","text":"Ia ditakdirkan tidak pernah ikut menerima Hadiah Nobel tersebut karena wafat lebih dulu pada tahun 1958"},{"id":"opt_4","text":"Ia menolak menerima Hadiah Nobel meskipun komite menawarkannya secara langsung"}],"audio_text":"In 1952 Franklin captured Photograph 51, providing crucial X-ray diffraction evidence of DNA''s double helix—a breakthrough that fueled a Nobel Prize she was never to share, owing to her untimely death in 1958."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Memahami ''was never to + V1'' sebagai penanda fakta sejarah masa depan (dilihat dari titik tahun 1952) yang tragis atau tak terelakkan.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000716', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'writing', 'sentence_builder', 'Susun kalimat prasyarat kebijakan pendidikan untuk esai TOEFL 120:', '{"romaji":"/ɪf voʊˈkeɪʃənəl skuːlz ɑːr tə brɪdʒ ði ˈeɪˈaɪ skɪlz ɡæp kəˈrɪkjələ mʌst ɪˈvɑːlv/","tokens":["is to bridge","the AI skills gap,","are to bridge","If vocational schools","bridging to","curricula must evolve","alongside industry."],"target_translation":"Jika sekolah kejuruan memang hendak menjembatani kesenjangan keterampilan AI, kurikulum wajib berkembang seiring industri."}'::jsonb, '["If vocational schools","are to bridge","the AI skills gap,","curricula must evolve","alongside industry."]'::jsonb, NULL, NULL, 'Ingat bentuk jamak ilmiah ''curricula'' (/kəˈrɪkjələ/, tunggal: ''curriculum'') dan pembuka ''If X are to V1''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000717', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'speaking', 'speaking_repeat', 'Ucapkan kalimat narasi sejarah teknologi berikut dengan irama bercerita yang jernih:', '{"romaji":"/wʌt bɪˈɡæn æz ən ˌækəˈdɛmɪk ˈpækɪt ˈnɛtˌwɜːrk wʌz suːn tə riːˈʃeɪp ˈɡloʊbəl ˈkɑːmɜːrs/","display_text":"What began as an academic packet network was soon to reshape global commerce.","phonetic_breakdown":["What began as","an academic packet network","was soon to reshape","global commerce."]}'::jsonb, '{"expected_transcript":"What began as an academic packet network was soon to reshape global commerce."}'::jsonb, NULL, NULL, '''Was soon to reshape'' menghubungkan titik awal sederhana dengan dampak sejarah raksasanya.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000718', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Pilih bentuk pasif untuk rencana masa lalu yang batal terlaksana (''batal diresmikan''):', '{"options":["is to been","were to have","was to be have","was to have been"],"translation":"Koridor Hidrogen lintas benua itu tadinya dijadwalkan akan diresmikan musim gugur lalu, sampai kelangkaan turbin memaksa penundaan dua tahun.","sentence_template":"The transcontinental Hydrogen Corridor [blank] inaugurated last autumn, until turbine shortages forced a two-year deferral."}'::jsonb, '{"selected":"was to have been"}'::jsonb, NULL, NULL, 'Bentuk pasif dari rencana batal ''was to have V3'' adalah ''was to have been + V3 (inaugurated)''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000719', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'listening', 'listening_choice', 'Dengarkan pidato rektor pada simposium riset semikonduktor. Apa prasyarat yang ia ajukan?', '{"options":[{"id":"opt_1","text":"Kampus sebaiknya berhenti meneliti cip berukuran di bawah sepuluh nanometer"},{"id":"opt_2","text":"Studio desain cip dalam negeri sudah menguasai pasar dua nanometer tanpa bantuan kampus"},{"id":"opt_3","text":"Agar studio desain cip dalam negeri mampu bersaing di batas dua nanometer, kampus dan pabrik pengecoran cip tidak boleh lagi berjalan sendiri-sendiri"},{"id":"opt_4","text":"Pabrik semikonduktor diminta menutup akses laboratorium bagi peneliti akademik"}],"audio_text":"If domestic chip design houses are to compete at the two-nanometer frontier, universities and foundries can no longer operate in separate silos."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''If [S] are to compete..., [S] can no longer...'' membangun urgensi kolaborasi strategis.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000720', 'e5100001-0000-4000-8000-000000000088', 'e2000001-0000-4000-8000-000000000052', 'writing', 'sentence_builder', 'Susun kalimat sejarah arsitektur dengan ''was to stand'':', '{"romaji":"/bɪlt æz ə ˈtɛmpəˌrɛri ˌɛksəˈbɪʃən ɑːrtʃ ði ˈaɪərn ˈtaʊər wʌz tə stænd fɔːr/","tokens":["the iron tower","were to stand","was to stand","for over a century.","Built as a","standing to","temporary exhibition arch,"],"target_translation":"Dibangun sebagai lengkungan pameran sementara, menara besi itu kelak berdiri tegak selama lebih dari satu abad."}'::jsonb, '["Built as a","temporary exhibition arch,","the iron tower","was to stand","for over a century."]'::jsonb, NULL, NULL, 'Kontras dramatis antara niat awal (''temporary'') dan kenyataan sejarah (''was to stand for over a century'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000721', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Pilih frasa kerja yang berarti ''mengantarkan dimulainya suatu babak sejarah baru'':', '{"options":["rule out","opt out of","usher in","air out"],"translation":"Kontainerisasi di Pelabuhan Newark pada 1956 kelak membuka gerbang bagi era perdagangan global yang super-efisien.","sentence_template":"Containerization at Port Newark in 1956 was to [blank] an era of hyper-efficient globalized trade."}'::jsonb, '{"selected":"usher in"}'::jsonb, NULL, NULL, '''Was to usher in [an era]'' adalah pasangan emas narasi sejarah ekonomi TOEFL.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000722', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Lengkapi kalimat syarat keberhasilan proyek jangka panjang berikut:', '{"options":["come to fruition","take at face value","contain the fallout","jump to conclusions"],"translation":"Jika strategi bioteknologi nasional kita ingin membuahkan hasil nyata, hibah awal wajib menjembatani lembah kematian antara meja lab dan uji klinis.","sentence_template":"If our national biotech strategy is to [blank], seed grants must bridge the valley of death between lab bench and clinical trials."}'::jsonb, '{"selected":"come to fruition"}'::jsonb, NULL, NULL, '''Come to fruition'' berarti terealisasi penuh sesudah melewati proses pematangan panjang.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000723', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'listening', 'listening_choice', 'Dengarkan kuliah sejarah kedokteran TOEFL tentang penemuan penisilin. Mengapa tahun 1941 disebut sebagai *watershed moment*?', '{"options":[{"id":"opt_1","text":"Fleming baru pertama kali melihat jamur penisilin di Peoria pada tahun 1941"},{"id":"opt_2","text":"Florey dan Chain membuktikan bahwa bakteri kebal terhadap segala jenis jamur"},{"id":"opt_3","text":"Produksi massal penisilin gagal total sehingga dihentikan pada tahun 1941"},{"id":"opt_4","text":"Tahun 1941 menjadi titik balik sejati ketika teknik fermentasi tangki dalam membuktikan bahwa antibiotik dapat diproduksi secara massal"}],"audio_text":"While Fleming noticed mold inhibiting bacteria in 1928, 1941 marked the true watershed moment when Florey and Chain scaled deep-tank fermentation in Peoria, proving antibiotics could be mass-produced."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Membedakan penemuan awal (1928) dari ''watershed moment'' industrialisasi massal (1941).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000724', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'writing', 'sentence_builder', 'Susun kalimat pembuka pidato reformasi kelembagaan berikut:', '{"romaji":"/bɪˈfɔːr ɪmˈbɑːrkɪŋ əˈpɑːn ˌkɑːnstəˈtuːʃənəl rɪˈfɔːrm ˈlɔːˌmeɪkərz ɑːr tə kənˈsʌlt ˈsɪvɪk/","tokens":["consulting to","civic assemblies nationwide.","Before embarking upon","are to consult","constitutional reform, lawmakers","embarked to"],"target_translation":"Sebelum memulai reformasi konstitusional besar, para pembuat undang-undang diwajibkan berkonsultasi dengan majelis warga di seluruh negeri."}'::jsonb, '["Before embarking upon","constitutional reform, lawmakers","are to consult","civic assemblies nationwide."]'::jsonb, NULL, NULL, 'Memadukan ''Before embarking upon [NP]'' dengan mandat prosedural ''are to consult''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000725', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'speaking', 'speaking_repeat', 'Ucapkan kalimat refleksi titik balik teknologi berikut dengan pelafalan ''fruition'' yang tepat:', '{"romaji":"/ˈdɛkeɪdz ʌv ˈɛmˈɑːrˈɛnˈeɪ rɪˈsɜːrtʃ keɪm tə fruˈɪʃən ˈdʊrɪŋ ə ˈɡloʊbəl ˈwɔːtərˌʃɛd ˈmoʊmənt/","display_text":"Decades of mRNA research came to fruition during a global watershed moment.","phonetic_breakdown":["Decades of mRNA research","came to fruition","during a global","watershed moment."]}'::jsonb, '{"expected_transcript":"Decades of mRNA research came to fruition during a global watershed moment."}'::jsonb, NULL, NULL, 'Pastikan tekanan ''fruition'' jatuh pada suku kata tengah /fruˈɪʃən/.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000726', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Pilih kata sifat/benda gabungan yang melukiskan peristiwa pemisah dua zaman:', '{"options":["confounding variable","ripple effect","watershed moment","common ground"],"translation":"Merilis model pelipatan protein berbobot terbuka merupakan momen titik balik bersejarah bagi laboratorium biologi struktural di negara berkembang.","sentence_template":"Releasing open-weights protein-folding models represented a [blank] for structural biology labs in developing nations."}'::jsonb, '{"selected":"watershed moment"}'::jsonb, NULL, NULL, '''Represent a watershed moment for [field]'' menandai perubahan paradigma permanen.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000727', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'listening', 'listening_choice', 'Dengarkan penutupan wawancara CEO energi terbarukan di radio bisnis AS. Apa pesan realistisnya?', '{"options":[{"id":"opt_1","text":"Jika baterai besi-udara ingin menggantikan pembangkit gas puncak pada 2032, antrean interkoneksi harus dirombak—dan tiga kawasan dijadwalkan memulai peninjauan jalur cepat bulan depan"},{"id":"opt_2","text":"Baterai besi-udara sudah menggantikan seluruh pembangkit gas tahun lalu"},{"id":"opt_3","text":"CEO menyarankan pembangunan pembangkit gas baru hingga tahun 2050"},{"id":"opt_4","text":"Tiga kawasan jaringan listrik menolak meninjau proyek baterai baru"}],"audio_text":"Look, if grid-scale iron-air batteries are to replace gas peaker plants by 2032, utilities must overhaul interconnection queues—and encouragingly, three ISO regions are to launch fast-track reviews next month."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Perhatikan dua fungsi ''be + to V1'' berdampingan: syarat tujuan (''if batteries are to replace'') dan jadwal resmi (''regions are to launch'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000728', 'e5100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000052', 'writing', 'sentence_builder', 'Susun kalimat sejarah pelayaran ilmiah dengan ''was never to'':', '{"romaji":"/ˈhævɪŋ dɪˈpɑːrtɪd ˈplɪməθ ɪn ˈɔːtəm ðə ˈwʊdən ˈsɜːrveɪ ˈvɛsəl wʌz ˈnɛvər tuː/","tokens":["wooden survey vessel","see home waters.","in autumn, the","departing to","was never seeing","Having departed Plymouth","was never to"],"target_translation":"Setelah bertolak dari Plymouth pada musim gugur, kapal survei kayu tersebut ditakdirkan tak pernah lagi melihat perairan kampung halamannya."}'::jsonb, '["Having departed Plymouth","in autumn, the","wooden survey vessel","was never to","see home waters."]'::jsonb, NULL, NULL, 'Partisip perfek pembuka berpadu dengan takdir historis ''was never to see''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000729', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Pilih bentuk larangan pasif resmi untuk spesimen forensik:', '{"options":["were never breaking","are not to be","do not to be","are not to"],"translation":"Segel rantai pengawasan pada kantong bukti digital dilarang dibuka kecuali di hadapan penasihat hukum pembela.","sentence_template":"Chain-of-custody seals on digital evidence bags [blank] broken except in the presence of defense counsel."}'::jsonb, '{"selected":"are not to be"}'::jsonb, NULL, NULL, 'Subjek pasif ''seals'' membutuhkan ''are not to be + V3 (broken)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000730', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Pilih bentuk rencana resmi masa lalu yang BATAL terjadi akibat gempa:', '{"options":["was to have","is to have","were to","was soon to"],"translation":"Jembatan layang kereta cepat itu tadinya dijadwalkan dibuka bagi penumpang pada bulan April, sebelum guncangan bulan Maret mengharuskan perkuatan struktur.","sentence_template":"The high-speed viaduct [blank] opened for passenger service in April, before March tremors prompted structural retrofits."}'::jsonb, '{"selected":"was to have"}'::jsonb, NULL, NULL, '''Was to have + V3 (opened)'' menandai agenda resmi masa lalu yang urung terlaksana.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000731', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'listening', 'listening_choice', 'Evaluasi Unit 2 — Dengarkan cuplikan kuliah sejarah diplomasi TOEFL tentang Liga Bangsa-Bangsa. Apa ironi sejarah yang disoroti dosen?', '{"options":[{"id":"opt_1","text":"Perjanjian Versailles baru ditandatangani sesudah Perang Dunia Kedua selesai"},{"id":"opt_2","text":"Woodrow Wilson menentang pembentukan Liga Bangsa-Bangsa sejak awal"},{"id":"opt_3","text":"Meskipun digagas oleh Presiden AS Woodrow Wilson, Senat AS sendiri pada akhirnya tidak pernah meratifikasi Perjanjian Versailles"},{"id":"opt_4","text":"Senat AS menjadi parlemen pertama di dunia yang meratifikasi perjanjian tersebut"}],"audio_text":"Woodrow Wilson championed the League of Nations as humanity''s safeguard against future wars, yet ironically, the United States Senate was never to ratify the Treaty of Versailles."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''The Senate was never to ratify...'' menggarisbawahi ironi fakta sejarah secara elegan.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000732', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'writing', 'sentence_builder', 'Evaluasi Unit 2 — Susun kalimat syarat tujuan strategis (''If ... are to'') berikut:', '{"romaji":"/ɪf ˈriːdʒənəl ˈhɑːspɪtəlz ɑːr tə rɪˈteɪn ˈspɛʃəlɪst ˈnɜːrsɪz ʃɪft ˈskɛdʒuːlz mʌst bɪˈkʌm/","tokens":["are to retain","predictable.","If regional hospitals","schedules must become","retaining to","is to retain","specialist nurses, shift"],"target_translation":"Jika rumah sakit daerah memang ingin mempertahankan perawat spesialis, jadwal giliran kerja wajib dibuat terprediksi."}'::jsonb, '["If regional hospitals","are to retain","specialist nurses, shift","schedules must become","predictable."]'::jsonb, NULL, NULL, '''If + Plural Subject + are to + V1, Main Clause + must...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000733', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'speaking', 'speaking_repeat', 'Evaluasi Unit 2 — Ucapkan kalimat narasi inovasi bersejarah berikut dengan mantap:', '{"romaji":"/ðæt ˈmɑːdəst ɡəˈrɑːʒ ˈproʊtəˌtaɪp wʌz suːn tə ˈʌʃər ɪn ˈpɜːrsənəl kəmˈpjuːtɪŋ/","display_text":"That modest garage prototype was soon to usher in personal computing.","phonetic_breakdown":["That modest","garage prototype","was soon to usher in","personal computing."]}'::jsonb, '{"expected_transcript":"That modest garage prototype was soon to usher in personal computing."}'::jsonb, NULL, NULL, 'Lafalkan ''garage'' ala Amerika /ɡəˈrɑːʒ/ (tekanan pada suku kata KEDUA, bukan pertama!).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000734', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'reading', 'fill_blank', 'Evaluasi Unit 2 — Pilih kolokasi C2 yang berarti ''mulai melaksanakan proyek reformasi besar'':', '{"options":["embark upon","cast doubt on","air out","recede from"],"translation":"Didukung sukuk hijau negara, kementerian perhubungan dijadwalkan memulai proyek elektrifikasi sepuluh tahun jalur kereta barang Jawa.","sentence_template":"Backed by sovereign green sukuk, the transport ministry is to [blank] a ten-year electrification of Java''s freight rail."}'::jsonb, '{"selected":"embark upon"}'::jsonb, NULL, NULL, '''Is to embark upon [a major undertaking]'' menyatukan jadwal resmi dengan skala proyek strategis.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000735', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'listening', 'listening_choice', 'Evaluasi Unit 2 — Dengarkan instruksi ketua panitia ujian lisensi medis. Apa konsekuensi membawa jam tangan pintar ke ruang ujian?', '{"options":[{"id":"opt_1","text":"Pengawas ujian hanya akan memberikan teguran lisan tanpa pembatalan ujian"},{"id":"opt_2","text":"Jam tangan pintar boleh dipakai asalkan disetel ke mode pesawat"},{"id":"opt_3","text":"Peserta wajib menyimpan seluruh gawai pakai di loker tersegel, dan siapa pun yang kedapatan mengenakannya di ruang ujian wajib langsung dikeluarkan"},{"id":"opt_4","text":"Loker penyimpanan baru dibuka setelah ujian berlangsung selama satu jam"}],"audio_text":"Candidates are to place all wearables in sealed lockers prior to check-in; anyone found wearing a smart device inside the hall is to be dismissed immediately."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Rangkaian aturan ganda ''are to place'' (kewajiban aktif) dan ''is to be dismissed'' (sanksi pasif).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000736', 'e5100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000052', 'writing', 'sentence_builder', 'Evaluasi Unit 2 — Susun kalimat realisasi riset panjang berikut:', '{"romaji":"/ˈæftər twɛlv jɪrz ʌv ˈklɪnɪkəl ˈtraɪəlz ðə məˈlɛriə vækˈsiːn ˈfaɪnəli keɪm tə fruˈɪʃən/","tokens":["the malaria vaccine","fruition.","After twelve years","finally came to","into fruitions","coming fruition","of clinical trials,"],"target_translation":"Setelah dua belas tahun uji klinis, vaksin malaria tersebut akhirnya membuahkan hasil nyata."}'::jsonb, '["After twelve years","of clinical trials,","the malaria vaccine","finally came to","fruition."]'::jsonb, NULL, NULL, 'Idiom ''come to fruition'' merangkum keberhasilan akhir riset multi-tahun.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000737', 'e5100001-0000-4000-8000-000000000091', NULL, 'reading', 'fill_blank', 'Pilih bentuk partisip absolut untuk menyatakan asumsi ilmiah *ceteris paribus* (tanpa *comma splice*!):', '{"options":["being held","hold","were holding","are held"],"translation":"Dengan seluruh variabel lain dijaga tetap konstan, menggandakan luas permukaan katalis akan menggandakan laju reaksi.","sentence_template":"All other variables [blank] constant, doubling catalyst surface area doubles the reaction rate."}'::jsonb, '{"selected":"being held"}'::jsonb, NULL, NULL, 'Klausa absolut TIDAK BOLEH memakai kata kerja finit ''are held'' tanpa konjungsi; gunakan partisip pasif ''being held'' (atau ''held'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000738', 'e5100001-0000-4000-8000-000000000091', NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman peluncuran roket cuaca sensitif menggunakan konstruksi absolut baku:', '{"options":["are permitting","permitted to","permit","permitting"],"translation":"Jika angin atmosfer atas mendukung, misi berbagi tumpangan orbit tersebut meluncur dari Vandenberg saat fajar.","sentence_template":"Upper-atmosphere winds [blank], the orbital rideshare mission lifts off from Vandenberg at dawn."}'::jsonb, '{"selected":"permitting"}'::jsonb, NULL, NULL, '''[Factor] permitting,'' (= if upper-atmosphere winds permit) adalah konstruksi absolut aktif yang ringkas.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000739', 'e5100001-0000-4000-8000-000000000091', NULL, 'listening', 'listening_choice', 'Dengarkan moderator menutup diskusi rapat kuartalan. Bagaimana ia menggunakan ''Time permitting'' dan ''That being said''?', '{"options":[{"id":"opt_1","text":"Menolak membahas biaya tepi meskipun waktu rapat masih tersisa satu jam"},{"id":"opt_2","text":"Meminta tim menghapus seluruh server tembolok karena sudah tidak ada biaya"},{"id":"opt_3","text":"Memuji perbaikan latensi terlebih dahulu, memberi catatan kenaikan biaya tepi (''that being said''), lalu mengajak membahas aturan tembolok jika waktu tersisa cukup"},{"id":"opt_4","text":"Menyatakan bahwa latensi memburuk di seluruh wilayah dan membatalkan sisa rapat"}],"audio_text":"Our latency metrics improved across every region this quarter; that being said, edge costs crept up, so—time permitting—let''s spend five minutes on caching rules."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Dua konstruksi absolut alami (''that being said'' + ''time permitting'') bekerja mulus mengatur alur rapat AS.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000740', 'e5100001-0000-4000-8000-000000000091', NULL, 'writing', 'sentence_builder', 'Susun kalimat kesimpulan evaluasi menyeluruh dengan ''All things considered,'':', '{"romaji":"/ɔːl θɪŋz kənˈsɪdərd ˈmaɪˌɡreɪtɪŋ tə ˈmænɪdʒd ˈpoʊstɡrɛsˌkjuːˈɛl rɪˈduːst ˌɑːpəˈreɪʃənəl tɔɪl/","tokens":["All things considering","migrating to managed","are considered","All things considered,","PostgreSQL reduced operational","toil substantially."],"target_translation":"Setelah menimbang seluruh faktor, bermigrasi ke PostgreSQL terkelola memangkas beban kerja operasional berulang secara substansial."}'::jsonb, '["All things considered,","migrating to managed","PostgreSQL reduced operational","toil substantially."]'::jsonb, NULL, NULL, '''All things'' dinilai oleh kita -> pasif ''considered'' (bukan aktif *''considering''*!).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000741', 'e5100001-0000-4000-8000-000000000091', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat prinsip ekonomi mikro berikut dengan jeda tegas setelah ''equal'':', '{"romaji":"/ˈʌðər θɪŋz ˈbiːɪŋ ˈiːkwəl ˈtærɪf haɪks reɪz ˈɪnˌpʊt kɔːsts fɔːr dəˈmɛstɪk əˈsɛmblərz/","display_text":"Other things being equal, tariff hikes raise input costs for domestic assemblers.","phonetic_breakdown":["Other things","being equal,","tariff hikes raise","input costs for domestic assemblers."]}'::jsonb, '{"expected_transcript":"Other things being equal, tariff hikes raise input costs for domestic assemblers."}'::jsonb, NULL, NULL, 'Pastikan ''being'' terdengar utuh (/ˈbiːɪŋ ˈiːkwəl/) untuk menghindari kesalahan tata bahasa *comma splice*.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000742', 'e5100001-0000-4000-8000-000000000091', NULL, 'reading', 'fill_blank', 'Pilih transisi absolut lisan/tulisan untuk mengakui argumen lawan sebelum mengajukan kualifikasi:', '{"options":["that being said","weather permitting","if ever","to that end"],"translation":"Model bahasa sumber terbuka menekan biaya inferensi secara drastis; meskipun demikian, perusahaan tetap bertanggung jawab secara hukum atas keluaran yang melanggar hak cipta.","sentence_template":"Open-source LLMs lower inference costs dramatically; [blank], enterprises remain liable for copyright-tainted outputs."}'::jsonb, '{"selected":"that being said"}'::jsonb, NULL, NULL, '''That being said'' (= having acknowledged that point, however) adalah penyeimbang argumen C1/C2.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000743', 'e5100001-0000-4000-8000-000000000091', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah demografi ekonomi TOEFL. Mengapa dosen menekankan frasa ''all else being equal'' sebelum memprediksi pertumbuhan PDB?', '{"options":[{"id":"opt_1","text":"Penuaan angkatan kerja hanya memperlambat PDB JIKA faktor lain diam; lonjakan otomasi dan partisipasi kerja perempuan dapat membalikkan tren tersebut"},{"id":"opt_2","text":"Penuaan penduduk pasti menurunkan PDB tanpa bisa diimbangi oleh teknologi apa pun"},{"id":"opt_3","text":"Partisipasi angkatan kerja tidak memengaruhi perhitungan output per kapita"},{"id":"opt_4","text":"Otomasi hanya bermanfaat di negara yang jumlah penduduk mudanya berlimpah"}],"audio_text":"Now, an aging workforce typically slows GDP growth—all else being equal. Yet if automation and female labor participation rise simultaneously, output per capita can still expand!"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menangkap fungsi ilmiah ''all else being equal'': mengisolasi satu variabel sembari mengingatkan bahwa di dunia nyata variabel lain ikut bergerak!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000744', 'e5100001-0000-4000-8000-000000000091', NULL, 'writing', 'sentence_builder', 'Susun kalimat jadwal sidang lapangan dengan ''Security clearance permitting,'':', '{"romaji":"/sɪˈkjʊrəti ˈklɪrəns pərˈmɪtɪŋ ˌɪndɪˈpɛndənt ˌɛndʒəˈnɪrz wɪl ɪnˈspɛkt ðə ˈsʌbˌsteɪʃən ˈriːleɪz/","tokens":["permits clearance","relays tomorrow morning.","independent engineers will","Security clearance permitting,","is permitting","inspect the substation"],"target_translation":"Jika izin keamanan mengizinkan, para insinyur independen akan memeriksa relai gardu induk besok pagi."}'::jsonb, '["Security clearance permitting,","independent engineers will","inspect the substation","relays tomorrow morning."]'::jsonb, NULL, NULL, 'Pola produktif ''[Noun] permitting,'' menghemat klausa syarat penuh secara elegan.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000745', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Hindari kesalahan *comma splice*! Pilih bentuk klausa absolut pasif yang benar sebelum koma:', '{"options":["With consensus re-establish","Re-establishing consensus","Consensus was re-established","Consensus re-established"],"translation":"Begitu konsensus berhasil dipulihkan di seluruh dua belas simpul, gugus basis data kembali menerima transaksi tulis.","sentence_template":"[blank] across all twelve nodes, the database cluster resumed accepting write transactions."}'::jsonb, '{"selected":"Consensus re-established"}'::jsonb, NULL, NULL, '''Consensus was re-established, the cluster resumed...'' akan salah karena dua kata kerja finit hanya dipisah koma; buang ''was'' menjadi klausa absolut ''Consensus re-established,''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000746', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Pilih partisip aktif sesudah struktur absolut ''With + Noun Phrase'' untuk proses yang sedang melonjak:', '{"options":["was filling","filled","fills","filling"],"translation":"Seiring air lelehan gletser mengisi waduk Pegunungan Alpen dengan kecepatan rekor, operator PLTA membuka pintu pelimpah lebih awal.","sentence_template":"With glacial meltwater [blank] Alpine reservoirs at record speed, hydro operators opened spillway gates early."}'::jsonb, '{"selected":"filling"}'::jsonb, NULL, NULL, 'Karena ''meltwater'' secara aktif mengisi waduk (''fills''), bentuk absolutnya adalah ''With + NP + V-ing (filling)''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000747', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'listening', 'listening_choice', 'Dengarkan narasi eksplorasi planet Mars pada kuliah astronomi TOEFL. Mengapa penjelajah (*rover*) akhirnya membisu?', '{"options":[{"id":"opt_1","text":"Badai angin justru membersihkan panel surya sehingga dayanya berlebih"},{"id":"opt_2","text":"Teknisi di Bumi sengaja mematikan pemancar radio penjelajah untuk menghemat anggaran"},{"id":"opt_3","text":"Roda penjelajah patah saat menuruni kawah curam pada tahun 2018"},{"id":"opt_4","text":"Panel suryanya tertutup rapat debu halus oksida besi seusai badai global sehingga tidak sanggup lagi mengisi daya pemanasnya"}],"audio_text":"Its solar panels blanketed in fine iron-oxide dust after a planet-encircling storm, the Opportunity rover could no longer trickle-charge its heaters and fell silent in 2018."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Klausa absolut ''Its solar panels blanketed in ... dust, the rover could no longer...'' merangkum sebab fisik secara sinematik dan presisi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000748', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'writing', 'sentence_builder', 'Susun kalimat konstruksi absolut kausal untuk laporan keuangan eksekutif:', '{"romaji":"/wɪð dɛt ˈkʌvənənts ˈsætɪsˌfaɪd əˈhɛd ʌv ˈskɛdʒuːl ðə juːˈtɪləti ʌnˈlɑːkt ˈloʊər/","tokens":["satisfying covenants","unlocked lower borrowing","schedule, the utility","With debt covenants","satisfied ahead of","were satisfied","spreads."],"target_translation":"Karena klausul perjanjian utang telah dipenuhi lebih cepat dari jadwal, perusahaan utilitas tersebut berhasil membuka selisih bunga pinjaman yang lebih rendah."}'::jsonb, '["With debt covenants","satisfied ahead of","schedule, the utility","unlocked lower borrowing","spreads."]'::jsonb, NULL, NULL, '''With + debt covenants + V3 (satisfied)'' memadatkan sebab keberhasilan finansial.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000749', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'speaking', 'speaking_repeat', 'Ucapkan kalimat klausa absolut tanpa kata kerja bantu berikut dengan intonasi naratif:', '{"romaji":"/ðə ˈsiːsˌfaɪər saɪnd æt ˈmɪdˌnaɪt hjuːˌmænəˈtɛriən ˈkɑːnvɔɪz krɔːst ðə brɪdʒ æt dɔːn/","display_text":"The ceasefire signed at midnight, humanitarian convoys crossed the bridge at dawn.","phonetic_breakdown":["The ceasefire","signed at midnight,","humanitarian convoys","crossed the bridge at dawn."]}'::jsonb, '{"expected_transcript":"The ceasefire signed at midnight, humanitarian convoys crossed the bridge at dawn."}'::jsonb, NULL, NULL, 'Beri jeda sesaat setelah ''midnight,'' agar pendengar menangkap peralihan dari klausa absolut ke subjek utama.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000750', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Pilih bentuk absolut perfek aktif untuk kata kerja intransitif (''recede'' = surut sendiri, tidak bisa dipasifkan):', '{"options":["were receded","having been receded","having receded","receded by"],"translation":"Setelah air banjir surut dari kawasan industri tersebut, perusahaan asuransi menerjunkan tim drone untuk memetakan kerusakan atap.","sentence_template":"The floodwaters [blank] from the industrial park, insurers dispatched drone teams to map roof damage."}'::jsonb, '{"selected":"having receded"}'::jsonb, NULL, NULL, 'Verba intransitif seperti ''recede, expire, subside'' tidak memiliki bentuk pasif V3; gunakan partisip perfek aktif ''having receded''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000751', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'listening', 'listening_choice', 'Dengarkan penjelasan dosen penulisan ilmiah tentang cara memperbaiki *dangling modifier*. Mengapa versi kedua benar?', '{"options":[{"id":"opt_1","text":"Menambahkan subjek mandiri (''Its yolk sac'') mengubah partisip menggantung yang konyol menjadi konstruksi absolut yang jernih dan logis"},{"id":"opt_2","text":"Kedua kalimat tersebut sama-sama salah karena tidak memakai kata ''because''"},{"id":"opt_3","text":"Kalimat pertama sudah benar karena peneliti memang memiliki kantung kuning telur"},{"id":"opt_4","text":"Konstruksi absolut dilarang dipakai di dalam artikel jurnal biologi"}],"audio_text":"If you write ''Having depleted its yolk sac, researchers fed the larvae,'' you''re implying the scientists had yolk sacs! Write ''Its yolk sac depleted, the larva began active feeding.''"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memahami persis mengapa konstruksi absolut menjadi solusi elegan saat subjek anak kalimat dan induk kalimat berbeda.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000752', 'e5100001-0000-4000-8000-000000000092', 'e2000001-0000-4000-8000-000000000053', 'writing', 'sentence_builder', 'Susun kalimat konstruksi absolut berpredikat frasa preposisi (*verbless absolute*):', '{"romaji":"/iːtʃ ˈsæmpəl ˈvaɪəl ɪn ɪts ˈbɑːrˌkoʊdɪd slɑːt ðə roʊˈbɑːtɪk ˈsɛntrəˌfjuːdʒ ɪˈnɪʃiˌeɪtɪd/","tokens":["was in","high-speed spin.","in its barcoded","initiating spin","slot, the robotic","centrifuge initiated","Each sample vial"],"target_translation":"Setelah setiap botol sampel berada di slot berkode batangnya masing-masing, sentrifus robotik memulai putaran kecepatan tinggi."}'::jsonb, '["Each sample vial","in its barcoded","slot, the robotic","centrifuge initiated","high-speed spin."]'::jsonb, NULL, NULL, 'Klausa absolut bahkan dapat melesapkan ''being'' di depan frasa lokasi (''Each vial [being] in its slot, ...'')!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000753', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Pilih konstruksi absolut penutup kalimat untuk memerinci pembagian porsi dua komponen tanpa *comma splice*:', '{"options":["which Sumatra accounting","with Sumatra accounts","with Sumatra accounting for","Sumatra accounts for"],"translation":"Jalur proyek panas bumi Indonesia membentang di dua belas provinsi, dengan Sumatera menyumbang hampir separuh megawatt yang direncanakan.","sentence_template":"Indonesia''s geothermal pipeline spans twelve provinces, [blank] nearly half of planned megawatts."}'::jsonb, '{"selected":"with Sumatra accounting for"}'::jsonb, NULL, NULL, 'Di akhir kalimat utuh setelah koma, gunakan ''with + NP + V-ing (accounting for)'', bukan kalimat finit lepas ''Sumatra accounts for''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000754', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Pilih kata kerja intransitif C2 yang menggambarkan menipisnya cadangan bijih kadar tinggi:', '{"options":["embarking","ushering","dwindling","complying"],"translation":"Seiring cadangan tembaga kadar tinggi makin menipis di tambang-tambang tua Andes, perusahaan tambang beralih ke pencucian hayati.","sentence_template":"With high-grade copper deposits [blank] in aging Andean pits, miners are turning to bioleaching."}'::jsonb, '{"selected":"dwindling"}'::jsonb, NULL, NULL, '''Dwindling'' melukiskan penyusutan kuantitas cadangan secara bertahap.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000755', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'listening', 'listening_choice', 'Dengarkan kuliah geologi sejarah TOEFL tentang Zaman Kambrium. Bagaimana naiknya kadar oksigen laut memicu ''Cambrian Explosion''?', '{"options":[{"id":"opt_1","text":"Stabilnya oksigen laut dangkal di atas ambang metabolik memungkinkan hewan awal membentuk otot dan cangkang, menyiapkan panggung bagi ledakan evolusi Kambrium"},{"id":"opt_2","text":"Turunnya kadar oksigen laut memusnahkan seluruh hewan bercangkang pada Zaman Kambrium"},{"id":"opt_3","text":"Otot dan cangkang sama sekali tidak membutuhkan energi metabolik oksigen"},{"id":"opt_4","text":"Hewan bercangkang muncul jutaan tahun sebelum oksigen ada di lautan"}],"audio_text":"Shallow marine oxygen levels having stabilized above a critical metabolic threshold, early bilaterian animals could finally build energy-hungry muscles and shells—setting the stage for the Cambrian evolutionary radiation."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Perhatikan pembuka absolut perfek ''Oxygen levels having stabilized..., animals could build...'' diikuti penutup '', setting the stage for...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000756', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'writing', 'sentence_builder', 'Susun kalimat rincian arsitektur menggunakan absolut penutup '', each + V3'':', '{"romaji":"/ðə ˈsætəˌlaɪt ˌkɑːnstəˈleɪʃən ˈɑːpəˌreɪts əˈkrɔːs sɪks ˈɔːrbɪtəl pleɪnz iːtʃ speɪst ˈsɪksti/","tokens":["The satellite constellation","operates across six","orbital planes, each","each is spaced","spacing sixty","apart.","spaced sixty degrees"],"target_translation":"Konstelasi satelit tersebut beroperasi melintasi enam bidang orbit, yang masing-masing berjarak enam puluh derajat satu sama lain."}'::jsonb, '["The satellite constellation","operates across six","orbital planes, each","spaced sixty degrees","apart."]'::jsonb, NULL, NULL, 'Absolut penutup '', each spaced...'' (tanpa ''is'') menjaga kepadatan dan ketepatan tanda baca koma.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000757', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'speaking', 'speaking_repeat', 'Ucapkan kalimat deskripsi dampak krisis berikut dengan penekanan jelas pada ''in its wake'':', '{"romaji":"/ðə tuː ˈθaʊzənd eɪt lɪˈkwɪdəti friːz rɪˈsiːdɪd ˈsloʊli ˈliːvɪŋ ˈstrɪktər ˈkæpɪtəl ruːlz ɪn ɪts weɪk/","display_text":"The 2008 liquidity freeze receded slowly, leaving stricter capital rules in its wake.","phonetic_breakdown":["The 2008 liquidity freeze","receded slowly,","leaving stricter capital rules","in its wake."]}'::jsonb, '{"expected_transcript":"The 2008 liquidity freeze receded slowly, leaving stricter capital rules in its wake."}'::jsonb, NULL, NULL, 'Lafalkan ''liquidity'' /lɪˈkwɪdəti/ dengan flap lembut AS pada suku kata terakhir.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000758', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Pilih idiom yang berarti ''sebagai dampak susulan tepat sesudah berlalunya suatu peristiwa'':', '{"options":["at face value","under wraps","in its wake","out of hand"],"translation":"Guncangan rantai pasok tahun 2021 merombak buku pedoman pengadaan, meninggalkan mandat pemasok ganda sebagai dampak susulannya.","sentence_template":"The supply-chain shock of 2021 reshaped procurement playbooks, leaving dual-sourcing mandates [blank]."}'::jsonb, '{"selected":"in its wake"}'::jsonb, NULL, NULL, '''Leave [consequence] in its wake'' sangat idiomatis dalam tulisan sejarah dan ekonomi.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000759', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'listening', 'listening_choice', 'Dengarkan rangkuman analis demografi tentang pergeseran kerja jarak jauh di kota besar AS. Bagaimana ia memadatkan dua tren berlawanan dalam satu kalimat?', '{"options":[{"id":"opt_1","text":"Ruang kerja bersama di pinggiran kota ikut tutup bersamaan dengan gedung pusat kota"},{"id":"opt_2","text":"Dinas transportasi menambah kereta khusus pusat kota karena lonjakan penumpang harian"},{"id":"opt_3","text":"Kekosongan kantor pusat kota menembus 20%, diiringi sentra kerja bersama pinggiran kota menyerap tim dan dinas transportasi menata ulang jadwal hari kerja"},{"id":"opt_4","text":"Kantor pusat kota penuh sesak hingga melampaui kapasitas seratus persen"}],"audio_text":"Downtown office vacancies climbed past twenty percent, with suburban coworking hubs absorbing displaced teams and transit agencies rethinking weekday schedules."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Struktur ''With [S1 + V-ing] and [S2 + V-ing]'' merangkum dua dampak paralel dalam satu tarikan napas.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000760', 'e5100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000053', 'writing', 'sentence_builder', 'Susun kalimat transisi sejarah sains dengan ''set the stage for'':', '{"romaji":"/prɪˈsɪʒən ˈɡlæs ɡraɪndɪŋ ɪn dʌtʃ ˈwɜːrkˌʃɑːps sɛt ðə steɪdʒ fɔːr boʊθ maɪˈkrɑːskəpi/","tokens":["setting stages to","telescopic astronomy.","set the stage for","in Dutch workshops","both microscopy and","Precision glass-grinding","into microscopy"],"target_translation":"Pengasahan kaca presisi di bengkel-bengkel Belanda menyiapkan panggung bagi mikroskopi sekaligus astronomi teleskopik."}'::jsonb, '["Precision glass-grinding","in Dutch workshops","set the stage for","both microscopy and","telescopic astronomy."]'::jsonb, NULL, NULL, 'Perhatikan tekanan suku kata kedua pada ''mi-CROS-co-py'' (/maɪˈkrɑːskəpi/).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000761', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih bentuk pembuka absolut yang bebas dari kesalahan *comma splice*:', '{"options":["Having verified its formal proofs","Its formal proofs verified","Verifying its formal proofs","Its formal proofs were verified"],"translation":"Setelah bukti matematika formalnya terverifikasi oleh para kriptografer independen, pustaka pertukaran kunci pascakuantum itu masuk ke kernel utama Linux.","sentence_template":"[blank] by independent cryptographers, the post-quantum key-exchange library entered mainline Linux kernels."}'::jsonb, '{"selected":"Its formal proofs verified"}'::jsonb, NULL, NULL, 'Subjek induk adalah ''the library'' (bukan peneliti!), sehingga membutuhkan klausa absolut pasif bersubjek sendiri ''Its formal proofs verified,''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000762', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Lengkapi klausa absolut ekonomi *ceteris paribus* berikut:', '{"options":["are","is","being","been"],"translation":"Dengan asumsi seluruh faktor lain tetap sama, sertifikasi tanah yang transparan menurunkan risiko agunan bagi petani kecil.","sentence_template":"All else [blank] equal, transparent land titling lowers collateral risk for smallholder farmers."}'::jsonb, '{"selected":"being"}'::jsonb, NULL, NULL, '''All else being equal,'' menggunakan partisip ''being'', bukan verba finit ''is''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000763', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'listening', 'listening_choice', 'Evaluasi Unit 3 — Dengarkan laporan ketua tim bedah robotik tentang operasi jarak jauh lintas pulau. Kondisi apa yang memungkinkan operasi dimulai?', '{"options":[{"id":"opt_1","text":"Generator cadangan belum sempat diperiksa ketika operasi dimulai"},{"id":"opt_2","text":"Jaringan serat bawah laut terputus sehingga operasi ditunda minggu depan"},{"id":"opt_3","text":"Latensi jaringan melonjak melampaui dua ratus milidetik selama operasi"},{"id":"opt_4","text":"Fluktuasi latensi serat bawah laut stabil di bawah 12 milidetik dan pemeriksaan generator cadangan telah rampung"}],"audio_text":"Subsea fiber jitter holding steady below twelve milliseconds and backup generator checks completed, our Makassar and Surabaya surgical teams proceeded with the telesurgery."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Dua klausa absolut sejajar (''jitter holding steady...'' dan ''checks completed,'') merangkum daftar prasyarat prabedah dengan sangat ringkas.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000764', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'writing', 'sentence_builder', 'Evaluasi Unit 3 — Susun kalimat absolut penutup berpola '', each + V-ing'':', '{"romaji":"/fɔːr ˈtaɪdəl ˈtɜːrbaɪnz ˈæŋkər ðə streɪt əˈreɪ iːtʃ ˈdʒɛnəˌreɪtɪŋ tuː ˈmɛɡəˌwɑːts/","tokens":["array, each generating","are generating","anchor the strait","each generates","Four tidal turbines","spring tides.","two megawatts during"],"target_translation":"Empat turbin pasang surut menopang susunan di selat tersebut, yang masing-masing membangkitkan dua megawatt saat pasang purnama."}'::jsonb, '["Four tidal turbines","anchor the strait","array, each generating","two megawatts during","spring tides."]'::jsonb, NULL, NULL, 'Gunakan partisip ''each generating'' sesudah koma agar tidak terjadi *comma splice*.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000765', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'speaking', 'speaking_repeat', 'Evaluasi Unit 3 — Ucapkan kalimat klausa absolut kausal berikut dengan jelas:', '{"romaji":"/wɪð ˈrɛzərˌvwɑːr ˈlɛvəlz ˈdwɪndəlɪŋ mjuːˈnɪsəpəl juːˈtɪlətiz ækˈsɛləˌreɪtɪd ˈweɪstˌwɔːtər riːˈsaɪklɪŋ/","display_text":"With reservoir levels dwindling, municipal utilities accelerated wastewater recycling.","phonetic_breakdown":["With reservoir levels","dwindling, municipal utilities","accelerated wastewater","recycling."]}'::jsonb, '{"expected_transcript":"With reservoir levels dwindling, municipal utilities accelerated wastewater recycling."}'::jsonb, NULL, NULL, 'Lafalkan ''reservoir'' ala AS /ˈrɛzərˌvwɑːr/ dengan akhiran rhotic /r/ yang jelas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000766', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'reading', 'fill_blank', 'Evaluasi Unit 3 — Pilih partisip perfek aktif yang tepat untuk verba intransitif ''subside'' (mereda):', '{"options":["subside","were subsided","having been subsided","having subsided"],"translation":"Setelah gelombang monsun mereda di sepanjang Selat Sunda, kapal perbaikan kabel bawah laut melanjutkan operasi penyambungan.","sentence_template":"Monsoon swells [blank] along the Sunda Strait, subsea cable repair ships resumed splicing operations."}'::jsonb, '{"selected":"having subsided"}'::jsonb, NULL, NULL, 'Karena ''subside'' intransitif (air mereda sendiri), bentuk absolut selesainya adalah ''having subsided''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000767', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'listening', 'listening_choice', 'Evaluasi Unit 3 — Dengarkan analisis dosen sejarah Eropa tentang dampak Wabah Hitam abad ke-14. Apa yang ditinggalkan krisis tersebut ''in its wake''?', '{"options":[{"id":"opt_1","text":"Jumlah buruh tani di Inggris abad ke-14 justru berlipat ganda selama wabah"},{"id":"opt_2","text":"Kelangkaan tenaga kerja pedesaan melemahkan sistem perhambaan feodal dan meningkatkan daya tawar petani sesudah wabah berlalu"},{"id":"opt_3","text":"Para bangsawan feodal berhasil menurunkan upah petani hingga nol sesudah wabah"},{"id":"opt_4","text":"Sistem perhambaan feodal makin menguat selama lima abad berikutnya di Inggris"}],"audio_text":"With rural labor suddenly scarce across fourteenth-century England, feudal lords could no longer dictate subsistence wages—leaving weakened serfdom and rising peasant bargaining power in the plague''s wake."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Memahami rantai sebab-akibat sejarah dari pembuka ''With rural labor suddenly scarce,'' hingga penutup ''in the plague''s wake''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000768', 'e5100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000053', 'writing', 'sentence_builder', 'Evaluasi Unit 3 — Susun kalimat kualifikasi eksekutif dengan ''that being said'':', '{"romaji":"/sɪnˈθɛtɪk ˈbɛntʃˌmɑːrks lʊk ˈprɑːmɪsɪŋ ðæt ˈbiːɪŋ sɛd ˈnɔɪzi ˈhɑːspɪtəl ˈwaɪˌfaɪ rɪˈmeɪnz/","tokens":["saying that","that is said","Synthetic benchmarks look","promising; that being said,","remains the true test.","noisy hospital Wi-Fi"],"target_translation":"Tolok ukur sintetis tampak menjanjikan; namun demikian, Wi-Fi rumah sakit yang bising tetap menjadi ujian sesungguhnya."}'::jsonb, '["Synthetic benchmarks look","promising; that being said,","noisy hospital Wi-Fi","remains the true test."]'::jsonb, NULL, NULL, 'Titik koma + ''that being said,'' mengantarkan kontras realitas lapangan secara tajam.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000769', 'e5100001-0000-4000-8000-000000000095', NULL, 'reading', 'fill_blank', 'Pilih pembuka konsesi emfatik yang bermakna ''Betapapun besarnya keinginan kami...'':', '{"options":["Many as","Very though","Much as","So as"],"translation":"Betapapun besarnya keinginan kami menyalin balik tambalan ini ke versi 2.0, skema lawas tersebut tidak memiliki batasan kunci asing.","sentence_template":"[blank] we would like to backport this patch to version 2.0, the legacy schema lacks foreign-key constraints."}'::jsonb, '{"selected":"Much as"}'::jsonb, NULL, NULL, '''Much as + Subject + Verb'' adalah idiom konsesi baku untuk kata kerja keinginan, rasa hormat, atau apresiasi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000770', 'e5100001-0000-4000-8000-000000000095', NULL, 'reading', 'fill_blank', 'Pahami idiom jebakan TOEFL Reading! Apa kata yang melengkapi makna ''Terlepas dari segala kemewahan arsitekturnya...''?', '{"options":["With","For","By","From"],"translation":"Terlepas dari segala kemegahan arsitekturnya, terminal kaca tersebut mengalami panas radiasi matahari yang parah setiap siang.","sentence_template":"[blank] all its architectural grandeur, the glass terminal suffered severe solar heat gain every afternoon."}'::jsonb, '{"selected":"For"}'::jsonb, NULL, NULL, '''For all its [positive trait],'' berarti ''Despite all its [trait],''—kontras tajam antara kemegahan luar dan cacat fungsi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000771', 'e5100001-0000-4000-8000-000000000095', NULL, 'listening', 'listening_choice', 'Dengarkan ulasan kritikus kebijakan energi terhadap target nol-emisi sebuah maskapai. Mengapa kritikus menyebut target itu ''laudable''?', '{"options":[{"id":"opt_1","text":"Niatnya memang patut dipuji, namun terlepas dari kemeriahan siaran persnya, pasokan bahan bakar pesawat berkelanjutan saat ini masih di bawah satu persen"},{"id":"opt_2","text":"Maskapai tersebut sudah berhasil mencapai nol-emisi penuh pada tahun ini"},{"id":"opt_3","text":"Bahan bakar pesawat berkelanjutan sudah mencukupi sembilan puluh sembilan persen kebutuhan armada"},{"id":"opt_4","text":"Kritikus mengecam niat pengurangan emisi sebagai tujuan yang buruk secara moral"}],"audio_text":"Pledging net-zero aviation by 2035 is undeniably laudable; for all the press-release fanfare, however, sustainable aviation fuel currently supplies less than one percent of fleet demand."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memadukan pujian ''laudable'' dengan konsesi kritis ''for all the press-release fanfare, however...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000772', 'e5100001-0000-4000-8000-000000000095', NULL, 'writing', 'sentence_builder', 'Susun kalimat konsesi kata kerja dasar ''Try as they might,'' berikut:', '{"romaji":"/traɪ æz ðeɪ maɪt ˈnaɪnˌtiːnθ ˈsɛntʃəri ˈælkəmɪsts kʊd ˈnɛvər trænzˈmjuːt lɛd θruː/","tokens":["transmuted lead","could never transmute","Trying might","Try as they might,","nineteenth-century alchemists","lead through chemical","reactions alone."],"target_translation":"Sekeras apa pun mereka berusaha, alkemis abad kesembilan belas tidak pernah bisa mengubah timbal lewat reaksi kimia semata."}'::jsonb, '["Try as they might,","nineteenth-century alchemists","could never transmute","lead through chemical","reactions alone."]'::jsonb, NULL, NULL, 'Perhatikan lafal logam timbal ''lead'' (/lɛd/, berima dengan ''red''), berbeda dari verba ''lead'' (/liːd/)!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000773', 'e5100001-0000-4000-8000-000000000095', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat sanggahan penuh hormat di ruang rapat berikut:', '{"romaji":"/mʌtʃ æz aɪ rɪˈspɛkt ði ˈeɪdʒənsiz kræft ðɛr kæmˈpeɪn ˈmɪsɪz ˈrʊrəl ˈbaɪərz/","display_text":"Much as I respect the agency''s craft, their campaign misses rural buyers.","phonetic_breakdown":["Much as I respect","the agency''s craft,","their campaign misses","rural buyers."]}'::jsonb, '{"expected_transcript":"Much as I respect the agency''s craft, their campaign misses rural buyers."}'::jsonb, NULL, NULL, 'Beri intonasi hangat dan tulus pada ''Much as I respect...'', lalu tegas pada ''misses rural buyers''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000774', 'e5100001-0000-4000-8000-000000000095', NULL, 'reading', 'fill_blank', 'Pilih kata sifat yang tepat untuk menggambarkan cita-cita yang mulia dan terpuji sebelum memberi catatan:', '{"options":["putative","laudable","untenable","uncorroborated"],"translation":"Serat optik ke rumah pedesaan secara universal adalah ambisi yang terpuji, namun hibrida satelit-seluler menjangkau pulau terpencil dengan sepersepuluh biayanya.","sentence_template":"Universal rural fiber-to-the-home is a [blank] ambition, yet satellite-cellular hybrids reach remote islands at a tenth of the cost."}'::jsonb, '{"selected":"laudable"}'::jsonb, NULL, NULL, '''A laudable ambition / goal / effort'' adalah kolokasi standar untuk memuji tujuan luhur.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000775', 'e5100001-0000-4000-8000-000000000095', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah paleontologi TOEFL tentang kepunahan megafauna Pleistosen. Mengapa para peneliti belum mencapai satu konsensus tunggal?', '{"options":[{"id":"opt_1","text":"Perburuan manusia terbukti tidak terjadi di benua mana pun selama zaman es"},{"id":"opt_2","text":"Perubahan iklim sama sekali tidak memengaruhi populasi hewan besar"},{"id":"opt_3","text":"Sekeras apa pun ahli paleontologi mencari satu penyebab tunggal, bukti fosil menunjukkan perubahan iklim dan perburuan manusia berinteraksi secara berbeda di tiap benua"},{"id":"opt_4","text":"Para ahli sudah sepakat bahwa meteorit tunggal memusnahkan megafauna Pleistosen"}],"audio_text":"Search as paleontologists might for a single smoking gun, fossil timelines suggest climate swings and human hunting interacted differently on every continent."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Pola produktif ''[Base Verb: Search] as [Subject] might,'' menegaskan pencarian bukti yang menantang.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000776', 'e5100001-0000-4000-8000-000000000095', NULL, 'writing', 'sentence_builder', 'Susun kalimat konsesi ''For all'' untuk analisis bisnis berikut:', '{"romaji":"/fɔːr ɔːl ɪts ˈvaɪrəl kənˈsuːmər ɡroʊθ ðə ˈsuːpər æp stɪl ˈluːzɪz ˈmʌni/","tokens":["grocery deliveries.","loses money on","losing money","To all its","the super-app still","For all its","viral consumer growth,"],"target_translation":"Terlepas dari pertumbuhan konsumennya yang viral, aplikasi super tersebut masih merugi pada pengantaran bahan pangan."}'::jsonb, '["For all its","viral consumer growth,","the super-app still","loses money on","grocery deliveries."]'::jsonb, NULL, NULL, '''For all its [NP], [Main Clause]'' menyajikan paradoks bisnis secara ringkas.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000777', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Ingat pantangan ''although'' pada konsesi terbalik! Pilih kata hubung yang sah sesudah kata sifat di awal kalimat:', '{"options":["despite","although","though","even"],"translation":"Semenggoda apa pun perbaikan cepat basis data pada pukul 2 dini hari, melewati lingkungan staging berisiko merusak data secara diam-diam.","sentence_template":"Tempting [blank] a quick database hotfix may appear at 2 a.m., bypassing staging risks silent data corruption."}'::jsonb, '{"selected":"though"}'::jsonb, NULL, NULL, 'Hanya ''though'' atau ''as'' yang boleh mengikuti kata sifat yang dikedepankan (''Tempting though/as...''), tidak pernah ''although'' atau ''despite''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000778', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Terapkan aturan penghilangan artikel (*zero article*) saat kata benda tunggal dikedepankan sebelum ''though'':', '{"options":["Pioneering is","The pioneer of","Pioneer","A pioneer"],"translation":"Meskipun Dr. Kartika seorang pelopor dalam virologi tropis, beliau tetap memeriksa ulang setiap urutan primer bersama teknisi lab muda.","sentence_template":"[blank] though Dr. Kartika was in tropical virology, she double-checked every primer sequence with junior lab techs."}'::jsonb, '{"selected":"Pioneer"}'::jsonb, NULL, NULL, 'Kata benda tunggal predikatif (''a pioneer'') wajib menanggalkan artikel ''a'' ketika dikedepankan: ''Pioneer though she was,''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000779', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'listening', 'listening_choice', 'Dengarkan kuliah sejarah seni arsitektur TOEFL tentang kubah Pantheon di Roma. Struktur konsesi apa yang dipakai profesor?', '{"options":[{"id":"opt_1","text":"Kubah Pantheon ditopang oleh ribuan batang baja modern di bagian puncaknya"},{"id":"opt_2","text":"Kubah Pantheon runtuh beberapa dekade sesudah selesai dibangun"},{"id":"opt_3","text":"Meskipun kubah beton tanpa tulangannya begitu masif hingga kini, arsitek Romawi meringankan puncaknya dengan batu apung vulkanik ringan"},{"id":"opt_4","text":"Arsitek Romawi menggunakan granit terberat justru di sekeliling lubang puncak oculus"}],"audio_text":"Massive as the Pantheon''s unreinforced concrete dome remains even today, Roman builders lightened its crown ingeniously by grading volcanic pumice aggregate toward the oculus."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Konsesi ''Massive as [Subject] remains..., [Builders] lightened...'' menonjolkan keajaiban rekayasa struktural.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000780', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'writing', 'sentence_builder', 'Susun kalimat konsesi derajat dengan ''However + Adverb'' (tanpa koma setelah ''However''!):', '{"romaji":"/haʊˈɛvər ˈrɪɡərəsli wi rɪˈdækt ˈtreɪnɪŋ ˈkɔːrpərə ˈmɛmbərˌʃɪp ˈɪnfərəns əˈtæks stɪl ˈwɔːrənt/","tokens":["warranting vigilance","redact training corpora,","However rigorously we","However, rigorously","still warrant vigilance.","membership inference attacks"],"target_translation":"Seketat apa pun kita menyensor korpus pelatihan, serangan inferensi keanggotaan tetap menuntut kewaspadaan."}'::jsonb, '["However rigorously we","redact training corpora,","membership inference attacks","still warrant vigilance."]'::jsonb, NULL, NULL, '''However + Adverb (rigorously) + S + V'' ditulis menyatu tanpa tanda koma sesudah ''However''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000781', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'speaking', 'speaking_repeat', 'Ucapkan kalimat konsesi kata sifat di awal kalimat berikut dengan lancar:', '{"romaji":"/ˈluːkrətɪv ðoʊ ˈʃɔːrt tɜːrm ˈɑːrbəˌtrɑːʒ wʌz ðə fʌnd praɪˈɔːrəˌtaɪzd ˈlɔːŋ həˈraɪzən ˈɪnfrəˌstrʌktʃər/","display_text":"Lucrative though short-term arbitrage was, the fund prioritized long-horizon infrastructure.","phonetic_breakdown":["Lucrative though","short-term arbitrage was,","the fund prioritized","long-horizon infrastructure."]}'::jsonb, '{"expected_transcript":"Lucrative though short-term arbitrage was, the fund prioritized long-horizon infrastructure."}'::jsonb, NULL, NULL, 'Lafalkan ''arbitrage'' /ˈɑːrbəˌtrɑːʒ/ dengan bunyi akhir /-ɑːʒ/ seperti pada ''garage''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000782', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Pilih susunan Subjek + Kata Kerja yang tepat sesudah ''Rigorous as'':', '{"options":["the protocol being","the protocol was","did the protocol","was the protocol"],"translation":"Seketat apa pun protokol tersebut, studi hewan pengerat terkontrol di lab jarang diterjemahkan mentah-mentah menjadi hasil klinis manusia.","sentence_template":"Rigorous as [blank], lab-controlled rodent studies rarely translate one-to-one into human clinical outcomes."}'::jsonb, '{"selected":"the protocol was"}'::jsonb, NULL, NULL, 'Dalam inversi konsesif, yang berpindah ke depan HANYA kata sifatnya (''Rigorous''), sedangkan ''the protocol was'' tetap berurutan S + V!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000783', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'listening', 'listening_choice', 'Dengarkan tanggapan anggota komite beasiswa terhadap esai kandidat. Apa kekuatan sekaligus celah dari proposal tersebut?', '{"options":[{"id":"opt_1","text":"Esai kandidat menjelaskan secara tuntas protokol autentikasi tanpa ponsel"},{"id":"opt_2","text":"Purwarupa tekfin kandidat dinilai tidak menarik sama sekali oleh komite"},{"id":"opt_3","text":"Seluruh petani sasaran di esai tersebut sudah memiliki ponsel pintar terbaru"},{"id":"opt_4","text":"Purwarupa tekfin desanya memang meyakinkan, namun esainya belum menjelaskan cara petani tanpa ponsel pintar mengautentikasi transaksi"}],"audio_text":"Compelling though the applicant''s rural fintech prototype is, her essay stops short of explaining how farmers without smartphones will authenticate transactions."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Compelling though X is, her essay stops short of V-ing...'' adalah pola evaluasi kritis komite seleksi beasiswa.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000784', 'e5100001-0000-4000-8000-000000000096', 'e2000001-0000-4000-8000-000000000054', 'writing', 'sentence_builder', 'Susun kalimat inversi konsesif berpredikat adverbia ''Swiftly as'':', '{"romaji":"/ˈswɪftli æz ˈɪnsədənt rɪˈspɑːndərz ˈaɪsəˌleɪtɪd ðə ˈsʌbˌnɛt ˈlætərəl ˈmuːvmənt hæd ɔːlˈrɛdi/","tokens":["had already occurred.","responders isolated the","did responders isolate","Swiftly although","Swiftly as incident","subnet, lateral movement"],"target_translation":"Secepat apa pun tim tanggap insiden mengisolasi subjaringan tersebut, pergerakan menyamping telanjur terjadi."}'::jsonb, '["Swiftly as incident","responders isolated the","subnet, lateral movement","had already occurred."]'::jsonb, NULL, NULL, '''Swiftly as + S + V'' menekankan kecepatan aksi yang tetap kalah cepat dari penyusup.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000785', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Pilih kata benda klasik C2 yang berarti ''obat mujarab tunggal bagi segala persoalan'':', '{"options":["fruition","panacea","quorum","fallout"],"translation":"Sememukau apa pun internet satelit bagi pelayaran maritim, lebar pita orbit bukanlah obat mujarab pengganti serat optik perkotaan padat.","sentence_template":"Dazzling though satellite internet is for maritime shipping, orbital bandwidth is no [blank] for dense urban fiber."}'::jsonb, '{"selected":"panacea"}'::jsonb, NULL, NULL, '''Be no panacea for [X]'' adalah pembatas argumen favorit pada esai kebijakan dan teknologi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000786', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Pilih idiom yang tepat ketika komite memberi teguran keras namun TIDAK sampai mencabut izin:', '{"options":["came down on","stopped short of","ushered in","followed suit with"],"translation":"Regulator penerbangan mendenda maskapai tersebut atas keterlambatan perawatan namun tidak sampai melarang terbang armada regionalnya.","sentence_template":"The aviation regulator fined the carrier for maintenance delays but [blank] grounding its regional fleet."}'::jsonb, '{"selected":"stopped short of"}'::jsonb, NULL, NULL, '''Stop short of + V-ing'' menandai batas tindakan yang sengaja tidak dilampaui.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000787', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'listening', 'listening_choice', 'Dengarkan diskusi akademis TOEFL tentang penangkapan karbon langsung dari udara (*Direct Air Capture*). Bagaimana profesor meredam euforia mahasiswa?', '{"options":[{"id":"opt_1","text":"Hukum termodinamika meredam antusiasme berlebih karena konsentrasi CO2 di udara bebas 250 kali lebih encer daripada di cerobong pembangkit"},{"id":"opt_2","text":"Konsentrasi CO2 di udara bebas mencapai lima puluh persen volume atmosfer"},{"id":"opt_3","text":"Menangkap CO2 dari udara terbuka jauh lebih hemat energi daripada di cerobong pabrik"},{"id":"opt_4","text":"Profesor menolak seluruh riset pengurangan emisi karbon di universitas"}],"audio_text":"Look, capturing CO2 straight out of ambient air sounds magical, yet thermodynamics tempers our enthusiasm: CO2 is 250 times more dilute in open air than inside a power-plant smokestack!"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Penggunaan ''tempers our enthusiasm'' diikuti fakta fisika kuantitatif memodelkan penalaran ilmiah kritis.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000788', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'writing', 'sentence_builder', 'Susun kalimat kritik keseimbangan laboratorium vs. produksi massal berikut:', '{"romaji":"/ɪmˈprɛsɪv æz ˈbɛntʃˌtɑːp pəˈrɑːvskaɪt sɛlz ɑːr ˈtwɛnti jɪr ˈruːfˌtɑːp ˌdʊrəˈbɪləti rɪˈmeɪnz/","tokens":["perovskite cells are,","Impressive as benchtop","far crying","from proven.","Impressive although","remains a far cry","twenty-year rooftop durability"],"target_translation":"Semengesankan apa pun sel perovskit di meja laboratorium, ketahanan atap dua puluh tahun masih sangat jauh dari terbukti."}'::jsonb, '["Impressive as benchtop","perovskite cells are,","twenty-year rooftop durability","remains a far cry","from proven."]'::jsonb, NULL, NULL, 'Inversi konsesif ''Impressive as X are,'' dipadukan idiom ''a far cry from [Adj/NP]''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000789', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penutup esai teknologi pendidikan berikut dengan artikulasi ''panacea'' yang jernih:', '{"romaji":"/ɪnˈɡeɪdʒɪŋ ðoʊ ˈeɪˈaɪ ˈtuːtərz meɪ bi ˈsɔːftˌwɛr ɪz noʊ ˌpænəˈsiːə fɔːr ˌoʊvərˈkraʊdɪd ˈklæsˌruːmz/","display_text":"Engaging though AI tutors may be, software is no panacea for overcrowded classrooms.","phonetic_breakdown":["Engaging though","AI tutors may be,","software is no panacea","for overcrowded classrooms."]}'::jsonb, '{"expected_transcript":"Engaging though AI tutors may be, software is no panacea for overcrowded classrooms."}'::jsonb, NULL, NULL, 'Tekankan ritme kontras ''AI TUTORS may be'' vs. ''NO PANACEA for overcrowded CLASSROOMS''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000790', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Pilih verba yang berpasangan tepat dengan ''optimism / enthusiasm'' untuk arti ''menyeimbangkan dengan kehati-hatian'':', '{"options":["receded","embarked","transpired","tempered"],"translation":"Hasil awal onkologi fase dua menyemangati investor, meski para klinisi berpengalaman menyeimbangkan optimisme mereka sembari menunggu data kelangsungan hidup.","sentence_template":"Early phase-two oncology readouts encouraged investors, though seasoned clinicians [blank] their optimism pending survival data."}'::jsonb, '{"selected":"tempered"}'::jsonb, NULL, NULL, '''Temper optimism / enthusiasm'' menunjukkan kematangan penilaian ilmiah dan finansial.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000791', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'listening', 'listening_choice', 'Dengarkan wawancara penulis buku ekonomi industri AS. Mengapa ia menyebut subsidi pabrik perakitan tertentu ''a far cry from true industrial policy''?', '{"options":[{"id":"opt_1","text":"Memberi keringanan pajak bagi pabrik perakitan akhir tanpa mendanai riset pemasok lokal sangat jauh dari pembangunan ekosistem industri sejati"},{"id":"opt_2","text":"Pemasok lokal tidak membutuhkan dukungan riset dan pengembangan"},{"id":"opt_3","text":"Penulis menolak segala bentuk investasi manufaktur di dalam negeri"},{"id":"opt_4","text":"Keringanan pajak perakitan saja sudah cukup membangun ekosistem riset kelas dunia"}],"audio_text":"Handing tax breaks to screwdriver assembly plants without funding local supplier R&D is a far cry from true industrial ecosystem building."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''A far cry from [true standard]'' membedakan kebijakan kosmetik dari transformasi struktural.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000792', 'e5100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000054', 'writing', 'sentence_builder', 'Susun kalimat sanggahan halus berstruktur ''Much as'' dan ''stop short of'':', '{"romaji":"/mʌtʃ æz rɪˈvjuːərz preɪzd ðə ˈdeɪtəˌsɛt ðeɪ stɑːpt ʃɔːrt ʌv ɪnˈdɔːrsɪŋ ˈklɪnɪkəl dɪˈplɔɪmənt/","tokens":["deployment.","they stopped short","of endorsing clinical","stopping short to","endorse clinical","praised the dataset,","Much as reviewers"],"target_translation":"Betapapun para peninjau memuji dataset tersebut, mereka belum sampai memberikan dukungan untuk penggelaran klinis."}'::jsonb, '["Much as reviewers","praised the dataset,","they stopped short","of endorsing clinical","deployment."]'::jsonb, NULL, NULL, 'Menggabungkan konsesi pembuka ''Much as + S + V'' dengan batasan ''stopped short of + V-ing''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000793', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Pilih bentuk kata benda tanpa artikel yang sah untuk inversi konsesif di awal kalimat:', '{"options":["Championing","The champion","Champion","A champion"],"translation":"Meskipun ia seorang pembela gigih ortodoksi monetaris, sang gubernur tetap mengizinkan pertukaran likuiditas terarah saat kepanikan terjadi.","sentence_template":"[blank] though he was of monetarist orthodoxy, the governor authorized targeted liquidity swaps during the panic."}'::jsonb, '{"selected":"Champion"}'::jsonb, NULL, NULL, 'Kata benda tunggal terhitung melepaskan artikel ''a/the'' ketika dikedepankan mendahului ''though/as'': ''Champion though he was...''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000794', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Pilih penghubung konsesif yang tepat sesudah kata sifat yang dikedepankan:', '{"options":["as","although","despite","whereas"],"translation":"Sekontraintuitif apa pun pembakaran hutan terkendali di mata warga kota, membersihkan semak kering mencegah kebakaran tajuk raksasa.","sentence_template":"Counterintuitive [blank] controlled forest burns seem to urban residents, clearing dry underbrush prevents crown megafires."}'::jsonb, '{"selected":"as"}'::jsonb, NULL, NULL, 'Kata sifat yang dikedepankan wajib diikuti ''as'' atau ''though'' (tidak pernah ''although'' atau ''despite'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000795', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'listening', 'listening_choice', 'Evaluasi Unit 4 — Dengarkan petikan teks kritik sejarah teknologi tentang proyek pesawat supersonik Concorde. Apa arti ''For all its aerodynamic brilliance''?', '{"options":[{"id":"opt_1","text":"Pesawat Concorde sangat hemat bahan bakar dibandingkan pesawat berbadan lebar biasa"},{"id":"opt_2","text":"Terlepas dari kecemerlangan aerodinamikanya yang luar biasa, konsumsi bahan bakar per kursinya terlalu boros secara komersial"},{"id":"opt_3","text":"Concorde membutuhkan waktu lebih dari sepuluh jam untuk menyeberangi Samudra Atlantik"},{"id":"opt_4","text":"Berkat kecemerlangan aerodinamikanya, puluhan maskapai murah mengoperasikan Concorde secara menguntungkan"}],"audio_text":"For all its aerodynamic brilliance—crossing the Atlantic in under three and a half hours—Concorde guzzled so much fuel per seat that only two subsidized flag carriers ever operated it."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Mengenali kontras tajam di balik pembuka konsesi idiomatis ''For all its [praise], [commercial flaw]''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000796', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'writing', 'sentence_builder', 'Evaluasi Unit 4 — Susun kalimat konsesi derajat ''However'' untuk keamanan siber:', '{"romaji":"/haʊˈɛvər ˈɛr ɡæpt ən ɪnˈdʌstriəl ˈnɛtˌwɜːrk əˈpɪrz rɪˈmuːvəbəl ˈmeɪntənəns draɪvz kæn stɪl/","tokens":["removable maintenance drives","can still introduce","malware.","appears network","However air-gapped an","industrial network appears,","However, air-gapped"],"target_translation":"Sterisolasi apa pun tampaknya sebuah jaringan industri dari internet, diska perawatan lepasan tetap dapat menyusupkan program jahat."}'::jsonb, '["However air-gapped an","industrial network appears,","removable maintenance drives","can still introduce","malware."]'::jsonb, NULL, NULL, '''However + Adjective (air-gapped) + Subject + Verb'' berfungsi sebagai klausa konsesi utuh.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000797', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'speaking', 'speaking_repeat', 'Evaluasi Unit 4 — Ucapkan kalimat konsesi ''Try as they might'' berikut dengan ekspresif:', '{"romaji":"/traɪ æz kəmˈpɛtətərz maɪt ˈrɛplɪˌkeɪtɪŋ ˈθɜːrti jɪrz ʌv lɪˈθɑːɡrəfi ˈɑːptɪks teɪks ˈdɛkeɪdz/","display_text":"Try as competitors might, replicating thirty years of lithography optics takes decades.","phonetic_breakdown":["Try as","competitors might,","replicating thirty years","of lithography optics takes decades."]}'::jsonb, '{"expected_transcript":"Try as competitors might, replicating thirty years of lithography optics takes decades."}'::jsonb, NULL, NULL, 'Tekankan kata pertama ''TRY as competitors might'' untuk menonjolkan kontras upaya vs. kesulitan.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000798', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'reading', 'fill_blank', 'Evaluasi Unit 4 — Lengkapi kalimat evaluasi bijak tentang teknologi penangkapan karbon:', '{"options":["no panacea","in strict accordance","the benefit of the doubt","common ground"],"translation":"Kompensasi karbon memang berperan di sektor yang sulit didekarbonisasi, namun bukan obat mujarab bagi tertundanya elektrifikasi jaringan.","sentence_template":"Carbon offsets have a role in hard-to-abate sectors, yet they remain [blank] for delayed grid electrification."}'::jsonb, '{"selected":"no panacea"}'::jsonb, NULL, NULL, '''Remain no panacea for [X]'' menjaga proporsi argumen kebijakan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000799', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'listening', 'listening_choice', 'Evaluasi Unit 4 — Dengarkan ulasan sidang promosi doktor tentang model prediksi banjir. Apa batas klaim yang dijaga oleh kandidat?', '{"options":[{"id":"opt_1","text":"Kandidat mengklaim modelnya bekerja seratus persen akurat di seluruh pegunungan dunia tanpa kalibrasi"},{"id":"opt_2","text":"Akurasi prediksi radar di wilayah Jakarta gagal total selama pengujian"},{"id":"opt_3","text":"Kandidat menolak memasang alat penakar hujan lokal di daerah pegunungan"},{"id":"opt_4","text":"Meskipun akurasi di Jakarta menggembirakan, peneliti secara jujur tidak mengklaim modelnya langsung berlaku di DAS pegunungan curam tanpa kalibrasi ulang"}],"audio_text":"Encouraging though our radar nowcasting accuracy is over Jakarta, we stop short of claiming transferability to steep mountainous watersheds without local rain-gauge recalibration."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Kejujuran metodologis C2: ''Encouraging though X is, we stop short of claiming Y without Z''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000800', 'e5100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000054', 'writing', 'sentence_builder', 'Evaluasi Unit 4 — Susun kalimat inversi konsesif dengan urutan S + V yang benar:', '{"romaji":"/ˈɛləɡənt ðoʊ ðə ˌkrɪptəˈɡræfɪk ˈproʊtəˌkɔːl lʊks ɑːn ˈpeɪpər ˈsaɪd ˈtʃænəl ˈliːkɪdʒ dɪˈmændz/","tokens":["Elegant although","cryptographic protocol looks","Elegant though the","shielding.","leakage demands hardware","on paper, side-channel","looks the protocol"],"target_translation":"Seelegan apa pun protokol kriptografis tersebut tampak di atas kertas, kebocoran saluran samping tetap menuntut pelindung perangkat keras."}'::jsonb, '["Elegant though the","cryptographic protocol looks","on paper, side-channel","leakage demands hardware","shielding."]'::jsonb, NULL, NULL, 'Pastikan urutan ''the cryptographic protocol looks'' (S + V), bukan terbalik *''looks the protocol''*.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000801', 'e5100001-0000-4000-8000-000000000099', NULL, 'reading', 'fill_blank', 'Pilih kata kerja yang menyiratkan keraguan tajam penulis terhadap klaim sepihak vendor:', '{"options":["corroborates","substantiates to","purports to","complies with"],"translation":"Tolok ukur tertutup tersebut mengklaim mengukur penalaran umum, padahal tujuh puluh persen soalnya telah bocor ke dataset pelatihan publik.","sentence_template":"The proprietary benchmark [blank] measure general reasoning, yet seventy percent of its prompts leaked into public training sets."}'::jsonb, '{"selected":"purports to"}'::jsonb, NULL, NULL, '''Purports to + V1'' menandai bahwa penulis meragukan keabsahan klaim yang diajukan subjek.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000802', 'e5100001-0000-4000-8000-000000000099', NULL, 'reading', 'fill_blank', 'Pilih adverbia C2 untuk menyingkap kontras antara alasan resmi di permukaan dan kenyataan sebenarnya:', '{"options":["ostensibly","unanimously","preemptively","mutually"],"translation":"Tarif tersebut di permukaan diberlakukan atas alasan kesehatan karantina tumbuhan, meski sejarawan dagang mencatat waktunya bertepatan dengan lobi pemilu domestik.","sentence_template":"The tariff was [blank] enacted on phytosanitary grounds, though trade historians note it coincided with domestic election lobbying."}'::jsonb, '{"selected":"ostensibly"}'::jsonb, NULL, NULL, '''Ostensibly'' memisahkan alasan lahiriah yang dikemukakan dari motif sesungguhnya.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000803', 'e5100001-0000-4000-8000-000000000099', NULL, 'listening', 'listening_choice', 'Dengarkan pembahasan soal ''Author''s Attitude'' TOEFL Reading tentang fosil burung purba *Protoavis*. Mengapa penulis memakai frasa ''its putative feathers''?', '{"options":[{"id":"opt_1","text":"Seluruh ilmuwan dunia sepakat bahwa Protoavis bukanlah fosil asli"},{"id":"opt_2","text":"Kata ''putative'' berarti bulu yang digunakan untuk terbang melintasi samudra"},{"id":"opt_3","text":"Penulis memberi sinyal bahwa dugaan adanya bulu tersebut masih diperdebatkan dan belum diterima bulat oleh rekan sejawat"},{"id":"opt_4","text":"Penulis memastikan seratus persen bahwa fosil Protoavis memiliki bulu berwarna cerah"}],"audio_text":"Notice the adjective ''putative'' in ''its putative feathers'': the author isn''t confirming Protoavis had feathers—she''s signaling that while one paleontologist claimed those marks were feather nodes, most peers remain unconvinced."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Memahami ''putative'' (= commonly supposed, though unproven) langsung menjawab soal sikap penulis di TOEFL Reading 28–30.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000804', 'e5100001-0000-4000-8000-000000000099', NULL, 'writing', 'sentence_builder', 'Susun kalimat prinsip kehati-hatian audit data berikut:', '{"romaji":"/ˈsiːzənd ˈduː ˈdɪlədʒəns tiːmz ˈnɛvər teɪk ˈsɛlf rɪˈpɔːrtɪd rɪˈtɛnʃən ˈkoʊhɔːrts æt feɪs ˈvæljuː/","tokens":["on face value","never take self-reported","taking cohorts","Seasoned due-diligence teams","retention cohorts at","face value."],"target_translation":"Tim uji tuntas yang berpengalaman tidak pernah menelan mentah-mentah kelompok data retensi yang dilaporkan sendiri."}'::jsonb, '["Seasoned due-diligence teams","never take self-reported","retention cohorts at","face value."]'::jsonb, NULL, NULL, 'Idiom baku memakai preposisi ''AT face value'' (bukan *''on''* atau *''in''*).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000805', 'e5100001-0000-4000-8000-000000000099', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat kritik ilmiah berikut dengan penekanan jelas pada ''purports'' dan ''ostensibly'':', '{"romaji":"/ðə waɪt ˈpeɪpər pərˈpɔːrts tə pruːv diːˌsɛntrələˈzeɪʃən waɪl ɑːˈstɛnsəbli ˈhaɪdɪŋ ˈvæləˌdeɪtər ˌkɑːnsənˈtreɪʃən/","display_text":"The white paper purports to prove decentralization while ostensibly hiding validator concentration.","phonetic_breakdown":["The white paper","purports to prove decentralization","while ostensibly hiding","validator concentration."]}'::jsonb, '{"expected_transcript":"The white paper purports to prove decentralization while ostensibly hiding validator concentration."}'::jsonb, NULL, NULL, 'Latih kontras tekanan pada ''pur-PORTS'' (/pərˈpɔːrts/) dan ''os-TEN-sibly'' (/ɑːˈstɛnsəbli/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000806', 'e5100001-0000-4000-8000-000000000099', NULL, 'reading', 'fill_blank', 'Pilih kata sifat akademik untuk merujuk pada mekanisme biologis yang ''diduga demikian namun belum pasti'':', '{"options":["untenable","putative","laudable","mandatory"],"translation":"Eksperimen tikus rekayasa genetika gagal mengonfirmasi peran reseptor yang selama ini diduga menekan nafsu makan.","sentence_template":"Knockout-mouse experiments failed to confirm the receptor''s [blank] role in appetite suppression."}'::jsonb, '{"selected":"putative"}'::jsonb, NULL, NULL, '''Putative role / mechanism / ancestor'' adalah kolokasi ilmiah murni untuk hipotesis yang belum terkonfirmasi.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000807', 'e5100001-0000-4000-8000-000000000099', NULL, 'listening', 'listening_choice', 'Dengarkan peringatan jurnalis keuangan AS tentang laporan laba perusahaan pra-IPO. Mengapa metrik ''adjusted EBITDA'' tidak boleh ditelan mentah-mentah?', '{"options":[{"id":"opt_1","text":"Kompensasi berbasis saham memang hanya terjadi satu kali seumur hidup perusahaan"},{"id":"opt_2","text":"Metrik EBITDA yang disesuaikan selalu lebih jujur daripada arus kas resmi audit"},{"id":"opt_3","text":"Jurnalis menyarankan investor membeli saham tanpa membaca catatan kaki laporan keuangan"},{"id":"opt_4","text":"Dengan mengeluarkan biaya rutin seperti kompensasi saham dan pemasaran, perusahaan merugi mengklaim seolah-olah mencetak margin sehat"}],"audio_text":"Never take ''community-adjusted EBITDA'' at face value: by stripping out stock-based compensation and marketing as ''one-time costs,'' unprofitable firms purport to show healthy margins!"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Menggabungkan ''never take X at face value'' dan ''purport to show'' dalam analisis laporan keuangan kritis.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000808', 'e5100001-0000-4000-8000-000000000099', NULL, 'writing', 'sentence_builder', 'Susun kalimat analisis sejarah dengan pembuka ''Ostensibly'':', '{"romaji":"/ɑːˈstɛnsəbli ˈtʃɑːrtərd æz ə ˈtreɪdɪŋ ˈkʌmpəni ðə ˈsɪndɪkət suːn ˈɛksərˌsaɪzd ˈsɑːvrən ˈmɪləˌtɛri/","tokens":["Ostensibly chartered as","a trading company,","Ostensible chartered","exercising sovereign","powers.","the syndicate soon","exercised sovereign military"],"target_translation":"Meskipun di permukaan diberi piagam sebagai perusahaan dagang, sindikat tersebut tak lama kemudian menjalankan kekuasaan militer berdaulat."}'::jsonb, '["Ostensibly chartered as","a trading company,","the syndicate soon","exercised sovereign military","powers."]'::jsonb, NULL, NULL, 'Adverbia ''Ostensibly'' memodifikasi partisip pasif pembuka ''chartered as...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000809', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Pilih infinitif perfek PASIF yang tepat untuk subjek benda arkeologis (''The sunken bronze astrolabe'') dan kejadian abad ke-16:', '{"options":["having been","that it was","to have","to have been"],"translation":"Astrolab perunggu yang karam itu diperkirakan telah dicor di Lisabon sesaat sebelum armada berlayar pada 1596.","sentence_template":"The sunken bronze astrolabe is believed [blank] cast in Lisbon shortly before the armada sailed in 1596."}'::jsonb, '{"selected":"to have been"}'::jsonb, NULL, NULL, 'Astrolab tidak mengecor dirinya sendiri (pasif) dan kejadiannya di tahun 1596 (lampau), sehingga memakai ''to have been + V3 (cast)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000810', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Pilih infinitif progresif untuk rumor negosiasi korporat yang SEDANG berlangsung minggu ini:', '{"options":["to have been negotiated","negotiating","that they negotiate","to be negotiating"],"translation":"Dua dana kekayaan negara santer diberitakan sedang menegosiasikan kepemilikan saham bersama pada operator kabel bawah laut tersebut minggu ini.","sentence_template":"Two sovereign wealth funds are widely reported [blank] a joint stake in the subsea cable operator this week."}'::jsonb, '{"selected":"to be negotiating"}'::jsonb, NULL, NULL, '''Are reported + to be V-ing'' secara presisi menandai aktivitas yang sedang berjalan saat laporan ditulis.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000811', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'listening', 'listening_choice', 'Dengarkan siaran berita hukum pasar modal AS. Mengapa pembawa berita wajib menggunakan ''is alleged to have traded'' alih-alih ''traded''?', '{"options":[{"id":"opt_1","text":"Karena tuduhan perdagangan orang dalam tersebut baru berupa gugatan yang belum diputus pengadilan, sehingga asas praduga tak bersalah wajib dijaga"},{"id":"opt_2","text":"Karena jurnalis memastikan bahwa direktur tersebut tidak pernah membeli opsi saham"},{"id":"opt_3","text":"Karena mantan direktur tersebut sudah mengaku bersalah di depan hakim"},{"id":"opt_4","text":"Karena transaksi opsi tersebut baru akan dilakukan tahun depan"}],"audio_text":"In the SEC''s civil complaint, the former director is alleged to have traded options ahead of three unannounced clinical trial halts—charges his counsel categorically denies."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Presisi hukum jurnalisme AS: ''is alleged to have V3'' melindungi media dari gugatan pencemaran nama baik (*defamation*) sebelum vonis inkracht.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000812', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'writing', 'sentence_builder', 'Susun kalimat pelaporan temuan postmortem teknis dengan ''appears to have been'':', '{"romaji":"/ðə ˈmɛməri liːk əˈpɪrz tə həv bɪn ˌɪntrəˈduːst ˈdʊrɪŋ læst ˈθɜːrzdeɪz təˈlɛmətri/","tokens":["to have introduced","appears to have been","Thursday''s telemetry SDK","The memory leak","upgrade.","introduced during last","appearing to have"],"target_translation":"Kebocoran memori tersebut tampaknya telah tak sengaja dimasukkan saat peningkatan SDK telemetri Kamis lalu."}'::jsonb, '["The memory leak","appears to have been","introduced during last","Thursday''s telemetry SDK","upgrade."]'::jsonb, NULL, NULL, 'Kebocoran memori ''dimasukkan'' (pasif) pada Kamis lalu (lampau) -> ''appears to have been introduced''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000813', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pelaporan hukum berikut dengan pelafalan ''alleged'' dua suku kata yang tepat:', '{"romaji":"/ðə ʃɛl ˈkʌmpəni ɪz əˈlɛdʒd tə həv ˈraʊtɪd ˈkɪkˌbæks θruː ˌɔːfˈʃɔːr trʌsts/","display_text":"The shell company is alleged to have routed kickbacks through offshore trusts.","phonetic_breakdown":["The shell company","is alleged to have routed","kickbacks through","offshore trusts."]}'::jsonb, '{"expected_transcript":"The shell company is alleged to have routed kickbacks through offshore trusts."}'::jsonb, NULL, NULL, 'Pastikan ''alleged'' diucapkan /əˈlɛdʒd/ (dua suku kata), dan di US English verba ''routed'' lazim diucapkan /ˈraʊtɪd/!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000814', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Pilih infinitif perfek AKTIF untuk subjek pelaku (''Polynesian navigators'') yang berlayar berabad-abad silam:', '{"options":["to have reached","to have been reached","reaching","to be reaching"],"translation":"Bukti genetik ubi jalar mengonfirmasi bahwa para navigator Polinesia kemungkinan besar telah mencapai Amerika Selatan berabad-abad sebelum kontak Eropa.","sentence_template":"Genetic sweet-potato evidence confirms that Polynesian navigators are likely [blank] South America centuries before European contact."}'::jsonb, '{"selected":"to have reached"}'::jsonb, NULL, NULL, 'Karena navigator adalah pelaku aktif dan kejadiannya di masa lampau, gunakan ''to have + V3 (reached)''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000815', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'listening', 'listening_choice', 'Dengarkan kuliah linguistik historis TOEFL tentang aksara Rongorongo Pulau Paskah. Apa kesimpulan terbaru dari penanggalan radiokarbon?', '{"options":[{"id":"opt_1","text":"Penanggalan radiokarbon tidak dapat diterapkan pada artefak berbahan kayu"},{"id":"opt_2","text":"Seluruh loh aksara Rongorongo terbukti baru dibuat pada abad kesembilan belas"},{"id":"opt_3","text":"Bangsa Eropa mengajarkan aksara kayu tersebut saat mendarat pada abad kelima belas"},{"id":"opt_4","text":"Setidaknya satu loh kayu diperkirakan diukir dari pohon yang ditebang akhir abad ke-15, lebih dari 200 tahun sebelum kedatangan bangsa Eropa"}],"audio_text":"At least one wooden tablet in a Rome museum is now estimated to have been carved from a tree felled in the late fifteenth century, predating European arrival on Rapa Nui by over two hundred years."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Is now estimated to have been carved...'' memperbarui konsensus ilmiah secara objektif.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000816', 'e5100001-0000-4000-8000-000000000100', 'e2000001-0000-4000-8000-000000000055', 'writing', 'sentence_builder', 'Susun kalimat pelaporan arkeologi pasif perfek berikut:', '{"romaji":"/ðə ˌsʌbtəˈreɪniən ˈækwəˌdʌkt ɪz θɔːt tə həv bɪn ˌɛndʒəˈnɪrd wɪˈðaʊt ˈaɪərn sərˈveɪɪŋ/","tokens":["is thought to","have been engineered","thinking to be","The subterranean aqueduct","to have engineered","without iron surveying","instruments."],"target_translation":"Akuaduk bawah tanah tersebut diperkirakan telah direkayasa tanpa instrumen survei berbahan besi."}'::jsonb, '["The subterranean aqueduct","is thought to","have been engineered","without iron surveying","instruments."]'::jsonb, NULL, NULL, '''Is thought + to have been + V3 (engineered)'' menjaga jarak bukti sejarah secara akurat.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000817', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Pilih kata benda formal C2 yang bermakna ''sangat minimnya / kelangkaan data'':', '{"options":["ripple","paucity","panacea","fruition"],"translation":"Sejarawan arsip menghadapi kelangkaan parah catatan pajak dari abad ketujuh, yang mempersulit perkiraan demografis.","sentence_template":"Archive historians face a severe [blank] of tax registers from the seventh century, complicating demographic estimates."}'::jsonb, '{"selected":"paucity"}'::jsonb, NULL, NULL, '''A severe paucity of [records/data]'' adalah register akademik puncak pengganti ''lack of''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000818', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Pilih frasa evaluasi kritis untuk bukti yang hanya bersumber dari beberapa cerita testimoni tanpa kelompok kontrol:', '{"options":["mutually exclusive","anecdotal at best","all things considered","in strict accordance"],"translation":"Tanpa kelompok kontrol acak, peningkatan produktivitas yang dilaporkan di blog vendor paling banter baru bersifat anekdotal.","sentence_template":"Without a randomized control arm, productivity gains reported in vendor blog posts are [blank]."}'::jsonb, '{"selected":"anecdotal at best"}'::jsonb, NULL, NULL, '''Anecdotal at best'' menempatkan kualitas bukti pada kasta terendah hierarki ilmiah secara sopan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000819', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'listening', 'listening_choice', 'Dengarkan komentar editor jurnal kedokteran terhadap naskah studi nutrisi observasional. Mengapa editor meminta penulis melunakkan judul makalahnya?', '{"options":[{"id":"opt_1","text":"Studi tersebut menggunakan pemantauan metabolik tertutup di bangsal rumah sakit selama setahun penuh"},{"id":"opt_2","text":"Editor langsung menerbitkan makalah tanpa perubahan satu kata pun"},{"id":"opt_3","text":"Kuesioner ingatan makan selama 12 bulan belum terverifikasi silang secara objektif, sehingga judul sebab-akibat mutlak tidak dapat dibenarkan"},{"id":"opt_4","text":"Editor meminta penulis membuat judul yang jauh lebih sensasional agar viral"}],"audio_text":"Because food-frequency questionnaires rely on uncorroborated memory recall over twelve months, causal headlines like ''Seed Oils Trigger Inflammation'' aren''t justified—the findings warrant caution."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Menghubungkan kelemahan instrumen (''uncorroborated memory recall'') dengan tuntutan ''warrant caution''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000820', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'writing', 'sentence_builder', 'Susun kalimat kritik tinjauan pustaka (*literature review*) tingkat C2:', '{"romaji":"/ˈɡɪvən ə ˈpɔːsəti ʌv ˈdiːp ˈoʊʃən ˈsɛnsərz ˈɜːrli ˌsɜːrkjəˈleɪʃən ˈmɑːdəlz ˈwɔːrənt kənˈsɪdərəbəl/","tokens":["warrants caution","of deep-ocean sensors,","Given a paucity","paucities into","warrant considerable","early circulation models","methodological caution."],"target_translation":"Mengingat minimnya sensor laut dalam, model-model sirkulasi awal menuntut kehati-hatian metodologis yang tinggi."}'::jsonb, '["Given a paucity","of deep-ocean sensors,","early circulation models","warrant considerable","methodological caution."]'::jsonb, NULL, NULL, 'Subjek jamak ''models'' mengambil kata kerja ''warrant'' + ''considerable methodological caution''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000821', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'speaking', 'speaking_repeat', 'Ucapkan kalimat standar replikasi sains berikut dengan artikulasi lima suku kata ''uncorroborated'' yang mantap:', '{"romaji":"/ˈsɪŋɡəl sɔːrs ɪnˈtɛlədʒəns rɪˈpɔːrts rɪˈmeɪn ˌʌnkəˈrɑːbəˌreɪtɪd ʌnˈtɪl ˈvɛrəˌfaɪd baɪ ˈsætəˌlaɪt ˈɪmɪdʒri/","display_text":"Single-source intelligence reports remain uncorroborated until verified by satellite imagery.","phonetic_breakdown":["Single-source intelligence reports","remain uncorroborated","until verified","by satellite imagery."]}'::jsonb, '{"expected_transcript":"Single-source intelligence reports remain uncorroborated until verified by satellite imagery."}'::jsonb, NULL, NULL, 'Pecah perlahan lalu sambungkan: un-cor-ROB-o-rat-ed (/ˌʌnkəˈrɑːbəˌreɪtɪd/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000822', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Pilih kata sifat untuk klaim kronik kuno yang tidak memiliki bukti arkeologis pembanding:', '{"options":["uncorroborated","untenable","laudable","preemptive"],"translation":"Angka jumlah pasukan menurut Herodotus tetap belum terkonfirmasi silang oleh loh tanah liat administrasi Persia dari masa pemerintahan yang sama.","sentence_template":"Herodotus''s troop figures remain [blank] by Persian administrative clay tablets from the same reign."}'::jsonb, '{"selected":"uncorroborated"}'::jsonb, NULL, NULL, '''Uncorroborated by [independent source]'' adalah standar emas historiografi kritis.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000823', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'listening', 'listening_choice', 'Dengarkan kuliah TOEFL Integrated (Arkeologi vs. Teks Kuno). Bagaimana dosen menggunakan konsep *evidential distancing*?', '{"options":[{"id":"opt_1","text":"Penggalian arkeologis membuktikan keempat puluh kota dibakar habis dalam satu musim panas"},{"id":"opt_2","text":"Kronik tersebut mengklaim menaklukkan 40 kota dalam satu musim panas, padahal penggalian di situs benteng yang diduga itu justru menunjukkan lapisan tembikar damai tanpa jeda"},{"id":"opt_3","text":"Tidak ditemukan satu pun pecahan tembikar di keempat puluh kota tersebut"},{"id":"opt_4","text":"Profesor menelan mentah-mentah seluruh angka penaklukan di dalam kronik kuno tersebut"}],"audio_text":"While the chronicle purports to list forty tributary cities conquered in a single summer, excavating those putative fortress sites reveals uninterrupted peaceful pottery layers!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan perpaduan maut C2 di kuliah TOEFL: ''purports to list'' + ''those putative fortress sites'' + bukti fisik tandingan!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000824', 'e5100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000055', 'writing', 'sentence_builder', 'Susun kalimat evaluasi investasi bioteknologi berikut:', '{"romaji":"/ˌpriːˈklɪnɪkəl lɔːnˈdʒɛvəti kleɪmz pərˈpɔːrtɪŋ tə ˈdʌbəl ˈlaɪfˌspæn ˈwɔːrənt ɪkˈstriːm ˈskɛptəˌsɪzəm/","tokens":["skepticism from institutional","allocators.","warrants extreme","lifespan warrant extreme","purported doubling","purporting to double","Preclinical longevity claims"],"target_translation":"Klaim umur panjang praklinis yang mengaku mampu menggandakan masa hidup menuntut skeptisisme tinggi dari pengelola dana institusional."}'::jsonb, '["Preclinical longevity claims","purporting to double","lifespan warrant extreme","skepticism from institutional","allocators."]'::jsonb, NULL, NULL, 'Partisip aktif ''purporting to double lifespan'' memodifikasi subjek jamak ''claims'' (''warrant'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000825', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih bentuk infinitif pelaporan untuk lukisan yang diperkirakan DIPALSUKAN pada dekade 1920-an:', '{"options":["to have","having been","to be","to have been"],"translation":"Menyusul spektroskopi pigmen, lukisan potret tersebut kini diyakini telah dilukis pada dekade 1920-an alih-alih zaman Renaisans.","sentence_template":"Following pigment spectroscopy, the portrait is now believed [blank] painted in the 1920s rather than the Renaissance."}'::jsonb, '{"selected":"to have been"}'::jsonb, NULL, NULL, 'Subjek pasif (''the portrait'') + kejadian masa lalu (''in the 1920s'') mewajibkan ''to have been + V3 (painted)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000826', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih kata yang menandai sikap skeptis penulis terhadap klaim aplikasi deteksi kebohongan suara:', '{"options":["corroborates to","complies to","ushered in","purports to"],"translation":"Alat pusat panggilan tersebut mengklaim mendeteksi kecurangan asuransi dari getaran mikro suara, kendati studi tinjauan sejawat telah mematahkan analisis stres suara.","sentence_template":"The call-center tool [blank] detect insurance fraud from vocal micro-tremors, despite peer-reviewed studies debunking voice stress analysis."}'::jsonb, '{"selected":"purports to"}'::jsonb, NULL, NULL, '''Purports to + V1'' secara tajam menandai klaim yang bertentangan dengan bukti ilmiah.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000827', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'listening', 'listening_choice', 'Evaluasi Unit 5 — Dengarkan analisis soal TOEFL Reading tentang fungsi kata ''ostensibly'' dalam paragraf sejarah pajak garam.', '{"options":[{"id":"opt_1","text":"Stabilitas harga pangan hanyalah dalih publik di permukaan, sedangkan tujuan aslinya adalah membiayai ekspansi angkatan laut"},{"id":"opt_2","text":"Sejarawan memuji pemerintah karena tidak pernah membiayai ekspansi angkatan laut"},{"id":"opt_3","text":"Monopoli garam terbukti menurunkan harga pangan musim dingin tanpa menambah pajak negara"},{"id":"opt_4","text":"Kata ''ostensibly'' berarti kebijakan tersebut disetujui secara bulat oleh petani garam"}],"audio_text":"By writing that the salt monopoly was ''ostensibly'' created to stabilize winter food prices, the historian implies price stability was merely a public pretext—its real purpose was funding naval expansion."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menguasai inferensi kata ''ostensibly'' (= alasan luar sebagai dalih / *pretext*).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000828', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'writing', 'sentence_builder', 'Evaluasi Unit 5 — Susun kalimat laporan investigasi pelanggaran sanksi dengan ''is alleged to have'':', '{"romaji":"/ðə ˈmærəˌtaɪm ˈbroʊkər ɪz əˈlɛdʒd tə həv ˈfɔːlsəˌfaɪd trænˈspɑːndər koʊˈɔːrdənəts əˈkrɔːs θriː/","tokens":["to have been","have falsified transponder","coordinates across three","tanker voyages.","is alleged to","The maritime broker","alleging to"],"target_translation":"Pialang maritim tersebut diduga telah memalsukan koordinat transponder dalam tiga pelayaran kapal tanker."}'::jsonb, '["The maritime broker","is alleged to","have falsified transponder","coordinates across three","tanker voyages."]'::jsonb, NULL, NULL, 'Pelaku aktif (''broker'') + aksi lampau -> ''is alleged to have falsified''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000829', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'speaking', 'speaking_repeat', 'Evaluasi Unit 5 — Ucapkan kalimat tinjauan metodologi ilmiah berikut dengan lancar:', '{"romaji":"/ˈɡɪvən ə ˈpɔːsəti ʌv ˌlɑːndʒəˈtuːdənəl ˈkoʊhɔːrts ðiːz ˈpjuːtətɪv ˈbaɪoʊˌmɑːrkərz ˈwɔːrənt ˈkɔːʃən/","display_text":"Given a paucity of longitudinal cohorts, these putative biomarkers warrant caution.","phonetic_breakdown":["Given a paucity","of longitudinal cohorts,","these putative biomarkers","warrant caution."]}'::jsonb, '{"expected_transcript":"Given a paucity of longitudinal cohorts, these putative biomarkers warrant caution."}'::jsonb, NULL, NULL, 'Lafalkan ''longitudinal'' ala AS /ˌlɑːndʒəˈtuːdənəl/ (tanpa /j/ sesudah ''t''!).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000830', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'reading', 'fill_blank', 'Evaluasi Unit 5 — Pilih kolokasi idiom yang tepat untuk menolak menerima klaim sepihak tanpa audit:', '{"options":["out of hand","to fruition","in its wake","at face value"],"translation":"Ekonom antipakat jarang menelan mentah-mentah janji efisiensi pasca-merjer tanpa memeriksa data harga historis.","sentence_template":"Antitrust economists rarely take post-merger efficiency promises [blank] without examining historical price data."}'::jsonb, '{"selected":"at face value"}'::jsonb, NULL, NULL, '''Take [promises/claims] at face value'' berarti mempercayai begitu saja tampilan luar klaim.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000831', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'listening', 'listening_choice', 'Evaluasi Unit 5 — Dengarkan kabar pasar modal pagi ini tentang perusahaan semikonduktor. Apa status kesepakatan saat ini?', '{"options":[{"id":"opt_1","text":"Perusahaan cip secara resmi membatalkan seluruh rencana investasi di Arizona pagi ini"},{"id":"opt_2","text":"Perusahaan cip tersebut dikabarkan sedang merampungkan usaha patungan pabrik pengecoran senilai $10 miliar, meski belum diumumkan resmi"},{"id":"opt_3","text":"Harga saham anjlok enam persen karena pabrik mengalami kerugian"},{"id":"opt_4","text":"Pabrik pengecoran di Arizona tersebut sudah beroperasi penuh sejak lima tahun lalu"}],"audio_text":"Shares jumped six percent in pre-market trading as the chipmaker is rumored to be finalizing a ten-billion-dollar foundry joint venture in Arizona."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Infinitif progresif ''is rumored to be finalizing'' menunjukkan proses yang dikabarkan sedang berlangsung saat ini.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000832', 'e5100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000055', 'writing', 'sentence_builder', 'Evaluasi Unit 5 — Susun kalimat penilaian bukti lemah berikut:', '{"romaji":"/wɪˈðaʊt ˌɪndɪˈpɛndənt ˌrɛplɪˈkeɪʃən ˈsoʊʃəl ˈmiːdiə ˌproʊdʌkˈtɪvəti ˌtɛstəˈmoʊniəlz rɪˈmeɪn ˌʌnkəˈrɑːbəˌreɪtɪd/","tokens":["anecdotal at best.","at best anecdotal","uncorroborating","Without independent replication,","remain uncorroborated and","social-media productivity testimonials"],"target_translation":"Tanpa replikasi independen, testimoni produktivitas di media sosial tetap belum terkonfirmasi silang dan paling banter hanya anekdotal."}'::jsonb, '["Without independent replication,","social-media productivity testimonials","remain uncorroborated and","anecdotal at best."]'::jsonb, NULL, NULL, 'Mengikat ''uncorroborated'' dan ''anecdotal at best'' sebagai predikat evaluasi bukti yang presisi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000833', 'e5100001-0000-4000-8000-000000000103', NULL, 'reading', 'fill_blank', 'Pilih ungkapan subjunctive klasik untuk beralih tegas dari alasan masa lalu ke kewajiban saat ini:', '{"options":["be that as it may","is that as it may","come what might","suffices it to say"],"translation":"Gejolak mata uang memang menekan margin Eropa kita; biarpun demikian, menunda pembayaran kewajiban utang tidak mungkin dilakukan.","sentence_template":"Currency headwinds certainly compressed our European margins; [blank], delaying debt service is out of the question."}'::jsonb, '{"selected":"be that as it may"}'::jsonb, NULL, NULL, '''Be that as it may,'' mengakui fakta klausa pertama lalu memotong alasan lanjutan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000834', 'e5100001-0000-4000-8000-000000000103', NULL, 'reading', 'fill_blank', 'Pilih bentuk subjunctive murni tanpa ''-s'' untuk merangkum hal rahasia secara singkat:', '{"options":["suffice it to say","suffices it to say","sufficed to say","it suffice saying"],"translation":"Kerahasiaan klien mencegah saya menyebutkan nama pengakuisisi; cukuplah dikatakan bahwa pembicaraan integrasi sudah berjalan jauh.","sentence_template":"Client privilege prevents me from naming the acquirer; [blank] that integration talks are already well advanced."}'::jsonb, '{"selected":"suffice it to say"}'::jsonb, NULL, NULL, 'Bentuk beku yang benar adalah ''suffice it to say (that)...'' dengan verba dasar ''suffice''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000835', 'e5100001-0000-4000-8000-000000000103', NULL, 'listening', 'listening_choice', 'Dengarkan komentar anggota senior dewan pengawas kepada direktur pemasaran baru. Apa fungsi pembuka ''Far be it from me to micromanage''?', '{"options":[{"id":"opt_1","text":"Menyampaikan peringatan kepatuhan hukum yang sangat tegas sembari tetap menjaga kesantunan agar tidak terkesan mencampuri ranah kreatif"},{"id":"opt_2","text":"Menyatakan bahwa ia ingin mengambil alih penulisan seluruh takarir Instagram harian"},{"id":"opt_3","text":"Mengaku tidak memahami aturan Badan Pengawas Obat dan Makanan AS"},{"id":"opt_4","text":"Memuji slogan ''kesembuhan klinis terjamin'' sebagai ide yang aman secara hukum"}],"audio_text":"Far be it from me to micromanage creative copy, yet promising ''guaranteed clinical cures'' on Instagram will invite an FDA warning letter by Friday."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Far be it from me to V1, yet...'' membungkus koreksi keras dalam kemasan kerendahan hati retoris.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000836', 'e5100001-0000-4000-8000-000000000103', NULL, 'writing', 'sentence_builder', 'Susun kalimat komitmen ketahanan lembaga keuangan dengan ''Come what may,'':', '{"romaji":"/kʌm wʌt meɪ ðə ˈklɪrɪŋˌhaʊs meɪnˈteɪnz ˈtrɪpəl rɪˈdʌndənt ˈsɛtəlmənt ˈlɛdʒərz əˈkrɔːs ˈsaɪzmɪk/","tokens":["Comes what may","across seismic zones.","Come what may,","maintaining ledgers","the clearinghouse maintains","triple-redundant settlement ledgers"],"target_translation":"Apa pun yang terjadi, lembaga kliring tersebut memelihara buku besar penyelesaian rangkap tiga lintas zona gempa."}'::jsonb, '["Come what may,","the clearinghouse maintains","triple-redundant settlement ledgers","across seismic zones."]'::jsonb, NULL, NULL, '''Come what may,'' (= whatever happens) diawali verba subjunctive murni ''Come''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000837', 'e5100001-0000-4000-8000-000000000103', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat transisi rapat eksekutif berikut dengan ritme ''Be that as it may'' yang mulus:', '{"romaji":"/ˈfɔːrˌkæstɪŋ ˈmɑːdəlz mɪst ðə sɜːrdʒ biː ðæt æz ɪt meɪ ˈhɑːspɪtəl kəˈpæsəti hɛld fɜːrm/","display_text":"Forecasting models missed the surge; be that as it may, hospital capacity held firm.","phonetic_breakdown":["Forecasting models","missed the surge;","be that as it may,","hospital capacity held firm."]}'::jsonb, '{"expected_transcript":"Forecasting models missed the surge; be that as it may, hospital capacity held firm."}'::jsonb, NULL, NULL, 'Ucapkan ''be that as it may'' sebagai satu kesatuan kelompok napas cepat (/biː ˈðætəzɪt ˈmeɪ/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000838', 'e5100001-0000-4000-8000-000000000103', NULL, 'reading', 'fill_blank', 'Lengkapi pembuka kerendahan hati retoris sebelum mengkritik metodologi rekan:', '{"options":["Long live it","Be far it","Far be it","Far is it"],"translation":"Sama sekali bukan maksud orang luar untuk mempertanyakan tradisi departemen, namun penyalinan CSV manual mengundang galat pembulatan diam-diam.","sentence_template":"[blank] from an outsider to question departmental tradition, but manual CSV copying invites silent rounding errors."}'::jsonb, '{"selected":"Far be it"}'::jsonb, NULL, NULL, 'Formula baku: ''Far be it from [person] to + V1''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000839', 'e5100001-0000-4000-8000-000000000103', NULL, 'listening', 'listening_choice', 'Dengarkan kesaksian pakar keamanan siber di depan komite parlemen. Mengapa ia menggunakan ''suffice it to say''?', '{"options":[{"id":"opt_1","text":"Meminta parlemen menghentikan seluruh penggunaan internet nasional"},{"id":"opt_2","text":"Menyimpulkan bahwa seluruh router tepi sudah aman tanpa perlu pembaruan"},{"id":"opt_3","text":"Membagikan kode serangan lengkap kepada publik selama siaran langsung"},{"id":"opt_4","text":"Menolak membeberkan kode celah keamanan di sidang terbuka demi keamanan, namun menegaskan inti bahayanya bahwa router tepi masih sangat rentan"}],"audio_text":"Revealing exact exploit payloads in an open hearing would hand blueprints to copycats; suffice it to say that unpatched edge routers remain critically exposed."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Penggunaan ''suffice it to say'' paling tepat saat pembicara membatasi rincian teknis/rahasia demi fokus ke simpulan utama.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000840', 'e5100001-0000-4000-8000-000000000103', NULL, 'writing', 'sentence_builder', 'Susun kalimat rangkuman diplomasi berikut:', '{"romaji":"/nɪˌɡoʊʃiˈeɪʃənz strɛtʃt pæst dɔːn səˈfaɪs ɪt tə seɪ ˈniːðər ˌdɛləˈɡeɪʃən wɔːkt əˈweɪ/","tokens":["to say, neither","delegation walked away","empty-handed.","walking away","Negotiations stretched past","suffices it","dawn; suffice it"],"target_translation":"Perundingan molor melewati fajar; cukuplah dikatakan bahwa tidak satu pun delegasi pulang dengan tangan hampa."}'::jsonb, '["Negotiations stretched past","dawn; suffice it","to say, neither","delegation walked away","empty-handed."]'::jsonb, NULL, NULL, '''Suffice it to say,'' merangkum hasil perundingan panjang secara padat.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000841', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Pilih sisipan subjunctive alternatif untuk merinci kata benda tunggal ''Every algorithmic model'':', '{"options":["is it","be they","be it","whether it"],"translation":"Setiap model algoritmik—baik berbobot terbuka maupun tertutup—memerlukan pengujian tim merah khusus domain sebelum digunakan di rumah sakit.","sentence_template":"Every algorithmic model—[blank] open-weights or proprietary—requires domain-specific red-teaming before hospital use."}'::jsonb, '{"selected":"be it"}'::jsonb, NULL, NULL, 'Rujukan tunggal (''Every algorithmic model'') berpasangan dengan inversi subjunctive ''be it ... or ...''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000842', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Pilih sisipan pelunak metafora (*metaphor hedge*) ketika mengibaratkan enzim sebagai ''gunting molekuler'':', '{"options":["come what may","so be it","far be it","as it were"],"translation":"Protein Cas9 bekerja layaknya gunting molekuler terprogram, kalau boleh diibaratkan demikian, memotong untai DNA sasaran di titik presisi.","sentence_template":"Cas9 proteins function as programmable molecular scissors, [blank], snipping target DNA strands at precise loci."}'::jsonb, '{"selected":"as it were"}'::jsonb, NULL, NULL, ''', as it were,'' memberi sinyal elok bahwa istilah ''molecular scissors'' adalah kiasan figuratif.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000843', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'listening', 'listening_choice', 'Dengarkan pernyataan tegas ketua komisi antikorupsi saat menolak kompromi pengawasan pengadaan. Apa makna penutup ''so be it''?', '{"options":[{"id":"opt_1","text":"Komisi meminta maaf karena telah memperlambat pengadaan kendaraan dinas"},{"id":"opt_2","text":"Ketua komisi setuju mempercepat pembelian mobil mewah tanpa lelang terbuka"},{"id":"opt_3","text":"Sistem e-katalog publik akan segera dihapuskan demi kenyamanan pejabat"},{"id":"opt_4","text":"Jika transparansi e-katalog memang menghambat pembelian mobil mewah pejabat, konsekuensi itu diterima sepenuhnya tanpa penyesalan"}],"audio_text":"If insisting on public e-catalog bidding slows down luxury vehicle purchases for ministry officials, then frankly, so be it."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''If [consequence], (then) so be it'' mengekspresikan keteguhan prinsip menghadapi konsekuensi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000844', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'writing', 'sentence_builder', 'Susun kalimat subjunctive alternatif jamak dengan ''be they'':', '{"romaji":"/ɔːl ˈkoʊstəl ˈmɛɡəˌsɪtiz biː ðeɪ ɪn ˈeɪʒə ɔːr ði əˈmɛrɪkəz kənˈfrʌnt lænd səbˈsaɪdəns/","tokens":["subsidence.","be they in","Asia or the","All coastal megacities,","are they in","be it in","Americas, confront land"],"target_translation":"Seluruh megakota pesisir, baik yang berada di Asia maupun di Benua Amerika, menghadapi penurunan muka tanah."}'::jsonb, '["All coastal megacities,","be they in","Asia or the","Americas, confront land","subsidence."]'::jsonb, NULL, NULL, 'Karena ''All coastal megacities'' jamak, gunakan ''be they ... or ...''; perhatikan lafal ''subsidence'' /səbˈsaɪdəns/.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000845', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'speaking', 'speaking_repeat', 'Ucapkan kalimat prinsip tata kelola data berikut dengan jeda tanda pisah yang jelas:', '{"romaji":"/ˈɛvri ˈsɪtəzən ˈrɛkərd biː ɪt tæks hɛlθ ɔːr ˌbaɪoʊˈmɛtrɪk dɪˈmændz ɪnˈkrɪpʃən æt rɛst/","display_text":"Every citizen record—be it tax, health, or biometric—demands encryption at rest.","phonetic_breakdown":["Every citizen","record—be it tax,","health, or biometric—demands","encryption at rest."]}'::jsonb, '{"expected_transcript":"Every citizen record—be it tax, health, or biometric—demands encryption at rest."}'::jsonb, NULL, NULL, 'Tekankan tiga serangkai ''tax, health, or biometric'' di dalam aposisi ''be it''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000846', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Pilih bentuk kata kerja sesudah ''Heaven forbid that...'' dalam gaya formal C2:', '{"options":["was compromised","be compromised","is compromising","compromises"],"translation":"Kami memelihara cadangan dingin luring agar—jangan sampai terjadi akun cloud utama kita tersusupi—pemulihan memakan waktu berjam-jam, bukan berminggu-minggu.","sentence_template":"We maintain offline cold backups so that—Heaven forbid that our primary cloud account [blank]—recovery takes hours, not weeks."}'::jsonb, '{"selected":"be compromised"}'::jsonb, NULL, NULL, 'Klausa ''Heaven forbid that + Subject'' mengambil Present Subjunctive pasif ''be compromised''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000847', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'listening', 'listening_choice', 'Dengarkan kuliah sejarah filsafat sains TOEFL tentang istilah ''ether'' abad ke-19. Mengapa dosen menyisipkan ''as it were''?', '{"options":[{"id":"opt_1","text":"Fisikawan Victoria menolak gagasan bahwa cahaya bergerak sebagai gelombang"},{"id":"opt_2","text":"Dosen menggunakan kiasan ''samudra kosmik tak kasatmata'' untuk membantu mahasiswa membayangkan konsep eter abad ke-19"},{"id":"opt_3","text":"Michelson dan Morley berhasil membuktikan bahwa ruang angkasa dipenuhi air laut"},{"id":"opt_4","text":"Istilah ''as it were'' berarti eksperimen tersebut dilakukan di masa depan"}],"audio_text":"Victorian physicists imagined light waves rippling through an invisible cosmic ocean—luminiferous aether, as it were—until Michelson and Morley proved no such medium existed."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Mengenali '', as it were,'' sebagai sinyal analogi ilustratif dalam kuliah akademik.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000848', 'e5100001-0000-4000-8000-000000000104', 'e2000001-0000-4000-8000-000000000056', 'writing', 'sentence_builder', 'Susun kalimat prinsip kebebasan akademik dengan penutup ''so be it'':', '{"romaji":"/ɪf ˈpʌblɪʃɪŋ ˈnɛɡətɪv ˌrɛplɪˈkeɪʃən rɪˈzʌlts ˈrʌfəlz prɛˈstɪdʒəs ˈfɛðərz ðɛn soʊ biː ɪt/","tokens":["If publishing negative","so is it","replication results ruffles","so be it.","prestigious feathers, then","it be so"],"target_translation":"Jika menerbitkan hasil replikasi negatif menyinggung perasaan tokoh-tokoh bergengsi, biarlah demikian."}'::jsonb, '["If publishing negative","replication results ruffles","prestigious feathers, then","so be it."]'::jsonb, NULL, NULL, 'Idiom ''ruffle feathers'' (membuat pihak mapan terusik) ditutup tegas dengan ''then so be it''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000849', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Pilih frasa keberatan resmi ketika laporan lawan salah menggambarkan posisi tim Anda:', '{"options":["take at face value","come to fruition with","take exception to","usher in"],"translation":"Meskipun kami menyambut masukan audit yang membangun, kami wajib menyatakan keberatan tegas atas sindiran bahwa tambalan sengaja ditunda.","sentence_template":"While we welcome constructive audit feedback, we must [blank] the insinuation that patches were deliberately delayed."}'::jsonb, '{"selected":"take exception to"}'::jsonb, NULL, NULL, '''Take exception to [a claim/insinuation]'' menolak tuduhan secara bermartabat dan tegas.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000850', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Pilih idiom litotes yang berarti ''secara sangat lugas dan tanpa keraguan sedikit pun'':', '{"options":["as it were","anecdotal at best","if any","in no uncertain terms"],"translation":"Menyusul insiden nyaris celaka di Landas Pacu 28, pemandu lalu lintas udara menginstruksikan pilot secara sangat tegas untuk membacakan ulang setiap izin berhenti.","sentence_template":"Following the near-miss on Runway 28, air traffic control instructed pilots [blank] to read back every hold-short clearance."}'::jsonb, '{"selected":"in no uncertain terms"}'::jsonb, NULL, NULL, '''In no uncertain terms'' menekankan komunikasi otoritatif tanpa ruang salah tafsir.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000851', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'listening', 'listening_choice', 'Dengarkan pernyataan anggota independen komite risiko pada rapat direksi bank. Mengapa ia mengucapkan ''let the record reflect''?', '{"options":[{"id":"opt_1","text":"Meminta sekretaris menghapus hasil pemodelan risiko dari dokumen rapat"},{"id":"opt_2","text":"Mengusulkan agar rapat ditunda tanpa pemungutan suara"},{"id":"opt_3","text":"Mendukung penuh pelonggaran rasio kredit tanpa catatan keberatan apa pun"},{"id":"opt_4","text":"Memastikan risalah resmi rapat mencatat peringatan tertulis tim risiko sebelum pemungutan suara dilakukan"}],"audio_text":"Before we vote on loosening loan-to-value ratios, let the record reflect that risk modeling flagged a nineteen-percent default spike under stress scenarios."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Let the record reflect that...'' memastikan akuntabilitas tata kelola tercatat secara hukum.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000852', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'writing', 'sentence_builder', 'Susun kalimat pengingat konsekuensi logis dengan ''Needless to say,'':', '{"romaji":"/ˈpraɪvət kiːz rɪˈmeɪn ˈɪnˌsaɪd ˈhɑːrdˌwɛr ˈmɑːdʒuːlz ˈniːdləs tə seɪ ˈluːzɪŋ ɔːl siːd/","tokens":["phrases forfeits access.","losing all seed","Private keys remain","needless to say,","needlessly saying","inside hardware modules;","forfeit access"],"target_translation":"Kunci privat tersimpan di dalam modul perangkat keras; tak perlu dikatakan lagi, kehilangan seluruh frasa benih berarti kehilangan akses selamanya."}'::jsonb, '["Private keys remain","inside hardware modules;","needless to say,","losing all seed","phrases forfeits access."]'::jsonb, NULL, NULL, 'Gerund tunggal ''losing all seed phrases'' diikuti verba tunggal ''forfeits''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000853', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'speaking', 'speaking_repeat', 'Ucapkan kalimat keberatan resmi berikut dengan intonasi tenang namun berwibawa:', '{"romaji":"/aɪ mʌst teɪk rɪˈspɛktfəl ɪkˈsɛpʃən tə ðə ˈprɛmɪs ðæt ˌrɛɡjəˈleɪʃən ˈstaɪfəlz ˈbaɪoʊˌtɛk/","display_text":"I must take respectful exception to the premise that regulation stifles biotech.","phonetic_breakdown":["I must take","respectful exception to","the premise that","regulation stifles biotech."]}'::jsonb, '{"expected_transcript":"I must take respectful exception to the premise that regulation stifles biotech."}'::jsonb, NULL, NULL, 'Menambahkan ''respectful'' (''take respectful exception to'') melunakkan nada interpersonal sambil mempertahankan ketajaman intelektual.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000854', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Pilih struktur risalah resmi rapat dewan komisaris AS:', '{"options":["reflected to","reflect that","reflecting what","to reflect"],"translation":"Mohon risalah rapat mencatat bahwa Dr. Pratama abstain dari pemungutan suara karena afiliasi hibah universitas yang telah dideklarasikan.","sentence_template":"Let the minutes [blank] Dr. Pratama abstained from voting due to a declared university grant affiliation."}'::jsonb, '{"selected":"reflect that"}'::jsonb, NULL, NULL, 'Kausatif imperatif ''Let + Object (the minutes/record) + bare infinitive (reflect that...)''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000855', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'listening', 'listening_choice', 'Dengarkan rangkuman dosen hukum konstitusi tentang opini berbeda (*dissenting opinion*) hakim agung. Bagaimana dua ungkapan Unit 6 berpadu?', '{"options":[{"id":"opt_1","text":"Perlindungan hukum hanya berlaku bagi kelompok kelas ekonomi tertentu"},{"id":"opt_2","text":"Terlepas dari argumen mayoritas saat itu, Hakim Harlan menulis secara sangat tegas bahwa perlindungan setara tidak menoleransi hierarki kasta maupun kelas"},{"id":"opt_3","text":"Hakim Harlan menyetujui sepenuhnya argumen mayoritas tanpa catatan berbeda"},{"id":"opt_4","text":"Opini tersebut ditulis dengan bahasa kabur yang menghindari sikap tegas"}],"audio_text":"Be that as it may, Justice Harlan wrote in no uncertain terms that equal protection tolerates neither caste nor class hierarchies under the law."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perpaduan ''Be that as it may,'' dan ''in no uncertain terms'' menghidupkan prosa hukum bersejarah.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000856', 'e5100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000056', 'writing', 'sentence_builder', 'Susun kalimat peringatan kepatuhan ekspor berikut:', '{"romaji":"/ˈkaʊnsəl rɪˈmaɪndɪd seɪlz dəˈrɛktərz ɪn noʊ ʌnˈsɜːrtən tɜːrmz ðæt ˈduːəl juːs ˈɑːptɪks/","tokens":["uncertainly terms","uncertain terms that","Counsel reminded sales","dual-use optics require","export licenses.","directors in no","requires export"],"target_translation":"Penasihat hukum mengingatkan para direktur penjualan dengan sangat tegas bahwa optik fungsi-ganda memerlukan izin ekspor."}'::jsonb, '["Counsel reminded sales","directors in no","uncertain terms that","dual-use optics require","export licenses."]'::jsonb, NULL, NULL, '''Remind [someone] in no uncertain terms that + Clause'' memperjelas kepatuhan hukum.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000857', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Pilih sisipan subjunctive alternatif untuk kata benda jamak ''Regional lenders'':', '{"options":["be it","be they","are they","so be"],"translation":"Pemberi pinjaman daerah—baik bank milik negara maupun koperasi pedesaan—wajib mencadangkan dana menghadapi keterlambatan panen akibat El Niño.","sentence_template":"Regional lenders—[blank] state-owned banks or rural cooperatives—must provision against El Niño harvest delays."}'::jsonb, '{"selected":"be they"}'::jsonb, NULL, NULL, 'Karena rujukannya jamak (''Regional lenders''), bentuk subjunctive alternatif yang selaras adalah ''be they ... or ...''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000858', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Pilih bentuk subjunctive beku yang tepat untuk beralih dari kendala masa lalu:', '{"options":["far be it","is that as it might","as it were that","be that as it may"],"translation":"Purwarupa awal memang sempat mengalami panas berlebih di ruang lembap; biarpun demikian, Versi 4 lulus uji ketahanan tropis dengan nol gangguan.","sentence_template":"Early prototypes certainly overheated in humid chambers; [blank], Version 4 passed tropical endurance testing with zero faults."}'::jsonb, '{"selected":"be that as it may"}'::jsonb, NULL, NULL, '''Be that as it may,'' mengakui kendala historis lalu mengarahkan fokus ke fakta terbaru.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000859', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'listening', 'listening_choice', 'Evaluasi Unit 6 — Dengarkan jawaban CFO saat ditanya analis mengenai rincian kontrak klien pertahanan. Mengapa ia menggunakan ''suffice it to say''?', '{"options":[{"id":"opt_1","text":"CFO membacakan daftar harga rahasia tiap kementerian secara terperinci"},{"id":"opt_2","text":"Perusahaan memutuskan keluar dari seluruh proyek sektor publik"},{"id":"opt_3","text":"Aturan klasifikasi keamanan melarang perincian per item, sehingga CFO cukup merangkum fakta utamanya bahwa antrean kontrak cloud negara tumbuh 40%"},{"id":"opt_4","text":"Antrean kontrak cloud negara mengalami penurunan empat puluh persen tahun ini"}],"audio_text":"Security classifications bar me from breaking down contract line items; suffice it to say that sovereign cloud backlog grew forty percent year over year."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Konteks paling otentik bagi ''suffice it to say that...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000860', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'writing', 'sentence_builder', 'Evaluasi Unit 6 — Susun kalimat kerendahan hati retoris ''Far be it from me'':', '{"romaji":"/fɑːr biː ɪt frʌm miː tə ˈsɛkənd ɡɛs ˈloʊkəl klɪˈnɪʃənz jɛt ˌæntibaɪˈɑːtɪk ˈstuːərdˌʃɪp/","tokens":["second-guess local clinicians,","yet antibiotic stewardship","remains urgent.","second-guessing to","Far is it","from me to","Far be it"],"target_translation":"Sama sekali bukan maksud saya meragukan pertimbangan klinisi daerah, namun penatagunaan antibiotik tetaplah mendesak."}'::jsonb, '["Far be it","from me to","second-guess local clinicians,","yet antibiotic stewardship","remains urgent."]'::jsonb, NULL, NULL, '''Far be it from me to + V1, yet...'' menjaga rasa hormat sejawat medis.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000861', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'speaking', 'speaking_repeat', 'Evaluasi Unit 6 — Ucapkan kalimat ketegasan prinsip tata kelola berikut:', '{"romaji":"/ɪf ɪnˈfɔːrsɪŋ ˈseɪfti ˈɔːdɪts dɪˈleɪz ˈaʊər lɔːntʃ baɪ tuː wiːks soʊ biː ɪt/","display_text":"If enforcing safety audits delays our launch by two weeks, so be it.","phonetic_breakdown":["If enforcing","safety audits delays","our launch by two weeks,","so be it."]}'::jsonb, '{"expected_transcript":"If enforcing safety audits delays our launch by two weeks, so be it."}'::jsonb, NULL, NULL, 'Beri jeda mantap sebelum menutup dengan tiga kata tegas ''SO BE IT''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000862', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'reading', 'fill_blank', 'Evaluasi Unit 6 — Pilih pelunak metafora C2 saat penulis mengibaratkan rantai pasok sebagai ''sistem saraf'':', '{"options":["as it were","come what may","in no uncertain terms","needless to say"],"translation":"Telemetri rantai dingin bekerja layaknya sistem saraf pusat distributor, kalau boleh diibaratkan demikian, memperingatkan gudang sebelum pembusukan dimulai.","sentence_template":"Cold-chain telemetry acts as the distributor''s central nervous system, [blank], alerting warehouses before spoilage begins."}'::jsonb, '{"selected":"as it were"}'::jsonb, NULL, NULL, ''', as it were,'' menandai perumpamaan figuratif ''central nervous system''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000863', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'listening', 'listening_choice', 'Evaluasi Unit 6 — Dengarkan tanggapan peneliti utama dalam sidang terbuka jurnal ilmiah. Terhadap hal apa peneliti tersebut ''takes exception''?', '{"options":[{"id":"opt_1","text":"Peneliti mengakui telah lupa menimbang berat katoda selama eksperimen"},{"id":"opt_2","text":"Tabel S4 memang sengaja dihapus dari lampiran makalah"},{"id":"opt_3","text":"Peneliti menolak laboratorium lain mereplikasi studi baterainya"},{"id":"opt_4","text":"Peneliti berkeberatan tegas terhadap klaim Peninjau 2 bahwa berat katoda disembunyikan, sebab Tabel S4 sudah memuatnya hingga satuan mikrogram"}],"audio_text":"We welcome replications of our battery study, though we take strong exception to Reviewer 2''s assertion that cathode weights were omitted—Table S4 lists every cell to the microgram."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Menggunakan ''take strong exception to [false assertion]'' yang langsung dibuktikan dengan rujukan data presisi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000864', 'e5100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000056', 'writing', 'sentence_builder', 'Evaluasi Unit 6 — Susun kalimat komitmen jangka panjang dengan ''Come what may,'':', '{"romaji":"/kʌm wʌt meɪ ɪnˈdaʊmənt ˈfɛloʊˌʃɪps wɪl kənˈtɪnjuː ˈfʌndɪŋ fiːld iˈkɑːlədʒɪsts əˈkrɔːs/","tokens":["continue funding field","Comes what might","continued funded","ecologists across Kalimantan.","endowment fellowships will","Come what may,"],"target_translation":"Apa pun yang terjadi, beasiswa dana abadi tersebut akan terus mendanai peneliti ekologi lapangan di seluruh Kalimantan."}'::jsonb, '["Come what may,","endowment fellowships will","continue funding field","ecologists across Kalimantan."]'::jsonb, NULL, NULL, '''Come what may,'' menegaskan keberlanjutan pendanaan melintasi siklus ekonomi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000865', 'e5100001-0000-4000-8000-000000000107', NULL, 'reading', 'fill_blank', 'Pastikan aposisi pembuka merujuk tepat ke subjek sesudah koma (*appositive alignment*):', '{"options":["regasification is","shipping routes in","forty million tons","the Jurong terminal"],"translation":"Sebagai pasak penyangga krusial logistik LNG Asia Tenggara, terminal Jurong menangani kapasitas regasifikasi empat puluh juta ton per tahun.","sentence_template":"A crucial linchpin of Southeast Asian LNG logistics, [blank] handles forty million tons of regasification capacity annually."}'::jsonb, '{"selected":"the Jurong terminal"}'::jsonb, NULL, NULL, 'Frasa benda ''A crucial linchpin...'' adalah aposisi bagi fasilitas fisik tunggal ''the Jurong terminal'' tepat sesudah koma.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000866', 'e5100001-0000-4000-8000-000000000107', NULL, 'reading', 'fill_blank', 'Ganti rujukan kabur dengan *summative modifier* yang menamai fenomena di klausa pertama:', '{"options":["which it","depleting which","a depletion that","that depletion"],"translation":"Akuifer pinggiran kota turun tiga meter hanya dalam satu musim kemarau—sebuah pengurasan yang memaksa otoritas menghentikan pemompaan industri.","sentence_template":"Suburban aquifers dropped three meters in a single dry season—[blank] forced authorities to halt industrial pumping."}'::jsonb, '{"selected":"a depletion that"}'::jsonb, NULL, NULL, '''—a depletion that + V'' merangkum klausa ''aquifers dropped three meters'' menjadi satu nomina abstrak yang jernih.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000867', 'e5100001-0000-4000-8000-000000000107', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah sejarah perbankan TOEFL tentang krisis Overend, Gurney & Co tahun 1866. Bagaimana profesor menggunakan ''precipitated''?', '{"options":[{"id":"opt_1","text":"Keputusan tersebut menenangkan nasabah di seluruh Lombard Street selama satu dekade"},{"id":"opt_2","text":"Bank of England memberikan talangan tak terbatas kepada Overend Gurney pada Mei 1866"},{"id":"opt_3","text":"Penolakan bantuan darurat oleh Bank of England menjadi keputusan penentu yang langsung memicu penarikan dana besar-besaran secara mendadak"},{"id":"opt_4","text":"Kata ''precipitated'' berarti menunda krisis hingga abad berikutnya"}],"audio_text":"In May 1866, the Bank of England refused emergency assistance to Overend Gurney—a fateful decision that precipitated violent bank runs across Lombard Street."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Summative modifier ''—a fateful decision that precipitated...'' mengikat fakta sejarah dengan penilaian dampaknya.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000868', 'e5100001-0000-4000-8000-000000000107', NULL, 'writing', 'sentence_builder', 'Susun kalimat beraposisi pembuka ''A hallmark of'' berikut:', '{"romaji":"/ə ˈhɔːlˌmɑːrk ʌv ˈpɪr rɪˈvjuːd ˈsaɪəns ˈoʊpən ˈdeɪtə ˈʃɛrɪŋ ækˈsɛləˌreɪts ˌɪndɪˈpɛndənt/","tokens":["A hallmark of","peer-reviewed science, open","independent error detection.","sharing openly","data sharing accelerates","accelerate independent"],"target_translation":"Sebagai ciri khas sains tinjauan sejawat, berbagi data terbuka mempercepat deteksi kesalahan secara independen."}'::jsonb, '["A hallmark of","peer-reviewed science, open","data sharing accelerates","independent error detection."]'::jsonb, NULL, NULL, '''A hallmark of X, [open data sharing]'' menyandingkan definisi nilai dengan subjek tunggalnya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000869', 'e5100001-0000-4000-8000-000000000107', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat *summative modifier* bertanda pisah berikut dengan intonasi turun-tegas:', '{"romaji":"/fərˈtɪləti reɪts fɛl bɪˈloʊ rɪˈpleɪsmənt ə ˌdɛməˈɡræfɪk ʃɪft ðæt riːˈʃeɪpt ˈpɛnʃən mæθ/","display_text":"Fertility rates fell below replacement—a demographic shift that reshaped pension math.","phonetic_breakdown":["Fertility rates","fell below replacement—a","demographic shift that","reshaped pension math."]}'::jsonb, '{"expected_transcript":"Fertility rates fell below replacement—a demographic shift that reshaped pension math."}'::jsonb, NULL, NULL, 'Berhenti sepersekian detik pada tanda pisah ''replacement—'' sebelum menekankan ''a demographic SHIFT''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000870', 'e5100001-0000-4000-8000-000000000107', NULL, 'reading', 'fill_blank', 'Pilih kata kerja kausalitas C2 untuk arti ''memicu terjadinya krisis secara mendadak'':', '{"options":["complied","precipitated","receded","corroborated"],"translation":"Pembatalan mendadak surat kredit impor memicu kelangkaan bahan baku akut di seluruh pabrik garmen.","sentence_template":"Abruptly canceling import letters of credit [blank] acute raw-material shortages across garment factories."}'::jsonb, '{"selected":"precipitated"}'::jsonb, NULL, NULL, '''Precipitate [a crisis/shortage]'' berarti mempercepat jatuhnya peristiwa buruk secara tiba-tiba.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000871', 'e5100001-0000-4000-8000-000000000107', NULL, 'listening', 'listening_choice', 'Dengarkan kiat penyunting senior jurnal kebijakan kepada penulis muda. Mengapa tanda pisah + kata benda penilai begitu disukai editor?', '{"options":[{"id":"opt_1","text":"Tanda pisah tidak pernah boleh dipakai dalam penulisan kebijakan Amerika"},{"id":"opt_2","text":"Editor melarang pemakaian kalimat yang lebih panjang dari sepuluh kata"},{"id":"opt_3","text":"Menamai fenomena secara spesifik (''—a paradox that...'') memberi analisis tajam sekaligus mencegah kalimat menjadi kabur"},{"id":"opt_4","text":"Penulis disarankan mengulang kata '', which was nice'' di setiap akhir paragraf"}],"audio_text":"Instead of tacking '', which was surprising'' onto a thirty-word sentence, name the phenomenon! Write ''—a paradox that puzzled trade economists for decades.''"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Memilih kata benda penilai (*a paradox / a triumph / an oversight*) mengangkat bobot intelektual tulisan secara instan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000872', 'e5100001-0000-4000-8000-000000000107', NULL, 'writing', 'sentence_builder', 'Susun kalimat dengan *summative modifier* untuk analisis infrastruktur:', '{"romaji":"/tuː ˈsʌbˌsiː rɪˈpiːtərz lɔːst ˈpaʊər ˌsaɪməlˈteɪniəsli ə rɛr fɔːlt ðæt ˈaɪsəˌleɪtɪd/","tokens":["banks.","a rare fault","which isolating","Two subsea repeaters","lost power simultaneously—","faults rare","that isolated island"],"target_translation":"Dua penguat sinyal bawah laut kehilangan daya secara bersamaan—sebuah gangguan langka yang mengisolasi perbankan pulau."}'::jsonb, '["Two subsea repeaters","lost power simultaneously—","a rare fault","that isolated island","banks."]'::jsonb, NULL, NULL, 'Lafalkan ''simultaneously'' ala AS dengan vokal awal panjang /ˌsaɪməlˈteɪniəsli/!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000873', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Pilih *resumptive modifier* yang menggemakan kata benda ''architecture'' tanpa membuat kalimat patah (*fragment*) atau *comma splice*:', '{"options":["which architecture it","an architecture that","architectures","it is an architecture"],"translation":"Bank-bank konvensional kesulitan memodernisasi buku besar COBOL inti mereka, sebuah arsitektur yang mendahului kontainer cloud-native empat dekade lebih awal.","sentence_template":"Legacy banks struggle to modernize core COBOL ledgers, [blank] predates cloud-native containers by four decades."}'::jsonb, '{"selected":"an architecture that"}'::jsonb, NULL, NULL, 'Menambahkan ''it is...'' sesudah koma akan memicu *comma splice*; aposisi ''an architecture that...'' menyambung kalimat dengan mulus.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000874', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Lengkapi struktur aposisi + preposisi relatif untuk menggambarkan batas kritis suhu terumbu karang:', '{"options":["above that","which above","above which","above it"],"translation":"Pemutihan makin cepat melewati pemanasan dua derajat—sebuah batas langit-langit termal yang di atasnya sangat sedikit karang bercabang sanggup pulih.","sentence_template":"Bleaching accelerates past two degrees of warming—a thermal ceiling [blank] few branching corals recover."}'::jsonb, '{"selected":"above which"}'::jsonb, NULL, NULL, 'Preposisi ''above'' membutuhkan objek kata ganti relatif ''which'' (bukan *''above that''* atau kalimat lepas *''above it''*).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000875', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'listening', 'listening_choice', 'Dengarkan petikan pidato ilmiah pemenang Nobel Kimia. Teknik pengulangan retoris apa yang membuat kalimatnya begitu mudah diikuti telinga?', '{"options":[{"id":"opt_1","text":"Memotong kalimat menjadi empat kalimat pendek bersubjek ''It''"},{"id":"opt_2","text":"Mengulang kata kunci ''a pathway'' (*resumptive modifier*) sebagai jangkar sebelum menguraikan tiga manfaat beruntun secara paralel"},{"id":"opt_3","text":"Mengulang kata ''industry'' lima kali tanpa kata kerja"},{"id":"opt_4","text":"Menolak penggunaan katalis dalam industri kimia modern"}],"audio_text":"Catalysis gives industry a cleaner pathway—a pathway that slashes reaction temperatures, eliminates toxic solvents, and turns waste carbon into feedstock."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dalam pidato lisan pun, *resumptive modifier* memberi pendengar titik tumpu memori sebelum rincian panjang.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000876', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'writing', 'sentence_builder', 'Susun kalimat *resumptive modifier* yang menggemakan kata ''trust'':', '{"romaji":"/ˈpʌblɪk hɛlθ ˈhɪndʒɪz ɑːn kəˈmjuːnəti trʌst trʌst ɜːrnd ˈsloʊli θruː trænˈspærənt/","tokens":["Public health hinges","trusts earning","trust earned slowly","through transparent local","on community trust,","it is earned","clinics."],"target_translation":"Kesehatan masyarakat bertumpu pada kepercayaan warga, kepercayaan yang diraih perlahan melalui klinik lokal yang transparan."}'::jsonb, '["Public health hinges","on community trust,","trust earned slowly","through transparent local","clinics."]'::jsonb, NULL, NULL, ''', trust earned slowly...'' mengulang kata benda objek ''trust'' lalu memodifikasinya dengan partisip pasif.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000877', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'speaking', 'speaking_repeat', 'Ucapkan kalimat ekspansi kata sifat *resumptive* berikut dengan irama naik yang bertenaga:', '{"romaji":"/ɡrɪd ˈbætəriz mʌst bi ˈdʊrəbəl ˈdʊrəbəl ɪˈnʌf tə ˈsaɪkəl ˈdeɪli fɔːr fɪfˈtiːn jɪrz/","display_text":"Grid batteries must be durable, durable enough to cycle daily for fifteen years.","phonetic_breakdown":["Grid batteries","must be durable,","durable enough to cycle","daily for fifteen years."]}'::jsonb, '{"expected_transcript":"Grid batteries must be durable, durable enough to cycle daily for fifteen years."}'::jsonb, NULL, NULL, 'Jeda tipis sesudah ''durable,'' pertama, lalu tekankan pengulangan ''DURABLE enough to cycle...''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000878', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Pilih kata benda C2 yang melukiskan keruntuhan atau efek beruntun bertingkat:', '{"options":["paucity","cascade","linchpin","hallmark"],"translation":"Satu rute BGP yang salah dikonfigurasi memicu runtutan berjenjang hilangnya paket data di seluruh sistem otonom global.","sentence_template":"One misconfigured BGP route triggered a global [blank] of packet drops across autonomous systems."}'::jsonb, '{"selected":"cascade"}'::jsonb, NULL, NULL, '''Trigger a cascade of [failures/events]'' menggambarkan reaksi berantai cepat.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000879', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'listening', 'listening_choice', 'Dengarkan bacaan sejarah percetakan TOEFL tentang Alkitab Gutenberg. Bagaimana aposisi ganda dipakai menjelaskan signifikansinya?', '{"options":[{"id":"opt_1","text":"Gutenberg menggunakan balok tanah liat lunak tanpa campuran timah dan antimon"},{"id":"opt_2","text":"Harga buku justru naik delapan puluh persen sesudah penemuan logam cetak di Mainz"},{"id":"opt_3","text":"Mengapit definisi logam cetak dengan aposisi tengah, lalu menutup kalimat dengan *summative modifier* (''a cost collapse that...'') tentang demokratisasi literasi"},{"id":"opt_4","text":"Tingkat melek huruf di Eropa menurun drastis selama zaman Renaisans"}],"audio_text":"Movable metal type—an alloy of lead, tin, and antimony perfected in Mainz—slashed book prices by eighty percent, a cost collapse that democratized literacy across Renaissance Europe."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Arsitektur kalimat bacaan TOEFL skor 30: aposisi penjelas di tengah + *summative modifier* dampak di akhir!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000880', 'e5100001-0000-4000-8000-000000000108', 'e2000001-0000-4000-8000-000000000057', 'writing', 'sentence_builder', 'Susun kalimat dengan *summative modifier* + klausa preposisi ''without which'':', '{"romaji":"/ˈsʌbˌsiː ˈkeɪbəlz rɪˈlaɪ ɑːn ˈɑːptɪkəl ˈæmpləˌfaɪərz kəmˈpoʊnənts wɪˈðaʊt wɪtʃ ˌtrænzˌoʊʃiˈænɪk/","tokens":["would fade.","on optical amplifiers,","fading signals","without that","Subsea cables rely","components without which","transoceanic light signals"],"target_translation":"Kabel bawah laut mengandalkan penguat optik, komponen yang tanpanya sinyal cahaya lintas samudra akan memudar."}'::jsonb, '["Subsea cables rely","on optical amplifiers,","components without which","transoceanic light signals","would fade."]'::jsonb, NULL, NULL, '''Components without which + S + would V1'' menggabungkan aposisi rangkuman dan relatif berpreposisi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000881', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Pilih subjek yang selaras secara logis tepat sesudah aposisi pembuka ''Working at the crossroads of marine ecology and satellite radar,'':', '{"options":["the Arafura Sea","Dr. Nabila''s lab","radar wavelengths were","illegal fishing vessels"],"translation":"Bekerja di persimpangan ekologi laut dan radar satelit, laboratorium Dr. Nabila memetakan armada penangkapan ikan ilegal malam hari di Laut Arafura.","sentence_template":"Working at the crossroads of marine ecology and satellite radar, [blank] mapped illegal night-fishing fleets across the Arafura Sea."}'::jsonb, '{"selected":"Dr. Nabila''s lab"}'::jsonb, NULL, NULL, 'Pembuka partisip/aposisi profesi mewajibkan pelaku risetnya (''Dr. Nabila''s lab'') hadir tepat sesudah koma.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000882', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Pilih istilah kalkulus/ekonomi C2 untuk titik perubahan arah kurva secara tajam:', '{"options":["byproduct","inflection point","paucity","cascade"],"translation":"Turunnya harga paket baterai ke bawah $80 per kilowatt-jam menandai titik belok penentu bagi truk angkutan barang listrik.","sentence_template":"Falling battery pack prices below $80 per kilowatt-hour marked a decisive [blank] for electric freight trucks."}'::jsonb, '{"selected":"inflection point"}'::jsonb, NULL, NULL, '''Mark a decisive inflection point'' menandai momen ketika kurva adopsi berbelok tajam ke atas.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000883', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'listening', 'listening_choice', 'Dengarkan pembukaan wawancara kandidat PhD komputasi kuantum. Bagaimana ia memperkenalkan profil lintas disiplinnya?', '{"options":[{"id":"opt_1","text":"Mengaku hanya memahami teori fisika tanpa pengalaman perangkat lunak sama sekali"},{"id":"opt_2","text":"Memilih meninggalkan riset kuantum demi membangun peramban web biasa"},{"id":"opt_3","text":"Menyatakan bahwa komputer kuantum superkonduktor sudah bebas dari gangguan derau"},{"id":"opt_4","text":"Memperkenalkan latar belakangnya di persimpangan fisika materi terkondensasi dan desain kompiler sebelum menjelaskan fokus risetnya secara konkret"}],"audio_text":"Trained at the crossroads of condensed-matter physics and fault-tolerant compiler design, I build middleware that maps logical algorithms onto noisy superconducting qubits."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Pembuka ''Trained at the crossroads of [Field A] and [Field B], I build...'' adalah kalimat perkenalan akademik yang luar biasa kuat.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000884', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'writing', 'sentence_builder', 'Susun kalimat evaluasi teknologi dengan *summative modifier* ''a double-edged sword'':', '{"romaji":"/ˌhaɪpər ˈpɜːrsənəˌlaɪzd fiːdz ˈmæksəˌmaɪz ɪnˈɡeɪdʒmənt ə ˈdʌbəl ɛdʒd sɔːrd ðæt ˈdiːpənz/","tokens":["engagement—a double-edged","civic discourse.","Hyper-personalized feeds maximize","sword that deepens","swords that","relevance while fragmenting","which fragment"],"target_translation":"Linimasa yang sangat dipersonalisasi memaksimalkan keterlibatan—pedang bermata dua yang memperdalam relevansi sembari memecah belah wacana publik."}'::jsonb, '["Hyper-personalized feeds maximize","engagement—a double-edged","sword that deepens","relevance while fragmenting","civic discourse."]'::jsonb, NULL, NULL, 'Menangkap dua sisi positif-negatif sekaligus lewat ''—a double-edged sword that V1 ... while V-ing...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000885', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'speaking', 'speaking_repeat', 'Ucapkan kalimat dengan huruf ''w'' bisu pada ''sword'' (/sɔːrd/) berikut:', '{"romaji":"/ˌælɡəˈrɪðmɪk ˈlɛvrɪdʒ ɪz ə ˈdʌbəl ɛdʒd sɔːrd ˈæmpləˌfaɪɪŋ boʊθ lɪˈkwɪdəti ænd flæʃ ˈkræʃɪz/","display_text":"Algorithmic leverage is a double-edged sword, amplifying both liquidity and flash crashes.","phonetic_breakdown":["Algorithmic leverage","is a double-edged sword,","amplifying both liquidity","and flash crashes."]}'::jsonb, '{"expected_transcript":"Algorithmic leverage is a double-edged sword, amplifying both liquidity and flash crashes."}'::jsonb, NULL, NULL, 'Di American English, ''leverage'' dilafalkan /ˈlɛvrɪdʒ/ (berima dengan ''beverage'') dan ''sword'' /sɔːrd/!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000886', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Pilih kata benda yang tepat untuk hasil sampingan tak disengaja dari proses industri:', '{"options":["hallmark","quorum","byproduct","linchpin"],"translation":"Pewarna ter batu bara pada mulanya ditemukan sebagai produk sampingan kimia dari penerangan gas kota abad kesembilan belas.","sentence_template":"Coal-tar dyes were originally discovered as a chemical [blank] of nineteenth-century town-gas lighting."}'::jsonb, '{"selected":"byproduct"}'::jsonb, NULL, NULL, '''A chemical / unintended byproduct of [process]'' sangat sering muncul pada teks sejarah kimia TOEFL.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000887', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'listening', 'listening_choice', 'Dengarkan kuliah geografi perkotaan tentang kanal drainase abad ke-19. Bagaimana tiga lapis kalimat editorial dipakai dosen?', '{"options":[{"id":"opt_1","text":"Membuka dengan tujuan sanitasi awal, menyatakan aksi pembalikan arus kanal 1900, lalu menutup dengan rangkuman kemenangan teknik sekaligus sengketa hukum hilir"},{"id":"opt_2","text":"Pembalikan arus kanal Chicago gagal melindungi air minum Danau Michigan dari kolera"},{"id":"opt_3","text":"Kota-kota di daerah hilir menyambut gembira proyek tersebut tanpa gugatan hukum"},{"id":"opt_4","text":"Proyek kanal tersebut baru dimulai pada akhir abad kedua puluh"}],"audio_text":"Conceived as a cholera-prevention measure, Chicago''s 1900 canal reversal spared Lake Michigan''s drinking water—an engineering triumph that nonetheless sparked decades of downstream legal battles."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Struktur tiga lapis: ''Conceived as..., [Subject + Verb]—an engineering triumph that nonetheless...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000888', 'e5100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000057', 'writing', 'sentence_builder', 'Susun kalimat tiga lapis bergaya editorial C2 berikut:', '{"romaji":"/wʌns ə ˈsliːpi ˈfɪʃɪŋ pɔːrt ʃɛnˈdʒɛn trænsˈfɔːrmd ˈhɑːrdˌwɛr ˈproʊtəˌtaɪpɪŋ ə ˌmɛtəˈmɔːrfəsɪs ʌnˈmætʃt/","tokens":["Once a sleepy","a metamorphosis unmatched","transforming hardware","fishing port, Shenzhen","in industrial history.","transformed hardware prototyping—","which unmatched"],"target_translation":"Dahulu sebuah pelabuhan nelayan yang tenang, Shenzhen merombak pembuatan purwarupa perangkat keras—sebuah metamorfosis yang tiada duanya dalam sejarah industri."}'::jsonb, '["Once a sleepy","fishing port, Shenzhen","transformed hardware prototyping—","a metamorphosis unmatched","in industrial history."]'::jsonb, NULL, NULL, 'Aposisi pembuka ''Once a sleepy fishing port,'' + inti kalimat + aposisi penutup ''—a metamorphosis unmatched...''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000889', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Eliminasi kesalahan *comma splice* dengan memilih *summative modifier* yang benar:', '{"options":["it was an intervention","an intervention that","which intervention it","intervening that"],"translation":"Jalur pertukaran bank sentral menenangkan pasar pendanaan dolar luar negeri dalam hitungan jam, sebuah intervensi yang mencegah obral likuidasi surat utang negara.","sentence_template":"Central-bank swap lines calmed offshore dollar funding markets within hours, [blank] averted fire-sale liquidations of sovereign bonds."}'::jsonb, '{"selected":"an intervention that"}'::jsonb, NULL, NULL, '''An intervention that + V'' merangkum klausa pertama tanpa melanggar kaidah penggabungan kalimat.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000890', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Pastikan keselarasan aposisi pembuka dengan subjek sesudah koma:', '{"options":["mirrors are coated","chipmakers in Taiwan","extreme ultraviolet light","heating tin droplets"],"translation":"Sebagai pasak penyangga tak tergantikan dalam litografi modern, sinar ultraviolet ekstrem memerlukan plasma timah hasil tembakan laser bersuhu ratusan ribu derajat.","sentence_template":"An indispensable linchpin of modern lithography, [blank] requires laser-produced tin plasma heated to hundreds of thousands of degrees."}'::jsonb, '{"selected":"extreme ultraviolet light"}'::jsonb, NULL, NULL, 'Subjek tepat sesudah koma haruslah hal yang berstatus ''linchpin of modern lithography'', yakni ''extreme ultraviolet light''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000891', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'listening', 'listening_choice', 'Evaluasi Unit 7 — Dengarkan analisis bacaan biologi evolusioner TOEFL tentang endosimbiosis mitokondria. Bagaimana *resumptive modifier* memperjelas kalimatnya?', '{"options":[{"id":"opt_1","text":"Bakteri aerobik memusnahkan seluruh kehidupan kompleks dua miliar tahun lalu"},{"id":"opt_2","text":"Menangkap peristiwa penelanan sel purba tersebut dengan dua aposisi beruntun (''a partnership, a cellular merger that...'') untuk menjelaskan ledakan energi kehidupan kompleks"},{"id":"opt_3","text":"Sel eukariotik kompleks terbukti tidak memiliki mitokondria sama sekali"},{"id":"opt_4","text":"Peristiwa penggabungan sel tersebut baru terjadi lima puluh tahun yang lalu"}],"audio_text":"An ancient archaeon engulfed an aerobic bacterium roughly two billion years ago—a partnership, a cellular merger that unlocked the vast bioenergetic budget of complex life."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Aposisi berlapis memperjelas makna konseptual istilah teknis secara langsung.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000892', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'writing', 'sentence_builder', 'Evaluasi Unit 7 — Susun kalimat *resumptive adjective* yang elegan berikut:', '{"romaji":"/ˌkrɪptəˈɡræfɪk ˈɔːdɪt treɪlz mʌst rɪˈmeɪn ɪˈmjuːtəbəl ɪˈmjuːtəbəl ˈiːvən əˈɡɛnst ˈprɪvəlɪdʒd/","tokens":["they are immutable","immutable even against","privileged database administrators.","Cryptographic audit trails","immutably enough","must remain immutable,"],"target_translation":"Jejak audit kriptografis wajib tetap tak terubahkan, tak terubahkan bahkan terhadap administrator basis data berhak istimewa sekalipun."}'::jsonb, '["Cryptographic audit trails","must remain immutable,","immutable even against","privileged database administrators."]'::jsonb, NULL, NULL, 'Mengulang kata sifat predikatif '', immutable even against...'' menghindari *comma splice* sekaligus memberi tekanan dramatis.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000893', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'speaking', 'speaking_repeat', 'Evaluasi Unit 7 — Ucapkan kalimat editorial bertanda pisah berikut dengan jelas:', '{"romaji":"/ˈækwəfər səˈlɪnəti krɔːst ˈkrɪtɪkəl ˈθrɛʃˌhoʊldz ən ɪnˈflɛkʃən pɔɪnt ðæt fɔːrst krɑːp ˈswɪtʃɪŋ/","display_text":"Aquifer salinity crossed critical thresholds—an inflection point that forced crop switching.","phonetic_breakdown":["Aquifer salinity crossed","critical thresholds—an inflection","point that forced","crop switching."]}'::jsonb, '{"expected_transcript":"Aquifer salinity crossed critical thresholds—an inflection point that forced crop switching."}'::jsonb, NULL, NULL, 'Perhatikan pergeseran vokal dari ''saline'' (/ˈseɪliːn/) ke nomina ''salinity'' (/səˈlɪnəti/)!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000894', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'reading', 'fill_blank', 'Evaluasi Unit 7 — Pilih kombinasi rangkuman + preposisi relatif untuk batas kedalaman penyelaman:', '{"options":["which at","at which","whereby it","at that"],"translation":"Penyelam saturasi komersial bekerja di kisaran tiga ratus meter—sebuah rezim tekanan yang pada titik itu campuran helium-oksigen menjadi wajib.","sentence_template":"Commercial saturation divers work near three hundred meters—a pressure regime [blank] helium-oxygen mixtures become mandatory."}'::jsonb, '{"selected":"at which"}'::jsonb, NULL, NULL, 'Kolokasi ''at [a pressure regime]'' berubah menjadi klausa relatif berpreposisi ''at which + S + V''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000895', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'listening', 'listening_choice', 'Evaluasi Unit 7 — Dengarkan ulasan buku sejarah ekonomi tentang jalur kereta api transkontinental AS. Apa ''unintended byproduct'' yang disoroti?', '{"options":[{"id":"opt_1","text":"Jalur kereta api menghapus pembagian zona waktu di Amerika Utara pada tahun 1883"},{"id":"opt_2","text":"Penyeragaman zona waktu tahun 1883 lahir sebagai hasil sampingan kelembagaan dari penjadwalan kereta api, yang kemudian menyinkronkan pasar keuangan modern"},{"id":"opt_3","text":"Pasar keuangan modern sudah tersinkronisasi jauh sebelum kereta api ditemukan"},{"id":"opt_4","text":"Pelabuhan Pasifik gagal terhubung dengan pabrik-pabrik di wilayah Timur"}],"audio_text":"Built to bind Pacific ports to Eastern factories, transcontinental railroads also standardized clock zones in 1883—an institutional byproduct that synchronized modern financial markets."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Menangkap benang merah dari partisip pembuka hingga *summative modifier* ''—an institutional byproduct that...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000896', 'e5100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000057', 'writing', 'sentence_builder', 'Evaluasi Unit 7 — Susun kalimat kausalitas ''precipitated a cascade of'' berikut:', '{"romaji":"/ˈmɛltɪŋ ˈpɜːrməˌfrɔːst ˈwiːkənd paɪl faʊnˈdeɪʃənz ə ˈstrʌktʃərəl ˈfeɪljər ðæt prɪˈsɪpəˌteɪtɪd/","tokens":["of pipeline leaks.","which it forced","precipitated a cascade","precipitating cascades","structural failure that","Melting permafrost weakened","pile foundations—a"],"target_translation":"Mencairnya ibun abadi melemahkan fondasi tiang pancang—sebuah kegagalan struktural yang memicu runtutan kebocoran pipa."}'::jsonb, '["Melting permafrost weakened","pile foundations—a","structural failure that","precipitated a cascade","of pipeline leaks."]'::jsonb, NULL, NULL, 'Mengikat kosakata puncak Unit 7 (''precipitated'' + ''a cascade of'') di dalam *summative modifier*.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000897', 'e5100001-0000-4000-8000-000000000111', NULL, 'reading', 'fill_blank', 'Pilih konjungsi pembatas ruang lingkup yang diikuti klausa lengkap S + V:', '{"options":["insofar as","vis-à-vis","notwithstanding","contrary to"],"translation":"Pembuatan kode otomatis mendongkrak kecepatan rekayasa hanya sejauh peninjau senior menegakkan aturan tetap arsitektur.","sentence_template":"Automated code generation boosts engineering velocity only [blank] senior reviewers enforce architectural invariants."}'::jsonb, '{"selected":"insofar as"}'::jsonb, NULL, NULL, 'Karena diikuti klausa lengkap (''senior reviewers enforce...''), dibutuhkan konjungsi batas ''insofar as'', bukan preposisi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000898', 'e5100001-0000-4000-8000-000000000111', NULL, 'reading', 'fill_blank', 'Pilih preposisi konsesi C2 unik yang sah diletakkan SETELAH frasa kata bendanya (*postpositional*):', '{"options":["although","insofar as","notwithstanding","despite"],"translation":"Terlepas dari gangguan monsun musiman, pabrik pemurnian nikel kawasan timur berhasil menjaga tingkat utilisasi sembilan puluh empat persen.","sentence_template":"Seasonal monsoon disruptions [blank], eastern nickel smelters maintained ninety-four percent utilization."}'::jsonb, '{"selected":"notwithstanding"}'::jsonb, NULL, NULL, 'Hanya ''notwithstanding'' (bukan ''despite'' maupun ''although'') yang dapat diletakkan tepat di belakang objek kata bendanya!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000899', 'e5100001-0000-4000-8000-000000000111', NULL, 'listening', 'listening_choice', 'Dengarkan komentar ekonom valuta asing tentang daya saing ekspor manufaktur. Apa makna ''vis-à-vis'' dalam analisisnya?', '{"options":[{"id":"opt_1","text":"Stabilitas relatif nilai tukar rupiah jika dibandingkan terhadap mata uang negara-negara pesaing manufaktur se-kawasan"},{"id":"opt_2","text":"Bank sentral mematok nilai tukar tetap terhadap dolar AS selamanya"},{"id":"opt_3","text":"Rupiah menggantikan mata uang negara tetangga dalam seluruh transaksi domestik"},{"id":"opt_4","text":"Biaya komponen impor melonjak tak terkendali dibandingkan negara tetangga"}],"audio_text":"Even though the rupiah dipped slightly against the US dollar, its relative stability vis-à-vis regional manufacturing peers kept imported component costs predictable."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '''Vis-à-vis [peers/benchmarks]'' membandingkan posisi relatif suatu entitas berhadapan dengan pembandingnya.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000900', 'e5100001-0000-4000-8000-000000000111', NULL, 'writing', 'sentence_builder', 'Susun kalimat argumen simetris dengan ''by the same token'':', '{"romaji":"/ˈoʊpən weɪts ˈmɑːdəlz dɪˈmɑːkrəˌtaɪz ˈkæmpəs ˈriːsɜːrtʃ baɪ ðə seɪm ˈtoʊkən ðeɪ ˈloʊər/","tokens":["in same token","Open-weights models democratize","for automated phishing.","they lower barriers","campus research; by","lowering barriers","the same token,"],"target_translation":"Model berbobot terbuka mendemokratisasi riset kampus; atas dasar mekanisme yang sama, kemudahan akses itu juga menurunkan hambatan bagi pengelabuan otomatis."}'::jsonb, '["Open-weights models democratize","campus research; by","the same token,","they lower barriers","for automated phishing."]'::jsonb, NULL, NULL, '''By the same token,'' menunjukkan bahwa sifat keterbukaan yang sama melahirkan konsekuensi di sisi sebaliknya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000901', 'e5100001-0000-4000-8000-000000000111', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat analisis daya saing dengan pelafalan ''vis-à-vis'' (/ˌviːzəˈviː/) yang fasih:', '{"romaji":"/reɪl freɪt rɪˈmeɪnz ˈkɔːst kəmˈpɛtətɪv ˌviːzəˈviː ˈlɔːŋ hɔːl ˈtrʌkɪŋ ɑːn ˈkɔːrɪdɔːrz ˈoʊvər faɪv ˈhʌndrəd maɪlz/","display_text":"Rail freight remains cost-competitive vis-à-vis long-haul trucking on corridors over five hundred miles.","phonetic_breakdown":["Rail freight remains","cost-competitive vis-à-vis","long-haul trucking on corridors","over five hundred miles."]}'::jsonb, '{"expected_transcript":"Rail freight remains cost-competitive vis-à-vis long-haul trucking on corridors over five hundred miles."}'::jsonb, NULL, NULL, 'Pastikan ''vis-à-vis'' mengalir mulus /ˌviːzəˈviː/ tanpa melafalkan huruf ''s'' terakhir.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000902', 'e5100001-0000-4000-8000-000000000111', NULL, 'reading', 'fill_blank', 'Pilih penulisan preposisi konsesi di awal klausul hukum (tanpa ''of''!):', '{"options":["By the same token","Notwithstanding","Notwithstanding of","Insofar"],"translation":"Terlepas dari ketentuan mana pun yang menyatakan sebaliknya pada Pasal 4, kewajiban domisili data tetap berlaku melampaui pengakhiran kontrak.","sentence_template":"[blank] anything to the contrary in Section 4, data residency obligations survive contract termination."}'::jsonb, '{"selected":"Notwithstanding"}'::jsonb, NULL, NULL, 'Frasa pembuka kontrak paling ikonik dalam hukum Anglo-Amerika: ''Notwithstanding anything to the contrary...''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000903', 'e5100001-0000-4000-8000-000000000111', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah filsafat ilmu pengetahuan TOEFL tentang model matematika iklim. Bagaimana profesor membatasi klaim keakuratan model?', '{"options":[{"id":"opt_1","text":"Parameter awan tidak memiliki pengaruh apa pun terhadap keluaran model iklim"},{"id":"opt_2","text":"Profesor menolak penggunaan komputer dalam seluruh cabang meteorologi"},{"id":"opt_3","text":"Simulasi komputer informatif hanya sejauh parameter umpan-balik awannya mencerminkan pengamatan fisik nyata"},{"id":"opt_4","text":"Simulasi komputer selalu seratus persen akurat tanpa memerlukan pengamatan cuaca fisik"}],"audio_text":"Computer simulations are informative only insofar as their cloud-feedback parameters reflect physical observations; garbage parameters yield precise-looking nonsense."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Informative only insofar as [Clause]'' membingkai syarat validitas ilmiah secara presisi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000904', 'e5100001-0000-4000-8000-000000000111', NULL, 'writing', 'sentence_builder', 'Susun kalimat dengan posisi pasca-nomina ''notwithstanding'':', '{"romaji":"/ˈɜːrli ˈskɛptəˌsɪzəm frʌm ɪnˈkʌmbənt ˈtɛlkoʊz ˌnɑːtwɪðˈstændɪŋ loʊ ɜːrθ ˈɔːrbɪt ˌkɑːnstəˈleɪʃənz pruːvd/","tokens":["low-Earth-orbit constellations proved","despite","commercially viable.","incumbent telcos notwithstanding,","viable commercially","Early skepticism from"],"target_translation":"Terlepas dari skeptisisme awal operator telekomunikasi petahana, konstelasi satelit orbit rendah Bumi terbukti layak secara komersial."}'::jsonb, '["Early skepticism from","incumbent telcos notwithstanding,","low-Earth-orbit constellations proved","commercially viable."]'::jsonb, NULL, NULL, '''[Noun Phrase] notwithstanding,'' menempatkan preposisi sesudah objeknya untuk penekanan gaya C2.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000905', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Pilih preposisi khas hukum dan kebijakan Amerika yang bermakna ''Tanpa adanya...'':', '{"options":["Suffice","Purporting","Absent","Insofar"],"translation":"Tanpa adanya pengecualian undang-undang yang eksplisit, pelatihan generatif atas rekam medis berhak cipta melanggar hukum privasi negara bagian.","sentence_template":"[blank] an explicit statutory carve-out, generative training on copyrighted health records violates state privacy law."}'::jsonb, '{"selected":"Absent"}'::jsonb, NULL, NULL, '''Absent + Noun Phrase,'' berfungsi sebagai preposisi formal setara ''In the absence of / Without''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000906', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Pahami makna pengecualian di TOEFL Reading! Kata mana yang berarti ''kecuali untuk satu kawah terlindung''?', '{"options":["by the same token","in tandem","inasmuch as","save for"],"translation":"Angin matahari mengikis es volatil dari khatulistiwa bulan, kecuali untuk kawah-kawah kutub yang terlindung bayangan abadi.","sentence_template":"Solar wind stripped volatile ice from the lunar equator, [blank] permanently shadowed polar craters."}'::jsonb, '{"selected":"save for"}'::jsonb, NULL, NULL, '''Save for + Noun Phrase'' adalah preposisi pengecualian formal yang berarti ''except for''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000907', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'listening', 'listening_choice', 'Dengarkan analisis soal *Sentence Simplification* TOEFL Reading tentang kalimat berawalan ''Inasmuch as''. Apa inti maknanya?', '{"options":[{"id":"opt_1","text":"Karena dan sejauh pembentukan kerangka karang bergantung pada kejenuhan aragonit, pengasaman laut menghantam fondasi kerangkanya"},{"id":"opt_2","text":"Pengasaman laut meningkatkan kejenuhan aragonit sehingga mempertebal kerangka karang"},{"id":"opt_3","text":"Meskipun pembentukan karang tidak membutuhkan aragonit, pengasaman laut tetap berbahaya"},{"id":"opt_4","text":"Karang hanya tumbuh di perairan asam yang bebas dari mineral aragonit"}],"audio_text":"When the passage states, ''Inasmuch as coral calcification depends on aragonite saturation, ocean acidification strikes at the reef''s skeletal foundation,'' ''inasmuch as'' links cause and scope—because and to the degree that calcification relies on aragonite!"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menguasai parafrasa presisi ''inasmuch as'' pada soal penyederhanaan kalimat TOEFL Reading.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000908', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'writing', 'sentence_builder', 'Susun kalimat proporsional pembuka dengan ''To the extent that'':', '{"romaji":"/tə ði ɪkˈstɛnt ðæt mjuːˈnɪsəpəl bɑːndz fʌnd flʌd ˈbæriərz ɪnˈʃʊrərz ˈloʊər ˈkoʊstəl/","tokens":["To extent which","fund flood barriers,","lowering coastal","reinsurance surcharges.","To the extent","insurers lower coastal","that municipal bonds"],"target_translation":"Sejauh obligasi daerah mendanai tanggul banjir, perusahaan asuransi menurunkan biaya tambahan reasuransi pesisir."}'::jsonb, '["To the extent","that municipal bonds","fund flood barriers,","insurers lower coastal","reinsurance surcharges."]'::jsonb, NULL, NULL, '''To the extent that + S + V, [Main Clause]'' mengaitkan tingkat aksi dengan tingkat respons.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000909', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kebijakan Amerika berawalan preposisi ''Absent'' berikut dengan tegas:', '{"romaji":"/ˈæbsənt ˈhɑːrməˌnaɪzd ɡrɪd koʊdz ˈkrɔːs ˈbɔːrdər ˈsoʊlər ˈtreɪdɪŋ rɪˈmeɪnz ˈbɑːtəlˌnɛkt/","display_text":"Absent harmonized grid codes, cross-border solar trading remains bottlenecked.","phonetic_breakdown":["Absent harmonized","grid codes,","cross-border solar trading","remains bottlenecked."]}'::jsonb, '{"expected_transcript":"Absent harmonized grid codes, cross-border solar trading remains bottlenecked."}'::jsonb, NULL, NULL, 'Tekankan kata pertama ''ABSENT harmonized grid codes'' agar fungsi preposisinya jelas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000910', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Pilih konjungsi kausal-pembatas formal yang diikuti klausa lengkap:', '{"options":["notwithstanding","save for","vis-à-vis","inasmuch as"],"translation":"Putusan banding tersebut menetapkan preseden yang sempit, mengingat dan sejauh pengadilan membatasi analisisnya pada klausul arbitrase maritim.","sentence_template":"The appellate ruling sets a narrow precedent, [blank] the court confined its analysis to maritime arbitration clauses."}'::jsonb, '{"selected":"inasmuch as"}'::jsonb, NULL, NULL, 'Di depan klausa utuh (''the court confined...''), gunakan konjungsi ''inasmuch as''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000911', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'listening', 'listening_choice', 'Dengarkan penjelasan pengacara hak kekayaan intelektual tentang klausul kontrak perangkat lunak terbuka. Apa arti bagian sesudah ''save that''?', '{"options":[{"id":"opt_1","text":"Penerima lisensi dilarang keras memodifikasi kode sumber dalam kondisi apa pun"},{"id":"opt_2","text":"Pemberitahuan atribusi asli wajib dihapus sebelum mendistribusikan perangkat tegar"},{"id":"opt_3","text":"Pengguna wajib membayar royalti bulanan untuk setiap baris kode"},{"id":"opt_4","text":"Penerima lisensi bebas memodifikasi dan mendistribusikan ulang kernel secara gratis, dengan satu pengecualian wajib bahwa perangkat tegar turunan harus tetap mencantumkan pemberitahuan atribusi asli"}],"audio_text":"Licensees may modify and redistribute the cryptographic kernel royalty-free, save that derivative firmware must retain the original attribution notice."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''Save that + [Clause]'' berfungsi sebagai konjungsi pengecualian (''except that'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000912', 'e5100001-0000-4000-8000-000000000112', 'e2000001-0000-4000-8000-000000000058', 'writing', 'sentence_builder', 'Susun kalimat analisis fiskal dengan preposisi ''Absent'' di awal:', '{"romaji":"/ˈæbsənt ˈkrɛdəbəl ˈsɑːvrən dɛt riːˈstrʌktʃərɪŋ ɪˈmɜːrdʒənsi ˈaɪˈɛmˈɛf ˈtrɑːntʃɪz ˈmɪrli poʊstˈpoʊn/","tokens":["postpone default.","debt restructuring, emergency","Absent credible sovereign","IMF tranches merely","Absent of","postponing default"],"target_translation":"Tanpa adanya restrukturisasi utang negara yang kredibel, pencairan bertahap darurat IMF hanya menunda gagal bayar."}'::jsonb, '["Absent credible sovereign","debt restructuring, emergency","IMF tranches merely","postpone default."]'::jsonb, NULL, NULL, 'Ingat ''Absent'' langsung diikuti Noun Phrase TANPA ''of'' (''Absent credible...'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000913', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Pilih ungkapan presisi untuk menyatakan bahwa defisit anggaran ''tidak berbahaya pada dirinya sendiri secara hakiki'':', '{"options":["save for","as it were","vis-à-vis","per se"],"translation":"Utang negara tidak bersifat inflasioner pada dirinya sendiri; bahaya makroekonomi bergantung pada apakah dana tersebut membangun pelabuhan produktif atau menyubsidi konsumsi.","sentence_template":"Sovereign borrowing is not inflationary [blank]; macroeconomic danger depends on whether funds build productive ports or subsidize consumption."}'::jsonb, '{"selected":"per se"}'::jsonb, NULL, NULL, '''Not [Adjective] per se'' memisahkan hakikat instrumen dari cara penggunaannya.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000914', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Pilih istilah yang merujuk pada standar yang menguasai kenyataan pasar meski tidak pernah diwajibkan undang-undang:', '{"options":["putative","de facto","uncorroborated","de jure"],"translation":"Meskipun tidak pernah diwajibkan oleh perjanjian internasional, kunci-putar kontainer menjadi standar pelayaran global secara praktik nyata dalam satu dekade.","sentence_template":"Although never mandated by treaty, container twist-locks became the [blank] global shipping standard within a decade."}'::jsonb, '{"selected":"de facto"}'::jsonb, NULL, NULL, '''De facto standard'' berarti standar yang berlaku nyata di lapangan berkat adopsi luas, berbeda dari ''de jure'' (ditetapkan hukum).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000915', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'listening', 'listening_choice', 'Dengarkan kuliah sejarah perkotaan Amerika TOEFL tentang segregasi perumahan pasca-1968. Apa perbedaan *de jure* dan *de facto* yang dijelaskan profesor?', '{"options":[{"id":"opt_1","text":"Undang-undang 1968 menghapus aturan diskriminasi tertulis secara hukum (*de jure*), namun zonasi perumahan eksklusif mempertahankan pemisahan nyata di lapangan (*de facto*)"},{"id":"opt_2","text":"Undang-undang 1968 mewajibkan pemisahan lingkungan secara tertulis di sertifikat rumah"},{"id":"opt_3","text":"Istilah ''de jure'' merujuk pada kebiasaan tak tertulis masyarakat"},{"id":"opt_4","text":"Segregasi lapangan langsung hilang seratus persen pada hari pengesahan undang-undang 1968"}],"audio_text":"While the Fair Housing Act of 1968 outlawed de jure racial covenants in property deeds, exclusionary single-family zoning preserved de facto neighborhood segregation for decades."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Kontras klasik sejarah Amerika di TOEFL Listening & Reading.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000916', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'writing', 'sentence_builder', 'Susun kalimat kesimpulan berimbang paragraf akhir dengan ''On balance,'':', '{"romaji":"/trænˈzɪʃən kɔːsts ˌnɑːtwɪðˈstændɪŋ ɑːn ˈbæləns ˈriːəl taɪm ˌɪntərˈbæŋk ˈsɛtəlmənt ˈstrɛŋθənz/","tokens":["strengthening systemic","Transition costs notwithstanding,","interbank settlement strengthens","in balance","systemic financial resilience.","on balance, real-time"],"target_translation":"Terlepas dari biaya transisinya, secara keseluruhan setelah ditimbang, penyelesaian antarbank waktu-nyata memperkuat ketahanan keuangan sistemik."}'::jsonb, '["Transition costs notwithstanding,","on balance, real-time","interbank settlement strengthens","systemic financial resilience."]'::jsonb, NULL, NULL, 'Perpaduan ''[NP] notwithstanding, on balance, [Main Clause]'' menutup esai TOEFL dengan sangat matang.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000917', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pembeda *de jure* dan *de facto* berikut dengan artikulasi jernih:', '{"romaji":"/deɪ ˈdʒʊri ˌɪndɪˈpɛndəns miːnz ˈlɪtəl ˈæbsənt deɪ ˈfæktoʊ kənˈtroʊl ˈoʊvər ˈpeɪmənt reɪlz/","display_text":"De jure independence means little absent de facto control over payment rails.","phonetic_breakdown":["De jure independence","means little absent","de facto control","over payment rails."]}'::jsonb, '{"expected_transcript":"De jure independence means little absent de facto control over payment rails."}'::jsonb, NULL, NULL, 'Menggabungkan tiga permata Unit 8 sekaligus: ''de jure'', preposisi ''absent'', dan ''de facto''!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000918', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Pilih kata benda kebijakan untuk ''pengecualian khusus yang dipahat di dalam undang-undang bagi riset universitas'':', '{"options":["fallout","cascade","carve-out","byproduct"],"translation":"Para kriptografer akademik melobi pembuat undang-undang demi memperoleh pengecualian khusus riset yang sempit di dalam RUU pertanggungjawaban keamanan siber.","sentence_template":"Academic cryptographers lobbied lawmakers for a narrow research [blank] inside the cybersecurity liability bill."}'::jsonb, '{"selected":"carve-out"}'::jsonb, NULL, NULL, '''A statutory / research carve-out'' adalah istilah baku kebijakan publik Amerika.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000919', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'listening', 'listening_choice', 'Dengarkan rangkuman analis regulasi AI Eropa dan AS. Mengapa ia menyimpulkan ''on balance, the carve-out was prudent''?', '{"options":[{"id":"opt_1","text":"Tanpa pengecualian tersebut laboratorium kampus akan tercekik biaya kepatuhan sekelas raksasa teknologi, sehingga secara keseluruhan pengecualian itu bijaksana"},{"id":"opt_2","text":"Model sumber terbuka pra-komersial dilarang total oleh undang-undang tersebut"},{"id":"opt_3","text":"Raksasa teknologi dibebaskan dari seluruh aturan kepatuhan AI"},{"id":"opt_4","text":"Analis meminta pemerintah membebankan biaya kepatuhan yang sama beratnya kepada mahasiswa"}],"audio_text":"Exempting pre-commercial open-source weights worried some safety hawks; yet absent that carve-out, university labs would have faced compliance costs meant for trillion-dollar giants—so on balance, the carve-out was prudent."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menyimak penalaran berlapis: keberatan awal -> kontrafaktual ''absent that carve-out'' -> simpulan ''on balance''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000920', 'e5100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000058', 'writing', 'sentence_builder', 'Susun kalimat pembingkaian nuansa ''not ... per se, but insofar as'':', '{"romaji":"/haɪ dɛt ɪz nɑːt ˈpɛrələs pɜːr seɪ bʌt ˌɪnsoʊˈfɑːr æz məˈtʃʊrətiz ˈklʌstər/","tokens":["foreign currencies.","High debt is","per se perilous","not perilous per se,","maturities cluster in","but insofar as","notwithstanding maturities"],"target_translation":"Utang tinggi tidak berbahaya pada dirinya sendiri, melainkan sejauh jatuh temponya menumpuk dalam mata uang asing."}'::jsonb, '["High debt is","not perilous per se,","but insofar as","maturities cluster in","foreign currencies."]'::jsonb, NULL, NULL, 'Struktur analitis puncak C2 untuk membedah risiko ekonomi secara presisi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000921', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih preposisi konsesi yang sah ditempatkan tepat sesudah frasa kata bendanya:', '{"options":["despite","although","notwithstanding","insofar as"],"translation":"Terlepas dari penyempitan margin jangka pendek, manajemen menolak memangkas jumlah peneliti riset dasar.","sentence_template":"Short-term margin compression [blank], management refused to slash foundational R&D headcount."}'::jsonb, '{"selected":"notwithstanding"}'::jsonb, NULL, NULL, 'Posisi pasca-nomina (''[NP] notwithstanding,'') adalah ciri khas eksklusif ''notwithstanding''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000922', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih preposisi formal khas AS yang bermakna ''Tanpa adanya'':', '{"options":["Save","Inasmuch","Absent","Per se"],"translation":"Tanpa adanya audit kustodian yang dapat diverifikasi, tangkapan layar bukti cadangan hanya memberi perlindungan minim bagi nasabah.","sentence_template":"[blank] verifiable custody audits, proof-of-reserve screenshots offer depositors scant protection."}'::jsonb, '{"selected":"Absent"}'::jsonb, NULL, NULL, '''Absent + Noun Phrase'' berarti ''Without / In the absence of''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000923', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'listening', 'listening_choice', 'Evaluasi Unit 8 — Dengarkan analisis hakim dalam perkara antipakat perangkat lunak. Kapan bundel produk melanggar hukum?', '{"options":[{"id":"opt_1","text":"Penggabungan produk tidak melanggar hukum pada hakikatnya, melainkan menjadi masalah antipakat sejauh platform dominan memblokir API pesaing untuk menutup persaingan"},{"id":"opt_2","text":"Platform dominan bebas memblokir seluruh API pesaing tanpa pengawasan hukum"},{"id":"opt_3","text":"Setiap bentuk penggabungan dua perangkat lunak otomatis melanggar hukum pidana"},{"id":"opt_4","text":"Pengadilan melarang perusahaan menjual penyimpanan cloud kepada kantor"}],"audio_text":"Bundling cloud storage with productivity suites is not unlawful per se; antitrust scrutiny attaches insofar as dominant platforms block rival APIs to foreclose competition."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memahami pembedaan hukum ''not unlawful per se'' vs. ''insofar as [anticompetitive conduct]''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000924', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'writing', 'sentence_builder', 'Evaluasi Unit 8 — Susun kalimat perbandingan valuta menggunakan ''vis-à-vis'':', '{"romaji":"/ˈɛkspɔːrt kəmˈpɛtətɪvnəs ɪmˈpruːvd æz ðə jɛn ˈwiːkənd ˌviːzəˈviː boʊθ ðə ˈdɑːlər/","tokens":["vis-à-vis of","the dollar and","as the yen","weakening yen","Export competitiveness improved","weakened vis-à-vis both","the euro."],"target_translation":"Daya saing ekspor meningkat seiring melemahnya yen dibandingkan terhadap dolar maupun euro."}'::jsonb, '["Export competitiveness improved","as the yen","weakened vis-à-vis both","the dollar and","the euro."]'::jsonb, NULL, NULL, '''Vis-à-vis'' langsung diikuti objek kata benda tanpa tambahan preposisi ''of''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000925', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'speaking', 'speaking_repeat', 'Evaluasi Unit 8 — Ucapkan kalimat pembatasan ruang lingkup klaim berikut dengan jelas:', '{"romaji":"/ˈbɛntʃˌmɑːrks ɡaɪd prəˈkjʊrmənt ˈoʊnli ˌɪnsoʊˈfɑːr æz tɛst ˈwɜːrkˌloʊdz ˈmɪrər ˈriːəl ˈtræfɪk/","display_text":"Benchmarks guide procurement only insofar as test workloads mirror real traffic.","phonetic_breakdown":["Benchmarks guide procurement","only insofar as","test workloads mirror","real traffic."]}'::jsonb, '{"expected_transcript":"Benchmarks guide procurement only insofar as test workloads mirror real traffic."}'::jsonb, NULL, NULL, 'Tekankan ''ONLY in-so-FAR as'' untuk menggarisbawahi batas validitas tolok ukur.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000926', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'reading', 'fill_blank', 'Evaluasi Unit 8 — Pilih preposisi pengecualian formal (''kecuali untuk'') pada kalimat sejarah berikut:', '{"options":["vis-à-vis","save for","insofar as","by the same token"],"translation":"Kebakaran tahun 1906 meratakan hampir seluruh distrik keuangan, kecuali gedung Percetakan Uang AS yang berdinding granit.","sentence_template":"The 1906 fire leveled nearly the entire financial district, [blank] the granite-walled United States Mint."}'::jsonb, '{"selected":"save for"}'::jsonb, NULL, NULL, '''Save for + Noun Phrase'' (= except for) menandai satu-satunya bangunan yang selamat.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000927', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'listening', 'listening_choice', 'Evaluasi Unit 8 — Dengarkan penutup esai lisan kebijakan moneter kandidat beasiswa. Bagaimana ia menggunakan ''by the same token'' dan ''on balance''?', '{"options":[{"id":"opt_1","text":"Mendukung batas suku bunga nol persen tanpa skema penjaminan kredit"},{"id":"opt_2","text":"Menyimpulkan bahwa bank pedesaan tidak membutuhkan modal kerja"},{"id":"opt_3","text":"Menunjukkan dua sisi mekanisme suku bunga dengan ''by the same token'', lalu menarik simpulan kebijakan akhir menggunakan ''on balance''"},{"id":"opt_4","text":"Menolak pemberian kredit mikro bagi wirausahawan pedesaan"}],"audio_text":"Subsidized micro-credit expands rural entrepreneurship; by the same token, capping interest too aggressively starves rural banks of capital—so on balance, targeted credit guarantees work better than rate ceilings."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Struktur penalaran seimbang yang sangat disukai panelis wawancara beasiswa S2/S3.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000928', 'e5100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000058', 'writing', 'sentence_builder', 'Evaluasi Unit 8 — Susun kalimat pengecualian regulasi (*carve-out*) berikut:', '{"romaji":"/ˈlɔːˌmeɪkərz ɪnˈsɜːrtɪd ə ˈnæroʊ ˈstætʃəˌtɔːri ˈkɑːrv aʊt fɔːr ˈnɑːn ˈprɑːfɪt ˈklɪnɪkəl ˈbaɪoʊˌbæŋks/","tokens":["into statutory","for non-profit clinical","carve-outs narrow","narrow statutory carve-out","Lawmakers inserted a","biobanks."],"target_translation":"Para pembuat undang-undang menyisipkan pengecualian hukum yang sempit bagi biobank klinis nirlaba."}'::jsonb, '["Lawmakers inserted a","narrow statutory carve-out","for non-profit clinical","biobanks."]'::jsonb, NULL, NULL, 'Kolokasi ''insert a narrow statutory carve-out for [entity]''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000929', 'e5100001-0000-4000-8000-000000000115', NULL, 'reading', 'fill_blank', 'Perhatikan bahwa ''to'' pada ''boil down to'' adalah preposisi! Pilih bentuk kata kerja sesudahnya:', '{"options":["survive","surviving","be survived","have survived"],"translation":"Singkirkan seluruh jargon pemasarannya, maka penyimpanan terdistribusi yang andal pada intinya mengerucut pada kemampuan bertahan dari kegagalan diska yang saling berkorelasi.","sentence_template":"Strip away the marketing jargon, and reliable distributed storage boils down to [blank] correlated disk failures."}'::jsonb, '{"selected":"surviving"}'::jsonb, NULL, NULL, 'Sesudah phrasal-prepositional verb ''boil/come down to'', kata kerja wajib berbentuk gerund ''V-ing'' (''surviving'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000930', 'e5100001-0000-4000-8000-000000000115', NULL, 'reading', 'fill_blank', 'Terapkan aturan tak terpisahkan (*inseparability*) saat menggunakan objek pronomina ''them'':', '{"options":["did away with them","did them away with","did away them with","away did with them"],"translation":"Aturan penggantian kata sandi tiga bulanan justru melemahkan keamanan karena mendorong pola tebakan mudah, sehingga pedoman NIST menghapuskannya.","sentence_template":"Quarterly password-rotation rules actually weakened security by encouraging predictable patterns, so NIST guidelines [blank]."}'::jsonb, '{"selected":"did away with them"}'::jsonb, NULL, NULL, 'Idiom tiga kata ''do away with'' tidak boleh dipisah oleh ''them''; letakkan pronomina di ujung (''did away with them'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000931', 'e5100001-0000-4000-8000-000000000115', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dua peneliti pascadoktoral di koridor kampus AS (gaya TOEFL Listening). Mengapa mereka kecewa terhadap reagen baru?', '{"options":[{"id":"opt_1","text":"Kit enzim mahal tersebut gagal memenuhi klaim brosur vendor, sehingga mereka kembali mengandalkan protokol buatan lab sendiri"},{"id":"opt_2","text":"Kit enzim baru menghasilkan rendemen seratus persen melebihi ekspektasi brosur"},{"id":"opt_3","text":"Mereka memutuskan membuang protokol lab sendiri dan memesan sepuluh kit lagi"},{"id":"opt_4","text":"Vendor memberikan pengembalian dana dua kali lipat tanpa diminta"}],"audio_text":"Honestly, that pricey enzyme kit didn''t live up to the vendor''s brochure—yields plateaued at forty percent, so we''re falling back on our in-house protocol."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Perhatikan dua idiom tiga kata alami AS dalam satu kalimat: ''live up to'' (memenuhi ekspektasi) dan ''fall back on'' (kembali mengandalkan cadangan).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000932', 'e5100001-0000-4000-8000-000000000115', NULL, 'writing', 'sentence_builder', 'Susun kalimat investigasi akar masalah teknis dengan ''zeroed in on'':', '{"romaji":"/ˈfleɪm ɡræf ˈproʊfaɪlɪŋ ˈkwɪkli ˈzɪroʊd ɪn ɑːn ən ʌnˈɪndɛkst ˈdʒeɪsɑːn ˈlʊkˌʌp/","tokens":["lookup inside checkout.","an unindexed JSON","Flame-graph profiling quickly","zeroed in on","into zeroing","zeroed an lookup"],"target_translation":"Pemrofilan grafik-api dengan cepat membidik tepat ke pencarian JSON tanpa indeks di dalam alur pembayaran."}'::jsonb, '["Flame-graph profiling quickly","zeroed in on","an unindexed JSON","lookup inside checkout."]'::jsonb, NULL, NULL, '''Zero in on + Noun Phrase'' menggambarkan ketajaman diagnosis teknis.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000933', 'e5100001-0000-4000-8000-000000000115', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat rangkuman kepemimpinan berikut dengan gerund sesudah ''comes down to'':', '{"romaji":"/ˈkrɔːs ˈbɔːrdər ˈmɜːrdʒər səkˈsɛs kʌmz daʊn tə rɪˈteɪnɪŋ kiː ˌɛndʒəˈnɪrɪŋ ˈtælənt/","display_text":"Cross-border merger success comes down to retaining key engineering talent.","phonetic_breakdown":["Cross-border merger success","comes down to","retaining key","engineering talent."]}'::jsonb, '{"expected_transcript":"Cross-border merger success comes down to retaining key engineering talent."}'::jsonb, NULL, NULL, 'Reduksi alami Amerika pada ''to'': /kʌmz ˈdaʊn tə rɪˈteɪnɪŋ/.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000934', 'e5100001-0000-4000-8000-000000000115', NULL, 'reading', 'fill_blank', 'Pilih idiom tiga kata yang berarti ''memenuhi ekspektasi atau reputasi besar'':', '{"options":["lived up to","fallen back to","come down on","done away with"],"translation":"Sangat sedikit perusahaan rintisan fusi nuklir yang terbukti mampu memenuhi jadwal komersialisasi akhir dekade mereka yang berani.","sentence_template":"Few Fusion startups have [blank] their bold decade-end commercialization timelines."}'::jsonb, '{"selected":"lived up to"}'::jsonb, NULL, NULL, '''Live up to [timelines/promises/expectations]'' mengukur kesesuaian hasil nyata terhadap janji awal.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000935', 'e5100001-0000-4000-8000-000000000115', NULL, 'listening', 'listening_choice', 'Dengarkan kuliah sejarah transportasi TOEFL tentang penghapusan loket tol tunai manual. Apa dampak utama kebijakan tersebut?', '{"options":[{"id":"opt_1","text":"Pengemudi diwajibkan berhenti lima menit di bawah setiap gawang pemindai"},{"id":"opt_2","text":"Emisi kendaraan justru naik enam puluh persen akibat pemasangan pemindai elektronik"},{"id":"opt_3","text":"Otoritas jalan tol menambah jumlah penjaga loket uang tunai di jembatan sungai"},{"id":"opt_4","text":"Menghapuskan gardu tol tunai dan beralih ke pemindai atas berhasil memangkas emisi antrean kendaraan di penyeberangan sungai sebesar 60%"}],"audio_text":"By doing away with cash tollbooths in favor of overhead gantry transponders, the turnpike authority slashed tailpipe idling emissions at river crossings by sixty percent."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '''By doing away with X in favor of Y'' merangkum transformasi kebijakan secara idiomatis.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000936', 'e5100001-0000-4000-8000-000000000115', NULL, 'writing', 'sentence_builder', 'Susun kalimat investigasi epidemiologi dengan ''zero in on'':', '{"romaji":"/dʒɪˈnoʊmɪk ˈkɑːntækt ˈtreɪsɪŋ hɛlpt ˌɛpəˌdiːmiˈɑːlədʒɪsts ˈzɪroʊ ɪn ɑːn ə kənˈtæməˌneɪtɪd/","tokens":["in on a","zero on in","contaminating tower","helped epidemiologists zero","contaminated cooling tower.","Genomic contact tracing"],"target_translation":"Pelacakan kontak genomik membantu para ahli epidemiologi membidik tepat sebuah menara pendingin yang terkontaminasi."}'::jsonb, '["Genomic contact tracing","helped epidemiologists zero","in on a","contaminated cooling tower."]'::jsonb, NULL, NULL, '''Help + Object + bare infinitive (zero in on + NP)''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000937', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Pilih kelanjutan gerund yang tepat sesudah preposisi ''to'' pada ''face up to'':', '{"options":["lose","losing","have lost","be lost"],"translation":"Konglomerat media cetak menunggu terlalu lama untuk berani menghadapi kenyataan hilangnya pendapatan iklan baris ke mesin pencari.","sentence_template":"Print conglomerates waited too long to face up to [blank] classified ad revenue to search engines."}'::jsonb, '{"selected":"losing"}'::jsonb, NULL, NULL, '''Face up to'' berakhir dengan preposisi ''to'', sehingga wajib diikuti gerund ''losing''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000938', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Pilih bentuk pasif utuh tiga kata dari ''do away with'' untuk kalimat reformasi birokrasi:', '{"options":["done away","away done with","done away with","did away with"],"translation":"Stempel notarisasi berulang untuk pelaporan pajak digital akhirnya telah dihapuskan di seluruh negeri.","sentence_template":"Redundant notarization stamps for digital tax filings have finally been [blank] nationwide."}'::jsonb, '{"selected":"done away with"}'::jsonb, NULL, NULL, 'Bentuk pasif perfek ''have been + V3 (done) + away + with'' wajib mempertahankan ketiga unsurnya.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000939', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'listening', 'listening_choice', 'Dengarkan saran penasihat akademik pascasarjana AS kepada mahasiswa baru kebijakan ekonomi. Apa yang perlu ia ''brush up on''?', '{"options":[{"id":"opt_1","text":"Menghapus perangkat lunak R dari laptop sebelum minggu pertama kuliah"},{"id":"opt_2","text":"Membatalkan pengambilan mata kuliah inferensi kausal karena terlalu teoretis"},{"id":"opt_3","text":"Mempelajari aljabar matriks dari nol baru pada akhir semester nanti"},{"id":"opt_4","text":"Menyegarkan kembali penguasaan aljabar matriks dan bahasa pemrograman R sebelum kuliah dimulai bulan September"}],"audio_text":"Before Prof. Miller''s causal-inference seminar starts in September, definitely brush up on matrix algebra and R—he dives straight into instrumental variables in week one!"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Konteks kampus Amerika yang sangat otentik untuk ''brush up on [prior skill]'' di TOEFL Listening.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000940', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'writing', 'sentence_builder', 'Susun kalimat ketahanan sistem navigasi menggunakan ''fall back on'':', '{"romaji":"/ʃʊd klaʊd ˈɪnfərəns taɪm aʊt ˌdaɪəɡˈnɑːstɪk ˈtæbləts fɔːl bæk ɑːn ˈkwɑːntaɪzd ˈloʊkəl/","tokens":["time out, diagnostic","models.","Should cloud inference","fall on back","tablets fall back","on quantized local","falling back to"],"target_translation":"Apabila inferensi cloud kehabisan waktu tunggu, tablet diagnostik kembali mengandalkan model lokal terkuantisasi."}'::jsonb, '["Should cloud inference","time out, diagnostic","tablets fall back","on quantized local","models."]'::jsonb, NULL, NULL, 'Menggabungkan inversi Unit 1 (''Should cloud inference time out,'') dengan idiom Unit 9 (''fall back on'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000941', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'speaking', 'speaking_repeat', 'Ucapkan kalimat realisme tata kelola dana pensiun berikut dengan lancar:', '{"romaji":"/trʌˈstiːz mʌst feɪs ʌp tə əˈdʒʌstɪŋ ˈpeɪˌaʊt əˈsʌmpʃənz æz lɔːnˈdʒɛvəti ˈraɪzɪz/","display_text":"Trustees must face up to adjusting payout assumptions as longevity rises.","phonetic_breakdown":["Trustees must","face up to","adjusting payout assumptions","as longevity rises."]}'::jsonb, '{"expected_transcript":"Trustees must face up to adjusting payout assumptions as longevity rises."}'::jsonb, NULL, NULL, 'Perhatikan tekanan suku kata akhir pada ''trus-TEES'' (/trʌˈstiːz/)!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000942', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Pilih idiom tiga kata untuk tindakan ''mengandalkan cadangan saat cara utama buntu'':', '{"options":["fall back on","do away on","brush up with","live up with"],"translation":"Setiap kali OCR otomatis salah membaca akta tanah kolonial yang pudar, para arsiparis kembali mengandalkan transkripsi paleografi manual.","sentence_template":"Whenever automated OCR misreads faded colonial land deeds, archivists [blank] manual paleographic transcription."}'::jsonb, '{"selected":"fall back on"}'::jsonb, NULL, NULL, '''Fall back on [backup method]'' adalah kolokasi tepat untuk mekanisme cadangan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000943', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'listening', 'listening_choice', 'Dengarkan keluhan insinyur perangkat keras dalam rapat retrospektif. Masalah apa yang tidak bersedia mereka ''put up with'' lagi?', '{"options":[{"id":"opt_1","text":"Mereka sangat puas dengan kecepatan pengujian otomatis selama dua kuartal terakhir"},{"id":"opt_2","text":"Mereka sudah terlalu lama menoleransi proses kompilasi pengujian CI yang tidak stabil dan memakan waktu berjam-jam"},{"id":"opt_3","text":"Mereka meminta tim menghentikan seluruh pengujian otomatis secara permanen"},{"id":"opt_4","text":"Kecepatan perilisan produk sudah mencapai rekor tercepat sepanjang sejarah"}],"audio_text":"We''ve put up with flaky four-hour CI builds for two quarters now; if we don''t parallelize test shards this sprint, release velocity will grind to a halt."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Put up with [chronic annoyance]'' (= tolerate) sangat sering keluar pada percakapan TOEFL Listening.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000944', 'e5100001-0000-4000-8000-000000000116', 'e2000001-0000-4000-8000-000000000059', 'writing', 'sentence_builder', 'Susun kalimat persiapan wawancara teknis internasional berikut:', '{"romaji":"/ˈiːvən stæf ˌɛndʒəˈnɪrz brʌʃ ʌp ɑːn dɪˈstrɪbjuːtɪd kənˈsɛnsəs pruːfs bɪˈfɔːr ˈɪntərˌvjuːɪŋ/","tokens":["into distributed","distributed consensus proofs","before interviewing at","Even staff engineers","brushing on up","infrastructure labs.","brush up on"],"target_translation":"Bahkan insinyur tingkat staf pun menyegarkan kembali pemahaman bukti konsensus terdistribusi sebelum wawancara di laboratorium infrastruktur."}'::jsonb, '["Even staff engineers","brush up on","distributed consensus proofs","before interviewing at","infrastructure labs."]'::jsonb, NULL, NULL, '''Brush up on + Noun Phrase'' tepat menggambarkan peninjauan ulang materi yang pernah dikuasai.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000945', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Pilih bentuk gerund yang wajib hadir sesudah ''get around to'':', '{"options":["pruning","prune","be pruned","pruned"],"translation":"Karena sibuk menambal celah keamanan mendesak, tim platform tidak pernah sempat memangkas resolver GraphQL yang sudah usang.","sentence_template":"Busy patching urgent CVEs, the platform squad never got around to [blank] deprecated GraphQL resolvers."}'::jsonb, '{"selected":"pruning"}'::jsonb, NULL, NULL, 'Kata ''to'' pada ''get around to'' adalah preposisi, sehingga wajib diikuti gerund ''pruning''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000946', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Pilih idiom tiga kata yang berarti ''menuntaskan komitmen hingga tuntas tereksekusi'':', '{"options":["do away from","brush up at","follow through on","fall back to"],"translation":"Pemilih mengapresiasi wali kota yang menuntaskan janji perbaikan jalan dan transportasi alih-alih terus memamerkan rencana induk tanpa ujung.","sentence_template":"Voters reward mayors who [blank] pothole and transit promises rather than unveiling endless master plans."}'::jsonb, '{"selected":"follow through on"}'::jsonb, NULL, NULL, '''Follow through on [promises/commitments]'' menekankan eksekusi nyata sampai garis akhir.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000947', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'listening', 'listening_choice', 'Dengarkan percakapan mahasiswa dengan staf perpustakaan di TOEFL Listening. Mengapa mahasiswa tersebut belum menyerahkan formulir ruang baca tesis?', '{"options":[{"id":"opt_1","text":"Ia memutuskan berhenti menyewa meja baca khusus tesis semester ini"},{"id":"opt_2","text":"Kesibukan dua ujian tengah semester dan tugas asisten lab membuatnya belum sempat mengisi dan menyerahkan formulir tersebut"},{"id":"opt_3","text":"Ia lupa membawa kartu mahasiswa saat datang ke perpustakaan hari Senin"},{"id":"opt_4","text":"Staf perpustakaan telah menghilangkan formulir perpanjangan yang ia serahkan hari Senin"}],"audio_text":"I meant to drop off my carrel renewal form on Monday, but between two midterms and lab TA duties, I just haven''t gotten around to filling it out yet!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Ungkapan Amerika sehari-hari paling khas di TOEFL Listening Part A: ''haven''t gotten around to V-ing yet''!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000948', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'writing', 'sentence_builder', 'Susun kalimat integritas ilmiah dengan ''owned up to'':', '{"romaji":"/tə ðɛr ˈkrɛdɪt ði ˈɔːθərz ˈprɑːmptli oʊnd ʌp tə ˌoʊvərˈlʊkɪŋ bætʃ ɪˈfɛkt kənˈfaʊndərz/","tokens":["confounders.","To their credit,","owned up to","overlook confounders","overlooking batch-effect","the authors promptly","owning to up"],"target_translation":"Patut diapresiasi, para penulis segera mengakui secara terbuka kelalaian mereka melewatkan variabel perancu efek-kelompok."}'::jsonb, '["To their credit,","the authors promptly","owned up to","overlooking batch-effect","confounders."]'::jsonb, NULL, NULL, 'Pembuka ''To their credit,'' berpadu harmonis dengan ''owned up to + V-ing (overlooking...)''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000949', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'speaking', 'speaking_repeat', 'Ucapkan kalimat evaluasi mutu manufaktur berikut dengan jelas:', '{"romaji":"/riːˈsaɪkəld ˈkæθoʊd ˈpaʊdərz naʊ ˈmɛʒər ʌp tə ˈvɜːrdʒən ˈbætəri ɡreɪd ˈlɪθiəm ˈstændərdz/","display_text":"Recycled cathode powders now measure up to virgin battery-grade lithium standards.","phonetic_breakdown":["Recycled cathode powders","now measure up to","virgin battery-grade","lithium standards."]}'::jsonb, '{"expected_transcript":"Recycled cathode powders now measure up to virgin battery-grade lithium standards."}'::jsonb, NULL, NULL, '''Measure up to [standards]'' menyampaikan kesetaraan mutu teknis terhadap tolok ukur industri.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000950', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Pilih idiom tiga kata yang tepat untuk arti ''mengakui kesalahan secara jujur'':', '{"options":["brushed up on","did away with","fell back on","owned up to"],"translation":"Menerbitkan laporan pasca-insiden transparan yang secara jujur mengakui pergeseran konfigurasi berhasil memulihkan kepercayaan korporat lebih cepat daripada berdiam diri.","sentence_template":"Publishing a transparent postmortem that [blank] configuration drift rebuilt enterprise trust faster than silence."}'::jsonb, '{"selected":"owned up to"}'::jsonb, NULL, NULL, '''Own up to [an error/drift]'' adalah standar budaya rekayasa yang matang.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000951', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'listening', 'listening_choice', 'Dengarkan penilaian analis industri otomotif AS tentang pemasok baterai lokal baru. Di mana letak kekurangannya?', '{"options":[{"id":"opt_1","text":"Analis menyarankan produsen mobil menghapus uji umur siklus baterai"},{"id":"opt_2","text":"Pemasok lokal baru tersebut sudah melampaui seluruh pabrikan Asia Timur dalam semua aspek"},{"id":"opt_3","text":"Konsistensi umur siklus pakainya masih belum sepenuhnya menyamai standar mutu pemasok papan atas Asia Timur"},{"id":"opt_4","text":"Kepadatan energi selnya jauh tertinggal di atas kertas dibandingkan pesaing"}],"audio_text":"Their cell energy density looks competitive on spec sheets, yet cycle-life consistency still doesn''t quite measure up to established East Asian tier-one suppliers."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Doesn''t quite measure up to [benchmark]'' adalah kritik perbandingan kualitas yang halus dan presisi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000952', 'e5100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000059', 'writing', 'sentence_builder', 'Susun kalimat tata kelola iklim korporat dengan ''follow through on'':', '{"romaji":"/ˌɪnstəˈtuːʃənəl ɪnˈvɛstərz træk ˈwɛðər ɪˈmɪtərz ˈæktʃuəli ˈfɑːloʊ θruː ɑːn ˈɪntərəm/","tokens":["interim 2030 decarbonization","following on through","Institutional investors track","to follow on","targets.","follow through on","whether emitters actually"],"target_translation":"Investor institusional melacak apakah penghasil emisi benar-benar menuntaskan target dekarbonisasi antara tahun 2030."}'::jsonb, '["Institutional investors track","whether emitters actually","follow through on","interim 2030 decarbonization","targets."]'::jsonb, NULL, NULL, '''Follow through on + Noun Phrase'' menjaga integritas antara janji dan realisasi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000953', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Pilih bentuk gerund sesudah preposisi ''to'' pada ''come down to'':', '{"options":["enforce","enforcing","enforced","be enforcing"],"translation":"Mencegah infeksi nosokomial rumah sakit sering kali mengerucut pada penegakan kepatuhan cuci tangan yang ketat di sela kunjungan bangsal.","sentence_template":"Preventing hospital-acquired infections often comes down to [blank] strict hand-hygiene compliance between ward rounds."}'::jsonb, '{"selected":"enforcing"}'::jsonb, NULL, NULL, '''Comes down to + V-ing (enforcing)'' wajib memakai gerund.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000954', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Terapkan kaidah *inseparability* untuk kata ganti objek ''it'':', '{"options":["did it away with","did away with it","away with it did","did away it with"],"translation":"Meskipun konfirmasi faks masih tertinggal di undang-undang kesehatan lama, aturan kesehatan digital federal akhirnya menghapuskannya.","sentence_template":"Although fax confirmation remained in old healthcare statutes, federal digital-health rules finally [blank]."}'::jsonb, '{"selected":"did away with it"}'::jsonb, NULL, NULL, 'Pronomina ''it'' wajib diletakkan sesudah keseluruhan tiga kata ''did away with''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000955', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'listening', 'listening_choice', 'Evaluasi Unit 9 — Dengarkan diskusi dekan dan ketua jurusan tentang akreditasi laboratorium. Apa langkah mendesak mereka bulan ini?', '{"options":[{"id":"opt_1","text":"Jurusan memutuskan menutup laboratorium kimia selamanya sebelum bulan November"},{"id":"opt_2","text":"Peninjau memuji ketiga kipas pembuangan tua karena masih berfungsi sempurna"},{"id":"opt_3","text":"Catatan aliran udara lemari asam tidak diperiksa sama sekali saat akreditasi"},{"id":"opt_4","text":"Peninjau akreditasi membidik tajam catatan aliran udara lemari asam, sehingga kampus harus menghadapi kenyataan mengganti tiga kipas pembuangan tua"}],"audio_text":"Accreditation reviewers zeroed in on chemical-hood airflow logs, so we''ve got to face up to replacing three aging exhaust fans before November''s revisit."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Dua idiom tiga kata (''zeroed in on'' + ''face up to replacing'') merangkum temuan dan tindak lanjut secara alami.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000956', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'writing', 'sentence_builder', 'Evaluasi Unit 9 — Susun kalimat pencadangan komunikasi darurat dengan ''fell back on'':', '{"romaji":"/ˈsʌbˌsiː ˈkeɪbəlz ˈsɛvərd baɪ ˈæŋkər dræɡ ˈɛr ˈtræfɪk kənˈtroʊlərz fɛl bæk ɑːn/","tokens":["back on high-frequency","Subsea cables severed","radio.","by anchor drag,","were severed","fell on back","air-traffic controllers fell"],"target_translation":"Setelah kabel bawah laut terputus terseret jangkar, pemandu lalu lintas udara kembali mengandalkan radio frekuensi tinggi."}'::jsonb, '["Subsea cables severed","by anchor drag,","air-traffic controllers fell","back on high-frequency","radio."]'::jsonb, NULL, NULL, 'Menggabungkan konstruksi absolut pasif (''Subsea cables severed...,'') dengan ''fell back on''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000957', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'speaking', 'speaking_repeat', 'Evaluasi Unit 9 — Ucapkan kalimat akuntabilitas eksekutif berikut dengan lancar:', '{"romaji":"/ˈkrɛdəbəl ˈliːdərz oʊn ʌp tə ˈfɔːrˌkæstɪŋ ˈɛrərz ænd ˈfɑːloʊ θruː ɑːn rɪˈfɔːrmz/","display_text":"Credible leaders own up to forecasting errors and follow through on reforms.","phonetic_breakdown":["Credible leaders","own up to","forecasting errors and","follow through on reforms."]}'::jsonb, '{"expected_transcript":"Credible leaders own up to forecasting errors and follow through on reforms."}'::jsonb, NULL, NULL, 'Alirkan kedua idiom tiga kata (''own up to'' + ''follow through on'') secara sejajar dan mantap.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000958', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'reading', 'fill_blank', 'Evaluasi Unit 9 — Pilih idiom yang tepat untuk calon diplomat yang ''menyegarkan kembali kemahiran bahasa Prancisnya'':', '{"options":["brushing up on","doing away with","coming down on","putting up at"],"translation":"Karena ditugaskan ke Jenewa kuartal depan, konselor perdagangan kita sedang menyegarkan kembali bahasa Prancis perjanjian multilateralnya setiap malam.","sentence_template":"Posted to Geneva next quarter, our trade counselor is [blank] multilateral treaty French every evening."}'::jsonb, '{"selected":"brushing up on"}'::jsonb, NULL, NULL, '''Brush up on [a language/skill]'' mengaktifkan kembali kecakapan yang sudah pernah dipelajari.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000959', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'listening', 'listening_choice', 'Evaluasi Unit 9 — Dengarkan ulasan kritikus teknologi tentang kacamata realitas tertambah generasi pertama. Mengapa produk tersebut gagal?', '{"options":[{"id":"opt_1","text":"Konsumen tidak memedulikan daya tahan baterai maupun sudut pandang layar"},{"id":"opt_2","text":"Daya tahan baterai dan sudut pandang gagal memenuhi ekspektasi konsumen, dan pengembang pun tidak pernah sempat membangun aplikasi kerja unggulan"},{"id":"opt_3","text":"Produk tersebut laris terjual berkat daya tahan baterai yang melampaui janji panggung"},{"id":"opt_4","text":"Pengembang berhasil merilis ratusan aplikasi kerja unggulan pada hari peluncuran"}],"audio_text":"Despite dazzling keynote demos, battery life and field of view never lived up to consumer expectations, nor did developers ever get around to building killer workplace apps."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan perpaduan ''lived up to'', inversi negatif ''nor did developers ever'', dan ''get around to building''!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000960', 'e5100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000059', 'writing', 'sentence_builder', 'Evaluasi Unit 9 — Susun kalimat pasif utuh dari phrasal-prepositional verb:', '{"romaji":"/ˌʌnɪnˈkrɪptɪd ˈtɛlnɛt pɔːrts ʃʊd həv bɪn dʌn əˈweɪ wɪð ˈoʊvər tuː ˈdɛkeɪdz əˈɡoʊ/","tokens":["done away with","done away over","over two decades","should have been","Unencrypted telnet ports","ago.","doing away with"],"target_translation":"Porta telnet tanpa enkripsi semestinya sudah dihapuskan lebih dari dua dekade silam."}'::jsonb, '["Unencrypted telnet ports","should have been","done away with","over two decades","ago."]'::jsonb, NULL, NULL, 'Modal pasif perfek ''should have been + done away with'' menjaga keutuhan tiga kata idiom.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000961', 'e5100001-0000-4000-8000-000000000119', NULL, 'reading', 'fill_blank', 'Pilih pasangan antitesis proporsional dengan pengulangan preposisi ''about'' yang sejajar:', '{"options":["then about","but for","as about","than about"],"translation":"Mencegah kebakaran hutan dahsyat bukan terutama soal membeli pesawat pengebom air yang lebih besar, melainkan soal memulihkan pembakaran terkendali berintensitas rendah.","sentence_template":"Preventing catastrophic wildfires is less about buying larger water bombers [blank] restoring controlled low-intensity burns."}'::jsonb, '{"selected":"than about"}'::jsonb, NULL, NULL, '''Less about + V-ing ... than about + V-ing'' menciptakan kontras prioritas yang sangat elegan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000962', 'e5100001-0000-4000-8000-000000000119', NULL, 'reading', 'fill_blank', 'Pahami idiom sastra-akademik TOEFL Reading! Apa arti frasa yang menyatukan dua sifat paradoks ''intimate'' dan ''monumental'' sekaligus?', '{"options":["at once","once again","for once","at first"],"translation":"Monumen Veteran Vietnam karya Maya Lin sekaligus terasa sangat intim melalui pantulan nama-namanya dan monumental dalam wibawa publiknya.","sentence_template":"Maya Lin''s Vietnam Veterans Memorial is [blank] deeply intimate in its reflective names and monumental in its civic gravity."}'::jsonb, '{"selected":"at once"}'::jsonb, NULL, NULL, '''At once [Adj A] and [Adj B]'' berarti ''both A and B at the same time''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000963', 'e5100001-0000-4000-8000-000000000119', NULL, 'listening', 'listening_choice', 'Dengarkan pidato pembukaan CTO pada konferensi arsitektur sistem. Bagaimana ia membingkai ulang arti keandalan (*reliability*)?', '{"options":[{"id":"opt_1","text":"Fitur pengembalian versi (*rollback*) dihapus agar insinyur tidak pernah berbuat salah"},{"id":"opt_2","text":"Insinyur manusia dilarang keras menyentuh server produksi dalam kondisi apa pun"},{"id":"opt_3","text":"Keandalan tinggi dicapai bukan dengan melarang insinyur menyentuh produksi, melainkan dengan membuat pemulihan versi berlangsung cepat, aman, dan terlatih rutin"},{"id":"opt_4","text":"Keandalan sistem hanya bergantung pada pembelian perangkat keras termahal"}],"audio_text":"Ultimately, five-nines reliability is achieved not by forbidding human engineers from touching production, but by making rollbacks fast, safe, and muscle-memory routine."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Antitesis ''not by V-ing..., but by V-ing...'' ditutup dengan *tricolon* (''fast, safe, and muscle-memory routine'')!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000964', 'e5100001-0000-4000-8000-000000000119', NULL, 'writing', 'sentence_builder', 'Susun kalimat penegas Wh-Cleft antitesis berikut:', '{"romaji":"/wʌt dɪˈstɪŋɡwɪʃɪz ɪnˈdʊrɪŋ ˌɪnstəˈtuːʃənz ɪz nɑːt ɪnˈfæləbəl ˈliːdərˌʃɪp bʌt ˈsɛlf kəˈrɛktɪŋ/","tokens":["infallible leadership, but","self-correcting governance.","institutions is not","than self-correcting","What distinguishes enduring","not infallibly"],"target_translation":"Hal yang membedakan institusi yang bertahan lama bukanlah kepemimpinan yang tak pernah salah, melainkan tata kelola yang mampu mengoreksi diri."}'::jsonb, '["What distinguishes enduring","institutions is not","infallible leadership, but","self-correcting governance."]'::jsonb, NULL, NULL, '''What distinguishes X is not [NP A], but [NP B]'' memberikan kalimat tesis sekelas esai puncak.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000965', 'e5100001-0000-4000-8000-000000000119', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat evaluasi karya klasik berikut dengan irama yang mantap:', '{"romaji":"/kliːn æbˈstrækʃənz stænd ðə tɛst ʌv taɪm lɔːŋ ˈæftər ˈfreɪmˌwɜːrks feɪd/","display_text":"Clean abstractions stand the test of time long after frameworks fade.","phonetic_breakdown":["Clean abstractions","stand the test of time","long after","frameworks fade."]}'::jsonb, '{"expected_transcript":"Clean abstractions stand the test of time long after frameworks fade."}'::jsonb, NULL, NULL, 'Tekankan aliterasi halus pada ''FRAMEWORKS FADE'' di akhir kalimat.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000966', 'e5100001-0000-4000-8000-000000000119', NULL, 'reading', 'fill_blank', 'Pilih idiom yang berarti ''bertahan melewati ujian zaman selama puluhan/ratusan tahun'':', '{"options":["stopped short of","taken at face value","brushed up on","stood the test of time"],"translation":"Prinsip ujung-ke-ujung TCP/IP telah terbukti tahan uji melintasi zaman, berkembang dari puluhan simpul kampus hingga miliaran gawai seluler.","sentence_template":"TCP/IP''s end-to-end principle has [blank], scaling from a few dozen university nodes to billions of mobile devices."}'::jsonb, '{"selected":"stood the test of time"}'::jsonb, NULL, NULL, 'Bentuk Present Perfect ''has stood the test of time'' merayakan ketangguhan desain jangka panjang.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000967', 'e5100001-0000-4000-8000-000000000119', NULL, 'listening', 'listening_choice', 'Dengarkan pembahasan soal kosakata konteks TOEFL Reading tentang prosa Rachel Carson di buku *Silent Spring*. Mengapa gaya tulisannya begitu efektif?', '{"options":[{"id":"opt_1","text":"Buku tersebut hanya dapat dipahami oleh ahli kimia toksikologi di laboratorium"},{"id":"opt_2","text":"Frasa ''at once'' berarti buku tersebut ditulis hanya dalam satu hari"},{"id":"opt_3","text":"Tulisannya memadukan ketelitian ilmiah dan daya desak puitis secara bersamaan sehingga warga awam memahami bahaya toksikologi"},{"id":"opt_4","text":"Carson mengabaikan data ilmiah demi menulis puisi fiksi semata"}],"audio_text":"Carson''s prose was at once scientifically meticulous and poetically urgent, translating parts-per-million toxicology into a moral awakening regular citizens could grasp."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Memastikan penguasaan penuh atas konstruksi ''at once [Adv+Adj] and [Adv+Adj]''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000968', 'e5100001-0000-4000-8000-000000000119', NULL, 'writing', 'sentence_builder', 'Susun kalimat antitesis proporsional ''less ... than'' dengan preposisi ''in'':', '{"romaji":"/ðə ˈbreɪkˌθruː leɪ lɛs ɪn rɔː pəˈræmətər kaʊnt ðæn ɪn ˈkjʊreɪtɪd sɪnˈθɛtɪk/","tokens":["in curated synthetic","parameter count than","than raw","less in raw","reasoning traces.","less about","The breakthrough lay"],"target_translation":"Terobosan tersebut terletak bukan terutama pada jumlah parameter mentah, melainkan pada jejak penalaran sintetis yang terkurasi."}'::jsonb, '["The breakthrough lay","less in raw","parameter count than","in curated synthetic","reasoning traces."]'::jsonb, NULL, NULL, 'Ingat bentuk lampau dari ''lie'' (terletak) adalah ''lay'' (/leɪ/): ''lay less in X than in Y''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000969', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Pilih penutup daftar tiga serangkai (*tricolon*) yang mematuhi kaidah paralelisme sekaligus bobot klimaks menanjak (*end-weight*):', '{"options":["to manufacture equitably","cheap","equitable manufacturing across developing regions","also drugs"],"translation":"Kesiapsiagaan pandemi yang efektif menuntut pengurutan cepat, pelaporan transparan, serta manufaktur yang merata di seluruh kawasan berkembang.","sentence_template":"Effective pandemic preparedness requires rapid sequencing, transparent reporting, and [blank]."}'::jsonb, '{"selected":"equitable manufacturing across developing regions"}'::jsonb, NULL, NULL, 'Dua frasa benda pertama terdiri atas 2 kata (''rapid sequencing, transparent reporting''); menutup dengan frasa benda paralel 5 kata menciptakan klimaks *tricolon* yang utuh.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000970', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Lengkapi struktur pembalikan cermin (*chiasmus*) tentang arsitektur perangkat lunak dan organisasi:', '{"options":["built by them","are software too","reshape the organizations that built them","designing communication"],"translation":"Organisasi merancang sistem perangkat lunak mengikuti struktur komunikasinya, dan tak lama kemudian sistem perangkat lunak itulah yang membentuk ulang organisasi pembuatnya.","sentence_template":"Organizations design software systems around their communication structures, and soon enough those software systems [blank]."}'::jsonb, '{"selected":"reshape the organizations that built them"}'::jsonb, NULL, NULL, 'Membalikkan arah pengaruh `Organizations -> Systems` menjadi `Systems -> Organizations` menciptakan resonansi retoris.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000971', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'listening', 'listening_choice', 'Dengarkan analisis profesor retorika tentang pidato antariksa Presiden John F. Kennedy di Rice University (1962). Struktur apa yang membuat kalimatnya legendaris?', '{"options":[{"id":"opt_1","text":"Pidato tersebut menyarankan penundaan program antariksa hingga abad berikutnya"},{"id":"opt_2","text":"Kalimat tersebut menghindari pengulangan kata ''because'' sama sekali"},{"id":"opt_3","text":"Kennedy menyatakan perjalanan ke Bulan dipilih karena biayanya murah dan mudah"},{"id":"opt_4","text":"Antitesis kausal tajam (''not because they are easy, but because they are hard'') yang membalikkan ekspektasi alasan lazim"}],"audio_text":"Listen to Kennedy''s cadence: ''We choose to go to the Moon in this decade and do the other things, not because they are easy, but because they are hard''—pure causal antithesis!"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Contoh paling mahsyur dalam sejarah retorika Amerika untuk ''not because [A], but because [B]''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000972', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'writing', 'sentence_builder', 'Susun kalimat *tricolon* dengan irama suku kata menanjak (pendek -> sedang -> panjang):', '{"romaji":"/saʊnd ˈmɑːnəˌtɛri ˈpɑːləsi mʌst rɪˈmeɪn ˌɪndɪˈpɛndənt ˈdeɪtə ˈdrɪvən ænd ˈɪnsəˌleɪtɪd frʌm/","tokens":["data-driven, and insulated","cycles.","Sound monetary policy","insulating from","from short-term electoral","short-term, and smart","must remain independent,"],"target_translation":"Kebijakan moneter yang sehat wajib tetap independen, berbasis data, serta terlindung dari siklus pemilu jangka pendek."}'::jsonb, '["Sound monetary policy","must remain independent,","data-driven, and insulated","from short-term electoral","cycles."]'::jsonb, NULL, NULL, '1 kata (''independent'') -> 2 kata (''data-driven'') -> 6 kata (''insulated from short-term electoral cycles''): irama klimaks sempurna!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000973', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'speaking', 'speaking_repeat', 'Ucapkan kalimat cermin (*chiasmus*) tata kelola AI berikut dengan penekanan kontras yang jernih:', '{"romaji":"/ˈælɡəˌrɪðəmz ʃʊd ɔːɡˈmɛnt ˈhjuːmən əˌkaʊntəˈbɪləti ˈnɛvər rɪˈpleɪs ˈhjuːmən əˌkaʊntəˈbɪləti wɪð oʊˈpæsəti/","display_text":"Algorithms should augment human accountability, never replace human accountability with opacity.","phonetic_breakdown":["Algorithms should augment","human accountability,","never replace human accountability","with opacity."]}'::jsonb, '{"expected_transcript":"Algorithms should augment human accountability, never replace human accountability with opacity."}'::jsonb, NULL, NULL, 'Perhatikan tekanan verba ''aug-MENT'' (/ɔːɡˈmɛnt/) dan kontras dengan ''re-PLACE'' + ''o-PAC-i-ty'' (/oʊˈpæsəti/).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000974', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Pilih pasangan paralel infinitif untuk kalimat pembuka berbasis anafora (''To delay X is...''):', '{"options":["for guaranteeing","guaranteeing","guaranteed","to guarantee"],"translation":"Menunda restorasi bakau pesisir hari ini sama saja dengan menjamin tagihan pertahanan banjir yang berlipat ganda besok.","sentence_template":"To defer coastal mangrove restoration today is [blank] exponentially higher flood-defense bills tomorrow."}'::jsonb, '{"selected":"to guarantee"}'::jsonb, NULL, NULL, 'Subjek infinitif ''To defer X today'' menuntut pelengkap predikat infinitif sejajar ''is to guarantee Y tomorrow''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000975', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'listening', 'listening_choice', 'Dengarkan penutup kuliah etika rekayasa tentang Jembatan Tacoma Narrows dan keselamatan struktural. Bagaimana dosen menyusun kalimat pamungkasnya?', '{"options":[{"id":"opt_1","text":"Menganggap verifikasi independen membuang-buang anggaran pembangunan jembatan"},{"id":"opt_2","text":"Menyatakan bahwa standar rekayasa ditulis murni berdasarkan teori matematika tanpa belajar dari kegagalan"},{"id":"opt_3","text":"Menyarankan penghapusan faktor cadangan keamanan (*redundancy*) pada jembatan gantung"},{"id":"opt_4","text":"Membuka dengan antitesis (''not in abstract ink, but in hard-won lessons...'') lalu menguncinya dengan *tricolon* klimaks (''humility, redundancy, and independent verification'')"}],"audio_text":"Engineering codes are written not in abstract ink, but in the hard-won lessons of past failures—reminding every generation that humility, redundancy, and independent verification save lives."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Mengenali anatomi kalimat penutup pidato/kuliah tingkat C2.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000976', 'e5100001-0000-4000-8000-000000000120', 'e2000001-0000-4000-8000-000000000060', 'writing', 'sentence_builder', 'Susun kalimat antitesis kausal ''not because ... but because'' untuk esai beasiswa:', '{"romaji":"/wi ʃɛr dʒɪˈnoʊmɪk ˈpaɪpˌlaɪnz ˈoʊpənli nɑːt bɪˈkɔːz ˈpæθədʒənz rɪˈspɛkt ˈbɔːrdərz bʌt prɪˈsaɪsli/","tokens":["because pathogens respect","We share genomic","not due to","because they ignore them.","pipelines openly, not","borders, but precisely","ignoring them"],"target_translation":"Kita membagikan alur kerja genomik secara terbuka, bukan karena patogen menghormati batas negara, melainkan justru karena patogen mengabaikannya."}'::jsonb, '["We share genomic","pipelines openly, not","because pathogens respect","borders, but precisely","because they ignore them."]'::jsonb, NULL, NULL, 'Penegas ''but precisely because...'' mempertajam antitesis alasan ilmiah.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000977', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Pilih kolokasi kata sifat C2 yang berarti ''jejak yang tak terhapuskan'':', '{"options":["indelible","untenable","uncorroborated","anecdotal"],"translation":"Institusi-institusi Bretton Woods meninggalkan jejak yang tak terhapuskan pada arsitektur moneter pascaperang, terlepas dari reformasi mereka di kemudian hari.","sentence_template":"Bretton Woods institutions left an [blank] mark on postwar monetary architecture, notwithstanding their later reforms."}'::jsonb, '{"selected":"indelible"}'::jsonb, NULL, NULL, '''Leave an indelible mark on [history/field]'' adalah kolokasi baku untuk pengaruh abadi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000978', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Pilih idiom kepemimpinan untuk ''bangkit menjawab tantangan besar saat dibutuhkan'':', '{"options":["fell back to","took at face value","stopped short of","rose to the occasion"],"translation":"Setiap kali putusnya serat optik bawah laut mengancam konektivitas pulau, para insinyur jaringan lokal secara konsisten bangkit menjawab tantangan tersebut.","sentence_template":"Whenever submarine fiber cuts threatened island connectivity, local network engineers consistently [blank]."}'::jsonb, '{"selected":"rose to the occasion"}'::jsonb, NULL, NULL, 'Bentuk lampau dari ''rise to the occasion'' adalah ''rose to the occasion''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000979', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'listening', 'listening_choice', 'Dengarkan kalimat penutup pidato penerimaan beasiswa doktor seorang ilmuwan asal Indonesia di AS. Bagaimana ia merangkai misinya?', '{"options":[{"id":"opt_1","text":"Ia berencana menghindari publikasi jurnal ilmiah sama sekali selama studi doktor"},{"id":"opt_2","text":"Ia hanya ingin meneliti topik yang tidak berkaitan dengan layanan kesehatan Indonesia"},{"id":"opt_3","text":"Ia menyatakan bahwa rumah sakit daerah tidak membutuhkan riset onkologi komputasional"},{"id":"opt_4","text":"Ambisinya bukan sekadar menerbitkan jurnal elit demi prestise semata, melainkan menjembatani jurang antara onkologi komputasional di Boston dan RS daerah di Indonesia"}],"audio_text":"My ambition is less about publishing in elite journals for its own sake than about bridging the divide between computational oncology in Boston and district hospitals across Indonesia."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Perpaduan ''less about V-ing ... than about bridging the divide between A and B'' menciptakan penutup wawancara yang sangat menyentuh dan berbobot.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000980', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'writing', 'sentence_builder', 'Susun kalimat navigasi kebijakan publik dengan ''chart a pragmatic course'':', '{"romaji":"/smɔːl ˈoʊpən iˈkɑːnəmiz mʌst tʃɑːrt ə præɡˈmætɪk kɔːrs bɪˈtwiːn səˈplaɪ tʃeɪn rɪˈzɪljəns/","tokens":["Small open economies","supply-chain resilience and","to free trade","charting course","must chart a","free trade.","pragmatic course between"],"target_translation":"Negara-negara dengan ekonomi terbuka berskala menengah-kecil harus memetakan haluan pragmatis di antara ketahanan rantai pasok dan perdagangan bebas."}'::jsonb, '["Small open economies","must chart a","pragmatic course between","supply-chain resilience and","free trade."]'::jsonb, NULL, NULL, '''Chart a [Adj] course between A and B'' memadukan metafora kemudi dengan paralelisme.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000981', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'speaking', 'speaking_repeat', 'Ucapkan kalimat puncak pidato kelulusan tingkat C2 berikut dengan artikulasi berwibawa:', '{"romaji":"/ˈliːdərˌʃɪp ɪz ˈmɛʒərd nɑːt baɪ ˈtaɪtəlz hɛld bʌt baɪ dɪˈvaɪdz brɪdʒd wɪð ɪnˈtɛɡrəti/","display_text":"Leadership is measured not by titles held, but by divides bridged with integrity.","phonetic_breakdown":["Leadership is measured","not by titles held,","but by divides bridged","with integrity."]}'::jsonb, '{"expected_transcript":"Leadership is measured not by titles held, but by divides bridged with integrity."}'::jsonb, NULL, NULL, 'Perhatikan paralelisme partisip pasif pasca-nomina: ''titles HELD'' vs. ''divides BRIDGED''!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000982', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Pilih frasa kerja yang berarti ''menjembatani jurang pemisah antara dua dunia'':', '{"options":["take exception to","cast doubt on","do away with","bridge the divide between"],"translation":"Kedokteran translasional hadir secara khusus untuk menjembatani jurang pemisah antara penemuan molekuler di meja lab dan perawatan pasien di tepi ranjang.","sentence_template":"Translational medicine exists specifically to [blank] benchtop molecular discoveries and bedside patient care."}'::jsonb, '{"selected":"bridge the divide between"}'::jsonb, NULL, NULL, '''Bridge the divide between [benchtop] and [bedside]'' adalah ungkapan klasik kedokteran modern.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000983', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'listening', 'listening_choice', 'Dengarkan nasihat terakhir profesor penulisan ilmiah kepada kandidat TOEFL iBT 115–120. Apa peringatan emasnya tentang gaya bahasa C2?', '{"options":[{"id":"opt_1","text":"Kemahiran C2 sejati bukan menjejalkan inversi kuno di setiap kalimat, melainkan memakai struktur presisi tepat saat struktur itu mempertajam logika, memperjelas lingkup, dan mengangkat irama"},{"id":"opt_2","text":"Peserta TOEFL disarankan hanya menggunakan kalimat pendek lima kata tanpa konjungsi"},{"id":"opt_3","text":"Struktur inversi wajib muncul di setiap kalimat pertama hingga kalimat terakhir esai"},{"id":"opt_4","text":"Semakin panjang dan rumit setiap kalimat, semakin tinggi skor otomatis yang diperoleh"}],"audio_text":"True C2 mastery isn''t stuffing every sentence with archaic inversions—it''s deploying precision structures only where they sharpen logic, clarify scope, and elevate cadence!"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Prinsip puncak stilistika C2: kejelasan, ketepatan ruang lingkup, dan irama (*sharpen logic, clarify scope, and elevate cadence*).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000984', 'e5100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000060', 'writing', 'sentence_builder', 'Susun kalimat sintesis pamungkas kurikulum bahasa Inggris Merantalk:', '{"romaji":"/ˈmæstəri kʌmz daʊn tə ˈspiːkɪŋ ˈklɪrli ˈriːzənɪŋ ˈrɪɡərəsli ænd ˈbrɪdʒɪŋ ˈkʌltʃərz wɪð hjuːˈmɪləti/","tokens":["bridging cultures with","to speaking clearly,","reasoning rigorously, and","Mastery comes down","speak clearly","humility.","with humble"],"target_translation":"Kemahiran sejati mengerucut pada berbicara dengan jernih, bernalar dengan ketat, serta menjembatani lintas budaya dengan kerendahan hati."}'::jsonb, '["Mastery comes down","to speaking clearly,","reasoning rigorously, and","bridging cultures with","humility."]'::jsonb, NULL, NULL, 'Memadukan ''comes down to'' + *tricolon gerund* berirama menanjak (''speaking clearly, reasoning rigorously, and bridging cultures with humility'')!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000985', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih bentuk antitesis proporsional yang sejajar sesudah ''less on'':', '{"options":["then on","as in","but on","than on"],"translation":"Kepemimpinan semikonduktor jangka panjang bergantung bukan terutama pada subsidi pabrik satu kali, melainkan pada kesinambungan jalur talenta kampus dan industri pengecoran.","sentence_template":"Long-term semiconductor leadership depends less on one-off factory subsidies [blank] sustained university-foundry talent pipelines."}'::jsonb, '{"selected":"than on"}'::jsonb, NULL, NULL, 'Preposisi ''on'' sesudah ''less'' diulang secara simetris sesudah ''than'' (''less on X than on Y'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000986', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih frasa yang berarti ''sekaligus secara bersamaan'' di depan dua sifat kontras:', '{"options":["at once","at least","once more","for all"],"translation":"Geografi maritim kepulauan tersebut sekaligus merupakan rintangan logistik yang berat dan perisai geopolitik alami.","sentence_template":"The archipelago''s maritime geography is [blank] a formidable logistical hurdle and a natural geopolitical shield."}'::jsonb, '{"selected":"at once"}'::jsonb, NULL, NULL, '''At once [NP A] and [NP B]'' menyandingkan paradoks geografi dalam satu bingkai utuh.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000987', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'listening', 'listening_choice', 'Evaluasi Unit 10 — Dengarkan penutup pidato rektor universitas riset tentang kecerdasan buatan. Bagaimana ia menggunakan *chiasmus* dan *tricolon*?', '{"options":[{"id":"opt_1","text":"Menyatakan bahwa mesin kecerdasan buatan tidak pernah perlu dipertanyakan hasilnya"},{"id":"opt_2","text":"Meminta mahasiswa berhenti mempelajari teknologi komputer demi fokus pada filsafat kuno saja"},{"id":"opt_3","text":"Menghapus mata kuliah etika dari kurikulum fakultas ilmu komputer"},{"id":"opt_4","text":"Mengontraskan ''prompt machines'' vs. ''question them'', lalu menutup dengan *tricolon* klimaks (''technically fluent, ethically grounded, and unafraid of complex truth'')"}],"audio_text":"We must train students not merely to prompt machines, but to question them—graduating citizens who are technically fluent, ethically grounded, and unafraid of complex truth."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Kombinasi antitesis infinitif + *tricolon* sifat menanjak menciptakan penutup pidato kelas dunia.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000988', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'writing', 'sentence_builder', 'Evaluasi Unit 10 — Susun kalimat kesetaraan infinitif berbasis anafora (''To neglect X is to invite Y''):', '{"romaji":"/tə nɪˈɡlɛkt faʊnˈdeɪʃənəl məˈtrɑːlədʒi læbz təˈdeɪ ɪz tə ˈfɔːrfɪt prɪˈsɪʒən ˌmænjəˈfæktʃərɪŋ təˈmɑːroʊ/","tokens":["neglecting labs","metrology labs today","forfeiting precision","is to forfeit","To neglect foundational","precision manufacturing tomorrow."],"target_translation":"Mengabaikan laboratorium metrologi dasar hari ini sama saja dengan melepaskan manufaktur presisi di hari esok."}'::jsonb, '["To neglect foundational","metrology labs today","is to forfeit","precision manufacturing tomorrow."]'::jsonb, NULL, NULL, 'Simetri sempurna antara ''To neglect X today'' dan ''is to forfeit Y tomorrow''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000989', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'speaking', 'speaking_repeat', 'Evaluasi Unit 10 — Ucapkan kalimat visi kepemimpinan global berikut dengan penuh wibawa:', '{"romaji":"/truː ˈskɑːlərˌʃɪp tʃɑːrts ə kɔːrs dɪˈfaɪnd nɑːt baɪ ˈkʌmfərt bʌt baɪ ˈpʌblɪk ˈsɜːrvɪs/","display_text":"True scholarship charts a course defined not by comfort, but by public service.","phonetic_breakdown":["True scholarship","charts a course","defined not by comfort,","but by public service."]}'::jsonb, '{"expected_transcript":"True scholarship charts a course defined not by comfort, but by public service."}'::jsonb, NULL, NULL, 'Beri jeda sesaat sebelum ''but by PUBLIC SERVICE'' untuk mengunci penekanan akhir.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000990', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'reading', 'fill_blank', 'Evaluasi Unit 10 — Pilih anggota ketiga *tricolon* agar paralel dengan dua kata sifat sebelumnya dan memberi bobot akhir:', '{"options":["resistant to coercion at scale","coercion resistance","resist coercion","fast"],"translation":"Bukti pemungutan suara kriptografis wajib kokoh secara matematis, dapat diaudit publik, serta tahan terhadap pemaksaan berskala luas.","sentence_template":"Cryptographic voting receipts must be mathematically sound, publicly auditable, and [blank]."}'::jsonb, '{"selected":"resistant to coercion at scale"}'::jsonb, NULL, NULL, 'Frasa kata sifat panjang ''resistant to coercion at scale'' sejajar dengan ''sound'' dan ''auditable'' sekaligus memenuhi kaidah *end-weight*.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000991', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'listening', 'listening_choice', 'Evaluasi Unit 10 — Dengarkan refleksi diplomat senior PBB tentang perjanjian ozon Protokol Montreal 1987. Mengapa perjanjian itu ''stood the test of time''?', '{"options":[{"id":"opt_1","text":"Protokol Montreal gagal menghentikan penipisan lapisan ozon sejak tahun 1987"},{"id":"opt_2","text":"Negara berkembang dikecualikan dari bantuan pendanaan transisi bahan kimia"},{"id":"opt_3","text":"Tidak ada perdebatan diplomatik sama sekali saat perjanjian dirundingkan"},{"id":"opt_4","text":"Protokol Montreal bertahan melintasi zaman bukan karena diplomasinya mudah, melainkan karena ilmuwan, insinyur kimia, dan dana negara berkembang bergerak serempak"}],"audio_text":"The Montreal Protocol has stood the test of time not because diplomacy was effortless in 1987, but because scientists, chemical engineers, and developing-country funds moved in lockstep."}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Merangkum keberhasilan sejarah lewat ''stood the test of time'' + ''not because..., but because...'' + subjek *tricolon*.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000992', 'e5100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000060', 'writing', 'sentence_builder', 'Evaluasi Unit 10 — Susun kalimat penutup berdampak abadi (''indelible mark'') berikut:', '{"romaji":"/baɪ ˈbrɪdʒɪŋ ˈrʊrəl ˈklɪnɪks ænd dʒɪˈnoʊmɪks hɜːr ˈfɛloʊˌʃɪp lɛft ən ɪnˈdɛləbəl mɑːrk/","tokens":["her fellowship left","bridge rural","By bridging rural","an indelible mark","indelibly mark","clinics and genomics,","on tropical medicine."],"target_translation":"Dengan menjembatani klinik pedesaan dan genomika, riset beasiswanya meninggalkan jejak tak terhapuskan pada kedokteran tropis."}'::jsonb, '["By bridging rural","clinics and genomics,","her fellowship left","an indelible mark","on tropical medicine."]'::jsonb, NULL, NULL, 'Menyatukan ''bridging...'' dan ''left an indelible mark on...'' dalam kalimat penutup inspiratif.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000993', 'e5100001-0000-4000-8000-000000000123', NULL, 'reading', 'fill_blank', 'Simulasi C2 [Reading 1/4] — Pilih pembuka pengandaian Tipe 2 terbalik untuk kata kerja aksi (''default'') tanpa ''if'':', '{"options":["Had the issuer default","Were the issuer to default","Should the issuer defaulted","Were the issuer default"],"translation":"Seandainya penerbit gagal bayar atas kewajiban sukuk luar negerinya, klausul gagal-bayar-silang di perusahaan negara akan langsung aktif.","sentence_template":"[blank] on its offshore sukuk obligations, cross-default clauses across state enterprises would trigger immediately."}'::jsonb, '{"selected":"Were the issuer to default"}'::jsonb, NULL, NULL, 'Inversi pengandaian Tipe 2 untuk verba aksi wajib menggunakan rumus ''Were + Subject + to + V1''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000994', 'e5100001-0000-4000-8000-000000000123', NULL, 'reading', 'fill_blank', 'Simulasi C2 [Reading 2/4] — Pilih bentuk infinitif pasif pelaporan untuk artefak yang DIPALSUKAN di masa lampau:', '{"options":["to have been","to be","to have","having been"],"translation":"Pengujian termoluminesensi menunjukkan bahwa ukiran terakota tersebut kemungkinan besar telah dibakar di tungku abad ke-19 alih-alih pada zaman kuno.","sentence_template":"Thermoluminescence testing indicates that the terracotta frieze is likely [blank] fired in a nineteenth-century kiln rather than in antiquity."}'::jsonb, '{"selected":"to have been"}'::jsonb, NULL, NULL, 'Subjek pasif (''the terracotta frieze'') + kejadian abad ke-19 menuntut infinitif perfek pasif ''to have been + V3 (fired)''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000995', 'e5100001-0000-4000-8000-000000000123', NULL, 'reading', 'fill_blank', 'Simulasi C2 [Reading 3/4] — Terapkan kaidah inversi konsesif dan ketepatan preposisi pasca-nomina:', '{"options":["although","despite","notwithstanding","though"],"translation":"Secerdas apa pun pembuat-pasar algoritmik itu tampak saat pasar naik, likuiditasnya lenyap ketika uji tekanan bulan Mei berlangsung.","sentence_template":"Ingenious [blank] the algorithmic market-maker appeared in bull markets, liquidity vanished during the May stress test."}'::jsonb, '{"selected":"though"}'::jsonb, NULL, NULL, 'Kata sifat yang dikedepankan wajib diikuti ''though'' atau ''as'' (tidak pernah ''although'' atau ''notwithstanding'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000996', 'e5100001-0000-4000-8000-000000000123', NULL, 'reading', 'fill_blank', 'Simulasi C2 [Reading 4/4] — Pilih pembatas ruang lingkup klausa dan gerund sesudah idiom tiga kata:', '{"options":["vis-à-vis","insofar as","save for","absent"],"translation":"Tarif perbatasan karbon memajukan tujuan iklim hanya sejauh pendapatannya mengerucut pada pendanaan transfer teknologi bersih alih-alih proteksionisme fiskal.","sentence_template":"Carbon border tariffs advance climate goals only [blank] revenues come down to funding clean-tech transfers rather than fiscal protectionism."}'::jsonb, '{"selected":"insofar as"}'::jsonb, NULL, NULL, 'Diikuti klausa lengkap (''revenues come down to funding...''), konjungsi batas yang tepat adalah ''insofar as''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000997', 'e5100001-0000-4000-8000-000000000123', NULL, 'listening', 'listening_choice', 'Simulasi C2 [Listening 1/4] — Dengarkan kuliah sejarah ekonomi TOEFL tentang proyek Terusan Panama Prancis tahun 1880-an. Mengapa rencana Ferdinand de Lesseps gagal?', '{"options":[{"id":"opt_1","text":"Rencana terusan sejajar permukaan laut yang tadinya dijadwalkan buka tahun 1889 gagal terwujud karena malaria tropis dan tanah longsor membuat desain tanpa pintu air mustahil dipertahankan"},{"id":"opt_2","text":"Malaria tropis sudah berhasil diberantas sebelum penggalian Prancis dimulai"},{"id":"opt_3","text":"Terusan tanpa pintu air karya de Lesseps berhasil dibuka tepat waktu pada tahun 1889"},{"id":"opt_4","text":"Kondisi geologi Panama sama persis dengan gurun pasir datar di Terusan Suez"}],"audio_text":"Emboldened by Suez, de Lesseps embarked upon a sea-level canal across Panama that was to have opened by 1889; tropical malaria and Chagres River landslides, however, rendered a lockless design utterly untenable."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menangkap nuansa ''was to have opened by 1889'' (rencana resmi masa lalu yang batal terlaksana) + ''utterly untenable''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000998', 'e5100001-0000-4000-8000-000000000123', NULL, 'listening', 'listening_choice', 'Simulasi C2 [Listening 2/4] — Dengarkan analisis soal ''Author''s Attitude'' TOEFL Reading tentang kronik sejarah abad pertengahan.', '{"options":[{"id":"opt_1","text":"Sejarawan menerima klaim penulis kronik abad pertengahan secara mentah-mentah (''at face value'')"},{"id":"opt_2","text":"Sejarawan menyingkap kontras tajam antara retorika kesalehan di permukaan (''ostensibly'') dan motif persaingan dagang Venesia yang sebenarnya (''zeroing in on'')"},{"id":"opt_3","text":"Frasa ''For all'' berarti ekspedisi tersebut murni didorong oleh semangat keagamaan"},{"id":"opt_4","text":"Pedagang Venesia menentang ekspedisi karena merugikan jalur pelayaran mereka"}],"audio_text":"Notice how the historian writes, ''For all the chronicler''s pious rhetoric, the crusade was ostensibly launched to secure pilgrim roads while zeroing in on Venetian commercial rivals''—she''s contrasting pious pretexts against hard trade motives!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Sintesis tiga penanda C2 sekaligus: konsesi ''For all...'', jarak skeptis ''ostensibly'', dan idiom ''zeroing in on''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000000999', 'e5100001-0000-4000-8000-000000000123', NULL, 'listening', 'listening_choice', 'Simulasi C2 [Listening 3/4] — Dengarkan tanya-jawab rapat dewan gubernur bank sentral. Apa posisi gubernur terkait pemangkasan suku bunga?', '{"options":[{"id":"opt_1","text":"Bank sentral akan segera memangkas suku bunga minggu depan demi menghindari tekanan politik"},{"id":"opt_2","text":"Meskipun inflasi utama sedikit turun, tanpa pelambatan upah jasa yang bertahan lama pemangkasan bunga terlalu dini berisiko menggoyahkan ekspektasi—dan bank sentral siap menanggung kritik politik demi menjaga stabilitas"},{"id":"opt_3","text":"Gubernur menyatakan bahwa ekspektasi inflasi tidak penting bagi kebijakan moneter"},{"id":"opt_4","text":"Upah sektor jasa sudah turun tajam ke bawah target bank sentral"}],"audio_text":"Headline inflation has edged down—be that as it may, absent durable moderation in service-sector wages, premature rate cuts would risk unanchoring expectations; if holding steady draws political heat, so be it."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Menyimak rangkaian C2 tingkat tertinggi: ''be that as it may'' + preposisi ''absent'' + penutup prinsipil ''so be it''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001000', 'e5100001-0000-4000-8000-000000000123', NULL, 'listening', 'listening_choice', 'Simulasi C2 [Listening 4/4] — Dengarkan diskusi dua direktur teknik AS mengenai penghapusan layanan autentikasi lama. Apa kesimpulan mereka?', '{"options":[{"id":"opt_1","text":"Meskipun klien lama enggan bermigrasi, terus menoleransi celah token SHA-1 mengundang mimpi buruk audit sehingga sistem lama wajib segera dihapuskan"},{"id":"opt_2","text":"Menjaga dua sistem autentikasi sekaligus terbukti menghemat biaya audit keamanan"},{"id":"opt_3","text":"Klien korporat lama sangat antusias meminta penghapusan sistem lama"},{"id":"opt_4","text":"Mereka sepakat mempertahankan token SHA-1 selama lima tahun ke depan"}],"audio_text":"Look, maintaining two auth stacks has become a double-edged sword: legacy enterprise clients hate migration, yet putting up with SHA-1 token workarounds any longer invites an audit nightmare—it''s time we did away with them."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memahami ''double-edged sword'', ''putting up with'', Past Subjunctive ''it''s time we did away with them'' dalam rapat cepat AS.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001001', 'e5100001-0000-4000-8000-000000000123', NULL, 'writing', 'sentence_builder', 'Simulasi C2 [Writing 1/4] — Susun kalimat berstruktur *Nominative Absolute* + *Summative Modifier*:', '{"romaji":"/ɪts ˈɡraʊndˌwɔːtər rɪˈzɜːrvz dɪˈpliːtɪd ðə ˈvæli ˈhɔːltɪd ælˈfælfə ˈɛkspɔːrts ə ˈrɛkənɪŋ ˈdɛkeɪdz/","tokens":["in the making.","halted alfalfa exports—","which decades","were depleted","a reckoning decades","Its groundwater reserves","depleted, the valley"],"target_translation":"Setelah cadangan air tanahnya terkuras habis, lembah tersebut menghentikan ekspor alfalfa—sebuah perhitungan konsekuensi yang telah terbentuk selama puluhan tahun."}'::jsonb, '["Its groundwater reserves","depleted, the valley","halted alfalfa exports—","a reckoning decades","in the making."]'::jsonb, NULL, NULL, 'Klausa absolut ''Its reserves depleted,'' di awal dan aposisi rangkuman ''—a reckoning...'' di akhir tanpa satu pun *comma splice*.', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001002', 'e5100001-0000-4000-8000-000000000123', NULL, 'writing', 'sentence_builder', 'Simulasi C2 [Writing 2/4] — Susun kalimat syarat tujuan (''If ... are to'') dan idiom tiga kata:', '{"romaji":"/ɪf ˌmʌltiˈlætərəl ˈklaɪmət fʌndz ɑːr tə lɪv ʌp tə ðɛr ˈmænˌdeɪt dɪsˈbɜːrsmənt dɪˈleɪz/","tokens":["If multilateral climate","funds are to","delays must end.","living up","live up to","their mandate, disbursement","is to live"],"target_translation":"Jika dana iklim multilateral memang ingin memenuhi mandatnya, keterlambatan pencairan dana wajib diakhiri."}'::jsonb, '["If multilateral climate","funds are to","live up to","their mandate, disbursement","delays must end."]'::jsonb, NULL, NULL, 'Mengikat ''If + Plural Subject + are to + V1 (live up to...)'' dengan tuntutan tegas di induk kalimat.', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001003', 'e5100001-0000-4000-8000-000000000123', NULL, 'writing', 'sentence_builder', 'Simulasi C2 [Writing 3/4] — Susun kalimat preposisi pasca-nomina ''notwithstanding'' & ''absent'':', '{"romaji":"/ˈrɛkərd ˈvɛntʃər ˈɪnˌfloʊz ˌnɑːtwɪðˈstændɪŋ ˈkwɑːntəm ˈstɑːrtˌʌps ˈkænɑːt skeɪl ˈæbsənt ˌkraɪəˈdʒɛnɪk/","tokens":["despite inflows","Record venture inflows","notwithstanding, quantum startups","cannot scale absent","cryogenic supply chains.","absent of"],"target_translation":"Terlepas dari rekor arus masuk modal ventura, rintisan kuantum tidak dapat berkembang skala besar tanpa rantai pasok kriogenik."}'::jsonb, '["Record venture inflows","notwithstanding, quantum startups","cannot scale absent","cryogenic supply chains."]'::jsonb, NULL, NULL, '''[NP] notwithstanding,'' di awal dipadukan preposisi ''absent [NP]'' tanpa ''of''.', 11, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001004', 'e5100001-0000-4000-8000-000000000123', NULL, 'writing', 'sentence_builder', 'Simulasi C2 [Writing 4/4] — Susun kalimat antitesis proporsional & *tricolon* puncak C2:', '{"romaji":"/ˌsaɪənˈtɪfɪk əˈθɔːrəti rɛsts lɛs ɑːn kənˈsɛnsəs ðæn ɑːn ˈmɛθədz trænˈspærənt ˈrɛplɪkəbəl ænd ˈoʊpən/","tokens":["open to refutation.","openly refuting","then on","Scientific authority rests","transparent, replicable, and","less on consensus","than on methods"],"target_translation":"Otoritas ilmiah bertumpu bukan terutama pada konsensus semata, melainkan pada metode yang transparan, dapat direplikasi, serta terbuka terhadap pembantahan."}'::jsonb, '["Scientific authority rests","less on consensus","than on methods","transparent, replicable, and","open to refutation."]'::jsonb, NULL, NULL, '''Less on X than on Y'' ditutup dengan *postpositive adjective tricolon* berirama klimaks!', 12, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001005', 'e5100001-0000-4000-8000-000000000123', NULL, 'speaking', 'speaking_repeat', 'Simulasi C2 [Speaking 1/4] — Ucapkan kalimat kontrafaktual terbalik tanpa kontraksi berikut:', '{"romaji":"/hæd ɪt nɑːt bɪn fɔːr ˈoʊpən sɔːrs krɪpˈtɑːɡrəfi ˈmɑːdərn ˈɪntərˌnɛt ˈkɑːmɜːrs kʊd ˈnɛvər həv skeɪld/","display_text":"Had it not been for open-source cryptography, modern internet commerce could never have scaled.","phonetic_breakdown":["Had it not been","for open-source cryptography,","modern internet commerce","could never have scaled."]}'::jsonb, '{"expected_transcript":"Had it not been for open-source cryptography, modern internet commerce could never have scaled."}'::jsonb, NULL, NULL, 'Jaga ketegasan ''Had it NOT been for...'' diikuti pelafalan lemah alami ''/kʊd ˈnɛvərəv skeɪld/''.', 13, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001006', 'e5100001-0000-4000-8000-000000000123', NULL, 'speaking', 'speaking_repeat', 'Simulasi C2 [Speaking 2/4] — Ucapkan kalimat konsesi emfatik & batas klaim berikut:', '{"romaji":"/ˈprɑːmɪsɪŋ ðoʊ ˈɜːrli ˈfjuːʒən ʃɑːts ɑːr kəˈmɜːrʃəl ɡrɪd ˈpaʊər rɪˈmeɪnz ə fɑːr kraɪ əˈweɪ/","display_text":"Promising though early fusion shots are, commercial grid power remains a far cry away.","phonetic_breakdown":["Promising though","early fusion shots are,","commercial grid power","remains a far cry away."]}'::jsonb, '{"expected_transcript":"Promising though early fusion shots are, commercial grid power remains a far cry away."}'::jsonb, NULL, NULL, 'Tekankan kata pertama ''PROMISING though...'' sebelum menyeimbangkannya di klausa kedua.', 14, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001007', 'e5100001-0000-4000-8000-000000000123', NULL, 'speaking', 'speaking_repeat', 'Simulasi C2 [Speaking 3/4] — Ucapkan kalimat *resumptive modifier* editorial berikut:', '{"romaji":"/ˈsɛntrəl bæŋks ˈseɪfˌɡɑːrd ˈkɜːrənsi ˌkrɛdəˈbɪləti ˌkrɛdəˈbɪləti ðæt wʌns lɔːst teɪks ə ˌdʒɛnəˈreɪʃən tə riːˈbɪld/","display_text":"Central banks safeguard currency credibility, credibility that once lost takes a generation to rebuild.","phonetic_breakdown":["Central banks safeguard","currency credibility,","credibility that once lost","takes a generation to rebuild."]}'::jsonb, '{"expected_transcript":"Central banks safeguard currency credibility, credibility that once lost takes a generation to rebuild."}'::jsonb, NULL, NULL, 'Beri jeda tipis di koma, lalu gemakan kata ''CREDIBILITY that once lost...'' dengan mantap.', 15, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5200001-0000-4000-8000-000000001008', 'e5100001-0000-4000-8000-000000000123', NULL, 'speaking', 'speaking_repeat', 'Simulasi C2 [Speaking 4/4] — Ucapkan kalimat puncak pidato kepemimpinan global berikut:', '{"romaji":"/ɪnˈdʊrɪŋ ˈprɑːɡrɛs kʌmz daʊn tə ˈbrɪdʒɪŋ frʌnˈtɪr ˈriːsɜːrtʃ ænd ˈpʌblɪk niːd wɪð hjuːˈmɪləti/","display_text":"Enduring progress comes down to bridging frontier research and public need with humility.","phonetic_breakdown":["Enduring progress","comes down to","bridging frontier research","and public need with humility."]}'::jsonb, '{"expected_transcript":"Enduring progress comes down to bridging frontier research and public need with humility."}'::jsonb, NULL, NULL, 'Lafalkan kata benda ''progress'' ala Amerika dengan vokal /ɑː/ (/ˈprɑːɡrɛs/, bukan /ˈproʊɡrɛs/ Inggris)!', 16, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "acceptable_answers" = EXCLUDED."acceptable_answers", "diagnostic_rubric" = EXCLUDED."diagnostic_rubric", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
